search:
  formats:
    - html
    - json
  safe_search: 1

server:
  bind_address: "0.0.0.0"
  port: 8080
  secret_key: "replace-this-local-dev-secret"
  limiter: false
  image_proxy: false

ui:
  static_use_hash: true# AppArmor profile template for Source Bubblewrap runner.
#
# Install example:
#   sudo install -m 0644 config/source-bwrap.apparmor /etc/apparmor.d/source-bwrap
#   sudo apparmor_parser -r /etc/apparmor.d/source-bwrap
#
# This profile is intentionally conservative and pairs with the Bubblewrap
# runner's own namespace, capability-drop, and network policy controls.

abi <abi/4.0>,

include <tunables/global>

profile source-bwrap /usr/bin/bwrap flags=(attach_disconnected,mediate_deleted) {
  include <abstractions/base>

  capability,
  userns,
  mount,
  umount,
  pivot_root,

  network,

  /usr/bin/bwrap rix,
  /usr/bin/ls rix,
  /usr/bin/curl rix,
  /usr/bin/npm rix,
  /usr/bin/node rix,
  /usr/share/nodejs/npm/bin/npm-cli.js rix,
  /usr/lib/node_modules/npm/bin/npm-cli.js rix,
  /usr/share/nodejs/** r,
  /usr/lib/node_modules/** r,
  /bin/** rix,
  /usr/bin/** rix,
  /usr/lib/** r,
  /lib/** r,
  /lib64/** r,
  /etc/ssl/** r,
  /etc/alternatives/** r,
  /etc/nsswitch.conf r,
  /etc/resolv.conf r,
  /etc/hosts r,
  / rw,
  /proc rw,
  /proc/ rw,
  owner /proc/*/fd/ r,
  /proc/self/mountinfo r,
  owner /proc/*/mountinfo r,
  /proc/sys/kernel/overflowuid r,
  /proc/sys/kernel/overflowgid r,
  owner /proc/*/uid_map rw,
  owner /proc/*/gid_map rw,
  owner /proc/*/setgroups rw,
  mount fstype=proc -> /proc/,
  /newroot/ rw,
  /newroot/proc rw,
  /newroot/proc/ rw,
  /newroot/** rwkl,

  deny /home/** rwklx,
  deny /root/** rwklx,
  deny /etc/shadow r,
  deny /etc/ssh/** r,

  owner /tmp/ rw,
  owner /tmp/** rwkl,
  owner /run/ rw,
  owner /run/** rwkl,
}import { describe, expect, it, vi } from "vitest";

describe("Windows agent filesystem safety", () => {
  async function loadAgent(allowlist = "C:\\Projects") {
    vi.resetModules();
    vi.stubEnv("SPIRIT_DESKTOP_FS_ALLOWLIST", allowlist);
    const agent = await import("./agent.js");
    return agent.default ?? agent;
  }

  function blockedCode(result: { ok: boolean; body?: { code?: string } }): string | undefined {
    expect(result.ok).toBe(false);
    return result.body?.code;
  }

  it("normalizes C:/Projects and c/projects to Windows drive paths", async () => {
    const agent = await loadAgent();
    expect(agent.normalizeWindowsPath("C:/Projects")).toBe("C:\\Projects");
    expect(agent.normalizeWindowsPath("c/projects")).toBe("C:\\projects");
    vi.unstubAllEnvs();
  });

  it("allows only configured roots and children", async () => {
    const agent = await loadAgent("C:\\Projects");
    expect(agent.assertFsPathAllowed("C:\\Projects").ok).toBe(true);
    expect(agent.assertFsPathAllowed("C:\\Projects\\SpiritOS").ok).toBe(true);
    expect(blockedCode(agent.assertFsPathAllowed("C:\\Windows"))).toBe("PATH_NOT_ALLOWLISTED");
    vi.unstubAllEnvs();
  });

  it("blocks traversal into sensitive segments and secret basenames", async () => {
    const agent = await loadAgent("C:\\Projects");
    expect(blockedCode(agent.assertFsPathAllowed("C:\\Projects\\repo\\.git"))).toBe("PATH_BLOCKED");
    expect(blockedCode(agent.assertFsPathAllowed("C:\\Projects\\repo\\node_modules"))).toBe("PATH_BLOCKED");
    expect(blockedCode(agent.assertFsPathAllowed("C:\\Projects\\repo\\.env.local"))).toBe("PATH_BLOCKED");
    expect(blockedCode(agent.assertFsPathAllowed("C:\\Projects\\repo\\id_rsa"))).toBe("PATH_BLOCKED");
    vi.unstubAllEnvs();
  });
});#!/usr/bin/env node
import { WebSocketServer } from "ws";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

process.env.NEXT_DEVTOOLS_HOST ||= "127.0.0.1";
process.env.NODE_TLS_REJECT_UNAUTHORIZED ||= "0";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(scriptDir, "..");
const nextDevtoolsDist = resolve(repoRoot, "node_modules", "next-devtools-mcp", "dist");
const { handler: nextjsCall } = await import(
  pathToFileURL(resolve(nextDevtoolsDist, "tools", "nextjs_call.js")).href
);
const { handler: nextjsIndex } = await import(
  pathToFileURL(resolve(nextDevtoolsDist, "tools", "nextjs_index.js")).href
);

const bridgePort = readIntEnv("NEXT_MCP_WS_PORT", 3901);
const nextPort = readIntEnv("NEXT_MCP_PORT", 3000);
const host = process.env.NEXT_MCP_WS_HOST || "127.0.0.1";

const bridgeTools = [
  {
    name: "get_errors",
    description: "Get current Next.js build, runtime, and type errors.",
    inputSchema: {
      type: "object",
      properties: {
        port: { type: "number", description: "Next.js dev server port." },
      },
      additionalProperties: true,
    },
  },
  {
    name: "get_page_metadata",
    description: "Query Next.js application routes, pages, and component metadata.",
    inputSchema: {
      type: "object",
      properties: {
        port: { type: "number", description: "Next.js dev server port." },
      },
      additionalProperties: true,
    },
  },
  {
    name: "nextjs_index",
    description: "Discover running Next.js dev servers and their MCP tools.",
    inputSchema: {
      type: "object",
      properties: {
        port: { type: "number", description: "Optional Next.js dev server port." },
      },
      additionalProperties: false,
    },
  },
];

const server = new WebSocketServer({ host, port: bridgePort });

server.on("connection", (socket) => {
  socket.on("message", async (rawMessage) => {
    let request;
    try {
      request = JSON.parse(rawMessage.toString("utf8"));
    } catch (error) {
      socket.send(JSON.stringify(jsonRpcError(null, -32700, "Parse error", error)));
      return;
    }

    try {
      const result = await handleJsonRpc(request);
      if (request.id !== undefined) {
        socket.send(JSON.stringify({ jsonrpc: "2.0", id: request.id, result }));
      }
    } catch (error) {
      socket.send(
        JSON.stringify(
          jsonRpcError(
            request.id ?? null,
            -32000,
            error instanceof Error ? error.message : String(error),
            error,
          ),
        ),
      );
    }
  });
});

server.on("listening", () => {
  console.log(
    `Next MCP WebSocket bridge listening on ws://${host}:${bridgePort} -> Next port ${nextPort}`,
  );
});

async function handleJsonRpc(request) {
  if (request.jsonrpc !== "2.0" || typeof request.method !== "string") {
    throw new Error("Invalid JSON-RPC request.");
  }

  if (request.method === "initialize") {
    return {
      protocolVersion: "2025-03-26",
      serverInfo: { name: "source-next-mcp-ws-bridge", version: "0.1.0" },
      capabilities: { tools: {} },
    };
  }

  if (request.method === "tools/list") {
    return { tools: bridgeTools };
  }

  if (request.method === "tools/call") {
    const name = request.params?.name;
    const args = request.params?.arguments || {};
    return callBridgeTool(name, args);
  }

  if (bridgeTools.some((tool) => tool.name === request.method)) {
    return callBridgeTool(request.method, request.params || {});
  }

  throw new Error(`Unsupported method: ${request.method}`);
}

async function callBridgeTool(toolName, args) {
  if (toolName === "nextjs_index") {
    return parseToolJson(await nextjsIndex(args));
  }

  if (toolName === "get_errors" || toolName === "get_page_metadata") {
    const port = args.port ?? nextPort;
    return parseToolJson(
      await nextjsCall({
        port,
        toolName,
        args: withoutBridgeOnlyArgs(args),
      }),
    );
  }

  throw new Error(`Unsupported tool: ${toolName}`);
}

function withoutBridgeOnlyArgs(args) {
  const nextArgs = { ...args };
  delete nextArgs.port;
  return nextArgs;
}

function parseToolJson(value) {
  if (typeof value !== "string") {
    return value;
  }
  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

function jsonRpcError(id, code, message, error) {
  return {
    jsonrpc: "2.0",
    id,
    error: {
      code,
      message,
      data: error instanceof Error ? error.stack : String(error ?? ""),
    },
  };
}

function readIntEnv(name, defaultValue) {
  const rawValue = process.env[name];
  if (!rawValue) {
    return defaultValue;
  }

  const value = Number.parseInt(rawValue, 10);
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`${name} must be a positive integer, got ${rawValue}.`);
  }
  return value;
}#!/usr/bin/env node
import WebSocket from "ws";

const toolName = process.argv[2] || "get_errors";
const bridgeUrl = process.env.NEXT_MCP_WS_URL || "ws://127.0.0.1:3901";
const nextPort = process.env.NEXT_MCP_PORT
  ? Number.parseInt(process.env.NEXT_MCP_PORT, 10)
  : undefined;

const socket = new WebSocket(bridgeUrl);

socket.on("open", () => {
  socket.send(
    JSON.stringify({
      jsonrpc: "2.0",
      id: 1,
      method: "tools/call",
      params: {
        name: toolName,
        arguments: nextPort ? { port: nextPort } : {},
      },
    }),
  );
});

socket.on("message", (data) => {
  console.log(data.toString("utf8"));
  socket.close();
});

socket.on("error", (error) => {
  console.error(error.message);
  process.exitCode = 1;
});#!/usr/bin/env node
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import WebSocket from "ws";

const sentinel = "TS2322: Type 'string' is not assignable to type 'number'.";
const mockNextServer = createServer((request, response) => {
  if (request.method !== "POST" || request.url !== "/_next/mcp") {
    response.writeHead(404).end();
    return;
  }

  let body = "";
  request.on("data", (chunk) => {
    body += chunk;
  });
  request.on("end", () => {
    const payload = JSON.parse(body);
    response.writeHead(200, { "content-type": "text/event-stream" });
    response.end(
      `data: ${JSON.stringify({
        jsonrpc: "2.0",
        id: payload.id,
        result: {
          content: [{ type: "text", text: sentinel }],
          isError: false,
        },
      })}\n\n`,
    );
  });
});

mockNextServer.listen(0, "127.0.0.1", async () => {
  const mockNextPort = mockNextServer.address().port;
  const bridgePort = await pickPort();
  const bridge = spawn(
    process.execPath,
    ["./scripts/next-mcp-ws-bridge.mjs"],
    {
      env: {
        ...process.env,
        NEXT_MCP_PORT: String(mockNextPort),
        NEXT_MCP_WS_PORT: String(bridgePort),
      },
      stdio: ["ignore", "pipe", "pipe"],
    },
  );

  let bridgeOutput = "";
  bridge.stdout.on("data", (chunk) => {
    bridgeOutput += chunk.toString("utf8");
    if (bridgeOutput.includes("listening")) {
      runProbe(bridgePort, bridge, mockNextServer).catch((error) => {
        console.error(error);
        cleanup(bridge, mockNextServer, 1);
      });
    }
  });
  bridge.stderr.pipe(process.stderr);
});

async function runProbe(bridgePort, bridge, server) {
  const response = await callWebSocket(bridgePort);
  const text = JSON.stringify(response);
  if (!text.includes(sentinel)) {
    throw new Error(`Smoke response did not include sentinel. Response: ${text}`);
  }

  console.log(text);
  cleanup(bridge, server, 0);
}

function callWebSocket(port) {
  return new Promise((resolve, reject) => {
    const socket = new WebSocket(`ws://127.0.0.1:${port}`);
    socket.on("open", () => {
      socket.send(
        JSON.stringify({
          jsonrpc: "2.0",
          id: 1,
          method: "tools/call",
          params: { name: "get_errors", arguments: {} },
        }),
      );
    });
    socket.on("message", (data) => {
      resolve(JSON.parse(data.toString("utf8")));
      socket.close();
    });
    socket.on("error", reject);
  });
}

function pickPort() {
  return new Promise((resolve) => {
    const server = createServer();
    server.listen(0, "127.0.0.1", () => {
      const port = server.address().port;
      server.close(() => resolve(port));
    });
  });
}

function cleanup(bridge, server, exitCode) {
  bridge.kill();
  server.close(() => {
    process.exit(exitCode);
  });
}#!/usr/bin/env bash
