    unittest.main()from __future__ import annotations

import os
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

from fastapi.testclient import TestClient

from source_proxy.context.inventory import build_safe_context_inventory
from source_proxy.main import app


class SafeContextInventoryTests(unittest.TestCase):
    def test_inventory_reports_verified_roots_without_contents_or_entries(self) -> None:
        with tempfile.TemporaryDirectory() as temp_dir:
            root = Path(temp_dir)
            (root / "repomix-output.xml").write_text(
                "SECRET_SHOULD_NOT_APPEAR",
                encoding="utf-8",
            )

            inventory = build_safe_context_inventory(root)

        self.assertEqual(inventory["inventory_version"], "2.8-1")
        self.assertIn("without reading file contents", inventory["access_scope"])
        self.assertFalse(inventory["inventory_limits"]["file_contents_included"])
        self.assertFalse(inventory["inventory_limits"]["directory_entries_included"])
        self.assertFalse(inventory["inventory_limits"]["recursive_expansion"])
        self.assertGreaterEqual(len(inventory["verified_context_roots"]), 1)
        self.assertNotIn("SECRET_SHOULD_NOT_APPEAR", str(inventory))

    def test_inventory_distinguishes_unavailable_and_windows_allowlisted_roots(self) -> None:
        env = {
            "SPIRIT_PROJECT_PATH": "/path/that/does/not/exist",
            "SPIRIT_WINDOWS_FS_ENABLED": "true",
            "SPIRIT_WINDOWS_FS_BASE_URL": "http://windows-host:3000",
            "SPIRIT_WINDOWS_FS_TOKEN": "secret-token",
            "SPIRIT_WINDOWS_FS_ALLOWLIST": "C:\\Projects,C:\\Dev",
        }
        with patch.dict(os.environ, env, clear=False):
            inventory = build_safe_context_inventory(Path.cwd())

        unavailable_paths = {item["path"] for item in inventory["unavailable_roots"]}
        verified_paths = {item["path"] for item in inventory["verified_context_roots"]}
        self.assertIn("/path/that/does/not/exist", unavailable_paths)
        self.assertIn("C:\\Projects", verified_paths)
        self.assertIn("C:\\Dev", verified_paths)
        self.assertNotIn("secret-token", str(inventory))

    def test_inventory_policy_blocks_broad_and_secret_shaped_paths(self) -> None:
        inventory = build_safe_context_inventory(Path.cwd())
        policy = inventory["blocked_paths_policy"]

        self.assertTrue(policy["no_arbitrary_drive_browsing"])
        self.assertTrue(policy["no_recursive_expansion_by_default"])
        self.assertTrue(policy["no_hidden_files"])
        self.assertIn(".env", policy["blocked_name_patterns"])
        self.assertIn("C:\\Windows", policy["blocked_path_prefixes"])

    def test_context_inventory_endpoint_returns_structured_inventory(self) -> None:
        client = TestClient(app)
        response = client.get("/v1/context/inventory")

        self.assertEqual(response.status_code, 200)
        payload = response.json()
        self.assertEqual(payload["inventory_version"], "2.8-1")
        self.assertIn("verified_context_roots", payload)
        self.assertIn("blocked_paths_policy", payload)
        self.assertIn("available_read_only_sources", payload)
        self.assertIn("next_context_selection_action", payload)


if __name__ == "__main__":
    unittest.main()from __future__ import annotations

import os
import unittest
from unittest.mock import AsyncMock, patch

from fastapi.testclient import TestClient

from source_proxy.decision.prompt_packet import PromptPacketInput, build_prompt_packet
from source_proxy.main import app


class PromptPacketContextMetadataTests(unittest.TestCase):
    def test_prompt_packet_marks_missing_context_without_claiming_file_contents(self) -> None:
        packet = build_prompt_packet(
            PromptPacketInput(
                task="Review the repo architecture",
                needs_codebase_context=True,
            )
        ).as_payload()

        metadata = packet["context_metadata"]
        self.assertEqual(metadata["context_inclusion_mode"], "none")
        self.assertFalse(metadata["file_contents_claimed"])
        self.assertEqual(metadata["included_paths"], [])
        self.assertIn("ask for the specific files", packet["relevant_context"])

    def test_prompt_packet_marks_path_listing_only_and_omits_secret_paths(self) -> None:
        packet = build_prompt_packet(
            PromptPacketInput(
                task="Review Windows project folder listing",
                relevant_context=(
                    "Path listing only:\n"
                    "C:\\Projects\\SpiritOS\\package.json\n"
                    "C:\\Projects\\SpiritOS\\.env\n"
                    "src/app/page.tsx\n"
                ),
                needs_codebase_context=True,
            )
        ).as_payload()

        metadata = packet["context_metadata"]
        self.assertEqual(metadata["context_inclusion_mode"], "path_listing_only")
        self.assertFalse(metadata["file_contents_claimed"])
        self.assertIn("C:\\Projects\\SpiritOS\\package.json", metadata["included_paths"])
        self.assertIn("src/app/page.tsx", metadata["included_paths"])
        self.assertNotIn("C:\\Projects\\SpiritOS\\.env", metadata["included_paths"])
        self.assertIn("C:\\Projects\\SpiritOS\\.env", metadata["omitted_paths"])

    def test_prompt_packet_marks_generated_bundle_reference(self) -> None:
        packet = build_prompt_packet(
            PromptPacketInput(
                task="Use compressed context",
                relevant_context="generated_context_bundle: repomix-output.ast.xml",
                context_tokens=12000,
            )
        ).as_payload()

        metadata = packet["context_metadata"]
        self.assertEqual(metadata["context_inclusion_mode"], "generated_bundle_reference")
        self.assertFalse(metadata["file_contents_claimed"])
        self.assertIn("repomix-output.ast.xml", metadata["included_paths"])
        self.assertGreater(metadata["estimated_context_tokens"], 0)

    def test_prompt_packet_endpoint_returns_context_metadata(self) -> None:
        client = TestClient(app)
        response = client.post(
            "/v1/decisions/prompt-packet",
            json={
                "task": "Create prompt packet from listing",
                "relevant_context": "folder listing:\nsrc/lib/example.ts",
                "needs_codebase_context": True,
            },
        )

        self.assertEqual(response.status_code, 200)
        payload = response.json()
        self.assertIn("context_metadata", payload)
        self.assertEqual(
            payload["context_metadata"]["context_inclusion_mode"],
            "path_listing_only",
        )

    def test_research_prompt_packet_endpoint_attaches_sources(self) -> None:
        client = TestClient(app)
        sources = [
            {
                "title": "Vite 6.0 is out!",
                "url": "https://vite.dev/blog/announcing-vite6",
                "snippet": "Vite 6 release notes.",
            }
        ]

        with patch(
            "source_proxy.decision.router.run_local_research_preview",
            new=AsyncMock(return_value=sources),
        ):
            with patch.dict(os.environ, {"SPIRIT_ENABLE_PROXY_RESEARCH": "true"}, clear=False):
                response = client.post(
                    "/v1/decisions/prompt-packet",
                    json={"task": "What are the latest changes in Vite 6?"},
                )

        self.assertEqual(response.status_code, 200)
        payload = response.json()
        self.assertTrue(payload["route_decision"]["research_recommended"])
        self.assertEqual(payload["research_sources"], sources)
        self.assertEqual(payload["route_decision"]["research_sources"], sources)

    def test_research_route_endpoint_attaches_sources(self) -> None:
        client = TestClient(app)
        sources = [
            {
                "title": "Releases | Vite",
