interface DashboardDemoV4StorageProps {
  data: ClusterTelemetryResponse | null;
  state: ClusterFetchState;
  error: string | null;
}

function fmtBytes(bytes: number | null): string {
  if (bytes === null || bytes <= 0) return "Unavailable";
  const tb = bytes / 1e12;
  if (tb >= 1) return `${tb.toFixed(2)} TB`;
  const gb = bytes / 1e9;
  if (gb >= 100) return `${Math.round(gb)} GB`;
  return `${gb.toFixed(1)} GB`;
}

function fillVariant(pct: number | null): "default" | "warn" | "bad" {
  if (pct === null) return "default";
  if (pct >= 85) return "bad";
  if (pct >= 65) return "warn";
  return "default";
}

function driveTagClass(type: NodeDrive["type"]): string {
  if (type === "HDD") return "homelab-tag homelab-tag--hdd";
  if (type === "SSD" || type === "NVME") return "homelab-tag homelab-tag--ssd";
  return "homelab-tag homelab-tag--unknown";
}

function smartTone(s: SmartStatus): string {
  if (s === "Healthy") return "dashboard-demo-v4-smart-healthy";
  if (s === "Warning") return "dashboard-demo-v4-smart-warning";
  if (s === "Critical") return "dashboard-demo-v4-smart-critical";
  return "dashboard-demo-v4-smart-unknown";
}

function nodeStorageBadge(node: ClusterNodeTelemetry): "live" | "pending" | "offline" {
  if (node.status === "offline" || node.status === "unknown") return "offline";
  const drives = node.storage?.drives;
  if (drives && drives.length > 0) return "live";
  return "pending";
}

function nodeStorageBadgeLabel(node: ClusterNodeTelemetry): string {
  if (node.status === "offline" || node.status === "unknown") return "Offline";
  const drives = node.storage?.drives;
  if (drives && drives.length > 0) return "Live";
  return "Pending";
}

function stateBadge(state: ClusterFetchState) {
  if (state === "error") return { variant: "offline" as const, label: "Error" };
  if (state === "checking") return { variant: "pending" as const, label: "Loading" };
  return { variant: "live" as const, label: "Synced" };
}

export function DashboardDemoV4Storage({ data, state, error }: DashboardDemoV4StorageProps) {
  const nodes = data?.nodes ?? [];
  const badge = stateBadge(state);
  const syncTime = data?.collectedAt
    ? new Date(data.collectedAt).toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
      })
    : null;

  return (
    <section aria-label="Storage pool" className="dashboard-demo-v4-glass-pearl dashboard-demo-v4-card">
      <div className="dashboard-demo-v4-card-header">
        <div className="dashboard-demo-v4-card-title-row">
          <span className="dashboard-demo-v4-icon-tile" aria-hidden>
            <HardDrive className="h-5 w-5" />
          </span>
          <div>
            <p className="dashboard-demo-v4-eyebrow">Local drive health</p>
            <h2>Storage pool</h2>
            <p className="dashboard-demo-v4-card-subtitle">
              {state === "error" && error
                ? error
                : syncTime
                  ? `Synced ${syncTime}`
                  : "Cluster storage telemetry"}
            </p>
          </div>
        </div>
        <HomelabStatusBadge variant={badge.variant}>{badge.label}</HomelabStatusBadge>
      </div>

      {state === "checking" ? (
        <div className="dashboard-demo-v4-skeleton-list" aria-label="Loading storage telemetry">
          <div />
          <div />
        </div>
      ) : null}

      {state !== "checking" && nodes.length === 0 ? (
        <p className="dashboard-demo-v4-empty-copy">
          {state === "error" ? error ?? "Cluster telemetry failed" : "Telemetry not configured"}
        </p>
      ) : null}

      {nodes.length > 0 && state !== "checking" ? (
        <div className="dashboard-demo-v4-storage-list">
          {nodes.map((node) => {
            const offline = node.status === "offline" || node.status === "unknown";
            const drives = node.storage?.drives ?? [];

            return (
              <article key={node.id} className="dashboard-demo-v4-storage-node">
                <div className="dashboard-demo-v4-storage-node-header">
                  <span>{node.label}</span>
                  <HomelabStatusBadge variant={nodeStorageBadge(node)}>
                    {nodeStorageBadgeLabel(node)}
                  </HomelabStatusBadge>
                </div>

                {offline ? (
                  <p className="dashboard-demo-v4-empty-copy">
                    Offline{node.error ? ` · ${node.error}` : ""}
                  </p>
                ) : drives.length === 0 ? (
                  <div className="dashboard-demo-v4-drive-card">
                    <p className="dashboard-demo-v4-empty-copy">Storage telemetry unavailable</p>
                    {node.storage?.error ? (
                      <p className="dashboard-demo-v4-warning-copy">{node.storage.error}</p>
                    ) : null}
                  </div>
                ) : (
                  <div className="dashboard-demo-v4-drive-list">
                    {drives.map((drive) => (
                      <div key={drive.id} className="dashboard-demo-v4-drive-card">
                        <div className="dashboard-demo-v4-drive-header">
                          <div className="dashboard-demo-v4-drive-name">
                            <span className={driveTagClass(drive.type)}>{drive.type}</span>
                            <strong>{drive.name}</strong>
                          </div>
                          <span className="dashboard-demo-v4-drive-capacity">
                            {fmtBytes(drive.usedBytes)} / {fmtBytes(drive.totalBytes)}
                          </span>
                        </div>

                        {(drive.mount || drive.fsType) && (
                          <p className="dashboard-demo-v4-drive-meta">
                            {[drive.mount, drive.fsType].filter(Boolean).join(" · ")}
                          </p>
                        )}

                        <HomelabProgressBar
                          pct={drive.usedPct ?? 0}
                          variant={fillVariant(drive.usedPct)}
                          label={`${drive.name} usage`}
                        />

                        <div className="dashboard-demo-v4-drive-footer">
                          <span className={cn("dashboard-demo-v4-smart", smartTone(drive.smart))}>
                            {drive.smart}
                          </span>
                          {drive.tempC !== null ? <span>{drive.tempC}°C</span> : null}
                        </div>
                      </div>
                    ))}
                    {node.storage?.error ? (
                      <p className="dashboard-demo-v4-warning-copy">{node.storage.error}</p>
                    ) : null}
                  </div>
                )}
              </article>
            );
          })}
        </div>
      ) : null}
    </section>
  );
}"use client";

import { Activity } from "lucide-react";

import { HomelabProgressBar } from "@/components/dashboard/HomelabProgressBar";
import { HomelabStatusBadge } from "@/components/dashboard/HomelabStatusBadge";
import type { ClusterFetchState } from "@/hooks/useClusterTelemetry";
import type { ClusterNodeTelemetry, ClusterTelemetryResponse } from "@/lib/server/telemetry/types";

interface DashboardDemoV4SystemStatsProps {
  data: ClusterTelemetryResponse | null;
  state: ClusterFetchState;
  error: string | null;
}

function pct(val: number | null): string {
  return val !== null ? `${Math.round(val)}%` : "Unavailable";
}

function fmtMemory(used: number | null, total: number | null): string {
  if (used === null || total === null) return "Unavailable";
  const usedGB = (used / 1e9).toFixed(1);
  const totalGB = Math.round(total / 1e9);
  return `${usedGB} GB / ${totalGB} GB`;
}

function formatUptime(sec: number | null): string {
  if (sec === null) return "Unavailable";
  const d = Math.floor(sec / 86400);
  const h = Math.floor((sec % 86400) / 3600);
  const m = Math.floor((sec % 3600) / 60);
  if (d > 0) return `${d}d ${h}h`;
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}

function cpuVariant(v: number | null): "default" | "good" | "warn" | "bad" {
  if (v === null) return "default";
  if (v >= 85) return "bad";
  if (v >= 65) return "warn";
  if (v < 40) return "good";
  return "default";
}

function ramVariant(v: number | null): "default" | "warn" | "bad" {
  if (v === null) return "default";
  if (v >= 85) return "bad";
  if (v >= 65) return "warn";
  return "default";
}

function stateBadge(state: ClusterFetchState) {
  if (state === "error") return { variant: "offline" as const, label: "Error" };
  if (state === "checking") return { variant: "pending" as const, label: "Loading" };
  return { variant: "live" as const, label: "Synced" };
}

function NodeVitals({ node }: { node: ClusterNodeTelemetry }) {
  const offline = node.status === "offline" || node.status === "unknown";
  const spec = [node.hostname, node.platform, node.arch].filter(Boolean).join(" · ");
  const badgeVariant =
    node.status === "online"
      ? "live"
      : node.status === "offline"
        ? "offline"
        : ("pending" as const);
  const badgeLabel =
    node.status === "online"
      ? "Live"
      : node.status === "degraded"
        ? "Degraded"
        : node.status === "offline"
          ? "Offline"
          : "Unknown";

  return (
    <article className="dashboard-demo-v4-node-card">
      <div className="dashboard-demo-v4-node-card-header">
        <div className="min-w-0">
          <h3>{node.label}</h3>
          <p>{spec || "Node details unavailable"}</p>
        </div>
        <HomelabStatusBadge variant={badgeVariant}>{badgeLabel}</HomelabStatusBadge>
      </div>

      {offline ? (
        <p className="dashboard-demo-v4-empty-copy">
          Offline{node.error ? ` · ${node.error}` : ""}
        </p>
      ) : (
        <div className="dashboard-demo-v4-vitals-list">
          <div className="dashboard-demo-v4-meter">
            <div className="dashboard-demo-v4-meter-label">
              <span>CPU</span>
              <strong>{pct(node.cpu.usagePct)}</strong>
            </div>
            {node.cpu.usagePct !== null ? (
              <HomelabProgressBar
                pct={node.cpu.usagePct}
                variant={cpuVariant(node.cpu.usagePct)}
                label={`${node.label} CPU`}
              />
            ) : null}
          </div>

          <div className="dashboard-demo-v4-meter">
            <div className="dashboard-demo-v4-meter-label">
              <span>RAM</span>
              <strong>{fmtMemory(node.memory.usedBytes, node.memory.totalBytes)}</strong>
            </div>
            {node.memory.usedPct !== null ? (
              <HomelabProgressBar
                pct={node.memory.usedPct}
                variant={ramVariant(node.memory.usedPct)}
                label={`${node.label} RAM`}
              />
            ) : null}
          </div>

          <div className="dashboard-demo-v4-node-detail-row">
            <span>Uptime</span>
            <strong>{formatUptime(node.uptimeSec)}</strong>
          </div>
        </div>
      )}
    </article>
  );
}

export function DashboardDemoV4SystemStats({
  data,
  state,
  error,
}: DashboardDemoV4SystemStatsProps) {
  const nodes = data?.nodes ?? [];
  const badge = stateBadge(state);
  const syncTime = data?.collectedAt
    ? new Date(data.collectedAt).toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
      })
    : null;

  return (
    <section aria-label="System stats" className="dashboard-demo-v4-glass-pearl dashboard-demo-v4-card">
      <div className="dashboard-demo-v4-card-header">
        <div className="dashboard-demo-v4-card-title-row">
          <span className="dashboard-demo-v4-icon-tile" aria-hidden>
            <Activity className="h-5 w-5" />
          </span>
          <div>
            <p className="dashboard-demo-v4-eyebrow">Node vitals</p>
            <h2>System vitals</h2>
            <p className="dashboard-demo-v4-card-subtitle">
              {state === "checking"
                ? "Polling cluster telemetry"
                : state === "error" && error
                  ? error
                  : syncTime
                    ? `Synced ${syncTime}`
                    : "Live telemetry"}
            </p>
          </div>
        </div>
        <HomelabStatusBadge variant={badge.variant}>{badge.label}</HomelabStatusBadge>
      </div>

      {state === "checking" ? (
        <div className="dashboard-demo-v4-skeleton-grid" aria-label="Loading system vitals">
          <div />
          <div />
        </div>
      ) : null}

      {state !== "checking" && nodes.length === 0 ? (
        <p className="dashboard-demo-v4-empty-copy">
          {state === "error" ? error ?? "Cluster telemetry failed" : "Telemetry not configured"}
        </p>
      ) : null}

      {nodes.length > 0 ? (
        <div className="dashboard-demo-v4-node-grid">
          {nodes.map((node) => (
            <NodeVitals key={node.id} node={node} />
          ))}
        </div>
      ) : null}
    </section>
  );
}import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import type { ReactNode } from "react";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { DashboardDemoV4FloatingNav } from "./DashboardDemoV4FloatingNav";
import { SPIRIT_PALETTES } from "@/theme/spiritPalettes";
import { useSpiritTheme } from "@/theme/useSpiritTheme";

const mockSetTheme = vi.fn();
const navMock = vi.hoisted(() => ({ path: "/" }));

vi.mock("@/theme/useSpiritTheme", () => ({
  useSpiritTheme: vi.fn(() => ({
    theme: "frozen-water",
    setTheme: mockSetTheme,
  })),
}));

vi.mock("next/navigation", () => ({
  usePathname: () => navMock.path,
}));

vi.mock("next/link", () => ({
  default: ({
    href,
    children,
    ...rest
  }: {
    href: string;
    children: ReactNode;
    [key: string]: unknown;
  }) => (
    <a href={href} {...rest}>
      {children}
    </a>
  ),
}));

function openThemePickerFromMobileNav() {
  const mobileNav = screen.getByRole("navigation", {
    name: /dashboard mobile navigation/i,
  });
  fireEvent.click(
    within(mobileNav).getByRole("button", {
      name: /open interface theme picker/i,
    }),
  );
}

describe("DashboardDemoV4ThemePicker", () => {
  beforeEach(() => {
    navMock.path = "/";
    mockSetTheme.mockClear();
    vi.mocked(useSpiritTheme).mockReturnValue({
      theme: "frozen-water",
      setTheme: mockSetTheme,
    });
  });

  it("opens the Interface picker from the floating nav palette button", () => {
    render(<DashboardDemoV4FloatingNav />);

    openThemePickerFromMobileNav();

    expect(
      screen.getByRole("dialog", { name: /interface theme picker/i }),
    ).toBeInTheDocument();
    expect(screen.getByRole("heading", { name: /^interface$/i })).toBeInTheDocument();
  });

  it("renders one card per palette and marks the active palette", () => {
    render(<DashboardDemoV4FloatingNav />);
    openThemePickerFromMobileNav();

    for (const palette of SPIRIT_PALETTES) {
      expect(
        screen.getByRole("button", { name: new RegExp(palette.label, "i") }),
      ).toBeInTheDocument();
    }

    const active = SPIRIT_PALETTES.find((palette) => palette.id === "frozen-water")!;
    expect(
      screen.getByRole("button", { name: new RegExp(active.label, "i") }),
    ).toHaveAttribute("aria-pressed", "true");
  });

  it("selecting a palette calls setTheme and closes the picker", async () => {
    render(<DashboardDemoV4FloatingNav />);
    openThemePickerFromMobileNav();

    const target = SPIRIT_PALETTES.find((palette) => palette.id === "deep-sky")!;
    fireEvent.click(screen.getByRole("button", { name: new RegExp(target.label, "i") }));

    expect(mockSetTheme).toHaveBeenCalledWith("deep-sky");
    await waitFor(() => {
      expect(screen.queryByRole("dialog", { name: /interface theme picker/i })).not.toBeInTheDocument();
    });
  });

  it("Escape closes the picker", async () => {
    render(<DashboardDemoV4FloatingNav />);
    openThemePickerFromMobileNav();

    fireEvent.keyDown(document, { key: "Escape" });

    await waitFor(() => {
      expect(screen.queryByRole("dialog", { name: /interface theme picker/i })).not.toBeInTheDocument();
    });
  });

  it("clicking the backdrop closes the picker", async () => {
    render(<DashboardDemoV4FloatingNav />);
    openThemePickerFromMobileNav();

    fireEvent.click(screen.getAllByRole("button", { name: /close interface theme picker/i })[0]);

    await waitFor(() => {
      expect(screen.queryByRole("dialog", { name: /interface theme picker/i })).not.toBeInTheDocument();
    });
  });

  it("keeps the nav links rendered", () => {
    render(<DashboardDemoV4FloatingNav />);
    const desktopNav = screen.getByRole("navigation", {
      name: /dashboard desktop navigation/i,
    });
    const mobileNav = screen.getByRole("navigation", {
      name: /dashboard mobile navigation/i,
    });

    for (const nav of [desktopNav, mobileNav]) {
      const hrefs = Array.from(nav.querySelectorAll("a")).map((a) => a.getAttribute("href"));
      expect(hrefs).toContain("/");
      expect(hrefs).toContain("/chat");
      expect(hrefs).toContain("/coding");
      expect(hrefs).toContain("/oracle");
    }
  });
});"use client";

import { useEffect } from "react";
import type { CSSProperties } from "react";
import { createPortal } from "react-dom";
import { Check, X } from "lucide-react";

import { cn } from "@/lib/cn";
import { SPIRIT_PALETTES } from "@/theme/spiritPalettes";
import { useSpiritTheme } from "@/theme/useSpiritTheme";

interface DashboardDemoV4ThemePickerProps {
  open: boolean;
  onClose: () => void;
}

export function DashboardDemoV4ThemePicker({
  open,
  onClose,
}: DashboardDemoV4ThemePickerProps) {
  const { theme, setTheme } = useSpiritTheme();

  useEffect(() => {
    if (!open) return;

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        onClose();
      }
    }

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [onClose, open]);

  if (!open || typeof document === "undefined") return null;

  const picker = (
    <div className="dashboard-demo-v4-interface-layer">
      <button
        type="button"
        className="dashboard-demo-v4-interface-backdrop"
        aria-label="Close interface theme picker"
        onClick={onClose}
      />

      <div
        role="dialog"
        aria-modal="true"
        aria-label="Interface theme picker"
        className="dashboard-demo-v4-interface-panel"
      >
            <div className="dashboard-demo-v4-interface-header">
              <div>
                <p className="dashboard-demo-v4-interface-kicker">Visual system</p>
                <h2>Interface</h2>
                <p>Choose a visual system</p>
              </div>
              <button
                type="button"
                className="dashboard-demo-v4-interface-close"
                aria-label="Close interface theme picker"
                onClick={onClose}
              >
                <X className="h-4 w-4" aria-hidden />
              </button>
            </div>

            <div className="dashboard-demo-v4-interface-grid">
              {SPIRIT_PALETTES.map((palette) => {
                const active = theme === palette.id;
                const gradient = palette.colors.map((color) => color.hex).join(", ");

                return (
                  <button
                    key={palette.id}
                    type="button"
                    aria-pressed={active}
                    className={cn(
                      "dashboard-demo-v4-interface-card",
                      active && "dashboard-demo-v4-interface-card-active",
                    )}
                    onClick={() => {
                      setTheme(palette.id);
                      onClose();
                    }}
                  >
                    <span
                      className={cn(
                        "dashboard-demo-v4-interface-preview",
                        `dashboard-demo-v4-interface-preview-${palette.previewPattern ?? "none"}`,
                      )}
                      style={{
                        background: palette.previewSurface,
                        "--dashboard-demo-v4-preview-accent": palette.previewAccent,
                      } as CSSProperties}
                      aria-hidden
                    >
                      <span style={{ background: `linear-gradient(135deg, ${gradient})` }} />
                    </span>

                    <span
                      className="dashboard-demo-v4-interface-accent"
                      style={{
                        background: palette.previewAccent,
                        boxShadow: `0 0 18px 2px ${palette.previewAccent}66`,
                      }}
                      aria-hidden
                    />

                    <span className="dashboard-demo-v4-interface-card-copy">
                      <strong>{palette.label}</strong>
                      <span>{palette.toneLabel}</span>
                    </span>

                    {active ? (
                      <span className="dashboard-demo-v4-interface-check" aria-hidden>
                        <Check className="h-3.5 w-3.5" />
                      </span>
                    ) : null}
                  </button>
                );
              })}
            </div>
      </div>
    </div>
  );

  return createPortal(picker, document.body);
}import { beforeEach, describe, expect, it } from "vitest";

import {
  clearWebSearchCache,
  runCacheWebSearch,
  storeWebSearchCacheResult,
} from "@/lib/server/web-search/cache-provider";
import type { WebSearchProviderConfig } from "@/lib/server/web-search/types";

function config(overrides: Partial<WebSearchProviderConfig> = {}): WebSearchProviderConfig {
  return {
    enabled: true,
    providerOrder: ["cache"],
    maxResults: 8,
    cache: { enabled: true, ttlSeconds: 86_400 },
    searxng: { url: "http://127.0.0.1:8080", maxResults: 8, timeoutMs: 10_000 },
    fetchPage: {
      enabled: true,
      timeoutMs: 10_000,
      respectRobots: true,
      userAgent: "SpiritOSLocalSearch/0.1",
    },
    paidFallback: { enabled: false, requireApproval: true },
    ...overrides,
  };
}

describe("cache web-search provider", () => {
  beforeEach(() => clearWebSearchCache());

  it("returns an empty successful miss", async () => {
    const result = await runCacheWebSearch({ query: "docs", maxResults: 5, config: config() });

    expect(result).toMatchObject({
      ok: true,
      searched: true,
      provider: "cache",
      sources: [],
    });
  });

  it("returns stored sources for matching query and max result count", async () => {
    storeWebSearchCacheResult({
      query: "Docs",
      maxResults: 5,
      config: config(),
      sources: [{ title: "Docs", url: "https://example.com/docs", provider: "searxng" }],
      answerPreview: "preview",
    });

    const result = await runCacheWebSearch({ query: "docs", maxResults: 5, config: config() });

    expect(result).toMatchObject({
      ok: true,
      provider: "cache",
      answerPreview: "preview",
      sources: [{ title: "Docs", url: "https://example.com/docs", provider: "searxng" }],
    });
  });

  it("does not read or write when cache is disabled", async () => {
    const disabledConfig = config({ cache: { enabled: false, ttlSeconds: 86_400 } });
    storeWebSearchCacheResult({
      query: "docs",
      maxResults: 5,
      config: disabledConfig,
      sources: [{ title: "Docs", url: "https://example.com/docs" }],
    });

    const result = await runCacheWebSearch({ query: "docs", maxResults: 5, config: disabledConfig });

    expect(result).toMatchObject({
      ok: false,
      searched: false,
      provider: "cache",
      error: "cache_disabled",
    });
  });
});import { describe, expect, it, vi } from "vitest";

import {
  isAllowedByRobotsTxt,
  runFetchPageWebSearch,
} from "@/lib/server/web-search/fetch-page-provider";
import type { WebSearchProviderConfig } from "@/lib/server/web-search/types";

function config(overrides: Partial<WebSearchProviderConfig> = {}): WebSearchProviderConfig {
  return {
    enabled: true,
    providerOrder: ["fetch"],
    maxResults: 8,
    cache: { enabled: true, ttlSeconds: 86_400 },
    searxng: { url: "http://127.0.0.1:8080", maxResults: 8, timeoutMs: 10_000 },
    fetchPage: {
      enabled: true,
      timeoutMs: 10_000,
      respectRobots: true,
      userAgent: "SpiritOSLocalSearch/0.1",
    },
    paidFallback: { enabled: false, requireApproval: true },
    ...overrides,
  };
}

describe("isAllowedByRobotsTxt", () => {
  it("uses the most specific allow/disallow rule", () => {
    const robots = `User-agent: *
Disallow: /private/
Allow: /private/public.html`;

    expect(isAllowedByRobotsTxt(robots, "https://example.com/private/public.html", "SpiritOSLocalSearch/0.1")).toBe(true);
    expect(isAllowedByRobotsTxt(robots, "https://example.com/private/secret.html", "SpiritOSLocalSearch/0.1")).toBe(false);
  });
});

describe("runFetchPageWebSearch", () => {
  it("extracts title, canonical URL, and snippet from static HTML", async () => {
    const fetchImpl = vi.fn(async (url: RequestInfo | URL) => {
      if (String(url).endsWith("/robots.txt")) {
        return new Response("User-agent: *\nAllow: /", { status: 200 });
      }
      return new Response(
        `<!doctype html>
        <html>
          <head>
            <link rel="canonical" href="https://example.com/canonical">
            <title>Example page</title>
            <meta name="description" content="A useful description.">
          </head>
          <body><p>This is a long readable paragraph with enough text to use as a fallback snippet.</p></body>
        </html>`,
        { status: 200, headers: { "Content-Type": "text/html" } },
      );
    }) as unknown as typeof fetch;

    const result = await runFetchPageWebSearch({
      query: "https://example.com/page",
      maxResults: 5,
      config: config(),
      fetchImpl,
    });

    expect(result.ok && result.sources).toEqual([
      {
        title: "Example page",
        url: "https://example.com/canonical",
        snippet: "A useful description.",
        provider: "fetch",
      },
    ]);
  });

  it("rejects non-URL queries", async () => {
    const result = await runFetchPageWebSearch({
      query: "latest vite release notes",
      maxResults: 5,
      config: config(),
      fetchImpl: vi.fn() as unknown as typeof fetch,
    });

    expect(result).toMatchObject({
      ok: false,
      searched: false,
      provider: "fetch",
      error: "fetch_query_not_url",
    });
  });

  it("returns robots-disallowed failure when strict robots mode blocks the page", async () => {
    const fetchImpl = vi.fn(async () => new Response("User-agent: *\nDisallow: /blocked", { status: 200 })) as unknown as typeof fetch;

    const result = await runFetchPageWebSearch({
      query: "https://example.com/blocked/page",
      maxResults: 5,
      config: config(),
      fetchImpl,
    });

    expect(result).toMatchObject({
      ok: false,
      searched: false,
      provider: "fetch",
      error: "robots_disallowed",
    });
  });

  it("returns timeout failure when page fetch aborts", async () => {
    const fetchImpl = vi.fn(async (url: RequestInfo | URL) => {
      if (String(url).endsWith("/robots.txt")) {
        return new Response("", { status: 404 });
      }
      const error = new Error("aborted");
      error.name = "AbortError";
      throw error;
    }) as unknown as typeof fetch;

    const result = await runFetchPageWebSearch({
      query: "https://example.com/page",
      maxResults: 5,
      config: config(),
      fetchImpl,
    });

    expect(result).toMatchObject({
      ok: false,
      provider: "fetch",
      error: "fetch_timeout",
    });
  });
});import { describe, expect, it, vi } from "vitest";

