import { runWebSearch } from "@/lib/server/web-search/provider-router";
import type {
  WebSearchAdapter,
  WebSearchProvider,
  WebSearchProviderConfig,
  WebSearchResult,
  WebSearchSource,
} from "@/lib/server/web-search/types";

function config(overrides: Partial<WebSearchProviderConfig> = {}): WebSearchProviderConfig {
  return {
    enabled: true,
    providerOrder: ["cache", "searxng", "fetch"],
    maxResults: 8,
    cache: { enabled: true, ttlSeconds: 86_400 },
    searxng: { url: "http://127.0.0.1:8080", maxResults: 8, timeoutMs: 10_000 },
    fetchPage: {
      enabled: false,
      timeoutMs: 10_000,
      respectRobots: true,
      userAgent: "SpiritOSLocalSearch/0.1",
    },
    paidFallback: { enabled: false, requireApproval: true },
    ...overrides,
  };
}

function fetchEnabled(): WebSearchProviderConfig["fetchPage"] {
  return {
    enabled: true,
    timeoutMs: 10_000,
    respectRobots: true,
    userAgent: "SpiritOSLocalSearch/0.1",
  };
}

function ok(provider: WebSearchProvider, sources: WebSearchSource[]): WebSearchResult {
  return {
    ok: true,
    searched: true,
    provider,
    query: "test",
    sources,
    elapsedMs: 1,
    providerTrace: [],
  };
}

function fail(provider: WebSearchProvider, error = "failed"): WebSearchResult {
  return {
    ok: false,
    searched: true,
    provider,
    error,
    elapsedMs: 1,
    providerTrace: [],
  };
}

function adapter(provider: WebSearchProvider, result: WebSearchResult): WebSearchAdapter {
  return {
    provider,
    search: vi.fn(async () => result),
  };
}

const source: WebSearchSource = {
  title: "Example",
  url: "https://example.com",
  provider: "searxng",
};

describe("runWebSearch", () => {
  it("cache hit stops before SearXNG", async () => {
    const cache = adapter("cache", ok("cache", [{ ...source, provider: "cache" }]));
    const searxng = adapter("searxng", ok("searxng", [source]));

    const result = await runWebSearch({
      query: "latest docs",
      config: config(),
      providers: [cache, searxng],
    });

    expect(result.ok).toBe(true);
    expect(result.provider).toBe("cache");
    expect(cache.search).toHaveBeenCalledTimes(1);
    expect(searxng.search).not.toHaveBeenCalled();
    expect(result.providerTrace.map((trace) => trace.status)).toEqual(["used"]);
  });

  it("cache miss tries SearXNG next", async () => {
    const cache = adapter("cache", ok("cache", []));
    const searxng = adapter("searxng", ok("searxng", [source]));

    const result = await runWebSearch({
      query: "latest docs",
      config: config(),
      providers: [cache, searxng],
    });

    expect(result.ok).toBe(true);
    expect(result.provider).toBe("searxng");
    expect(cache.search).toHaveBeenCalledTimes(1);
    expect(searxng.search).toHaveBeenCalledTimes(1);
    expect(result.providerTrace.map((trace) => trace.status)).toEqual(["failed", "used"]);
    expect(result.providerTrace[0]?.reason).toBe("no_verified_sources");
  });

  it("SearXNG verified results stop before fetch", async () => {
    const searxng = adapter("searxng", ok("searxng", [source]));
    const fetchPage = adapter("fetch", ok("fetch", [{ ...source, provider: "fetch" }]));

    const result = await runWebSearch({
      query: "latest docs",
      config: config({ providerOrder: ["searxng", "fetch"], fetchPage: fetchEnabled() }),
      providers: [searxng, fetchPage],
    });

    expect(result.provider).toBe("searxng");
    expect(fetchPage.search).not.toHaveBeenCalled();
  });

  it("SearXNG failure falls through to fetch", async () => {
    const searxng = adapter("searxng", fail("searxng", "searxng_unreachable"));
    const fetchPage = adapter("fetch", ok("fetch", [{ ...source, provider: "fetch" }]));

    const result = await runWebSearch({
      query: "latest docs",
      config: config({ providerOrder: ["searxng", "fetch"], fetchPage: fetchEnabled() }),
      providers: [searxng, fetchPage],
    });

    expect(result.ok).toBe(true);
    expect(result.provider).toBe("fetch");
    expect(result.providerTrace[0]?.reason).toBe("searxng_unreachable");
  });

  it("empty verified sources count as failure and fall through", async () => {
    const searxng = adapter("searxng", ok("searxng", []));
    const fetchPage = adapter("fetch", ok("fetch", [{ ...source, provider: "fetch" }]));

    const result = await runWebSearch({
      query: "latest docs",
      config: config({ providerOrder: ["searxng", "fetch"], fetchPage: fetchEnabled() }),
      providers: [searxng, fetchPage],
    });

    expect(result.provider).toBe("fetch");
    expect(result.providerTrace[0]?.status).toBe("failed");
    expect(result.providerTrace[0]?.sourceCount).toBe(0);
  });

  it("OpenAI is skipped when paid fallback is disabled", async () => {
    const openai = adapter("openai", ok("openai", [{ ...source, provider: "openai" }]));

    const result = await runWebSearch({
      query: "latest docs",
      config: config({ providerOrder: ["openai"], paidFallback: { enabled: false, requireApproval: true } }),
      providers: [openai],
    });

    expect(result.ok).toBe(false);
    expect(openai.search).not.toHaveBeenCalled();
    expect(result.providerTrace[0]).toMatchObject({
      provider: "openai",
      status: "skipped",
      reason: "paid_fallback_disabled",
    });
  });

  it("OpenAI is skipped when paid fallback is enabled but approval is missing", async () => {
    const openai = adapter("openai", ok("openai", [{ ...source, provider: "openai" }]));

    const result = await runWebSearch({
      query: "latest docs",
      config: config({ providerOrder: ["openai"], paidFallback: { enabled: true, requireApproval: true } }),
      providers: [openai],
    });

    expect(result.ok).toBe(false);
    expect(openai.search).not.toHaveBeenCalled();
    expect(result.providerTrace[0]?.reason).toBe("paid_fallback_approval_missing");
  });

  it("OpenAI is attempted only when enabled, approved, and earlier providers fail", async () => {
    const searxng = adapter("searxng", ok("searxng", []));
    const openai = adapter("openai", ok("openai", [{ ...source, provider: "openai" }]));

    const result = await runWebSearch({
      query: "latest docs",
      paidFallbackApproved: true,
      config: config({ providerOrder: ["searxng", "openai"], paidFallback: { enabled: true, requireApproval: true } }),
      providers: [searxng, openai],
    });

    expect(result.ok).toBe(true);
    expect(result.provider).toBe("openai");
    expect(searxng.search).toHaveBeenCalledTimes(1);
    expect(openai.search).toHaveBeenCalledTimes(1);
    expect(result.providerTrace.map((trace) => trace.status)).toEqual(["failed", "used"]);
  });

  it("runs the full ladder in order and uses OpenAI last only after local/free providers fail with approval", async () => {
    const calls: WebSearchProvider[] = [];
    const orderedAdapter = (provider: WebSearchProvider, result: WebSearchResult): WebSearchAdapter => ({
      provider,
      search: vi.fn(async () => {
        calls.push(provider);
        return result;
      }),
    });
    const cache = orderedAdapter("cache", ok("cache", []));
    const searxng = orderedAdapter("searxng", ok("searxng", []));
    const fetchPage = orderedAdapter("fetch", ok("fetch", []));
    const openai = orderedAdapter("openai", ok("openai", [{ ...source, provider: "openai" }]));

    const result = await runWebSearch({
      query: "latest docs",
      paidFallbackApproved: true,
      config: config({
        providerOrder: ["cache", "searxng", "fetch", "openai"],
        fetchPage: fetchEnabled(),
        paidFallback: { enabled: true, requireApproval: true },
      }),
      providers: [cache, searxng, fetchPage, openai],
    });

    expect(result.ok).toBe(true);
    expect(result.provider).toBe("openai");
    expect(calls).toEqual(["cache", "searxng", "fetch", "openai"]);
    expect(openai.search).toHaveBeenCalledTimes(1);
    expect(result.providerTrace.map((trace) => [trace.provider, trace.status])).toEqual([
      ["cache", "failed"],
      ["searxng", "failed"],
      ["fetch", "failed"],
      ["openai", "used"],
    ]);
  });

  it("skips fetch without calling the adapter unless direct fetch is explicitly enabled", async () => {
    const fetchPage = adapter("fetch", ok("fetch", [{ ...source, provider: "fetch" }]));

    const result = await runWebSearch({
      query: "https://example.com",
      config: config({ providerOrder: ["fetch"] }),
      providers: [fetchPage],
    });

    expect(result.ok).toBe(false);
    expect(fetchPage.search).not.toHaveBeenCalled();
    expect(result.providerTrace).toEqual([
      { provider: "fetch", status: "skipped", reason: "fetch_page_disabled" },
    ]);
  });

  it("provider trace records skipped, attempted, used, and failed states", async () => {
    const cache = adapter("cache", ok("cache", []));
    const searxng = adapter("searxng", ok("searxng", [source]));

    const result = await runWebSearch({
      query: "latest docs",
      config: config({ providerOrder: ["ddgs", "cache", "openai", "searxng"] }),
      providers: [cache, searxng],
    });

    expect(result.providerTrace.map((trace) => [trace.provider, trace.status, trace.reason])).toEqual([
      ["ddgs", "skipped", "provider_unavailable"],
      ["cache", "failed", "no_verified_sources"],
      ["openai", "skipped", "paid_fallback_disabled"],
      ["searxng", "used", undefined],
    ]);
  });

  it("unknown provider names do not crash the router", async () => {
    const result = await runWebSearch({
      query: "latest docs",
      config: config({ providerOrder: ["bogus"] }),
      providers: [],
    });

    expect(result.ok).toBe(false);
    expect(result.providerTrace).toEqual([{ provider: "bogus", status: "skipped", reason: "unknown_provider" }]);
  });
});import "server-only";

import type {
  WebSearchAdapter,
  WebSearchProviderConfig,
  WebSearchSource,
  WebSearchResult,
} from "@/lib/server/web-search/types";

type CacheEntry = {
  query: string;
  sources: WebSearchSource[];
  answerPreview?: string;
  storedAt: number;
  ttlMs: number;
};

const cache = new Map<string, CacheEntry>();

function cacheKey(query: string, maxResults: number): string {
  return `${query.trim().toLowerCase()}\n${maxResults}`;
}

function elapsedSince(startedAt: number): number {
  return Date.now() - startedAt;
}

export function clearWebSearchCache(): void {
  cache.clear();
}

export function storeWebSearchCacheResult(opts: {
  query: string;
  maxResults: number;
  config: WebSearchProviderConfig;
  sources: WebSearchSource[];
  answerPreview?: string;
}): void {
  if (!opts.config.cache.enabled || opts.sources.length === 0) return;
  cache.set(cacheKey(opts.query, opts.maxResults), {
    query: opts.query.trim(),
    sources: opts.sources.map((source) => ({ ...source })),
    ...(opts.answerPreview ? { answerPreview: opts.answerPreview } : {}),
    storedAt: Date.now(),
    ttlMs: opts.config.cache.ttlSeconds * 1000,
  });
}

export async function runCacheWebSearch(opts: {
  query: string;
  maxResults: number;
  config: WebSearchProviderConfig;
}): Promise<WebSearchResult> {
  const startedAt = Date.now();
  if (!opts.config.cache.enabled) {
    return {
      ok: false,
      searched: false,
      provider: "cache",
      error: "cache_disabled",
      elapsedMs: elapsedSince(startedAt),
      providerTrace: [],
    };
  }

  const key = cacheKey(opts.query, opts.maxResults);
  const entry = cache.get(key);
  if (!entry) {
    return {
      ok: true,
      searched: true,
      provider: "cache",
      query: opts.query.trim(),
      sources: [],
      elapsedMs: elapsedSince(startedAt),
      providerTrace: [],
    };
  }

  if (Date.now() - entry.storedAt > entry.ttlMs) {
    cache.delete(key);
    return {
      ok: true,
      searched: true,
      provider: "cache",
      query: opts.query.trim(),
      sources: [],
      elapsedMs: elapsedSince(startedAt),
      providerTrace: [],
    };
  }

  return {
    ok: true,
    searched: true,
    provider: "cache",
    query: entry.query,
    sources: entry.sources.map((source) => ({ ...source })),
    ...(entry.answerPreview ? { answerPreview: entry.answerPreview } : {}),
    elapsedMs: elapsedSince(startedAt),
    providerTrace: [],
  };
}

export const cacheWebSearchProvider: WebSearchAdapter = {
  provider: "cache",
  search: ({ query, maxResults, config }) => runCacheWebSearch({ query, maxResults, config }),
};import "server-only";

import { resolveVerifiedHttpUrl } from "@/lib/verified-http-url";
import { normalizeWebSearchSources } from "@/lib/server/web-search/source-normalizer";
import type {
  WebSearchAdapter,
  WebSearchProviderConfig,
  WebSearchResult,
} from "@/lib/server/web-search/types";

type RobotsRule = {
  directive: "allow" | "disallow";
  path: string;
};

type RobotsGroup = {
  agents: string[];
  rules: RobotsRule[];
};

function elapsedSince(startedAt: number): number {
  return Date.now() - startedAt;
}

function failure(opts: {
  startedAt: number;
  error: string;
  detail?: string;
  searched?: boolean;
}): WebSearchResult {
  return {
    ok: false,
    searched: opts.searched ?? true,
    provider: "fetch",
    error: opts.error,
    ...(opts.detail ? { detail: opts.detail } : {}),
    elapsedMs: elapsedSince(opts.startedAt),
    providerTrace: [],
  };
}

function stripHtml(value: string): string {
  return value
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function decodeHtmlEntities(value: string): string {
  return value
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'");
}

function extractFirstMatch(html: string, regex: RegExp): string | undefined {
  const match = regex.exec(html);
  const value = match?.[1]?.trim();
  return value ? decodeHtmlEntities(stripHtml(value)) : undefined;
}

function extractMetaContent(html: string, name: string): string | undefined {
  const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const metaRegex = new RegExp(
    `<meta\\s+[^>]*(?:name|property)=["']${escapedName}["'][^>]*content=["']([^"']+)["'][^>]*>`,
    "i",
  );
  return extractFirstMatch(html, metaRegex);
}

function extractCanonicalUrl(html: string): string | undefined {
  return extractFirstMatch(html, /<link\s+[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["'][^>]*>/i);
}

function extractReadableSnippet(html: string): string | undefined {
  const paragraphs = html.match(/<p\b[^>]*>[\s\S]*?<\/p>/gi) ?? [];
  for (const paragraph of paragraphs) {
    const text = decodeHtmlEntities(stripHtml(paragraph));
    if (text.length >= 40) return text.slice(0, 500).trim();
  }
  const body = extractFirstMatch(html, /<body\b[^>]*>([\s\S]*?)<\/body>/i);
  return body ? body.slice(0, 500).trim() : undefined;
}

function parseRobotsTxt(text: string): RobotsGroup[] {
  const groups: RobotsGroup[] = [];
  let current: RobotsGroup | undefined;

  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.replace(/#.*$/, "").trim();
    if (!line) continue;
    const separator = line.indexOf(":");
    if (separator < 0) continue;

    const key = line.slice(0, separator).trim().toLowerCase();
    const value = line.slice(separator + 1).trim();

    if (key === "user-agent") {
      if (!current || current.rules.length > 0) {
        current = { agents: [], rules: [] };
        groups.push(current);
      }
      current.agents.push(value.toLowerCase());
      continue;
    }

    if ((key === "allow" || key === "disallow") && current) {
      current.rules.push({ directive: key, path: value });
    }
  }

  return groups;
}

function productToken(userAgent: string): string {
  return userAgent.split(/[\/\s;]/)[0]?.toLowerCase() || "*";
}

function ruleMatches(rulePath: string, pathWithQuery: string): boolean {
  if (!rulePath) return false;
  const escaped = rulePath
    .replace(/[.+?^${}()|[\]\\]/g, "\\$&")
    .replace(/\*/g, ".*")
    .replace(/\\\$$/, "$");
  return new RegExp(`^${escaped}`).test(pathWithQuery);
}

export function isAllowedByRobotsTxt(text: string, targetUrl: string, userAgent: string): boolean {
  const groups = parseRobotsTxt(text);
  if (groups.length === 0) return true;

  const token = productToken(userAgent);
  const exactGroups = groups.filter((group) => group.agents.some((agent) => agent === token));
  const wildcardGroups = groups.filter((group) => group.agents.some((agent) => agent === "*"));
  const applicable = exactGroups.length ? exactGroups : wildcardGroups;
  if (applicable.length === 0) return true;

  const url = new URL(targetUrl);
  const pathWithQuery = `${url.pathname}${url.search}`;
  let best: RobotsRule | undefined;

  for (const group of applicable) {
    for (const rule of group.rules) {
      if (!ruleMatches(rule.path, pathWithQuery)) continue;
      if (!best || rule.path.length > best.path.length || (rule.path.length === best.path.length && rule.directive === "allow")) {
        best = rule;
      }
    }
  }

  return best?.directive !== "disallow";
}

async function fetchTextWithTimeout(
  fetchImpl: typeof fetch,
  url: string,
  init: RequestInit,
  timeoutMs: number,
): Promise<Response> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetchImpl(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timeout);
  }
}

async function robotsAllows(opts: {
  targetUrl: string;
  config: WebSearchProviderConfig;
  fetchImpl: typeof fetch;
}): Promise<{ allowed: true } | { allowed: false; reason: string }> {
  if (!opts.config.fetchPage.respectRobots) return { allowed: true };

  const url = new URL(opts.targetUrl);
  const robotsUrl = `${url.origin}/robots.txt`;

  try {
    const response = await fetchTextWithTimeout(
      opts.fetchImpl,
      robotsUrl,
      {
        method: "GET",
        headers: { "User-Agent": opts.config.fetchPage.userAgent },
        redirect: "follow",
      },
      opts.config.fetchPage.timeoutMs,
    );

    // Conservative best-effort robots handling:
    // - 4xx means no robots policy was found for this origin, so access may proceed.
    // - 5xx, network errors, and timeouts are treated as unreachable and block fetch.
    if (response.status >= 400 && response.status < 500) return { allowed: true };
    if (!response.ok) return { allowed: false, reason: "robots_unreachable" };

    const text = await response.text();
    return isAllowedByRobotsTxt(text, opts.targetUrl, opts.config.fetchPage.userAgent)
      ? { allowed: true }
      : { allowed: false, reason: "robots_disallowed" };
  } catch {
    return { allowed: false, reason: "robots_unreachable" };
  }
}

export async function runFetchPageWebSearch(opts: {
  query: string;
  maxResults: number;
  config: WebSearchProviderConfig;
  fetchImpl?: typeof fetch;
}): Promise<WebSearchResult> {
  const startedAt = Date.now();
  if (!opts.config.fetchPage.enabled) {
    return failure({ startedAt, error: "fetch_page_disabled", searched: false });
  }

  const targetUrl = resolveVerifiedHttpUrl(opts.query);
  if (!targetUrl) {
    return failure({
      startedAt,
      error: "fetch_query_not_url",
      detail: "Direct page fetch only accepts an HTTP(S) URL.",
      searched: false,
    });
  }

  const fetchImpl = opts.fetchImpl ?? fetch;
  const robots = await robotsAllows({ targetUrl, config: opts.config, fetchImpl });
  if (!robots.allowed) {
    return failure({ startedAt, error: robots.reason, searched: false });
  }

  try {
    const response = await fetchTextWithTimeout(
      fetchImpl,
      targetUrl,
      {
        method: "GET",
        headers: {
          Accept: "text/html,application/xhtml+xml,text/plain;q=0.8,*/*;q=0.5",
          "User-Agent": opts.config.fetchPage.userAgent,
        },
        redirect: "follow",
      },
      opts.config.fetchPage.timeoutMs,
    );

    const text = await response.text();
    if (!response.ok) {
      return failure({ startedAt, error: `fetch_${response.status}`, detail: text.slice(0, 400) });
    }

    const canonical = resolveVerifiedHttpUrl(extractCanonicalUrl(text)) ?? targetUrl;
    const title = extractMetaContent(text, "og:title") ?? extractFirstMatch(text, /<title\b[^>]*>([\s\S]*?)<\/title>/i);
    const snippet = extractMetaContent(text, "description") ?? extractMetaContent(text, "og:description") ?? extractReadableSnippet(text);
    const sources = normalizeWebSearchSources(
      [{ title, url: canonical, snippet, provider: "fetch" }],
      { maxResults: opts.maxResults, provider: "fetch" },
    );

    return {
      ok: true,
      searched: true,
      provider: "fetch",
      query: opts.query.trim(),
      sources,
      answerPreview: snippet,
      elapsedMs: elapsedSince(startedAt),
      providerTrace: [],
    };
  } catch (error) {
    const aborted = error instanceof Error && error.name === "AbortError";
    return failure({
      startedAt,
      error: aborted ? "fetch_timeout" : "fetch_failed",
      detail: error instanceof Error ? error.message : String(error),
    });
  }
}

export const fetchPageProvider: WebSearchAdapter = {
  provider: "fetch",
  search: ({ query, maxResults, config }) => runFetchPageWebSearch({ query, maxResults, config }),
};import "server-only";

import { runOpenAiWebSearch } from "@/lib/server/openai-web-search";
