export async function runOpenAiFallbackWebSearch(opts: {
  query: string;
  maxResults: number;
  timeoutMs?: number;
}): Promise<WebSearchResult> {
  const startedAt = Date.now();
  const result = await runOpenAiWebSearch({
    query: opts.query,
    maxResults: opts.maxResults,
    timeoutMs: opts.timeoutMs,
  });

  if (!result.ok) {
    return {
      ok: false,
      searched: result.searched,
      provider: "openai",
      error: result.error,
      ...(result.detail ? { detail: result.detail } : {}),
      elapsedMs: Date.now() - startedAt,
      providerTrace: [],
    };
  }

  const sources = normalizeWebSearchSources(
    result.sources.map((source) => ({
      title: source.title,
      url: source.url,
      snippet: source.snippet,
      provider: "openai",
    })),
    { maxResults: opts.maxResults, provider: "openai" },
  );

  return {
    ok: true,
    searched: true,
    provider: "openai",
    query: result.query,
    sources,
    ...(result.answerPreview ? { answerPreview: result.answerPreview } : {}),
    elapsedMs: Date.now() - startedAt,
    providerTrace: [],
  };
}

export const openAiWebSearchProvider: WebSearchAdapter = {
  provider: "openai",
  search: ({ query, maxResults }) => runOpenAiFallbackWebSearch({ query, maxResults }),
};import "server-only";

import type { WebSearchProviderConfig } from "@/lib/server/web-search/types";

const DEFAULT_PROVIDER_ORDER = ["cache", "searxng"];
const DEFAULT_SEARXNG_URL = "";
const DEFAULT_MAX_RESULTS = 8;

function readBoolean(raw: string | undefined, defaultValue: boolean): boolean {
  const value = raw?.trim().toLowerCase();
  if (!value) return defaultValue;
  if (value === "1" || value === "true" || value === "yes" || value === "on") return true;
  if (value === "0" || value === "false" || value === "no" || value === "off") return false;
  return defaultValue;
}

function readPositiveInt(raw: string | undefined, defaultValue: number, maxValue?: number): number {
  const parsed = Number.parseInt(raw?.trim() ?? "", 10);
  if (!Number.isFinite(parsed) || parsed <= 0) return defaultValue;
  return typeof maxValue === "number" ? Math.min(parsed, maxValue) : parsed;
}

function readProviderOrder(raw: string | undefined): string[] {
  const providers = (raw ?? DEFAULT_PROVIDER_ORDER.join(","))
    .split(",")
    .map((provider) => provider.trim().toLowerCase())
    .filter(Boolean);
  return providers.length ? providers : [...DEFAULT_PROVIDER_ORDER];
}

export function getWebSearchProviderConfig(
  env: Partial<Record<string, string | undefined>> = process.env,
): WebSearchProviderConfig {
  const maxResults = readPositiveInt(env.WEB_SEARCH_MAX_RESULTS, DEFAULT_MAX_RESULTS, 12);

  return {
    enabled: readBoolean(env.WEB_SEARCH_ENABLED, false),
    providerOrder: readProviderOrder(env.WEB_SEARCH_PROVIDER_ORDER),
    maxResults,
    cache: {
      enabled: readBoolean(env.WEB_SEARCH_CACHE_ENABLED, true),
      ttlSeconds: readPositiveInt(env.WEB_SEARCH_CACHE_TTL_SECONDS, 86_400),
    },
    searxng: {
      url: env.SEARXNG_URL?.trim() || DEFAULT_SEARXNG_URL,
      maxResults: readPositiveInt(env.SEARXNG_MAX_RESULTS, maxResults, 12),
      timeoutMs: readPositiveInt(env.SEARXNG_TIMEOUT_MS, 10_000),
    },
    fetchPage: {
      enabled: readBoolean(env.WEB_SEARCH_FETCH_PAGE_ENABLED, false),
      timeoutMs: readPositiveInt(env.WEB_SEARCH_FETCH_TIMEOUT_MS, 10_000),
      respectRobots: readBoolean(env.WEB_SEARCH_RESPECT_ROBOTS, true),
      userAgent: env.WEB_SEARCH_USER_AGENT?.trim() || "SpiritOSLocalSearch/0.1",
    },
    paidFallback: {
      enabled: readBoolean(env.WEB_SEARCH_PAID_FALLBACK_ENABLED, false),
      requireApproval: readBoolean(
        env.WEB_SEARCH_PAID_FALLBACK_REQUIRES_APPROVAL ?? env.WEB_SEARCH_REQUIRE_APPROVAL_FOR_PAID,
        true,
      ),
    },
  };
}import "server-only";

import { cacheWebSearchProvider, storeWebSearchCacheResult } from "@/lib/server/web-search/cache-provider";
import { fetchPageProvider } from "@/lib/server/web-search/fetch-page-provider";
import { openAiWebSearchProvider } from "@/lib/server/web-search/openai-provider";
import { getWebSearchProviderConfig } from "@/lib/server/web-search/provider-config";
import { searxngProvider } from "@/lib/server/web-search/searxng-provider";
import type {
  WebSearchAdapter,
  WebSearchProvider,
  WebSearchProviderConfig,
  WebSearchProviderTrace,
  WebSearchResult,
} from "@/lib/server/web-search/types";

const KNOWN_PROVIDERS = new Set<WebSearchProvider>(["cache", "searxng", "ddgs", "fetch", "openai", "manual"]);
const DEFAULT_ADAPTERS: WebSearchAdapter[] = [
  cacheWebSearchProvider,
  searxngProvider,
  fetchPageProvider,
  openAiWebSearchProvider,
];

export type RunWebSearchOptions = {
  query: string;
  maxResults?: number;
  paidFallbackApproved?: boolean;
  config?: WebSearchProviderConfig;
  providers?: WebSearchAdapter[];
};

function nowMs(): number {
  return Date.now();
}

function isKnownProvider(provider: string): provider is WebSearchProvider {
  return KNOWN_PROVIDERS.has(provider as WebSearchProvider);
}

function fallbackFailure(opts: {
  query: string;
  providerTrace: WebSearchProviderTrace[];
  startedAt: number;
  searched: boolean;
  error: string;
  detail: string;
}): WebSearchResult {
  return {
    ok: false,
    searched: opts.searched,
    provider: "manual",
    error: opts.error,
    detail: opts.detail,
    elapsedMs: nowMs() - opts.startedAt,
    providerTrace: opts.providerTrace,
  };
}

export async function runWebSearch(opts: RunWebSearchOptions): Promise<WebSearchResult> {
  const startedAt = nowMs();
  const query = opts.query.trim();
  const config = opts.config ?? getWebSearchProviderConfig();
  const maxResults =
    typeof opts.maxResults === "number" && opts.maxResults > 0
      ? Math.min(Math.floor(opts.maxResults), 12)
      : config.maxResults;
  const providerTrace: WebSearchProviderTrace[] = [];
  const adapters = new Map((opts.providers ?? DEFAULT_ADAPTERS).map((adapter) => [adapter.provider, adapter]));
  let attempted = false;

  if (!query) {
    return fallbackFailure({
      query,
      providerTrace,
      startedAt,
      searched: false,
      error: "empty_query",
      detail: "Query is empty.",
    });
  }

  if (!config.enabled) {
    providerTrace.push({
      provider: "manual",
      status: "skipped",
      reason: "web_search_disabled",
      elapsedMs: nowMs() - startedAt,
    });
    return fallbackFailure({
      query,
      providerTrace,
      startedAt,
      searched: false,
      error: "disabled",
      detail: "WEB_SEARCH_ENABLED is not true - web search is off.",
    });
  }

  for (const providerName of config.providerOrder) {
    if (!isKnownProvider(providerName) || providerName === "manual") {
      providerTrace.push({ provider: providerName, status: "skipped", reason: "unknown_provider" });
      continue;
    }

    if (providerName === "openai") {
      if (!config.paidFallback.enabled) {
        providerTrace.push({ provider: "openai", status: "skipped", reason: "paid_fallback_disabled" });
        continue;
      }
      if (config.paidFallback.requireApproval && opts.paidFallbackApproved !== true) {
        providerTrace.push({ provider: "openai", status: "skipped", reason: "paid_fallback_approval_missing" });
        continue;
      }
    }

    if (providerName === "fetch" && !config.fetchPage.enabled) {
      providerTrace.push({ provider: "fetch", status: "skipped", reason: "fetch_page_disabled" });
      continue;
    }

    const adapter = adapters.get(providerName);
    if (!adapter) {
      providerTrace.push({ provider: providerName, status: "skipped", reason: "provider_unavailable" });
      continue;
    }

    const providerStartedAt = nowMs();
    providerTrace.push({ provider: providerName, status: "attempted" });
    attempted = true;

    try {
      const result = await adapter.search({ query, maxResults, config });
      const elapsedMs = nowMs() - providerStartedAt;
      const attemptedTrace = providerTrace[providerTrace.length - 1];

      if (result.ok && result.sources.length > 0) {
        attemptedTrace.status = "used";
        attemptedTrace.elapsedMs = elapsedMs;
        attemptedTrace.sourceCount = result.sources.length;
        if (providerName !== "cache") {
          storeWebSearchCacheResult({
            query,
            maxResults,
            config,
            sources: result.sources,
            answerPreview: result.answerPreview,
          });
        }
        return {
          ...result,
          provider: providerName,
          query,
          searched: true,
          elapsedMs: nowMs() - startedAt,
          providerTrace,
        };
      }

      attemptedTrace.status = "failed";
      attemptedTrace.elapsedMs = elapsedMs;
      attemptedTrace.sourceCount = result.ok ? result.sources.length : 0;
      attemptedTrace.reason = result.ok ? "no_verified_sources" : result.error;
    } catch (error) {
      const attemptedTrace = providerTrace[providerTrace.length - 1];
      attemptedTrace.status = "failed";
      attemptedTrace.elapsedMs = nowMs() - providerStartedAt;
      attemptedTrace.sourceCount = 0;
      attemptedTrace.reason = error instanceof Error ? error.message : String(error);
    }
  }

  return fallbackFailure({
    query,
    providerTrace,
    startedAt,
    searched: attempted,
    error: "no_local_provider_available",
    detail: "No free/local web-search provider returned verified sources.",
  });
}import "server-only";

import { normalizeWebSearchSources } from "@/lib/server/web-search/source-normalizer";
import type {
  WebSearchAdapter,
  WebSearchProviderConfig,
  WebSearchResult,
} from "@/lib/server/web-search/types";

type SearxngSearchResult = {
  title?: unknown;
  url?: unknown;
  content?: unknown;
  publishedDate?: unknown;
  published_date?: unknown;
};

const DEFAULT_TIMEOUT_MS = 10_000;

function elapsedSince(startedAt: number): number {
  return Date.now() - startedAt;
}

function failure(opts: {
  query: string;
  startedAt: number;
  error: string;
  detail?: string;
  searched?: boolean;
}): WebSearchResult {
  return {
    ok: false,
    searched: opts.searched ?? true,
    provider: "searxng",
    error: opts.error,
    ...(opts.detail ? { detail: opts.detail } : {}),
    elapsedMs: elapsedSince(opts.startedAt),
    providerTrace: [],
  };
}

function buildSearxngUrl(baseUrl: string, query: string): string {
  const url = new URL("/search", baseUrl);
  url.searchParams.set("q", query);
  url.searchParams.set("format", "json");
  return url.toString();
}

function stringValue(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

export async function runSearxngWebSearch(opts: {
  query: string;
  maxResults: number;
  config: WebSearchProviderConfig;
  fetchImpl?: typeof fetch;
}): Promise<WebSearchResult> {
  const startedAt = Date.now();
  const query = opts.query.trim();
  if (!query) {
    return failure({ query, startedAt, error: "empty_query", detail: "Query is empty.", searched: false });
  }

  if (!opts.config.searxng.url.trim()) {
    return failure({
      query,
      startedAt,
      error: "searxng_not_configured",
      detail: "SEARXNG_URL is not configured.",
      searched: false,
    });
  }

  const fetchImpl = opts.fetchImpl ?? fetch;
  const timeoutMs = opts.config.searxng.timeoutMs || DEFAULT_TIMEOUT_MS;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetchImpl(buildSearxngUrl(opts.config.searxng.url, query), {
      method: "GET",
      headers: {
        Accept: "application/json",
        "User-Agent": opts.config.fetchPage.userAgent,
      },
      signal: controller.signal,
    });

    const text = await response.text();
    if (!response.ok) {
      return failure({
        query,
        startedAt,
        error: response.status === 403 ? "searxng_json_forbidden" : `searxng_${response.status}`,
        detail: text.slice(0, 400),
      });
    }

    let json: unknown;
    try {
      json = JSON.parse(text) as unknown;
    } catch {
      return failure({
        query,
        startedAt,
        error: "searxng_invalid_json",
        detail: text.slice(0, 400),
      });
    }

    const results =
      json && typeof json === "object" && Array.isArray((json as { results?: unknown }).results)
        ? ((json as { results: SearxngSearchResult[] }).results)
        : [];
    const sources = normalizeWebSearchSources(
      results.map((result) => ({
        title: stringValue(result.title),
        url: stringValue(result.url),
        snippet: stringValue(result.content),
        publishedAt: stringValue(result.publishedDate) ?? stringValue(result.published_date),
        provider: "searxng",
      })),
      { maxResults: Math.min(opts.maxResults, opts.config.searxng.maxResults), provider: "searxng" },
    );

    return {
      ok: true,
      searched: true,
      provider: "searxng",
      query,
      sources,
      elapsedMs: elapsedSince(startedAt),
      providerTrace: [],
    };
  } catch (error) {
    const aborted = error instanceof Error && error.name === "AbortError";
    return failure({
      query,
      startedAt,
      error: aborted ? "searxng_timeout" : "searxng_unreachable",
      detail: error instanceof Error ? error.message : String(error),
    });
  } finally {
    clearTimeout(timeout);
  }
}

export const searxngProvider: WebSearchAdapter = {
  provider: "searxng",
  search: ({ query, maxResults, config }) => runSearxngWebSearch({ query, maxResults, config }),
};import "server-only";

import { resolveVerifiedHttpUrl } from "@/lib/verified-http-url";
import type { WebSearchProvider, WebSearchSource } from "@/lib/server/web-search/types";

export type RawWebSearchSource = {
  title?: string | null;
  url?: string | null;
  snippet?: string | null;
  publishedAt?: string | null;
  provider?: WebSearchProvider;
};

function trimToUndefined(value: string | null | undefined, maxLength: number): string | undefined {
  const trimmed = value?.trim();
  if (!trimmed) return undefined;
  return trimmed.length > maxLength ? trimmed.slice(0, maxLength).trimEnd() : trimmed;
}

function fallbackTitle(url: string): string {
  try {
    return new URL(url).hostname || "Untitled";
  } catch {
    return "Untitled";
  }
}

function dedupeKey(url: string): string {
  try {
    const parsed = new URL(url);
    parsed.hash = "";
    if (parsed.pathname !== "/") parsed.pathname = parsed.pathname.replace(/\/+$/, "");
    return parsed.toString().toLowerCase();
  } catch {
    return url.toLowerCase();
  }
}

export function normalizeWebSearchSources(
  sources: RawWebSearchSource[],
  opts: {
    maxResults: number;
    provider?: WebSearchProvider;
  },
): WebSearchSource[] {
  const maxResults = Math.max(0, Math.floor(opts.maxResults));
  const normalized: WebSearchSource[] = [];
  const seen = new Set<string>();

  for (const source of sources) {
    if (normalized.length >= maxResults) break;

    const url = resolveVerifiedHttpUrl(source.url ?? undefined);
    if (!url) continue;

    const key = dedupeKey(url);
    if (seen.has(key)) continue;
    seen.add(key);

    const title = trimToUndefined(source.title, 180) ?? fallbackTitle(url);
    const snippet = trimToUndefined(source.snippet, 500);
    const publishedAt = trimToUndefined(source.publishedAt, 80);
    const provider = source.provider ?? opts.provider;

    normalized.push({
      title,
      url,
      ...(snippet ? { snippet } : {}),
      ...(publishedAt ? { publishedAt } : {}),
      ...(provider ? { provider } : {}),
    });
  }

  return normalized;
}import "server-only";

export type WebSearchProvider =
  | "cache"
  | "searxng"
  | "ddgs"
  | "fetch"
  | "openai"
  | "manual";

export type WebSearchStatus = "used" | "skipped" | "disabled" | "failed";

export type WebSearchProviderTrace = {
  provider: string;
  status: "skipped" | "attempted" | "used" | "failed";
  reason?: string;
  elapsedMs?: number;
  sourceCount?: number;
};

export type WebSearchSource = {
  title: string;
  url: string;
  snippet?: string;
  publishedAt?: string;
  provider?: WebSearchProvider;
};

export type WebSearchOk = {
  ok: true;
  searched: true;
  provider: WebSearchProvider;
  query: string;
  sources: WebSearchSource[];
  answerPreview?: string;
  elapsedMs: number;
  providerTrace: WebSearchProviderTrace[];
};

export type WebSearchFail = {
  ok: false;
  searched: boolean;
  provider: WebSearchProvider;
  error: string;
  detail?: string;
  elapsedMs: number;
  providerTrace: WebSearchProviderTrace[];
};

export type WebSearchResult = WebSearchOk | WebSearchFail;

export type WebSearchProviderConfig = {
  enabled: boolean;
  providerOrder: string[];
  maxResults: number;
  cache: {
    enabled: boolean;
    ttlSeconds: number;
  };
  searxng: {
    url: string;
    maxResults: number;
    timeoutMs: number;
  };
  fetchPage: {
    enabled: boolean;
    timeoutMs: number;
    respectRobots: boolean;
    userAgent: string;
  };
  paidFallback: {
    enabled: boolean;
    requireApproval: boolean;
  };
};

export type WebSearchAdapterRequest = {
  query: string;
  maxResults: number;
  config: WebSearchProviderConfig;
};

export type WebSearchAdapter = {
  provider: WebSearchProvider;
  search: (request: WebSearchAdapterRequest) => Promise<WebSearchResult>;
};import type {
  GeneralIntelligenceEvalCase,
  GeneralIntelligenceTrait,
} from "@/lib/spirit/general-intelligence-eval";

function trait(
  id: string,
  label: string,
  patterns: readonly RegExp[],
  matchMode?: "any" | "all",
): GeneralIntelligenceTrait {
  return { id, label, patterns, matchMode };
}

