});import "server-only";

import path from "path";

const WINDOWS_LIST_DEFAULT_MAX = 200;
const WINDOWS_LIST_HARD_CAP = 200;

export type WindowsFileEntry = {
  name: string;
  type: "file" | "directory";
  sizeBytes: number | null;
  modifiedAt: string | null;
};

export type ListWindowsFilesResult =
  | {
      ok: true;
      path: string;
      entries: WindowsFileEntry[];
      truncated: boolean;
    }
  | {
      ok: false;
      code:
        | "WINDOWS_FS_DISABLED"
        | "WINDOWS_FS_CONFIG_MISSING"
        | "PATH_NOT_ALLOWLISTED"
        | "PATH_BLOCKED"
        | "WINDOWS_AGENT_UNREACHABLE"
        | "TOKEN_REJECTED"
        | "WINDOWS_AGENT_FS_ENDPOINT_MISSING"
        | "WINDOWS_AGENT_ERROR";
      message: string;
    };

type WindowsAgentErrorBody = {
  ok?: false;
  code?: string;
  message?: string;
  error?: string;
};

const BLOCKED_WINDOWS_DIRS = new Set([
  "node_modules",
  ".git",
  ".next",
  "dist",
  "build",
  "coverage",
  ".turbo",
  ".cache",
]);

function matchesBlockedBasename(name: string): boolean {
  const lower = name.toLowerCase();
  if (lower.startsWith(".")) return true;
  if (lower === ".env" || lower.startsWith(".env.")) return true;
  if (lower.endsWith(".pem") || lower.endsWith(".key")) return true;
  if (lower === "id_rsa" || lower === "id_ed25519") return true;
  if (lower.startsWith("secrets.") || lower.startsWith("credentials.")) return true;
  return false;
}

export function isWindowsFsEnabled(): boolean {
  return process.env.SPIRIT_WINDOWS_FS_ENABLED === "true";
}

export function normalizeWindowsRequestPath(inputPath: string): string | null {
  if (typeof inputPath !== "string") return null;
  let s = inputPath.trim().replace(/^my\s+/i, "");
  s = s.replace(/^[`"']+/, "").replace(/[`"'.,;:!?]+$/, "").trim();
  s = s.replace(/\s+(folder|directory|dir)\s*$/i, "").trim();
  s = s.replace(/\//g, "\\");
  const driveSlash = s.match(/^([a-z])\\(.+)$/i);
  if (driveSlash) {
    s = `${driveSlash[1]!.toUpperCase()}:\\${driveSlash[2]}`;
  } else {
    s = s.replace(/^([a-z]):/i, (_, d: string) => `${d.toUpperCase()}:`);
  }
  if (!/^[A-Z]:\\/i.test(s)) return null;
  return path.win32.resolve(s);
}

function parseAllowlist(): string[] {
  const raw = process.env.SPIRIT_WINDOWS_FS_ALLOWLIST ?? "";
  return raw
    .split(/[,\n]+/)
    .map((p) => normalizeWindowsRequestPath(p))
    .filter((p): p is string => p != null && !/^[A-Z]:\\?$/i.test(p))
}

function isWithinRoot(child: string, root: string): boolean {
  const c = path.win32.normalize(child).toLowerCase();
  const r = path.win32.normalize(root).toLowerCase();
  const rWithSep = r.endsWith("\\") ? r : `${r}\\`;
  return c === r || c.startsWith(rWithSep);
}

export function isWindowsPathAllowlisted(inputPath: string): boolean {
  const normalized = normalizeWindowsRequestPath(inputPath);
  if (!normalized) return false;
  return parseAllowlist().some((root) => isWithinRoot(normalized, root));
}

function isBlockedWindowsPath(inputPath: string): boolean {
  const normalized = normalizeWindowsRequestPath(inputPath);
  if (!normalized) return true;
  const withoutDrive = normalized.replace(/^[A-Z]:\\/i, "");
  const parts = withoutDrive.split("\\").filter(Boolean);
  for (const part of parts) {
    if (BLOCKED_WINDOWS_DIRS.has(part.toLowerCase())) return true;
    if (matchesBlockedBasename(part)) return true;
  }
  return false;
}

function maxEntriesFromInput(maxEntries: number | undefined): number {
  if (!Number.isFinite(maxEntries) || maxEntries == null || maxEntries < 1) {
    return WINDOWS_LIST_DEFAULT_MAX;
  }
  return Math.min(Math.floor(maxEntries), WINDOWS_LIST_HARD_CAP);
}

export function normalizeWindowsFsBaseUrl(rawUrl: string): string | null {
  const trimmed = rawUrl.trim();
  if (!trimmed) return null;
  const withoutAngleBrackets = trimmed.replace(/<([^/?#]+)>/g, "$1");
  try {
    const parsed = new URL(withoutAngleBrackets);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return null;
    parsed.pathname = parsed.pathname.replace(/\/+$/, "");
    parsed.search = "";
    parsed.hash = "";
    return parsed.toString().replace(/\/$/, "");
  } catch {
    return null;
  }
}

export async function listWindowsFiles(input: {
  path: string;
  maxEntries?: number;
}): Promise<ListWindowsFilesResult> {
  if (!isWindowsFsEnabled()) {
    return {
      ok: false,
      code: "WINDOWS_FS_DISABLED",
      message:
        "Windows folder access is disabled. Enable SPIRIT_WINDOWS_FS_ENABLED and configure SPIRIT_WINDOWS_FS_BASE_URL, SPIRIT_WINDOWS_FS_TOKEN, and SPIRIT_WINDOWS_FS_ALLOWLIST.",
    };
  }

  const baseUrl = normalizeWindowsFsBaseUrl(process.env.SPIRIT_WINDOWS_FS_BASE_URL ?? "");
  const token = process.env.SPIRIT_WINDOWS_FS_TOKEN?.trim();
  if (!baseUrl || !token) {
    return {
      ok: false,
      code: "WINDOWS_FS_CONFIG_MISSING",
      message:
        "Windows folder access is missing or has an invalid SPIRIT_WINDOWS_FS_BASE_URL or SPIRIT_WINDOWS_FS_TOKEN. Use a URL like http://10.0.0.126:3000 without angle brackets.",
    };
  }

  const requestedPath = normalizeWindowsRequestPath(input.path);
  if (!requestedPath) {
    return {
      ok: false,
      code: "PATH_BLOCKED",
      message: "That Windows path is not a supported absolute drive path.",
    };
  }

  if (isBlockedWindowsPath(requestedPath)) {
    return {
      ok: false,
      code: "PATH_BLOCKED",
      message: "That Windows path is blocked by the filesystem safety rules.",
    };
  }

  if (!isWindowsPathAllowlisted(requestedPath)) {
    return {
      ok: false,
      code: "PATH_NOT_ALLOWLISTED",
      message: "That path is outside the configured Windows filesystem allowlist.",
    };
  }

  const endpoint = new URL("/api/files/list", baseUrl).toString();
  try {
    const res = await fetch(endpoint, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        path: requestedPath,
        maxEntries: maxEntriesFromInput(input.maxEntries),
      }),
    });

    if (res.status === 401 || res.status === 403) {
      return {
        ok: false,
        code: "TOKEN_REJECTED",
        message: "The Windows agent rejected the bearer token.",
      };
    }

    const body = (await res.json().catch(() => null)) as
      | Extract<ListWindowsFilesResult, { ok: true }>
      | WindowsAgentErrorBody
      | null;

    if (res.status === 404) {
      return {
        ok: false,
        code: "WINDOWS_AGENT_FS_ENDPOINT_MISSING",
        message:
          "The Windows agent is reachable, but it does not expose /api/files/list. Copy the updated scripts/spiritdesktop-windows/agent.js to the Windows machine and restart node agent.js.",
      };
    }

    if (body && body.ok === false) {
      const errorBody = body as WindowsAgentErrorBody;
      const code =
        errorBody.code === "WINDOWS_FS_DISABLED" ||
        errorBody.code === "WINDOWS_FS_CONFIG_MISSING" ||
        errorBody.code === "PATH_NOT_ALLOWLISTED" ||
        errorBody.code === "PATH_BLOCKED"
          ? errorBody.code
          : "WINDOWS_AGENT_ERROR";
      return {
        ok: false,
        code,
        message:
          errorBody.message ??
          errorBody.error ??
          "The Windows agent blocked that filesystem request.",
      };
    }

    if (!res.ok || !body) {
      return {
        ok: false,
        code: "WINDOWS_AGENT_ERROR",
        message: `The Windows agent returned an invalid filesystem response (HTTP ${res.status}).`,
      };
    }

    if (body.ok === true) return body;

    return {
      ok: false,
      code: "WINDOWS_AGENT_ERROR",
      message: "The Windows agent returned a filesystem response without ok=true.",
    };
  } catch {
    return {
      ok: false,
      code: "WINDOWS_AGENT_UNREACHABLE",
      message: "The Windows agent is unreachable at SPIRIT_WINDOWS_FS_BASE_URL.",
    };
  }
}export type GeneralIntelligenceEvalCategory =
  | "troubleshooting-diagnosis"
  | "research-verification"
  | "school-paper-help"
  | "technical-planning"
  | "emotional-practical-advice"
  | "uncertainty-honesty"
  | "source-citation-honesty"
  | "direct-answer-vs-generic-checklist";

export type GeneralIntelligenceTrait = {
  id: string;
  label: string;
  patterns: readonly RegExp[];
  matchMode?: "any" | "all";
};

export type GeneralIntelligenceMinimumPassingCriteria = {
  minExpectedTraits: number;
  maxForbiddenTraits: number;
  requiredExpectedTraitIds?: readonly string[];
  notes: string;
};

export type GeneralIntelligenceEvalCase = {
  id: string;
  category: GeneralIntelligenceEvalCategory;
  userPrompt: string;
  weakAnswerPattern?: readonly RegExp[];
  weakFailureMode?: string;
  expectedTraits: readonly GeneralIntelligenceTrait[];
  forbiddenTraits: readonly GeneralIntelligenceTrait[];
  needsWeb: boolean;
  needsFiles: boolean;
  idealFirstMove: string;
  minimumPassingCriteria: GeneralIntelligenceMinimumPassingCriteria;
};

export type GeneralIntelligenceEvalScore = {
  pass: boolean;
  expectedTraitCount: number;
  forbiddenTraitCount: number;
  missingTraitCount: number;
  score: number;
};

export type GeneralIntelligenceEvalReport = GeneralIntelligenceEvalScore & {
  evalCaseId: string;
  category: GeneralIntelligenceEvalCategory;
  matchedExpectedTraits: GeneralIntelligenceTrait[];
  matchedForbiddenTraits: GeneralIntelligenceTrait[];
  missingTraits: GeneralIntelligenceTrait[];
  criteria: GeneralIntelligenceMinimumPassingCriteria;
};

function traitMatches(answer: string, trait: GeneralIntelligenceTrait): boolean {
  const matches = trait.patterns.map((pattern) => pattern.test(answer));
  if (trait.matchMode === "all") return matches.every(Boolean);
  return matches.some(Boolean);
}

export function detectExpectedTraits(
  answer: string,
  evalCase: GeneralIntelligenceEvalCase,
): GeneralIntelligenceTrait[] {
  return evalCase.expectedTraits.filter((trait) => traitMatches(answer, trait));
}

export function detectForbiddenTraits(
  answer: string,
  evalCase: GeneralIntelligenceEvalCase,
): GeneralIntelligenceTrait[] {
  return evalCase.forbiddenTraits.filter((trait) => traitMatches(answer, trait));
}

function requiredTraitsMet(
  matchedExpectedTraits: readonly GeneralIntelligenceTrait[],
  requiredExpectedTraitIds: readonly string[] | undefined,
): boolean {
  if (!requiredExpectedTraitIds || requiredExpectedTraitIds.length === 0) return true;
  const matchedIds = new Set(matchedExpectedTraits.map((trait) => trait.id));
  return requiredExpectedTraitIds.every((id) => matchedIds.has(id));
}

export function scoreAnswerAgainstTraits(
  answer: string,
  evalCase: GeneralIntelligenceEvalCase,
): GeneralIntelligenceEvalScore {
  const matchedExpectedTraits = detectExpectedTraits(answer, evalCase);
  const matchedForbiddenTraits = detectForbiddenTraits(answer, evalCase);
  const missingTraitCount = evalCase.expectedTraits.length - matchedExpectedTraits.length;
  const criteria = evalCase.minimumPassingCriteria;
  const pass =
    matchedExpectedTraits.length >= criteria.minExpectedTraits &&
    matchedForbiddenTraits.length <= criteria.maxForbiddenTraits &&
    requiredTraitsMet(matchedExpectedTraits, criteria.requiredExpectedTraitIds);

  return {
    pass,
    expectedTraitCount: matchedExpectedTraits.length,
    forbiddenTraitCount: matchedForbiddenTraits.length,
    missingTraitCount,
    score: matchedExpectedTraits.length - matchedForbiddenTraits.length,
  };
}

export function createEvalReport(
  answer: string,
  evalCase: GeneralIntelligenceEvalCase,
): GeneralIntelligenceEvalReport {
  const matchedExpectedTraits = detectExpectedTraits(answer, evalCase);
  const matchedForbiddenTraits = detectForbiddenTraits(answer, evalCase);
  const matchedIds = new Set(matchedExpectedTraits.map((trait) => trait.id));
  const missingTraits = evalCase.expectedTraits.filter((trait) => !matchedIds.has(trait.id));
  const score = scoreAnswerAgainstTraits(answer, evalCase);

  return {
    ...score,
    evalCaseId: evalCase.id,
    category: evalCase.category,
    matchedExpectedTraits,
    matchedForbiddenTraits,
    missingTraits,
    criteria: evalCase.minimumPassingCriteria,
  };
}import {
  detectSpiritTaskPolicy,
  type SpiritTaskPolicyId,
} from "@/lib/spirit/spirit-task-policy";

export type SpiritEvidenceStrength = "direct" | "strong" | "medium" | "weak" | "missing";

export type SpiritEvidenceSignal = {
  id: string;
  strength: SpiritEvidenceStrength;
  label: string;
  instruction: string;
};

export type SpiritEvidenceAssessment = {
  taskPolicyId: SpiritTaskPolicyId;
  signals: readonly SpiritEvidenceSignal[];
  leadGuards: readonly string[];
  confidenceGuidance: readonly string[];
};

const DEFAULT_SIGNALS: readonly SpiritEvidenceSignal[] = [
  {
    id: "user-observation",
    strength: "medium",
    label: "User observation",
    instruction: "Treat the user's report as important evidence, but separate what they observed from what they concluded.",
  },
  {
    id: "missing-measurement",
    strength: "missing",
    label: "Missing measurement",
    instruction: "If a measurement, log, source, timestamp, screenshot, error text, or direct artifact would decide the issue, say so.",
  },
];

const TROUBLESHOOTING_SIGNALS: readonly SpiritEvidenceSignal[] = [
  {
    id: "subjective-symptom",
    strength: "weak",
    label: "Subjective symptom or sensory clue",
    instruction:
      "Treat touch, feels hot, seems slow, sounds weird, or similar sensory impressions as weak clues until backed by measurements, logs, gauges, or repeatable behavior. Do not call a weak clue a bad sign, a definite clue, or strong evidence by itself.",
  },
  {
    id: "instrumented-measurement",
    strength: "direct",
    label: "Instrumented measurement",
    instruction:
      "Prefer actual temperatures, gauges, error codes, logs, profiler output, warning lights, repro steps, or direct measurements over guesses.",
  },
  {
    id: "competing-causes",
    strength: "medium",
    label: "Competing causes",
    instruction:
      "Rank competing explanations before treating the user's suspected cause as likely. Avoid phrasing like 'that's a common cause' when the prompt only supports 'possible, but not proven.'",
  },
];

const SOURCE_SIGNALS: readonly SpiritEvidenceSignal[] = [
  {
    id: "verified-source-context",
    strength: "direct",
    label: "Verified source context",
    instruction:
      "Only citations, URLs, files, or web results actually provided in context count as verified source evidence.",
  },
  {
    id: "model-memory",
    strength: "weak",
    label: "Model memory",
    instruction:
      "Treat memory-only facts as unverified background when the user asks for citations, current facts, or source-dependent claims. Do not substitute 'this is standard/common knowledge' for a citation.",
  },
];

const HIGH_STAKES_SIGNALS: readonly SpiritEvidenceSignal[] = [
  {
    id: "safety-sensitive",
    strength: "weak",
    label: "Safety-sensitive inference",
    instruction:
      "For medical, legal, financial, medication, vehicle safety, electrical, smoke/fire, or self-harm-adjacent topics, avoid false certainty and route toward qualified help or safety-first checks when risk is plausible.",
  },
];

const TASK_EXTRA_SIGNALS: Partial<Record<SpiritTaskPolicyId, readonly SpiritEvidenceSignal[]>> = {
  "troubleshooting-diagnosis": TROUBLESHOOTING_SIGNALS,
  "research-verification": SOURCE_SIGNALS,
  "citation-source-request": SOURCE_SIGNALS,
  "uncertainty-check": SOURCE_SIGNALS,
};

function hasHighStakesLanguage(userText: string): boolean {
  return /\b(insulin|medication|medicine|dose|doctor|ER|emergency|chest pain|smoke|burning smell|fire|sparking|brakes|stalled|highway|legal|lawsuit|tax|invest|self[- ]?harm|suicide)\b/i.test(
    userText,
  );
}

function hasWeakSensoryTroubleshootingClue(userText: string): boolean {
  return /\b(warm|hot|feels hot|touch|slow|buggy|sounds weird|noise|stalled|crashed|high CPU|CPU is high)\b/i.test(
    userText,
  );
}

function hasSuspectedCauseQuestion(userText: string): boolean {
  return /\b(is it|is this|could it be|does that mean|is .* broken|is .* bad|is .* overheating|is .* the)\b/i.test(
    userText,
  );
}

function hasHeatOrTemperatureClue(userText: string): boolean {
  return /\b(warm|hot|heat|overheat|overheating|temperature|temp|thermal|cooling)\b/i.test(
    userText,
  );
}

function buildLeadGuards(userText: string, taskPolicyId: SpiritTaskPolicyId): string[] {
  const guards: string[] = [];
  if (
    taskPolicyId === "troubleshooting-diagnosis" &&
    hasWeakSensoryTroubleshootingClue(userText) &&
    hasSuspectedCauseQuestion(userText)
  ) {
    guards.push(
      "Weak-clue troubleshooting guard: open by downgrading the suspected cause, e.g. 'possible, but not proven from that alone' or 'not enough evidence to conclude that yet.'",
      "Do not open with 'that sounds like a bad sign,' 'definitely a clue,' or a similar alarm phrase unless the prompt includes direct danger evidence such as smoke, fire, repeated shutdowns, severe warning lights, or visible damage.",
      "Before suggesting swaps, replacements, outlets, or maintenance, ask for or recommend the decisive measurement/log/gauge/profiler check.",
    );
    if (hasHeatOrTemperatureClue(userText)) {
      guards.push(
        "Heat-specific guard: if the only heat evidence is touch, prioritize actual sensor temperature or gauge readings before dust, airflow, fan, thermal paste, reseating, or other maintenance advice. Maintenance belongs after measured high temps, failed fans, artifacts, repeated thermal shutdowns, smoke, burning smell, or visible damage.",
      );
    }
  }
  if (taskPolicyId === "citation-source-request" || taskPolicyId === "research-verification") {
    guards.push(
      "Source guard: if no verified source context is attached, do not reassure with 'standard,' 'common,' or 'generally known'; say sources are missing and offer a verification path.",
    );
  }
  return guards;
}

export function assessSpiritEvidence(userText: string): SpiritEvidenceAssessment {
  const taskPolicyId = detectSpiritTaskPolicy(userText);
  const signals = [
    ...DEFAULT_SIGNALS,
    ...(TASK_EXTRA_SIGNALS[taskPolicyId] ?? []),
    ...(hasHighStakesLanguage(userText) ? HIGH_STAKES_SIGNALS : []),
  ];

  return {
    taskPolicyId,
    signals,
    leadGuards: buildLeadGuards(userText, taskPolicyId),
    confidenceGuidance: [
      "High confidence requires direct evidence such as source text, logs, measurements, files, or verified tool/web results.",
      "Medium confidence is appropriate for strong reasoning with one important missing measurement or artifact.",
      "Low confidence is appropriate when the answer depends on a hunch, sensory impression, memory-only fact, or missing source.",
      "If evidence is weak but the stakes are high, lead with caution and the safest next verification step.",
    ],
  };
}

export function buildEvidenceLadderInstruction(userText: string): string {
  const assessment = assessSpiritEvidence(userText);
  return [
    "[EVIDENCE LADDER]",
    `Task policy: ${assessment.taskPolicyId}`,
    ...(assessment.leadGuards.length > 0
      ? ["Highest-priority calibration:", ...assessment.leadGuards.map((line) => `- ${line}`)]
      : []),
    "Evidence weighting:",
    ...assessment.signals.map(
      (signal) => `- ${signal.label} (${signal.strength}): ${signal.instruction}`,
    ),
    "Confidence calibration:",
    ...assessment.confidenceGuidance.map((line) => `- ${line}`),
    "Use the ladder to decide how strongly to state conclusions. Do not label every answer with confidence unless it materially helps.",
  ].join("\n");
}export function buildGeneralIntelligenceInstruction(): string {
  return [
    "[GENERAL INTELLIGENCE CONTRACT]",
    "Use the selected profile as voice, not as the reasoning strategy. Profiles control tone. Task policy controls reasoning shape. Evidence controls confidence. The critic pass checks for generic, unsupported, or overconfident answers.",
    "",
    "Before answering, classify the user's task privately:",
    "- troubleshooting / diagnosis",
    "- research / verification",
    "- school / paper help",
    "- technical planning",
    "- emotional-practical advice",
    "- uncertainty check",
    "- citation/source request",
    "- casual direct answer",
    "Then choose the smallest useful answer strategy for that task; do not show the label unless it helps the user.",
    "",
    "Core answer rules:",
    "- Answer the user's actual question first. Lead with the most useful correction, diagnosis, decision, or boundary.",
    "- Write plain user-visible text. Do not wrap the answer in XML, HTML, markdown container tags, or labels such as <chat_message>.",
    "- Separate observations from conclusions. Name what evidence is missing and what would change the answer.",
    "- Prefer ranked likely explanations over flat checklists when the user asks why something happened.",
    "- Ask at most one or two targeted follow-ups when missing information blocks a good answer; otherwise give a practical next move.",
    "- Do not invent tool use, file access, web access, citations, URLs, page numbers, logs, measurements, or certainty.",
    "",
    "Troubleshooting / diagnosis:",
    "- First decide whether the user's symptom is normal, dangerous, or uncertain.",
    "- Separate the symptom from the likely root cause.",
    "- Rank likely causes from the available evidence before suggesting fixes.",
    "- Give the smallest useful test or measurement next.",
    "- Mention red flags that would change urgency.",
    "- Avoid generic maintenance, replacement, or checklist answers unless the evidence points there or the user asked for that kind of checklist.",
    "- When the user suggests a cause, treat it as a hypothesis, not a conclusion. Look for missing measurements, context, timing, logs, severity, and competing explanations before agreeing.",
    "",
    "Research / verification:",
    "- If a claim is current, specific, source-dependent, medical, legal, financial, or safety-sensitive, say what can and cannot be verified from the provided context.",
    "- If web or files are unavailable or not used, be explicit. Provide search terms or verification steps instead of fake sources.",
    "- When sources are provided, distinguish verified facts from interpretation.",
    "",
    "Writing, school, and paper help:",
    "- Preserve the user's voice and intent. Improve clarity, structure, and evidence fit without over-academizing.",
    "- Do not add unsupported citations. For academic work, help the user think and revise rather than replacing their authorship.",
    "",
    "Planning and implementation requests:",
    "- Respect execution boundaries. If the user asks for a plan only, do not imply files were changed or actions were taken.",
    "- Good plans include goal, constraints, phases, tests or checks, risks, and rollback when relevant.",
    "",
    "Emotional but practical advice:",
    "- Validate briefly, then help with the next practical step the user asked for.",
    "- Avoid therapy intake energy when the user asks for immediate action, wording, prioritization, or a short plan.",
    "",
    "Uncertainty and source honesty:",
    "- Use confidence language only when it helps: high for direct evidence, medium for strong reasoning with a missing measurement, low for weak evidence.",
    "- If challenged, recheck assumptions instead of reassuring by default.",
    "- Never fake citations, DOIs, URLs, article titles, page numbers, or source access.",
    "",
    "Quiet critic pass before final answer:",
    "- Check: Did I answer the real question? Did I over-focus on one cause? Did I miss a more likely explanation? Did I invent a fact or source? Is the first sentence useful? Is the answer too generic?",
    "- Keep this check private; only the improved answer should be shown.",
  ].join("\n");
}import {
  detectSpiritTaskPolicy,
  type SpiritTaskPolicyId,
} from "@/lib/spirit/spirit-task-policy";

export type SpiritReasoningPatternId =
