const POLICY_DETECTORS: Array<{
  id: SpiritTaskPolicyId;
  patterns: readonly RegExp[];
}> = [
  {
    id: "citation-source-request",
    patterns: [
      /\b(cite|citation|citations|source|sources|references|bibliography|doi|page number|page numbers)\b/i,
      /\bweb access\b/i,
    ],
  },
  {
    id: "uncertainty-check",
    patterns: [
      /\b(are you sure|am i wrong|might be wrong|could be wrong|double[- ]?check|recheck)\b/i,
      /\b(what would change|how confident|confidence)\b/i,
    ],
  },
  {
    id: "emotional-practical-advice",
    patterns: [
      /\b(overwhelmed|stressed|panicking|anxious|burned out|burnt out)\b/i,
      /\b(help me text|what should i text|without being mean|set a boundary|boundary text)\b/i,
      /\b(i don't need therapy|i need a way through|next \d+ hours)\b/i,
    ],
  },
  {
    id: "school-paper-help",
    patterns: [
      /\b(master'?s|discussion post|discussion board|paper|essay|thesis|APA|assignment|homework)\b/i,
      /\b(make it sound like me|improve this draft|revise my|peer response)\b/i,
    ],
  },
  {
    id: "technical-planning",
    patterns: [
      /\b(plan|roadmap|phases|migration|architecture|design doc|low-risk|rollback)\b/i,
      /\b(fix my app|build my app|implement|refactor|deploy|release)\b/i,
    ],
  },
  {
    id: "research-verification",
    patterns: [
      /\b(is it true|verify|fact[- ]?check|latest|current|today|recent|202[4-9]|study|studies|research)\b/i,
      /\b(peer[- ]?reviewed|evidence|claim|claims|data shows)\b/i,
    ],
  },
  {
    id: "troubleshooting-diagnosis",
    patterns: [
      /\b(crash|crashed|stall|stalled|broken|buggy|slow|error|failed|failure|not working|overheat|overheating)\b/i,
      /\b(high CPU|high memory|CPU is high|memory leak|fan|temperature|hot|warm|leak|noise|symptom)\b/i,
      /\b(is it|is this|could it be|does that mean).*\b(broken|failing|overheating|dead|bad|food poisoning|radiator|React)\b/i,
    ],
  },
];

export function getSpiritTaskPolicy(id: SpiritTaskPolicyId): SpiritTaskPolicy {
  return TASK_POLICIES[id];
}

export function detectSpiritTaskPolicy(userText: string): SpiritTaskPolicyId {
  const text = userText.trim();
  if (text.length === 0) return "casual-direct-answer";

  for (const detector of POLICY_DETECTORS) {
    if (detector.patterns.some((pattern) => pattern.test(text))) {
      return detector.id;
    }
  }

  return "casual-direct-answer";
}

export function buildActiveTaskPolicyInstruction(userText: string): string {
  const policy = getSpiritTaskPolicy(detectSpiritTaskPolicy(userText));
  return [
    "[ACTIVE TASK POLICY]",
    `Detected task policy: ${policy.label} (${policy.id})`,
    `Strategy: ${policy.summary}`,
    "If this detection is wrong, adapt to the user's actual request.",
    ...policy.instructions.map((instruction) => `- ${instruction}`),
  ].join("\n");
}import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

describe("spirit-trinity-chat.css thread rail (compact / no chunky grid hacks)", () => {
  const css = readFileSync(
    resolve(process.cwd(), "src/styles/spirit-trinity-chat.css"),
    "utf8",
  );

  it("does not force legacy 2.125rem action chrome on recent thread rows", () => {
    expect(css).not.toMatch(/2\.125rem/);
  });

  it("keeps a subtle active accent for trinity-recent rows", () => {
    expect(css).toMatch(/\[data-action-layout="trinity-recent"\]\[data-active="true"\]/);
    expect(css).toMatch(/inset 2px 0 0 rgba\(99, 216, 248/);
  });

  it("uses coarse-pointer media for larger touch targets where needed", () => {
    expect(css).toMatch(/@media \(pointer: coarse\)/);
  });
});/* ── Dashboard Demo v4 - isolated namespace (additive; no v2 reuse) ──────────
 * All classes prefixed `.dashboard-demo-v4-`. No html/body mutation.
 * Root/shell skip transform so nested panel glass still reads the atmosphere.
 * Theme switching rides the existing `html[data-theme="..."]` attribute set by
 * `useSpiritTheme`. Light palettes use pearl treatment; dark/hybrid palettes smoke.
 */

/* Drift animations for atmosphere blobs */
@keyframes ddv4-drift-a {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(15deg); }
  33%      { transform: translate3d(6%, 4%, 0) rotate(18deg); }
  66%      { transform: translate3d(3%, -3%, 0) rotate(12deg); }
}
@keyframes ddv4-drift-b {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(-12deg); }
  50%      { transform: translate3d(-8%, -4%, 0) rotate(-16deg); }
}
@keyframes ddv4-glow-breathe {
  0%, 100% { opacity: 0.22; transform: scale(1); }
  50%      { opacity: 0.38; transform: scale(1.06); }
}
@keyframes ddv4-pill-pulse {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in oklab, currentColor 55%, transparent); }
  60%      { box-shadow: 0 0 0 3px transparent; }
}

/* Category / status badges: whisper-thin glow (currentColor); keep it subliminal. */
@keyframes ddv4-badge-outer-glow {
  0%, 100% {
    box-shadow: var(--ddv4-badge-stack-base), 0 0 0 0 transparent;
  }
  50% {
    box-shadow: var(--ddv4-badge-stack-base), 0 0 15px 2px color-mix(in oklab, currentColor 24%, transparent);
  }
}
@keyframes ddv4-badge-sheen {
  to { transform: translateX(175%); }
}

/* Muted chrome pills — barely-there accent lift so it does not read as “LED billboard”. */
@keyframes ddv4-accent-pill-breathe {
  0%, 100% {
    border-color: var(--ddv4-pill-border);
    box-shadow: 0 0 0 0 transparent;
  }
  50% {
    border-color: color-mix(in oklab, var(--spirit-accent-strong, var(--ddv4-fg)) 14%, var(--ddv4-pill-border));
    box-shadow: 0 0 8px 1px color-mix(in oklab, var(--spirit-accent-strong, var(--ddv4-fg)) 7%, transparent);
  }
}

/* SMART row: hint of bloom only if you squint. */
@keyframes ddv4-smart-text-glow {
  0%, 100% { text-shadow: none; }
  50% {
    text-shadow: 0 0 5px color-mix(in oklab, currentColor 12%, transparent);
  }
}
@keyframes ddv4-oracle-viz-standby {
  0%, 100% {
    opacity: 0.64;
    transform: scaleY(0.58);
  }
  22% {
    opacity: 1;
    transform: scaleY(1.18);
  }
  46% {
    opacity: 0.82;
    transform: scaleY(0.78);
  }
  72% {
    opacity: 0.96;
    transform: scaleY(1.38);
  }
}
@keyframes ddv4-widget-float {
  0%, 100% {
    transform: translate3d(0, 0, 0);
  }
  50% {
    transform: translate3d(0, -9px, 0);
  }
}
@keyframes ddv4-widget-aura {
  0%, 100% {
    opacity: 0.72;
  }
  50% {
    opacity: 1;
  }
}

