## Provider result contract

Create a shared result shape.

```ts
export type WebSearchProvider =
  | "cache"
  | "searxng"
  | "ddgs"
  | "fetch"
  | "openai"
  | "manual";

export type WebSearchStatus =
  | "used"
  | "skipped"
  | "disabled"
  | "failed";

export type WebSearchSource = {
  title: string;
  url: string;
  snippet?: string;
  publishedAt?: string;
  provider?: WebSearchProvider;
};

export type WebSearchResult =
  | {
      ok: true;
      searched: true;
      provider: WebSearchProvider;
      sources: WebSearchSource[];
      answerPreview?: string;
      elapsedMs: number;
      providerTrace: WebSearchProviderTrace[];
    }
  | {
      ok: false;
      searched: boolean;
      provider: WebSearchProvider;
      error: string;
      detail?: string;
      elapsedMs: number;
      providerTrace: WebSearchProviderTrace[];
    };

export type WebSearchProviderTrace = {
  provider: WebSearchProvider;
  status: "skipped" | "attempted" | "used" | "failed";
  reason?: string;
  elapsedMs?: number;
  sourceCount?: number;
};
```

The trace matters because the UI and logs should show that Source tried cache, SearXNG, fetch, then stopped before paid fallback.

