    ).toBe("NVME");
    expect(
      normalizeWindowsPhysicalDiskType(
        ssdRow.PhysicalBusType,
        ssdRow.PhysicalMediaType,
        null,
      ),
    ).toBe("SSD");
    expect(
      normalizeWindowsPhysicalDiskType(
        hddRow.PhysicalBusType,
        hddRow.PhysicalMediaType,
        null,
      ),
    ).toBe("HDD");
    expect(
      normalizeWindowsPhysicalDiskType(
        unknownRow.PhysicalBusType,
        unknownRow.PhysicalMediaType,
        null,
      ),
    ).toBe("UNKNOWN");
  });
});#!/usr/bin/env bash
# ── Generate LAN/Tailscale-friendly TLS certs for Next dev (mkcert) ────────────────
# > Default `npm run dev:https` certs often include localhost only; remote browsers
# > hitting https://10.x need SANs on the cert (warnings OK after mkcert -install).
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
mkdir -p certificates

EXTRA_RAW="${SPIRIT_TLS_EXTRA_HOSTS:-}"
EXTRA_PARTS=()
if [[ -n "$EXTRA_RAW" ]]; then
  IFS=',' read -ra EXTRA_PARTS <<< "${EXTRA_RAW// /}"
fi

HOSTS=(localhost 127.0.0.1 ::1)
for part in "${EXTRA_PARTS[@]}"; do
  t="$(echo "$part" | xargs)"
  if [[ -n "$t" ]]; then
    HOSTS+=("$t")
  fi
done

if ! command -v mkcert >/dev/null 2>&1; then
  echo "mkcert not found. Install: https://github.com/FiloSottile/mkcert#installation" >&2
  exit 1
fi

mkcert -key-file certificates/spirit-dev-key.pem -cert-file certificates/spirit-dev.pem "${HOSTS[@]}"
echo "OK: certificates/spirit-dev.pem - SANs: ${HOSTS[*]}"
echo "Next: npm run dev:https:lan   (or export SPIRIT_TLS_EXTRA_HOSTS and re-run to add hosts)"from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from source_proxy.approval.gate import (
    SpendEstimationUnavailable,
    projected_spend_breakdown,
)
from source_proxy.decision.prompt_packet import PromptPacketInput, build_prompt_packet
from source_proxy.decision.recommendation import (
    ModelRecommendationInput,
    recommend_model,
)
from source_proxy.routing.litellm_router import route_model_for_alias, route_provider_for_alias


@dataclass(frozen=True)
class ApiVsManualPreviewInput:
    task: str
    api_model_alias: str = "openai"
    max_completion_tokens: int = 1024
    relevant_context: str | None = None
    context_tokens: int | None = None
    sensitive: bool = False
    needs_current_info: bool = False
    needs_codebase_context: bool = False
    wants_implementation: bool = False
    prefer_free: bool = True


def build_api_vs_manual_preview(input_data: ApiVsManualPreviewInput) -> dict[str, Any]:
    manual_model_recommendation = recommend_model(
        ModelRecommendationInput(
            task=input_data.task,
            context_tokens=input_data.context_tokens,
            sensitive=input_data.sensitive,
            needs_current_info=input_data.needs_current_info,
            needs_codebase_context=input_data.needs_codebase_context,
            wants_implementation=input_data.wants_implementation,
            prefer_free=input_data.prefer_free,
        )
    )
    prompt_packet = build_prompt_packet(
        PromptPacketInput(
            task=input_data.task,
            target_model_hint=manual_model_recommendation.primary_model,
            relevant_context=input_data.relevant_context,
            context_tokens=input_data.context_tokens,
            sensitive=input_data.sensitive,
            needs_current_info=input_data.needs_current_info,
            needs_codebase_context=input_data.needs_codebase_context,
            wants_implementation=input_data.wants_implementation,
            prefer_free=input_data.prefer_free,
        )
    )
    projected_api_cost = _project_api_cost(input_data)
    context_estimate = manual_model_recommendation.route_decision.context_estimate
    privacy_flags = _privacy_flags(input_data)
    api_model_option = {
        "model_alias": input_data.api_model_alias,
        "max_completion_tokens": input_data.max_completion_tokens,
        "enabled": projected_api_cost.get("available", False),
        "fail_closed": projected_api_cost.get("fail_closed", True),
    }
    default_choice = _default_choice(projected_api_cost, manual_model_recommendation.route_type)

    return {
        "preview_version": "2.7B-2",
        "execution_status": "paused_for_human_decision",
        "would_execute": False,
        "projected_api_cost": projected_api_cost,
        "context_tokens": context_estimate.total_estimated_tokens,
        "context_estimate": context_estimate.as_payload(),
        "manual_model_recommendation": manual_model_recommendation.as_payload(),
        "api_model_option": api_model_option,
        "privacy_flags": privacy_flags,
        "decision_summary": _decision_summary(
            projected_api_cost=projected_api_cost,
            context_tokens=context_estimate.total_estimated_tokens,
            manual_primary_model=manual_model_recommendation.primary_model,
            api_model_alias=input_data.api_model_alias,
            privacy_flags=privacy_flags,
            default_choice=default_choice,
        ),
        "manual_prompt_packet": prompt_packet.as_payload(),
        "required_human_decision": {
            "question": "Use paid API route, manual browser route, or local route?",
            "allowed_choices": ["api", "manual", "local", "cancel"],
            "default_choice": default_choice,
            "api_choice_requires_approval": True,
            "source_will_not_execute_until_choice_is_confirmed": True,
        },
    }


def _project_api_cost(input_data: ApiVsManualPreviewInput) -> dict[str, Any]:
    routed_model = route_model_for_alias(input_data.api_model_alias)
    provider = route_provider_for_alias(input_data.api_model_alias)
    if routed_model is None:
        return {
            "available": False,
            "model_alias": input_data.api_model_alias,
            "error": "API model alias is not enabled.",
            "fail_closed": True,
        }

    context = (input_data.relevant_context or "").strip()
    content = input_data.task if not context else f"{input_data.task}\n\n{context}"
    try:
        breakdown = projected_spend_breakdown(
            model_alias=input_data.api_model_alias,
            routed_model=routed_model,
            provider=provider,
            messages=[{"role": "user", "content": content}],
            max_completion_tokens=input_data.max_completion_tokens,
        )
    except SpendEstimationUnavailable as error:
        return {
            "available": False,
            "model_alias": input_data.api_model_alias,
            "error": str(error),
            "fail_closed": True,
        }

    payload = breakdown.as_payload()
    payload["available"] = True
    payload["fail_closed"] = False
    return payload


def _privacy_flags(input_data: ApiVsManualPreviewInput) -> list[str]:
    flags: list[str] = []
    lowered = f"{input_data.task}\n{input_data.relevant_context or ''}".lower()
    if input_data.sensitive:
        flags.append("user_marked_sensitive")
    if any(token in lowered for token in ["secret", "password", "api_key", ".env", "token"]):
        flags.append("possible_secret_or_env_content")
    if input_data.needs_codebase_context:
        flags.append("codebase_context_requested")
    if not flags:
        flags.append("no_privacy_flags_detected")
    return flags


def _default_choice(projected_api_cost: dict[str, Any], manual_route_type: str) -> str:
    if manual_route_type == "manual_route":
        return "manual"
    if manual_route_type == "local_route":
        return "local"
    if projected_api_cost.get("available"):
        return "api"
    return "manual"


def _decision_summary(
    *,
    projected_api_cost: dict[str, Any],
    context_tokens: int,
    manual_primary_model: str,
    api_model_alias: str,
    privacy_flags: list[str],
    default_choice: str,
) -> dict[str, Any]:
    return {
        "recommended_default": default_choice,
        "manual_route": {
            "available": True,
            "primary_model": manual_primary_model,
            "requires_external_paste": True,
            "source_spend_usd": "$0.00000000",
        },
        "api_route": {
            "model_alias": api_model_alias,
            "available": projected_api_cost.get("available", False),
            "fail_closed": projected_api_cost.get("fail_closed", True),
            "projected_cost_usd": projected_api_cost.get("projected_cost_usd"),
            "requires_spend_approval": True,
        },
        "context": {
            "tokens": context_tokens,
            "size_class": _context_size_class(context_tokens),
        },
        "privacy": {
            "flags": privacy_flags,
            "has_flags": privacy_flags != ["no_privacy_flags_detected"],
        },
        "decision_copy": _decision_copy(
            default_choice=default_choice,
            projected_api_cost=projected_api_cost,
            manual_primary_model=manual_primary_model,
        ),
    }


def _context_size_class(context_tokens: int) -> str:
    if context_tokens >= 120_000:
        return "huge"
    if context_tokens >= 32_000:
        return "large"
    if context_tokens >= 8_000:
        return "medium"
    return "small"


def _decision_copy(
    *,
    default_choice: str,
    projected_api_cost: dict[str, Any],
    manual_primary_model: str,
) -> str:
    if default_choice == "manual":
        return (
            f"Manual browser route is recommended first using {manual_primary_model}; "
            "Source will not send a paid API request unless you explicitly choose API."
        )
    if default_choice == "local":
        return "Local route is recommended first; no paid API request will be sent."
    if projected_api_cost.get("available"):
        return (
            "API route is available, but Source is paused until you approve the "
            "spend-before-send preview."
        )
    return "API route is unavailable or fail-closed; manual route is the default."from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal

from source_proxy.decision.router import DecisionInput, RouteDecision, decide_route

TargetModelHint = Literal["chatgpt", "claude", "gemini", "google_ai_studio", "grok"]


@dataclass(frozen=True)
class PromptPacketInput:
    task: str
    target_model_hint: TargetModelHint | None = None
    relevant_context: str | None = None
    context_tokens: int | None = None
    sensitive: bool = False
    needs_current_info: bool = False
    needs_codebase_context: bool = False
    wants_implementation: bool = False
    prefer_free: bool = True


@dataclass(frozen=True)
class PromptPacket:
    target_model_hint: str
    task_summary: str
    relevant_context: str
    context_metadata: dict[str, object]
    constraints: list[str]
    requested_output: list[str]
    paste_back_instructions: str
    prompt_text: str
    route_decision: RouteDecision
    research_sources: list[dict[str, str]] = field(default_factory=list)

    def as_payload(self) -> dict[str, object]:
        return {
            "target_model_hint": self.target_model_hint,
            "task_summary": self.task_summary,
            "relevant_context": self.relevant_context,
            "context_metadata": self.context_metadata,
            "constraints": self.constraints,
            "requested_output": self.requested_output,
            "paste_back_instructions": self.paste_back_instructions,
            "prompt_text": self.prompt_text,
            "route_decision": self.route_decision.as_payload(),
            "research_sources": self.research_sources,
        }


def build_prompt_packet(input_data: PromptPacketInput) -> PromptPacket:
    decision_input = DecisionInput(
        task=input_data.task,
        context_tokens=input_data.context_tokens,
        sensitive=input_data.sensitive,
        needs_current_info=input_data.needs_current_info,
        needs_codebase_context=input_data.needs_codebase_context,
        wants_implementation=input_data.wants_implementation,
        prefer_free=input_data.prefer_free,
    )
    decision = decide_route(decision_input)
    target_model = input_data.target_model_hint or _default_model_for_decision(decision)
    task_summary = _summarize_task(input_data.task)
    relevant_context = _build_context_section(input_data)
    context_metadata = _context_metadata_for(input_data, relevant_context)
    constraints = _constraints_for(input_data, decision)
    requested_output = _requested_output_for(input_data, decision)
    paste_back_instructions = (
        "Paste the model answer back into Source. Source will summarize, compare, "
        "and convert the useful parts into a Codex-ready follow-up."
    )
    prompt_text = _render_prompt_text(
        target_model_hint=target_model,
        task_summary=task_summary,
        relevant_context=relevant_context,
        constraints=constraints,
        requested_output=requested_output,
        paste_back_instructions=paste_back_instructions,
    )

    return PromptPacket(
        target_model_hint=target_model,
        task_summary=task_summary,
        relevant_context=relevant_context,
        context_metadata=context_metadata,
        constraints=constraints,
        requested_output=requested_output,
        paste_back_instructions=paste_back_instructions,
        prompt_text=prompt_text,
        route_decision=decision,
    )


def _default_model_for_decision(decision: RouteDecision) -> str:
    if decision.task_classification == "codebase_analysis":
        return "claude"
    if decision.task_classification == "current_research":
        return "gemini"
    if decision.task_classification == "implementation":
        return "chatgpt"
    return "chatgpt"


def _summarize_task(task: str) -> str:
    normalized = " ".join(task.strip().split())
    if len(normalized) <= 240:
        return normalized
    return f"{normalized[:237].rstrip()}..."


def _build_context_section(input_data: PromptPacketInput) -> str:
    context = (input_data.relevant_context or "").strip()
    if context:
        return context

    if input_data.needs_codebase_context:
        return (
            "Use the repository context packet from Source if provided separately. "
            "If context is missing, ask for the specific files or compressed XML excerpt needed."
        )

    return "No additional repository context was supplied."


def _context_metadata_for(
    input_data: PromptPacketInput,
    relevant_context: str,
) -> dict[str, object]:
    context = (input_data.relevant_context or "").strip()
    if not context:
        mode = "none"
        included_paths: list[str] = []
        redaction_notes = ["No supplied context; prompt asks external model to request missing files."]
    elif _looks_like_path_listing(context):
        mode = "path_listing_only"
        included_paths = _extract_candidate_paths(context)
        redaction_notes = [
            "Only path/listing context was supplied; no file contents are implied.",
            *_secret_shape_notes(context),
        ]
    elif _looks_like_generated_bundle_reference(context):
        mode = "generated_bundle_reference"
        included_paths = _extract_candidate_paths(context)
        redaction_notes = [
            "Generated bundle reference supplied; metadata does not prove contents were read.",
            *_secret_shape_notes(context),
        ]
    else:
        mode = "supplied_excerpt"
        included_paths = _extract_candidate_paths(context)
        redaction_notes = [
            "User-supplied excerpt included as context.",
            *_secret_shape_notes(context),
        ]

    omitted_paths = _omitted_secret_shaped_paths(context)
    return {
        "context_inclusion_mode": mode,
        "included_paths": included_paths,
        "omitted_paths": omitted_paths,
        "redaction_notes": redaction_notes,
        "estimated_context_tokens": _estimate_tokens(relevant_context),
        "file_contents_claimed": mode == "supplied_excerpt",
    }


def _constraints_for(
    input_data: PromptPacketInput,
    decision: RouteDecision,
) -> list[str]:
    constraints = [
        "Do not invent file contents, test results, URLs, logs, or tool output.",
        "Separate facts from assumptions.",
        "Keep recommendations actionable and scoped to the task.",
    ]
    if input_data.sensitive or decision.risk_tier == "high":
        constraints.append("Treat secrets and private data as sensitive; do not echo credentials.")
    if input_data.needs_codebase_context:
        constraints.append("When referencing code, cite file paths and ask for missing files instead of guessing.")
    if input_data.wants_implementation:
        constraints.append("Prefer minimal, reviewable implementation steps over broad rewrites.")
    if input_data.needs_current_info:
        constraints.append("Use current browsing/research if available and cite sources.")
    return constraints


def _requested_output_for(
    input_data: PromptPacketInput,
    decision: RouteDecision,
) -> list[str]:
    if input_data.wants_implementation:
        return [
            "A concise implementation plan",
            "Specific files or modules likely involved",
            "Risks, edge cases, and tests to run",
            "A final Codex-ready instruction block",
        ]
    if decision.task_classification == "codebase_analysis":
        return [
            "Top findings ordered by importance",
            "Evidence or file-path references for each finding",
            "Open questions or missing context",
            "Recommended next action",
        ]
    return [
        "Direct answer",
        "Reasoning summary",
        "Caveats or assumptions",
        "Recommended next action",
    ]


def _render_prompt_text(
    *,
    target_model_hint: str,
    task_summary: str,
    relevant_context: str,
    constraints: list[str],
    requested_output: list[str],
    paste_back_instructions: str,
) -> str:
    constraints_text = "\n".join(f"- {item}" for item in constraints)
    output_text = "\n".join(f"- {item}" for item in requested_output)
    return f"""# Source Manual Prompt Packet

Target model hint: {target_model_hint}

## Task
{task_summary}

## Relevant Context
{relevant_context}

## Constraints
{constraints_text}

## Requested Output
{output_text}

## Paste Back
{paste_back_instructions}
"""


def _looks_like_path_listing(context: str) -> bool:
    lowered = context.lower()
    return any(
        marker in lowered
        for marker in [
            "path listing",
            "directory listing",
            "folder listing",
            "verified_context_roots",
            "available_read_only_sources",
        ]
    )


def _looks_like_generated_bundle_reference(context: str) -> bool:
    lowered = context.lower()
    return any(
        marker in lowered
        for marker in [
            "repomix-output.xml",
            "repomix-output.ast.xml",
            "generated_context_bundle",
            "<repository_context",
            "<source_context_bundle",
        ]
    )


def _extract_candidate_paths(context: str) -> list[str]:
    candidates: list[str] = []
    for raw_token in context.replace(",", "\n").splitlines():
        token = raw_token.strip().strip("-*`'\"")
        if ":" in token and not _looks_like_windows_path(token):
            token = token.rsplit(":", 1)[1].strip()
        if not token or _is_secret_shaped_path(token):
            continue
        if _looks_like_path_token(token):
            candidates.append(token)
    return list(dict.fromkeys(candidates))[:50]


def _omitted_secret_shaped_paths(context: str) -> list[str]:
    omitted: list[str] = []
    for raw_token in context.replace(",", "\n").splitlines():
        token = raw_token.strip().strip("-*`'\"")
        if ":" in token and not _looks_like_windows_path(token):
            token = token.rsplit(":", 1)[1].strip()
        if token and _is_secret_shaped_path(token) and _looks_like_path_token(token):
            omitted.append(token)
    return list(dict.fromkeys(omitted))[:50]


def _secret_shape_notes(context: str) -> list[str]:
    if _omitted_secret_shaped_paths(context):
        return ["Secret-shaped paths were omitted from included_paths metadata."]
    return ["No secret-shaped path names detected in supplied context metadata."]


def _looks_like_path_token(value: str) -> bool:
    return (
        "/" in value
        or "\\" in value
        or value.endswith((".ts", ".tsx", ".py", ".js", ".jsx", ".json", ".md", ".xml"))
    )


def _looks_like_windows_path(value: str) -> bool:
    return len(value) >= 3 and value[1:3] == ":\\"


def _is_secret_shaped_path(value: str) -> bool:
    lowered = value.lower()
    return any(
        marker in lowered
        for marker in [
            ".env",
            ".pem",
            ".key",
            "secret",
            "token",
            "credential",
            "id_rsa",
            "id_ed25519",
        ]
    )


def _estimate_tokens(value: str) -> int:
    return max(1, round(len(value) / 4)) if value else 0from fastapi import FastAPI

