    onVoiceSpeedChange: noop,
    onToggleAutoSpeak: noop,
    onRequestVoiceCatalog: noop,
    onElevenLabsVoiceChange: noop,
    transportBusy: false,
    ...over,
  };
  return render(<OracleVoiceControls {...props} />);
}

