import { useCallback, useEffect, useRef, useState } from "react";
import type { ClusterTelemetryResponse } from "@/lib/server/telemetry/types";

export type ClusterFetchState = "checking" | "loaded" | "error";

export type UseClusterTelemetryResult = {
  data: ClusterTelemetryResponse | null;
  state: ClusterFetchState;
  error: string | null;
  refetch: () => void;
};

export function useClusterTelemetry(pollMs = 15_000): UseClusterTelemetryResult {
  const [state, setState] = useState<ClusterFetchState>("checking");
  const [data, setData] = useState<ClusterTelemetryResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const refetchRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    let active = true;
    let ctrl = new AbortController();
    let reqId = 0;

    async function poll() {
      const id = ++reqId;
      try {
        const res = await fetch("/api/telemetry/cluster", {
          cache: "no-store",
          signal: ctrl.signal,
        });
        if (!active || id !== reqId) return;
        if (res.ok) {
          const json = (await res.json()) as ClusterTelemetryResponse;
          if (!active || id !== reqId) return;
          setData(json);
          setState("loaded");
          setError(null);
        } else {
          const msg = res.statusText?.trim()
            ? `${res.status} ${res.statusText}`
            : `HTTP ${res.status}`;
          if (active && id === reqId) {
            setState("error");
            setError(msg);
          }
        }
      } catch (e) {
        if (!active || id !== reqId) return;
        if (e instanceof DOMException && e.name === "AbortError") return;
        if (e instanceof Error && e.name === "AbortError") return;
        setState("error");
        setError(e instanceof Error ? e.message : "fetch failed");
      }
    }

    refetchRef.current = () => {
      if (!active) return;
      ctrl.abort();
      ctrl = new AbortController();
      void poll();
    };

    void poll();
    const pollTimer = setInterval(() => {
      ctrl.abort();
      ctrl = new AbortController();
      void poll();
    }, pollMs);

    return () => {
      active = false;
      refetchRef.current = null;
      clearInterval(pollTimer);
      ctrl.abort();
    };
  }, [pollMs]);

  const refetch = useCallback(() => {
    refetchRef.current?.();
  }, []);

  return { data, state, error, refetch };
}import { describe, expect, it } from "vitest";

import {
  buildFolderSidebarModel,
  buildMoveSelectModel,
  buildMoveTargetsForThread,
  isDuplicateFolderName,
  normalizeFolderName,
  sortFoldersByOrderThenUpdated,
  sortThreadsWithOrderFallback,
} from "@/lib/chat-folder-utils";
import type { ChatFolder, ChatThread } from "@/lib/chat-db.types";

function folder(p: Partial<ChatFolder> & Pick<ChatFolder, "id">): ChatFolder {
  return {
    name: "F",
    createdAt: 1,
    updatedAt: 1,
    order: 0,
    collapsed: false,
    ...p,
  };
}

function thread(p: Partial<ChatThread> & Pick<ChatThread, "id">): ChatThread {
  return {
    title: "T",
    createdAt: 1,
    updatedAt: 2,
    ...p,
  };
}

describe("chat-folder-utils", () => {
  it("normalizeFolderName trims and lowercases", () => {
    expect(normalizeFolderName("  Test  ")).toBe("test");
    expect(normalizeFolderName("")).toBe("");
  });

  it("isDuplicateFolderName is case-insensitive and ignores folder by id", () => {
    const folders = [folder({ id: "a", name: "Work" }), folder({ id: "b", name: "play" })];
    expect(isDuplicateFolderName("work", folders)).toBe(true);
    expect(isDuplicateFolderName("WORK ", folders)).toBe(true);
    expect(isDuplicateFolderName("work", folders, "a")).toBe(false);
    expect(isDuplicateFolderName("Work", folders, "a")).toBe(false);
    expect(isDuplicateFolderName("new", folders)).toBe(false);
    expect(isDuplicateFolderName("   ", folders)).toBe(false);
  });

  it("rename can keep the same name on the same folder (case-insensitive)", () => {
    const folders = [folder({ id: "a", name: "Work" }), folder({ id: "b", name: "play" })];
    expect(isDuplicateFolderName("WORK", folders, "a")).toBe(false);
  });

  it("sortFoldersByOrderThenUpdated orders by order then newer updatedAt", () => {
    const a = folder({ id: "a", order: 1, updatedAt: 100 });
    const b = folder({ id: "b", order: 1, updatedAt: 200 });
    const c = folder({ id: "c", order: 0, updatedAt: 50 });
    expect(sortFoldersByOrderThenUpdated([a, b, c]).map((f) => f.id)).toEqual([
      "c",
      "b",
      "a",
    ]);
  });

  it("sortThreadsWithOrderFallback prefers numeric order when any row has order", () => {
    const threads: ChatThread[] = [
      thread({ id: "a", order: 3000, updatedAt: 50 }),
      thread({ id: "b", order: 1000, updatedAt: 99 }),
    ];
    expect(sortThreadsWithOrderFallback(threads).map((t) => t.id)).toEqual([
      "b",
      "a",
    ]);
  });

  it("buildMoveSelectModel hides move when no folders exist", () => {
    const t = thread({ id: "x", folderId: null, updatedAt: 1 });
    const m = buildMoveSelectModel(t, []);
    expect(m.show).toBe(false);
  });

  it("buildMoveSelectModel includes Chats and folders with current value", () => {
    const folders = [
      folder({ id: "a", name: "Alpha", order: 0 }),
      folder({ id: "b", name: "Beta", order: 1 }),
    ];
    const t = thread({ id: "x", folderId: "b", updatedAt: 1 });
    const m = buildMoveSelectModel(t, folders);
    expect(m.show).toBe(true);
    expect(m.value).toBe("b");
    expect(m.options.map((o) => o.value)).toEqual(["__root__", "a", "b"]);
  });

  it("buildFolderSidebarModel buckets root vs folders and drops orphan folderIds to root", () => {
    const f1 = folder({ id: "f1", order: 0, name: "Work" });
    const threads: ChatThread[] = [
      thread({ id: "r1", folderId: null, updatedAt: 10 }),
      thread({ id: "in1", folderId: "f1", updatedAt: 5 }),
      thread({ id: "orphan", folderId: "missing", updatedAt: 99 }),
    ];
    const { rootThreads, folderSections } = buildFolderSidebarModel(threads, [
      f1,
    ]);
    expect(rootThreads.map((t) => t.id)).toEqual(["orphan", "r1"]);
    expect(folderSections).toHaveLength(1);
    expect(folderSections[0]!.threads.map((t) => t.id)).toEqual(["in1"]);
  });

  it("buildFolderSidebarModel orders filed threads by order when set", () => {
    const f1 = folder({ id: "f1", order: 0, name: "Work" });
    const threads: ChatThread[] = [
      thread({ id: "t2", folderId: "f1", order: 2000, updatedAt: 1 }),
      thread({ id: "t1", folderId: "f1", order: 1000, updatedAt: 99 }),
    ];
    const { folderSections } = buildFolderSidebarModel(threads, [f1]);
    expect(folderSections[0]!.threads.map((t) => t.id)).toEqual(["t1", "t2"]);
  });

  it("buildMoveTargetsForThread lists sibling folders and root when filed", () => {
    const folders = [
      folder({ id: "a", name: "Alpha", order: 0 }),
      folder({ id: "b", name: "Beta", order: 1 }),
    ];
    const t = thread({ id: "x", folderId: "a", updatedAt: 1 });
    const targets = buildMoveTargetsForThread(t, folders);
    expect(targets).toEqual([
      { folderId: null, label: "Chats" },
      { folderId: "b", label: "Beta" },
    ]);
  });

  it("buildMoveTargetsForThread at root only lists folders", () => {
    const folders = [folder({ id: "a", name: "Alpha", order: 0 })];
    const t = thread({ id: "x", folderId: null, updatedAt: 1 });
    expect(buildMoveTargetsForThread(t, folders)).toEqual([
      { folderId: "a", label: "Alpha" },
    ]);
  });
});import { describe, expect, it } from "vitest";

import { DEFAULT_SCROLL_NEAR_BOTTOM_PX, isNearBottom } from "@/lib/chat-scroll";

function mockScrollEl(opts: {
  scrollHeight: number;
  scrollTop: number;
  clientHeight: number;
}): HTMLElement {
  const el = document.createElement("div");
  Object.defineProperties(el, {
    scrollHeight: { value: opts.scrollHeight, configurable: true },
    scrollTop: { value: opts.scrollTop, configurable: true },
    clientHeight: { value: opts.clientHeight, configurable: true },
  });
  return el;
}

describe("isNearBottom", () => {
  it("is true when gap to bottom is under threshold", () => {
    const el = mockScrollEl({ scrollHeight: 1000, scrollTop: 850, clientHeight: 100 });
    expect(isNearBottom(el, DEFAULT_SCROLL_NEAR_BOTTOM_PX)).toBe(true);
  });

  it("is false when user scrolled far from bottom", () => {
    const el = mockScrollEl({ scrollHeight: 1000, scrollTop: 0, clientHeight: 200 });
    expect(isNearBottom(el, DEFAULT_SCROLL_NEAR_BOTTOM_PX)).toBe(false);
  });

  it("treats missing scroll container as near-bottom (stickiness safe)", () => {
    expect(isNearBottom(null)).toBe(true);
    expect(isNearBottom(undefined)).toBe(true);
  });

  it("respects custom threshold", () => {
    const el = mockScrollEl({ scrollHeight: 500, scrollTop: 350, clientHeight: 100 });
    expect(isNearBottom(el, 60)).toBe(true);
    expect(isNearBottom(el, 40)).toBe(false);
  });
});import { describe, expect, it, vi } from "vitest";

import { copyTextToClipboard } from "@/lib/clipboard";

describe("copyTextToClipboard", () => {
  it("uses clipboard API when available", async () => {
    const writeText = vi.fn().mockResolvedValue(undefined);
    Object.assign(navigator, { clipboard: { writeText } });
    const r = await copyTextToClipboard("hello");
    expect(r).toEqual({ ok: true });
    expect(writeText).toHaveBeenCalledWith("hello");
  });

  it("does not throw when clipboard API is missing", async () => {
    const prev = navigator.clipboard;
    Object.defineProperty(navigator, "clipboard", { value: undefined, configurable: true });
    const r = await copyTextToClipboard("hello");
    expect(r.ok).toBe(false);
    Object.defineProperty(navigator, "clipboard", { value: prev, configurable: true });
  });
});import { describe, expect, it, vi } from "vitest";

import {
  planAssistantOutboundFinish,
  runAutoSpeakAssistantFinish,
  shouldStopTtsOnOutboundSubmit,
} from "@/lib/spirit-chat-tts";

describe("planAssistantOutboundFinish", () => {
  it("commits when thread matches and body non-empty", () => {
    expect(
      planAssistantOutboundFinish({
        threadId: "t1",
        body: "hello",
        activeThreadId: "t1",
        draftLaneActive: false,
      }),
    ).toEqual({ kind: "commit" });
  });

  it("skips with keepOutcomeRef when thread id missing", () => {
    expect(
      planAssistantOutboundFinish({
        threadId: null,
        body: "hello",
        activeThreadId: "t1",
        draftLaneActive: false,
      }),
    ).toMatchObject({ kind: "skip", reason: "no-outcome-thread", keepOutcomeRef: true });
  });

  it("skips empty assistant text but keeps outcome ref", () => {
    expect(
      planAssistantOutboundFinish({
        threadId: "t1",
        body: "   ",
        activeThreadId: "t1",
        draftLaneActive: false,
      }),
    ).toMatchObject({ kind: "skip", reason: "empty-assistant-text", keepOutcomeRef: true });
  });

  it("skips wrong thread when not draft lane", () => {
    expect(
      planAssistantOutboundFinish({
        threadId: "t-old",
        body: "done",
        activeThreadId: "t-new",
        draftLaneActive: false,
      }),
    ).toMatchObject({ kind: "skip", reason: "wrong-thread", keepOutcomeRef: true });
  });

  it("does not reject wrong thread when draft lane is active", () => {
    expect(
      planAssistantOutboundFinish({
        threadId: "t-old",
        body: "done",
        activeThreadId: "t-new",
        draftLaneActive: true,
      }),
    ).toEqual({ kind: "commit" });
  });
});

describe("shouldStopTtsOnOutboundSubmit", () => {
