describe("Phase 8 eval: file edit honesty", () => {
  let tmpRoot: string;

  beforeEach(() => {
    tmpRoot = mkdtempSync(path.join(os.tmpdir(), "spirit-honesty-fe-"));
    vi.stubEnv("SPIRIT_PROJECT_PATH", tmpRoot);
    clearAllFileEditProposalsForTests();
  });

  afterEach(() => {
    rmSync(tmpRoot, { recursive: true, force: true });
    clearAllFileEditProposalsForTests();
  });

  it("file editing disabled returns FILE_EDIT_DISABLED without writing", async () => {
    vi.stubEnv("SPIRIT_ENABLE_FILE_EDIT_TOOLS", "false");
    writeFileSync(path.join(tmpRoot, "z.txt"), "a", "utf8");
    const r = await proposeFileEdit({ filePath: "z.txt", nextContent: "b" });
    expect(r.ok === false && r.code === "FILE_EDIT_DISABLED").toBe(true);
    const { readFileSync } = await import("fs");
    expect(readFileSync(path.join(tmpRoot, "z.txt"), "utf8")).toBe("a");
  });

  it("propose does not mutate disk until apply with confirm", async () => {
    vi.stubEnv("SPIRIT_ENABLE_FILE_EDIT_TOOLS", "true");
    writeFileSync(path.join(tmpRoot, "p.txt"), "old\n", "utf8");
    const p = await proposeFileEdit({ filePath: "p.txt", nextContent: "new\n" });
    expect(p.ok).toBe(true);
    if (!p.ok) throw new Error("propose");
    const { readFileSync } = await import("fs");
    expect(readFileSync(path.join(tmpRoot, "p.txt"), "utf8")).toBe("old\n");
  });
});

describe("Phase 8 eval: activity honesty", () => {
  it("metadata cards never embed absolute workspace root in JSON", () => {
    const secretRoot = "/this/should/not/appear/in/cards";
    const card = createSpiritToolActivityCard({
      kind: "workspace_list",
      label: "List workspace files",
      status: "completed",
      target: "src",
      summary: "ok",
    });
    const json = JSON.stringify([card]);
    expect(json).not.toContain(secretRoot);
    expect(json).not.toMatch(/\/home\/[^\s"]+\/SpiritOS/);
  });

  it("mergeSpiritToolActivityCardsForMessage preserves blocked semantics from metadata", () => {
    const msg = {
      id: "m",
      role: "assistant" as const,
      metadata: {
        spiritToolActivity: [
          createSpiritToolActivityCard({
            kind: "tool_unavailable",
            label: "Dev command",
            status: "failed",
            target: "npm_lint",
            safeMessage: "Script missing",
          }),
        ],
      },
      parts: [{ type: "text" as const, text: "x" }],
    } satisfies UIMessage;
    const cards = mergeSpiritToolActivityCardsForMessage(msg);
    expect(cards[0]?.safeMessage).toBe("Script missing");
    expect(JSON.stringify(cards)).not.toMatch(/at \w+ \(/);
  });
});import { describe, expect, it } from "vitest";

import {
  isConcreteWorkspaceReadRequest,
  pathFragmentLooksConcrete,
} from "../concrete-workspace-read-request";

describe("isConcreteWorkspaceReadRequest", () => {
  it("returns true for list/show/read/tail with concrete paths", () => {
    expect(isConcreteWorkspaceReadRequest("List the files in src/lib/spirit")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("show files in src/app")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("whats in src/lib?")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("what's in src/lib/spirit folder?")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("what files are in src?")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("show me what is inside src/lib")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("whats in my c/projects folder?")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("list directory src/lib")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("read package.json")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("open src/lib/spirit/model-runtime.ts")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("show contents of src/lib/spirit/system-state.ts")).toBe(
      true,
    );
    expect(isConcreteWorkspaceReadRequest("tail nohup.out")).toBe(true);
    expect(isConcreteWorkspaceReadRequest("show last 50 lines of app.log")).toBe(true);
  });

  it("returns false for vague capability questions", () => {
    expect(isConcreteWorkspaceReadRequest("Can you browse files?")).toBe(false);
    expect(isConcreteWorkspaceReadRequest("Do you have file access?")).toBe(false);
    expect(isConcreteWorkspaceReadRequest("Can you read my files?")).toBe(false);
    expect(isConcreteWorkspaceReadRequest("Can you edit files?")).toBe(false);
    expect(isConcreteWorkspaceReadRequest("What tools do you have?")).toBe(false);
    expect(isConcreteWorkspaceReadRequest("Can you control my desktop?")).toBe(false);
    expect(isConcreteWorkspaceReadRequest("Can you run commands?")).toBe(false);
  });

  it("returns false for command / package-manager asks", () => {
    expect(isConcreteWorkspaceReadRequest("Run npm test")).toBe(false);
    expect(isConcreteWorkspaceReadRequest("npm install lodash")).toBe(false);
  });

  it("treats read .env.local as concrete (tool layer blocks unsafe paths)", () => {
    expect(isConcreteWorkspaceReadRequest("Read .env.local")).toBe(true);
  });
});

describe("pathFragmentLooksConcrete", () => {
  it("rejects vague fragments", () => {
    expect(pathFragmentLooksConcrete("my")).toBe(false);
    expect(pathFragmentLooksConcrete("files")).toBe(false);
  });
