import { isOllamaModelToolUnsupportedError } from "../ollama-tool-unsupported-error";

describe("isOllamaModelToolUnsupportedError", () => {
  it("returns true for Ollama does-not-support-tools APICallError", () => {
    const err = new APICallError({
      message: "registry.ollama.ai/library/hermes4:latest does not support tools",
      url: "http://100.111.32.31:11434/v1/chat/completions",
      requestBodyValues: {},
      statusCode: 400,
      responseBody:
        '{"error":{"message":"registry.ollama.ai/library/hermes4:latest does not support tools"}}',
    });
    expect(isOllamaModelToolUnsupportedError(err)).toBe(true);
  });

  it("returns true when only responseBody mentions unsupported tools", () => {
    const err = new APICallError({
      message: "Bad Request",
      url: "http://localhost/v1/chat/completions",
      requestBodyValues: {},
      statusCode: 400,
      responseBody: '{"error":{"message":"model does not support tools"}}',
    });
    expect(isOllamaModelToolUnsupportedError(err)).toBe(true);
  });

  it("returns false for unrelated errors", () => {
    expect(isOllamaModelToolUnsupportedError(new Error("network"))).toBe(false);
    const err = new APICallError({
      message: "rate limited",
      url: "http://localhost/v1/chat/completions",
      requestBodyValues: {},
      statusCode: 429,
    });
    expect(isOllamaModelToolUnsupportedError(err)).toBe(false);
  });
});import { describe, expect, it } from "vitest";

import {
  addResearchPlanStep,
  draftResearchPlanFromPrompt,
  editResearchPlanStep,
  removeResearchPlanStep,
  researchPlanToSummary,
} from "@/lib/spirit/research-plan";

describe("research-plan", () => {
  it("draftResearchPlanFromPrompt seeds default steps", () => {
    const p = draftResearchPlanFromPrompt("What about sleep?");
    expect(p.steps.length).toBeGreaterThanOrEqual(4);
    expect(p.originalQuestion).toContain("sleep");
    expect(p.steps[0]?.status).toBe("pending");
  });

  it("editResearchPlanStep updates a step", () => {
    let p = draftResearchPlanFromPrompt("q");
    p = editResearchPlanStep(p, p.steps[0]!.id, { label: "Renamed", detail: "d" });
    expect(p.steps[0]?.label).toBe("Renamed");
    expect(p.steps[0]?.detail).toBe("d");
  });

  it("addResearchPlanStep and removeResearchPlanStep", () => {
    let p = draftResearchPlanFromPrompt("q");
    const n = p.steps.length;
    p = addResearchPlanStep(p, "Extra");
    expect(p.steps).toHaveLength(n + 1);
    const lastId = p.steps[p.steps.length - 1]!.id;
    p = removeResearchPlanStep(p, lastId);
    expect(p.steps).toHaveLength(n);
  });

  it("researchPlanToSummary is non-CoT checklist text", () => {
    const p = draftResearchPlanFromPrompt("test");
    const s = researchPlanToSummary(p);
    expect(s).toContain("User-approved research plan");
    expect(s.toLowerCase()).not.toContain("chain of thought");
  });
});import { describe, expect, it } from "vitest";

import {
  buildResearchSourcePolicy,
  hasUsableResearchSources,
  stripFakeCitationsWhenNoSources,
  userRequestedFreshExternalSources,
} from "@/lib/spirit/research-source-enforcement";

describe("research-source-enforcement", () => {
  it("hasUsableResearchSources requires http(s) URLs", () => {
    expect(hasUsableResearchSources([{ url: "https://a.edu/x" }])).toBe(true);
    expect(hasUsableResearchSources([{ url: "" }, { url: "not-a-url" }])).toBe(false);
  });

  it("hasUsableResearchSources treats bare hosts as verified after normalize", () => {
    expect(hasUsableResearchSources([{ url: "www.example.com/abc" }])).toBe(true);
  });

  it("buildResearchSourcePolicy teacher mode mandates links in Study aids when URLs exist", () => {
    const p = buildResearchSourcePolicy({
      searchStatus: "used",
      sources: [{ url: "https://example.com/a" }, { url: "https://example.org/b" }],
      requestedFreshSources: false,
      modelProfileId: "teacher",
    });
    expect(p).toContain("Study aids");
    expect(p).toContain("markdown bullet");
    expect(p).not.toContain("End with **## Sources**");
  });

  it("buildResearchSourcePolicy forbids citations when no URLs", () => {
    const p = buildResearchSourcePolicy({
      searchStatus: "skipped",
      sources: [],
      requestedFreshSources: false,
    });
    expect(p).toContain("Search used: no");
    expect(p).toContain("Do **not** include numbered citations");
  });

  it("stripFakeCitationsWhenNoSources removes Cochrane cosplay tail", () => {
    const t = `Search used: no (user_disabled_web_search)

## Executive Summary
Blah

## Sources
[1] Cochrane review
[2] PLOS One
[3] JADD`;
    const out = stripFakeCitationsWhenNoSources(t);
    expect(out).not.toContain("## Sources");
    expect(out).not.toMatch(/\[1\]/);
  });

  it("userRequestedFreshExternalSources detects 2024+ proof asks", () => {
    expect(
      userRequestedFreshExternalSources("Give me 2025 peer-reviewed sources on autism interventions"),
    ).toBe(true);
    expect(userRequestedFreshExternalSources("What is gravity")).toBe(false);
  });
});import { describe, expect, it } from "vitest";

