});import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "fs";
import os from "os";
import path from "path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import {
  FILE_EDIT_MAX_NEXT_BYTES,
  applyConfirmedFileEdit,
  clearAllFileEditProposalsForTests,
  getFileEditProposalForTest,
  proposeFileEdit,
  setFileEditProposalExpiryForTest,
} from "../file-edit-tools";
import { resolveSafeWorkspacePath } from "../tool-safety";

describe("file-edit-tools", () => {
  let tmpRoot: string;

  beforeEach(() => {
    tmpRoot = mkdtempSync(path.join(os.tmpdir(), "spirit-fe-"));
    vi.stubEnv("SPIRIT_PROJECT_PATH", tmpRoot);
    vi.stubEnv("SPIRIT_ENABLE_FILE_EDIT_TOOLS", "true");
    clearAllFileEditProposalsForTests();
  });

  afterEach(() => {
    vi.unstubAllEnvs();
    clearAllFileEditProposalsForTests();
    rmSync(tmpRoot, { recursive: true, force: true });
  });

  it("returns FILE_EDIT_DISABLED when SPIRIT_ENABLE_FILE_EDIT_TOOLS is false", async () => {
    vi.stubEnv("SPIRIT_ENABLE_FILE_EDIT_TOOLS", "false");
    writeFileSync(path.join(tmpRoot, "a.txt"), "hi", "utf8");
    const r = await proposeFileEdit({ filePath: "a.txt", nextContent: "bye" });
    expect(r.ok === false && r.code === "FILE_EDIT_DISABLED").toBe(true);
  });

  it("proposeFileEdit creates proposal and diff without writing", async () => {
    writeFileSync(path.join(tmpRoot, "edit-me.txt"), "alpha\n", "utf8");
    const r = await proposeFileEdit({
      filePath: "edit-me.txt",
      nextContent: "beta\n",
    });
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error("expected ok");
    expect(readFileSync(path.join(tmpRoot, "edit-me.txt"), "utf8")).toBe("alpha\n");
    expect(getFileEditProposalForTest(r.proposalId)).toBeDefined();
    expect(r.diff).toContain("--- edit-me.txt");
  });

  it("proposeFileEdit rejects .env.local", async () => {
    writeFileSync(path.join(tmpRoot, ".env.local"), "x", "utf8");
    const r = await proposeFileEdit({ filePath: ".env.local", nextContent: "y" });
    expect(r.ok === false && r.code === "BLOCKED_FILE_PATTERN").toBe(true);
  });

  it("proposeFileEdit rejects path traversal", async () => {
    const r = await proposeFileEdit({ filePath: "../outside.txt", nextContent: "x" });
    expect(r.ok === false && r.code === "PATH_TRAVERSAL").toBe(true);
  });

  it("proposeFileEdit rejects node_modules segment", async () => {
    const r = await proposeFileEdit({
      filePath: "node_modules/foo/package.json",
      nextContent: "{}",
    });
    expect(r.ok === false && r.code === "BLOCKED_SEGMENT").toBe(true);
  });

  it("proposeFileEdit rejects oversized nextContent", async () => {
    writeFileSync(path.join(tmpRoot, "small.txt"), "a", "utf8");
    const huge = "x".repeat(FILE_EDIT_MAX_NEXT_BYTES + 1);
    const r = await proposeFileEdit({ filePath: "small.txt", nextContent: huge });
    expect(r.ok === false && r.code === "NEXT_TOO_LARGE").toBe(true);
  });

  it("applyConfirmedFileEdit rejects missing proposal", async () => {
    const r = await applyConfirmedFileEdit({
      proposalId: "00000000-0000-4000-8000-000000000000",
      confirm: true,
    });
    expect(r.ok === false && r.code === "PROPOSAL_NOT_FOUND").toBe(true);
  });

  it("applyConfirmedFileEdit rejects expired proposal", async () => {
    writeFileSync(path.join(tmpRoot, "e.txt"), "old\n", "utf8");
    const p = await proposeFileEdit({ filePath: "e.txt", nextContent: "new\n" });
    expect(p.ok).toBe(true);
    if (!p.ok) throw new Error("propose");
    setFileEditProposalExpiryForTest(p.proposalId, Date.now() - 1000);
    const r = await applyConfirmedFileEdit({ proposalId: p.proposalId, confirm: true });
    expect(r.ok === false && r.code === "PROPOSAL_EXPIRED").toBe(true);
  });

  it("applyConfirmedFileEdit rejects confirm false", async () => {
    writeFileSync(path.join(tmpRoot, "c.txt"), "x", "utf8");
    const p = await proposeFileEdit({ filePath: "c.txt", nextContent: "y" });
    expect(p.ok).toBe(true);
    if (!p.ok) throw new Error("propose");
    const r = await applyConfirmedFileEdit({ proposalId: p.proposalId, confirm: false });
    expect(r.ok === false && r.code === "CONFIRMATION_REQUIRED").toBe(true);
  });

  it("applyConfirmedFileEdit writes when confirmed and creates backup", async () => {
    writeFileSync(path.join(tmpRoot, "w.txt"), "before\n", "utf8");
    const p = await proposeFileEdit({ filePath: "w.txt", nextContent: "after\n" });
    expect(p.ok).toBe(true);
    if (!p.ok) throw new Error("propose");
    const r = await applyConfirmedFileEdit({ proposalId: p.proposalId, confirm: true });
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error("apply");
    expect(readFileSync(path.join(tmpRoot, "w.txt"), "utf8")).toBe("after\n");
    expect(r.backupRelativePath.startsWith(".spirit-backups/")).toBe(true);
    expect(r.backupRelativePath.endsWith(".bak")).toBe(true);
    const backupAbs = resolveSafeWorkspacePath(r.backupRelativePath);
    expect(readFileSync(backupAbs, "utf8")).toBe("before\n");
  });

  it("applyConfirmedFileEdit rejects when file changed since proposal", async () => {
    writeFileSync(path.join(tmpRoot, "race.txt"), "v1\n", "utf8");
    const p = await proposeFileEdit({ filePath: "race.txt", nextContent: "v2\n" });
    expect(p.ok).toBe(true);
    if (!p.ok) throw new Error("propose");
    writeFileSync(path.join(tmpRoot, "race.txt"), "tampered\n", "utf8");
    const r = await applyConfirmedFileEdit({ proposalId: p.proposalId, confirm: true });
    expect(r.ok === false && r.code === "CONFLICT").toBe(true);
  });

  it("apply output does not expose raw workspace root path", async () => {
    writeFileSync(path.join(tmpRoot, "root-check.txt"), "a", "utf8");
    const p = await proposeFileEdit({ filePath: "root-check.txt", nextContent: "b" });
    expect(p.ok).toBe(true);
    if (!p.ok) throw new Error("propose");
    const r = await applyConfirmedFileEdit({ proposalId: p.proposalId, confirm: true });
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error("apply");
    expect(JSON.stringify(r)).not.toContain(tmpRoot);
  });
});import { mkdtempSync, rmSync, writeFileSync } from "fs";
import { tmpdir } from "os";
import path from "path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import {
  SpiritToolPathError,
  TOOL_MAX_OUTPUT_CHARS,
  createToolError,
  normalizeWorkspaceRelativePath,
  resolveSafeWorkspacePath,
  toolErrorFromUnknown,
  truncateToolOutput,
} from "../tool-safety";

describe("tool-safety", () => {
  let fixture: string;

  beforeEach(() => {
    fixture = mkdtempSync(path.join(tmpdir(), "spirit-safe-"));
    vi.stubEnv("SPIRIT_PROJECT_PATH", fixture);
  });

  afterEach(() => {
    rmSync(fixture, { recursive: true, force: true });
    vi.unstubAllEnvs();
  });

  it("rejects absolute paths", () => {
    expect(() => normalizeWorkspaceRelativePath("/etc/passwd")).toThrow(SpiritToolPathError);
    expect(() => normalizeWorkspaceRelativePath("C:/Projects")).toThrow(SpiritToolPathError);
  });

  it("rejects ../ traversal", () => {
    expect(() => normalizeWorkspaceRelativePath("foo/../../secret")).toThrow(SpiritToolPathError);
  });

  it("rejects .env and .env.local", () => {
    expect(() => normalizeWorkspaceRelativePath(".env")).toThrow(SpiritToolPathError);
    expect(() => normalizeWorkspaceRelativePath(".env.local")).toThrow(SpiritToolPathError);
  });

  it("rejects node_modules segment", () => {
    expect(() => normalizeWorkspaceRelativePath("node_modules/foo")).toThrow(SpiritToolPathError);
  });

  it("rejects .git segment", () => {
    expect(() => normalizeWorkspaceRelativePath(".git/config")).toThrow(SpiritToolPathError);
  });

  it("rejects key/private style basenames", () => {
    expect(() => normalizeWorkspaceRelativePath("secrets.yaml")).toThrow(SpiritToolPathError);
    expect(() => normalizeWorkspaceRelativePath("id_rsa")).toThrow(SpiritToolPathError);
    expect(() => normalizeWorkspaceRelativePath("cert.pem")).toThrow(SpiritToolPathError);
  });

  it("allows normal relative file paths", () => {
    writeFileSync(path.join(fixture, "readme.md"), "hi");
    const resolved = resolveSafeWorkspacePath("readme.md");
    expect(resolved).toBe(path.join(fixture, "readme.md"));
  });

  it("truncates long output", () => {
    const long = "x".repeat(TOOL_MAX_OUTPUT_CHARS + 50);
    const out = truncateToolOutput(long, TOOL_MAX_OUTPUT_CHARS);
    expect(out.truncated).toBe(true);
    expect(out.text.length).toBeLessThanOrEqual(TOOL_MAX_OUTPUT_CHARS + 40);
  });

  it("safe error shape does not expose stack traces", () => {
    const errObj = createToolError("X", "bad");
    const wrapped = toolErrorFromUnknown(new Error("nope"));
    expect(JSON.stringify(errObj)).not.toMatch(/\bat\b/);
    expect(JSON.stringify(wrapped)).not.toMatch(/\bat\b/);
    expect(JSON.stringify(wrapped)).not.toContain("nope");
  });
});// ── child-process-spawn - test-mockable spawn facade (shell always false at call site) ─
import "server-only";

import { spawn as nodeSpawn, type SpawnOptionsWithoutStdio } from "child_process";

/** Spawn without shell; isolated so Vitest can mock this module. */
export function spawnNoShell(
  command: string,
  args: readonly string[],
  options: SpawnOptionsWithoutStdio,
): ReturnType<typeof nodeSpawn> {
  return nodeSpawn(command, [...args], { ...options, shell: false });
}// ── dev-command-tools - allowlisted spawn-only dev commands, workspace cwd ─
// > No shell, no user strings, no exec(). Phase 6.

import "server-only";

import { spawnNoShell } from "@/lib/spirit/tools/child-process-spawn";
import { readFileSync } from "fs";
import path from "path";

import { getWorkspaceRoot, TOOL_MAX_OUTPUT_CHARS, truncateToolOutput } from "@/lib/spirit/tools/tool-safety";

export type DevCommandId =
  | "git_status"
  | "git_diff"
  | "npm_typecheck"
  | "npm_test"
  | "npm_lint"
  | "npm_build";

export type RunDevCommandInput = {
  commandId: DevCommandId;
  confirm?: boolean;
};

export type DevCommandResult = {
  ok: boolean;
  commandId: DevCommandId;
  label: string;
  exitCode?: number | null;
  stdout?: string;
  stderr?: string;
  output?: string;
  timedOut?: boolean;
  durationMs?: number;
  requiresConfirmation?: boolean;
  message?: string;
  error?: {
    code: string;
    message: string;
  };
};

export const DEV_COMMANDS = {
  git_status: {
    label: "git status",
    cmd: "git",
    args: ["status", "--short"],
    timeoutMs: 10_000,
    requiresConfirmation: false,
  },
  git_diff: {
    label: "git diff",
    cmd: "git",
    args: ["diff", "--", "."],
    timeoutMs: 10_000,
    requiresConfirmation: false,
  },
  npm_typecheck: {
    label: "npm run typecheck",
    cmd: "npm",
    args: ["run", "typecheck"],
    timeoutMs: 120_000,
    requiresConfirmation: false,
  },
  npm_test: {
    label: "npx vitest run",
    cmd: "npx",
    args: ["vitest", "run"],
    timeoutMs: 180_000,
    requiresConfirmation: true,
  },
  npm_lint: {
    label: "npm run lint",
    cmd: "npm",
    args: ["run", "lint"],
    timeoutMs: 120_000,
    requiresConfirmation: false,
  },
  npm_build: {
    label: "npm run build",
    cmd: "npm",
    args: ["run", "build"],
    timeoutMs: 180_000,
    requiresConfirmation: true,
  },
} as const;

let cachedPackageScripts: Record<string, string> | null | undefined;

/** Tests only */
export function clearPackageScriptsCacheForTests(): void {
  cachedPackageScripts = undefined;
}

function loadPackageScripts(): Record<string, string> | null {
  if (cachedPackageScripts !== undefined) return cachedPackageScripts;
  try {
    const pj = path.join(getWorkspaceRoot(), "package.json");
    const raw = readFileSync(pj, "utf8");
    const j = JSON.parse(raw) as { scripts?: Record<string, string> };
    cachedPackageScripts = j.scripts ?? {};
    return cachedPackageScripts;
  } catch {
    cachedPackageScripts = null;
    return null;
  }
}

export function isDevCommandToolsEnvEnabled(): boolean {
  return process.env.SPIRIT_ENABLE_DEV_COMMAND_TOOLS === "true";
}

function npmScriptExists(scriptName: string): boolean {
  const scripts = loadPackageScripts();
  return Boolean(scripts && typeof scripts[scriptName] === "string");
}

/** IDs that are valid for this workspace (npm scripts must exist where applicable). */
export function getAllowedDevCommandIds(): DevCommandId[] {
  const out: DevCommandId[] = ["git_status", "git_diff", "npm_test"];

  if (npmScriptExists("typecheck")) out.push("npm_typecheck");
  if (npmScriptExists("lint")) out.push("npm_lint");
  if (npmScriptExists("build")) out.push("npm_build");

  return out;
}

function safeSpawnEnv(): NodeJS.ProcessEnv {
  const keys = ["PATH", "HOME", "NODE_ENV", "CI", "npm_config_cache"] as const;
  const env: Record<string, string> = {};
  for (const k of keys) {
    const v = process.env[k];
    if (v !== undefined) env[k] = v;
  }
  return env as NodeJS.ProcessEnv;
}

export async function runDevCommand(input: RunDevCommandInput): Promise<DevCommandResult> {
  const fail = (
    code: string,
    message: string,
    partial: Partial<DevCommandResult> = {},
  ): DevCommandResult => ({
    ok: false,
    commandId: input.commandId,
    label: DEV_COMMANDS[input.commandId]?.label ?? input.commandId,
    ...partial,
    error: { code, message },
  });

  if (!isDevCommandToolsEnvEnabled()) {
    return fail("DEV_COMMAND_TOOLS_DISABLED", "SPIRIT_ENABLE_DEV_COMMAND_TOOLS is not enabled.");
  }

  const spec = DEV_COMMANDS[input.commandId];
  if (!spec) {
    return fail("UNKNOWN_COMMAND", "Unknown command id.");
  }

  if (!getAllowedDevCommandIds().includes(input.commandId)) {
    return fail(
      "SCRIPT_NOT_FOUND",
      `Command "${input.commandId}" is not available (missing npm script or not allowlisted for this workspace).`,
    );
  }

  if (spec.requiresConfirmation && input.confirm !== true) {
    return {
      ok: false,
      commandId: input.commandId,
      label: spec.label,
      requiresConfirmation: true,
      message: `Run "${spec.label}" only after explicit approval: pass confirm: true.`,
    };
  }

  const cwd = getWorkspaceRoot();
  const t0 = Date.now();

  try {
    const { exitCode, stdout, stderr, timedOut } = await spawnCollect(
      spec.cmd,
      [...spec.args],
      cwd,
      spec.timeoutMs,
    );
    const dur = Date.now() - t0;
    const combined = truncateToolOutput(`${stdout}\n${stderr}`.trim(), TOOL_MAX_OUTPUT_CHARS);

    return {
      ok: exitCode === 0 && !timedOut,
      commandId: input.commandId,
      label: spec.label,
      exitCode,
      stdout: truncateToolOutput(stdout, TOOL_MAX_OUTPUT_CHARS).text,
      stderr: truncateToolOutput(stderr, TOOL_MAX_OUTPUT_CHARS).text,
      output: combined.text,
      timedOut,
      durationMs: dur,
      message: timedOut
        ? `Command timed out after ${spec.timeoutMs} ms.`
        : exitCode === 0
          ? "Command finished."
          : `Command exited with code ${exitCode}.`,
    };
  } catch (e) {
    const msg = e instanceof Error ? e.message : "spawn failed";
    return fail("SPAWN_ERROR", msg);
  }
}

function spawnCollect(
  cmd: string,
  args: string[],
  cwd: string,
  timeoutMs: number,
): Promise<{ exitCode: number | null; stdout: string; stderr: string; timedOut: boolean }> {
  return new Promise((resolve, reject) => {
    const child = spawnNoShell(cmd, args, {
      cwd,
      env: safeSpawnEnv(),
    });

    let out = "";
    let err = "";
    let timedOut = false;
    const to = setTimeout(() => {
      timedOut = true;
      child.kill("SIGKILL");
    }, timeoutMs);

    child.stdout?.on("data", (c: Buffer) => {
      out += c.toString("utf8");
    });
    child.stderr?.on("data", (c: Buffer) => {
      err += c.toString("utf8");
    });

    child.on("error", (e) => {
      clearTimeout(to);
      reject(e);
    });

    child.on("close", (code) => {
      clearTimeout(to);
      resolve({ exitCode: code, stdout: out, stderr: err, timedOut });
    });
  });
}// ── file-edit-tools - guarded propose / confirmed apply, no silent writes ─
// > Phase 5: fs/promises only. Paths via tool-safety. Backups live under .spirit-backups/.

import "server-only";

import { randomUUID } from "crypto";
import { promises as fs } from "fs";
import path from "path";

import {
  TOOL_MAX_FILE_BYTES,
  TOOL_MAX_OUTPUT_CHARS,
  SpiritToolPathError,
  normalizeWorkspaceRelativePath,
  resolveSafeWorkspacePath,
  truncateToolOutput,
  toolErrorFromUnknown,
  type ToolSafeError,
} from "@/lib/spirit/tools/tool-safety";

export const FILE_EDIT_MAX_NEXT_BYTES = 200 * 1024;
export const FILE_EDIT_PROPOSAL_TTL_MS = 10 * 60 * 1000;

export type FileEditProposal = {
  id: string;
  createdAt: number;
  expiresAt: number;
  relativeFilePath: string;
  previousContent: string;
  nextContent: string;
  diff: string;
  reason?: string;
};

const fileEditProposalStore = new Map<string, FileEditProposal>();

export function isFileEditToolsEnvEnabled(): boolean {
  return process.env.SPIRIT_ENABLE_FILE_EDIT_TOOLS === "true";
}

export function clearExpiredFileEditProposals(): void {
  const now = Date.now();
  for (const [id, p] of fileEditProposalStore) {
    if (p.expiresAt <= now) fileEditProposalStore.delete(id);
  }
}

/** Vitest only */
export function clearAllFileEditProposalsForTests(): void {
  fileEditProposalStore.clear();
}

/** Vitest only */
export function setFileEditProposalExpiryForTest(id: string, expiresAt: number): void {
  const p = fileEditProposalStore.get(id);
  if (p) {
    p.expiresAt = expiresAt;
  }
}

/** Vitest only: inspect stored proposal */
export function getFileEditProposalForTest(id: string): FileEditProposal | undefined {
  return fileEditProposalStore.get(id);
}

function assertUtf8NoNul(buf: Buffer): void {
  if (buf.includes(0)) {
    throw new SpiritToolPathError("NOT_TEXT_FILE", "Only UTF-8 text files are allowed.");
  }
}

/** Simple line-aligned unified-ish diff (no external deps); capped for tool output */
export function buildSimpleUnifiedDiff(
  relativeDisplayPath: string,
  previousContent: string,
  nextContent: string,
): string {
  const a = previousContent.split(/\r?\n/);
  const b = nextContent.split(/\r?\n/);
  const lines: string[] = [`--- ${relativeDisplayPath}`, `+++ ${relativeDisplayPath}`, "@@"];
  const maxLines = 800;
  const maxRows = Math.max(a.length, b.length);
  for (let i = 0; i < maxRows; i++) {
    if (lines.length > maxLines) {
      lines.push("... [diff truncated]");
      break;
    }
    const la = i < a.length ? a[i] : undefined;
    const lb = i < b.length ? b[i] : undefined;
    if (la === lb && la !== undefined) {
      lines.push(` ${la}`);
    } else {
      if (la !== undefined) lines.push(`-${la}`);
      if (lb !== undefined) lines.push(`+${lb}`);
    }
  }
  const raw = lines.join("\n");
  const capped = truncateToolOutput(raw, TOOL_MAX_OUTPUT_CHARS);
  return capped.text + (capped.truncated ? "\n... [diff output truncated]" : "");
}

export type ProposeFileEditInput = {
  filePath: string;
  nextContent: string;
  reason?: string;
};

export type ProposeFileEditOk = {
  ok: true;
  proposalId: string;
  relativeFilePath: string;
  diff: string;
  confirmationRequired: true;
  expiresAt: number;
  message: string;
};

export async function proposeFileEdit(
  input: ProposeFileEditInput,
): Promise<ProposeFileEditOk | ToolSafeError> {
  clearExpiredFileEditProposals();

  if (!isFileEditToolsEnvEnabled()) {
    return {
      ok: false,
      code: "FILE_EDIT_DISABLED",
      message: "SPIRIT_ENABLE_FILE_EDIT_TOOLS is not enabled.",
    };
  }

  if (typeof input.nextContent !== "string") {
    return { ok: false, code: "INVALID_INPUT", message: "nextContent must be a string." };
  }

  const nextBuf = Buffer.from(input.nextContent, "utf8");
  if (nextBuf.length > FILE_EDIT_MAX_NEXT_BYTES) {
    return {
      ok: false,
      code: "NEXT_TOO_LARGE",
      message: `nextContent exceeds maximum of ${FILE_EDIT_MAX_NEXT_BYTES} bytes.`,
    };
  }

  let rel: string;
  try {
    rel = normalizeWorkspaceRelativePath(input.filePath);
    resolveSafeWorkspacePath(input.filePath);
  } catch (e) {
    return toolErrorFromUnknown(e);
  }

  const abs = resolveSafeWorkspacePath(input.filePath);

  let previousContent = "";
  try {
    const st = await fs.stat(abs);
    if (!st.isFile()) {
      return { ok: false, code: "NOT_A_FILE", message: "Path is not a file." };
    }
    if (st.size > TOOL_MAX_FILE_BYTES) {
      return {
        ok: false,
        code: "FILE_TOO_LARGE",
        message: `Existing file exceeds maximum size of ${TOOL_MAX_FILE_BYTES} bytes.`,
      };
    }
    const buf = await fs.readFile(abs);
    assertUtf8NoNul(buf);
    previousContent = buf.toString("utf8");
  } catch (e) {
    const err = e as NodeJS.ErrnoException;
    if (err?.code === "ENOENT") {
      previousContent = "";
    } else {
      return toolErrorFromUnknown(e);
    }
  }

  const relDisplay = rel.split(path.sep).join("/");
  const diff = buildSimpleUnifiedDiff(relDisplay, previousContent, input.nextContent);

  const id = randomUUID();
  const createdAt = Date.now();
  const expiresAt = createdAt + FILE_EDIT_PROPOSAL_TTL_MS;

  const proposal: FileEditProposal = {
    id,
    createdAt,
    expiresAt,
    relativeFilePath: relDisplay,
    previousContent,
    nextContent: input.nextContent,
    diff,
    reason: input.reason,
  };
  fileEditProposalStore.set(id, proposal);

  return {
    ok: true,
    proposalId: id,
    relativeFilePath: relDisplay,
    diff,
    confirmationRequired: true,
    expiresAt,
    message:
      "Review this diff. To apply it, call apply_confirmed_file_edit with this proposalId and confirm: true after the user approves.",
  };
}

export type ApplyConfirmedFileEditInput = {
  proposalId: string;
  confirm: boolean;
};

export type ApplyConfirmedFileEditOk = {
  ok: true;
  relativeFilePath: string;
  backupRelativePath: string;
  appliedAt: string;
  message: string;
};

export async function applyConfirmedFileEdit(
  input: ApplyConfirmedFileEditInput,
): Promise<ApplyConfirmedFileEditOk | ToolSafeError> {
  if (!isFileEditToolsEnvEnabled()) {
    return {
      ok: false,
      code: "FILE_EDIT_DISABLED",
      message: "SPIRIT_ENABLE_FILE_EDIT_TOOLS is not enabled.",
    };
  }

  if (!input.confirm) {
    return {
      ok: false,
      code: "CONFIRMATION_REQUIRED",
      message: "confirm must be true to apply a stored proposal.",
    };
  }

  const proposal = fileEditProposalStore.get(input.proposalId);
  if (!proposal) {
    return { ok: false, code: "PROPOSAL_NOT_FOUND", message: "Unknown or expired proposal id." };
  }

  if (proposal.expiresAt <= Date.now()) {
    fileEditProposalStore.delete(input.proposalId);
    return { ok: false, code: "PROPOSAL_EXPIRED", message: "This proposal has expired." };
  }

  let rel: string;
  try {
    rel = normalizeWorkspaceRelativePath(proposal.relativeFilePath);
    resolveSafeWorkspacePath(proposal.relativeFilePath);
  } catch (e) {
    return toolErrorFromUnknown(e);
  }

  const abs = resolveSafeWorkspacePath(proposal.relativeFilePath);

  let currentContent = "";
  try {
    const st = await fs.stat(abs);
    if (!st.isFile()) {
      return { ok: false, code: "NOT_A_FILE", message: "Path is not a file." };
    }
    if (st.size > TOOL_MAX_FILE_BYTES) {
      return {
        ok: false,
        code: "FILE_TOO_LARGE",
        message: "File grew beyond the maximum allowed size since the proposal.",
      };
    }
    const buf = await fs.readFile(abs);
    assertUtf8NoNul(buf);
    currentContent = buf.toString("utf8");
  } catch (e) {
    const err = e as NodeJS.ErrnoException;
    if (err?.code === "ENOENT") {
      currentContent = "";
    } else {
      return toolErrorFromUnknown(e);
    }
  }

  if (currentContent !== proposal.previousContent) {
    return {
      ok: false,
      code: "CONFLICT",
      message:
        "File content changed since the proposal was created. Re-run propose_file_edit with a fresh diff.",
    };
  }

  clearExpiredFileEditProposals();

  const appliedAt = new Date().toISOString();
  const day = appliedAt.slice(0, 10);
  const ts = Date.now();
  const safeBase = path.basename(rel).replace(/[^\w.-]+/g, "_") || "file";
  const backupRelPath = path.join(".spirit-backups", day, `${safeBase}.${ts}.bak`).split(path.sep).join("/");

  let backupAbs: string;
  try {
    backupAbs = resolveSafeWorkspacePath(backupRelPath);
  } catch (e) {
    return toolErrorFromUnknown(e);
  }

  await fs.mkdir(path.dirname(backupAbs), { recursive: true });

  if (currentContent.length > 0) {
    await fs.writeFile(backupAbs, currentContent, "utf8");
  }

  await fs.mkdir(path.dirname(abs), { recursive: true });

  await fs.writeFile(abs, proposal.nextContent, "utf8");
  fileEditProposalStore.delete(input.proposalId);

  return {
    ok: true,
    relativeFilePath: rel.split(path.sep).join("/"),
    backupRelativePath: backupRelPath,
    appliedAt,
    message: "Applied confirmed edit and created a backup.",
  };
}// ── tool-safety - path + output guards for read-only Spirit workspace tools ──
// > No shell, no writes, no leaking cwd paths into model-facing JSON.

import path from "path";

export const TOOL_MAX_FILE_BYTES = 120 * 1024;
export const TOOL_MAX_OUTPUT_CHARS = 20 * 1024;

export const BLOCKED_WORKSPACE_DIRS = [
  "node_modules",
  ".git",
  ".next",
  "dist",
  "build",
  "coverage",
  ".turbo",
  ".vercel",
  ".cache",
] as const;

/** Human-readable patterns; matching logic is in matchesBlockedFileBasename. */
export const BLOCKED_WORKSPACE_FILE_PATTERNS = [
  ".env",
  ".env.*",
  "*.pem",
  "*.key",
  "id_rsa",
  "id_ed25519",
  "secrets.*",
  "credentials.*",
  "service-account*.json",
] as const;

export type ToolSafeError = {
  ok: false;
  code: string;
  message: string;
};

export class SpiritToolPathError extends Error {
  readonly code: string;

  constructor(code: string, message: string) {
    super(message);
    this.name = "SpiritToolPathError";
    this.code = code;
  }
}

export function createToolError(code: string, message: string): ToolSafeError {
  return { ok: false, code, message };
}

export function getWorkspaceRoot(): string {
  const raw = process.env.SPIRIT_PROJECT_PATH?.trim();
  const base = raw && raw.length > 0 ? raw : process.cwd();
  return path.resolve(base);
}

function workspaceRootForChecks(): string {
  return path.normalize(getWorkspaceRoot());
}

export function isBlockedPathSegment(segment: string): boolean {
  return (BLOCKED_WORKSPACE_DIRS as readonly string[]).includes(segment);
}

export function matchesBlockedFileBasename(basename: string): boolean {
  const lower = basename.toLowerCase();
  if (lower === ".env") return true;
  if (lower.startsWith(".env.")) return true;
  if (lower.endsWith(".pem")) return true;
  if (lower.endsWith(".key")) return true;
  if (basename === "id_rsa" || basename === "id_ed25519") return true;
  if (lower.startsWith("secrets.")) return true;
  if (lower.startsWith("credentials.")) return true;
  if (/^service-account.*\.json$/i.test(basename)) return true;
  return false;
}

/**
 * Returns a workspace-relative path using forward slashes for stable tool output.
 * Throws SpiritToolPathError when input is not a safe relative path.
 */
export function normalizeWorkspaceRelativePath(inputPath: string): string {
  if (typeof inputPath !== "string") {
    throw new SpiritToolPathError("INVALID_PATH", "Path must be a string.");
  }

  const trimmed = inputPath.trim();
  if (trimmed === "") {
    throw new SpiritToolPathError("INVALID_PATH", "Path cannot be empty.");
  }

  if (path.isAbsolute(trimmed) || /^[a-z]:[\\/]/i.test(trimmed)) {
    throw new SpiritToolPathError("ABSOLUTE_PATH_NOT_ALLOWED", "Absolute paths are not allowed.");
  }

  const cleaned = trimmed.replace(/^[/\\]+/, "");
  const segments = cleaned.split(/[/\\]+/).filter((s) => s !== "." && s !== "");
  for (const seg of segments) {
    if (seg === "..") {
      throw new SpiritToolPathError("PATH_TRAVERSAL", "Path traversal is not allowed.");
    }
  }

  const normalized = segments.length === 0 ? "." : segments.join(path.sep);

  const relParts = normalized === "." ? [] : normalized.split(path.sep);
  for (const part of relParts) {
    if (part !== "." && isBlockedPathSegment(part)) {
      throw new SpiritToolPathError("BLOCKED_SEGMENT", `Blocked path segment: ${part}`);
    }
    if (matchesBlockedFileBasename(part)) {
      throw new SpiritToolPathError("BLOCKED_FILE_PATTERN", "That file pattern is blocked.");
    }
  }

  return normalized;
}

export function resolveSafeWorkspacePath(inputPath: string): string {
  const relative = normalizeWorkspaceRelativePath(inputPath);
  const root = workspaceRootForChecks();
  const full =
    relative === "."
      ? root
      : path.resolve(path.join(root, relative));

  const rootWithSep = root.endsWith(path.sep) ? root : `${root}${path.sep}`;
  const normalizedFull = path.normalize(full);
  if (normalizedFull !== root && !normalizedFull.startsWith(rootWithSep)) {
    throw new SpiritToolPathError("OUTSIDE_WORKSPACE", "Path resolves outside the workspace root.");
  }

  return normalizedFull;
}

export function assertSafeWorkspacePath(inputPath: string): void {
  resolveSafeWorkspacePath(inputPath);
}

export function truncateToolOutput(text: string, maxChars: number): { text: string; truncated: boolean } {
  if (text.length <= maxChars) {
    return { text, truncated: false };
  }
  return {
    text: text.slice(0, maxChars) + "\n... [truncated]",
    truncated: true,
  };
}

export function isSpiritToolPathError(err: unknown): err is SpiritToolPathError {
  return err instanceof SpiritToolPathError;
}

export function toolErrorFromUnknown(err: unknown): ToolSafeError {
  if (err && typeof err === "object" && "ok" in err && (err as ToolSafeError).ok === false) {
    const e = err as ToolSafeError;
    return createToolError(e.code, e.message);
  }
  if (isSpiritToolPathError(err)) {
    return createToolError(err.code, err.message);
  }
  return createToolError("TOOL_ERROR", "The tool could not complete safely.");
}// concrete-workspace-read-request - gate LLM path vs capability shortcut
// > True only for path-specific read/list/tail asks, not vague permission questions.

/** Strip trailing punctuation / quotes from a captured path fragment. */
function trimPathFragment(fragment: string): string {
  return fragment.replace(/^[`"']+/, "").replace(/[`"'.,;:!?]+$/, "").trim();
}

function stripNaturalFolderLabels(fragment: string): string {
  let s = trimPathFragment(fragment).replace(/\\/g, "/").trim();
  s = s.replace(/^my\s+/i, "").trim();
  s = s.replace(/\s+(folder|directory|dir)\s*$/i, "").trim();
  return trimPathFragment(s);
}

function looksLikeWindowsDrivePath(fragment: string): boolean {
  const s = stripNaturalFolderLabels(fragment);
  return /^[a-z]:\//i.test(s) || /^[a-z]\//i.test(s);
}

/**
 * True when the fragment looks like a workspace-relative path or filename,
 * not a vague noun phrase ("my files", "folders").
 */
export function pathFragmentLooksConcrete(fragment: string): boolean {
  const s = stripNaturalFolderLabels(fragment);
  if (s.length < 1) return false;
  if (/^(files?|folders?|directories?)$/i.test(s)) return false;
  if (/^(my|your|the|a|an|any|all|arbitrary|some)\s+files?$/i.test(s)) return false;
  if (/^my\s+/i.test(s) && !s.includes("/")) return false;

  if (looksLikeWindowsDrivePath(s)) return true;
  if (s.includes("/")) return true;
  if (/^\.env/i.test(s)) return true;
  if (/\.(?:ts|tsx|js|jsx|json|md|mjs|cjs|css|html|txt|log|yaml|yml|toml|xml|svg|pem|key)(?:\.\w+)?$/i.test(s))
    return true;
  if (s === "package.json" || s === "nohup.out" || /^[\w.-]+\.json$/i.test(s)) return true;
  if (/^(src|lib|app|test|tests|public|docs|packages|components|scripts|config)(\/[\w.-]+)*$/i.test(s))
    return true;
  return false;
}

/**
 * True when the user is asking for a concrete workspace read/list/tail operation
 * (so Hermes can use read-only tools), not a capability meta-question.
 */
export function isConcreteWorkspaceReadRequest(text: string): boolean {
  const raw = text.trim();
  if (raw.length < 6) return false;
  const lower = raw.toLowerCase();

  if (
    /\b(run|execute|exec|bash|shell|terminal|sudo|npm\s+(test|run|install|ci|start|dev|exec)|pnpm\s|yarn\s+(test|install|add))\b/i.test(
      lower,
    )
  ) {
    return false;
  }

  if (/\b(edit|delete|write|create|mkdir|rm\s|mv\s|cp\s|move|rename)\s+/i.test(lower)) {
    return false;
  }

  if (/\bshow\s+(the\s+)?(last|past)\s+\d+\s+lines\s+of\s+([^\s?!,]+)/i.test(raw)) {
    const m = raw.match(/\bshow\s+(the\s+)?(last|past)\s+\d+\s+lines\s+of\s+([^\s?!,]+)/i);
    if (m?.[3] && pathFragmentLooksConcrete(m[3])) return true;
  }

  if (/\btail\s+([^\s?!,]+)/i.test(raw)) {
    const m = raw.match(/\btail\s+([^\s?!,]+)/i);
    if (m?.[1] && pathFragmentLooksConcrete(m[1])) return true;
  }

  const listFilesIn = raw.match(/\blist\s+(the\s+)?files?\s+in\s+([^\s?!,]+)/i);
  if (listFilesIn?.[2] && pathFragmentLooksConcrete(listFilesIn[2])) return true;

  const listDir = raw.match(/\blist\s+(the\s+)?(directory|dir)\s+([^\s?!,]+)/i);
  if (listDir?.[3] && pathFragmentLooksConcrete(listDir[3])) return true;

  const showFilesIn = raw.match(/\bshow\s+(the\s+)?files?\s+in\s+([^\s?!,]+)/i);
  if (showFilesIn?.[2] && pathFragmentLooksConcrete(showFilesIn[2])) return true;

  const showContents = raw.match(/\bshow\s+(the\s+)?contents\s+of\s+([^\s?!,]+)/i);
  if (showContents?.[2] && pathFragmentLooksConcrete(showContents[2])) return true;

  const naturalList = raw.match(
    /\b(?:show\s+me\s+)?(?:what(?:'s|s|\s+is)\s+(?:in|inside)|what\s+(?:files|folders)\s+are\s+in)\s+(.+)$/i,
  );
  if (naturalList?.[1] && pathFragmentLooksConcrete(naturalList[1])) return true;

  const readFile = raw.match(/\bread\s+([^\s?!,]+)/i);
  if (readFile?.[1] && !/^(files?|folders?|directories?)$/i.test(readFile[1])) {
    if (pathFragmentLooksConcrete(readFile[1])) return true;
  }

  const openFile = raw.match(/\bopen\s+([^\s?!,]+)/i);
  if (openFile?.[1] && pathFragmentLooksConcrete(openFile[1])) return true;

  return false;
}// ── ollama-tool-unsupported-error - detect Ollama "no tools" 400 for safe retry ──

import { APICallError } from "ai";

/** True when Ollama OpenAI-compat rejected the request because the model does not support tools. */
export function isOllamaModelToolUnsupportedError(error: unknown): boolean {
  if (!APICallError.isInstance(error)) return false;
  const msg = String(error.message).toLowerCase();
  if (msg.includes("does not support tools")) return true;
  const body = (error.responseBody ?? "").toLowerCase();
  if (body.includes("does not support tools")) return true;
  return false;
}// ── spirit-assistant-tool-activity - merge stream metadata + tool UI parts into cards ─
// > Client-safe: mirrors server telemetry shapes without importing workspace roots or secrets.

import type { UIMessage } from "ai";

import {
  createSpiritToolActivityCard,
  type SpiritAssistantMessageMetadata,
  type SpiritToolActivityCard,
  type SpiritToolActivityKind,
  type SpiritToolActivityStatus,
} from "@/lib/spirit/spirit-activity-events";

function isRecord(x: unknown): x is Record<string, unknown> {
  return Boolean(x && typeof x === "object");
}

export function readSpiritAssistantMessageMetadata(
  message: UIMessage,
): SpiritAssistantMessageMetadata | undefined {
  const m = message.metadata;
  if (!m || typeof m !== "object") return undefined;
  const spirit = (m as SpiritAssistantMessageMetadata).spiritToolActivity;
  if (!Array.isArray(spirit)) return undefined;
  return m as SpiritAssistantMessageMetadata;
}

function toolNameFromPart(part: UIMessage["parts"][number]): string | null {
  if (!isRecord(part)) return null;
  if ("toolName" in part && typeof (part as { toolName?: string }).toolName === "string") {
    return (part as { toolName: string }).toolName;
  }
  const t = (part as { type?: unknown }).type;
  if (typeof t === "string" && t.startsWith("tool-")) {
    return t.slice("tool-".length);
  }
  return null;
}

function statusLabel(s: SpiritToolActivityStatus): string {
  switch (s) {
    case "pending":
      return "Pending";
    case "completed":
      return "Completed";
    case "failed":
      return "Failed";
    case "blocked":
      return "Blocked";
    case "confirmation_required":
      return "Confirmation required";
    default:
      return s;
  }
}

/** Human-readable action title for tool parts (matches direct-fallback labels where possible). */
export function spiritToolKindDisplay(kind: SpiritToolActivityKind): string {
  switch (kind) {
    case "workspace_list":
      return "List workspace files";
    case "workspace_read":
      return "Read workspace file";
    case "workspace_tail":
      return "Tail log file";
    case "file_edit_proposed":
      return "Propose file edit";
    case "file_edit_applied":
      return "Apply file edit";
    case "dev_command_started":
      return "Dev command";
    case "dev_command_completed":
      return "Dev command";
    case "dev_command_failed":
      return "Dev command";
    case "tool_blocked":
      return "Blocked";
    case "tool_unavailable":
      return "Tool unavailable";
    default:
      return "Tool";
  }
}

export { statusLabel };

function cardsFromListWorkspace(
  out: unknown,
  id: string,
  input: unknown,
): SpiritToolActivityCard[] {
  if (!isRecord(out)) return [];
  const inp = isRecord(input) ? input : {};
  const dir =
    typeof inp.directory === "string" ? inp.directory : typeof inp.path === "string" ? inp.path : ".";

  if (out.ok === true) {
    return [
      createSpiritToolActivityCard({
        id,
        kind: "workspace_list",
        label: "List workspace files",
        status: "completed",
        target: typeof out.directory === "string" ? out.directory : dir,
        summary: out.truncated === true ? "truncated" : undefined,
      }),
    ];
  }
  return [
    createSpiritToolActivityCard({
      id,
      kind: "tool_blocked",
      label: "List workspace files",
      status: "blocked",
      target: dir,
      safeMessage: typeof out.message === "string" ? out.message : "blocked",
    }),
  ];
}

function cardsFromReadFile(out: unknown, id: string, input: unknown): SpiritToolActivityCard[] {
  if (!isRecord(out)) return [];
  const inp = isRecord(input) ? input : {};
  const fp = typeof inp.filePath === "string" ? inp.filePath : undefined;

  if (out.ok === true) {
    return [
      createSpiritToolActivityCard({
        id,
        kind: "workspace_read",
        label: "Read workspace file",
        status: "completed",
        target: typeof out.filePath === "string" ? out.filePath : fp,
        summary: out.truncated === true ? "truncated" : undefined,
      }),
    ];
  }
  return [
    createSpiritToolActivityCard({
      id,
      kind: "tool_blocked",
      label: "Read workspace file",
      status: "blocked",
      target: fp,
      safeMessage: typeof out.message === "string" ? out.message : "blocked",
    }),
  ];
}

function cardsFromTail(out: unknown, id: string, input: unknown): SpiritToolActivityCard[] {
  if (!isRecord(out)) return [];
  const inp = isRecord(input) ? input : {};
  const fp = typeof inp.filePath === "string" ? inp.filePath : undefined;

  if (out.ok === true) {
    return [
      createSpiritToolActivityCard({
        id,
        kind: "workspace_tail",
        label: "Tail log file",
        status: "completed",
        target: typeof out.filePath === "string" ? out.filePath : fp,
        summary: out.truncated === true ? "truncated" : undefined,
      }),
    ];
  }
  return [
    createSpiritToolActivityCard({
      id,
      kind: "tool_blocked",
      label: "Tail log file",
      status: "blocked",
      target: fp,
      safeMessage: typeof out.message === "string" ? out.message : "blocked",
    }),
  ];
}

function cardsFromProposeEdit(out: unknown, id: string): SpiritToolActivityCard[] {
  if (!isRecord(out)) return [];
  if (out.ok === true && typeof out.proposalId === "string") {
    return [
      createSpiritToolActivityCard({
        id,
        kind: "file_edit_proposed",
        label: "Propose file edit",
        status: "confirmation_required",
        target: typeof out.relativeFilePath === "string" ? out.relativeFilePath : undefined,
        summary: `proposal ${out.proposalId}`,
      }),
    ];
  }
  return [
    createSpiritToolActivityCard({
      id,
      kind: "tool_blocked",
      label: "Propose file edit",
      status: "blocked",
      safeMessage: typeof out.message === "string" ? out.message : "failed",
    }),
  ];
}

function cardsFromApplyEdit(out: unknown, id: string): SpiritToolActivityCard[] {
  if (!isRecord(out)) return [];
  if (out.ok === true) {
    return [
      createSpiritToolActivityCard({
        id,
        kind: "file_edit_applied",
        label: "Apply file edit",
        status: "completed",
        target: typeof out.relativeFilePath === "string" ? out.relativeFilePath : undefined,
        summary:
          typeof out.backupRelativePath === "string"
            ? `backup ${out.backupRelativePath}`
            : undefined,
      }),
    ];
  }
  const code = typeof out.code === "string" ? out.code : "";
  const needsConfirm = code === "CONFIRMATION_REQUIRED";
  return [
    createSpiritToolActivityCard({
      id,
      kind: "tool_blocked",
      label: "Apply file edit",
      status: needsConfirm ? "confirmation_required" : "blocked",
      safeMessage: typeof out.message === "string" ? out.message : "failed",
    }),
  ];
}

function cardsFromDevCommand(out: unknown, id: string): SpiritToolActivityCard[] {
  if (!isRecord(out)) return [];
  const cmdId = typeof out.commandId === "string" ? out.commandId : "?";

  if (out.requiresConfirmation === true) {
    return [
      createSpiritToolActivityCard({
        id,
        kind: "dev_command_started",
        label: "Dev command",
        status: "confirmation_required",
        target: cmdId,
        summary: typeof out.label === "string" ? out.label : undefined,
      }),
    ];
  }

  if (out.error && isRecord(out.error)) {
    const code = typeof out.error.code === "string" ? out.error.code : "";
    const unavailable =
      code === "DEV_COMMAND_TOOLS_DISABLED" ||
      code === "SCRIPT_NOT_FOUND" ||
      code === "UNKNOWN_COMMAND";
    return [
      createSpiritToolActivityCard({
        id,
        kind: unavailable ? "tool_unavailable" : "dev_command_failed",
        label: "Dev command",
        status: "failed",
        target: cmdId,
        safeMessage:
          typeof out.error.message === "string" ? out.error.message : "command failed",
      }),
    ];
  }

  if (out.timedOut === true || out.ok === false) {
    return [
      createSpiritToolActivityCard({
        id,
        kind: "dev_command_failed",
        label: "Dev command",
        status: "failed",
        target: cmdId,
        summary: out.timedOut === true ? "Timed out" : `Exit ${out.exitCode ?? "?"}`,
      }),
    ];
  }

  return [
    createSpiritToolActivityCard({
      id,
      kind: "dev_command_completed",
      label: "Dev command",
      status: "completed",
      target: cmdId,
      summary: typeof out.label === "string" ? out.label : undefined,
    }),
  ];
}

/**
 * Derive activity cards from persisted tool UI parts (LLM tool path).
 */
export function toolUIPartsToActivityCards(parts: UIMessage["parts"]): SpiritToolActivityCard[] {
  const cards: SpiritToolActivityCard[] = [];

  for (const part of parts) {
    const name = toolNameFromPart(part);
    if (!name) continue;
    if (!isRecord(part) || !("state" in part)) continue;
    const p = part as {
      state: string;
      toolCallId?: string;
      type?: string;
      input?: unknown;
      output?: unknown;
      errorText?: string;
    };
    const callId = typeof p.toolCallId === "string" ? p.toolCallId : "unknown";
    const baseId = `toolpart_${callId}`;

    if (p.state === "output-error") {
      cards.push(
        createSpiritToolActivityCard({
          id: baseId,
          kind: "tool_blocked",
          label: name.replace(/_/g, " "),
          status: "failed",
          summary: typeof p.errorText === "string" ? p.errorText.slice(0, 200) : undefined,
        }),
      );
      continue;
    }

    if (p.state !== "output-available") continue;
    const input = p.input;

    switch (name) {
      case "list_workspace_files":
        cards.push(...cardsFromListWorkspace(p.output, baseId, input));
        break;
      case "read_workspace_file":
        cards.push(...cardsFromReadFile(p.output, baseId, input));
        break;
      case "read_log_tail":
        cards.push(...cardsFromTail(p.output, baseId, input));
        break;
      case "propose_file_edit":
        cards.push(...cardsFromProposeEdit(p.output, baseId));
        break;
      case "apply_confirmed_file_edit":
        cards.push(...cardsFromApplyEdit(p.output, baseId));
        break;
      case "run_dev_command":
        cards.push(...cardsFromDevCommand(p.output, baseId));
        break;
      default:
        break;
    }
  }

  return cards;
}

/**
 * Metadata from deterministic `/api/spirit` responses plus tool parts from streamed tool calls.
 */
export function mergeSpiritToolActivityCardsForMessage(message: UIMessage): SpiritToolActivityCard[] {
  const meta = readSpiritAssistantMessageMetadata(message)?.spiritToolActivity ?? [];
  const fromParts = toolUIPartsToActivityCards(message.parts);
  const map = new Map<string, SpiritToolActivityCard>();
  for (const c of fromParts) {
    map.set(c.id, c);
  }
  for (const c of meta) {
    map.set(c.id, c);
  }
  return [...map.values()];
}// ── spirit-tool-activity-response - parse x-spirit-tool-activity-json (client-safe) ─

import type { SpiritToolActivityCard } from "@/lib/spirit/spirit-activity-events";

function isCard(x: unknown): x is SpiritToolActivityCard {
  if (!x || typeof x !== "object") return false;
  const o = x as Record<string, unknown>;
  return (
    typeof o.id === "string" &&
    typeof o.timestamp === "number" &&
    typeof o.kind === "string" &&
    typeof o.label === "string" &&
    typeof o.status === "string"
  );
}

/** Compact JSON from /api/spirit response headers (deterministic tool paths). */
export function parseSpiritToolActivityHeader(res: Response): SpiritToolActivityCard[] {
  const raw = res.headers.get("x-spirit-tool-activity-json");
  if (!raw?.trim()) return [];
  try {
    const j = JSON.parse(raw) as unknown;
    if (!Array.isArray(j)) return [];
    return j.filter(isCard);
  } catch {
    return [];
  }
}import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { AudioQueue } from "@/lib/tts/audio-queue";

describe("AudioQueue interrupt (Prompt 9G)", () => {
  beforeEach(() => {
    vi.stubGlobal(
      "fetch",
      vi.fn(() => new Promise<Response>(() => {})),
    );
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("aborts the in-flight fetch signal when a new speak() interrupts", async () => {
    const q = new AudioQueue({});
    q.speak("first chunk of speech", { interrupt: true });
    for (let i = 0; i < 24; i += 1) {
      await Promise.resolve();
    }
    const firstInit = vi.mocked(fetch).mock.calls[0]?.[1] as RequestInit | undefined;
    expect(firstInit?.signal).toBeDefined();
    const sig = firstInit!.signal!;
    expect(sig.aborted).toBe(false);

    q.speak("second chunk replaces session", { interrupt: true });
    expect(sig.aborted).toBe(true);
  });

  it("stop() aborts active fetch", async () => {
    const q = new AudioQueue({});
    q.speak("hold the line", { interrupt: true });
    for (let i = 0; i < 24; i += 1) {
      await Promise.resolve();
    }
    const firstInit = vi.mocked(fetch).mock.calls[0]?.[1] as RequestInit | undefined;
    const sig = firstInit?.signal;
    expect(sig).toBeDefined();
    q.stop();
    expect(sig!.aborted).toBe(true);
  });

  it("second speak schedules a new fetch without waiting for the first hang to resolve", async () => {
    const q = new AudioQueue({});
    q.speak("aaaaaaaaaaaaaaaa", { interrupt: true });
    for (let i = 0; i < 40; i += 1) await Promise.resolve();
    expect(fetch).toHaveBeenCalledTimes(1);

    q.speak("bbbbbbbbbbbbbbbb", { interrupt: true });
    for (let i = 0; i < 10; i += 1) await Promise.resolve();
    expect(fetch).toHaveBeenCalledTimes(2);
  });
});import { describe, expect, it } from "vitest";

import {
