import { parseOptionalTtsSpeedField, parseOptionalTtsVoiceIdField, parseOptionalTtsVoiceNameField } from "@/lib/tts/tts-http";

describe("parseOptionalTtsSpeedField", () => {
  it("returns undefined when speed absent", () => {
    expect(parseOptionalTtsSpeedField({ text: "hi" })).toEqual({ ok: true, value: undefined });
  });

  it("returns undefined for null speed", () => {
    expect(parseOptionalTtsSpeedField({ speed: null })).toEqual({ ok: true, value: undefined });
  });

  it("accepts finite number", () => {
    expect(parseOptionalTtsSpeedField({ speed: 1.12 })).toEqual({ ok: true, value: 1.12 });
  });

  it("rejects non-number speed", () => {
    const r = parseOptionalTtsSpeedField({ speed: "1.12" });
    expect(r.ok).toBe(false);
    if (!r.ok) expect(r.message).toMatch(/finite number/);
  });

  it("rejects NaN", () => {
    const r = parseOptionalTtsSpeedField({ speed: NaN });
    expect(r.ok).toBe(false);
  });
});

describe("parseOptionalTtsVoiceIdField", () => {
  it("returns undefined when absent", () => {
    expect(parseOptionalTtsVoiceIdField({ text: "hi" })).toEqual({ ok: true, value: undefined });
  });

  it("accepts trimmed string", () => {
    expect(parseOptionalTtsVoiceIdField({ voiceId: "  abc123  " })).toEqual({
      ok: true,
      value: "abc123",
    });
  });

  it("rejects non-string", () => {
    const r = parseOptionalTtsVoiceIdField({ voiceId: 1 });
    expect(r.ok).toBe(false);
  });
});

describe("parseOptionalTtsVoiceNameField", () => {
  it("returns undefined when absent", () => {
    expect(parseOptionalTtsVoiceNameField({ text: "hi" })).toEqual({ ok: true, value: undefined });
  });

  it("accepts trimmed string", () => {
    expect(parseOptionalTtsVoiceNameField({ voiceName: "  Ada  " })).toEqual({
      ok: true,
      value: "Ada",
    });
  });

  it("rejects absurd length", () => {
    const r = parseOptionalTtsVoiceNameField({ voiceName: "x".repeat(200) });
    expect(r.ok).toBe(false);
  });
});import { describe, expect, it } from "vitest";

import { parseTtsSegments, stripTextForTts } from "@/lib/tts/tts-parser";

describe("stripTextForTts", () => {
  it("strips fenced code and inline markers", () => {
    const s = stripTextForTts("See `x` and [a](http://b) **bold**");
    expect(s).toContain("x");
    expect(s).toContain("a");
    expect(s).not.toContain("**");
  });
});

describe("parseTtsSegments", () => {
  it("parses plain speech", () => {
    expect(parseTtsSegments("Hello world")).toEqual([
      { type: "speech", text: "Hello world" },
    ]);
  });

  it("parses pause markers", () => {
    expect(parseTtsSegments("A [pause:100] B")).toEqual([
      { type: "speech", text: "A" },
      { type: "pause", ms: 100 },
      { type: "speech", text: "B" },
    ]);
    expect(parseTtsSegments("A [pause:1s] B")).toEqual([
      { type: "speech", text: "A" },
      { type: "pause", ms: 1000 },
      { type: "speech", text: "B" },
    ]);
    expect(parseTtsSegments("A [[pause 250ms]] B")).toEqual([
      { type: "speech", text: "A" },
      { type: "pause", ms: 250 },
      { type: "speech", text: "B" },
    ]);
  });
});import { describe, expect, it } from "vitest";

import {
  filterFolderSidebarModel,
  type FolderSidebarModel,
} from "@/lib/chat-folder-utils";

describe("filterFolderSidebarModel", () => {
  const model: FolderSidebarModel = {
    rootThreads: [
      { id: "a", title: "A", createdAt: 1, updatedAt: 3 },
      { id: "b", title: "B", createdAt: 1, updatedAt: 2 },
    ],
    folderSections: [
      {
        folder: {
          id: "f1",
          name: "F",
          createdAt: 1,
          updatedAt: 1,
          order: 1,
        },
        threads: [{ id: "c", title: "C", createdAt: 1, updatedAt: 1, folderId: "f1" }],
      },
    ],
  };

  it("returns unchanged when allowed null", () => {
    expect(filterFolderSidebarModel(model, null)).toEqual(model);
  });

  it("filters roots and folder threads", () => {
    const out = filterFolderSidebarModel(model, new Set(["b", "c"]));
    expect(out.rootThreads.map((t) => t.id)).toEqual(["b"]);
    expect(out.folderSections).toHaveLength(1);
    expect(out.folderSections[0]!.threads.map((t) => t.id)).toEqual(["c"]);
  });

  it("drops empty folder sections", () => {
    const out = filterFolderSidebarModel(model, new Set(["a"]));
    expect(out.folderSections).toEqual([]);
  });
});import { describe, expect, it } from "vitest";

import { buildTitleFromText } from "@/lib/chat-persistence";

describe("buildTitleFromText", () => {
