const mockThreadsUpdate = vi.fn();
const mockThreadsToArray = vi.fn();
const mockMessagesFilter = vi.fn();

vi.mock("@/lib/chat-db", () => ({
  isBrowserChatDbAvailable: () => true,
  db: {
    threads: {
      update: (...a: unknown[]) => mockThreadsUpdate(...a),
      toArray: () => mockThreadsToArray(),
    },
    messages: {
      filter: (fn: (m: { text: string }) => boolean) => ({
        toArray: async () => {
          const all = await mockMessagesFilter();
          return all.filter(fn);
        },
      }),
    },
  },
}));

import { pinThread, searchThreadsAndMessages, unpinThread } from "@/lib/chat-persistence";

describe("chat-persistence pins", () => {
  beforeEach(() => {
    mockThreadsUpdate.mockClear();
  });

  it("pinThread sets pinned true and pinnedAt", async () => {
    await pinThread("abc");
    expect(mockThreadsUpdate).toHaveBeenCalledTimes(1);
    const [id, patch] = mockThreadsUpdate.mock.calls[0]!;
    expect(id).toBe("abc");
    expect(patch).toMatchObject({ pinned: true });
    expect(typeof (patch as { pinnedAt: number }).pinnedAt).toBe("number");
  });

  it("unpinThread clears pinned", async () => {
    await unpinThread("abc");
    expect(mockThreadsUpdate).toHaveBeenCalledWith(
      "abc",
      expect.objectContaining({ pinned: false, pinnedAt: undefined }),
    );
  });
});

describe("searchThreadsAndMessages", () => {
  beforeEach(() => {
    mockThreadsToArray.mockReset();
    mockMessagesFilter.mockReset();
  });

  it("returns [] for empty query", async () => {
    expect(await searchThreadsAndMessages("   ")).toEqual([]);
  });

  it("matches title case-insensitively", async () => {
    mockThreadsToArray.mockResolvedValue([
      {
        id: "t1",
        title: "Hello WORLD",
        createdAt: 1,
        updatedAt: 10,
        archived: false,
      },
    ]);
    mockMessagesFilter.mockResolvedValue([]);
    const hits = await searchThreadsAndMessages("world");
    expect(hits).toHaveLength(1);
    expect(hits[0]!.thread.id).toBe("t1");
  });

  it("matches message text with snippet", async () => {
    mockThreadsToArray.mockResolvedValue([
      {
        id: "t1",
        title: "Other",
        createdAt: 1,
        updatedAt: 10,
        archived: false,
      },
    ]);
    mockMessagesFilter.mockResolvedValue([
      { threadId: "t1", text: "The quick brown Fox jumps", role: "user" },
    ]);
    const hits = await searchThreadsAndMessages("fox");
    expect(hits).toHaveLength(1);
    expect(hits[0]!.thread.id).toBe("t1");
    expect(hits[0]!.snippet?.toLowerCase()).toContain("fox");
  });

  it("returns empty when nothing matches", async () => {
    mockThreadsToArray.mockResolvedValue([
      {
        id: "t1",
        title: "Zed",
        createdAt: 1,
        updatedAt: 2,
        archived: false,
      },
    ]);
    mockMessagesFilter.mockResolvedValue([]);
    expect(await searchThreadsAndMessages("nope")).toEqual([]);
  });
});import { describe, expect, it } from "vitest";

import {
  deleteUIMessageById,
  findPreviousUserMessage,
  updateUIMessageText,
} from "@/lib/chat-utils";
import type { UIMessage } from "ai";

function msg(
  id: string,
  role: "user" | "assistant",
  text: string,
): UIMessage {
  return {
    id,
    role,
    parts: [{ type: "text", text }],
  };
}

describe("chat-utils message helpers", () => {
  it("updateUIMessageText changes text part", () => {
    const rows: UIMessage[] = [msg("u1", "user", "hi")];
    const next = updateUIMessageText(rows, "u1", "yo");
    expect(next[0]!.parts).toEqual([{ type: "text", text: "yo" }]);
  });

  it("deleteUIMessageById removes one id", () => {
    const rows: UIMessage[] = [msg("a", "user", "1"), msg("b", "assistant", "2")];
    expect(deleteUIMessageById(rows, "a").map((m) => m.id)).toEqual(["b"]);
  });

  it("findPreviousUserMessage finds nearest previous user", () => {
    const rows: UIMessage[] = [
      msg("1", "user", "a"),
      msg("2", "assistant", "b"),
      msg("3", "user", "c"),
      msg("4", "assistant", "d"),
    ];
    expect(findPreviousUserMessage(rows, "4")?.id).toBe("3");
  });
});import { describe, expect, it } from "vitest";
import type { UIMessage } from "ai";

import { dedupeUIMessagesById, textFromParts } from "./chat-utils";

function u(
  id: string,
  text: string,
  role: "user" | "assistant" = "user",
): UIMessage {
  return {
    id,
    role,
    parts: [{ type: "text", text }],
  };
}

describe("dedupeUIMessagesById", () => {
  it("removes duplicate ids while preserving first-seen order (last payload wins)", () => {
    const out = dedupeUIMessagesById([
      u("a", "first-a"),
      u("b", "bee"),
      u("a", "second-a"),
    ]);
    expect(out.map((m) => m.id)).toEqual(["a", "b"]);
    expect(textFromParts(out[0]!)).toBe("second-a");
    expect(textFromParts(out[1]!)).toBe("bee");
  });

  it("is a no-op when ids are already unique", () => {
    const rows = [u("1", "x"), u("2", "y")];
    expect(dedupeUIMessagesById(rows)).toEqual(rows);
  });
