  --trinity-sidebar-border: rgba(255, 255, 255, 0.2);
  --trinity-sidebar-highlight: rgba(255, 255, 255, 0.24);
  --trinity-sidebar-inner-shadow: inset 0 -12px 32px rgba(0, 0, 0, 0.24);
  --trinity-sidebar-float-shadow:
    0 26px 56px -32px rgba(12, 16, 24, 0.52),
    0 10px 28px -18px rgba(24, 32, 44, 0.36);

  /* ── Sidebar chrome: liquid glass v2 — transparent core, shine at edges ── */
  --trinity-liquid-text: rgba(228, 233, 238, 0.86);
  --trinity-liquid-text-strong: rgba(248, 250, 252, 0.96);
  --trinity-liquid-muted: rgba(206, 214, 222, 0.62);
  --trinity-liquid-clear-center: rgba(10, 13, 17, 0.28);
  --trinity-liquid-clear-fill: rgba(22, 26, 32, 0.34);
  --trinity-liquid-hover-fill: rgba(38, 44, 52, 0.44);
  --trinity-liquid-top-sheen: rgba(255, 255, 255, 0.82);
  --trinity-liquid-specular: rgba(255, 255, 255, 0.95);
  --trinity-liquid-cyan-edge: rgba(255, 255, 255, 0.32);
  --trinity-liquid-cyan-hotspot: rgba(255, 255, 255, 0.38);
  --trinity-liquid-blue-shadow: rgba(0, 0, 0, 0.42);
  /* Aliases — older selectors still reference these tokens */
  --trinity-liquid-blue-base: var(--trinity-liquid-clear-fill);
  --trinity-liquid-blue-fill: var(--trinity-liquid-hover-fill);
  --trinity-liquid-blue-edge: var(--trinity-liquid-cyan-edge);
  --trinity-liquid-white-edge: rgba(255, 255, 255, 0.78);
  --trinity-liquid-hotspot: var(--trinity-liquid-cyan-hotspot);
  --trinity-liquid-shadow: var(--trinity-liquid-blue-shadow);
}

.spirit-trinity-atmosphere {
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.spirit-trinity-atmosphere__base {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--trinity-backdrop-base);
  filter: blur(0.35px) saturate(118%);
}

.spirit-trinity-atmosphere__grid {
  position: absolute;
  inset: 0;
  z-index: 1;
  opacity: 0.94;
  background-image: var(--trinity-backdrop-architecture);
  background-size: auto;
  filter: blur(16px) saturate(124%) contrast(1.03);
  transform: scale(1.04);
  pointer-events: none;
}

.spirit-trinity-atmosphere__wash {
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    var(--ddv4-atmos-wash),
    var(--trinity-backdrop-diagonal-light);
  opacity: 0.88;
  mix-blend-mode: normal;
}

.spirit-trinity-atmosphere__veil {
  position: absolute;
  inset: 0;
  z-index: 3;
  background: var(--trinity-charcoal-tint);
  opacity: 0.64;
  pointer-events: none;
}

/* Content stack above atmosphere (grid/wash are paint-only, pointer-events: none). */
.spirit-trinity-live-chat {
  position: relative;
  z-index: 2;
  display: flex;
  min-height: 0;
  flex-direction: column;
  isolation: isolate;
}

.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height {
  --ddv4-nav-bg: rgba(10, 12, 16, 0.46);
  --ddv4-nav-border: rgba(255, 255, 255, 0.14);
  --ddv4-nav-fg: rgba(232, 236, 242, 0.9);
  --ddv4-nav-divider: rgba(255, 255, 255, 0.1);
  --ddv4-nav-active-bg: rgba(244, 247, 250, 0.92);
  --ddv4-nav-active-fg: rgba(10, 12, 15, 0.96);
}

.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height .dashboard-demo-v4-desktop-brand {
  padding-top: 0.25rem;
}

.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height .dashboard-demo-v4-desktop-nav-list {
  gap: 0.45rem;
}

.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height .dashboard-demo-v4-desktop-nav-item {
  min-height: 2.75rem;
  border: 1px solid transparent;
  border-radius: 0.85rem;
  opacity: 0.92;
}

.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height .dashboard-demo-v4-desktop-nav-item:not(.dashboard-demo-v4-desktop-nav-item-active) {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.1);
}

.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height .dashboard-demo-v4-desktop-theme-picker {
  border-radius: 0.8rem;
  color: rgba(226, 232, 240, 0.88);
}

.spirit-trinity-chat__desktop-header,
.spirit-trinity-chat__mobile-bar,
.spirit-trinity-chat__modebar,
.spirit-trinity-chat aside[aria-label="Spirit workspace navigation"] {
  border-color: var(--trinity-line);
  background: var(--ddv4-glass-bg);
  backdrop-filter: blur(28px) saturate(142%);
  -webkit-backdrop-filter: blur(28px) saturate(142%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    inset 0 -1px 0 rgba(0, 0, 0, 0.22),
    0 18px 48px -28px rgba(0, 0, 0, 0.45);
}

.spirit-trinity-chat__main {
  padding: 0;
}

.spirit-trinity-chat__panel {
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.spirit-trinity-chat__thread-rail {
  backdrop-filter: blur(var(--spirit-blur)) !important;
  -webkit-backdrop-filter: blur(var(--spirit-blur)) !important;
}

.spirit-trinity-chat__thread-rail input,
.spirit-trinity-chat select,
.spirit-trinity-chat textarea {
  color: var(--trinity-text);
  caret-color: var(--trinity-text);
}

.spirit-trinity-chat__thread-rail input,
.spirit-trinity-chat select {
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(8, 10, 14, 0.52);
}

.spirit-trinity-chat__thread-rail input::placeholder,
.spirit-trinity-chat textarea::placeholder {
  color: rgba(148, 163, 184, 0.55);
}

.spirit-trinity-chat__conversation {
  background: transparent;
}

.spirit-trinity-chat [data-role="assistant"] > div > div {
  max-width: min(760px, calc(100vw - 2rem));
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-left: 0;
  border-radius: 22px 22px 22px 6px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.11), transparent 62%),
    rgba(22, 26, 34, 0.52);
  box-shadow:
    0 22px 52px -36px rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(18px) saturate(130%);
  -webkit-backdrop-filter: blur(18px) saturate(130%);
}

.spirit-trinity-chat [data-role="user"] > div > div {
  max-width: min(760px, calc(100vw - 2rem));
  border-radius: 22px 22px 6px 22px;
  border-color: rgba(120, 132, 152, 0.32);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.03) 58%),
    rgba(28, 34, 44, 0.48);
  box-shadow:
    0 22px 56px -36px rgba(0, 0, 0, 0.52),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(20px) saturate(132%);
  -webkit-backdrop-filter: blur(20px) saturate(132%);
}

.spirit-trinity-chat [data-role="assistant"],
.spirit-trinity-chat [data-role="user"] {
  padding-inline: clamp(0.75rem, 2vw, 1.75rem);
}

.spirit-trinity-chat [data-role="assistant"] > div,
.spirit-trinity-chat [data-role="user"] > div {
  max-width: 780px !important;
}

.spirit-trinity-chat [data-role="assistant"] p,
.spirit-trinity-chat [data-role="user"] p {
  color: var(--trinity-text) !important;
}

.spirit-trinity-chat [data-role="assistant"] .font-mono,
.spirit-trinity-chat [data-role="user"] .font-mono {
  color: rgba(186, 198, 214, 0.88) !important;
}

.spirit-trinity-chat__composer-dock {
  position: relative;
  border-color: transparent;
  background:
    linear-gradient(to top, rgba(12, 16, 22, 0.78), rgba(18, 22, 30, 0.32), transparent);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow:
    0 -28px 64px -48px rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(18px) saturate(130%);
  -webkit-backdrop-filter: blur(18px) saturate(130%);
}

.spirit-trinity-chat__composer-surface {
  max-width: 690px !important;
  border-radius: 18px !important;
  border-color: rgba(255, 255, 255, 0.22);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.12), transparent 52%),
    rgba(10, 13, 18, 0.48);
  box-shadow:
    0 28px 76px -36px rgba(0, 0, 0, 0.58),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(24px) saturate(142%);
  -webkit-backdrop-filter: blur(24px) saturate(142%);
}

.spirit-trinity-chat__composer-surface:focus-within {
  border-color: rgba(30, 41, 59, 0.36);
  box-shadow:
    0 30px 82px -36px rgba(0, 0, 0, 0.5),
    0 0 0 1px rgba(30, 41, 59, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}

.spirit-trinity-chat__composer-surface button[type="submit"] {
  border-color: rgba(38, 49, 61, 0.46);
  background: rgba(38, 49, 61, 0.88);
  color: #ffffff;
  box-shadow: 0 12px 28px -16px rgba(15, 23, 42, 0.68);
}

.spirit-trinity-chat__modebar {
  border-color: rgba(255, 255, 255, 0.10) !important;
  background: transparent !important;
}

.spirit-trinity-mode-badge {
  max-width: none !important;
  border-color: var(--trinity-line-strong) !important;
  background: rgba(255, 255, 255, 0.08) !important;
  color: rgba(236, 242, 248, 0.92) !important;
}

.spirit-trinity-empty {
  transform: translateY(-4vh);
}

.spirit-trinity-chat__composer-surface button[type="submit"]:disabled {
  border-color: rgba(255, 255, 255, 0.28);
  background: rgba(38, 49, 61, 0.18);
  color: rgba(255, 255, 255, 0.68);
}

.spirit-trinity-chat__composer-surface textarea {
  color: var(--trinity-text) !important;
  font-size: 16px !important;
  min-height: 44px !important;
}

.spirit-trinity-chat__composer-surface textarea::placeholder {
