}

.spirit-trinity-chat__composer-chip,
.spirit-trinity-chat__composer-mode-select select {
  border-color: rgba(255, 255, 255, 0.16) !important;
  background: rgba(8, 11, 16, 0.44) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12);
}

.spirit-trinity-chat__composer-chip:hover,
.spirit-trinity-chat__composer-mode-select select:hover,
.spirit-trinity-chat__composer-mode-select select:focus {
