.spirit-trinity-chat [aria-label="Thread settings"],
.spirit-trinity-chat [aria-label="More chat options"] {
  border-color: rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.08);
  color: var(--trinity-text-soft);
}

/* Title open control is text-only — no hover/focus tile behind the name. */
.spirit-trinity-chat .spirit-trinity-chat__thread-rail button:not(.spirit-thread-row__title-button):not(.spirit-thread-row__drag-edge):not(.spirit-folder-row__drag-edge):hover,
.spirit-trinity-chat [data-testid="chat-empty-suggestions"] button:hover {
