}

.spirit-trinity-chat [class*="text-chalk/2"],
.spirit-trinity-chat [class*="text-chalk/3"],
.spirit-trinity-chat [class*="text-chalk/4"],
.spirit-trinity-chat [class*="text-chalk/5"],
