}

/* ── Trinity sidebar headings: chalk/* scan selectors steal contrast from "Chats" ── */
.spirit-trinity-chat .spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity .spirit-sidebar-trinity-chats-label,
.spirit-trinity-chat .spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity .spirit-sidebar-brand-title {
  color: var(--trinity-liquid-text-strong) !important;
  text-shadow:
    0 1px 0 rgba(255, 255, 255, 0.48),
