}

.spirit-trinity-chat .spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity .spirit-sidebar-brand-meta {
  color: color-mix(in oklab, var(--trinity-liquid-muted) 92%, rgba(13, 24, 38, 0.85)) !important;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.48) !important;
}

.spirit-trinity-chat [class*="border-white/"],
.spirit-trinity-chat [class*="border-[color:var(--spirit-border)]"] {
  border-color: var(--trinity-line) !important;
}

.spirit-trinity-chat__thread-rail button {
