}

.spirit-trinity-chat__thread-rail button[class*="bg-white/"],
.spirit-trinity-chat [class*="bg-white/[0.04]"],
.spirit-trinity-chat [class*="bg-white/[0.03]"],
.spirit-trinity-chat [class*="bg-white/[0.02]"] {
