}

/* Warm smoky depth sits behind chrome; panel fill reads as gray glass not icy strip */
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  z-index: 0;
  background:
    var(--trinity-sidebar-warm-glow),
    var(--trinity-sidebar-cool-sheen);
  opacity: 0.9;
}

.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity > * {
  position: relative;
  z-index: 1;
}

/* ── Trinity sidebar actions: transparent bubble glass (refinement v2) ── */
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"],
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"] {
  position: relative !important;
  isolation: isolate !important;
  overflow: hidden !important;
  border-radius: 999px !important;
  border-width: 1px !important;
  border-style: solid !important;
  border-color: color-mix(in oklab, var(--trinity-liquid-cyan-edge) 68%, rgba(255, 255, 255, 0.72) 32%) !important;
  background-color: var(--trinity-liquid-clear-center) !important;
  background-image:
    linear-gradient(
      180deg,
      rgba(244, 252, 255, 0.82) 0%,
      rgba(220, 245, 255, 0.26) 28%,
      rgba(184, 228, 255, 0.18) 100%
    ),
    radial-gradient(
      ellipse 120% 85% at 28% 0%,
      rgba(255, 255, 255, 0.92) 0%,
      rgba(140, 228, 255, 0.52) 26%,
      transparent 58%
    ),
    radial-gradient(ellipse 90% 70% at 90% 78%, rgba(92, 210, 248, 0.52) 0%, transparent 58%),
    radial-gradient(ellipse 80% 55% at 12% 100%, rgba(168, 228, 255, 0.32) 0%, transparent 60%) !important;
  background-blend-mode: screen, screen, soft-light, normal !important;
  color: var(--trinity-liquid-text-strong) !important;
  font-weight: 650 !important;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.45) !important;
  -webkit-font-smoothing: antialiased;
  box-shadow:
    0 12px 30px -14px var(--trinity-liquid-blue-shadow),
    0 4px 16px -8px rgba(88, 208, 246, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    inset 0 -3px 16px -5px rgba(80, 200, 240, 0.38),
    inset 0 0 0 1px rgba(255, 255, 255, 0.34),
    0 2px 8px -4px rgba(15, 23, 42, 0.07) !important;
  backdrop-filter: blur(24px) saturate(185%) brightness(1.08);
  -webkit-backdrop-filter: blur(24px) saturate(185%) brightness(1.08);
  filter: none !important;
  outline: none !important;
}

.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"]::before,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"]::before {
  content: "";
  position: absolute;
  inset: 1px 8px auto 8px;
  height: 40%;
  border-radius: inherit;
  pointer-events: none;
  z-index: 0;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.88) 0%,
    rgba(255, 255, 255, 0.22) 55%,
    transparent 100%
  );
