.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"]::after,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"]::after {
