  z-index: 1;
}

.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"] svg,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"] svg {
