.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity
  [data-sidebar-action="new-chat"]:hover:not(:disabled)::before,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity
  [data-sidebar-action="new-folder"]:hover:not(:disabled)::before {
