}

.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity
  [data-sidebar-action="new-chat"]:hover:not(:disabled)::after,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity
  [data-sidebar-action="new-folder"]:hover:not(:disabled)::after {
  opacity: 0.85;
}

.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"]:hover:not(:disabled),
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"]:hover:not(:disabled) {
  border-color: color-mix(in oklab, var(--trinity-liquid-cyan-edge) 78%, rgba(255, 255, 255, 0.88) 22%) !important;
  background-color: var(--trinity-liquid-clear-fill) !important;
  background-image:
    linear-gradient(
      180deg,
      rgba(238, 250, 255, 0.84) 0%,
      rgba(210, 242, 255, 0.24) 26%,
      rgba(176, 224, 255, 0.2) 100%
    ),
    radial-gradient(
      ellipse 118% 88% at 30% 0%,
      rgba(255, 255, 255, 0.94) 0%,
      rgba(130, 228, 255, 0.55) 24%,
      transparent 56%
    ),
    radial-gradient(ellipse 92% 72% at 88% 76%, rgba(88, 206, 246, 0.58) 0%, transparent 56%),
    radial-gradient(ellipse 82% 52% at 14% 100%, rgba(158, 226, 255, 0.34) 0%, transparent 58%) !important;
  background-blend-mode: screen, screen, soft-light, normal !important;
  box-shadow:
    0 14px 36px -12px var(--trinity-liquid-blue-shadow),
    0 0 32px -10px rgba(88, 215, 252, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.88),
    inset 0 -3px 18px -4px rgba(72, 198, 238, 0.42),
    inset 0 0 0 1px rgba(255, 255, 255, 0.46),
    0 4px 14px -6px rgba(15, 23, 42, 0.08) !important;
  filter: none !important;
}

.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"]:focus-visible,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"]:focus-visible {
