    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    inset 0 -3px 14px -5px rgba(72, 198, 238, 0.34) !important;
}

.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"]:disabled,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"]:disabled {
