  cursor: not-allowed !important;
  border-color: color-mix(in oklab, var(--trinity-liquid-cyan-edge) 62%, rgba(255, 255, 255, 0.48) 38%) !important;
  background-color: color-mix(in oklab, var(--trinity-liquid-clear-center) 85%, transparent) !important;
  background-image:
    linear-gradient(
      180deg,
      rgba(242, 250, 255, 0.46) 0%,
      rgba(228, 246, 255, 0.14) 38%,
