  }

  .spirit-trinity-chat__panel {
    border-radius: 1.5rem;
    overflow: hidden;
    /* Keep the frosted sheet off the viewport; live-chat padding does most of the work. */
    min-height: 0;
  }

  /* Route shell: breathing room so panel + sidebar float; was padding-left only → hard top/right clips. */
  .spirit-trinity-live-chat {
    padding: 1rem 1rem max(1rem, env(safe-area-inset-bottom, 0px)) var(--chat-app-rail-width);
    box-sizing: border-box;
  }
