    width: 2.5rem !important;
    height: 2.5rem !important;
  }
}

/* Phase 1: explicit dark liquid-glass surfaces over the smoky depth field. */
.spirit-trinity-liquid-glass,
.spirit-trinity-chat__panel,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity,
.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height,
.spirit-trinity-chat__composer-surface,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"],
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"] {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-color: var(--trinity-glass-border) !important;
  background:
    linear-gradient(138deg, rgba(255, 255, 255, 0.09), transparent 34%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), transparent 58%),
    var(--trinity-glass-fill) !important;
  box-shadow: var(--trinity-glass-shadow) !important;
  backdrop-filter: blur(26px) saturate(118%) brightness(1.04);
  -webkit-backdrop-filter: blur(26px) saturate(118%) brightness(1.04);
}

.spirit-trinity-liquid-glass::before,
.spirit-trinity-chat__panel::before,
.spirit-trinity-chat__composer-surface::before,
.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height::before,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity::before,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"]::before,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"]::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background:
    linear-gradient(135deg, var(--trinity-glass-highlight), transparent 23%),
    linear-gradient(90deg, rgba(255, 255, 255, 0.2), transparent 10%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.16), transparent 18%);
  opacity: 0.8;
}

.spirit-trinity-liquid-glass::after,
.spirit-trinity-chat__panel::after,
.spirit-trinity-chat__composer-surface::after,
.spirit-trinity-chat .dashboard-demo-v4-desktop-rail-full-height::after,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity::after,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-chat"]::after,
.spirit-trinity-chat__thread-rail.spirit-trinity-sidebar--trinity [data-sidebar-action="new-folder"]::after {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: -42% -18%;
  z-index: 0;
  border-radius: inherit;
  background: linear-gradient(
    112deg,
    transparent 0 38%,
    rgba(255, 255, 255, 0.16) 45%,
    rgba(255, 255, 255, 0.045) 51%,
    transparent 61% 100%
  );
  transform: translateX(-8%) rotate(0.001deg);
  opacity: 0.7;
}

