/* Phase 1 refinement: clear glass should reveal the environment, not become gray acrylic. */
@keyframes spirit-trinity-glass-sheen {
  0% {
    transform: translateX(-34%) rotate(0.001deg);
    opacity: 0;
  }

  18% {
    opacity: 0.72;
  }

  54% {
    opacity: 0.48;
  }

  100% {
    transform: translateX(34%) rotate(0.001deg);
    opacity: 0;
  }
}

