/* ── Composer Border Cleanup B — final capsule wins over Tailwind + legacy phases ─
 * SpiritChat still ships border-t / lg:border / inset rings; liquid-glass phase
 * also paints --trinity-glass-rim + twin inset strokes. This block nukes the stack.
 *
 * B2 (screenshot corner regression): any 1px light border + rounded rect = harsh corner
 * pixels; nested inset fills read as “textarea outline”. Rim = shadow only, no stroke.
 */
.spirit-trinity-chat .spirit-trinity-chat__composer-dock {
  border: none !important;
  border-top: none !important;
  border-top-width: 0 !important;
  border-top-color: transparent !important;
  outline: none !important;
  background: linear-gradient(180deg, transparent 0%, rgba(6, 8, 11, 0.38) 62%, rgba(4, 6, 9, 0.52) 100%) !important;
  box-shadow: 0 -28px 56px -42px rgba(0, 0, 0, 0.72) !important;
}

.spirit-trinity-chat .spirit-trinity-chat__composer-surface {
  max-width: min(52rem, calc(100vw - var(--chat-app-rail-width) - var(--chat-thread-rail-width) - 3.5rem)) !important;
  border: none !important;
  border-width: 0 !important;
  border-style: none !important;
  border-color: transparent !important;
  border-radius: 1.25rem !important;
  outline: none !important;
  background:
    linear-gradient(142deg, rgba(255, 255, 255, 0.06) 0%, transparent 42%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.028), transparent 60%),
    rgba(6, 8, 11, 0.26) !important;
  /* No inset rings — they stacked with Tailwind inset_0_0_0_1px before trinity JSX strip */
  box-shadow:
    0 40px 88px -38px rgba(0, 0, 0, 0.78),
    0 14px 44px -30px rgba(0, 0, 0, 0.5) !important;
  backdrop-filter: blur(28px) saturate(116%) brightness(1.04) !important;
  -webkit-backdrop-filter: blur(28px) saturate(116%) brightness(1.04) !important;
}

.spirit-trinity-chat .spirit-trinity-chat__composer-surface::before {
  display: none !important;
}

.spirit-trinity-chat .spirit-trinity-chat__composer-surface::after {
  opacity: 0 !important;
  visibility: hidden !important;
}

.spirit-trinity-chat .spirit-trinity-chat__composer-surface:focus-within {
  border: none !important;
  outline: none !important;
  box-shadow:
    0 46px 96px -40px rgba(0, 0, 0, 0.88),
    0 18px 50px -28px rgba(0, 0, 0, 0.55),
    0 0 64px -42px rgba(120, 140, 165, 0.07) !important;
}

.spirit-trinity-chat .spirit-trinity-chat__composer-surface textarea {
  border: 0 !important;
  border-width: 0 !important;
  outline: none !important;
  outline-offset: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
  border-radius: 0.7rem !important;
  --tw-ring-width: 0 !important;
  --tw-ring-offset-width: 0 !important;
  -webkit-appearance: none !important;
  appearance: none !important;
}

