  color: rgba(212, 220, 232, 0.62) !important;
}

.spirit-trinity-chat .spirit-trinity-chat__composer-surface:focus-within textarea::placeholder {
  color: rgba(226, 232, 240, 0.72) !important;
}

.spirit-trinity-chat .spirit-trinity-chat__composer-surface button[type="submit"] {
  border-width: 0 !important;
  border-style: none !important;
  border-color: transparent !important;
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.14), transparent 54%),
    rgba(14, 17, 22, 0.58) !important;
  color: rgba(246, 248, 252, 0.96) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.14),
