/* ── Composer Border Cleanup C — panel frame was drawing the “horizontal rule” ─
 * Liquid-glass bundles .spirit-trinity-chat__panel with --trinity-glass-rim (~0.52)
 * plus inset ±1px strokes → full inner rectangle including BOTTOM edge above composer.
 * Dock sat opaque vs thread rail — blur + lighter gradient so it melts into atmos.
 */
.spirit-trinity-chat .spirit-trinity-chat__panel {
  border-color: rgba(255, 255, 255, 0.055) !important;
  border-style: solid !important;
  border-width: 1px !important;
  box-shadow:
    0 40px 100px -52px rgba(0, 0, 0, 0.74),
    inset 0 1px 0 rgba(255, 255, 255, 0.065),
    inset 1px 0 0 rgba(255, 255, 255, 0.035),
    inset -1px 0 0 rgba(255, 255, 255, 0.035) !important;
}

.spirit-trinity-chat .spirit-trinity-chat__panel::before {
  opacity: 0.32 !important;
}

.spirit-trinity-chat .spirit-trinity-chat__panel::after {
  opacity: 0 !important;
  visibility: hidden !important;
}

.spirit-trinity-chat .spirit-trinity-chat__composer-dock {
  background:
    linear-gradient(180deg, transparent 0%, rgba(8, 10, 14, 0.14) 48%, rgba(6, 8, 11, 0.26) 100%) !important;
  backdrop-filter: blur(22px) saturate(118%) brightness(1.05) !important;
  -webkit-backdrop-filter: blur(22px) saturate(118%) brightness(1.05) !important;
}

/* ── Unified Liquid Input Language C ────────────────────────────────────────────
 * One smoked-glass material for /chat controls: composer, modebar, selects, sheets,
 * research gate, voice surfaces. Portaled nodes mount on document.body — never rely
 * on .spirit-trinity-chat descendants; use [data-trinity-liquid="…"] + modal/panel hooks.
 *
 * > Extracted from: Phase “Unified Liquid Input Language C”
 * > Design language: smoked glass, soft rim, blur, no white menu slabs
 */
.spirit-trinity-chat {
  --trl-smoke: rgba(8, 10, 14, 0.42);
