// ── ChatActiveModeBadge - always know which mode is eating your tokens ─────────
import { memo } from "react";

import { getModelProfile } from "@/lib/spirit/model-profiles";
import type { ModelProfileId } from "@/lib/spirit/model-profile.types";
import { cn } from "@/lib/cn";

const toneClass: Record<string, string> = {
  neutral: "border-chalk/20 bg-white/[0.04] text-chalk/85",
  cyan: "border-[color:color-mix(in_oklab,var(--spirit-accent)_45%,transparent)] bg-[color:color-mix(in_oklab,var(--spirit-accent)_10%,transparent)] text-chalk",
  amber: "border-amber-400/35 bg-amber-500/10 text-amber-100/95",
  rose: "border-rose-400/35 bg-rose-500/10 text-rose-100/95",
  violet: "border-violet-400/35 bg-violet-500/10 text-violet-100/95",
};

export type ChatActiveModeBadgeProps = {
  profileId: ModelProfileId;
  className?: string;
  /** Single-line / tighter for mobile sub-bar */
  compact?: boolean;
};

export const ChatActiveModeBadge = memo(function ChatActiveModeBadge({
  profileId,
  className,
  compact = false,
}: ChatActiveModeBadgeProps) {
  const p = getModelProfile(profileId);
  const tone = p.badgeTone ?? "neutral";
  return (
    <div
      className={cn(
        "min-w-0 rounded-lg border px-2 py-1 shadow-[inset_0_0_0_1px_rgba(255,255,255,0.04)]",
        toneClass[tone] ?? toneClass.neutral,
        compact && "max-w-full py-0.5",
        className,
      )}
      title={`${p.label} - ${p.responseStyleSummary}`}
    >
      <p className="truncate font-mono text-[9px] font-semibold uppercase tracking-[0.16em] text-chalk/50">
        Mode: {p.shortLabel}
      </p>
      {!compact ? (
        <p className="truncate font-mono text-[10px] leading-snug text-chalk/70">
          {p.responseStyleSummary}
        </p>
      ) : (
        <p className="truncate font-mono text-[9px] leading-snug text-chalk/60">
          {p.responseStyleSummary}
        </p>
      )}
    </div>
  );
});"use client";

// ── EditableUserMessage - inline textarea: ⌃/⌘+Enter save, Esc cancel ───────────
import {
  memo,
  useCallback,
  useEffect,
  useRef,
  useState,
  type KeyboardEvent,
} from "react";

import { EditMessageToolbar } from "@/components/chat/MessageActions";
import { cn } from "@/lib/cn";

export type EditableUserMessageProps = {
  initialText: string;
  onSave: (text: string) => void;
  onCancel: () => void;
  disabled?: boolean;
};

export const EditableUserMessage = memo(function EditableUserMessage({
  initialText,
  onSave,
  onCancel,
  disabled = false,
}: EditableUserMessageProps) {
  const [draft, setDraft] = useState(initialText);
  const taRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    setDraft(initialText);
  }, [initialText]);

  useEffect(() => {
    const el = taRef.current;
    if (!el) return;
    el.focus();
    el.setSelectionRange(el.value.length, el.value.length);
  }, []);

  const commit = useCallback(() => {
    if (disabled) return;
    onSave(draft);
  }, [disabled, draft, onSave]);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.nativeEvent.isComposing) return;
      if (e.key === "Escape") {
        e.preventDefault();
        onCancel();
        return;
      }
      if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        commit();
      }
    },
    [commit, onCancel],
  );

  return (
    <div className="flex w-full min-w-0 flex-col">
      <textarea
        ref={taRef}
        value={draft}
        disabled={disabled}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={handleKeyDown}
        rows={3}
        aria-label="Edit message"
        className={cn(
          "scrollbar-hide w-full min-h-[4.5rem] resize-y rounded-xl border border-[color:color-mix(in_oklab,var(--spirit-accent)_35%,transparent)] bg-black/35 px-3 py-2 font-sans text-[15px] text-chalk outline-none",
          "focus:ring-1 focus:ring-[color:color-mix(in_oklab,var(--spirit-accent)_30%,transparent)]",
          "disabled:opacity-40",
        )}
      />
      <EditMessageToolbar onSave={commit} onCancel={onCancel} disabled={disabled} />
    </div>
  );
});// ── hydrate-sources-markdown - fix cosplay Sources when header has real URLs ─────
// > Colocated with MessageMarkdown so the client bundle always resolves this module
//   (avoids “hydrateDegenerateSourcesMarkdown is not defined” from path/bundler drift).

import type { SpiritWebSourcesHeaderPayload } from "@/lib/spirit/spirit-web-sources";

function pickSourceLabel(title: string, url: string): string {
  const t = title?.trim().replace(/[\[\]]/g, "");
  if (t && t.length > 0) return t.length > 120 ? `${t.slice(0, 117)}…` : t;
  try {
    const u = new URL(url);
    const host = u.hostname.replace(/^www\./, "");
    const path = u.pathname === "/" ? "" : u.pathname;
    const s = (host + path).replace(/\/$/, "");
    return s.length > 120 ? `${s.slice(0, 117)}…` : s || host;
  } catch {
    return url.length > 100 ? `${url.slice(0, 97)}…` : url;
  }
}

/** True when Sources body looks like citation stubs (1 / 2 / [1](url)) with no real titles. */
export function isDegenerateSourcesBlock(section: string): boolean {
  const lines = section
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.length > 0);
  if (lines.length === 0) return true;
  let good = 0;
  let bad = 0;
  for (const line of lines) {
    if (/^\d+\.\s*\[[^\d\]]/.test(line) || /^\d+\.\s*https?:\/\//i.test(line) || /^[-*]\s*\[[^\d\]]/.test(line)) {
      good++;
    } else if (
      /^\d+\.\s*\d+\s*$/.test(line) ||
      /^\d+\.\s*\[\d{1,2}\]\(https?:/i.test(line) ||
      /^\d+\.\s*$/.test(line) ||
      /^[-*]\s*\d{1,2}\s*$/.test(line)
    ) {
      bad++;
    } else {
      return false;
    }
  }
  return good === 0 && bad > 0;
}

/**
 * If `## Sources` is degenerate and we have server header sources, replace that block
 * with markdown link bullets so MessageMarkdown shows real labels, not bare `1` / `2`.
 */
export function hydrateDegenerateSourcesMarkdown(
  md: string,
  payload: SpiritWebSourcesHeaderPayload | null | undefined,
): string {
  if (!payload?.sources?.length) return md;
  const m = md.match(/(?:^|\n)(##\s*sources\s*\n)/im);
  if (!m || m.index === undefined) return md;
  const headingLen = m[0].length;
  const introEnd = m.index + headingLen;
  const rest = md.slice(introEnd);
  const nextH2 = rest.search(/\n##\s+/i);
  const blockEnd = nextH2 === -1 ? md.length : introEnd + nextH2;
  const section = md.slice(introEnd, blockEnd).trimEnd();
  if (!isDegenerateSourcesBlock(section)) return md;

  const bullets = payload.sources
    .filter((s) => /^https?:\/\//i.test((s.url ?? "").trim()))
    .map((s) => {
      const url = (s.url ?? "").trim();
      const label = pickSourceLabel(s.title ?? "", url);
      return `- [${label}](${url})`;
    })
    .join("\n");
  if (!bullets) return md;

  const prefix = md.slice(m.index, introEnd);
  const tail = md.slice(blockEnd);
  return `${md.slice(0, m.index)}${prefix}${bullets}\n${tail.replace(/^\n+/, "")}`.replace(
    /\n{3,}/g,
    "\n\n",
  );
}"use client";

// ── MessageMarkdown - assistant-only markdown (react-markdown + GFM, no raw HTML) ─
import type { Components } from "react-markdown";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { memo, useMemo } from "react";

import { cn } from "@/lib/cn";
import { hydrateDegenerateSourcesMarkdown } from "@/components/chat/hydrate-sources-markdown";
import type { SpiritWebSourcesHeaderPayload } from "@/lib/spirit/spirit-web-sources";

export type MessageMarkdownProps = {
  text: string;
  className?: string;
  /** When set, degenerate `## Sources` stubs are rewritten from server header (Prompt 10B). */
  webSourcesSnapshot?: SpiritWebSourcesHeaderPayload | null;
};

export const MessageMarkdown = memo(function MessageMarkdown({
  text,
  className,
  webSourcesSnapshot,
}: MessageMarkdownProps) {
  const displayText = useMemo(
    () => hydrateDegenerateSourcesMarkdown(text, webSourcesSnapshot ?? null),
    [text, webSourcesSnapshot],
  );

  const components = useMemo<Components>(
    () => ({
      a: ({ href, children, ...rest }) => (
        <a
          href={href}
          target="_blank"
          rel="noopener noreferrer"
          className="font-medium text-[color:var(--spirit-accent-strong)] underline decoration-[color:color-mix(in_oklab,var(--spirit-accent)_55%,transparent)] underline-offset-2 hover:decoration-[color:var(--spirit-accent-strong)]"
          {...rest}
        >
          {children}
        </a>
      ),
      p: ({ children, ...rest }) => (
        <p className="mb-2 max-lg:mb-1.5 max-lg:leading-snug last:mb-0 leading-relaxed" {...rest}>
          {children}
        </p>
      ),
      ul: ({ children, ...rest }) => (
        <ul className="mb-2 list-disc space-y-1 pl-5 last:mb-0" {...rest}>
          {children}
        </ul>
      ),
      ol: ({ children, ...rest }) => (
        <ol className="mb-2 list-decimal space-y-1 pl-5 last:mb-0" {...rest}>
          {children}
        </ol>
      ),
      li: ({ children, ...rest }) => (
        <li className="leading-relaxed" {...rest}>
          {children}
        </li>
      ),
      blockquote: ({ children, ...rest }) => (
        <blockquote
          className="mb-2 border-l-2 border-[color:color-mix(in_oklab,var(--spirit-accent)_45%,transparent)] pl-3 text-chalk/80 last:mb-0"
          {...rest}
        >
          {children}
        </blockquote>
      ),
      pre: ({ children, ...rest }) => (
        <pre
          className="mb-2 max-w-full overflow-x-auto rounded-lg border border-[color:color-mix(in_oklab,var(--spirit-border)_55%,transparent)] bg-black/55 p-3 text-[13px] last:mb-0"
          {...rest}
        >
          {children}
        </pre>
      ),
      code: ({ className: codeClass, children, ...rest }) => {
        const isBlock = Boolean(codeClass?.includes("language-"));
        if (isBlock) {
          return (
            <code
              className={cn(
                "block font-mono text-[13px] leading-relaxed text-chalk/92",
                codeClass,
              )}
              {...rest}
            >
              {children}
            </code>
          );
        }
        return (
          <code
            className={cn(
              "rounded px-1 py-0.5 font-mono text-[13px]",
              "border border-[color:color-mix(in_oklab,var(--spirit-border)_40%,transparent)] bg-black/40 text-[color:color-mix(in_oklab,var(--spirit-accent-strong)_88%,var(--spirit-fg))]",
            )}
            {...rest}
          >
            {children}
          </code>
        );
      },
      strong: ({ children, ...rest }) => (
        <strong className="font-semibold text-chalk" {...rest}>
          {children}
        </strong>
      ),
      em: ({ children, ...rest }) => (
        <em className="italic text-chalk/90" {...rest}>
          {children}
        </em>
      ),
    }),
    [],
  );

  return (
    <div
      className={cn(
        "prose-spirit max-w-none break-words font-sans text-[15px] text-chalk/90 max-lg:text-[16px] max-lg:leading-snug",
        className,
      )}
    >
      <ReactMarkdown remarkPlugins={[remarkGfm]} components={components}>
        {displayText}
      </ReactMarkdown>
    </div>
  );
});"use client";

// ── SpiritUserProfilePanel - Stage 4 tabs (local-only, no fake memory theater) ────
import { Trash2, X } from "lucide-react";
import { memo, useCallback, useEffect, useState } from "react";

import {
  buildModeAwarePersonalizationSummary,
  buildPersonalizationSummary,
  defaultResearchSettings,
  defaultSpiritUserProfile,
  loadSpiritUserProfile,
  PERSONALIZATION_SUMMARY_MAX_CLIENT,
  saveSpiritUserProfile,
  type SpiritUserPreferenceRow,
  type SpiritUserProfileV1,
} from "@/lib/spirit/spirit-user-profile";
import { getModelProfile, MODEL_PROFILE_ORDER, MODEL_PROFILES } from "@/lib/spirit/model-profiles";
import type { ModelProfileId } from "@/lib/spirit/model-profile.types";
import { cn } from "@/lib/cn";

export type SpiritUserProfilePanelProps = {
  open: boolean;
  onClose: () => void;
  variant: "popover" | "sheet";
  anchorClassName?: string;
  onProfileChange?: () => void;
  activeModelProfileId?: ModelProfileId;
};

type ProfileTab = "overview" | "personality" | "modes" | "research" | "memory" | "server";

export const SpiritUserProfilePanel = memo(function SpiritUserProfilePanel({
  open,
  onClose,
  variant,
  anchorClassName = "",
  onProfileChange,
  activeModelProfileId = "normal-peer",
}: SpiritUserProfilePanelProps) {
  const [profile, setProfile] = useState<SpiritUserProfileV1>(() => defaultSpiritUserProfile());
  const [tab, setTab] = useState<ProfileTab>("overview");

  useEffect(() => {
    if (!open) return;
    setProfile(loadSpiritUserProfile());
    setTab("overview");
  }, [open]);

  const persist = useCallback(
    (next: SpiritUserProfileV1) => {
      setProfile(next);
      saveSpiritUserProfile(next);
      onProfileChange?.();
    },
    [onProfileChange],
  );

  const rs = profile.researchSettings ?? defaultResearchSettings();
  const modeAwareSummary = buildModeAwarePersonalizationSummary(profile, activeModelProfileId);
  const legacySummary = buildPersonalizationSummary(profile);

  const addPreference = useCallback(() => {
    const row: SpiritUserPreferenceRow = {
      id: `custom_${Date.now()}`,
      label: "New preference",
      value: "Describe what Spirit should remember.",
      source: "manual",
      confidence: "medium",
      category: "other",
    };
    persist({ ...profile, preferences: [...profile.preferences, row] });
  }, [profile, persist]);

  const updateRow = useCallback(
    (id: string, patch: Partial<SpiritUserPreferenceRow>) => {
      persist({
        ...profile,
        preferences: profile.preferences.map((p) => (p.id === id ? { ...p, ...patch } : p)),
      });
    },
    [profile, persist],
  );

  const deleteRow = useCallback(
    (id: string) => {
      persist({
        ...profile,
        preferences: profile.preferences.filter((p) => p.id !== id),
      });
    },
    [profile, persist],
  );

  const resetLocal = useCallback(() => {
    if (!window.confirm("Reset local Spirit profile to defaults?")) return;
    persist(defaultSpiritUserProfile());
  }, [persist]);

  const exportJson = useCallback(() => {
    const blob = new Blob([JSON.stringify(profile, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "spirit-user-profile.json";
    a.click();
    URL.revokeObjectURL(url);
  }, [profile]);

  const importJson = useCallback(() => {
    const raw = window.prompt("Paste JSON profile");
    if (raw === null) return;
    try {
      const o = JSON.parse(raw) as SpiritUserProfileV1;
      if (o?.version !== 1 || !Array.isArray(o.preferences)) throw new Error("bad shape");
      persist(o);
    } catch {
      window.alert("Invalid JSON profile");
    }
  }, [persist]);

  if (!open) return null;

  const sheet = variant === "sheet";
  const mode = getModelProfile(activeModelProfileId);

  const tabBtn = (id: ProfileTab, label: string, testId: string) => (
    <button
      key={id}
      type="button"
      role="tab"
      aria-selected={tab === id}
      data-testid={testId}
      onClick={() => setTab(id)}
      className={cn(
        "shrink-0 rounded-md px-2 py-1.5 font-mono text-[9px] font-semibold uppercase tracking-wide transition",
        tab === id
          ? "bg-[color:color-mix(in_oklab,var(--spirit-accent)_22%,transparent)] text-[color:var(--spirit-accent-strong)]"
          : "text-chalk/50 hover:bg-white/[0.05] hover:text-chalk/75",
      )}
    >
      {label}
    </button>
  );

  return (
    <>
      <button
        type="button"
        aria-label="Close profile panel"
        className="fixed inset-0 z-[140] bg-black/55 backdrop-blur-[2px]"
        onClick={onClose}
      />
      <div
        className={cn(
          "fixed z-[150] flex max-h-[80vh] w-[min(100vw-1rem,min(760px,92vw))] flex-col overflow-hidden rounded-xl border border-[color:var(--spirit-border)] bg-[color:color-mix(in_oklab,var(--spirit-bg)_94%,black)] shadow-[0_24px_80px_-24px_rgba(0,0,0,0.75)]",
          sheet
            ? "inset-x-0 bottom-0 mx-auto max-h-[80vh] w-full max-w-lg rounded-b-none rounded-t-2xl border-b-0 pb-[env(safe-area-inset-bottom,0px)]"
            : "right-3 top-[3.25rem] max-lg:right-2 max-lg:top-[6.5rem]",
          anchorClassName,
        )}
        role="dialog"
        aria-modal="true"
        aria-labelledby="spirit-profile-heading"
      >
        <div className="flex items-center justify-between gap-2 border-b border-[color:var(--spirit-border)] px-3 py-2">
          <div className="min-w-0 flex-1">
            <h2
              id="spirit-profile-heading"
              className="font-mono text-[11px] font-semibold uppercase tracking-wider text-chalk"
            >
              Spirit profile
            </h2>
            <p className="mt-0.5 font-mono text-[9px] leading-snug text-amber-200/80">
              Local only - full automatic learning ships later.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-chalk/60 transition hover:bg-white/[0.06] hover:text-chalk"
            aria-label="Close"
          >
            <X className="h-4 w-4" aria-hidden />
          </button>
        </div>
        <div
          className="scrollbar-hide flex shrink-0 gap-1 overflow-x-auto border-b border-[color:color-mix(in_oklab,var(--spirit-border)_55%,transparent)] px-2 py-1.5"
          role="tablist"
        >
          {tabBtn("overview", "Overview", "spirit-profile-tab-overview")}
          {tabBtn("personality", "Personality", "spirit-profile-tab-personality")}
          {tabBtn("modes", "Modes", "spirit-profile-tab-modes")}
          {tabBtn("research", "Research", "spirit-profile-tab-research")}
          {tabBtn("memory", "Memory", "spirit-profile-tab-memory")}
          {tabBtn("server", "Server", "spirit-profile-tab-server")}
        </div>
        <div className="scrollbar-hide min-h-0 flex-1 space-y-3 overflow-y-auto px-3 py-2">
          {tab === "overview" ? (
            <div data-testid="spirit-profile-tab-panel-overview" className="space-y-2 font-mono text-[10px] text-chalk/75">
              <p className="text-chalk/50">
                Active chat mode: <span className="text-chalk">{mode.shortLabel}</span>
              </p>
              <p>Spirit is local-only for now. Rows below are editable and optionally sent as a compact summary.</p>
              <ul className="list-disc space-y-1 pl-4">
                {profile.preferences.slice(0, 6).map((p) => (
                  <li key={p.id}>
                    <span className="text-chalk">{p.label}:</span> {p.value}
                  </li>
                ))}
              </ul>
            </div>
          ) : null}

          {tab === "personality" ? (
            <div data-testid="spirit-profile-tab-panel-personality" className="space-y-2">
              <p className="font-mono text-[9px] font-semibold uppercase tracking-[0.16em] text-chalk/40">
                Personality stats · editable rows
              </p>
              {profile.preferences.map((row) => (
                <div
                  key={row.id}
                  className="rounded-lg border border-[color:color-mix(in_oklab,var(--spirit-border)_45%,transparent)] bg-white/[0.03] p-2"
                >
                  <input
                    value={row.label}
                    onChange={(e) => updateRow(row.id, { label: e.target.value, source: "manual" })}
                    className="mb-1 w-full bg-transparent font-mono text-[10px] font-semibold text-chalk outline-none"
                  />
                  <textarea
                    value={row.value}
                    onChange={(e) => updateRow(row.id, { value: e.target.value, source: "manual" })}
                    rows={2}
                    className="w-full resize-none bg-black/20 px-1.5 py-1 font-mono text-[10px] text-chalk/80 outline-none"
                  />
                  <div className="mt-1 flex flex-wrap gap-2 font-mono text-[9px] text-chalk/50">
                    <label>
                      confidence{" "}
                      <select
                        value={row.confidence ?? "medium"}
                        onChange={(e) =>
                          updateRow(row.id, {
                            confidence: e.target.value as SpiritUserPreferenceRow["confidence"],
                            source: "manual",
                          })
                        }
                        className="rounded border border-chalk/20 bg-black/30 px-1 py-0.5 text-chalk"
                      >
                        <option value="low">low</option>
                        <option value="medium">medium</option>
                        <option value="high">high</option>
                      </select>
                    </label>
                    <label className="flex items-center gap-1">
                      <input
                        type="checkbox"
                        checked={Boolean(row.wrongPerspective)}
                        onChange={(e) =>
                          updateRow(row.id, { wrongPerspective: e.target.checked, source: "manual" })
                        }
                      />
                      wrong perspective
                    </label>
                    <button
                      type="button"
                      onClick={() => deleteRow(row.id)}
                      className="ml-auto inline-flex items-center gap-1 text-rose-200/90"
                    >
                      <Trash2 className="h-3 w-3" aria-hidden />
                      remove
                    </button>
                  </div>
                  <p className="mt-1 font-mono text-[8px] text-chalk/35">source: {row.source ?? "default"}</p>
                </div>
              ))}
              <button
                type="button"
                onClick={addPreference}
                className="rounded-full border border-[color:color-mix(in_oklab,var(--spirit-accent)_42%,transparent)] px-3 py-1 font-mono text-[10px] text-[color:var(--spirit-accent-strong)]"
              >
                Add row
              </button>
            </div>
          ) : null}

          {tab === "modes" ? (
            <div data-testid="spirit-profile-tab-panel-modes" className="grid gap-2 sm:grid-cols-2">
              {MODEL_PROFILE_ORDER.map((id) => {
                const m = MODEL_PROFILES[id];
                return (
                  <div
                    key={id}
                    className="rounded-lg border border-white/[0.06] bg-black/25 p-2 font-mono text-[10px] text-chalk/75"
                  >
                    <p className="font-semibold text-chalk">{m.shortLabel}</p>
                    <p className="mt-1 text-[9px] text-chalk/55">{m.description}</p>
                    <p className="mt-1 text-[9px]">budget: {m.responseBudget ?? "-"}</p>
                  </div>
                );
              })}
            </div>
          ) : null}

          {tab === "research" ? (
            <div data-testid="spirit-profile-tab-panel-research" className="space-y-2 font-mono text-[10px] text-chalk/75">
              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={rs.webSearchDefaultResearcher}
                  onChange={(e) =>
                    persist({
                      ...profile,
                      researchSettings: { ...rs, webSearchDefaultResearcher: e.target.checked },
                    })
                  }
                />
                Web search default for Researcher: ON when checked
              </label>
              <label className="flex items-center gap-2">
                Preferred source age: last 5 years
                <input
                  type="checkbox"
                  checked={rs.preferredSourceAge === "5y"}
                  onChange={(e) =>
                    persist({
                      ...profile,
                      researchSettings: {
                        ...rs,
                        preferredSourceAge: e.target.checked ? "5y" : "any",
                      },
                    })
                  }
                />
              </label>
              <p className="text-[9px] text-chalk/45">
                Require citations / full source list / warn on failure - wired in prefs object (defaults ON).
              </p>
            </div>
          ) : null}

          {tab === "memory" ? (
            <div data-testid="spirit-profile-tab-panel-memory" className="space-y-2 font-mono text-[10px] text-chalk/75">
              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={profile.sendPersonalizationToServer}
                  onChange={(e) =>
                    persist({ ...profile, sendPersonalizationToServer: e.target.checked })
                  }
                />
                Send compact summary with chat requests
              </label>
              <div className="flex flex-wrap gap-2">
                <button type="button" onClick={resetLocal} className="rounded-md border border-chalk/20 px-2 py-1">
                  Reset defaults
                </button>
                <button type="button" onClick={exportJson} className="rounded-md border border-chalk/20 px-2 py-1">
                  Export JSON
                </button>
                <button type="button" onClick={importJson} className="rounded-md border border-chalk/20 px-2 py-1">
                  Import JSON
                </button>
              </div>
            </div>
          ) : null}

          {tab === "server" ? (
            <div data-testid="spirit-profile-tab-panel-server" className="space-y-2">
              <p className="font-mono text-[9px] text-chalk/45">
                Mode-aware summary (Researcher adds research prefs). Max {PERSONALIZATION_SUMMARY_MAX_CLIENT} chars.
              </p>
              <p data-testid="spirit-profile-server-char-count" className="font-mono text-[10px] text-[color:var(--spirit-accent-strong)]">
                {modeAwareSummary.length} characters
              </p>
              <pre className="max-h-[42vh] overflow-y-auto whitespace-pre-wrap rounded-lg border border-white/[0.06] bg-black/40 p-2 font-mono text-[10px] leading-snug text-chalk/80">
                {modeAwareSummary || "(empty - toggle send or fill prefs)"}
              </pre>
              <p className="font-mono text-[9px] text-chalk/40">Base prefs-only preview (no mode block):</p>
              <pre className="max-h-24 overflow-y-auto whitespace-pre-wrap font-mono text-[9px] text-chalk/50">
                {legacySummary || " - "}
              </pre>
            </div>
          ) : null}
        </div>
      </div>
    </>
  );
});"use client";

