  ok: true,
  collectedAt: new Date().toISOString(),
  nodes: [
    {
      id: "spirit-dell",
      label: "Spirit Dell",
      hostname: "srv",
      status: "online",
      source: "local",
      platform: "linux",
      arch: "x64",
      cpu: { model: "x", cores: 4, usagePct: 1, loadAvg: null },
      memory: { totalBytes: 8e9, freeBytes: 4e9, usedBytes: 4e9, usedPct: 50 },
      storage: { drives: [driveFromApi], collectedAt: new Date().toISOString() },
      uptimeSec: 1,
      collectedAt: new Date().toISOString(),
    },
  ],
  summary: { total: 1, online: 1, offline: 0, degraded: 0, unknown: 0 },
};

describe("HomelabStorageCard", () => {
  it("renders drive name from API", async () => {
    globalThis.fetch = vi.fn().mockResolvedValue(
      new Response(JSON.stringify(withStorage), { status: 200 }),
    );
    render(<HomelabStorageCard />);
    await waitFor(() =>
      expect(screen.getByText("TEST_CLUSTER_DRIVE_ZZ9")).toBeInTheDocument(),
    );
  });

  it("does not render legacy mock drive names unless present in API", async () => {
    globalThis.fetch = vi.fn().mockResolvedValue(
      new Response(JSON.stringify(withStorage), { status: 200 }),
    );
    render(<HomelabStorageCard />);
    await waitFor(() => expect(screen.getByText("Spirit Dell")).toBeInTheDocument());
    expect(screen.queryByText(/Samsung 980 Pro/i)).toBeNull();
    expect(screen.queryByText(/Media Vault/i)).toBeNull();
    expect(screen.queryByText(/^Archive$/i)).toBeNull();
  });

  it("shows Storage telemetry unavailable when drives list is empty", async () => {
    const empty: ClusterTelemetryResponse = {
      ...withStorage,
      nodes: [
        {
          ...withStorage.nodes[0]!,
          storage: { drives: [], collectedAt: new Date().toISOString() },
        },
      ],
    };
    globalThis.fetch = vi.fn().mockResolvedValue(
      new Response(JSON.stringify(empty), { status: 200 }),
    );
    render(<HomelabStorageCard />);
    await waitFor(() =>
      expect(screen.getByText("Storage telemetry unavailable")).toBeInTheDocument(),
    );
  });

  it("shows storage error when node.storage.error is set", async () => {
    const err: ClusterTelemetryResponse = {
      ...withStorage,
      nodes: [
        {
          ...withStorage.nodes[0]!,
          storage: {
            drives: [],
            collectedAt: new Date().toISOString(),
            error: "df exploded",
          },
        },
      ],
    };
    globalThis.fetch = vi.fn().mockResolvedValue(
      new Response(JSON.stringify(err), { status: 200 }),
    );
    render(<HomelabStorageCard />);
    await waitFor(() => expect(screen.getByText("df exploded")).toBeInTheDocument());
  });

  it("uses neutral UNKNOWN tag styling (not HDD) when drive type is UNKNOWN", async () => {
    const unknownDrive = {
      ...driveFromApi,
      id: "D:",
      name: "D:",
      mount: "D:",
      type: "UNKNOWN" as const,
    };
    const payload: ClusterTelemetryResponse = {
      ...withStorage,
      nodes: [
        {
          ...withStorage.nodes[0]!,
          storage: {
            drives: [unknownDrive],
            collectedAt: new Date().toISOString(),
          },
        },
      ],
    };
    globalThis.fetch = vi.fn().mockResolvedValue(
      new Response(JSON.stringify(payload), { status: 200 }),
    );
    render(<HomelabStorageCard />);
    await waitFor(() => expect(screen.getByLabelText("UNKNOWN")).toBeInTheDocument());
    expect(screen.getByLabelText("UNKNOWN")).toHaveClass("homelab-tag--unknown");
    expect(screen.getByLabelText("UNKNOWN")).not.toHaveClass("homelab-tag--hdd");
  });

  it("shows offline state for offline node (no fake drives)", async () => {
    const offline: ClusterTelemetryResponse = {
      ok: true,
      collectedAt: new Date().toISOString(),
      nodes: [
        {
          id: "n",
          label: "dead-node",
          hostname: null,
          status: "offline",
          source: "remote",
          platform: null,
          arch: null,
          cpu: { model: null, cores: null, usagePct: null, loadAvg: null },
          memory: { totalBytes: null, freeBytes: null, usedBytes: null, usedPct: null },
          uptimeSec: null,
          collectedAt: new Date().toISOString(),
          error: "not configured",
        },
      ],
      summary: { total: 1, online: 0, offline: 1, degraded: 0, unknown: 0 },
    };
    globalThis.fetch = vi.fn().mockResolvedValue(
      new Response(JSON.stringify(offline), { status: 200 }),
    );
    render(<HomelabStorageCard />);
    await waitFor(() => expect(screen.getByText("dead-node")).toBeInTheDocument());
    expect(screen.getByText("Offline · not configured")).toBeInTheDocument();
    expect(screen.queryByText("TEST_CLUSTER_DRIVE_ZZ9")).toBeNull();
  });
});import { render, screen, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi, beforeEach } from "vitest";
import { ThemeStrip } from "../ThemeStrip";
import { SPIRIT_PALETTES, DEFAULT_THEME_ID } from "@/theme/spiritPalettes";
import { useSpiritTheme } from "@/theme/useSpiritTheme";

const mockSetTheme = vi.fn();

vi.mock("@/theme/useSpiritTheme", () => ({
  useSpiritTheme: vi.fn(() => ({
    theme: DEFAULT_THEME_ID,
    setTheme: mockSetTheme,
  })),
}));

describe("ThemeStrip", () => {
  beforeEach(() => {
    mockSetTheme.mockClear();
  });

  it("renders one control per registry palette (add palette = add button, no ThemeStrip edit)", () => {
    render(<ThemeStrip />);
    for (const p of SPIRIT_PALETTES) {
      expect(
        screen.getByRole("button", { name: new RegExp(`${p.label} palette`, "i") }),
      ).toBeInTheDocument();
    }
    expect(SPIRIT_PALETTES.length).toBeGreaterThan(0);
  });

  it("uses frozen-water as the active palette when the hook says so", () => {
    render(<ThemeStrip />);
    const ice = SPIRIT_PALETTES.find((p) => p.id === DEFAULT_THEME_ID)!;
    const btn = screen.getByRole("button", { name: new RegExp(`${ice.label} palette`, "i") });
    expect(btn).toHaveAttribute("aria-pressed", "true");
  });

  it("clicking another palette calls setTheme with that id", () => {
    render(<ThemeStrip />);
    const sky = SPIRIT_PALETTES.find((p) => p.id === "deep-sky")!;
    fireEvent.click(
      screen.getByRole("button", { name: new RegExp(`${sky.label} palette`, "i") }),
    );
    expect(mockSetTheme).toHaveBeenCalledWith("deep-sky");
  });

  it("highlights the active palette from the hook", () => {
    vi.mocked(useSpiritTheme).mockReturnValueOnce({
      theme: "alice-seagrass",
      setTheme: mockSetTheme,
    });
    render(<ThemeStrip />);
    const sea = SPIRIT_PALETTES.find((p) => p.id === "alice-seagrass")!;
    const btn = screen.getByRole("button", { name: new RegExp(`${sea.label} palette`, "i") });
    expect(btn).toHaveAttribute("aria-pressed", "true");
    expect(btn).toHaveClass("text-[color:var(--spirit-accent-strong)]");
  });
});"use client";

