 * > Imported from client surfaces only. Animations scoped; kill them in a11y lane.
 * > Safe-area + touch: iOS notch / home indicator, Android gesture bars - Spirit
 * > refuses to let your thumb miss the mic CTA because someone loved 8px padding.
 */

/* Horizontal padding that respects notch + curved edges (viewport-fit=cover). */
.oracle-chrome-px {
  padding-left: max(0.75rem, env(safe-area-inset-left, 0px));
  padding-right: max(0.75rem, env(safe-area-inset-right, 0px));
}

@media (min-width: 640px) {
  .oracle-chrome-px {
    padding-left: max(1.25rem, env(safe-area-inset-left, 0px));
    padding-right: max(1.25rem, env(safe-area-inset-right, 0px));
  }
}

@media (min-width: 1024px) {
  .oracle-chrome-px {
    padding-left: max(1.75rem, env(safe-area-inset-left, 0px));
    padding-right: max(1.75rem, env(safe-area-inset-right, 0px));
  }
}

/* <summary> rows: iOS/Android minimum tap height (HIG ~44pt). */
.oracle-details-summary {
  min-height: 44px;
  display: flex;
  align-items: center;
  padding-top: 4px;
  padding-bottom: 4px;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

@keyframes oracle-orb-orbit-a {
  from {
    transform: rotate(0deg) skewX(-16deg);
  }
  to {
