    transform: rotate(-360deg) scale(0.95);
  }
}
@keyframes oracle-orb-wing-l {
  0%,
  100% {
    transform: rotate(-2deg) scale(0.98);
    opacity: 0.74;
  }
  50% {
    transform: rotate(-8deg) scale(1.04);
    opacity: 0.98;
  }
}
@keyframes oracle-orb-wing-r {
