  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}
@keyframes oracle-orb-pulse {
  0%,
  100% {
    transform: scale(0.96);
  }
  50% {
    transform: scale(1.05);
  }
}
@keyframes oracle-orb-hot {
  0%,
  100% {
    transform: scale(0.82);
    opacity: 0.78;
  }
