    transform: scale(1.22);
    opacity: 1;
  }
}
@keyframes oracle-orb-mote {
  0%,
  100% {
    opacity: 0.26;
    transform: translateY(0) scale(0.75);
  }
  50% {
    opacity: 0.82;
    transform: translateY(-8px) scale(1.06);
  }
}
@keyframes oracle-viz-idle {
  0%,
  100% {
    transform: scaleY(0.38);
    opacity: 0.32;
  }
  50% {
    transform: scaleY(0.62);
    opacity: 0.55;
  }
}
@keyframes oracle-viz-permission {
