.oracle-orb-wrap {
  position: relative;
  z-index: 2;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 0 22px color-mix(in oklab, var(--spirit-accent) 28%, transparent));
}

.oracle-orb-wrap--widget {
  width: min(100%, 200px);
  max-width: 220px;
  aspect-ratio: 1;
}

.oracle-orb-wrap--chamber {
  width: min(100%, 420px);
  max-width: 420px;
  aspect-ratio: 1;
}

@media (max-width: 768px) {
  .oracle-orb-wrap--chamber {
    max-width: min(100%, 300px);
  }
}

@media (max-width: 480px) {
  .oracle-orb-wrap--chamber {
    max-width: min(100%, 260px);
  }
}

.oracle-orb-svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.oracle-orb-orbit {
  fill: none;
  stroke: color-mix(in oklab, var(--spirit-accent-strong) 16%, transparent);
  stroke-width: 1;
  transform-origin: 160px 158px;
}

.oracle-orb-orbit-a {
  animation: oracle-orb-orbit-a 10s linear infinite;
}
.oracle-orb-orbit-b {
  animation: oracle-orb-orbit-b 13s linear infinite reverse;
  stroke: color-mix(in oklab, var(--spirit-accent) 18%, transparent);
}
.oracle-orb-orbit-c {
  animation: oracle-orb-orbit-c 16s linear infinite;
  stroke-dasharray: 7 12;
  opacity: 0.72;
}

.oracle-orb-wing-l {
  transform-origin: 160px 174px;
  animation: oracle-orb-wing-l 4.2s ease-in-out infinite;
}
.oracle-orb-wing-r {
  transform-origin: 160px 174px;
  animation: oracle-orb-wing-r 4.2s ease-in-out infinite;
}

.oracle-orb-energy {
  stroke: color-mix(in oklab, var(--spirit-accent-strong) 22%, transparent);
  stroke-width: 1;
}

.oracle-orb-vein {
  fill: none;
  stroke: rgba(255, 255, 255, 0.22);
  stroke-width: 1.15;
  stroke-linecap: round;
  opacity: 0.52;
}
.oracle-orb-vein--thin {
  stroke-width: 0.8;
  opacity: 0.34;
}

.oracle-orb-group {
  transform-origin: 160px 158px;
  animation: oracle-orb-hover 3.8s ease-in-out infinite;
}

.oracle-orb-outer {
  opacity: 0.95;
  animation: oracle-orb-pulse 2.8s ease-in-out infinite;
}

.oracle-orb-hot {
  fill: white;
  filter: drop-shadow(0 0 10px white) drop-shadow(0 0 24px var(--spirit-accent));
  animation: oracle-orb-hot 1.8s ease-in-out infinite;
}

.oracle-orb-mote {
  fill: color-mix(in oklab, var(--spirit-accent-strong) 62%, transparent);
  filter: drop-shadow(0 0 6px var(--spirit-glow));
  animation: oracle-orb-mote 4.6s ease-in-out infinite;
}

.oracle-orb--listening .oracle-orb-mote {
  animation-duration: 3.2s;
}
.oracle-orb--processing .oracle-orb-orbit-a {
  animation-duration: 3.6s;
}
.oracle-orb--speaking .oracle-orb-wing-l,
.oracle-orb--speaking .oracle-orb-wing-r {
  animation-duration: 2.2s;
}
.oracle-orb--error .oracle-orb-orbit {
  stroke: color-mix(in oklab, var(--color-amber) 35%, transparent);
}

.oracle-viz {
  display: flex;
  align-items: center;
