/* ── Oracle session transcript (live UIMessage rows) ─────────────────────────── */

.oracle-session {
  display: flex;
  flex-direction: column;
  border-radius: 20px;
  border: 1px solid color-mix(in oklab, var(--spirit-border) 85%, transparent);
  background: color-mix(in oklab, var(--spirit-panel) 55%, #000000);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, white 4%, transparent);
  overflow: hidden;
  min-height: 12rem;
  /* dvh/svh: mobile browser chrome won’t clip the transcript mid-gesture. */
  max-height: min(52dvh, 28rem);
}

@media (max-height: 520px) {
  .oracle-session {
    max-height: min(42dvh, 22rem);
  }
}

.oracle-session__head {
  flex-shrink: 0;
  padding: 10px max(12px, env(safe-area-inset-left, 0px)) 10px max(12px, env(safe-area-inset-right, 0px));
  border-bottom: 1px solid color-mix(in oklab, white 6%, transparent);
  font-family: var(--font-mono);
  font-size: clamp(10px, 2.8vw, 11px);
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--spirit-accent-strong) 88%, transparent);
}

.oracle-session__scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 4px 0 8px;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

/* Narrow: icon + label row, body full width. Wide: one row icon | meta | body. */
.oracle-session__row {
  display: grid;
  grid-template-columns: 36px 1fr;
  grid-template-areas:
    "icon meta"
    "body body";
  gap: 8px 12px;
  align-items: center;
  padding: 12px max(12px, env(safe-area-inset-left, 0px)) 12px max(12px, env(safe-area-inset-right, 0px));
  border-bottom: 1px solid color-mix(in oklab, white 5%, transparent);
  font-family: var(--font-mono);
}

@media (min-width: 640px) {
  .oracle-session__row {
    grid-template-columns: 32px minmax(0, 7.5rem) 1fr;
    grid-template-areas: "icon meta body";
    align-items: start;
    padding-top: 14px;
    padding-bottom: 14px;
  }
}

.oracle-session__meta {
  grid-area: meta;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.oracle-session__icon {
  grid-area: icon;
  width: 32px;
  height: 32px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in oklab, #a855f7 38%, transparent);
  color: #c4b5fd;
  flex-shrink: 0;
  align-self: start;
  margin-top: 2px;
}

.oracle-session__row--user .oracle-session__icon {
  border-color: color-mix(in oklab, var(--spirit-accent) 42%, transparent);
  color: color-mix(in oklab, var(--spirit-accent-strong) 90%, transparent);
}

.oracle-session__role {
  font-size: clamp(11px, 3vw, 12px);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #c4b5fd;
  min-width: 0;
}

.oracle-session__row--user .oracle-session__role {
  color: color-mix(in oklab, var(--spirit-accent-strong) 88%, transparent);
}

.oracle-session__body {
  grid-area: body;
  margin: 0;
  font-size: clamp(12px, 3.4vw, 14px);
  line-height: 1.55;
  color: color-mix(in oklab, var(--color-chalk) 78%, transparent);
  word-break: break-word;
  overflow-wrap: anywhere;
  min-width: 0;
}

.oracle-session__time {
  font-size: clamp(11px, 3vw, 12px);
  color: color-mix(in oklab, var(--color-chalk) 38%, transparent);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.oracle-session__empty {
  padding: 20px max(16px, env(safe-area-inset-left, 0px)) 20px max(16px, env(safe-area-inset-right, 0px));
  font-family: var(--font-mono);
  font-size: clamp(12px, 3.5vw, 14px);
  color: color-mix(in oklab, var(--color-chalk) 42%, transparent);
  line-height: 1.5;
}

.oracle-session__foot {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 10px;
  padding-left: max(12px, env(safe-area-inset-left, 0px));
  padding-right: max(12px, env(safe-area-inset-right, 0px));
  padding-bottom: max(12px, env(safe-area-inset-bottom, 0px));
  border-top: 1px solid color-mix(in oklab, white 6%, transparent);
  background: color-mix(in oklab, #000 35%, transparent);
  font-family: var(--font-mono);
  font-size: clamp(11px, 3.1vw, 12px);
  color: color-mix(in oklab, var(--color-chalk) 52%, transparent);
}

.oracle-session__foot-meter {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 16px;
}
.oracle-session__foot-meter span {
  width: 3px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--spirit-accent) 55%, transparent);
  opacity: 0.55;
  animation: oracle-viz-listen 1.4s ease-in-out infinite;
}
.oracle-session__foot-meter span:nth-child(2) {
  height: 10px;
  animation-delay: 0.12s;
}
.oracle-session__foot-meter span:nth-child(3) {
  height: 14px;
  animation-delay: 0.24s;
}
.oracle-session__foot-meter span:nth-child(1) {
  height: 6px;
}
.oracle-session__foot-meter span:nth-child(4) {
  height: 8px;
  animation-delay: 0.08s;
}

.oracle-session__foot-info {
  margin-left: auto;
  min-width: 44px;
  min-height: 44px;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, white 12%, transparent);
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 700;
  color: color-mix(in oklab, var(--color-chalk) 45%, transparent);
