}

@media (prefers-reduced-motion: reduce) {
  .oracle-orb-orbit-a,
  .oracle-orb-orbit-b,
  .oracle-orb-orbit-c,
  .oracle-orb-wing-l,
  .oracle-orb-wing-r,
  .oracle-orb-group,
  .oracle-orb-outer,
