// ── OracleOrbSprite - abstract energy orb (no CDN, no <img>) ────────────────────
// > Extracted from the coded demo; SVG ids scoped with useId() so two mounts don’t
// > fight over defs. No crosshair reticle, no tail - just orb + rings + wings.

import { useId, useMemo } from "react";

import type { OracleVisualState } from "@/lib/oracle/oracle-visual-state";

export type OracleOrbSpriteProps = {
  /** Drives motion intensity classes on the wrapper. */
  visualState?: OracleVisualState;
  /** Homelab card vs /oracle chamber sizing. */
  variant?: "widget" | "chamber";
  className?: string;
};

export function OracleOrbSprite({
  visualState = "idle",
  variant = "chamber",
  className = "",
}: OracleOrbSpriteProps) {
  const uid = useId().replace(/:/g, "");
  const gid = `o${uid}`;

  const motes = useMemo(() => {
    const n = variant === "widget" ? 22 : 34;
    return Array.from({ length: n }, (_, i) => ({
      id: i,
      cx: 160 + Math.sin(i * 1.31) * (variant === "widget" ? 74 : 98),
      cy: 154 + Math.cos(i * 1.77) * (variant === "widget" ? 58 : 82),
      r: 0.85 + (i % 5) * 0.42,
      delay: `${(i % 12) * 0.13}s`,
    }));
  }, [variant]);

  return (
    <div
      data-testid="oracle-orb-sprite"
      className={`oracle-orb-wrap oracle-orb-wrap--${variant} oracle-orb--${visualState} ${className}`.trim()}
      aria-label="Oracle sprite"
      role="img"
    >
      <svg className="oracle-orb-svg" viewBox="0 0 320 320" aria-hidden>
        <defs>
          <radialGradient id={`${gid}-core`} cx="42%" cy="35%" r="65%">
            <stop offset="0%" stopColor="#ffffff" />
            <stop offset="18%" stopColor="color-mix(in oklab, var(--spirit-accent-strong) 85%, white)" />
            <stop offset="46%" stopColor="var(--spirit-accent)" />
            <stop offset="82%" stopColor="color-mix(in oklab, var(--spirit-accent) 40%, transparent)" />
            <stop offset="100%" stopColor="transparent" />
          </radialGradient>
          <linearGradient
            id={`${gid}-wl`}
            x1="154"
            x2="28"
            y1="182"
            y2="78"
            gradientUnits="userSpaceOnUse"
          >
            <stop offset="0%" stopColor="color-mix(in oklab, var(--spirit-accent-strong) 55%, transparent)" />
            <stop offset="50%" stopColor="color-mix(in oklab, var(--spirit-accent) 28%, transparent)" />
            <stop offset="100%" stopColor="transparent" />
          </linearGradient>
          <linearGradient
            id={`${gid}-wr`}
            x1="166"
            x2="292"
            y1="182"
            y2="78"
            gradientUnits="userSpaceOnUse"
          >
            <stop offset="0%" stopColor="color-mix(in oklab, var(--spirit-accent-strong) 55%, transparent)" />
            <stop offset="50%" stopColor="color-mix(in oklab, var(--spirit-accent) 28%, transparent)" />
            <stop offset="100%" stopColor="transparent" />
          </linearGradient>
          <filter id={`${gid}-glow`} x="-60%" y="-60%" width="220%" height="220%">
            <feGaussianBlur stdDeviation="5" result="blur" />
            <feColorMatrix
              in="blur"
              type="matrix"
              values="0 0 0 0 0.35  0 0 0 0 0.65  0 0 0 0 0.95  0 0 0 0.65 0"
              result="glow"
            />
            <feMerge>
              <feMergeNode in="glow" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        <ellipse className="oracle-orb-orbit oracle-orb-orbit-a" cx="160" cy="158" rx="118" ry="52" />
        <ellipse className="oracle-orb-orbit oracle-orb-orbit-b" cx="160" cy="158" rx="88" ry="118" />
        <ellipse className="oracle-orb-orbit oracle-orb-orbit-c" cx="160" cy="158" rx="128" ry="78" />

        {motes.map((m) => (
          <circle
            key={m.id}
            className="oracle-orb-mote"
            cx={m.cx}
            cy={m.cy}
            r={m.r}
            style={{ animationDelay: m.delay }}
          />
        ))}

        <g className="oracle-orb-wing-l" filter={`url(#${gid}-glow)`}>
          <path
            className="oracle-orb-energy"
            fill={`url(#${gid}-wl)`}
            d="M154 182 C132 173 104 154 72 124 C56 109 48 92 44 80 C80 86 112 102 136 128 C150 145 154 163 154 182 Z"
          />
          <path className="oracle-orb-vein" d="M148 176 C126 150 98 120 52 82" />
          <path className="oracle-orb-vein oracle-orb-vein--thin" d="M138 161 C116 140 92 118 68 96" />
        </g>

        <g className="oracle-orb-wing-r" filter={`url(#${gid}-glow)`}>
          <path
            className="oracle-orb-energy"
            fill={`url(#${gid}-wr)`}
            d="M166 182 C188 173 216 154 248 124 C264 109 272 92 276 80 C240 86 208 102 184 128 C170 145 166 163 166 182 Z"
          />
          <path className="oracle-orb-vein" d="M172 176 C194 150 222 120 268 82" />
          <path className="oracle-orb-vein oracle-orb-vein--thin" d="M182 161 C204 140 228 118 252 96" />
        </g>

        <g className="oracle-orb-group" filter={`url(#${gid}-glow)`}>
          <circle className="oracle-orb-outer" cx="160" cy="158" r="40" fill={`url(#${gid}-core)`} />
          <circle className="oracle-orb-hot" cx="160" cy="158" r="7" />
        </g>
      </svg>
    </div>
  );
}"use client";

// ── OracleSessionTranscript - live chat rows (UIMessage) for /oracle chamber ─────
// > Uses the same `transport.messages` the runtime already owns - zero fake copy.

import type { UIMessage } from "ai";
import { useMemo } from "react";

import { textFromParts } from "@/lib/chat-utils";

export type OracleSessionTranscriptProps = {
  messages: UIMessage[];
  /** Shown in the footer strip (e.g. “Listening…”, “Thinking…”). */
  activityLine: string;
  className?: string;
};

export function OracleSessionTranscript({
  messages,
  activityLine,
  className = "",
}: OracleSessionTranscriptProps) {
  const rows = useMemo(
    () => messages.filter((m) => m.role === "user" || m.role === "assistant"),
    [messages],
  );

  return (
    <section
      data-testid="oracle-session-transcript"
      aria-label="Oracle session"
      className={`oracle-session ${className}`.trim()}
    >
      <header className="oracle-session__head">Oracle session</header>

      <div className="oracle-session__scroll scrollbar-hide">
        {rows.length === 0 ? (
          <p className="oracle-session__empty">
            No messages yet - start a session and speak, or send text. Conversation from this
            Oracle lane appears here live.
          </p>
        ) : (
          rows.map((m, i) => {
            const text = textFromParts(m).trim();
            const isUser = m.role === "user";
            const slot = String(i + 1).padStart(2, "0");
            return (
              <article
                key={m.id}
                className={`oracle-session__row ${isUser ? "oracle-session__row--user" : ""}`}
              >
                <div className="oracle-session__icon" aria-hidden>
                  {isUser ? (
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                      <path
                        d="M12 12a4 4 0 1 0-4-4 4 4 0 0 0 4 4Z"
                        stroke="currentColor"
                        strokeWidth="1.6"
                      />
                      <path
                        d="M4 21a8 8 0 0 1 16 0"
                        stroke="currentColor"
                        strokeWidth="1.6"
                        strokeLinecap="round"
                      />
                    </svg>
                  ) : (
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                      <path
                        d="M12 3 13.4 7.2 18 8.5l-3.6 2.4L15.5 16 12 13.9 8.5 16l1.1-5.1L6 8.5l4.6-1.3L12 3Z"
                        fill="currentColor"
                        opacity="0.9"
                      />
                    </svg>
                  )}
                </div>
                <div className="oracle-session__meta">
                  <span className="oracle-session__role">{isUser ? "You" : "Oracle"}</span>
                  <span className="oracle-session__time" title="Message order in this session">
                    #{slot}
                  </span>
                </div>
                <p className="oracle-session__body">{text || "…"}</p>
              </article>
            );
          })
        )}
      </div>

      <footer className="oracle-session__foot">
        <div className="oracle-session__foot-meter" aria-hidden>
          <span />
          <span />
          <span />
          <span />
        </div>
        <span className="min-w-0 truncate">{activityLine}</span>
        <span className="oracle-session__foot-info" title="Live lane status" aria-hidden>
          i
        </span>
      </footer>
    </section>
  );
}"use client";

// ── OracleVoiceVisualizer - state-driven bars (+ optional mic level) ─────────────
// > Decorative lane: parent supplies `OracleVisualState` from live session logic.

import type { CSSProperties } from "react";
import { useMemo } from "react";

import type { OracleVisualState } from "@/lib/oracle/oracle-visual-state";

export type OracleVoiceVisualizerProps = {
  state: OracleVisualState;
  compact?: boolean;
  /** 0–1 live mic RMS when parent exposes it (e.g. Oracle page while recording). */
  audioLevel?: number;
  className?: string;
};

export function OracleVoiceVisualizer({
  state,
  compact = false,
  audioLevel,
  className = "",
}: OracleVoiceVisualizerProps) {
  const bars = useMemo(() => {
    const n = compact ? 18 : 26;
    return Array.from({ length: n }, (_, i) => ({
      id: i,
      h: 8 + ((i * 9) % (compact ? 18 : 30)),
      delay: `${(i % 9) * 0.052}s`,
    }));
  }, [compact]);

  const level = typeof audioLevel === "number" ? Math.min(1, Math.max(0, audioLevel)) : null;
  const levelBoost =
    state === "listening" || state === "processing" || state === "speaking";

  return (
    <div
      data-testid="oracle-voice-visualizer"
      className={`oracle-viz oracle-viz--${state} ${compact ? "oracle-viz--compact" : ""} ${className}`.trim()}
      aria-label="Oracle voice activity"
      role="img"
    >
      {bars.map((b) => {
        let h = b.h;
        if (level != null && levelBoost) {
          const wobble = 0.55 + level * 0.95 + ((b.id % 5) * 0.04 - 0.08);
          h = Math.max(5, Math.round(b.h * wobble));
        }
        return (
          <span
            key={b.id}
            className="oracle-viz__bar"
            style={
              {
                height: `${h}px`,
                animationDelay: b.delay,
              } as CSSProperties
            }
          />
        );
      })}
    </div>
  );
}"use client";

// ── Class error boundary - catches render-phase explosions from hooks/kids ────
// > Hooks can't try/catch; this is the sanctioned escape hatch. Logs loudly.
import {
  Component,
  type ErrorInfo,
  type ReactNode,
} from "react";

import { bootSplashOuterStyle } from "@/lib/boot-splash";

type Props = {
  children: ReactNode;
  /** Passed to console for grep */
  label?: string;
};

type State = { error: Error | null };

export class ClientFailSafe extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  override componentDidCatch(error: Error, info: ErrorInfo) {
    const tag = this.props.label ? `[ClientFailSafe:${this.props.label}]` : "[ClientFailSafe]";
    console.error(tag, error, info.componentStack);
  }

  override render() {
    if (this.state.error) {
      const e = this.state.error;
      return (
        <div style={bootSplashOuterStyle} role="alert">
          <div style={{ textAlign: "center", maxWidth: 480, padding: 16 }}>
            <div style={{ color: "#94a3b8" }}>Booting Spirit OS…</div>
            <p style={{ marginTop: 12, color: "#f87171", fontSize: 11, lineHeight: 1.5 }}>
              Client fault - {e.message}
            </p>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}// ── GlassPanel - default glass/card seam (static Tailwind, zero cleverness) ────
// > Extracted from: Hub + Oracle repeated glass/border/bg triplets
// > Design language: _blueprints/design_system.md - spirit-border, chalk void
import type { HTMLAttributes, ReactNode } from "react";

import { cn } from "@/lib/cn";

/** Full literal string so Tailwind JIT + motion wrappers can reuse without duplicating. */
export const glassPanelSurfaceClasses =
  "glass rounded-2xl border border-[color:var(--spirit-border)] bg-white/[0.02]";

type GlassPanelProps = {
  as?: "div" | "section" | "aside" | "article";
