  ...props
}: GlassPanelProps) {
  return (
    <Tag className={cn(glassPanelSurfaceClasses, className)} {...props}>
      {children}
    </Tag>
  );
}// ── SectionLabel - mono uppercase rail labels (panels, cards, dl rows) ────────
// > Extracted from: Diagnostics, Hub cards, Oracle panel - stop paste-widest hell
