import { act, renderHook, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { useOracleSpeechInput } from "@/hooks/useOracleSpeechInput";

type MediaRecorderInstance = {
  state: "inactive" | "recording";
  start: ReturnType<typeof vi.fn>;
  stop: ReturnType<typeof vi.fn>;
  ondataavailable: ((e: BlobEvent) => void) | null;
  onstop: ((e: Event) => void) | null;
  onerror: ((e: Event) => void) | null;
  mimeType: string;
};

const createdRecorders: MediaRecorderInstance[] = [];

function makeAnalyserMock(getLevelByte: () => number) {
  return {
    fftSize: 256,
    frequencyBinCount: 4,
    getByteFrequencyData(out: Uint8Array) {
      const v = Math.max(0, Math.min(255, Math.round(getLevelByte())));
      for (let i = 0; i < out.length; i++) out[i] = v;
    },
  } as unknown as AnalyserNode;
}

let levelByte = 200;
function setLevel(level0to1: number) {
  levelByte = Math.max(0, Math.min(255, Math.round(level0to1 * 255)));
}

function installBrowserGlobals() {
  Object.defineProperty(window, "isSecureContext", {
    value: true,
    configurable: true,
  });

  vi.stubGlobal(
    "MediaRecorder",
    class {
      static isTypeSupported() {
        return true;
      }
      state: "inactive" | "recording" = "inactive";
      mimeType = "audio/webm";
      ondataavailable: ((e: BlobEvent) => void) | null = null;
      onstop: ((e: Event) => void) | null = null;
      onerror: ((e: Event) => void) | null = null;
      start = vi.fn(() => {
        this.state = "recording";
        // Simulate data slicing - ensures the chunks array is non-empty by stop time.
        const fakeData = new Blob(["a".repeat(64)], { type: "audio/webm" });
        const ev = { data: fakeData } as unknown as BlobEvent;
        queueMicrotask(() => this.ondataavailable?.(ev));
      });
      stop = vi.fn(() => {
        this.state = "inactive";
        queueMicrotask(() => this.onstop?.(new Event("stop")));
      });
      constructor() {
        createdRecorders.push(this as unknown as MediaRecorderInstance);
      }
    },
  );

  vi.stubGlobal("navigator", {
    ...navigator,
    mediaDevices: {
      getUserMedia: vi.fn().mockResolvedValue({
        getTracks: () => [{ stop: vi.fn() }],
      }),
      enumerateDevices: vi.fn().mockResolvedValue([]),
    },
  });

  class AudioContextMock {
    createMediaStreamSource() {
      return { connect: () => {} };
    }
    createAnalyser() {
      return makeAnalyserMock(() => levelByte);
    }
    close() {
      return Promise.resolve();
    }
  }
  vi.stubGlobal("AudioContext", AudioContextMock);
  Object.defineProperty(window, "AudioContext", {
    value: AudioContextMock,
    configurable: true,
  });

  global.fetch = vi.fn().mockResolvedValue({
    ok: true,
    json: async () => ({ ok: true, text: "hello world" }),
  }) as unknown as typeof fetch;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

describe("useOracleSpeechInput", () => {
  beforeEach(() => {
    createdRecorders.length = 0;
    localStorage.clear();
    vi.unstubAllGlobals();
    installBrowserGlobals();
    setLevel(0.5);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("imports without throwing (SSR-safe module)", async () => {
    const { useOracleSpeechInput: hook } = await import("@/hooks/useOracleSpeechInput");
    expect(typeof hook).toBe("function");
  });

  it("becomes supported after mount when APIs exist", async () => {
    const { result } = renderHook(() => useOracleSpeechInput());
    await waitFor(() => expect(result.current.supported).toBe(true));
    expect(result.current.canUseMic).toBe(true);
    expect(result.current.blockedReason).toBeNull();
  });

  it("reports insecure context as blocked after mount", async () => {
    Object.defineProperty(window, "isSecureContext", { value: false, configurable: true });
    const { result } = renderHook(() => useOracleSpeechInput());
    await waitFor(() => expect(result.current.capability.mounted).toBe(true));
    expect(result.current.canUseMic).toBe(false);
    expect(result.current.blockedReason).toBe("insecure-context");
    expect(result.current.captureBlockedHint).toMatch(/HTTP/);
  });

  it("auto-stops on silence after threshold and submits transcript", async () => {
    const onAutoStop = vi.fn();
    const { result } = renderHook(() =>
      useOracleSpeechInput({
        silenceThreshold: 0.1,
        silenceDurationMs: 250,
        minRecordingMs: 100,
        onAutoStop,
      }),
    );
    await waitFor(() => expect(result.current.canUseMic).toBe(true));

    setLevel(0.4);
    await act(async () => {
      await result.current.startRecording();
    });
    expect(result.current.isRecording).toBe(true);

    await act(async () => {
      await sleep(300);
    });

    setLevel(0.0);
    await act(async () => {
      await sleep(700);
    });

    await waitFor(() => expect(result.current.isRecording).toBe(false), { timeout: 2000 });
    expect(onAutoStop).toHaveBeenCalledWith("silence");
  });

  it("does not auto-stop before minRecordingMs", async () => {
    const onAutoStop = vi.fn();
    const { result } = renderHook(() =>
      useOracleSpeechInput({
        silenceThreshold: 0.1,
        silenceDurationMs: 80,
        minRecordingMs: 3000,
        onAutoStop,
      }),
    );
    await waitFor(() => expect(result.current.canUseMic).toBe(true));

    setLevel(0.4);
    await act(async () => {
      await result.current.startRecording();
    });
    await act(async () => {
      await sleep(200);
    });
    setLevel(0.0);
    await act(async () => {
      await sleep(800);
    });

    expect(result.current.isRecording).toBe(true);
    expect(onAutoStop).not.toHaveBeenCalled();
  });

  it("voice above threshold resets silence timer", async () => {
    const { result } = renderHook(() =>
      useOracleSpeechInput({
        silenceThreshold: 0.1,
        silenceDurationMs: 400,
        minRecordingMs: 100,
      }),
    );
    await waitFor(() => expect(result.current.canUseMic).toBe(true));

    setLevel(0.5);
    await act(async () => {
      await result.current.startRecording();
    });

    // Speak.
    await act(async () => {
      await sleep(300);
    });
    // Quick gap shorter than the 400ms threshold.
    setLevel(0.0);
    await act(async () => {
      await sleep(150);
    });
    // Speak again.
    setLevel(0.5);
    await act(async () => {
      await sleep(400);
    });

    expect(result.current.isRecording).toBe(true);
  });

  it("stopRecordingAndTranscribe is idempotent", async () => {
    const { result } = renderHook(() =>
      useOracleSpeechInput({
        silenceThreshold: 0.05,
        silenceDurationMs: 5000,
        minRecordingMs: 200,
      }),
    );
    await waitFor(() => expect(result.current.canUseMic).toBe(true));

    setLevel(0.5);
    await act(async () => {
      await result.current.startRecording();
    });
    await act(async () => {
      await sleep(150);
    });

    let firstResult = "x";
    let secondResult = "x";
    await act(async () => {
      const [a, b] = await Promise.all([
        result.current.stopRecordingAndTranscribe(),
        result.current.stopRecordingAndTranscribe(),
      ]);
      firstResult = a;
      secondResult = b;
    });

    const submitted = (global.fetch as ReturnType<typeof vi.fn>).mock.calls.length;
    expect(submitted).toBe(1);
    expect([firstResult, secondResult].filter((s) => s.length > 0)).toHaveLength(1);
  });

  it("max-recording auto-stop fires after maxRecordingMs", async () => {
    const onAutoStop = vi.fn();
    const { result } = renderHook(() =>
      useOracleSpeechInput({
        silenceThreshold: 1,
        silenceDurationMs: 999_999,
        minRecordingMs: 100,
        maxRecordingMs: 400,
        onAutoStop,
      }),
    );
    await waitFor(() => expect(result.current.canUseMic).toBe(true));

    setLevel(0.9);
    await act(async () => {
      await result.current.startRecording();
    });

    await act(async () => {
      await sleep(700);
    });

    await waitFor(() => expect(result.current.isRecording).toBe(false), { timeout: 2000 });
    expect(onAutoStop).toHaveBeenCalledWith("max-duration");
  });

  it("cleanup cancels meter loop on unmount", async () => {
    const { result, unmount } = renderHook(() => useOracleSpeechInput());
    await waitFor(() => expect(result.current.canUseMic).toBe(true));

    setLevel(0.5);
    await act(async () => {
      await result.current.startRecording();
    });
    expect(result.current.isRecording).toBe(true);

    unmount();
    await sleep(150);
    // No throw and no further fetch calls.
    expect((global.fetch as ReturnType<typeof vi.fn>).mock.calls.length).toBe(0);
  });
});"use client";

// ── useChatFolders - Dexie.live folder rail (Prompt 5; no drag ghosts yet) ──────
import { useLiveQuery } from "dexie-react-hooks";
import { useCallback, useMemo } from "react";

import { db } from "@/lib/chat-db";
import type { ChatFolder } from "@/lib/chat-db.types";
import { sortFoldersByOrderThenUpdated } from "@/lib/chat-folder-utils";
import {
  createFolder as createFolderRow,
  deleteFolder as deleteFolderRow,
  updateFolderCollapsed,
  updateFolderName,
} from "@/lib/chat-persistence";

export function useChatFolders(enabled: boolean) {
  const resolved = useLiveQuery(
    () => {
      if (!enabled || !db) return [] as ChatFolder[];
      return db.folders.toArray();
    },
    [enabled],
  );

  const folders = useMemo(
    () => sortFoldersByOrderThenUpdated(resolved ?? []),
    [resolved],
  );

  const isLoading = enabled && resolved === undefined;

  const createNewFolder = useCallback(async (name: string): Promise<boolean> => {
    if (!enabled || !name.trim()) return false;
    const row = await createFolderRow(name.trim());
    return row !== undefined;
  }, [enabled]);

  const renameFolder = useCallback(
    async (id: string, name: string): Promise<boolean> => {
      if (!enabled || !name.trim()) return false;
      return updateFolderName(id, name.trim());
    },
    [enabled],
  );

  const removeFolder = useCallback(
    async (id: string) => {
      if (!enabled) return;
      await deleteFolderRow(id, { moveThreadsToRoot: true });
    },
    [enabled],
  );

  const setFolderCollapsed = useCallback(
    async (id: string, collapsed: boolean) => {
      if (!enabled) return;
      await updateFolderCollapsed(id, collapsed);
    },
    [enabled],
  );

  const toggleFolderCollapsed = useCallback(
    async (id: string) => {
      if (!enabled || !db) return;
      const row = await db.folders.get(id);
      if (!row) return;
      await updateFolderCollapsed(id, !Boolean(row.collapsed));
    },
    [enabled],
  );

  return {
    folders,
    isLoading,
    createNewFolder,
    renameFolder,
    removeFolder,
    setFolderCollapsed,
    toggleFolderCollapsed,
  };
}"use client";

// ── useChatThreads - Dexie.live thread list primitives (Prompt 3 sidebar eats this) ─
import { useLiveQuery } from "dexie-react-hooks";
import { useCallback } from "react";

import { db } from "@/lib/chat-db";
import { createThread, deleteThread, updateThreadTitle } from "@/lib/chat-persistence";
import type { ChatThread } from "@/lib/chat-db.types";

export function useChatThreads(enabled: boolean) {
  const threadsResolved = useLiveQuery(
    () => {
      if (!enabled || !db) return [];
      return db.threads.orderBy("updatedAt").reverse().toArray();
    },
    [enabled],
  );

  /** Sync `[]` when disabled skips the undefined suspense frame; Dexie awaits still start undefined while enabled */
  const threads = threadsResolved ?? ([] as ChatThread[]);
  const isLoading = enabled && threadsResolved === undefined;

  const createNewThread = useCallback(async () => {
    if (!enabled) return undefined;
    const row = await createThread({ title: "New chat" });
    return row?.id;
  }, [enabled]);

  const renameThread = useCallback(
    async (id: string, title: string) => {
      if (!enabled || !title.trim()) return;
      await updateThreadTitle(id, title.trim());
    },
    [enabled],
  );

  const removeThread = useCallback(
    async (id: string) => {
      if (!enabled) return;
      await deleteThread(id);
    },
    [enabled],
  );

  return {
    threads,
    isLoading,
    createNewThread,
    renameThread,
    removeThread,
  };
}"use client";

// ── useOracleSpeechInput - Whisper via MediaRecorder + /api/stt/transcribe ─────────
// > Oracle STT path is server-proxied Whisper - not browser Web Speech.
// > Silence-aware: amplitude meter doubles as a VAD so the user never has to click
// > "Finish thought" in normal hands-free use. Spirit refuses to call this an
// > advanced VAD - it's the simplest amplitude trick that survives hostile rooms.

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

import {
  appendOracleVoiceEvent,
  capOracleVoiceEvents,
  createOracleVoiceEvent,
  type OracleSpeechProvider,
  type OracleVoiceSessionEvent,
} from "@/lib/oracle/oracle-voice-session";
import {
  getOracleBrowserCapabilityReport,
  type OracleBrowserCapabilityBlockedReason,
  type OracleBrowserCapabilityReport,
} from "@/lib/oracle/oracle-browser-capabilities";

export const ORACLE_MIC_LS_KEY = "spirit:oracle:selectedMicId";

/** Hard cap per utterance - the user might forget about us. */
export const ORACLE_MAX_RECORDING_MS = 60_000;

/** Default silence detection knobs - tuned for "casual conversation" not dictation. */
export const ORACLE_DEFAULT_SILENCE_THRESHOLD = 0.035;
export const ORACLE_DEFAULT_SILENCE_DURATION_MS = 1200;
export const ORACLE_DEFAULT_MIN_RECORDING_MS = 700;
/** Grace before any auto-stop happens - gives the user time to start talking. */
export const ORACLE_DEFAULT_START_GRACE_MS = 600;
/** Amplitude meter polling cadence (ms). 60Hz audio reads are wasteful for VAD. */
export const ORACLE_AUDIO_LEVEL_INTERVAL_MS = 60;

const DEFAULT_TRANSCRIBE_LANG = "en";

export type OracleAudioInputDevice = {
  deviceId: string;
  label: string;
  groupId?: string;
};

export type UseOracleSpeechInputOptions = {
  /** 0..1 normalized amplitude considered "silence" below. */
  silenceThreshold?: number;
  /** Required continuous silence ms before auto-stop fires. */
  silenceDurationMs?: number;
  /** Hard floor for any auto-stop after `startRecording`. */
  minRecordingMs?: number;
  /** Hard cap per utterance. */
  maxRecordingMs?: number;
  /** When true, recording auto-stops on detected silence. */
  autoStopOnSilence?: boolean;
  onSilenceDetected?: () => void;
  onAutoStop?: (reason: "silence" | "max-duration") => void;
  onAudioLevel?: (level: number) => void;
};

export type UseOracleSpeechInputReturn = {
  provider: OracleSpeechProvider;
  supported: boolean;
  permissionState: "unknown" | "prompt" | "granted" | "denied" | "unsupported";
  devices: OracleAudioInputDevice[];
  devicesEnumerateError: string | null;
  selectedDeviceId: string | null;
  selectedDeviceLabel: string;
  setSelectedDeviceId: (id: string | null) => void;
  isRecording: boolean;
  isTranscribing: boolean;
  isListening: boolean;
  audioLevel: number;
  lastTranscript: string;
  lastError: string | null;
  /** Why capture failed (insecure context, missing API, etc). Null when usable. */
  captureBlockedHint: string | null;
  /** When page is plain http:// on a non-localhost host, same URL with https://. */
  httpsSamePageUrl: string | null;
  /** Capability report - components can show secure-context copy directly from this. */
  capability: OracleBrowserCapabilityReport;
  canUseMic: boolean;
  blockedReason: OracleBrowserCapabilityBlockedReason;
  capabilityMessage: string;
  /** True for the brief window between silence detection and the auto-stop firing. */
  silenceDetected: boolean;
  /** Continuous silence ms accumulated this recording. Resets when speech resumes. */
  silenceMs: number;
  recordingStartedAt: number | null;
  lastRecordingDurationMs: number | null;
  autoStopOnSilence: boolean;
  setAutoStopOnSilence: (value: boolean) => void;
  silenceThreshold: number;
  setSilenceThreshold: (value: number) => void;
  silenceDurationMs: number;
  setSilenceDurationMs: (value: number) => void;
  requestPermission: () => Promise<boolean>;
  refreshDevices: () => Promise<void>;
  startRecording: () => Promise<void>;
  stopRecordingAndTranscribe: () => Promise<string>;
  cancelRecording: () => void;
  clearTranscript: () => void;
};

function readLsMic(): string | null {
  if (typeof window === "undefined") return null;
  try {
    const v = window.localStorage.getItem(ORACLE_MIC_LS_KEY);
    return v?.trim() ? v.trim() : null;
  } catch {
    return null;
  }
}

function writeLsMic(id: string | null): void {
  if (typeof window === "undefined") return;
  try {
    if (id?.trim()) window.localStorage.setItem(ORACLE_MIC_LS_KEY, id.trim());
    else window.localStorage.removeItem(ORACLE_MIC_LS_KEY);
  } catch {
    /* private mode */
  }
}

function pickMimeType(): string | undefined {
  if (typeof MediaRecorder === "undefined") return undefined;
  const types = [
    "audio/webm;codecs=opus",
    "audio/webm",
    "audio/mp4",
    "audio/ogg;codecs=opus",
  ];
  for (const t of types) {
    try {
      if (MediaRecorder.isTypeSupported(t)) return t;
    } catch {
      /* ignore */
    }
  }
  return undefined;
}

export function useOracleSpeechInput(
  options: UseOracleSpeechInputOptions = {},
): UseOracleSpeechInputReturn {
  const [mounted, setMounted] = useState(false);

  const [autoStopOnSilence, setAutoStopOnSilenceState] = useState<boolean>(
    options.autoStopOnSilence ?? true,
  );
  const [silenceThreshold, setSilenceThresholdState] = useState<number>(
    options.silenceThreshold ?? ORACLE_DEFAULT_SILENCE_THRESHOLD,
  );
  const [silenceDurationMs, setSilenceDurationMsState] = useState<number>(
    options.silenceDurationMs ?? ORACLE_DEFAULT_SILENCE_DURATION_MS,
  );
  const minRecordingMs = options.minRecordingMs ?? ORACLE_DEFAULT_MIN_RECORDING_MS;
  const maxRecordingMs = options.maxRecordingMs ?? ORACLE_MAX_RECORDING_MS;

  const onSilenceDetectedRef = useRef(options.onSilenceDetected);
  const onAutoStopRef = useRef(options.onAutoStop);
  const onAudioLevelRef = useRef(options.onAudioLevel);
  useEffect(() => {
    onSilenceDetectedRef.current = options.onSilenceDetected;
    onAutoStopRef.current = options.onAutoStop;
    onAudioLevelRef.current = options.onAudioLevel;
  }, [options.onSilenceDetected, options.onAutoStop, options.onAudioLevel]);

  const autoStopRef = useRef(autoStopOnSilence);
  const thresholdRef = useRef(silenceThreshold);
  const silenceDurRef = useRef(silenceDurationMs);
  useEffect(() => {
    autoStopRef.current = autoStopOnSilence;
  }, [autoStopOnSilence]);
  useEffect(() => {
    thresholdRef.current = silenceThreshold;
  }, [silenceThreshold]);
  useEffect(() => {
    silenceDurRef.current = silenceDurationMs;
  }, [silenceDurationMs]);

  const [permissionState, setPermissionState] = useState<
    "unknown" | "prompt" | "granted" | "denied" | "unsupported"
  >("unknown");

  const [devices, setDevices] = useState<OracleAudioInputDevice[]>([]);
  const [devicesEnumerateError, setDevicesEnumerateError] = useState<string | null>(null);
  const [internalSelected, setInternalSelected] = useState<string | null>(null);
  const selectedDeviceId = internalSelected;

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [audioLevel, setAudioLevel] = useState(0);
  const [lastTranscript, setLastTranscript] = useState("");
  const [lastError, setLastError] = useState<string | null>(null);
  const [silenceDetected, setSilenceDetected] = useState(false);
  const [silenceMs, setSilenceMs] = useState(0);
  const [recordingStartedAt, setRecordingStartedAt] = useState<number | null>(null);
  const [lastRecordingDurationMs, setLastRecordingDurationMs] = useState<number | null>(null);

  const streamRef = useRef<MediaStream | null>(null);
  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<BlobPart[]>([]);
  const mimeRef = useRef<string | undefined>(undefined);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const meterIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const maxDurationTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const eventsRef = useRef<OracleVoiceSessionEvent[]>([]);
  const recordingStartTsRef = useRef<number | null>(null);
  const lastSpeechTsRef = useRef<number | null>(null);
  /** Last reason for stop - drives onAutoStop callback after the recorder finishes. */
  const stopReasonRef = useRef<"silence" | "max-duration" | "user" | null>(null);
  /** Idempotency latch - silence + Finish-now clicked on top of each other shouldn't double submit. */
  const stopInFlightRef = useRef(false);

  const emit = useCallback((row: Omit<OracleVoiceSessionEvent, "id" | "createdAt">) => {
    const ev = createOracleVoiceEvent(row);
    eventsRef.current = capOracleVoiceEvents(appendOracleVoiceEvent(eventsRef.current, ev));
  }, []);

  useEffect(() => {
    queueMicrotask(() => setMounted(true));
  }, []);

  const capability = useMemo(() => getOracleBrowserCapabilityReport(mounted), [mounted]);

  // Keep permissionState honest about API support after mount. This is a real
  // sync between an external system (browser capability flip) and our state,
  // exactly the pattern React docs allow for setState-in-effect.
  /* eslint-disable react-hooks/set-state-in-effect -- mirrors browser capability into state */
  useEffect(() => {
    if (!mounted) return;
    if (capability.canUseMic) {
      setPermissionState((p) => (p === "unsupported" ? "unknown" : p));
    } else {
      setPermissionState((p) => (p === "granted" || p === "denied" ? p : "unsupported"));
    }
  }, [mounted, capability.canUseMic]);
  /* eslint-enable react-hooks/set-state-in-effect */

  const supported = capability.canUseMic;
  const captureBlockedHint = mounted && !capability.canUseMic ? capability.userMessage : null;

  const [httpsSamePageUrl, setHttpsSamePageUrl] = useState<string | null>(null);
  useEffect(() => {
    if (typeof window === "undefined") return;
    let next: string | null = null;
    if (!window.isSecureContext && window.location.protocol === "http:") {
      const { host, pathname, search, hash } = window.location;
      next = `https://${host}${pathname}${search}${hash}`;
    }
    // eslint-disable-next-line react-hooks/set-state-in-effect -- mount-only URL helper for insecure LAN http://
    setHttpsSamePageUrl(next);
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- mount-only LS read
    setInternalSelected(readLsMic());
  }, []);

  const selectedDeviceLabel = (() => {
    if (!selectedDeviceId) return "Default microphone";
    const row = devices.find((d) => d.deviceId === selectedDeviceId);
    return row?.label ?? selectedDeviceId.slice(0, 14);
  })();

  const setSelectedDeviceId = useCallback(
    (id: string | null) => {
      setInternalSelected(id);
      writeLsMic(id);
      emit({
        type: "device_selected",
        label: id ? "Microphone selected" : "Default microphone",
        detail: id ?? undefined,
      });
    },
    [emit],
  );

  const refreshDevices = useCallback(async () => {
    setDevicesEnumerateError(null);
    if (typeof navigator === "undefined" || !navigator.mediaDevices?.enumerateDevices) {
      setDevices([]);
      setDevicesEnumerateError("Could not load microphones");
      return;
    }
    try {
      const raw = await navigator.mediaDevices.enumerateDevices();
      const inputs: OracleAudioInputDevice[] = [];
      for (const d of raw) {
        if (d.kind !== "audioinput") continue;
        inputs.push({
          deviceId: d.deviceId,
          label: d.label?.trim() ? d.label : `Microphone (${d.deviceId.slice(0, 6)}…)`,
          groupId: d.groupId || undefined,
        });
      }
      setDevices(inputs);
    } catch (e) {
      setDevices([]);
      setDevicesEnumerateError(e instanceof Error ? e.message : "Could not load microphones");
    }
  }, []);

  const stopLevelMeter = useCallback(() => {
    if (meterIntervalRef.current != null) {
      clearInterval(meterIntervalRef.current);
      meterIntervalRef.current = null;
    }
    setAudioLevel(0);
    setSilenceMs(0);
    setSilenceDetected(false);
    analyserRef.current = null;
    try {
      void audioCtxRef.current?.close();
    } catch {
      /* ignore */
    }
    audioCtxRef.current = null;
  }, []);

  const stopMediaTracks = useCallback(() => {
    const s = streamRef.current;
    streamRef.current = null;
    if (!s) return;
    for (const t of s.getTracks()) {
      try {
        t.stop();
      } catch {
        /* ignore */
      }
    }
  }, []);

  const clearMaxTimer = useCallback(() => {
    if (maxDurationTimerRef.current != null) {
      clearTimeout(maxDurationTimerRef.current);
      maxDurationTimerRef.current = null;
    }
  }, []);

  const requestPermission = useCallback(async (): Promise<boolean> => {
    setLastError(null);
    if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
      setPermissionState("unsupported");
      emit({ type: "error", label: "getUserMedia unavailable" });
      return false;
    }
    try {
      const constraints: MediaStreamConstraints = {
        audio: internalSelected ? { deviceId: { exact: internalSelected } } : true,
      };
      let stream: MediaStream;
      try {
        stream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (e) {
        const name = e instanceof DOMException ? e.name : "";
        if (name === "NotFoundError" || name === "OverconstrainedError") {
          setLastError("Selected microphone unavailable - using default.");
          stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        } else {
          throw e;
        }
      }
      for (const t of stream.getTracks()) t.stop();
      setPermissionState("granted");
      emit({ type: "permission_granted", label: "Microphone unlocked" });
      await refreshDevices();
      return true;
    } catch (e) {
      const name = e instanceof DOMException ? e.name : "";
      if (name === "NotAllowedError" || name === "PermissionDeniedError") {
        setPermissionState("denied");
        emit({ type: "permission_denied", label: "Microphone permission denied" });
      } else {
        const msg = e instanceof Error ? e.message : String(e);
        setLastError(msg);
        emit({ type: "error", label: `Mic error: ${msg}` });
      }
      return false;
    }
  }, [emit, refreshDevices, internalSelected]);

  // ── Forward decl so the meter can call into stopRecordingAndTranscribe ───────
  const stopRecordingAndTranscribeRef = useRef<() => Promise<string>>(async () => "");

  const startLevelMeter = useCallback(
    (stream: MediaStream) => {
      stopLevelMeter();
      try {
        const Ctx =
          window.AudioContext ||
          (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
        if (!Ctx) return;
        const ctx = new Ctx();
        audioCtxRef.current = ctx;
        const src = ctx.createMediaStreamSource(stream);
        const analyser = ctx.createAnalyser();
        analyser.fftSize = 256;
        src.connect(analyser);
        analyserRef.current = analyser;
        const data = new Uint8Array(analyser.frequencyBinCount);

        let lastTickAt = Date.now();
        const tick = () => {
          const a = analyserRef.current;
          if (!a) return;
          a.getByteFrequencyData(data);
          let sum = 0;
          for (let i = 0; i < data.length; i++) sum += data[i]!;
          const avg = sum / (data.length * 255);
          const level = Math.min(1, avg * 2.5);
          setAudioLevel(level);
          onAudioLevelRef.current?.(level);

          const now = Date.now();
          const dt = now - lastTickAt;
          lastTickAt = now;
          const startedAt = recordingStartTsRef.current;
          if (startedAt == null) return;
          const sinceStart = now - startedAt;

          if (level >= thresholdRef.current) {
            lastSpeechTsRef.current = now;
            setSilenceMs(0);
            setSilenceDetected(false);
            return;
          }

          // Below threshold - accrue silence.
          // Don't accrue during the start grace window - gives the user time to begin speaking.
          if (sinceStart < ORACLE_DEFAULT_START_GRACE_MS) return;
          // Hold off auto-stop until we've heard at least one frame of speech this turn,
          // so a totally silent room doesn't get auto-finished after 1.2s of dead air.
          const everSpoke = lastSpeechTsRef.current != null;
          setSilenceMs((prev) => prev + dt);

          if (!autoStopRef.current) return;
          if (sinceStart < minRecordingMs) return;
          if (!everSpoke) return;

          // Refs are the live source - `silenceMs` state lags by a tick.
          const lastSpeechAt = lastSpeechTsRef.current ?? startedAt;
          const silenceSpan = now - lastSpeechAt;
          if (silenceSpan >= silenceDurRef.current) {
            setSilenceDetected(true);
            onSilenceDetectedRef.current?.();
            stopReasonRef.current = "silence";
            void stopRecordingAndTranscribeRef.current();
          }
        };

        meterIntervalRef.current = setInterval(tick, ORACLE_AUDIO_LEVEL_INTERVAL_MS);
      } catch {
        setAudioLevel(0);
      }
    },
    [stopLevelMeter, minRecordingMs],
  );

  const cancelRecording = useCallback(() => {
    clearMaxTimer();
    const rec = recorderRef.current;
    recorderRef.current = null;
    chunksRef.current = [];
    stopReasonRef.current = "user";
    if (rec && rec.state !== "inactive") {
      try {
        rec.stop();
      } catch {
        /* ignore */
      }
    }
    stopLevelMeter();
    stopMediaTracks();
    setIsRecording(false);
    setRecordingStartedAt(null);
    recordingStartTsRef.current = null;
    lastSpeechTsRef.current = null;
    stopInFlightRef.current = false;
    emit({ type: "listening_stopped", label: "Recording cancelled" });
  }, [clearMaxTimer, emit, stopLevelMeter, stopMediaTracks]);

  const clearTranscript = useCallback(() => {
    setLastTranscript("");
  }, []);

  const stopRecordingAndTranscribe = useCallback(async (): Promise<string> => {
    // Idempotent: silence VAD and the user's "Finish now" click can race - only one wins.
    if (stopInFlightRef.current) return "";
    stopInFlightRef.current = true;

    clearMaxTimer();
    const rec = recorderRef.current;
    if (!rec || rec.state === "inactive") {
      stopLevelMeter();
      stopMediaTracks();
      setIsRecording(false);
      setRecordingStartedAt(null);
      recordingStartTsRef.current = null;
      stopInFlightRef.current = false;
      return "";
    }

    const startedAt = recordingStartTsRef.current;
    if (stopReasonRef.current === null) stopReasonRef.current = "user";
    const reasonForCallback = stopReasonRef.current;

    return await new Promise<string>((resolve) => {
      rec.onstop = () => {
        stopLevelMeter();
        stopMediaTracks();
        setIsRecording(false);
        setRecordingStartedAt(null);
        const finishedAt = Date.now();
        const duration = startedAt ? finishedAt - startedAt : null;
        setLastRecordingDurationMs(duration);
        recordingStartTsRef.current = null;
        const mime = mimeRef.current || rec.mimeType || "audio/webm";
        const blob = new Blob(chunksRef.current, { type: mime });
        chunksRef.current = [];
        if (reasonForCallback === "silence" || reasonForCallback === "max-duration") {
          onAutoStopRef.current?.(reasonForCallback);
        }
        void (async () => {
          try {
            if (blob.size < 32) {
              setLastError("No speech captured");
              emit({ type: "error", label: "Empty recording" });
              resolve("");
              return;
            }
            setIsTranscribing(true);
            try {
              const fd = new FormData();
              fd.append("audio", blob, `oracle.${mime.includes("webm") ? "webm" : "audio"}`);
              fd.append("language", DEFAULT_TRANSCRIBE_LANG);
              const res = await fetch("/api/stt/transcribe", {
                method: "POST",
                body: fd,
              });
              let json: {
                ok?: boolean;
                text?: string;
                detail?: string;
              };
              try {
                json = (await res.json()) as typeof json;
              } catch {
                setLastError("Invalid STT response");
                resolve("");
                return;
              }
              if (!res.ok || !json.ok) {
                const d = json.detail || `STT ${res.status}`;
                setLastError(d);
                emit({ type: "error", label: d });
                resolve("");
                return;
              }
              const text = typeof json.text === "string" ? json.text.trim() : "";
              setLastTranscript(text);
              if (!text) {
                setLastError("No speech detected");
              } else {
                setLastError(null);
                emit({
                  type: "transcript_ready",
                  label: "Transcript",
                  detail: text.slice(0, 120),
                });
              }
              resolve(text);
            } catch (e) {
              const msg = e instanceof Error ? e.message : String(e);
              setLastError(msg);
              resolve("");
            } finally {
              setIsTranscribing(false);
            }
          } finally {
            stopReasonRef.current = null;
            stopInFlightRef.current = false;
          }
        })();
      };
      try {
        rec.stop();
      } catch {
        stopLevelMeter();
        stopMediaTracks();
        setIsRecording(false);
        setRecordingStartedAt(null);
        recordingStartTsRef.current = null;
        stopReasonRef.current = null;
        stopInFlightRef.current = false;
        resolve("");
      }
    });
  }, [clearMaxTimer, emit, stopLevelMeter, stopMediaTracks]);

  useLayoutEffect(() => {
    stopRecordingAndTranscribeRef.current = stopRecordingAndTranscribe;
  }, [stopRecordingAndTranscribe]);

  const startRecording = useCallback(async () => {
    if (!supported) {
      setLastError(captureBlockedHint || "Recording not supported in this browser");
      return;
    }
    if (permissionState !== "granted") {
      const ok = await requestPermission();
      if (!ok) return;
    }

    cancelRecording();
    setLastError(null);
    chunksRef.current = [];
    mimeRef.current = pickMimeType();
    stopReasonRef.current = null;
    stopInFlightRef.current = false;

    let stream: MediaStream;
    try {
      stream = await navigator.mediaDevices.getUserMedia({
        audio: internalSelected ? { deviceId: { exact: internalSelected } } : true,
      });
    } catch (e) {
      const name = e instanceof DOMException ? e.name : "";
      if (name === "NotFoundError" || name === "OverconstrainedError") {
        setLastError("Selected mic failed - using default capture.");
        stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      } else {
        const msg = e instanceof Error ? e.message : String(e);
        setLastError(msg);
        emit({ type: "error", label: msg });
        return;
      }
    }

    streamRef.current = stream;
    startLevelMeter(stream);

    const opts: MediaRecorderOptions = {};
    if (mimeRef.current) opts.mimeType = mimeRef.current;
    let rec: MediaRecorder;
    try {
      rec = new MediaRecorder(stream, opts);
    } catch {
      rec = new MediaRecorder(stream);
    }
    recorderRef.current = rec;

    rec.ondataavailable = (ev) => {
      if (ev.data.size > 0) chunksRef.current.push(ev.data);
    };

    rec.onerror = () => {
      setLastError("MediaRecorder error");
    };

    rec.start(250);
    const startedAt = Date.now();
    recordingStartTsRef.current = startedAt;
    lastSpeechTsRef.current = null;
    setRecordingStartedAt(startedAt);
    setSilenceMs(0);
    setSilenceDetected(false);
    setIsRecording(true);
    emit({ type: "listening_started", label: "Recording" });

    clearMaxTimer();
    maxDurationTimerRef.current = setTimeout(() => {
      maxDurationTimerRef.current = null;
      stopReasonRef.current = "max-duration";
      void stopRecordingAndTranscribeRef.current();
    }, maxRecordingMs);
  }, [
    supported,
    captureBlockedHint,
    permissionState,
    requestPermission,
    cancelRecording,
    internalSelected,
    emit,
    startLevelMeter,
    clearMaxTimer,
    maxRecordingMs,
  ]);

  useEffect(() => {
    return () => {
      clearMaxTimer();
      cancelRecording();
    };
  }, [clearMaxTimer, cancelRecording]);

  const provider: OracleSpeechProvider = supported ? "whisper-backend" : "unsupported";

  const setAutoStopOnSilence = useCallback((value: boolean) => {
    setAutoStopOnSilenceState(value);
  }, []);
  const setSilenceThreshold = useCallback((value: number) => {
    if (!Number.isFinite(value)) return;
    const v = Math.max(0, Math.min(1, value));
    setSilenceThresholdState(v);
  }, []);
  const setSilenceDurationMs = useCallback((value: number) => {
    if (!Number.isFinite(value)) return;
    setSilenceDurationMsState(Math.max(200, Math.round(value)));
  }, []);

  return {
    provider,
    supported,
    permissionState,
    devices,
    devicesEnumerateError,
    selectedDeviceId,
    selectedDeviceLabel,
    setSelectedDeviceId,
    isRecording,
    isTranscribing,
    isListening: isRecording,
    audioLevel,
    lastTranscript,
    lastError,
    captureBlockedHint,
    httpsSamePageUrl,
    capability,
    canUseMic: capability.canUseMic,
    blockedReason: capability.blockedReason,
    capabilityMessage: capability.userMessage,
    silenceDetected,
    silenceMs,
    recordingStartedAt,
    lastRecordingDurationMs,
    autoStopOnSilence,
    setAutoStopOnSilence,
    silenceThreshold,
    setSilenceThreshold,
    silenceDurationMs,
    setSilenceDurationMs,
    requestPermission,
    refreshDevices,
    startRecording,
    stopRecordingAndTranscribe,
    cancelRecording,
    clearTranscript,
  };
}"use client";

// ── useSpiritModeRuntime - profile + personalization fields for /api/spirit (Prompt 10D) ─
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type MutableRefObject,
} from "react";

import type { ModelProfile } from "@/lib/spirit/model-profile.types";
import { getModelProfile } from "@/lib/spirit/model-profiles";
import { DEFAULT_MODEL_PROFILE_ID } from "@/lib/spirit/model-profile.types";
import type { ModelProfileId } from "@/lib/spirit/model-profile.types";
import {
  buildModeAwarePersonalizationSummary,
  loadSpiritUserProfile,
} from "@/lib/spirit/spirit-user-profile";
import type { SpiritRuntimeSurface } from "@/lib/spirit/spirit-runtime-surface";

export type SpiritThreadRuntimeModeSlice = {
  activeModelProfileId: ModelProfileId;
  setActiveModelProfile: (id: ModelProfileId) => void | Promise<void>;
};

export type UseSpiritModeRuntimeInput = {
  runtimeSurface: SpiritRuntimeSurface;
  persistenceEnabled: boolean;
  /** Dexie-backed profile focus; ignored when `persistenceEnabled` is false */
  threadRuntime: SpiritThreadRuntimeModeSlice;
};

export type SpiritModeRuntime = {
  runtimeSurface: SpiritRuntimeSurface;
  runtimeSurfaceRef: MutableRefObject<SpiritRuntimeSurface>;
  activeModelProfileId: ModelProfileId;
  activeModelProfile: ModelProfile;
  setActiveModelProfile: (id: ModelProfileId) => void | Promise<void>;
  /** Same id as state - transport reads mid-flight without rerunning effects too late */
  modelProfileIdRef: MutableRefObject<ModelProfileId>;

  personalizationSummary: string;
  personalizationEnabled: boolean;
  refreshPersonalizationPreview: () => void;

  profilePanelOpen: boolean;
  setProfilePanelOpen: (value: boolean) => void;

  requestBodyModeFields: {
    modelProfileId: ModelProfileId;
    runtimeSurface: SpiritRuntimeSurface;
    personalizationSummary?: string;
  };
};

export function useSpiritModeRuntime(
  input: UseSpiritModeRuntimeInput,
): SpiritModeRuntime {
  const [ephemeralProfileId, setEphemeralProfileId] =
    useState<ModelProfileId>(DEFAULT_MODEL_PROFILE_ID);

  const activeModelProfileId = input.persistenceEnabled
    ? input.threadRuntime.activeModelProfileId
    : ephemeralProfileId;

  const setActiveModelProfile = useCallback(
    async (id: ModelProfileId) => {
      if (input.persistenceEnabled) {
        await input.threadRuntime.setActiveModelProfile(id);
      } else {
        setEphemeralProfileId(id);
      }
    },
    [input.persistenceEnabled, input.threadRuntime],
  );

  const modelProfileIdRef = useRef(activeModelProfileId);
  const runtimeSurfaceRef = useRef(input.runtimeSurface);
  /** Bumps when profile JSON changes so personalization preview recomputes */
  const [profileEpoch, setProfileEpoch] = useState(0);
  useEffect(() => {
    modelProfileIdRef.current = activeModelProfileId;
  }, [activeModelProfileId]);
  useEffect(() => {
    runtimeSurfaceRef.current = input.runtimeSurface;
  }, [input.runtimeSurface]);
  const refreshPersonalizationPreview = useCallback(() => {
    setProfileEpoch((n: number) => n + 1);
  }, []);

  const personalizationPack = useMemo(
    () => {
      const profile = loadSpiritUserProfile();
      const summary = buildModeAwarePersonalizationSummary(
        profile,
        activeModelProfileId,
      ).trim();
      return { profile, summary };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps -- profileEpoch busts preview after profile JSON edits (refreshPersonalizationPreview)
    [activeModelProfileId, profileEpoch],
  );

  const personalizationEnabled = personalizationPack.profile.sendPersonalizationToServer;

  const [profilePanelOpen, setProfilePanelOpen] = useState(false);

  const activeModelProfile = useMemo(
    () => getModelProfile(activeModelProfileId),
    [activeModelProfileId],
  );

  const requestBodyModeFields = useMemo((): SpiritModeRuntime["requestBodyModeFields"] => {
    const base = {
      modelProfileId: activeModelProfileId,
      runtimeSurface: input.runtimeSurface,
    };
    const s = personalizationPack.summary;
    if (!s) return base;
    return { ...base, personalizationSummary: s };
  }, [activeModelProfileId, input.runtimeSurface, personalizationPack.summary]);

  return useMemo(
    (): SpiritModeRuntime => ({
      runtimeSurface: input.runtimeSurface,
      runtimeSurfaceRef,
      activeModelProfileId,
      activeModelProfile,
      setActiveModelProfile,
      modelProfileIdRef,

      personalizationSummary: personalizationPack.summary,
      personalizationEnabled,
      refreshPersonalizationPreview,

      profilePanelOpen,
      setProfilePanelOpen,

      requestBodyModeFields,
    }),
    [
      input.runtimeSurface,
      activeModelProfileId,
      activeModelProfile,
      setActiveModelProfile,
      personalizationPack.summary,
      personalizationEnabled,
      refreshPersonalizationPreview,
      profilePanelOpen,
      requestBodyModeFields,
    ],
  );
}"use client";

// ── useSpiritVoiceRuntime - TTS + speak helpers (shared by /chat and /oracle) ─────
import type { UIMessage } from "ai";
import { useCallback, useLayoutEffect, useMemo, useRef } from "react";

import { useTTS } from "@/hooks/useTTS";
import { textFromParts } from "@/lib/chat-utils";
import { sanitizeAssistantVisibleText } from "@/lib/spirit/assistant-output-sanitizer";
import {
  type SpiritActivityEvent,
} from "@/lib/spirit/spirit-activity-events";
import type { ModelProfileId } from "@/lib/spirit/model-profile.types";
import { stripFakeCitationsWhenNoSources } from "@/lib/spirit/research-source-enforcement";
import type { SpiritWebSourcesHeaderPayload } from "@/lib/spirit/spirit-web-sources";
import { pickTtsSpeakPayload } from "@/lib/tts/tts-text-budget";

export type AssistantSourceProofState = {
  messageId: string;
  hadVerifiedUrls: boolean;
  profileId: ModelProfileId;
  webSources?: SpiritWebSourcesHeaderPayload | null;
} | null;

export type SpiritTTS = ReturnType<typeof useTTS>;

export type UseSpiritVoiceRuntimeInput = {
  /** Single `useTTS()` instance shared with transport `onFinish` */
  tts: SpiritTTS;
  /** Saved-chat logging + activity spam; Oracle can silence extras */
  activityLoggingShell: boolean;
  messages: UIMessage[];
  /** Proof row from last assistant finish - researcher citation hygiene */
  assistantSourceProof: AssistantSourceProofState;
  /** Called when voice timing / errors should touch SpiritActivityPanel */
  pushActivity?: (e: Omit<SpiritActivityEvent, "id" | "at">) => void;
};

export type SpiritVoiceRuntime = {
  tts: SpiritTTS;
  speakLatestAssistant: () => Promise<void>;
  speakAssistantText: (text: string, mode: "summary" | "full-chunks") => Promise<void>;
  speakAssistantMessage: (text: string) => Promise<void>;
  speakAssistantMessageFull: (text: string) => Promise<void>;
  stop: () => void;
  assistantSpeakableText: (m: UIMessage) => string;
  activityVoiceLine: string;
};

export function useSpiritVoiceRuntime(
  input: UseSpiritVoiceRuntimeInput,
): SpiritVoiceRuntime {
  const { tts } = input;

  const pushActivity = input.pushActivity;

  const assistantSpeakableText = useCallback(
    (m: UIMessage): string => {
      const raw = textFromParts(m);
      if (m.role !== "assistant") return raw;
      let t = sanitizeAssistantVisibleText(raw);
      const stripFake =
        input.assistantSourceProof?.messageId === m.id &&
        input.assistantSourceProof.profileId === "researcher" &&
        !input.assistantSourceProof.hadVerifiedUrls;
      if (stripFake) t = stripFakeCitationsWhenNoSources(t);
      return t;
    },
    [input.assistantSourceProof],
  );

  const speakAssistantText = useCallback(
    async (text: string, mode: "summary" | "full-chunks") => {
      const ok = await tts.ensureAudioUnlocked();
      if (!ok) return;
      const plan = pickTtsSpeakPayload(text, mode);
      if (!plan.segments.length) return;
      if (plan.segments.length === 1) {
        tts.speak(plan.segments[0]!, {
          interrupt: true,
          spokenSummaryLine: plan.spokenSummaryLine,
        });
      } else {
        tts.speakMany(plan.segments, {
          interrupt: true,
          spokenSummaryLine: plan.spokenSummaryLine,
        });
      }
      if (input.activityLoggingShell && pushActivity) {
        pushActivity({ kind: "voice_played", label: plan.spokenSummaryLine });
      }
    },
    [tts, input.activityLoggingShell, pushActivity],
  );

  const speakLatestAssistant = useCallback(async () => {
    const ok = await tts.ensureAudioUnlocked();
    if (!ok) return;
    for (let i = input.messages.length - 1; i >= 0; i--) {
      const m = input.messages[i]!;
      if (m.role === "assistant") {
        await speakAssistantText(assistantSpeakableText(m), "summary");
        return;
      }
    }
  }, [input.messages, speakAssistantText, tts, assistantSpeakableText]);

  const speakAssistantMessage = useCallback(
    async (text: string) => {
      await speakAssistantText(text, "summary");
    },
    [speakAssistantText],
  );

  const speakAssistantMessageFull = useCallback(
    async (text: string) => {
      await speakAssistantText(text, "full-chunks");
    },
    [speakAssistantText],
  );

  const activityVoiceLine =
    tts.state.elevenLabsVoiceId || tts.state.voicesSource === "elevenlabs"
      ? "ElevenLabs"
      : "Piper / local";

  return useMemo(
    (): SpiritVoiceRuntime => ({
      tts,
      speakLatestAssistant,
      speakAssistantText,
      speakAssistantMessage,
      speakAssistantMessageFull,
      stop: tts.stop,
      assistantSpeakableText,
      activityVoiceLine,
    }),
    [
      tts,
      speakLatestAssistant,
      speakAssistantText,
      speakAssistantMessage,
      speakAssistantMessageFull,
      assistantSpeakableText,
      activityVoiceLine,
    ],
  );
}

/** Ref snapshot for transport `onFinish` - avoids stale hook closures during streaming */
export function useTtsSpeakGateRef(tts: SpiritTTS) {
  const ttsSpeakGateRef = useRef({ isEnabled: false, autoSpeakAssistant: false });
  useLayoutEffect(() => {
    ttsSpeakGateRef.current = {
      isEnabled: tts.state.isEnabled,
      autoSpeakAssistant: tts.state.autoSpeakAssistant,
    };
  }, [tts.state.isEnabled, tts.state.autoSpeakAssistant]);
  return ttsSpeakGateRef;
}import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

import {
  computeFolderReorderPlan,
  computeThreadDropPlan,
  fallbackNearestExcludingActive,
  getThreadLocation,
  parseDragId,
  pickThreadCollisionByVerticalMidpoints,
  resetThreadCollisionSticky,
  applyThreadOverHysteresis,
  shouldEnableChatThreadSidebarDnd,
  THREAD_DND_PREFIX,
} from "@/lib/chat-sidebar-dnd";
import type { FolderSidebarSection } from "@/lib/chat-folder-utils";
import type { ChatFolder, ChatThread } from "@/lib/chat-db.types";

function folder(id: string, order = 0, collapsed = false): ChatFolder {
  return {
    id,
    name: id,
    createdAt: 1,
    updatedAt: 1,
    order,
    collapsed,
  };
}

function thread(
  id: string,
  p: Partial<ChatThread> & { folderId?: string | null } = {},
): ChatThread {
  return {
    id,
    title: id,
    createdAt: 1,
    updatedAt: 2,
    ...p,
  };
}

describe("parseDragId", () => {
  it("parses thread ids", () => {
    expect(parseDragId(`${THREAD_DND_PREFIX}a`)).toEqual({
      kind: "thread",
      threadId: "a",
    });
  });
  it("parses root folder drop", () => {
    expect(parseDragId("folder:root")).toEqual({
      kind: "folder",
      folderId: null,
    });
  });
  it("parses nested folder drop", () => {
    expect(parseDragId("folder:f1")).toEqual({
      kind: "folder",
      folderId: "f1",
    });
  });
  it("does not treat folder-sort: as folder: (prefix collision)", () => {
    expect(parseDragId("folder-sort:f1")).toEqual({ kind: "unknown" });
  });
});

describe("getThreadLocation", () => {
  it("finds root", () => {
    const root = [thread("a")];
    const sections: FolderSidebarSection[] = [];
    expect(getThreadLocation("a", root, sections)).toEqual({ bucket: "root" });
  });
  it("finds folder bucket", () => {
    const root: ChatThread[] = [];
    const sections: FolderSidebarSection[] = [
      { folder: folder("f1"), threads: [thread("x")] },
    ];
    expect(getThreadLocation("x", root, sections)).toEqual({
      bucket: "folder",
      folderId: "f1",
    });
  });
});

describe("computeFolderReorderPlan", () => {
  it("moves folder when over id is folder-sort", () => {
    const folderSections: FolderSidebarSection[] = [
      { folder: folder("a"), threads: [] },
      { folder: folder("b"), threads: [] },
      { folder: folder("c"), threads: [] },
    ];
    expect(
      computeFolderReorderPlan({
        activeFolderId: "c",
        overId: "folder-sort:a",
        folderSections,
      }),
    ).toEqual(["c", "a", "b"]);
  });

  it("accepts thread-drop folder id as over target", () => {
    const folderSections: FolderSidebarSection[] = [
      { folder: folder("a"), threads: [] },
      { folder: folder("b"), threads: [] },
    ];
    expect(
      computeFolderReorderPlan({
        activeFolderId: "a",
        overId: "folder:b",
        folderSections,
      }),
    ).toEqual(["b", "a"]);
  });

  it("returns null when over is unrelated", () => {
    expect(
      computeFolderReorderPlan({
        activeFolderId: "a",
        overId: `${THREAD_DND_PREFIX}x`,
        folderSections: [{ folder: folder("a"), threads: [] }],
      }),
    ).toBeNull();
  });
});

describe("computeThreadDropPlan", () => {
  it("same bucket root: drag B over C -> [A,C,B,D]", () => {
    const rootThreads = [thread("A"), thread("B"), thread("C"), thread("D")];
    const ops = computeThreadDropPlan({
      activeThreadId: "B",
      overId: `${THREAD_DND_PREFIX}C`,
      rootThreads,
      folderSections: [],
    });
    expect(ops).toEqual([{ folderId: null, orderedIds: ["A", "C", "B", "D"] }]);
  });

  it("same bucket root: drag B over D -> [A,C,D,B]", () => {
    const rootThreads = [thread("A"), thread("B"), thread("C"), thread("D")];
    const ops = computeThreadDropPlan({
      activeThreadId: "B",
      overId: `${THREAD_DND_PREFIX}D`,
      rootThreads,
      folderSections: [],
    });
    expect(ops).toEqual([{ folderId: null, orderedIds: ["A", "C", "D", "B"] }]);
  });

  it("same bucket root: drag C over B -> [A,C,B,D]", () => {
    const rootThreads = [thread("A"), thread("B"), thread("C"), thread("D")];
    const ops = computeThreadDropPlan({
      activeThreadId: "C",
      overId: `${THREAD_DND_PREFIX}B`,
      rootThreads,
      folderSections: [],
    });
    expect(ops).toEqual([{ folderId: null, orderedIds: ["A", "C", "B", "D"] }]);
  });

  it("same bucket folder: drag down by one within folder list", () => {
    const rootThreads: ChatThread[] = [];
    const folderSections: FolderSidebarSection[] = [
      {
        folder: folder("f1"),
        threads: [thread("a"), thread("b"), thread("c"), thread("d")],
      },
    ];
    const ops = computeThreadDropPlan({
      activeThreadId: "b",
      overId: `${THREAD_DND_PREFIX}c`,
      rootThreads,
      folderSections,
    });
    expect(ops).toEqual([{ folderId: "f1", orderedIds: ["a", "c", "b", "d"] }]);
  });

  it("moves thread from root into empty folder (append)", () => {
    const rootThreads = [thread("a", { folderId: null })];
    const folderSections: FolderSidebarSection[] = [
      { folder: folder("f1"), threads: [] },
    ];
    const ops = computeThreadDropPlan({
      activeThreadId: "a",
      overId: "folder:f1",
      rootThreads,
      folderSections,
    });
    expect(ops).toEqual([
      { folderId: null, orderedIds: [] },
      { folderId: "f1", orderedIds: ["a"] },
    ]);
  });

  it("moves thread from folder to root", () => {
    const rootThreads: ChatThread[] = [];
    const folderSections: FolderSidebarSection[] = [
      { folder: folder("f1"), threads: [thread("a")] },
    ];
    const ops = computeThreadDropPlan({
      activeThreadId: "a",
      overId: "folder:root",
      rootThreads,
      folderSections,
    });
    expect(ops).toEqual([
      { folderId: "f1", orderedIds: [] },
      { folderId: null, orderedIds: ["a"] },
    ]);
  });

  it("uses caller-supplied root order when pinned rows precede unpinned visually but not by Dexie order", () => {
    const P = thread("p", { pinned: true, order: 3000 });
    const U1 = thread("u1", { pinned: false, order: 1000 });
    const U2 = thread("u2", { pinned: false, order: 2000 });
    const visualRoot = [P, U1, U2];
    const ops = computeThreadDropPlan({
      activeThreadId: "u2",
      overId: `${THREAD_DND_PREFIX}u1`,
      rootThreads: visualRoot,
      folderSections: [],
    });
    expect(ops).toEqual([
      { folderId: null, orderedIds: ["p", "u2", "u1"] },
    ]);
  });

  it("moves thread from folder onto root thread (insert before)", () => {
    const rootThreads = [thread("b")];
    const folderSections: FolderSidebarSection[] = [
      { folder: folder("f1"), threads: [thread("a")] },
    ];
    const ops = computeThreadDropPlan({
      activeThreadId: "a",
      overId: `${THREAD_DND_PREFIX}b`,
      rootThreads,
      folderSections,
    });
    expect(ops).toEqual([
      { folderId: "f1", orderedIds: [] },
      { folderId: null, orderedIds: ["a", "b"] },
    ]);
  });

  it("moves thread between folders", () => {
    const rootThreads: ChatThread[] = [];
    const folderSections: FolderSidebarSection[] = [
      { folder: folder("f1"), threads: [thread("a")] },
      { folder: folder("f2"), threads: [thread("b")] },
    ];
    const ops = computeThreadDropPlan({
      activeThreadId: "a",
      overId: `${THREAD_DND_PREFIX}b`,
      rootThreads,
      folderSections,
    });
    expect(ops).toEqual([
      { folderId: "f1", orderedIds: [] },
      { folderId: "f2", orderedIds: ["a", "b"] },
    ]);
  });

  it("reorders within same folder", () => {
    const rootThreads: ChatThread[] = [];
    const folderSections: FolderSidebarSection[] = [
      {
        folder: folder("f1"),
        threads: [thread("a"), thread("b"), thread("c")],
      },
    ];
    const ops = computeThreadDropPlan({
      activeThreadId: "c",
      overId: `${THREAD_DND_PREFIX}a`,
      rootThreads,
      folderSections,
    });
    expect(ops).toEqual([{ folderId: "f1", orderedIds: ["c", "a", "b"] }]);
  });

  it("reorders root list", () => {
    const rootThreads = [thread("a"), thread("b"), thread("c")];
    const ops = computeThreadDropPlan({
      activeThreadId: "c",
      overId: `${THREAD_DND_PREFIX}a`,
      rootThreads,
      folderSections: [],
    });
    expect(ops).toEqual([{ folderId: null, orderedIds: ["c", "a", "b"] }]);
  });

  it("root folder drop target appends within root bucket", () => {
    const rootThreads = [thread("a"), thread("b"), thread("c")];
    const ops = computeThreadDropPlan({
      activeThreadId: "b",
      overId: "folder:root",
      rootThreads,
      folderSections: [],
    });
    expect(ops).toEqual([{ folderId: null, orderedIds: ["a", "c", "b"] }]);
  });

  it("returns null when dropping onto self", () => {
    const rootThreads = [thread("a")];
    expect(
      computeThreadDropPlan({
        activeThreadId: "a",
        overId: `${THREAD_DND_PREFIX}a`,
        rootThreads,
        folderSections: [],
      }),
    ).toBeNull();
  });
});

describe("pickThreadCollisionByVerticalMidpoints", () => {
  function rectsMap(
    entries: { id: string; top: number; height: number }[],
  ): Map<string, DOMRect> {
    const m = new Map<string, DOMRect>();
    for (const e of entries) {
      const left = 0;
      const width = 10;
      const top = e.top;
      const height = e.height;
      m.set(
        e.id,
        {
          top,
          left,
          width,
          height,
          x: left,
          y: top,
          right: left + width,
          bottom: top + height,
          toJSON: () => ({}),
        } as DOMRect,
      );
    }
    return m;
  }

  it("partitions two overlapping rows by Y midpoint (no horizontal jitter flips)", () => {
    const a = `${THREAD_DND_PREFIX}a`;
    const b = `${THREAD_DND_PREFIX}b`;
    const rects = rectsMap([
      { id: a, top: 0, height: 40 },
      { id: b, top: 20, height: 40 },
    ]);
    expect(
      pickThreadCollisionByVerticalMidpoints([{ id: a }, { id: b }], 29, rects).id,
    ).toBe(a);
    expect(
      pickThreadCollisionByVerticalMidpoints([{ id: a }, { id: b }], 30, rects).id,
    ).toBe(b);
  });

  it("returns the only hit unchanged", () => {
    const a = `${THREAD_DND_PREFIX}a`;
    const rects = rectsMap([{ id: a, top: 0, height: 20 }]);
    expect(pickThreadCollisionByVerticalMidpoints([{ id: a }], 5, rects).id).toBe(a);
  });
});

describe("applyThreadOverHysteresis", () => {
  beforeEach(() => {
    resetThreadCollisionSticky();
  });

  it("after midpoint pick flips, hysteresis follows once pointer crosses inter-row boundary", () => {
    const a = `${THREAD_DND_PREFIX}a`;
    const b = `${THREAD_DND_PREFIX}b`;
    const rects = new Map<string, DOMRect>([
      [
        a,
        {
          top: 0,
          left: 0,
          width: 10,
          height: 40,
          x: 0,
          y: 0,
          right: 10,
          bottom: 40,
          toJSON: () => ({}),
        } as DOMRect,
      ],
      [
        b,
        {
          top: 30,
          left: 0,
          width: 10,
          height: 40,
          x: 0,
          y: 30,
          right: 10,
          bottom: 70,
          toJSON: () => ({}),
        } as DOMRect,
      ],
    ]);
    const hits = [{ id: a }, { id: b }];
    const yStart = 34;
    const first = pickThreadCollisionByVerticalMidpoints(hits, yStart, rects);
    expect(String(first.id)).toBe(a);
    applyThreadOverHysteresis(first, hits, yStart, rects, "thread:drag");
    const yMid = 36;
    const secondPick = pickThreadCollisionByVerticalMidpoints(hits, yMid, rects);
    expect(String(secondPick.id)).toBe(b);
    const afterBoundary = applyThreadOverHysteresis(secondPick, hits, yMid, rects, "thread:drag");
    expect(String(afterBoundary.id)).toBe(b);
    const yDeep = 46;
    const deepPick = pickThreadCollisionByVerticalMidpoints(hits, yDeep, rects);
    const moved = applyThreadOverHysteresis(deepPick, hits, yDeep, rects, "thread:drag");
    expect(String(moved.id)).toBe(b);
  });
});

