import { useEffect, useState } from "react";

/**
 * Tailwind `lg` breakpoint (1024px). The first client render reads matchMedia so
 * desktop does not flash the mobile chat chrome on reload.
 */
export function useMediaMinWidthLg(): boolean {
  const [isLg, setIsLg] = useState(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
      return false;
    }
    return window.matchMedia("(min-width: 1024px)").matches;
  });

  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
      return;
    }
    const mq = window.matchMedia("(min-width: 1024px)");
    const apply = () => setIsLg(mq.matches);
    apply();
    mq.addEventListener("change", apply);
    return () => mq.removeEventListener("change", apply);
  }, []);

  return isLg;
}"use client";

import { useEffect, useState } from "react";

/** True only after mount - use to avoid hydration / localStorage text mismatches. */
export function useMounted(): boolean {
  const [m, setM] = useState(false);
  useEffect(() => {
    queueMicrotask(() => setM(true));
  }, []);
  return m;
}// ── Oracle browser capability probe - SSR-safe mic/secure-context diagnostics ─────
// > Plain http:// to a LAN/Tailscale IP hides navigator.mediaDevices by design.
// > This module gives the UI one stable shape so we never hydrate one string and
// > then rip it out for a totally different one on the client tick. Source, if you
// > "fix" this by reading window during render, you will eat the hydration mismatch
// > yourself.

export type OracleBrowserCapabilityBlockedReason =
  | "not-mounted"
  | "insecure-context"
  | "missing-media-devices"
  | "missing-get-user-media"
  | "missing-media-recorder"
  | "unsupported-browser"
  | null;

export type OracleBrowserCapabilityReport = {
  /** Mirrors the `mounted` arg - false on SSR + first paint. */
  mounted: boolean;
  /** `window.isSecureContext` after mount. `null` until mounted (hydration-safe). */
  isSecureContext: boolean | null;
  hasNavigator: boolean;
  hasMediaDevices: boolean;
  hasGetUserMedia: boolean;
  hasMediaRecorder: boolean;
  hasAudioContext: boolean;
  /** True only when every capability needed for `MediaRecorder + getUserMedia` is present. */
  canUseMic: boolean;
  blockedReason: OracleBrowserCapabilityBlockedReason;
  /** Short human copy meant for UI hints. Stable until mounted to avoid hydration churn. */
  userMessage: string;
};

/** Stable pre-mount value - must match SSR every time. */
const SSR_REPORT: OracleBrowserCapabilityReport = {
  mounted: false,
  isSecureContext: null,
  hasNavigator: false,
  hasMediaDevices: false,
  hasGetUserMedia: false,
  hasMediaRecorder: false,
  hasAudioContext: false,
  canUseMic: false,
  blockedReason: "not-mounted",
  userMessage: "Checking voice input…",
};

/**
 * Build the capability report. `mounted` is the page-level mounted flag  - 
 * we refuse to inspect `window`/`navigator` until React tells us we're
 * past hydration. That keeps SSR and first paint identical.
 *
 * Browser checks live here (and only here). If you find yourself calling
 * `navigator.mediaDevices` from a component, route it through this report
 * instead. Less surface area = fewer Spirit roastings in the Toxic Grader.
 */
export function getOracleBrowserCapabilityReport(
  mounted: boolean,
): OracleBrowserCapabilityReport {
  if (!mounted) return SSR_REPORT;

  const hasWindow = typeof window !== "undefined";
  const hasNavigator = typeof navigator !== "undefined";
  const isSecureContext = hasWindow ? Boolean(window.isSecureContext) : false;
  const mediaDevices = hasNavigator ? navigator.mediaDevices : undefined;
  const hasMediaDevices = Boolean(mediaDevices);
  const hasGetUserMedia = Boolean(mediaDevices && typeof mediaDevices.getUserMedia === "function");
  const hasMediaRecorder = typeof MediaRecorder !== "undefined";
  const audioCtxCtor = hasWindow
    ? window.AudioContext ||
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    : undefined;
  const hasAudioContext = typeof audioCtxCtor === "function";

  const canUseMic =
    hasNavigator &&
    hasMediaDevices &&
    hasGetUserMedia &&
    hasMediaRecorder &&
    isSecureContext;

  let blockedReason: OracleBrowserCapabilityBlockedReason = null;
  let userMessage = "Mic ready.";

  if (!hasNavigator || !hasWindow) {
    blockedReason = "unsupported-browser";
    userMessage = "Voice input not available in this environment.";
  } else if (!isSecureContext) {
    blockedReason = "insecure-context";
    userMessage =
      "Mic access is blocked on this HTTP address. Use localhost, 127.0.0.1, or HTTPS.";
  } else if (!hasMediaDevices) {
    // Secure context but no mediaDevices - almost always an old browser.
    blockedReason = "missing-media-devices";
    userMessage = "Microphone API unavailable in this browser.";
  } else if (!hasGetUserMedia) {
    blockedReason = "missing-get-user-media";
    userMessage = "Microphone capture (getUserMedia) is not available in this browser.";
  } else if (!hasMediaRecorder) {
    blockedReason = "missing-media-recorder";
    userMessage = "Audio recording (MediaRecorder) is not supported in this browser.";
  }

  return {
    mounted: true,
    isSecureContext,
    hasNavigator,
    hasMediaDevices,
    hasGetUserMedia,
    hasMediaRecorder,
    hasAudioContext,
    canUseMic,
    blockedReason,
    userMessage,
  };
}

/** Same-host HTTPS variant of the current URL (or null when not relevant). */
export function getOracleHttpsUpgradeUrl(): string | null {
  if (typeof window === "undefined") return null;
  if (window.isSecureContext) return null;
  if (window.location.protocol !== "http:") return null;
  const { host, pathname, search, hash } = window.location;
  return `https://${host}${pathname}${search}${hash}`;
}// ── Oracle UI visual lane - maps live session/capability to orb + visualizer ───────
// > No new voice state machine: this is a thin paint adapter over
// > `OracleVoiceSessionStatus` + homelab capability rows.

import type { OracleBrowserCapabilityReport } from "@/lib/oracle/oracle-browser-capabilities";
import type { OracleVoiceSessionStatus } from "@/lib/oracle/oracle-voice-session";

/** Bars + orb intensity - six buckets for CSS. */
export type OracleVisualState =
  | "idle"
  | "permission"
  | "listening"
  | "processing"
  | "speaking"
  | "error";

export type HomelabOracleBadgeVariant = "pending" | "live" | "offline" | "ready";

export function getOracleVisualStateFromSessionStatus(
  status: OracleVoiceSessionStatus,
): OracleVisualState {
  switch (status) {
    case "error":
      return "error";
    case "permission-needed":
    case "requesting-mic":
    case "blocked":
    case "unsupported":
      return "permission";
    case "listening":
    case "hearing-speech":
      return "listening";
    case "silence-detected":
    case "transcribing":
    case "thinking":
    case "restarting":
      return "processing";
    case "speaking":
      return "speaking";
    case "idle":
    case "ready":
    case "stopped":
    default:
      return "idle";
  }
}

/**
 * Homelab card has no live mic stream - only capability + badge paint.
 * Insecure / hard API gaps read as error; soft “degraded” reads as permission lane.
 */
export function getOracleVisualStateForHomelab(input: {
  mounted: boolean;
  capability: OracleBrowserCapabilityReport;
  badgeVariant: HomelabOracleBadgeVariant;
}): OracleVisualState {
  const { mounted, capability, badgeVariant } = input;
  if (!mounted) return "idle";
  if (capability.isSecureContext === false) return "error";
  if (!capability.canUseMic) return "permission";
  if (badgeVariant === "offline") return "permission";
  return "idle";
}// ── Oracle Voice session - UI state machine (no Dexie, no server sync) ────────────
// > Prompt 10D-E: hands-free loop is the default - push-to-talk demoted to a knob,
// > silence VAD picks the moment we hand mic audio to Whisper, and TTS owns
// > "speaking" exclusively. If a status feels wrong in the UI, it's almost always
// > because someone forgot one of the priority rules in deriveOracleVoiceStatus.

export type OracleVoiceSessionStatus =
  | "idle"
  | "blocked"
  | "requesting-mic"
  | "permission-needed"
  | "ready"
  | "listening"
  | "hearing-speech"
  | "silence-detected"
  | "transcribing"
  | "thinking"
  | "speaking"
  | "restarting"
  | "stopped"
  | "unsupported"
  | "error";

/** Hands-free is the default loop mode for /oracle. Push-to-talk + manual stay as knobs. */
export type OracleVoiceLoopMode = "hands-free" | "push-to-talk" | "manual-text";

/** @deprecated keep until callers migrate - same shape as `hands-free` historically. */
export type OracleVoiceInputMode = OracleVoiceLoopMode;

/** Default loop mode for new sessions. */
export const DEFAULT_ORACLE_LOOP_MODE: OracleVoiceLoopMode = "hands-free";

export type OracleSpeechProvider =
  | "whisper-backend"
  | "browser-speech-recognition"
  | "manual-text"
  | "unsupported";

export type OracleVoiceSessionEventType =
  | "session_ready"
  | "session_started"
  | "session_stopped"
  | "permission_requested"
  | "permission_granted"
  | "permission_denied"
  | "device_selected"
  | "listening_started"
  | "listening_stopped"
  | "silence_detected"
  | "auto_stopped"
  | "transcript_ready"
  | "message_submitted"
  | "assistant_finished"
  | "speech_started"
  | "speech_stopped"
  | "speech_error"
  | "mode_changed"
  | "provider_unsupported"
  | "loop_restart"
  | "error";

export type OracleVoiceSessionEvent = {
  id: string;
  type: OracleVoiceSessionEventType;
  label: string;
  detail?: string;
  createdAt: number;
};

const EVENT_CAP = 80;

function randomId(): string {
  try {
    if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
      return crypto.randomUUID();
    }
  } catch {
    /* ignore */
  }
  return `evt_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
}

export function createOracleVoiceEvent(
  input: Omit<OracleVoiceSessionEvent, "id" | "createdAt">,
): OracleVoiceSessionEvent {
  return {
    id: randomId(),
    createdAt: Date.now(),
    ...input,
  };
}

export function appendOracleVoiceEvent(
  prev: OracleVoiceSessionEvent[],
  next: OracleVoiceSessionEvent,
): OracleVoiceSessionEvent[] {
  return [...prev, next];
}

export function capOracleVoiceEvents(
  rows: OracleVoiceSessionEvent[],
  cap = EVENT_CAP,
): OracleVoiceSessionEvent[] {
  if (rows.length <= cap) return rows;
  return rows.slice(rows.length - cap);
}

export type MicPermissionState = "unknown" | "prompt" | "granted" | "denied" | "unsupported";

export type DeriveOracleVoiceStatusInput = {
  inputMode: OracleVoiceLoopMode;
  /** getUserMedia + MediaRecorder available */
  recordingSupported: boolean;
  /** True when capability check says mic cannot be used (insecure ctx, missing API). */
  capabilityBlocked?: boolean;
  /** User tapped Start session; waiting on getUserMedia */
  requestingMic: boolean;
  micPermission: MicPermissionState;
  isListening: boolean;
  /** Recording AND amplitude above threshold = "hearing-speech". */
  hearingSpeech?: boolean;
  /** Silence threshold reached, stop+transcribe pending. */
  silenceDetected?: boolean;
  isTranscribing: boolean;
  isBusy: boolean;
  isPlaying: boolean;
  queueLength: number;
  /** True for the small grace window between TTS finishing and the next listen turn. */
  restarting?: boolean;
  /** True when user has explicitly stopped the session. Latches "stopped" until session restart. */
  sessionStopped?: boolean;
  /** True when a hands-free session is currently in progress. */
  sessionActive?: boolean;
  ttsLastError?: string | null;
  speechLastError?: string | null;
  spiritTransportError?: string | null;
  lastUserStopAtMs?: number | null;
  nowMs?: number;
  stoppedWindowMs?: number;
};

/** Maps machine status to short human copy for hints + status card */
export function oracleSessionStatusLabel(status: OracleVoiceSessionStatus): string {
  switch (status) {
    case "idle":
      return "Idle";
    case "blocked":
      return "Blocked";
    case "requesting-mic":
      return "Requesting mic";
    case "permission-needed":
      return "Permission needed";
    case "ready":
      return "Ready";
    case "listening":
      return "Listening";
    case "hearing-speech":
      return "Hearing you";
    case "silence-detected":
      return "Silence detected";
    case "transcribing":
      return "Transcribing";
    case "thinking":
      return "Thinking";
    case "speaking":
      return "Speaking";
    case "restarting":
      return "Restarting";
    case "stopped":
      return "Stopped";
    case "unsupported":
      return "Unsupported";
    case "error":
      return "Error";
    default:
      return status;
  }
}

/** Short per-status hint for UI subtitles. */
export function oracleSessionStatusHint(status: OracleVoiceSessionStatus): string {
  switch (status) {
    case "idle":
      return "Tap Start session to begin.";
    case "blocked":
      return "Mic blocked - see secure-context warning.";
    case "requesting-mic":
      return "Asking the browser for microphone access…";
    case "permission-needed":
      return "Grant the browser mic permission to continue.";
    case "ready":
      return "Mic ready - start a session whenever you are.";
    case "listening":
      return "Waiting for speech…";
    case "hearing-speech":
      return "Speak naturally - Oracle stops when you do.";
    case "silence-detected":
      return "Heard the gap - sending to Whisper.";
    case "transcribing":
      return "Transcribing with Whisper…";
    case "thinking":
      return "Oracle is thinking…";
    case "speaking":
      return "Oracle is speaking - listening resumes after.";
    case "restarting":
      return "Returning to listening…";
    case "stopped":
      return "Session stopped. Tap Start session to resume.";
    case "unsupported":
      return "Voice capture isn't available in this browser.";
    case "error":
      return "Something failed - see the status card for details.";
    default:
      return "";
  }
}

/**
 * Priority (highest first):
 *   error → unsupported / blocked → requesting mic → permission needed →
 *   silence-detected → transcribing → thinking → speaking → restarting →
 *   hearing-speech → listening → stopped (latched) → ready → idle.
 */
export function deriveOracleVoiceStatus(input: DeriveOracleVoiceStatusInput): OracleVoiceSessionStatus {
  const now = input.nowMs ?? Date.now();
  const windowMs = input.stoppedWindowMs ?? 3500;

  const voicePath = input.inputMode !== "manual-text";

  if (input.spiritTransportError?.trim()) return "error";
  if (input.ttsLastError?.trim()) return "error";
  if (input.speechLastError?.trim()) return "error";

  if (voicePath && input.capabilityBlocked) return "blocked";
  if (voicePath && input.micPermission === "unsupported") return "unsupported";
  if (voicePath && !input.recordingSupported) return "unsupported";

  if (voicePath && input.requestingMic) return "requesting-mic";

  if (
    voicePath &&
    input.recordingSupported &&
    input.micPermission !== "granted" &&
    input.micPermission !== "unsupported"
  ) {
    return "permission-needed";
  }

  if (input.silenceDetected) return "silence-detected";
  if (input.isTranscribing) return "transcribing";
  if (input.isBusy) return "thinking";
  if (input.isPlaying || input.queueLength > 0) return "speaking";
  if (input.restarting) return "restarting";

  if (input.isListening) {
    return input.hearingSpeech ? "hearing-speech" : "listening";
  }

  // Latched stopped after the user clicked Stop session - until a new session starts.
  if (input.sessionStopped && !input.sessionActive) return "stopped";

  const stoppedAt = input.lastUserStopAtMs;
  if (typeof stoppedAt === "number" && now - stoppedAt >= 0 && now - stoppedAt < windowMs) {
    return "stopped";
  }

  if (voicePath && input.micPermission === "granted" && !input.isListening && !input.isBusy) {
    return "ready";
  }

  if (!voicePath) {
    return input.isBusy ? "thinking" : "idle";
  }

  return "idle";
}

/**
 * Returns true when the hands-free loop should auto-restart listening after
 * the assistant's TTS finishes. We latch on session active + hands-free + no
 * pending error / busy / queue. Stage 4 calls this before starting a new turn.
 */
export function shouldOracleAutoRestartListening(input: {
  sessionActive: boolean;
  inputMode: OracleVoiceLoopMode;
  isBusy: boolean;
  isPlaying: boolean;
  queueLength: number;
  isTranscribing: boolean;
  isListening: boolean;
  micPermission: MicPermissionState;
  capabilityBlocked?: boolean;
  spiritTransportError?: string | null;
  ttsLastError?: string | null;
  speechLastError?: string | null;
}): boolean {
  if (!input.sessionActive) return false;
  if (input.inputMode !== "hands-free") return false;
  if (input.capabilityBlocked) return false;
  if (input.micPermission !== "granted") return false;
  if (input.isBusy) return false;
  if (input.isPlaying || input.queueLength > 0) return false;
  if (input.isTranscribing) return false;
  if (input.isListening) return false;
  if (input.spiritTransportError?.trim()) return false;
  if (input.ttsLastError?.trim()) return false;
  if (input.speechLastError?.trim()) return false;
  return true;
}import { describe, expect, it, vi } from "vitest";

