import { getClusterConfig } from "@/lib/server/telemetry/cluster-config";
import { collectClusterNodes } from "@/lib/server/telemetry/collect-cluster-nodes";
import type { ClusterNodeTelemetry } from "@/lib/server/telemetry/types";
import type {
  CapabilityNodeBundle,
  CapabilityRegistryHost,
  CapabilityRegistryNode,
  CapabilityRegistryResponse,
  CapabilityToolEntry,
} from "./types";

// ── Capability registry - thin layer on cluster telemetry; no parallel universe ─

/** Registry metadata for Phase 1 read-only tools; native AI SDK wiring is Phase 1.5 (see model runtime hint). */
const PHASE1_TOOLS: CapabilityToolEntry[] = [
  { name: "get_capabilities", enabled: true, readOnly: true, requiresApproval: false },
  { name: "list_nodes", enabled: true, readOnly: true, requiresApproval: false },
  { name: "get_node_status", enabled: true, readOnly: true, requiresApproval: false },
];

/** SPIRIT_PROJECT_PATH: comma-separated abs paths - configured iff any segment non-empty after trim. No fs access. */
export function isSpiritProjectPathConfigured(raw: string | undefined): boolean {
  if (raw === undefined) return false;
  const parts = raw.split(",").map((s) => s.trim()).filter(Boolean);
  return parts.length > 0;
}

function liveTelemetryAllowed(status: ClusterNodeTelemetry["status"]): boolean {
  return status === "online" || status === "degraded";
}

function buildNodeCapabilities(node: ClusterNodeTelemetry): CapabilityNodeBundle {
  const live = liveTelemetryAllowed(node.status);
  const hasStorage =
    Array.isArray(node.storage?.drives) && node.storage.drives.length > 0;
  const projectsConfigured = isSpiritProjectPathConfigured(process.env.SPIRIT_PROJECT_PATH);

  return {
    telemetry: { enabled: live, readOnly: true },
    storageTelemetry: { enabled: live && hasStorage, readOnly: true },
    projects: { enabled: false, configured: projectsConfigured, readOnly: true },
    ssh: { enabled: false, status: "unverified", requiresApproval: true },
    remoteControl: { live, requiresApproval: true },
  };
}

function resolveHost(configs: ReturnType<typeof getClusterConfig>): CapabilityRegistryHost {
  const local = configs.find((c) => c.source === "local");
  if (local) {
    return { id: local.id, label: local.label, source: "local" };
  }
  // Should not happen with current getClusterConfig - fall back without inventing hardware names
  return { id: "unknown", label: "unknown", source: "local" };
}

function toCapabilityNode(node: ClusterNodeTelemetry): CapabilityRegistryNode {
  return {
    id: node.id,
    label: node.label,
    status: node.status,
    source: node.source,
    platform: node.platform,
    capabilities: buildNodeCapabilities(node),
    telemetrySnapshot: {
      cpu: node.cpu,
      memory: node.memory,
      storage: node.storage,
      uptimeSec: node.uptimeSec,
      error: node.error,
    },
  };
}

export async function getCapabilityRegistry(): Promise<CapabilityRegistryResponse> {
  const configs = getClusterConfig();
  const nodes = await collectClusterNodes(configs);
  const collectedAt = new Date().toISOString();

  return {
    ok: true,
    collectedAt,
    host: resolveHost(configs),
    nodes: nodes.map(toCapabilityNode),
    tools: PHASE1_TOOLS,
  };
}import type { ClusterNodeStatus, ClusterNodeTelemetry } from "@/lib/server/telemetry/types";

/** Hardware snapshot for formatting - same fields as cluster telemetry */
export type CapabilityTelemetrySnapshot = Pick<
  ClusterNodeTelemetry,
  "cpu" | "memory" | "uptimeSec"
> & {
  storage?: ClusterNodeTelemetry["storage"];
  error?: string;
};

/** Phase 1 - execution wiring for SSH / WinRM / remote shell not verified in-app */
export type RemoteCapabilityVerificationStatus = "unverified" | "disabled";

export type CapabilityToolEntry = {
  name: "get_capabilities" | "list_nodes" | "get_node_status";
  enabled: boolean;
  readOnly: boolean;
  requiresApproval: boolean;
};

export type CapabilityNodeBundle = {
  telemetry: { enabled: boolean; readOnly: true };
  storageTelemetry: { enabled: boolean; readOnly: true };
  projects: { enabled: false; configured: boolean; readOnly: true };
  ssh: {
    enabled: false;
    status: RemoteCapabilityVerificationStatus;
    requiresApproval: true;
  };
  remoteControl: {
    /** Live node telemetry path vs offline / unreachable */
    live: boolean;
    requiresApproval: true;
  };
};

export type CapabilityRegistryNode = {
  id: string;
  label: string;
  status: ClusterNodeStatus;
  source: "local" | "remote";
  platform: string | null;
  capabilities: CapabilityNodeBundle;
  telemetrySnapshot: CapabilityTelemetrySnapshot;
};

export type CapabilityRegistryHost = {
  id: string;
  label: string;
  source: "local";
};

export type CapabilityRegistryResponse = {
  ok: true;
  collectedAt: string;
  host: CapabilityRegistryHost;
  nodes: CapabilityRegistryNode[];
  tools: CapabilityToolEntry[];
};export type ClusterNodeConfig = {
  id: string;
  label: string;
  source: "local" | "remote";
  telemetryUrl?: string;
};

/** Strips accidental `< >` from copy-pasted placeholders - `http://<10.0.0.1>:3000` breaks DNS otherwise. */
export function normalizeTelemetryEnvUrl(raw: string | undefined): string | undefined {
  if (!raw) return undefined;
  const t = raw.trim().replaceAll(/[<>]/g, "");
  return t || undefined;
}

export function getClusterConfig(): ClusterNodeConfig[] {
  const localId = process.env.SPIRIT_CLUSTER_LOCAL_ID?.trim() || "spirit-dell";
  const localLabel = process.env.SPIRIT_CLUSTER_LOCAL_LABEL?.trim() || localId;

  const spiritdesktopUrl = normalizeTelemetryEnvUrl(process.env.SPIRITDESKTOP_TELEMETRY_URL);
  const spiritDellUrl = normalizeTelemetryEnvUrl(process.env.SPIRIT_DELL_TELEMETRY_URL);

  const nodes: ClusterNodeConfig[] = [];

  if (localId === "spiritdesktop") {
    nodes.push({ id: "spiritdesktop", label: localLabel, source: "local" });
  } else {
    nodes.push({
      id: "spiritdesktop",
      label: "spiritdesktop",
      source: "remote",
      telemetryUrl: spiritdesktopUrl,
    });
  }

  if (localId === "spirit-dell") {
    nodes.push({ id: "spirit-dell", label: localLabel, source: "local" });
  } else {
    nodes.push({
      id: "spirit-dell",
      label: "Spirit Dell",
      source: "remote",
      telemetryUrl: spiritDellUrl,
    });
  }

  return nodes;
}import { collectLocalNodeTelemetry } from "./collect-local-node";
import { fetchRemoteNodeTelemetry } from "./fetch-remote-node";
import type { ClusterNodeConfig } from "./cluster-config";
import type { ClusterNodeTelemetry } from "./types";

/** Same merge semantics as GET /api/telemetry/cluster - single source of truth for node lists. */
export async function collectClusterNodes(configs: ClusterNodeConfig[]): Promise<ClusterNodeTelemetry[]> {
  const results = await Promise.allSettled(
    configs.map((cfg) => {
      if (cfg.source === "local") {
        return collectLocalNodeTelemetry({ id: cfg.id, label: cfg.label });
      }
      return fetchRemoteNodeTelemetry(cfg.id, cfg.label, cfg.telemetryUrl);
    }),
  );

  return results.map((result, i) => {
    if (result.status === "fulfilled") return result.value;
    const cfg = configs[i]!;
    return {
      id: cfg.id,
      label: cfg.label,
      hostname: null,
      status: "offline" as const,
      source: cfg.source,
      telemetryUrl: cfg.telemetryUrl,
      platform: null,
      arch: null,
      cpu: { model: null, cores: null, usagePct: null, loadAvg: null },
      memory: { totalBytes: null, freeBytes: null, usedBytes: null, usedPct: null },
      uptimeSec: null,
      collectedAt: new Date().toISOString(),
      error: result.reason instanceof Error ? result.reason.message : "collection failed",
    };
  });
}import os from "node:os";
import { execSync } from "node:child_process";
import { readFileSync } from "node:fs";
import type { ClusterNodeTelemetry, NodeDrive, NodeStorage } from "./types";

// ── CPU sampling ─────────────────────────────────────────────────────────────

function snapshotCpuTimes(): { idle: number; total: number } {
  let idle = 0;
  let total = 0;
  for (const cpu of os.cpus()) {
    const t = cpu.times;
    idle += t.idle;
    total += t.user + t.nice + t.sys + t.idle + t.irq;
  }
  return { idle, total };
}

async function measureCpuUsage(): Promise<number | null> {
  try {
    const before = snapshotCpuTimes();
    await new Promise<void>((resolve) => setTimeout(resolve, 150));
    const after = snapshotCpuTimes();
    const deltaIdle = after.idle - before.idle;
    const deltaTotal = after.total - before.total;
    if (deltaTotal === 0) return null;
    const pct = 100 - (deltaIdle / deltaTotal) * 100;
    return Math.min(100, Math.max(0, pct));
  } catch {
    return null;
  }
}

// ── Storage collection ────────────────────────────────────────────────────────

function getBaseDevice(device: string): string {
  const dev = device.replace(/^\/dev\//, "");
  if (/^nvme\d+n\d+p\d+/.test(dev)) return dev.replace(/p\d+$/, "");
  if (/^mmcblk\d+p\d+/.test(dev)) return dev.replace(/p\d+$/, "");
  return dev.replace(/\d+$/, "");
}

function inferDriveType(device: string): NodeDrive["type"] {
  const dev = device.replace(/^\/dev\//, "");
  if (dev.startsWith("nvme")) return "NVME";
  if (dev.startsWith("mmcblk")) return "SSD";
  if (dev.startsWith("sd") || dev.startsWith("hd") || dev.startsWith("vd")) {
    try {
      const baseDev = getBaseDevice(device);
      const rotational = readFileSync(`/sys/block/${baseDev}/queue/rotational`, "utf8").trim();
      return rotational === "0" ? "SSD" : "HDD";
    } catch {
      return "HDD";
    }
  }
  return "UNKNOWN";
}

async function collectLocalStorage(): Promise<NodeStorage> {
  const now = new Date().toISOString();
  try {
    // -P: POSIX format (no line wrapping), -l: local filesystems only (avoids stale NFS hangs)
    const output = execSync("df -Pl", { timeout: 3000, encoding: "utf8" });
    const lines = output.trim().split("\n").slice(1); // skip header

    const seen = new Set<string>();
    const drives: NodeDrive[] = [];

    for (const line of lines) {
      const parts = line.trim().split(/\s+/);
      // Filesystem  1024-blocks  Used  Available  Capacity%  Mounted on
      if (parts.length < 6) continue;
      const device = parts[0]!;
      const mount = parts[5]!;

      if (!device.startsWith("/dev/")) continue;
      // Snap/loop mounts masquerade as block devices - not useful homelab “drives”.
      if (device.startsWith("/dev/loop")) continue;
      if (seen.has(device)) continue;
      seen.add(device);

      const totalBlocks = parseInt(parts[1]!, 10);
      const usedBlocks = parseInt(parts[2]!, 10);
      const availBlocks = parseInt(parts[3]!, 10);
      if (isNaN(totalBlocks) || totalBlocks === 0) continue;

      const totalBytes = totalBlocks * 1024;
      const usedBytes = usedBlocks * 1024;
      const freeBytes = availBlocks * 1024;
      const usedPct = Math.round((usedBytes / totalBytes) * 100 * 10) / 10;

      drives.push({
        id: device,
        name: mount === "/" ? "/ (root)" : mount,
        mount,
        fsType: null,
        type: inferDriveType(device),
        totalBytes,
        usedBytes,
        freeBytes,
        usedPct,
        tempC: null,
        smart: "Unknown",
      });
    }

    return { drives, collectedAt: now };
  } catch (err) {
    return {
      drives: [],
      collectedAt: now,
      error: err instanceof Error ? err.message : "storage collection failed",
    };
  }
}

// ── Main collector ────────────────────────────────────────────────────────────

export async function collectLocalNodeTelemetry(options?: {
  id?: string;
  label?: string;
}): Promise<ClusterNodeTelemetry> {
  const hostname = os.hostname();
  const id = options?.id || process.env.SPIRIT_CLUSTER_LOCAL_ID?.trim() || hostname;
  const label = options?.label || process.env.SPIRIT_CLUSTER_LOCAL_LABEL?.trim() || hostname;

  let cpuModel: string | null = null;
  let cores: number | null = null;
  try {
    const cpus = os.cpus();
    cpuModel = cpus[0]?.model?.trim() || null;
    cores = cpus.length || null;
  } catch {
    // os.cpus unavailable on this platform
  }

  const [usagePct, storage] = await Promise.all([
    measureCpuUsage(),
    collectLocalStorage(),
  ]);

  const rawLoadAvg = os.loadavg();
  const loadAvg =
    rawLoadAvg.length === 3 && rawLoadAvg.some((v) => v > 0) ? rawLoadAvg : null;

  const totalBytes = os.totalmem();
  const freeBytes = os.freemem();
  const usedBytes = totalBytes - freeBytes;
  const usedPct = totalBytes > 0 ? (usedBytes / totalBytes) * 100 : null;

  return {
    id,
    label,
    hostname,
    status: "online",
    source: "local",
    platform: os.platform(),
    arch: os.arch(),
    cpu: {
      model: cpuModel,
      cores,
      usagePct: usagePct !== null ? Math.round(usagePct * 10) / 10 : null,
      loadAvg,
    },
    memory: {
      totalBytes,
      freeBytes,
      usedBytes,
      usedPct: usedPct !== null ? Math.round(usedPct * 10) / 10 : null,
    },
    storage,
    uptimeSec: Math.floor(os.uptime()),
    collectedAt: new Date().toISOString(),
  };
}import "server-only";

// ── API errors - JSON bodies only; never leak stacks to browsers ────────────────

export class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly publicMessage: string,
  ) {
    super(publicMessage);
    this.name = "ApiError";
  }
}

export function errorToResponse(error: unknown): Response {
  if (error instanceof ApiError) {
    return Response.json(
      { ok: false, error: error.publicMessage },
      { status: error.status },
    );
  }

  console.error("[api-error]", error);

  return Response.json(
    { ok: false, error: "Spirit backend failed" },
    { status: 500 },
  );
}import "server-only";

// ── ElevenLabs voice list - GET /v1/voices for UI + defaults (Prompt 9L allowlist) ─
// > Name-only allowlist needs catalog; explicit Name:voice_id does not need voices_read.

export type ElevenLabsVoiceRow = {
  voice_id: string;
  name: string;
  category?: string;
  labels?: Record<string, string>;
  preview_url?: string | null;
};

type ElevenLabsVoicesApiVoice = {
  voice_id?: string;
  name?: string;
  category?: string;
  labels?: Record<string, string>;
  preview_url?: string | null;
};

type ElevenLabsVoicesApi = {
  voices?: ElevenLabsVoicesApiVoice[];
  data?: { voices?: ElevenLabsVoicesApiVoice[] };
};

const FETCH_TIMEOUT_MS = 25_000;

/** RHS after `:` must look like a real ElevenLabs voice_id (not "Paige"). */
const VOICE_ID_LIKE = /^[a-zA-Z0-9_-]{10,64}$/;

export type ElevenLabsVoicesFetchErrorCode =
  | "elevenlabs_missing_key"
  | "elevenlabs_unauthorized"
  | "elevenlabs_forbidden"
  | "elevenlabs_rate_limited"
  | "elevenlabs_upstream"
  | "elevenlabs_bad_json"
  | "elevenlabs_network";

export class ElevenLabsVoicesFetchError extends Error {
  readonly name = "ElevenLabsVoicesFetchError";

  constructor(
    message: string,
    public readonly httpStatus: number,
    public readonly code: ElevenLabsVoicesFetchErrorCode,
    public readonly safeDetail?: string,
  ) {
    super(message);
  }
}

function abortTimeout(): AbortSignal {
  try {
    return AbortSignal.timeout(FETCH_TIMEOUT_MS);
  } catch {
    const c = new AbortController();
    const t = setTimeout(() => c.abort(), FETCH_TIMEOUT_MS);
    void t.unref?.();
    return c.signal;
  }
}

function normalizeRow(v: ElevenLabsVoicesApiVoice): ElevenLabsVoiceRow | null {
  const id = typeof v.voice_id === "string" ? v.voice_id.trim() : "";
  const name = typeof v.name === "string" ? v.name.trim() : "";
  if (!id || !name) return null;
  return {
    voice_id: id,
    name,
    category: typeof v.category === "string" ? v.category.trim() : undefined,
    labels: v.labels && typeof v.labels === "object" ? v.labels : undefined,
    preview_url:
      typeof v.preview_url === "string" && v.preview_url.trim()
        ? v.preview_url.trim()
        : null,
  };
}

function safeUpstreamSnippet(text: string, max = 240): string {
  const t = text.replace(/\s+/g, " ").trim();
  if (!t) return "";
  return t.length > max ? `${t.slice(0, max)}…` : t;
}

function extractVoicesArray(json: unknown): ElevenLabsVoicesApiVoice[] {
  if (!json || typeof json !== "object") return [];
  const root = json as ElevenLabsVoicesApi;
  if (Array.isArray(root.voices)) return root.voices;
  const nested = root.data?.voices;
  if (Array.isArray(nested)) return nested;
  return [];
}

/** Sort: Clarice first (case-insensitive), then name A–Z. */
export function sortElevenLabsVoicesForUi(rows: ElevenLabsVoiceRow[]): ElevenLabsVoiceRow[] {
  return [...rows].sort((a, b) => {
    const ac = a.name.toLowerCase() === "clarice" ? 0 : 1;
    const bc = b.name.toLowerCase() === "clarice" ? 0 : 1;
    if (ac !== bc) return ac - bc;
    return a.name.localeCompare(b.name, undefined, { sensitivity: "base" });
  });
}

export type PickDefaultElevenLabsVoiceResult = {
  defaultVoiceId: string | null;
  defaultVoiceName: string | null;
  /** When env default id is set but absent from fetched catalog (non-empty list). */
  warning?: string;
};

/**
 * Default pick order:
 * 1) ELEVENLABS_DEFAULT_VOICE_ID (in list → name from row; empty list → env name / "Configured voice"; not in list → warning)
 * 2) Clarice by name
 * 3) ELEVENLABS_VOICE_ID
 * 4) first sorted row
 */
export function pickDefaultElevenLabsVoice(
  sortedRows: ElevenLabsVoiceRow[],
): PickDefaultElevenLabsVoiceResult {
  const envDefaultId = process.env.ELEVENLABS_DEFAULT_VOICE_ID?.trim();
  const envDefaultName = process.env.ELEVENLABS_DEFAULT_VOICE_NAME?.trim();

  if (envDefaultId) {
    const hit = sortedRows.find((r) => r.voice_id === envDefaultId);
    if (sortedRows.length === 0) {
      return {
        defaultVoiceId: envDefaultId,
        defaultVoiceName: envDefaultName ?? "Configured voice",
      };
    }
    if (!hit) {
      return {
        defaultVoiceId: envDefaultId,
        defaultVoiceName: envDefaultName ?? "Configured voice",
        warning: "default_voice_id_not_in_catalog",
      };
    }
    return {
      defaultVoiceId: envDefaultId,
      defaultVoiceName: hit.name,
    };
  }

  const clarice = sortedRows.find((r) => r.name.toLowerCase() === "clarice");
  if (clarice) {
    return { defaultVoiceId: clarice.voice_id, defaultVoiceName: clarice.name };
  }

  const legacy = process.env.ELEVENLABS_VOICE_ID?.trim();
  if (legacy) {
    const hit = sortedRows.find((r) => r.voice_id === legacy);
    return { defaultVoiceId: legacy, defaultVoiceName: hit?.name ?? null };
  }

  const first = sortedRows[0];
  if (first) return { defaultVoiceId: first.voice_id, defaultVoiceName: first.name };
  return { defaultVoiceId: null, defaultVoiceName: null };
}

// ── Env allowlist - explicit ids OR name-only (Prompt 9L) ─────────────────────────

export type ElevenLabsAllowlistMode = "explicit-id" | "name-only" | "mixed" | "json" | "none";

export type AllowlistOrderedSegment =
  | { kind: "explicit"; row: ElevenLabsVoiceRow }
  | { kind: "name"; name: string };

export type ParsedElevenLabsAllowlist = {
  orderedSegments: AllowlistOrderedSegment[];
  explicitVoices: ElevenLabsVoiceRow[];
  nameOnly: string[];
  hasAllowlist: boolean;
  invalidEntries: string[];
  allowlistMode: ElevenLabsAllowlistMode;
};

export const WARN_NAME_ONLY_CATALOG_FAILED =
  "Voice allowlist uses names only, but ElevenLabs catalog lookup failed. Use Name:voice_id pairs to avoid voices_read permission.";

function parseCommaToken(token: string): AllowlistOrderedSegment | "invalid" | null {
  const t = token.trim();
  if (!t) return null;
  const lastColon = t.lastIndexOf(":");
  if (lastColon <= 0) {
    return { kind: "name", name: t };
  }
  if (lastColon >= t.length - 1) {
    return "invalid";
  }
  const name = t.slice(0, lastColon).trim();
  const voice_id = t.slice(lastColon + 1).trim();
  if (!name || !voice_id) return "invalid";
  if (VOICE_ID_LIKE.test(voice_id)) {
    return { kind: "explicit", row: { voice_id, name } };
  }
  /* Colon present but RHS is not a plausible voice_id - treat whole token as a display name (catalog match). */
  return { kind: "name", name: t };
}

/**
 * `ELEVENLABS_VOICE_ALLOWLIST_JSON` wins over comma env when both are set.
 * JSON: `[{"name":"Clarice","voice_id":"abc"},…]` - always explicit-id mode.
 * Comma: `Name:voice_id` (id must match VOICE_ID_LIKE) OR `Charlotte,Clarice` name-only.
 */
export function parseElevenLabsVoiceAllowlistFromEnv(): ParsedElevenLabsAllowlist {
  const jsonRaw = process.env.ELEVENLABS_VOICE_ALLOWLIST_JSON?.trim();
  if (jsonRaw) {
    try {
      const parsed = JSON.parse(jsonRaw) as unknown;
      if (!Array.isArray(parsed)) {
        return {
          orderedSegments: [],
          explicitVoices: [],
          nameOnly: [],
          hasAllowlist: false,
          invalidEntries: [],
          allowlistMode: "none",
        };
      }
      const orderedSegments: AllowlistOrderedSegment[] = [];
      const explicitVoices: ElevenLabsVoiceRow[] = [];
      const invalidEntries: string[] = [];
      for (const row of parsed) {
        if (!row || typeof row !== "object") continue;
        const o = row as Record<string, unknown>;
        const voice_id = typeof o.voice_id === "string" ? o.voice_id.trim() : "";
        const name = typeof o.name === "string" ? o.name.trim() : "";
        if (!voice_id || !name) {
          invalidEntries.push(JSON.stringify(row).slice(0, 80));
          continue;
        }
        const r = { voice_id, name };
        explicitVoices.push(r);
        orderedSegments.push({ kind: "explicit", row: r });
      }
      const hasAllowlist = orderedSegments.length > 0;
      return {
        orderedSegments,
        explicitVoices,
        nameOnly: [],
        hasAllowlist,
        invalidEntries,
        allowlistMode: hasAllowlist ? "json" : "none",
      };
    } catch {
      return {
        orderedSegments: [],
        explicitVoices: [],
        nameOnly: [],
        hasAllowlist: false,
        invalidEntries: [],
        allowlistMode: "none",
      };
    }
  }

  const comma = process.env.ELEVENLABS_VOICE_ALLOWLIST?.trim();
  if (!comma) {
    return {
      orderedSegments: [],
      explicitVoices: [],
      nameOnly: [],
      hasAllowlist: false,
      invalidEntries: [],
      allowlistMode: "none",
    };
  }

  const orderedSegments: AllowlistOrderedSegment[] = [];
  const explicitVoices: ElevenLabsVoiceRow[] = [];
  const nameOnly: string[] = [];
  const invalidEntries: string[] = [];

  for (const part of comma.split(",")) {
    const seg = parseCommaToken(part);
    if (seg === null) continue;
    if (seg === "invalid") {
      invalidEntries.push(part.trim());
      continue;
    }
    orderedSegments.push(seg);
    if (seg.kind === "explicit") {
      explicitVoices.push(seg.row);
    } else {
      nameOnly.push(seg.name);
    }
  }

  const hasAllowlist = orderedSegments.length > 0;
  let allowlistMode: ElevenLabsAllowlistMode = "none";
  if (hasAllowlist) {
    if (explicitVoices.length > 0 && nameOnly.length > 0) allowlistMode = "mixed";
    else if (explicitVoices.length > 0) allowlistMode = "explicit-id";
    else allowlistMode = "name-only";
  }

  return {
    orderedSegments,
    explicitVoices,
    nameOnly,
    hasAllowlist,
    invalidEntries,
    allowlistMode,
  };
}

export type ResolveElevenLabsVoiceAllowlistInput = {
  parsed: ParsedElevenLabsAllowlist;
  catalog: ElevenLabsVoiceRow[];
};

export type ResolveElevenLabsVoiceAllowlistResult = {
  voices: ElevenLabsVoiceRow[];
  warnings: string[];
  missingNames: string[];
};

/**
 * Resolves allowlist segments against catalog (case-insensitive name match).
 * Preserves env order. Does not append unrelated catalog voices.
 */
export function resolveElevenLabsVoiceAllowlist(
  input: ResolveElevenLabsVoiceAllowlistInput,
): ResolveElevenLabsVoiceAllowlistResult {
  const { parsed, catalog } = input;
  const warnings: string[] = [];
  const missingNames: string[] = [];
  const voices: ElevenLabsVoiceRow[] = [];

  if (!parsed.hasAllowlist) {
    return { voices: [...catalog], warnings, missingNames };
  }

  const byLower = new Map<string, ElevenLabsVoiceRow>();
  for (const r of catalog) {
    byLower.set(r.name.toLowerCase().trim(), r);
  }

  for (const seg of parsed.orderedSegments) {
    if (seg.kind === "explicit") {
      voices.push({ ...seg.row });
      continue;
    }
    const key = seg.name.toLowerCase().trim();
    const hit = byLower.get(key);
    if (hit) {
      voices.push({
        ...hit,
        name: seg.name.trim(),
      });
    } else {
      missingNames.push(seg.name.trim());
    }
  }

  if (missingNames.length > 0) {
    warnings.push(
      `Some allowlist names could not be resolved in the ElevenLabs catalog: ${missingNames.join(", ")}.`,
    );
  }

  return { voices, warnings, missingNames };
}

/** Merge catalog metadata into allowlisted rows (same `voice_id` only). */
export function enrichAllowlistWithCatalog(
  allowlist: ElevenLabsVoiceRow[],
  catalog: ElevenLabsVoiceRow[],
): ElevenLabsVoiceRow[] {
  const byId = new Map(catalog.map((r) => [r.voice_id, r]));
  return allowlist.map((a) => {
    const hit = byId.get(a.voice_id);
    if (!hit) return { ...a };
    return {
      voice_id: a.voice_id,
      name: a.name,
      category: hit.category ?? a.category,
      labels: hit.labels ?? a.labels,
      preview_url: hit.preview_url ?? a.preview_url,
    };
  });
}

export function hasElevenLabsApiKey(): boolean {
  return Boolean(process.env.ELEVENLABS_API_KEY?.trim());
}

export async function fetchElevenLabsVoicesNormalized(): Promise<ElevenLabsVoiceRow[]> {
  const key = process.env.ELEVENLABS_API_KEY?.trim();
  if (!key) {
    throw new ElevenLabsVoicesFetchError(
      "ElevenLabs API key missing",
      503,
      "elevenlabs_missing_key",
    );
  }

  let res: Response;
  try {
    res = await fetch("https://api.elevenlabs.io/v1/voices", {
      method: "GET",
      headers: {
        "xi-api-key": key,
        Accept: "application/json",
      },
      signal: abortTimeout(),
    });
  } catch (e) {
    const detail = e instanceof Error ? e.message : String(e);
    const isAbort =
      (e instanceof DOMException && e.name === "AbortError") ||
      (e instanceof Error && /abort/i.test(e.message));
    throw new ElevenLabsVoicesFetchError(
      isAbort ? "ElevenLabs voices request timed out or aborted" : "ElevenLabs voices network error",
      503,
      "elevenlabs_network",
      safeUpstreamSnippet(detail, 200),
    );
  }

  const ct = res.headers.get("content-type") ?? "";
  const rawText = await res.text().catch(() => res.statusText);

  if (!res.ok) {
    const detail = safeUpstreamSnippet(rawText, 280);
    if (res.status === 401) {
      throw new ElevenLabsVoicesFetchError("Unauthorized", res.status, "elevenlabs_unauthorized", detail);
    }
    if (res.status === 403) {
      throw new ElevenLabsVoicesFetchError("Forbidden", res.status, "elevenlabs_forbidden", detail);
    }
    if (res.status === 429) {
      throw new ElevenLabsVoicesFetchError("Rate limited", res.status, "elevenlabs_rate_limited", detail);
    }
    throw new ElevenLabsVoicesFetchError(
      "ElevenLabs voices request failed",
      res.status >= 400 && res.status < 600 ? res.status : 502,
      "elevenlabs_upstream",
      detail || res.statusText,
    );
  }

  if (!ct.includes("json")) {
    throw new ElevenLabsVoicesFetchError(
      "Unexpected ElevenLabs response (not JSON)",
      502,
      "elevenlabs_bad_json",
      safeUpstreamSnippet(rawText, 120),
    );
  }

  let json: unknown;
  try {
    json = JSON.parse(rawText) as unknown;
  } catch {
    throw new ElevenLabsVoicesFetchError(
      "Invalid JSON from ElevenLabs",
      502,
      "elevenlabs_bad_json",
      safeUpstreamSnippet(rawText, 120),
    );
  }

  const raw = extractVoicesArray(json);
  const rows: ElevenLabsVoiceRow[] = [];
  for (const v of raw) {
    const n = normalizeRow(v);
    if (n) rows.push(n);
  }
  return sortElevenLabsVoicesForUi(rows);
}

export async function getElevenLabsVoiceDetails(
  voiceId: string,
): Promise<ElevenLabsVoiceRow | null> {
  const id = voiceId.trim();
  if (!id) return null;
  const key = process.env.ELEVENLABS_API_KEY?.trim();
  if (!key) return null;
  const url = `https://api.elevenlabs.io/v1/voices/${encodeURIComponent(id)}`;
  const res = await fetch(url, {
    method: "GET",
    headers: {
      "xi-api-key": key,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    signal: abortTimeout(),
  });
  if (!res.ok) return null;
  let json: unknown;
  try {
    json = (await res.json()) as unknown;
  } catch {
    return null;
  }
  return normalizeRow(json as ElevenLabsVoicesApiVoice);
}import "server-only";

import type { SpiritRuntimeSurface } from "@/lib/spirit/spirit-runtime-surface";

// ── model-routing - /chat vs /oracle Ollama ids (Prompt 9C) ──────────────────────
// > Hermes-class chat stays on OLLAMA_MODEL; Oracle lane can opt into a smaller model.

export type { SpiritRuntimeSurface } from "@/lib/spirit/spirit-runtime-surface";

export function getSpiritChatModelId(): string {
  return process.env.OLLAMA_MODEL?.trim() || "hermes4";
}

/** Oracle UI; falls back to chat model when ORACLE_OLLAMA_MODEL unset. */
export function getOracleModelId(): string {
  const o = process.env.ORACLE_OLLAMA_MODEL?.trim();
  if (o) return o;
  return getSpiritChatModelId();
}

export function resolveOllamaModelId(surface: SpiritRuntimeSurface): string {
  return surface === "oracle" ? getOracleModelId() : getSpiritChatModelId();
}import "server-only";

import { resolveVerifiedHttpUrl } from "@/lib/verified-http-url";

// Re-export for tests / importers that expect URL helpers from this module.
export { normalizeToHttpUrl, resolveVerifiedHttpUrl, isVerifiedHttpUrl } from "@/lib/verified-http-url";

// ── OpenAI Responses API - web_search tool (isolated from Hermes chat, Prompt 10B) ─
// > If OpenAI changes payload shapes, adjust normalize only - do not leak keys to client.

export type WebSearchSource = {
  title?: string;
  url?: string;
  snippet?: string;
  sourceType?: string;
};

export type OpenAiWebSearchOk = {
  ok: true;
  provider: "openai";
  query: string;
  searched: true;
  sources: WebSearchSource[];
  answerPreview?: string;
  rawCitations?: unknown;
};

export type OpenAiWebSearchFail = {
  ok: false;
  provider: "openai";
  searched: false;
  error: string;
  detail?: string;
};

export type OpenAiWebSearchResult = OpenAiWebSearchOk | OpenAiWebSearchFail;

const DEFAULT_TIMEOUT_MS = 45_000;

function webEnabled(): boolean {
  const v = process.env.WEB_SEARCH_ENABLED?.trim().toLowerCase();
  return v === "1" || v === "true" || v === "yes";
}

/** First non-empty string among common OpenAI / crawler URL field names. */
function pickRawUrlFromRecord(r: Record<string, unknown>): string | undefined {
  const keys = [
    "url",
    "link",
    "href",
    "uri",
    "start_url",
    "end_url",
    "source_url",
    "webpage_url",
    "open_url",
    "page_url",
  ] as const;
  for (const k of keys) {
    const v = r[k];
    if (typeof v === "string" && v.trim()) return v.trim();
  }
  return undefined;
}

function walkForSources(obj: unknown, out: WebSearchSource[], cap: number): void {
  if (out.length >= cap || obj == null) return;
  if (typeof obj !== "object") return;
  if (Array.isArray(obj)) {
    for (const x of obj) walkForSources(x, out, cap);
    return;
  }
  const r = obj as Record<string, unknown>;
  const rawUrl = pickRawUrlFromRecord(r);
  const url = resolveVerifiedHttpUrl(rawUrl);
  const title = typeof r.title === "string" ? r.title : typeof r.name === "string" ? r.name : undefined;
  const snippet =
    typeof r.snippet === "string"
      ? r.snippet
      : typeof r.description === "string"
        ? r.description
        : typeof r.text === "string"
          ? r.text
          : undefined;
  if (url?.trim() || title?.trim()) {
    out.push({
      url: url?.trim(),
      title: title?.trim(),
      snippet: snippet?.trim(),
      sourceType: typeof r.type === "string" ? r.type : undefined,
    });
  }
  for (const k of Object.keys(r)) walkForSources(r[k], out, cap);
}

/** Exported for unit tests - parses Responses `output[]` into deduped sources. */
export function extractWebSearchSourcesFromOpenAiResponseJson(
  json: Record<string, unknown>,
  maxResults: number,
): {
  sources: WebSearchSource[];
  answerPreview?: string;
  rawCitations?: unknown;
} {
  const sources: WebSearchSource[] = [];
  const output = json.output;
  let answerPreview: string | undefined;
  const citations: unknown[] = [];

  if (Array.isArray(output)) {
    for (const item of output) {
      if (!item || typeof item !== "object") continue;
      const it = item as Record<string, unknown>;
      if (it.type === "web_search_call") {
        walkForSources(it, sources, maxResults);
      }
      if (it.type === "message") {
        const content = it.content;
        if (Array.isArray(content)) {
          for (const c of content) {
            if (!c || typeof c !== "object") continue;
            const cc = c as Record<string, unknown>;
            if (cc.type === "output_text" && typeof cc.text === "string") {
              answerPreview = (answerPreview ?? "") + cc.text;
            }
            if (Array.isArray(cc.annotations)) {
              citations.push(...cc.annotations);
              for (const a of cc.annotations) {
                if (!a || typeof a !== "object") continue;
                const ann = a as Record<string, unknown>;
                if (ann.type === "url_citation" || ann.type === "citation") {
                  const rawU = pickRawUrlFromRecord(ann);
                  const u = resolveVerifiedHttpUrl(rawU);
                  const t = typeof ann.title === "string" ? ann.title : undefined;
                  if (u || t) sources.push({ url: u, title: t, sourceType: String(ann.type) });
                }
              }
            }
          }
        }
      }
    }
  }

  const dedup: WebSearchSource[] = [];
  const seen = new Set<string>();
  for (const s of sources) {
    const key = `${s.url ?? ""}|${s.title ?? ""}`;
    if (seen.has(key)) continue;
    seen.add(key);
    dedup.push(s);
    if (dedup.length >= maxResults) break;
  }

  if (answerPreview && answerPreview.length > 1200) {
    answerPreview = `${answerPreview.slice(0, 1199)}…`;
  }

  return {
    sources: dedup,
    answerPreview,
    rawCitations: citations.length ? citations : undefined,
  };
}

/**
 * OpenAI sometimes omits structured URLs but embeds https links in grounded preview text.
 * Same resolveVerifiedHttpUrl gate as walk/citations - keeps digest + headers aligned.
 */
export function appendVerifiedUrlsFromAnswerPreview(
  sources: WebSearchSource[],
  answerPreview: string | undefined,
  maxResults: number,
): WebSearchSource[] {
  if (sources.some((s) => Boolean(resolveVerifiedHttpUrl(s.url)))) return sources;
  const preview = answerPreview?.trim();
  if (!preview) return sources;

  const extra: WebSearchSource[] = [];
  const seen = new Set<string>();
  for (const s of sources) {
    const u = resolveVerifiedHttpUrl(s.url);
    if (u) seen.add(u);
  }

  const re = /https?:\/\/[^\s)\]>"']+/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(preview)) !== null && extra.length < maxResults) {
    const raw = m[0].replace(/[.,;:)\]]+$/g, "");
    const url = resolveVerifiedHttpUrl(raw);
    if (!url || seen.has(url)) continue;
    seen.add(url);
    extra.push({ url, title: undefined, sourceType: "answer_preview" });
  }
  if (extra.length === 0) return sources;

  const merged = [...sources, ...extra];
  const dedup: WebSearchSource[] = [];
  const used = new Set<string>();
  for (const s of merged) {
    const u = resolveVerifiedHttpUrl(s.url);
    if (!u) continue;
    if (used.has(u)) continue;
    used.add(u);
    dedup.push({ ...s, url: u });
    if (dedup.length >= maxResults) break;
  }
  return dedup;
}

export async function runOpenAiWebSearch(opts: {
  query: string;
  maxResults?: number;
  timeoutMs?: number;
}): Promise<OpenAiWebSearchResult> {
  const query = opts.query.trim();
  if (!query) {
    return { ok: false, provider: "openai", searched: false, error: "empty_query", detail: "Query is empty" };
  }

  if (!webEnabled()) {
    return {
      ok: false,
      provider: "openai",
      searched: false,
      error: "disabled",
      detail: "WEB_SEARCH_ENABLED is not true - web search is off.",
    };
  }

  const key = process.env.OPENAI_API_KEY?.trim();
  if (!key) {
    return {
      ok: false,
      provider: "openai",
      searched: false,
      error: "missing_key",
      detail: "OPENAI_API_KEY is not configured",
    };
  }

  const model =
    process.env.WEB_SEARCH_MODEL?.trim() ||
    process.env.OPENAI_WEB_SEARCH_MODEL?.trim() ||
    "gpt-4o";

  const maxResultsRaw = process.env.WEB_SEARCH_MAX_RESULTS?.trim();
  const maxResults =
    typeof opts.maxResults === "number" && opts.maxResults > 0
      ? Math.min(opts.maxResults, 12)
      : Math.min(Math.max(Number.parseInt(maxResultsRaw ?? "8", 10) || 8, 1), 12);

  const toolType = process.env.WEB_SEARCH_TOOL_TYPE?.trim() || "web_search";

  const controller = new AbortController();
  const to = setTimeout(() => controller.abort(), opts.timeoutMs ?? DEFAULT_TIMEOUT_MS);
  try {
    const res = await fetch("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        input: query,
        tools: [{ type: toolType }],
        tool_choice: "auto",
        // action.sources + results: OpenAI intermittently omits one shape - ask for both.
        include: ["web_search_call.action.sources", "web_search_call.results"],
      }),
      signal: controller.signal,
    });

    const rawText = await res.text();
    let json: unknown;
    try {
      json = JSON.parse(rawText) as unknown;
    } catch {
      return {
        ok: false,
        provider: "openai",
        searched: false,
        error: "invalid_json",
        detail: rawText.slice(0, 200),
      };
    }

    if (!res.ok) {
      const errObj = json && typeof json === "object" ? (json as Record<string, unknown>) : {};
      const msg =
        typeof errObj.error === "object" && errObj.error && "message" in (errObj.error as object)
          ? String((errObj.error as { message?: string }).message ?? res.statusText)
          : res.statusText;
      return {
        ok: false,
        provider: "openai",
        searched: false,
        error: `openai_${res.status}`,
        detail: msg.slice(0, 400),
      };
    }

    if (!json || typeof json !== "object") {
      return { ok: false, provider: "openai", searched: false, error: "bad_response", detail: "Empty JSON" };
    }

    const extracted = extractWebSearchSourcesFromOpenAiResponseJson(json as Record<string, unknown>, maxResults);
    const sources = appendVerifiedUrlsFromAnswerPreview(
      extracted.sources,
      extracted.answerPreview,
      maxResults,
    );
    return {
      ok: true,
      provider: "openai",
      query,
      searched: true,
      sources,
      answerPreview: extracted.answerPreview,
      rawCitations: extracted.rawCitations,
    };
  } catch (e) {
    const aborted = e instanceof Error && e.name === "AbortError";
    return {
      ok: false,
      provider: "openai",
      searched: false,
      error: aborted ? "timeout" : "fetch_failed",
      detail: e instanceof Error ? e.message : String(e),
    };
  } finally {
    clearTimeout(to);
  }
}import "server-only";

// ── STT provider - proxy browser audio → Faster-Whisper (OpenAI-style API) ───────
// > Docker: `whisper-stt` → :8000, POST /v1/audio/transcriptions (see backend/docker-compose.yml)

export class SttProviderError extends Error {
  constructor(
    message: string,
    public readonly statusCode: number,
  ) {
    super(message);
    this.name = "SttProviderError";
  }
}

/** Host URL for Faster-Whisper / compatible STT (no trailing slash required). */
export function getWhisperSttBaseURL(): string {
  const raw = process.env.WHISPER_STT_URL?.trim();
  return raw || "http://localhost:8000";
}

export function getWhisperTranscribePath(): string {
  const raw = process.env.WHISPER_STT_TRANSCRIBE_PATH?.trim();
  return raw || "/v1/audio/transcriptions";
}

export function getWhisperSttModel(): string {
  const raw = process.env.WHISPER_STT_MODEL?.trim();
  return raw || "whisper-1";
}

/** Safe label for JSON - hostname + port only, no auth path segments. */
export function getSttDiagnostics(): {
  provider: string;
  url: string;
  source: string;
  transcribePath: string;
} {
  const base = getWhisperSttBaseURL().replace(/\/$/, "");
  let hostPort = base;
  try {
    const u = new URL(base);
    hostPort = `${u.hostname}${u.port ? `:${u.port}` : ""}`;
  } catch {
    hostPort = "invalid WHISPER_STT_URL";
  }
  return {
    provider: "Whisper (Faster-Whisper)",
    url: hostPort,
    source: process.env.WHISPER_STT_URL?.trim() ? "WHISPER_STT_URL" : "default (http://localhost:8000)",
    transcribePath: getWhisperTranscribePath(),
  };
}

type TranscribeOk = {
  ok: true;
  provider: "whisper";
  text: string;
  durationMs?: number;
};

/**
 * `form` must contain `audio` (Blob/File). Optional `language` (ISO code).
 * Forwards to upstream as OpenAI-style multipart: `file`, `model`, optional `language`, `response_format`.
 */
export async function transcribeSpeech(form: FormData): Promise<TranscribeOk> {
  const audio = form.get("audio");
  if (!audio || typeof (audio as Blob).arrayBuffer !== "function") {
    throw new SttProviderError("Audio blob required", 400);
  }
  const blob = audio as Blob;
  if (blob.size < 1) {
    throw new SttProviderError("Empty audio", 400);
  }

  const base = getWhisperSttBaseURL().replace(/\/$/, "");
  const path = getWhisperTranscribePath();
  const model = getWhisperSttModel();
  const url = `${base}${path.startsWith("/") ? path : `/${path}`}`;

  const upstream = new FormData();
  const ext = guessAudioExtension(blob.type);
  upstream.append("file", blob, `upload.${ext}`);
  upstream.append("model", model);
  upstream.append("response_format", "json");
  const lang = form.get("language");
  if (typeof lang === "string" && lang.trim()) {
    upstream.append("language", lang.trim());
  }

  let res: Response;
  try {
    res = await fetch(url, { method: "POST", body: upstream });
  } catch {
    throw new SttProviderError("Whisper backend unreachable", 503);
  }

  if (!res.ok) {
    const detail = await safeText(res);
    const msg = detail ? `Upstream STT ${res.status}: ${detail.slice(0, 200)}` : `Upstream STT ${res.status}`;
    throw new SttProviderError(msg, res.status >= 500 ? 502 : 502);
  }

  let json: unknown;
  try {
    json = await res.json();
  } catch {
    throw new SttProviderError("Invalid JSON from Whisper backend", 502);
  }

  if (!json || typeof json !== "object") {
    throw new SttProviderError("Invalid STT response shape", 502);
  }

  const text =
    typeof (json as { text?: unknown }).text === "string"
      ? (json as { text: string }).text.trim()
      : "";

  const durationMs =
    typeof (json as { duration?: unknown }).duration === "number"
      ? (json as { duration: number }).duration
      : typeof (json as { duration_ms?: unknown }).duration_ms === "number"
        ? (json as { duration_ms: number }).duration_ms
        : undefined;

  return { ok: true, provider: "whisper", text, durationMs };
}

function guessAudioExtension(mime: string): string {
  const m = mime.toLowerCase();
  if (m.includes("webm")) return "webm";
  if (m.includes("mp4") || m.includes("m4a")) return "m4a";
  if (m.includes("wav")) return "wav";
  if (m.includes("mpeg") || m.includes("mp3")) return "mp3";
  return "webm";
}

async function safeText(res: Response): Promise<string> {
  try {
    return await res.text();
  } catch {
    return "";
  }
}import "server-only";

import {
  clampTtsVoiceSpeed,
  TTS_SPEED_DEFAULT,
} from "@/lib/tts/voice-speed";
import {
  parseElevenLabsVoiceAllowlistFromEnv,
  pickDefaultElevenLabsVoice,
  sortElevenLabsVoicesForUi,
} from "@/lib/server/elevenlabs-voices";

// ── tts-provider - Piper + ElevenLabs server-side (Prompt 9C; no keys to client) ───

export type TtsProvider = "piper" | "elevenlabs";

export type TtsRequestInput = {
  text: string;
  /** Piper OpenAI-style voice name (e.g. fable). */
  voice?: string;
  /** ElevenLabs `voice_id` from client Voice picker; Piper ignores. */
  voiceId?: string;
  /** Client label for response headers / latency line - not used to pick ElevenLabs URL. */
  voiceName?: string;
  language?: string;
  responseFormat?: "wav" | "mp3";
  /** Client override (e.g. Voice settings); clamped 0.7–1.2. ElevenLabs only. */
  speed?: number;
};

export type TtsProviderResult = {
  audio: ArrayBuffer;
  contentType: string;
  provider: TtsProvider;
  upstreamMs?: number;
  /** Applied voice speed (ElevenLabs voice_settings; echoed for /api/tts headers). */
  speed?: number;
  /** ElevenLabs voice_id applied (echoed for client latency line). */
  voiceId?: string;
  /** Friendly label (from client `voiceName` or Piper `voice`). */
  voiceName?: string;
};

export class TtsProviderError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    public readonly provider: TtsProvider,
    public readonly detail?: string,
    public readonly code?: "elevenlabs_missing_key",
  ) {
    super(message);
    this.name = "TtsProviderError";
  }
}

const FETCH_TIMEOUT_MS = 60_000;

function envTtsVoiceSpeed(): number {
  const raw = process.env.ELEVENLABS_VOICE_SPEED;
  const v = raw === undefined || raw === "" ? NaN : Number.parseFloat(String(raw).trim());
  if (!Number.isFinite(v)) return TTS_SPEED_DEFAULT;
  return clampTtsVoiceSpeed(v);
}

/**
 * Final speed: finite client `override` wins (clamped), else env default (clamped).
 */
export function resolveTtsVoiceSpeed(override?: number | null): number {
  if (typeof override === "number" && Number.isFinite(override)) {
    return clampTtsVoiceSpeed(override);
  }
  return envTtsVoiceSpeed();
}

function resolveElevenLabsVoiceIdFromInput(input: TtsRequestInput): string {
  const req = input.voiceId?.trim();
  if (req) return req;
  const parsed = parseElevenLabsVoiceAllowlistFromEnv();
  if (parsed.explicitVoices.length > 0) {
    const picked = pickDefaultElevenLabsVoice(sortElevenLabsVoicesForUi(parsed.explicitVoices));
    if (picked.defaultVoiceId) return picked.defaultVoiceId;
  }
  return (
    process.env.ELEVENLABS_DEFAULT_VOICE_ID?.trim() ||
    process.env.ELEVENLABS_VOICE_ID?.trim() ||
    "fgDJOgmENIR82PueQrVs"
  );
}

function abortTimeout(): AbortSignal {
  try {
    return AbortSignal.timeout(FETCH_TIMEOUT_MS);
  } catch {
    const c = new AbortController();
    const t = setTimeout(() => c.abort(), FETCH_TIMEOUT_MS);
    void t.unref?.();
    return c.signal;
  }
}

export function getTtsProvider(): TtsProvider {
  const raw = process.env.TTS_PROVIDER?.trim().toLowerCase();
  if (raw === "elevenlabs") return "elevenlabs";
  if (raw === "piper" || raw === "" || raw === undefined) return "piper";
  console.warn(`[tts] unknown TTS_PROVIDER "${raw}", falling back to piper`);
  return "piper";
}

export async function synthesizeWithPiper(
  input: TtsRequestInput,
): Promise<TtsProviderResult> {
  const t0 = Date.now();
  const voice =
    input.voice?.trim() ||
    process.env.PIPER_TTS_VOICE?.trim() ||
    "fable";
  const language = input.language?.trim() || "en";
  const responseFormat = input.responseFormat ?? "wav";

  const base = process.env.PIPER_TTS_URL?.trim() || "http://localhost:5200";
  const endpoint = `${base.replace(/\/$/, "")}/v1/audio/speech`;

  const upstreamBody = {
    model: "tts-1",
    voice,
    input: input.text,
    response_format: responseFormat,
    language,
  };

  let upstream: Response;
  try {
    upstream = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(upstreamBody),
      signal: abortTimeout(),
    });
  } catch (e) {
    const detail = e instanceof Error ? e.message : String(e);
    throw new TtsProviderError("TTS provider unreachable", 503, "piper", detail);
  }

  if (!upstream.ok) {
    const detail = await upstream.text().catch(() => upstream.statusText);
    throw new TtsProviderError("TTS provider unreachable", 503, "piper", detail);
  }

  const audio = await upstream.arrayBuffer();
  const contentType =
    upstream.headers.get("content-type") ||
    (responseFormat === "mp3" ? "audio/mpeg" : "audio/wav");

  const speed = resolveTtsVoiceSpeed(input.speed ?? null);

  return {
    audio,
    contentType,
    provider: "piper",
    upstreamMs: Date.now() - t0,
    speed,
    voiceName: voice,
  };
}

export async function synthesizeWithElevenLabs(
  input: TtsRequestInput,
): Promise<TtsProviderResult> {
  const key = process.env.ELEVENLABS_API_KEY?.trim();
  if (!key) {
    throw new TtsProviderError(
      "ElevenLabs API key missing",
      503,
      "elevenlabs",
      "Set ELEVENLABS_API_KEY",
      "elevenlabs_missing_key",
    );
  }

  const voiceId = resolveElevenLabsVoiceIdFromInput(input);
  const echoVoiceName = input.voiceName?.trim() || undefined;
  const modelId =
    process.env.ELEVENLABS_MODEL_ID?.trim() || "eleven_turbo_v2_5";
  const outputFormat =
    process.env.ELEVENLABS_OUTPUT_FORMAT?.trim() || "mp3_44100_128";

  const speed = resolveTtsVoiceSpeed(input.speed ?? null);

  const t0 = Date.now();
  const url = new URL(
    `https://api.elevenlabs.io/v1/text-to-speech/${encodeURIComponent(voiceId)}`,
  );
  url.searchParams.set("output_format", outputFormat);

  const body = {
    text: input.text,
    model_id: modelId,
    voice_settings: {
      stability: 0.45,
      similarity_boost: 0.75,
      style: 0.25,
      use_speaker_boost: true,
      speed,
    },
  };

  let res: Response;
  try {
    res = await fetch(url.toString(), {
      method: "POST",
      headers: {
        "xi-api-key": key,
        "Content-Type": "application/json",
        Accept: "audio/mpeg, audio/*, */*",
      },
      body: JSON.stringify(body),
      signal: abortTimeout(),
    });
  } catch (e) {
    const detail = e instanceof Error ? e.message : String(e);
    throw new TtsProviderError("TTS provider unreachable", 503, "elevenlabs", detail);
  }

  if (!res.ok) {
    const detail = await res.text().catch(() => res.statusText);
    throw new TtsProviderError(
      "TTS provider unreachable",
      res.status >= 400 && res.status < 600 ? res.status : 503,
      "elevenlabs",
      detail.slice(0, 500),
    );
  }

  const audio = await res.arrayBuffer();
  const contentType =
    res.headers.get("content-type")?.split(";")[0]?.trim() || "audio/mpeg";

  return {
    audio,
    contentType,
    provider: "elevenlabs",
    upstreamMs: Date.now() - t0,
    speed,
    voiceId,
    voiceName: echoVoiceName,
  };
}

/**
 * Primary = env TTS_PROVIDER; ElevenLabs errors fall back to Piper when primary was ElevenLabs.
 */
export async function synthesizeSpeech(
  input: TtsRequestInput,
): Promise<TtsProviderResult> {
  const primary = getTtsProvider();

  if (primary === "elevenlabs") {
    try {
      return await synthesizeWithElevenLabs(input);
    } catch (e) {
      if (
        e instanceof TtsProviderError &&
        e.code === "elevenlabs_missing_key"
      ) {
        throw e;
      }
      console.warn("[tts] ElevenLabs failed, falling back to Piper:", e);
      return await synthesizeWithPiper(input);
    }
  }

  return await synthesizeWithPiper(input);
}/// <reference types="vitest/globals" />

import { sanitizeAssistantVisibleText } from "@/lib/spirit/assistant-output-sanitizer";

describe("sanitizeAssistantVisibleText", () => {
  it("removes redacted_thinking blocks", () => {
    const open = "<" + "redacted_thinking" + ">";
    const close = "<" + "/" + "redacted_thinking" + ">";
    const t = ["Hello", open, 'Respond in "Sassy mode" only', "Keep sentences short", close, "World"].join("\n");
    expect(sanitizeAssistantVisibleText(t)).toBe("Hello\n\nWorld");
  });

  it("unwraps leaked visible chat_message container tags", () => {
    const t = `<chat_message> It could be a lot of things.

A hot engine stalling is never good. </chat_message>`;
    expect(sanitizeAssistantVisibleText(t)).toBe(
      "It could be a lot of things.\n\nA hot engine stalling is never good.",
    );
  });

  it("unwraps assistant_response container tags without removing inner text", () => {
    const t = `<assistant_response tone="peer">Check the actual error first.</assistant_response>`;
    expect(sanitizeAssistantVisibleText(t)).toBe("Check the actual error first.");
  });

  it("removes leaked Sassy contract lines", () => {
    const t = `Go touch grass.

Respond in "Sassy mode" only
Keep sentences short
No hidden chain-of-thought

Actually: fine.`;
    expect(sanitizeAssistantVisibleText(t)).not.toContain("Sassy mode");
    expect(sanitizeAssistantVisibleText(t)).toContain("touch grass");
    expect(sanitizeAssistantVisibleText(t)).toContain("Actually: fine.");
  });

  it("removes leaked Brutal contract lines", () => {
    const t = `Truth here.

Respond in "Brutal mode" only
Mode contract:

Do the thing.`;
    expect(sanitizeAssistantVisibleText(t)).not.toContain("Brutal mode");
    expect(sanitizeAssistantVisibleText(t)).toContain("Truth here");
  });

  it("removes leaked coding-assistant customer-service line", () => {
    const t = `Hey.

I'm here to help with coding questions

So anyway: drink water.`;
    const out = sanitizeAssistantVisibleText(t);
    expect(out).not.toContain("coding questions");
    expect(out).toContain("drink water");
  });

  it("keeps normal text that mentions thinking in prose", () => {
    const t = "I think we should refactor the module.";
    expect(sanitizeAssistantVisibleText(t)).toBe(t);
  });
});import { describe, expect, it } from "vitest";

import {
