describe("isDegenerateSourcesBlock", () => {
  it("flags ordered list with only citation numbers", () => {
    expect(isDegenerateSourcesBlock("1. 1\n2. 2")).toBe(true);
  });

  it("flags [n](url) stub links", () => {
