describe("decideSpiritRoute", () => {
  const base = {
    modelHint: "hermes4:latest",
    webSearchGloballyEnabled: true,
    deepThinkEnabled: false,
    webSearchOptOut: false,
  };

  it("peer + casual → local-chat, no web", () => {
    const d = decideSpiritRoute({
      ...base,
      modelProfileId: "normal-peer",
      lastUserText: "sup",
    });
    expect(d.lane).toBe("local-chat");
    expect(d.shouldSearchWeb).toBe(false);
    expect(d.shouldDraftResearchPlan).toBe(false);
    expect(d.shouldShowVisualizer).toBe(false);
  });

  it("researcher + depth → local-web-search lane when prefetch triggers", () => {
    const d = decideSpiritRoute({
      ...base,
      modelProfileId: "researcher",
      lastUserText: "Summarize the latest systematic reviews on sleep and cognition",
    });
    expect(d.lane).toBe("local-web-search");
    expect(d.shouldSearchWeb).toBe(true);
    expect(d.shouldDraftResearchPlan).toBe(true);
    expect(d.shouldShowVisualizer).toBe(true);
  });

  it("researcher + casual → still prefetches web by default, hides visualizer", () => {
    const d = decideSpiritRoute({
      ...base,
      modelProfileId: "researcher",
      lastUserText: "yo",
    });
    expect(d.shouldSearchWeb).toBe(true);
    expect(d.lane).toBe("local-web-search");
    expect(d.shouldShowVisualizer).toBe(false);
  });

  it("researcher + substantive + web off → research-plan lane, no prefetch", () => {
    const d = decideSpiritRoute({
      ...base,
      webSearchGloballyEnabled: false,
      modelProfileId: "researcher",
      lastUserText:
        "Walk me through how heterogeneity is measured in random-effects meta-analysis models.",
    });
    expect(d.shouldSearchWeb).toBe(false);
    expect(d.lane).toBe("research-plan");
    expect(d.shouldDraftResearchPlan).toBe(true);
  });

  it("teacher + teaching depth shows visualizer", () => {
    const d = decideSpiritRoute({
      ...base,
      modelProfileId: "teacher",
      lastUserText: "Explain this homework step by step",
    });
    expect(d.shouldShowVisualizer).toBe(true);
  });

  it("deep think forces visualizer for casual peer", () => {
    const d = decideSpiritRoute({
      ...base,
      deepThinkEnabled: true,
      modelProfileId: "normal-peer",
      lastUserText: "hi",
    });
    expect(d.shouldShowVisualizer).toBe(true);
  });

  it("teacher + teacher web + study-aids prompt → local-web-search and shouldSearchTeacherWeb", () => {
    const d = decideSpiritRoute({
      ...base,
      modelProfileId: "teacher",
      teacherWebSearchEnabled: true,
      lastUserText: "Explain the latest peer-reviewed studies on sleep and cognition for my exam",
    });
    expect(d.shouldSearchTeacherWeb).toBe(true);
    expect(d.lane).toBe("local-web-search");
  });

  it("teacher + study prompt + omitted teacherWebSearchEnabled defaults to teacher web aids", () => {
    const d = decideSpiritRoute({
      ...base,
      modelProfileId: "teacher",
      lastUserText: "Define negative punishment with an ABA example for my exam",
    });
    expect(d.shouldSearchTeacherWeb).toBe(true);
    expect(d.lane).toBe("local-web-search");
  });

  it("teacher + sensory topic without explain/teach verbs → still uses web aids lane", () => {
    const d = decideSpiritRoute({
      ...base,
      modelProfileId: "teacher",
      lastUserText: "How is sensory overload different from a tantrum in young kids?",
    });
    expect(d.shouldSearchTeacherWeb).toBe(true);
    expect(d.lane).toBe("local-web-search");
  });

  it("teacher web toggle off → no teacher web search", () => {
    const d = decideSpiritRoute({
      ...base,
      modelProfileId: "teacher",
      teacherWebSearchEnabled: false,
      lastUserText: "Find the latest peer-reviewed studies on sleep and cognition",
    });
    expect(d.shouldSearchTeacherWeb).toBe(false);
  });
});import { describe, expect, it } from "vitest";

import { normalizeClientSearchStatus, parseSpiritSearchHeaders } from "@/lib/spirit/spirit-search-response-headers";

describe("parseSpiritSearchHeaders", () => {
  it("parses headers into structured fields", () => {
    const headers = new Headers();
    headers.set("x-spirit-route-lane", "local-web-search");
    headers.set("x-spirit-route-confidence", "high");
    headers.set("x-spirit-web-search", "used");
    headers.set("x-spirit-search-status", "used");
    headers.set("x-spirit-search-provider", "searxng");
    headers.set("x-spirit-source-count", "4");
    headers.set("x-spirit-search-query", "history of telegraph");
    headers.set("x-spirit-search-elapsed-ms", "900");
    headers.set("x-spirit-search-kind", "teacher");
    const res = new Response(null, { headers });
    const p = parseSpiritSearchHeaders(res);
    expect(p.searchStatus).toBe("used");
    expect(p.sourceCount).toBe(4);
    expect(p.searchElapsedMs).toBe(900);
    expect(p.searchKind).toBe("teacher");
    expect(p.searchQuery).toContain("telegraph");
    expect(p.searchProvider).toBe("searxng");
    expect(p.routeLane).toBe("local-web-search");
  });

  it("keeps legacy openai-web-search lane readable for older responses", () => {
    const headers = new Headers();
    headers.set("x-spirit-route-lane", "openai-web-search");
    const res = new Response(null, { headers });
    expect(parseSpiritSearchHeaders(res).routeLane).toBe("openai-web-search");
  });

  it("normalizeClientSearchStatus maps none for garbage", () => {
    expect(normalizeClientSearchStatus("weird")).toBe("none");
  });
});import { describe, expect, it } from "vitest";

import { parseSpiritWebSourcesHeader } from "@/lib/spirit/spirit-web-sources";

describe("parseSpiritWebSourcesHeader", () => {
  it("parses valid JSON header payload", () => {
    const json = JSON.stringify({
      provider: "searxng",
      count: 1,
      sources: [{ title: "T", url: "https://t" }],
    });
    const out = parseSpiritWebSourcesHeader(json);
    expect(out?.provider).toBe("searxng");
    expect(out?.count).toBe(1);
