  it("returns null on invalid JSON", () => {
    expect(parseSpiritWebSourcesHeader("{")).toBeNull();
  });

  it("returns null for empty input", () => {
    expect(parseSpiritWebSourcesHeader(null)).toBeNull();
    expect(parseSpiritWebSourcesHeader("")).toBeNull();
  });
});import { describe, expect, it } from "vitest";

