    const { probeOllamaChatCompletionsAcceptsToolSchema } = await import("@/lib/server/ollama");
    vi.mocked(probeOllamaChatCompletionsAcceptsToolSchema).mockResolvedValue(true);
  });

  afterEach(() => {
