});import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "fs";
import { tmpdir } from "os";
import path from "path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { TOOL_MAX_FILE_BYTES } from "../tool-safety";
import {
  getSystemStatus,
  listWorkspaceFiles,
  readLogTail,
  readWorkspaceFile,
} from "../workspace-tools";

describe("workspace-tools", () => {
  let fixture: string;

  beforeEach(() => {
    fixture = mkdtempSync(path.join(tmpdir(), "spirit-ws-"));
    vi.stubEnv("SPIRIT_PROJECT_PATH", fixture);
    mkdirSync(path.join(fixture, "src"));
    writeFileSync(path.join(fixture, "src/hello.ts"), "export const x = 1;\n");
    mkdirSync(path.join(fixture, "node_modules"));
    writeFileSync(path.join(fixture, "node_modules/shadow.txt"), "no");
    writeFileSync(path.join(fixture, "blocked.pem"), "-----BEGIN");
    writeFileSync(path.join(fixture, ".env.local"), "SECRET=1");
  });

  afterEach(() => {
    rmSync(fixture, { recursive: true, force: true });
    vi.unstubAllEnvs();
  });

  it("listWorkspaceFiles lists safe files", async () => {
    const r = await listWorkspaceFiles({ directory: ".", maxEntries: 50 });
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error("expected ok");
    const names = r.entries.map((e) => e.name);
    expect(names).toContain("src");
    expect(names).not.toContain("node_modules");
  });

  it("listWorkspaceFiles hides blocked entries", async () => {
    const r = await listWorkspaceFiles({});
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error("expected ok");
    const names = r.entries.map((e) => e.name);
    expect(names).not.toContain("node_modules");
    expect(names).not.toContain(".env.local");
    expect(names).not.toContain("blocked.pem");
  });

  it("readWorkspaceFile reads safe text file", async () => {
    const r = await readWorkspaceFile({ filePath: "src/hello.ts" });
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error("expected ok");
    expect(r.content).toContain("export const x");
  });

  it("readWorkspaceFile rejects blocked files", async () => {
    const r = await readWorkspaceFile({ filePath: ".env.local" });
    expect(r.ok).toBe(false);
  });

  it("readWorkspaceFile rejects oversized file", async () => {
    const bigName = "big.txt";
    writeFileSync(path.join(fixture, bigName), Buffer.alloc(TOOL_MAX_FILE_BYTES + 1, 97));
    const r = await readWorkspaceFile({ filePath: bigName });
    expect(r.ok).toBe(false);
    if (r.ok) throw new Error("expected failure");
    expect(r.code).toBe("FILE_TOO_LARGE");
  });

  it("readLogTail returns last N lines", async () => {
    const lines = Array.from({ length: 120 }, (_, i) => `line ${i + 1}`);
    writeFileSync(path.join(fixture, "app.log"), `${lines.join("\n")}\n`);
    const r = await readLogTail({ filePath: "app.log", lineCount: 10 });
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error("expected ok");
    expect(r.lines[r.lines.length - 1]).toMatch(/line 120/);
    expect(r.lines.length).toBeLessThanOrEqual(11);
  });

  it("readLogTail caps lineCount", async () => {
    const lines = Array.from({ length: 400 }, (_, i) => `L${i}`);
    writeFileSync(path.join(fixture, "big.log"), lines.join("\n"));
    const r = await readLogTail({ filePath: "big.log", lineCount: 9999 });
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error("expected ok");
    expect(r.lines.length).toBeLessThanOrEqual(300);
  });

  it("getSystemStatus reports read-only tools available only when env enabled", async () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "false");
    let s = await getSystemStatus();
    expect(s.availableReadOnlyTools.length).toBe(0);
    expect(s.unavailableTools.join(",")).toContain("list_workspace_files");

    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "true");
    s = await getSystemStatus();
    expect(s.availableReadOnlyTools.sort()).toEqual(
      ["get_system_status", "list_workspace_files", "read_log_tail", "read_workspace_file"].sort(),
    );
    expect(s.unavailableTools).toContain("file_editing");
    expect(s.unavailableTools).toContain("terminal_execution");
    expect(s.unavailableTools).toContain("email_access");
    expect(s.unavailableTools).toContain("calendar_access");
    expect(JSON.stringify(s)).not.toMatch(/[/]home[/]/);
  });
});// ── direct-dev-command-request - Phase 6B: allowlisted dev commands without LLM tools ─
// > Same safety as runDevCommand; fixed phrases only; never shell or user strings.

import "server-only";

import type { DevCommandResult } from "@/lib/spirit/tools/dev-command-tools";
import { isDevCommandToolsEnvEnabled, runDevCommand } from "@/lib/spirit/tools/dev-command-tools";
import {
  createSpiritToolActivityCard,
  type SpiritToolActivityCard,
} from "@/lib/spirit/spirit-activity-events";
import { isLocalToolsEnabled } from "@/lib/spirit/tools/tool-registry";

export type DirectDevCommandRequest =
  | { commandId: "git_status"; confirm?: boolean }
  | { commandId: "git_diff"; confirm?: boolean }
  | { commandId: "npm_typecheck"; confirm?: boolean }
  | { commandId: "npm_test"; confirm?: boolean }
  | { commandId: "npm_lint"; confirm?: boolean }
  | { commandId: "npm_build"; confirm?: boolean };

export type DirectDevCommandHandleResult = {
  markdown: string;
  toolActivity: SpiritToolActivityCard[];
};

function normalizeDirectPhrase(raw: string): string {
  return raw
    .trim()
    .replace(/\s+/g, " ")
    .replace(/^please\s+/i, "")
    .replace(/[?.!]+$/g, "")
    .trim();
}

function parseConfirmFlag(raw: string): boolean {
  return /\bconfirm\s+true\b/i.test(raw) || /\byes\s+confirm\b/i.test(raw);
}

/**
 * Concrete allowlisted phrases only. Returns null when vague or unsafe.
 */
export function parseDirectDevCommandRequest(text: string): DirectDevCommandRequest | null {
  const raw = text.trim();
  if (raw.length < 4) return null;
  const lower = raw.toLowerCase();

  if (/\bnpm\s+install\b/i.test(lower)) return null;
  if (/\brm\s+-\s*rf\b/i.test(lower) || /\brm\s+-rf\b/i.test(lower)) return null;
  if (/\bcurl\b/i.test(lower)) return null;
  if (/\bprint\s+env\b/i.test(lower)) return null;
  if (/\bshow\s+secrets\b/i.test(lower)) return null;
  if (/\brun\s+this\s+command\b/i.test(lower)) return null;
  if (/^can\s+you\s+run\s+commands?\s*$/i.test(normalizeDirectPhrase(raw))) return null;
  if (/\bopen\s+terminal\b/i.test(lower)) return null;

  const confirm = parseConfirmFlag(raw);
  let work = normalizeDirectPhrase(raw).toLowerCase();
  work = work
    .replace(/\bconfirm\s+true\b/g, "")
    .replace(/\byes\s+confirm\b/g, "")
    .replace(/\s+/g, " ")
    .trim();

  if (work === "npm run build" || work === "run build") {
    return { commandId: "npm_build", ...(confirm ? { confirm: true } : {}) };
  }
  if (work === "npm run lint" || work === "run lint") {
    return { commandId: "npm_lint", ...(confirm ? { confirm: true } : {}) };
  }
  if (
    work === "npm run typecheck" ||
    work === "run npm typecheck" ||
    work === "run typecheck" ||
    work === "check types"
  ) {
    return { commandId: "npm_typecheck", ...(confirm ? { confirm: true } : {}) };
  }
  if (
    work === "run npm test" ||
    work === "run tests" ||
    work === "npx vitest run" ||
    work === "run vitest"
  ) {
    return { commandId: "npm_test", ...(confirm ? { confirm: true } : {}) };
  }
  if (
    work === "check git status" ||
    work === "show git status" ||
    work === "git status" ||
    work === "what changed in git"
  ) {
    return { commandId: "git_status", ...(confirm ? { confirm: true } : {}) };
  }
  if (work === "show git diff" || work === "git diff" || work === "show the diff") {
    return { commandId: "git_diff", ...(confirm ? { confirm: true } : {}) };
  }

  return null;
}

function formatDirectDevReply(result: DevCommandResult): string {
  if (result.requiresConfirmation) {
    const hint =
      result.commandId === "npm_test"
        ? "Run npm test confirm true"
        : result.commandId === "npm_build"
          ? "Run build confirm true"
          : "confirm true";
    return `Confirmation required before running ${result.commandId}. Reply with: ${hint}`;
  }

  if (result.error) {
    const safe =
      result.error.code === "SCRIPT_NOT_FOUND" ||
      result.error.code === "UNKNOWN_COMMAND" ||
      result.error.code === "DEV_COMMAND_TOOLS_DISABLED"
        ? result.error.message
        : "That command could not be run from this shortcut.";
    return safe;
  }

  const body = (result.output ?? "").trim();
  const label = result.label;

  if (result.timedOut || result.ok === false) {
    const exit = result.exitCode ?? "unknown";
    return [
      `Dev command failed: ${label}`,
      `Exit code: ${exit}`,
      "",
      "```text",
      body || result.message || "(no output)",
      "```",
    ].join("\n");
  }

  return [`Dev command: ${label}`, "", "```text", body || "(no output)", "```"].join("\n");
}

function devCommandResultToCards(result: DevCommandResult): SpiritToolActivityCard[] {
  if (result.requiresConfirmation) {
    return [
      createSpiritToolActivityCard({
        kind: "dev_command_started",
        label: "Dev command",
        status: "confirmation_required",
        target: result.commandId,
        summary: result.label,
      }),
    ];
  }

  if (result.error) {
    const kind =
      result.error.code === "DEV_COMMAND_TOOLS_DISABLED" ||
      result.error.code === "SCRIPT_NOT_FOUND" ||
      result.error.code === "UNKNOWN_COMMAND"
        ? ("tool_unavailable" as const)
        : ("dev_command_failed" as const);
    const status: SpiritToolActivityCard["status"] =
      kind === "tool_unavailable" ? "failed" : "failed";
    return [
      createSpiritToolActivityCard({
        kind,
        label: "Dev command",
        status,
        target: result.commandId,
        safeMessage: result.error.message,
      }),
    ];
  }

  if (result.timedOut || result.ok === false) {
    return [
      createSpiritToolActivityCard({
        kind: "dev_command_failed",
        label: "Dev command",
        status: "failed",
        target: result.commandId,
        summary: result.timedOut ? "Timed out" : `Exit ${result.exitCode ?? "?"}`,
      }),
    ];
  }

  return [
    createSpiritToolActivityCard({
      kind: "dev_command_completed",
      label: "Dev command",
      status: "completed",
      target: result.commandId,
      summary: result.label,
    }),
  ];
}

export async function handleDirectDevCommandRequest(
  text: string,
): Promise<DirectDevCommandHandleResult | null> {
  if (!isDevCommandToolsEnvEnabled()) return null;
  if (!isLocalToolsEnabled()) return null;

  const parsed = parseDirectDevCommandRequest(text);
  if (!parsed) return null;

  const result = await runDevCommand({
    commandId: parsed.commandId,
    ...(parsed.confirm === true ? { confirm: true } : {}),
  });

  return {
    markdown: formatDirectDevReply(result),
    toolActivity: devCommandResultToCards(result),
  };
}// direct-workspace-request - read-only workspace without LLM tool calls
// > Same path discipline as tools; never leaks workspace root; uses workspace-tools only.

import "server-only";

import { pathFragmentLooksConcrete } from "@/lib/spirit/concrete-workspace-read-request";
import {
  createSpiritToolActivityCard,
  type SpiritToolActivityCard,
} from "@/lib/spirit/spirit-activity-events";
import {
  listWorkspaceFiles,
  readLogTail,
  readWorkspaceFile,
} from "@/lib/spirit/tools/workspace-tools";
import {
  listWindowsFiles,
  normalizeWindowsRequestPath,
} from "@/lib/spirit/tools/windows-workspace-tools";
import { isLocalToolsEnabled } from "@/lib/spirit/tools/tool-registry";

function trimPathFragment(fragment: string): string {
  return fragment.replace(/^[`"']+/, "").replace(/[`"'.,;:!?]+$/, "").trim();
}

function normalizeListPathFragment(fragment: string): string {
  let pathPart = trimPathFragment(fragment).replace(/\\/g, "/").trim();
  pathPart = pathPart.replace(/^my\s+/i, "").trim();
  pathPart = pathPart.replace(/\s+(folder|directory|dir)\s*$/i, "").trim();
  return trimPathFragment(pathPart);
}

export type DirectWorkspaceRequest =
  | { kind: "list"; source: "workspace" | "windows"; directory: string }
  | { kind: "read"; filePath: string }
  | { kind: "tail"; filePath: string; lineCount?: number };

export type DirectWorkspaceHandleResult = {
  markdown: string;
  toolActivity: SpiritToolActivityCard[];
};

function parseListPathFragment(fragment: string): DirectWorkspaceRequest | null {
  const pathPart = normalizeListPathFragment(fragment);
  if (!pathFragmentLooksConcrete(pathPart)) return null;
  const winPath = normalizeWindowsRequestPath(pathPart);
  if (winPath) {
    return { kind: "list", source: "windows", directory: winPath };
  }
  return { kind: "list", source: "workspace", directory: pathPart };
}

function fenceLang(filePath: string): string {
  const lower = filePath.toLowerCase();
  if (lower.endsWith(".json")) return "json";
  if (/\.(ts|tsx|mts|cts)$/.test(lower)) return "typescript";
  if (/\.(js|jsx|mjs|cjs)$/.test(lower)) return "javascript";
  if (/\.(md|mdx)$/.test(lower)) return "markdown";
  if (/\.(ya?ml|toml)$/.test(lower)) return "yaml";
  if (/\.(css|html|svg)$/.test(lower)) return "text";
  if (lower.endsWith(".log") || lower.endsWith(".txt")) return "text";
  return "text";
}

/**
 * Parse a concrete list/read/tail request; returns null for vague asks or blocked intents.
 * Mirrors `isConcreteWorkspaceReadRequest` extraction logic.
 */
export function parseDirectWorkspaceRequest(text: string): DirectWorkspaceRequest | null {
  const raw = text.trim();
  if (raw.length < 6) return null;
  const lower = raw.toLowerCase();

  if (
    /\b(run|execute|exec|bash|shell|terminal|sudo|npm\s+(test|run|install|ci|start|dev|exec)|pnpm\s|yarn\s+(test|install|add))\b/i.test(
      lower,
    )
  ) {
    return null;
  }

  if (/\b(edit|delete|write|create|mkdir|rm\s|mv\s|cp\s|move|rename)\s+/i.test(lower)) {
    return null;
  }

  const lastLines = raw.match(
    /\bshow\s+(the\s+)?(last|past)\s+(\d+)\s+lines\s+of\s+([^\s?!,]+)/i,
  );
  if (lastLines?.[4]) {
    const pathPart = trimPathFragment(lastLines[4]);
    if (!pathFragmentLooksConcrete(pathPart)) return null;
    const n = Number.parseInt(lastLines[3] ?? "", 10);
    const lineCount = Number.isFinite(n) && n > 0 ? n : undefined;
    return { kind: "tail", filePath: pathPart, lineCount };
  }

  const tailM = raw.match(/\btail\s+([^\s?!,]+)/i);
  if (tailM?.[1]) {
    const pathPart = trimPathFragment(tailM[1]);
    if (!pathFragmentLooksConcrete(pathPart)) return null;
    return { kind: "tail", filePath: pathPart };
  }

  const listFilesIn = raw.match(/\blist\s+(the\s+)?files?\s+in\s+([^\s?!,]+)/i);
  if (listFilesIn?.[2]) return parseListPathFragment(listFilesIn[2]);

  const listDir = raw.match(/\blist\s+(the\s+)?(directory|dir)\s+([^\s?!,]+)/i);
  if (listDir?.[3]) return parseListPathFragment(listDir[3]);

  const showFilesIn = raw.match(/\bshow\s+(the\s+)?files?\s+in\s+([^\s?!,]+)/i);
  if (showFilesIn?.[2]) return parseListPathFragment(showFilesIn[2]);

  const naturalList = raw.match(
    /\b(?:show\s+me\s+)?(?:what(?:'s|s|\s+is)\s+(?:in|inside)|what\s+(?:files|folders)\s+are\s+in)\s+(.+)$/i,
  );
  if (naturalList?.[1]) return parseListPathFragment(naturalList[1]);

  const showContents = raw.match(/\bshow\s+(the\s+)?contents\s+of\s+([^\s?!,]+)/i);
  if (showContents?.[2]) {
    const pathPart = trimPathFragment(showContents[2]);
    if (!pathFragmentLooksConcrete(pathPart)) return null;
    return { kind: "read", filePath: pathPart };
  }

  const readFile = raw.match(/\bread\s+([^\s?!,]+)/i);
  if (readFile?.[1] && !/^(files?|folders?|directories?)$/i.test(readFile[1])) {
    const pathPart = trimPathFragment(readFile[1]);
    if (!pathFragmentLooksConcrete(pathPart)) return null;
    return { kind: "read", filePath: pathPart };
  }

  const openFile = raw.match(/\bopen\s+([^\s?!,]+)/i);
  if (openFile?.[1]) {
    const pathPart = trimPathFragment(openFile[1]);
    if (!pathFragmentLooksConcrete(pathPart)) return null;
    return { kind: "read", filePath: pathPart };
  }

  return null;
}

function formatListSuccess(
  directory: string,
  r: Extract<Awaited<ReturnType<typeof listWorkspaceFiles>>, { ok: true }>,
): string {
  const header = `Files in ${directory}:`;
  const lines = r.entries.map((e) => {
    const suffix = e.type === "directory" ? "/" : "";
    return `- ${e.name}${suffix}`;
  });
  const trunc = r.truncated ? "\n\n(listing truncated to cap)" : "";
  return [header, ...lines].join("\n") + trunc;
}

function formatWindowsListSuccess(
  directory: string,
  r: Extract<Awaited<ReturnType<typeof listWindowsFiles>>, { ok: true }>,
): string {
  const header = `Files in ${r.path || directory}`;
  const lines = r.entries.map((e) => {
    const label = e.type === "directory" ? "[dir]" : "[file]";
    return `- ${label} ${e.name}`;
  });
  const trunc = r.truncated ? "\n\n(listing truncated to cap)" : "";
  return [header, ...lines].join("\n") + trunc;
}

function formatReadSuccess(
  labelPath: string,
  content: string,
  truncated: boolean,
): string {
  const lang = fenceLang(labelPath);
  const fence = "```" + lang + "\n" + content + "\n```";
  const trunc = truncated ? "\n\n(Output was truncated to the tool character cap.)" : "";
  return `Contents of ${labelPath}:\n${fence}${trunc}`;
}

function formatTailSuccess(
  filePath: string,
  lines: string[],
  requestedLines: number | undefined,
  truncated: boolean,
): string {
  const header =
    requestedLines != null
      ? `Last ${requestedLines} lines of ${filePath}:`
      : `Tail of ${filePath} (${lines.length} lines shown):`;
  const body = lines.join("\n");
  const fence = "```text\n" + body + "\n```";
  const trunc = truncated ? "\n\n(Output was truncated to the tool character cap.)" : "";
  return `${header}\n${fence}${trunc}`;
}

function formatToolError(message: string): string {
  return `I could not read that path: ${message}`;
}

function formatWindowsToolError(message: string): string {
  return message;
}

/**
 * Execute a parsed concrete read-only workspace operation and return assistant markdown,
 * or null when this text does not map to a direct request or local tools are disabled.
 */
export async function handleDirectWorkspaceRequest(
  text: string,
): Promise<DirectWorkspaceHandleResult | null> {
  const parsed = parseDirectWorkspaceRequest(text);
  if (!parsed) return null;

  if (parsed.kind === "list" && parsed.source === "windows") {
    const r = await listWindowsFiles({ path: parsed.directory });
    if (!r.ok) {
      return {
        markdown: formatWindowsToolError(r.message),
        toolActivity: [
          createSpiritToolActivityCard({
            kind: "windows_workspace_list",
            label: "List Windows files",
            status: "blocked",
            target: parsed.directory,
            safeMessage: r.message,
          }),
        ],
      };
    }
    return {
      markdown: formatWindowsListSuccess(parsed.directory, r),
      toolActivity: [
        createSpiritToolActivityCard({
          kind: "windows_workspace_list",
          label: "List Windows files",
          status: "completed",
          target: r.path,
          summary: `${r.entries.length} entr${r.entries.length === 1 ? "y" : "ies"}${r.truncated ? ", truncated" : ""}`,
        }),
      ],
    };
  }

  if (!isLocalToolsEnabled()) return null;

  if (parsed.kind === "list") {
    const r = await listWorkspaceFiles({ directory: parsed.directory });
    if (!r.ok) {
      return {
        markdown: formatToolError(r.message),
        toolActivity: [
          createSpiritToolActivityCard({
            kind: "tool_blocked",
            label: "List workspace files",
            status: "blocked",
            target: parsed.directory,
            safeMessage: r.message,
          }),
        ],
      };
    }
    return {
      markdown: formatListSuccess(parsed.directory, r),
      toolActivity: [
        createSpiritToolActivityCard({
          kind: "workspace_list",
          label: "List workspace files",
          status: "completed",
          target: parsed.directory,
          summary: `${r.entries.length} entr${r.entries.length === 1 ? "y" : "ies"}${r.truncated ? ", truncated" : ""}`,
        }),
      ],
    };
  }

  if (parsed.kind === "read") {
    const r = await readWorkspaceFile({ filePath: parsed.filePath });
    if (!r.ok) {
      return {
        markdown: formatToolError(r.message),
        toolActivity: [
          createSpiritToolActivityCard({
            kind: "tool_blocked",
            label: "Read workspace file",
            status: "blocked",
            target: parsed.filePath,
            safeMessage: r.message,
          }),
        ],
      };
    }
    const label = r.filePath;
    return {
      markdown: formatReadSuccess(label, r.content, r.truncated),
      toolActivity: [
        createSpiritToolActivityCard({
          kind: "workspace_read",
          label: "Read workspace file",
          status: "completed",
          target: label,
          summary: r.truncated ? "Content truncated in output" : "Read OK",
        }),
      ],
    };
  }

  const r = await readLogTail({
    filePath: parsed.filePath,
    lineCount: parsed.lineCount,
  });
  if (!r.ok) {
    return {
      markdown: formatToolError(r.message),
      toolActivity: [
        createSpiritToolActivityCard({
          kind: "tool_blocked",
          label: "Tail log file",
          status: "blocked",
          target: parsed.filePath,
          safeMessage: r.message,
        }),
      ],
    };
  }
  return {
    markdown: formatTailSuccess(r.filePath, r.lines, parsed.lineCount, r.truncated),
    toolActivity: [
      createSpiritToolActivityCard({
        kind: "workspace_tail",
        label: "Tail log file",
        status: "completed",
        target: r.filePath,
        summary: `${r.lines.length} lines${r.truncated ? ", truncated" : ""}`,
      }),
    ],
  };
}// ── workspace-tools - read-only listings and file reads for Hermes Phase 4 ──
// > fs/promises only. No shell. Paths go through tool-safety first.

import { promises as fs } from "fs";
import path from "path";

import {
  TOOL_MAX_FILE_BYTES,
  TOOL_MAX_OUTPUT_CHARS,
  SpiritToolPathError,
  isBlockedPathSegment,
  matchesBlockedFileBasename,
  normalizeWorkspaceRelativePath,
  resolveSafeWorkspacePath,
  truncateToolOutput,
} from "@/lib/spirit/tools/tool-safety";

const LIST_DEFAULT_MAX = 80;
const LIST_HARD_CAP = 200;
const LOG_TAIL_DEFAULT_LINES = 80;
const LOG_TAIL_MAX_LINES = 300;
/** Bytes read from disk when tailing logs (tail extraction only). */
const LOG_TAIL_READ_MAX_BYTES = 512 * 1024;

function isBlockedWorkspaceEntryName(name: string): boolean {
  if (name === "." || name === "..") return true;
  if (isBlockedPathSegment(name)) return true;
  if (matchesBlockedFileBasename(name)) return true;
  return false;
}

function assertUtf8TextBuffer(buf: Buffer): void {
  if (buf.includes(0)) {
    throw new SpiritToolPathError("NOT_TEXT_FILE", "Only UTF-8 text files are allowed.");
  }
}

export type ListWorkspaceFilesInput = {
  directory?: string;
  maxEntries?: number;
};

export async function listWorkspaceFiles(
  input: ListWorkspaceFilesInput,
): Promise<
  | {
      ok: true;
      directory: string;
      entries: Array<{
        name: string;
        type: "file" | "directory" | "symlink" | "other";
        size?: number;
        modifiedAt?: string;
      }>;
      truncated: boolean;
    }
  | { ok: false; code: string; message: string }
> {
  try {
    const dirRel = normalizeWorkspaceRelativePath(input.directory ?? ".");
    const dirAbs = resolveSafeWorkspacePath(dirRel);

    const stat = await fs.stat(dirAbs);
    if (!stat.isDirectory()) {
      return { ok: false, code: "NOT_A_DIRECTORY", message: "Path is not a directory." };
    }

    let maxEntries = input.maxEntries ?? LIST_DEFAULT_MAX;
    if (!Number.isFinite(maxEntries) || maxEntries < 1) {
      maxEntries = LIST_DEFAULT_MAX;
    }
    maxEntries = Math.min(Math.floor(maxEntries), LIST_HARD_CAP);

    const dirents = await fs.readdir(dirAbs, { withFileTypes: true });
    const safe: typeof dirents = [];
    for (const d of dirents) {
      if (isBlockedWorkspaceEntryName(d.name)) continue;
      const childRel = dirRel === "." ? d.name : `${dirRel}${path.sep}${d.name}`;
      try {
        resolveSafeWorkspacePath(childRel);
        safe.push(d);
      } catch {
        // Symlink escape or odd entry: skip rather than leak errors.
        continue;
      }
    }

    safe.sort((a, b) => a.name.localeCompare(b.name));
    const truncated = safe.length > maxEntries;
    const slice = safe.slice(0, maxEntries);

    const entries: Array<{
      name: string;
      type: "file" | "directory" | "symlink" | "other";
      size?: number;
      modifiedAt?: string;
    }> = [];

    for (const d of slice) {
      const childPath = path.join(dirAbs, d.name);
      let type: "file" | "directory" | "symlink" | "other" = "other";
      if (d.isDirectory()) type = "directory";
      else if (d.isFile()) type = "file";
      else if (d.isSymbolicLink()) type = "symlink";

      let size: number | undefined;
      let modifiedAt: string | undefined;
      try {
        const st = await fs.stat(childPath);
        size = st.size;
        modifiedAt = st.mtime.toISOString();
      } catch {
        /* optional metadata */
      }

      entries.push({ name: d.name, type, size, modifiedAt });
    }

    return {
      ok: true,
      directory: dirRel === "." ? "." : dirRel.split(path.sep).join("/"),
      entries,
      truncated,
    };
  } catch (e) {
    if (e instanceof SpiritToolPathError) {
      return { ok: false, code: e.code, message: e.message };
    }
    return { ok: false, code: "LIST_FAILED", message: "Could not list directory." };
  }
}

export type ReadWorkspaceFileInput = {
  filePath: string;
};

export async function readWorkspaceFile(
  input: ReadWorkspaceFileInput,
): Promise<
  | {
      ok: true;
      filePath: string;
      content: string;
      size: number;
      truncated: boolean;
    }
  | { ok: false; code: string; message: string }
> {
  try {
    const rel = normalizeWorkspaceRelativePath(input.filePath);
    const abs = resolveSafeWorkspacePath(rel);

    const stat = await fs.stat(abs);
    if (!stat.isFile()) {
      return { ok: false, code: "NOT_A_FILE", message: "Path is not a file." };
    }
    if (stat.size > TOOL_MAX_FILE_BYTES) {
      return {
        ok: false,
        code: "FILE_TOO_LARGE",
        message: `File exceeds maximum size of ${TOOL_MAX_FILE_BYTES} bytes.`,
      };
    }

    const buf = await fs.readFile(abs);
    assertUtf8TextBuffer(buf);
    const raw = buf.toString("utf8");
    const out = truncateToolOutput(raw, TOOL_MAX_OUTPUT_CHARS);

    return {
      ok: true,
      filePath: rel.split(path.sep).join("/"),
      content: out.text,
      size: stat.size,
      truncated: out.truncated,
    };
  } catch (e) {
    if (e instanceof SpiritToolPathError) {
      return { ok: false, code: e.code, message: e.message };
    }
    return { ok: false, code: "READ_FAILED", message: "Could not read file." };
  }
}

export type ReadLogTailInput = {
  filePath: string;
  lineCount?: number;
};

export async function readLogTail(
  input: ReadLogTailInput,
): Promise<
  | {
      ok: true;
      filePath: string;
      lines: string[];
      lineCount: number;
      truncated: boolean;
    }
  | { ok: false; code: string; message: string }
> {
  try {
    const rel = normalizeWorkspaceRelativePath(input.filePath);
    const abs = resolveSafeWorkspacePath(rel);

    const stat = await fs.stat(abs);
    if (!stat.isFile()) {
      return { ok: false, code: "NOT_A_FILE", message: "Path is not a file." };
    }

    let wantLines = input.lineCount ?? LOG_TAIL_DEFAULT_LINES;
    if (!Number.isFinite(wantLines) || wantLines < 1) {
      wantLines = LOG_TAIL_DEFAULT_LINES;
    }
    wantLines = Math.min(Math.floor(wantLines), LOG_TAIL_MAX_LINES);

    const buf =
      stat.size <= LOG_TAIL_READ_MAX_BYTES
        ? await fs.readFile(abs)
        : await (async () => {
            const fh = await fs.open(abs, "r");
            try {
              const readSize = Math.min(stat.size, LOG_TAIL_READ_MAX_BYTES);
              const pos = stat.size - readSize;
              const b = Buffer.alloc(readSize);
              await fh.read(b, 0, readSize, pos);
              return b;
            } finally {
              await fh.close();
            }
          })();

    assertUtf8TextBuffer(buf);
    const text = buf.toString("utf8");
    const rawLines = text.split(/\r?\n/);
    while (rawLines.length > 0 && rawLines[rawLines.length - 1] === "") {
      rawLines.pop();
    }
    const tailLines = rawLines.slice(-wantLines);
    const joined = tailLines.join("\n");
    const capped = truncateToolOutput(joined, TOOL_MAX_OUTPUT_CHARS);
    const outLines = capped.text.split("\n");

    return {
      ok: true,
      filePath: rel.split(path.sep).join("/"),
      lines: outLines,
      lineCount: outLines.length,
      truncated: capped.truncated || stat.size > LOG_TAIL_READ_MAX_BYTES,
    };
  } catch (e) {
    if (e instanceof SpiritToolPathError) {
      return { ok: false, code: e.code, message: e.message };
    }
    return { ok: false, code: "READ_FAILED", message: "Could not read log file." };
  }
}

const READ_ONLY_TOOL_NAMES = [
  "list_workspace_files",
  "read_workspace_file",
  "read_log_tail",
  "get_system_status",
] as const;

const WINDOWS_TOOL_NAMES = ["list_windows_files"] as const;

function isEnvTrue(name: string): boolean {
  return process.env[name] === "true";
}

export async function getSystemStatus(): Promise<{
  ok: true;
  localToolsEnabled: boolean;
  workspaceRootConfigured: boolean;
  workspaceRootSource: string;
  availableReadOnlyTools: string[];
  unavailableTools: string[];
  note: string;
}> {
  const localToolsEnabled = isEnvTrue("SPIRIT_ENABLE_LOCAL_TOOLS");
  const ollamaToolsTransport = isEnvTrue("SPIRIT_OLLAMA_SUPPORTS_TOOLS");
  const readOnlyToolsAttached = localToolsEnabled && ollamaToolsTransport;
  const workspaceRootConfigured = Boolean(process.env.SPIRIT_PROJECT_PATH?.trim());

  const unavailableTools: string[] = [];
  if (!isEnvTrue("SPIRIT_ENABLE_FILE_EDIT_TOOLS")) unavailableTools.push("file_editing");
  if (!isEnvTrue("SPIRIT_ENABLE_DEV_COMMAND_TOOLS")) unavailableTools.push("terminal_execution");
  if (!isEnvTrue("SPIRIT_ENABLE_EMAIL_TOOLS")) unavailableTools.push("email_access");
  if (!isEnvTrue("SPIRIT_ENABLE_CALENDAR_TOOLS")) unavailableTools.push("calendar_access");

  if (!readOnlyToolsAttached) {
    unavailableTools.push(...READ_ONLY_TOOL_NAMES);
  }
  if (isEnvTrue("SPIRIT_WINDOWS_FS_ENABLED") && readOnlyToolsAttached) {
    // Exposed through tool-registry only when the bridge env is explicitly enabled.
  } else {
    unavailableTools.push(...WINDOWS_TOOL_NAMES);
  }

  const availableReadOnlyTools = readOnlyToolsAttached
    ? [
        ...READ_ONLY_TOOL_NAMES,
        ...(isEnvTrue("SPIRIT_WINDOWS_FS_ENABLED") ? WINDOWS_TOOL_NAMES : []),
      ]
    : [];

  return {
    ok: true,
    localToolsEnabled,
    workspaceRootConfigured,
    workspaceRootSource: workspaceRootConfigured ? "SPIRIT_PROJECT_PATH" : "default_process_cwd",
    availableReadOnlyTools,
    unavailableTools: [...new Set(unavailableTools)].sort(),
    note:
      "Read-only workspace tools attach only when SPIRIT_ENABLE_LOCAL_TOOLS and SPIRIT_OLLAMA_SUPPORTS_TOOLS are true (Ollama must accept tools for your model). Workspace paths are workspace-relative only; Windows folder listing requires SPIRIT_WINDOWS_FS_ENABLED and an allowlisted bridge path.",
  };
}// ── Model profile ids - Prompt 7 runtime layer (no model id hardcoding) ─────────

export type ModelProfileId =
  | "normal-peer"
  | "researcher"
  | "teacher"
  | "brutal"
  | "sassy-chaotic";

export type ModelProfileBadgeTone = "neutral" | "cyan" | "amber" | "rose" | "violet";

export type ResponseBudget = "short" | "medium" | "report";

export type ModelProfile = {
  id: ModelProfileId;
  /** Longer chrome / docs label */
  label: string;
  /** Dropdown + compact UI */
  shortLabel: string;
  /** Badge line: Mode: X - one-liner hint */
  responseStyleSummary: string;
  description: string;
  systemPrompt: string;
  temperature: number;
  maxOutputTokens?: number;
  /** Prompt 10B - guides Hermes verbosity + budget helper */
  responseBudget?: ResponseBudget;
  casualMaxSentences?: number;
  ttsDefaultStrategy?: "summary" | "full-chunks";
  thinkingDefault?: boolean;
  /** Hint for Ollama / local providers - wire in Prompt 8+ when options API is stable. */
  numCtx?: number;
  searchEnabled?: boolean;
  /** Prompt 10B - Researcher wants search when it lands */
  searchPreferred?: boolean;
  requiresCitationStyle?: boolean;
  reportStyle?: boolean;
  learningMode?: boolean;
  directnessLevel?: 1 | 2 | 3 | 4 | 5;
  sassLevel?: 0 | 1 | 2 | 3 | 4 | 5;
  deepThinkDefault?: boolean;
  slowGenerationDefault?: boolean;
  badgeTone?: ModelProfileBadgeTone;
};

export const DEFAULT_MODEL_PROFILE_ID: ModelProfileId = "normal-peer";// ── research-plan - plan-first stub (Prompt 10C Stage 5) ─────────────────────────
// > Editable steps only - no background job queue until a later prompt eats PM2 alive.

export type ResearchPlanStepStatus = "pending" | "active" | "done" | "error";

export type ResearchPlanStep = {
  id: string;
  label: string;
  detail?: string;
  searchQuery?: string;
  status: ResearchPlanStepStatus;
};

export type ResearchPlan = {
  id: string;
  title: string;
  originalQuestion: string;
  createdAt: number;
  freshnessTarget?: string;
  sourcePreferences: string[];
  steps: ResearchPlanStep[];
};

function uid(): string {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  } catch {
    /* ignore */
  }
  return `rp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

const DEFAULT_STEP_LABELS = [
  "Clarify the research question.",
  "Search recent professional or academic sources.",
  "Review source quality.",
  "Compare findings and limitations.",
  "Draft answer.",
  "Provide citations and source list.",
] as const;

export function draftResearchPlanFromPrompt(question: string): ResearchPlan {
  const q = question.trim() || "Untitled research";
  const steps: ResearchPlanStep[] = DEFAULT_STEP_LABELS.map((label, i) => ({
    id: `step_${i + 1}`,
    label,
    status: "pending" as const,
  }));
  return {
    id: uid(),
    title: q.length > 72 ? `${q.slice(0, 69)}…` : q,
    originalQuestion: q,
    createdAt: Date.now(),
    freshnessTarget: "Prefer sources from the last ~5 years when relevant.",
    sourcePreferences: ["academic", "professional", "government", "primary sources", "credible news"],
    steps,
  };
}

export function editResearchPlanStep(
  plan: ResearchPlan,
  stepId: string,
  patch: Partial<Pick<ResearchPlanStep, "label" | "detail" | "searchQuery" | "status">>,
): ResearchPlan {
  return {
    ...plan,
    steps: plan.steps.map((s) => (s.id === stepId ? { ...s, ...patch } : s)),
  };
}

export function addResearchPlanStep(plan: ResearchPlan, label: string): ResearchPlan {
  const id = `step_${uid()}`;
  return {
    ...plan,
    steps: [...plan.steps, { id, label, status: "pending" }],
  };
}

export function removeResearchPlanStep(plan: ResearchPlan, stepId: string): ResearchPlan {
  return {
    ...plan,
    steps: plan.steps.filter((s) => s.id !== stepId),
  };
}

export function researchPlanToSummary(plan: ResearchPlan): string {
  const lines = plan.steps.map((s, i) => `${i + 1}. ${s.label}${s.detail ? ` - ${s.detail}` : ""}`);
  return `## User-approved research plan\nTitle: ${plan.title}\nQuestion: ${plan.originalQuestion}\nSteps:\n${lines.join("\n")}`;
}// ── research-source-enforcement - no fake citations when search lied or failed ─────
// > Hermes will still try; this module is policy text + a dumb safety net stripper.

import type { ModelProfileId } from "@/lib/spirit/model-profile.types";
import { isVerifiedHttpUrl } from "@/lib/verified-http-url";

export type SpiritSearchStatus =
  | "used"
  | "skipped"
  | "disabled"
  | "failed"
  | "none"
  | string;

export type ResearchSourcePolicyInput = {
  searchStatus: SpiritSearchStatus;
  /** URLs returned from web search (verified http(s)). */
  sources: Array<{ url?: string }>;
  /** User asked for fresh / recent external proof */
  requestedFreshSources?: boolean;
  /** Teacher needs links in Study aids, not buried only under ## Sources. */
  modelProfileId?: ModelProfileId;
};

function countVerifiedHttpUrls(sources: Array<{ url?: string }>): number {
  let n = 0;
  for (const s of sources) {
    if (isVerifiedHttpUrl(s.url)) n += 1;
  }
  return n;
}

export function hasUsableResearchSources(sources: Array<{ url?: string }>): boolean {
  return countVerifiedHttpUrls(sources) > 0;
}

/**
 * Extra system text appended to web-research context so Hermes stops cosplaying PubMed.
 */
export function buildResearchSourcePolicy(input: ResearchSourcePolicyInput): string {
  const urlCount = countVerifiedHttpUrls(input.sources);
  const searchUsed =
    input.searchStatus === "used" && urlCount > 0 ? "yes" : "no";
  const fresh = Boolean(input.requestedFreshSources);

  if (searchUsed === "yes") {
    if (input.modelProfileId === "teacher") {
      return [
        "## Source enforcement (mandatory)",
        "- Search used: yes",
        "- Verified URLs are in the web digest above.",
        '- **Study aids** must include a markdown bullet list: one line per verified URL, each exactly `- [Short label](https://...)` using only URLs from the digest (no invented links).',
        "- Optional: you may repeat the same links under **## Sources** - but Study aids must not be only generic search phrases when URLs exist.",
        `- Verified URL count: ${urlCount}`,
      ].join("\n");
    }
    return [
      "## Source enforcement (mandatory)",
      "- Search used: yes",
      "- You may use numbered citations **only** as [n](url) where url is one listed above.",
      "- End with **## Sources** using those same clickable URLs.",
      `- Verified URL count: ${urlCount}`,
    ].join("\n");
  }

  const lines = [
    "## Source enforcement (mandatory)",
    "- Search used: no",
    "- No verified external URLs were attached for this response.",
    "- State clearly that the answer is **unverified** general background.",
    "- Do **not** include numbered citations like [1], [2], [3].",
    "- Do **not** include **## Sources**, **## References**, or bibliography entries.",
    "- Do **not** invent article titles, journals, DOIs, or URLs from memory.",
  ];
  if (fresh) {
    lines.push(
      "- The user asked for time-bounded external proof: say you **cannot verify** that without attached URLs.",
    );
  } else {
    lines.push('- If you continue from training knowledge, label it **"Unverified background"** - not "Findings".');
  }
  return lines.join("\n");
}

const SOURCES_HEADING = /^#{1,6}\s*sources\s*$/im;
const REFS_HEADING = /^#{1,6}\s*references\s*$/im;

/** Strip [1]..[99] markers (standalone or before punctuation). */
function stripNumberedCitationMarkers(text: string): string {
  return text.replace(/\[\s*\d{1,2}\s*\](?=\s|[.,;:!?)\]]|$)/g, "");
}

function stripMarkdownSectionAfterHeading(text: string, headingLine: RegExp): string {
  const m = headingLine.exec(text);
  if (!m || m.index === undefined) return text;
  const start = m.index;
  const tail = text.slice(start + m[0].length);
  const rel = tail.search(/^\n#{1,6}\s+\S/m);
  const end = rel === -1 ? text.length : start + m[0].length + rel;
  return (text.slice(0, start) + text.slice(end)).replace(/\n{3,}/g, "\n\n").trim();
}

/**
 * Last-resort sanitizer when the model ignored policy - only safe when caller knows URLs were absent.
 */
export function stripFakeCitationsWhenNoSources(text: string): string {
  if (!text.trim()) return text;
  let t = text;
  t = stripMarkdownSectionAfterHeading(t, SOURCES_HEADING);
  t = stripMarkdownSectionAfterHeading(t, REFS_HEADING);
  t = stripNumberedCitationMarkers(t);
  return t.replace(/\n{3,}/g, "\n\n").trim();
}

export function userRequestedFreshExternalSources(text: string): boolean {
  const t = text.toLowerCase();
  return (
    /\b20(2[4-9]|3[0-9])\b/.test(t) &&
    /\b(source|study|studies|paper|peer|journal|doi|verify|evidence|literature)\b/i.test(t)
  );
}// ── spirit-answer-contract - hard output caps (Stage 3) ────────────────────────────
// > Appended in buildModelRuntime so Hermes can't "forget" mid-stream.

import type { ModelProfileId } from "@/lib/spirit/model-profile.types";

export function buildFinalAnswerContract(profileId: ModelProfileId, deepThinkEnabled: boolean): string {
  const deep =
    deepThinkEnabled &&
    `
## Deep Think modifier (user enabled)
- More verification and tighter structure - **still** respect the mode length caps below (no essay mode for Peer/Sassy/Brutal).
`.trim();

  const peer = `
## Final answer contract - Peer mode
- Not coding mode: **do not** mention coding/repo/tools unless the user did.
- Casual by default: **1–4 short sentences** for casual prompts.
- Mirror user energy lightly; witty, grounded, lightly sassy when appropriate.
- Do not over-explain. No customer-service tone.

### Banned phrases (do not use)
- "How may I assist you?"
- "I'm here to help with coding questions"
- "I'd rather not make anything up"
- "If you'd like to talk about something specific"
- "What coding project should we tackle?"
`.trim();

  const sassy = `
## Final answer contract - Sassy mode
- **Max 3 short sentences** by default unless the user asked for depth.
- Witty, sharp, playful - **no essays**, no numbered lists unless the user asked.
- No fake profound nonsense, no cringe theater energy.
- Answer the question, then **stop**.
`.trim();

  const brutal = `
## Final answer contract - Brutal mode
- **Max 2 short paragraphs** by default unless the user explicitly asked for a long teardown.
- One hard truth, one direct action. Funny-mean is OK; slight vulgarity is OK.
- Roast **behavior**, not identity. Do not ramble, do not go clinical, no long numbered breakdowns unless asked.
`.trim();

  const teacher = `
## Final answer contract - Teacher mode
- Simple explanation first, then one real-world example when useful.
- Add a **Study aids** footer when it helps (mnemonic / common trap / optional flashcard line).
- If no web search ran, **do not invent links** - give search phrases instead (e.g. YouTube search: "...").
- If web sources exist, include real links in Study aids.
`.trim();

  const researcher = `
## Final answer contract - Researcher mode
- Always state whether web search was used (yes/no) honestly.
- If search was used, include real sources with URLs when provided; if none, say: "No verified external sources were available for this response."
- Use headings in this order when substantive: **## Executive Summary** → **## Findings** → **## Limitations** → **## Sources**
- No fake citations. Prefer last ~5 years when the user asks for recency; if you cannot verify, say so explicitly (especially for 2024–2026 study requests with no sources).
- If the question is casual while in Researcher, stay disciplined and **do not bloat**.
`.trim();

  let block = "";
  switch (profileId) {
    case "normal-peer":
      block = peer;
      break;
    case "sassy-chaotic":
      block = sassy;
      break;
    case "brutal":
      block = brutal;
      break;
    case "teacher":
      block = teacher;
      break;
    case "researcher":
      block = researcher;
      break;
    default:
      block = peer;
  }

  if (deepThinkEnabled) {
    return `${block}\n\n${deep}`;
  }
  return block;
}// ── spirit-capability-context - short pointer for /api/spirit (client + server safe) ─
// > Live capability answers for intent-matched questions are assembled server-side in /api/spirit.
// > GET /api/telemetry/capabilities returns the full JSON for dashboards and curl.

/** Appended to mode system prompt so Spirit knows what it can query vs pretend. */
export const SPIRIT_CAPABILITY_CONTEXT_HINT = `## SpiritOS live capability registry (read-only)
SpiritOS has live cluster telemetry and read-only capability data on the server. For questions like **what you can do**, **what your capabilities are**, **what tools exist**, or **what you cannot do yet**, /api/spirit answers from that live registry when intent matches - use those facts instead of generic “I don’t have access” boilerplate.
Do not imply you lack visibility into the homelab when telemetry is available; say clearly what is **wired vs not wired** (app-level file browse, SSH from chat, desktop control are not tools yet).
SPIRIT_PROJECT_PATH in env only means paths are configured, not that files were inspected.`;// ── spirit-search-response-headers - parse /api/spirit proof headers (client-safe) ─
// > Server telemetry lives in spirit-search-telemetry (server-only); keep this import-free of that.

export type SpiritSearchStatusNormalized = "used" | "skipped" | "failed" | "disabled" | "none";

export type ParsedSpiritSearchHeaders = {
  routeLane: string | null;
  routeConfidence: string | null;
  webSearch: string | null;
  searchStatus: SpiritSearchStatusNormalized;
  searchProvider: string | null;
  sourceCount: number | null;
  searchQuery: string | null;
  searchElapsedMs: number | null;
  searchKind: "researcher" | "teacher" | "none";
  skipReason: string | null;
  webSourcesJson: string | null;
};

export function normalizeClientSearchStatus(raw: string | null | undefined): SpiritSearchStatusNormalized {
  const s = (raw ?? "none").trim().toLowerCase();
  if (s === "used") return "used";
  if (s === "failed") return "failed";
  if (s === "disabled") return "disabled";
  if (s === "skipped") return "skipped";
  return "none";
}

export function parseSpiritSearchHeaders(res: Response): ParsedSpiritSearchHeaders {
  const routeLane = res.headers.get("x-spirit-route-lane");
  const routeConfidence = res.headers.get("x-spirit-route-confidence");
  const webSearch = res.headers.get("x-spirit-web-search");
  const searchStatusRaw =
    res.headers.get("x-spirit-search-status") ?? res.headers.get("x-spirit-web-search");
  const searchProvider = res.headers.get("x-spirit-search-provider");
  const sc = res.headers.get("x-spirit-source-count");
  const sourceCount = sc != null && sc.trim() !== "" ? Number.parseInt(sc, 10) : null;
  const searchQuery = res.headers.get("x-spirit-search-query");
  const el = res.headers.get("x-spirit-search-elapsed-ms");
  const searchElapsedMs =
    el != null && el.trim() !== "" && Number.isFinite(Number(el)) ? Math.round(Number(el)) : null;
  const sk = res.headers.get("x-spirit-search-kind");
  const searchKind: "researcher" | "teacher" | "none" =
    sk === "researcher" || sk === "teacher" ? sk : "none";
  const skipReason = res.headers.get("x-spirit-search-skip-reason");
  const webSourcesJson = res.headers.get("x-spirit-web-sources");

  return {
    routeLane,
    routeConfidence,
    webSearch,
    searchStatus: normalizeClientSearchStatus(searchStatusRaw),
    searchProvider: searchProvider?.trim() || null,
    sourceCount: sourceCount != null && Number.isFinite(sourceCount) ? sourceCount : null,
    searchQuery: searchQuery?.trim() || null,
    searchElapsedMs,
    searchKind,
    skipReason: skipReason?.trim() || null,
    webSourcesJson,
  };
}// ── spirit-user-profile - local-only editable prefs (Prompt 10A, no server memory) ─
// > Full learning/RAG/sync are later prompts - this is transparent localStorage.

import type { ModelProfileId } from "@/lib/spirit/model-profile.types";

export const SPIRIT_USER_PROFILE_LS = "spirit:userProfile:v1";
export const PERSONALIZATION_SUMMARY_MAX_CLIENT = 1200;

export type SpiritUserPreferenceConfidence = "low" | "medium" | "high";
export type SpiritPreferenceCategory =
  | "communication"
  | "workflow"
  | "research"
  | "mode"
  | "ui"
  | "other";

export type SpiritResearchSettingsV1 = {
  webSearchDefaultResearcher: boolean;
  preferredSourceAge: "5y" | "any";
  preferredSourceTypes: string[];
  requireCitationsResearcher: boolean;
  includeFullSourceList: boolean;
  warnOnSearchFailure: boolean;
  planFirstDeepResearchLater: boolean;
};

export function defaultResearchSettings(): SpiritResearchSettingsV1 {
  return {
    webSearchDefaultResearcher: true,
    preferredSourceAge: "5y",
    preferredSourceTypes: [
      "academic",
      "professional",
      "government",
      "primary sources",
      "credible news",
    ],
    requireCitationsResearcher: true,
    includeFullSourceList: true,
    warnOnSearchFailure: true,
    planFirstDeepResearchLater: false,
  };
}

export type SpiritUserPreferenceSource = "manual" | "inferred" | "default";

export type SpiritUserPreferenceRow = {
  id: string;
  label: string;
  value: string;
  source?: SpiritUserPreferenceSource;
  wrongPerspective?: boolean;
  confidence?: SpiritUserPreferenceConfidence;
  category?: SpiritPreferenceCategory;
};

export type SpiritUserProfileV1 = {
  version: 1;
  /** When false, client skips personalizationSummary on /api/spirit */
  sendPersonalizationToServer: boolean;
  preferences: SpiritUserPreferenceRow[];
  researchSettings?: SpiritResearchSettingsV1;
};

function uid(): string {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  } catch {
    /* ignore */
  }
  return `pref_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
}

export const DEFAULT_SPIRIT_USER_PREFERENCES: SpiritUserPreferenceRow[] = [
  {
    id: "tone",
    label: "Communication style",
    value: "Casual, conversational; no customer-service glaze.",
    source: "default",
  },
  {
    id: "length",
    label: "Response length preference",
    value: "Concise by default; expand only when I ask for depth or a report.",
    source: "default",
  },
  {
    id: "writing",
    label: "Writing / formatting",
    value: "Avoid em dashes; prefer hyphen or comma.",
    source: "default",
  },
  {
    id: "workflow",
    label: "Work style",
    value: "Practical plans, senior-dev analysis, mobile-first with desktop still testable.",
    source: "default",
  },
  {
    id: "priorities",
    label: "Current build priorities",
    value: "Transparent status signals; local AI / homelab workflows; AI-native coding.",
    source: "default",
  },
  {
    id: "interests",
    label: "Interests / recurring themes",
    value: "ARPA-style planning before big Cursor dumps; SpiritOS chat workspace polish.",
    source: "default",
  },
  {
    id: "dislikes",
    label: "Frustration triggers / dislikes",
    value: "Bland support-agent replies; overlong casual answers; hidden chain-of-thought cosplay.",
    source: "default",
  },
  {
    id: "research",
    label: "Research expectations",
    value: "Clinical / psychedelic topics handled professionally; citations required in Researcher mode.",
    source: "default",
  },
  {
    id: "confidence",
    label: "Confidence level (self-reported)",
    value: "Medium - prefers receipts and sources for factual claims.",
    source: "default",
  },
];

export function defaultSpiritUserProfile(): SpiritUserProfileV1 {
  return {
    version: 1,
    sendPersonalizationToServer: true,
    preferences: DEFAULT_SPIRIT_USER_PREFERENCES.map((p) => ({ ...p, id: p.id || uid() })),
    researchSettings: defaultResearchSettings(),
  };
}

export function loadSpiritUserProfile(): SpiritUserProfileV1 {
  if (typeof window === "undefined") return defaultSpiritUserProfile();
  try {
    const raw = window.localStorage.getItem(SPIRIT_USER_PROFILE_LS);
    if (!raw) return defaultSpiritUserProfile();
    const parsed = JSON.parse(raw) as Partial<SpiritUserProfileV1>;
    if (parsed?.version !== 1 || !Array.isArray(parsed.preferences)) {
      return defaultSpiritUserProfile();
    }
    const prefs: SpiritUserPreferenceRow[] = [];
    for (const row of parsed.preferences) {
      if (!row || typeof row !== "object") continue;
      const r = row as Record<string, unknown>;
      const label = typeof r.label === "string" ? r.label.trim() : "";
      const value = typeof r.value === "string" ? r.value.trim() : "";
      const id = typeof r.id === "string" && r.id.trim() ? r.id.trim() : uid();
      if (!label || !value) continue;
      const srcRaw = typeof r.source === "string" ? r.source.trim().toLowerCase() : "";
      const source: SpiritUserPreferenceSource =
        srcRaw === "manual" || srcRaw === "inferred" || srcRaw === "default" ? srcRaw : "default";
      const wrongPerspective = r.wrongPerspective === true;
      const rowOut: SpiritUserPreferenceRow = { id, label, value, source };
      if (wrongPerspective) rowOut.wrongPerspective = true;
      const confRaw = typeof r.confidence === "string" ? r.confidence.trim().toLowerCase() : "";
      if (confRaw === "low" || confRaw === "medium" || confRaw === "high") {
        rowOut.confidence = confRaw;
      }
      const catRaw = typeof r.category === "string" ? r.category.trim().toLowerCase() : "";
      const cats: SpiritPreferenceCategory[] = [
        "communication",
        "workflow",
        "research",
        "mode",
        "ui",
        "other",
      ];
      if (cats.includes(catRaw as SpiritPreferenceCategory)) {
        rowOut.category = catRaw as SpiritPreferenceCategory;
      }
      prefs.push(rowOut);
    }
    const rsIn = parsed.researchSettings;
    let researchSettings: SpiritResearchSettingsV1 = defaultResearchSettings();
    if (rsIn && typeof rsIn === "object") {
      const rs = rsIn as Record<string, unknown>;
      const base = defaultResearchSettings();
      researchSettings = {
        ...base,
        webSearchDefaultResearcher:
          rs.webSearchDefaultResearcher === false ? false : base.webSearchDefaultResearcher,
        preferredSourceAge: rs.preferredSourceAge === "any" ? "any" : base.preferredSourceAge,
        preferredSourceTypes: Array.isArray(rs.preferredSourceTypes)
          ? (rs.preferredSourceTypes as unknown[]).filter((x) => typeof x === "string") as string[]
          : base.preferredSourceTypes,
        requireCitationsResearcher: rs.requireCitationsResearcher === false ? false : true,
        includeFullSourceList: rs.includeFullSourceList === false ? false : true,
        warnOnSearchFailure: rs.warnOnSearchFailure === false ? false : true,
        planFirstDeepResearchLater: rs.planFirstDeepResearchLater === true,
      };
    }
    return {
      version: 1,
      sendPersonalizationToServer: parsed.sendPersonalizationToServer !== false,
      preferences: prefs.length ? prefs : defaultSpiritUserProfile().preferences,
      researchSettings,
    };
  } catch {
    return defaultSpiritUserProfile();
  }
}

export function saveSpiritUserProfile(profile: SpiritUserProfileV1): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(SPIRIT_USER_PROFILE_LS, JSON.stringify(profile));
  } catch {
    /* quota / private mode */
  }
}

/** Compact bullet list for system prompt injection (server-truncated separately). */
export function buildPersonalizationSummary(profile: SpiritUserProfileV1): string {
  if (!profile.sendPersonalizationToServer) return "";
  const lines = profile.preferences
    .filter((p) => !p.wrongPerspective)
    .map((p) => {
      const src = p.source ?? "default";
      return `- ${p.label} (${src}): ${p.value}`.trim();
    })
    .filter(Boolean);
  const body = lines.join("\n");
  if (!body) return "";
  if (body.length <= PERSONALIZATION_SUMMARY_MAX_CLIENT) return body;
  return `${body.slice(0, PERSONALIZATION_SUMMARY_MAX_CLIENT - 1)}…`;
}

/** Mode-aware slice appended for /api/spirit (Researcher gets research settings block). */
export function buildModeAwarePersonalizationSummary(
  profile: SpiritUserProfileV1,
  mode: ModelProfileId,
): string {
  let out = buildPersonalizationSummary(profile);
  const rs = profile.researchSettings ?? defaultResearchSettings();
  if (mode === "researcher") {
    const block = [
      "---",
      "Research settings (local):",
      `- Web search default (Researcher): ${rs.webSearchDefaultResearcher ? "ON" : "OFF"}`,
      `- Preferred source age: ${rs.preferredSourceAge}`,
      `- Preferred source types: ${rs.preferredSourceTypes.join(", ")}`,
      `- Require citations in Researcher: ${rs.requireCitationsResearcher ? "yes" : "no"}`,
      `- Include full source list: ${rs.includeFullSourceList ? "yes" : "no"}`,
      `- Warn when search fails: ${rs.warnOnSearchFailure ? "yes" : "no"}`,
      `- Plan-first deep research: ${rs.planFirstDeepResearchLater ? "stub on" : "later"}`,
    ].join("\n");
    out = out ? `${out}\n${block}` : block;
  }
  const trimmed = out.trim();
  if (!trimmed) return "";
  if (trimmed.length <= PERSONALIZATION_SUMMARY_MAX_CLIENT) return trimmed;
  return `${trimmed.slice(0, PERSONALIZATION_SUMMARY_MAX_CLIENT - 1)}…`;
}// ── spirit-web-sources - parse `x-spirit-web-sources` from /api/spirit (client-safe) ─
// > No fake citations: only render what the server actually returned.

import { isVerifiedHttpUrl } from "@/lib/verified-http-url";

export type SpiritWebSourcesHeaderPayload = {
  provider: string;
  count: number;
  sources: Array<{ title: string; url: string; snippet?: string }>;
};

export function parseSpiritWebSourcesHeader(
  raw: string | null,
): SpiritWebSourcesHeaderPayload | null {
  if (!raw?.trim()) return null;
  try {
    const o = JSON.parse(raw) as unknown;
    if (!o || typeof o !== "object") return null;
    const r = o as Record<string, unknown>;
    const provider = typeof r.provider === "string" ? r.provider : "unknown";
    const count = typeof r.count === "number" && Number.isFinite(r.count) ? r.count : 0;
    const srcRaw = r.sources;
    const sources: SpiritWebSourcesHeaderPayload["sources"] = [];
    if (Array.isArray(srcRaw)) {
      for (const x of srcRaw) {
        if (!x || typeof x !== "object") continue;
        const s = x as Record<string, unknown>;
        const title = typeof s.title === "string" ? s.title : "";
        const url = typeof s.url === "string" ? s.url.trim() : "";
        const snippet = typeof s.snippet === "string" ? s.snippet.trim() : undefined;
        if (url && !isVerifiedHttpUrl(url)) continue;
        if (!title.trim() && !url.trim()) continue;
        sources.push({
          title: title.trim(),
          url: url.trim(),
          ...(snippet ? { snippet: snippet.slice(0, 400) } : {}),
        });
        if (sources.length >= 12) break;
      }
    }
    return { provider, count, sources };
  } catch {
    return null;
  }
}// ── formatTtsLatency - “last voice” copy + start-first summary (Prompt 9L) ────────
import type { TtsLatency } from "@/lib/tts/audio-queue";

function formatMs(ms: number | undefined): string {
  if (ms == null || !Number.isFinite(ms)) return " - ";
  if (ms >= 1000) return `${(ms / 1000).toFixed(1)}s`;
  return `${Math.round(ms)}ms`;
}

/** User-facing seconds (710ms → 0.7s; 5700ms → 5.7s). */
export function formatSecondsOneDecimal(ms: number | undefined): string {
  if (ms == null || !Number.isFinite(ms)) return " - ";
  return `${(ms / 1000).toFixed(1)}s`;
}

function providerLabel(p?: string): string {
  if (!p || p === " - ") return " - ";
  if (p === "elevenlabs") return "ElevenLabs";
  if (p === "piper") return "Piper";
  return p;
}

function playbackLabel(m?: TtsLatency["playbackMode"]): string {
  if (m === "html-audio") return "HTMLAudioElement";
  if (m === "audio-context") return "AudioContext";
  return " - ";
}

/** User-facing playback line (Voice card friendly block). */
function playbackFriendly(m?: TtsLatency["playbackMode"]): string {
  if (m === "html-audio") return "HTMLAudio (browser)";
  if (m === "audio-context") return "WebAudio (browser)";
  return "Browser audio";
}

function shortVoiceId(id: string): string {
  const t = id.trim();
  if (t.length <= 14) return t;
  return `${t.slice(0, 6)}…${t.slice(-4)}`;
}

/** Best-effort ms from first /api/tts request until playback starts. */
function resolveTimeToFirstAudioMs(lat: TtsLatency): number | undefined {
  if (typeof lat.timeToFirstAudioMs === "number" && Number.isFinite(lat.timeToFirstAudioMs)) {
    return lat.timeToFirstAudioMs;
  }
  const fetch = typeof lat.fetchMs === "number" && Number.isFinite(lat.fetchMs) ? lat.fetchMs : 0;
  const dec =
    typeof lat.decodeMs === "number" && Number.isFinite(lat.decodeMs) ? lat.decodeMs : 0;
  if (fetch > 0 || dec > 0) return fetch + dec;
  return undefined;
}

/**
 * Primary “audio started” line for the Voice card (Prompt 9L).
 * Under 1s uses “under 1 second” when ms ∈ [500, 1000); else one-decimal seconds.
 */
export function formatTtsFriendlyStartSummary(lat: TtsLatency | undefined): string {
  if (!lat) return "Audio has not been tested yet";
  const ms = resolveTimeToFirstAudioMs(lat);
  if (ms != null && Number.isFinite(ms) && ms >= 0) {
    if (ms < 500) {
      return ms < 100
        ? `Audio started in ${Math.round(ms)}ms`
        : `Audio started in ${formatSecondsOneDecimal(ms)}`;
    }
    if (ms < 1000) return "Audio started in under 1 second";
    return `Audio started in ${formatSecondsOneDecimal(ms)}`;
  }
  if (lat.fetchMs == null && lat.totalMs == null && !lat.provider) {
    return "Audio has not been tested yet";
  }
  return "Audio has not been tested yet";
}

/** Single readable line for Voice settings header (not buried in debug). */
export function formatTtsLastVoiceLine(lat: TtsLatency | undefined): string {
  if (!lat || (lat.fetchMs == null && lat.totalMs == null && !lat.provider)) {
    return "Last voice: Not tested yet";
  }
  const pb = playbackLabel(lat.playbackMode);
  const voiceLabel =
    typeof lat.voiceName === "string" && lat.voiceName.trim()
      ? lat.voiceName.trim()
      : typeof lat.voiceId === "string" && lat.voiceId.trim()
        ? shortVoiceId(lat.voiceId.trim())
        : null;
  const ttfa =
    typeof lat.timeToFirstAudioMs === "number" && Number.isFinite(lat.timeToFirstAudioMs)
      ? `time-to-audio ${formatMs(lat.timeToFirstAudioMs)}`
      : null;
  const spoken =
    typeof lat.spokenSummaryLine === "string" && lat.spokenSummaryLine.trim()
      ? lat.spokenSummaryLine.trim()
      : null;
  const parts = [
    `Last voice: ${providerLabel(lat.provider)}`,
    voiceLabel,
    typeof lat.speed === "number" && Number.isFinite(lat.speed)
      ? `speed ${lat.speed.toFixed(2)}x`
      : null,
    typeof lat.upstreamMs === "number" ? `upstream ${formatMs(lat.upstreamMs)}` : null,
    lat.fetchMs != null ? `fetch ${formatMs(lat.fetchMs)}` : null,
    lat.decodeMs != null ? `decode ${formatMs(lat.decodeMs)}` : null,
    ttfa,
    lat.totalMs != null ? `playback span ${formatMs(lat.totalMs)}` : null,
    typeof lat.startDelayMs === "number" && lat.startDelayMs > 0
      ? `start delay ${lat.startDelayMs}ms`
      : null,
    pb !== " - " ? pb : null,
    spoken,
  ].filter(Boolean);
  return parts.join(" · ");
}

/** Maps raw / internal errors to short UI labels (no console cosplay). */
export function formatTtsErrorLabel(raw: string | undefined): string | undefined {
  if (!raw?.trim()) return undefined;
  const t = raw.trim();
  if (/enable audio/i.test(t) || /notallowed/i.test(t) || /audio blocked/i.test(t)) {
    return "Audio blocked. Tap Enable audio.";
  }
  if (/aborted/i.test(t)) return "aborted";
  if (/fetch|api\/tts|network/i.test(t)) return "provider unavailable";
  return t.length > 120 ? `${t.slice(0, 117)}…` : t;
}

export type VoiceActivityLineInput = {
  lastLatency?: TtsLatency;
  lastError?: string;
  lastVoiceNote?: "interrupted";
};

/**
 * Plain-language lines for the Voice card “Last session” block (Prompt 9L).
 * Total playback / raw ms live under Debug voice timing.
 */
export function formatTtsFriendlySummaryLines(i: VoiceActivityLineInput): string[] {
  const err = formatTtsErrorLabel(i.lastError);
  if (err) {
    return [`Last voice failed: ${err}`];
  }
  if (i.lastVoiceNote === "interrupted" && !i.lastLatency) {
    return ["Last voice was interrupted"];
  }
  const lat = i.lastLatency;
  if (!lat || (lat.fetchMs == null && lat.totalMs == null && !lat.provider)) {
    return ["Audio has not been tested yet"];
  }

  const voiceLabel =
    typeof lat.voiceName === "string" && lat.voiceName.trim()
      ? lat.voiceName.trim()
      : typeof lat.voiceId === "string" && lat.voiceId.trim()
        ? shortVoiceId(lat.voiceId.trim())
        : " - ";

  const primary = formatTtsFriendlyStartSummary(lat);

  const responseMs =
    typeof lat.upstreamMs === "number" && Number.isFinite(lat.upstreamMs)
      ? lat.upstreamMs
      : typeof lat.fetchMs === "number" && Number.isFinite(lat.fetchMs)
        ? lat.fetchMs
        : undefined;

  const prov = providerLabel(lat.provider);
  const responseLine =
    responseMs != null
      ? `${prov} responded in ${formatSecondsOneDecimal(responseMs)}`
      : `${prov} responded in  - `;

  return [
    primary,
    responseLine,
    `Browser playback: ${playbackFriendly(lat.playbackMode)}`,
    `Voice: ${voiceLabel}`,
  ];
}

/**
 * One primary line for the voice card: error > latency metrics > interrupt-only hint.
 * Interrupted does not clobber an existing successful latency line (no junk suffix).
 */
export function formatVoiceActivityPrimaryLine(i: VoiceActivityLineInput): string {
  const err = formatTtsErrorLabel(i.lastError);
  if (err) return `Last voice error: ${err}`;
  if (i.lastLatency) return formatTtsLastVoiceLine(i.lastLatency);
  if (i.lastVoiceNote === "interrupted") return "Last voice: interrupted";
  return formatTtsLastVoiceLine(i.lastLatency);
}

/** Compact formatter for tests / logs. */
export function formatTtsLatency(lat: TtsLatency): string {
  return formatTtsLastVoiceLine(lat);
}// ── safe-tts-headers - ASCII-only TTS response headers (Prompt 9K ByteString crash) ─
// > Next/Headers reject Unicode in ByteString fields - en dash in voice names nuked Tailscale.

export const HEADER_TTS_VOICE_NAME_ENCODED = "X-Spirit-TTS-Voice-Name-Encoded";

/** Percent-encode for header transport; result is ASCII. */
export function encodeTtsVoiceNameForHeader(name: string): string {
  return encodeURIComponent(name.trim());
}

/** Decode header value; returns null on garbage. */
export function decodeTtsVoiceNameFromHeader(encoded: string | null | undefined): string | null {
  if (encoded == null) return null;
  const t = encoded.trim();
  if (!t) return null;
  try {
    const out = decodeURIComponent(t);
    return out.trim() || null;
  } catch {
    return null;
  }
}// ── tts-http - /api/tts JSON helpers (Prompt 9H) ─────────────────────────────────

export type ParsedTtsSpeed =
  | { ok: true; value: number | undefined }
  | { ok: false; message: string };

/**
 * Optional `speed` on POST body: absent/null → undefined (use env).
 * Present but non-finite number → 400 via `{ ok: false }`.
 */
export function parseOptionalTtsSpeedField(body: Record<string, unknown>): ParsedTtsSpeed {
  if (!Object.prototype.hasOwnProperty.call(body, "speed")) {
    return { ok: true, value: undefined };
  }
  const v = body.speed;
  if (v === undefined || v === null) return { ok: true, value: undefined };
  if (typeof v !== "number" || !Number.isFinite(v)) {
    return { ok: false, message: "speed must be a finite number" };
  }
  return { ok: true, value: v };
}

export type ParsedTtsVoiceId =
  | { ok: true; value: string | undefined }
  | { ok: false; message: string };

const MAX_VOICE_ID_LEN = 80;

/**
 * Optional `voiceId` on POST body: absent → undefined (use server default chain).
 * Non-string or absurd length → 400.
 */
export function parseOptionalTtsVoiceIdField(body: Record<string, unknown>): ParsedTtsVoiceId {
  if (!Object.prototype.hasOwnProperty.call(body, "voiceId")) {
    return { ok: true, value: undefined };
  }
  const v = body.voiceId;
  if (v === undefined || v === null) return { ok: true, value: undefined };
  if (typeof v !== "string") {
    return { ok: false, message: "voiceId must be a string" };
  }
  const t = v.trim();
  if (!t) return { ok: true, value: undefined };
  if (t.length > MAX_VOICE_ID_LEN) {
    return { ok: false, message: `voiceId exceeds ${MAX_VOICE_ID_LEN} characters` };
  }
  return { ok: true, value: t };
}

export type ParsedTtsVoiceName =
  | { ok: true; value: string | undefined }
  | { ok: false; message: string };

const MAX_VOICE_NAME_LEN = 120;

/**
 * Optional `voiceName` - UI label only; never selects the ElevenLabs endpoint (use `voiceId`).
 */
export function parseOptionalTtsVoiceNameField(body: Record<string, unknown>): ParsedTtsVoiceName {
  if (!Object.prototype.hasOwnProperty.call(body, "voiceName")) {
    return { ok: true, value: undefined };
  }
  const v = body.voiceName;
  if (v === undefined || v === null) return { ok: true, value: undefined };
  if (typeof v !== "string") {
    return { ok: false, message: "voiceName must be a string" };
  }
  const t = v.trim();
  if (!t) return { ok: true, value: undefined };
  if (t.length > MAX_VOICE_NAME_LEN) {
    return { ok: false, message: `voiceName exceeds ${MAX_VOICE_NAME_LEN} characters` };
  }
  return { ok: true, value: t };
}// ── tts-parser - pause markers + light markdown strip for speech (Prompt 9) ────

export type TtsSegment =
  | { type: "speech"; text: string }
  | { type: "pause"; ms: number };

function parsePauseMs(raw: string): number | null {
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0) return null;
  return Math.min(Math.round(n), 60_000);
}

/** Strip markdown-ish noise; keep readable words. */
export function stripTextForTts(input: string): string {
  let s = input;
  s = s.replace(/```[\s\S]*?```/g, " code block omitted. ");
  s = s.replace(/`([^`]+)`/g, "$1");
  s = s.replace(/\[([^\]]+)\]\([^)]+\)/g, "$1");
  s = s.replace(/^#{1,6}\s+/gm, "");
  s = s.replace(/^\s*[-*+]\s+/gm, "");
  s = s.replace(/^\s*\d+\.\s+/gm, "");
  s = s.replace(/\*\*([^*]+)\*\*/g, "$1");
  s = s.replace(/\*([^*]+)\*/g, "$1");
  s = s.replace(/__([^_]+)__/g, "$1");
  s = s.replace(/_([^_]+)_/g, "$1");
  return s.replace(/\s+/g, " ").trim();
}

/**
 * Replace pause markers with internal tokens, then split into segments.
 * Supports: [pause:500], [pause:1s], [[pause 500ms]]
 */
export function parseTtsSegments(raw: string): TtsSegment[] {
  let s = raw.replace(/\r\n/g, "\n");

  s = s.replace(
    /\[\[\s*pause\s+(\d+)\s*ms\s*\]\]/gi,
    (_m, ms: string) => `\u0000PAUSE:${parsePauseMs(ms) ?? 0}\u0000`,
  );
  s = s.replace(/\[pause:\s*(\d+)\s*\]/gi, (_m, ms: string) => {
    const v = parsePauseMs(ms) ?? 0;
    return `\u0000PAUSE:${v}\u0000`;
  });
  s = s.replace(/\[pause:\s*([\d.]+)\s*s\]/gi, (_m, sec: string) => {
    const n = Number(sec);
    const ms = Number.isFinite(n)
      ? (parsePauseMs(String(Math.round(n * 1000))) ?? 0)
      : 0;
    return `\u0000PAUSE:${ms}\u0000`;
  });

  const pieces = s.split(/\u0000PAUSE:(\d+)\u0000/);
  const out: TtsSegment[] = [];
  for (let i = 0; i < pieces.length; i++) {
    const piece = pieces[i]!;
    if (i % 2 === 0) {
      const t = stripTextForTts(piece);
      if (t) out.push({ type: "speech", text: t });
    } else {
      const ms = Number(piece);
      if (Number.isFinite(ms) && ms > 0) out.push({ type: "pause", ms });
    }
  }

  if (out.length === 0) {
    const t = stripTextForTts(s.replace(/\u0000PAUSE:\d+\u0000/g, " "));
    if (t) return [{ type: "speech", text: t }];
  }
  return out;
}// ── tts-text-budget - keep /api/tts under 800 chars (Prompt 10B) ───────────────────

export const TTS_TEXT_LIMIT = 800;
export const TTS_SUMMARY_TRIGGER_CHARS = 700;
export const TTS_FULL_CHUNK_SIZE = 650;

/** Strip markdown-ish noise for spoken summaries (no LLM round-trip). */
export function stripMarkdownishForTts(raw: string): string {
  let s = raw.replace(/\r\n/g, "\n");
  s = s.replace(/```[\s\S]*?```/g, " ");
  s = s.replace(/`([^`]+)`/g, "$1");
  s = s.replace(/\[([^\]]+)\]\([^)]+\)/g, "$1");
  s = s.replace(/[#>*_\-~]/g, "");
  s = s.replace(/\s+/g, " ").trim();
  return s;
}

function firstSentences(text: string, maxCount: number): string[] {
  const t = text.trim();
  if (!t) return [];
  const rough = t.split(/(?<=[.!?])\s+/).filter(Boolean);
  if (rough.length <= maxCount) return rough;
  return rough.slice(0, maxCount);
}

/**
 * First 1–3 sentences up to ~500 chars, then hard cap at `maxLen`.
 * Prefix optional “Quick summary: ” stays inside maxLen.
 */
export function summarizeTextForTts(
  raw: string,
  opts?: { maxLen?: number; prefix?: string },
): string {
  const maxLen = Math.min(opts?.maxLen ?? 500, TTS_TEXT_LIMIT - 48);
  const prefix = opts?.prefix ?? "Quick summary: ";
  const flat = stripMarkdownishForTts(raw);
  if (!flat) return prefix.trim().slice(0, TTS_TEXT_LIMIT);

  let body = firstSentences(flat, 3).join(" ");
  if (body.length > maxLen) {
    body = `${body.slice(0, Math.max(0, maxLen - 1)).trim()}…`;
  }

  let out = `${prefix}${body}`.trim();
  if (out.length > TTS_TEXT_LIMIT) {
    out = `${out.slice(0, TTS_TEXT_LIMIT - 1).trim()}…`;
  }
  return out;
}

/** Split into speech-safe chunks; none exceed `TTS_TEXT_LIMIT`. */
export function splitTextIntoTtsChunks(
  raw: string,
  chunkSize: number = TTS_FULL_CHUNK_SIZE,
): string[] {
  const flat = stripMarkdownishForTts(raw);
  if (!flat) return [];
  const cap = Math.min(chunkSize, TTS_TEXT_LIMIT);
  const out: string[] = [];
  let rest = flat;

  while (rest.length > 0) {
    if (rest.length <= cap) {
      out.push(rest);
      break;
    }
    let cut = rest.lastIndexOf(" ", cap);
    if (cut < cap * 0.5) cut = cap;
    const piece = rest.slice(0, cut).trim();
    if (!piece) {
      out.push(rest.slice(0, cap).trim());
      rest = rest.slice(cap).trim();
      continue;
    }
    out.push(piece);
    rest = rest.slice(cut).trim();
  }

  return out
    .filter(Boolean)
    .map((c) => (c.length > TTS_TEXT_LIMIT ? c.slice(0, TTS_TEXT_LIMIT) : c))
    .filter((c) => c.length > 0);
}

export function pickTtsSpeakPayload(
  fullText: string,
  mode: "summary" | "full-chunks",
): { segments: string[]; spokenSummaryLine: string } {
  const t = fullText.trim();
  if (!t) return { segments: [], spokenSummaryLine: "Spoken: (empty)" };
  if (t.length <= TTS_TEXT_LIMIT) {
    return { segments: [t], spokenSummaryLine: "Spoken: full message" };
  }
  if (mode === "summary") {
    const s = summarizeTextForTts(t);
    return { segments: [s], spokenSummaryLine: "Spoken: summary (message was long)" };
  }
  const chunks = splitTextIntoTtsChunks(t);
  const n = chunks.length;
  return {
    segments: chunks,
    spokenSummaryLine: `Spoken: full response in ${n} chunk${n === 1 ? "" : "s"}`,
  };
}// ── voice-speed - shared clamp for client + server TTS (Prompt 9H) ───────────────

export const TTS_SPEED_MIN = 0.7;
export const TTS_SPEED_MAX = 1.2;
export const TTS_SPEED_DEFAULT = 1.12;

export function clampTtsVoiceSpeed(n: number): number {
  return Math.min(TTS_SPEED_MAX, Math.max(TTS_SPEED_MIN, n));
}

/** UI / localStorage presets (must stay inside clamp range). */
export const TTS_VOICE_SPEED_PRESETS = [1.0, 1.08, 1.12, 1.18] as const;// ── Shared inline paint for loading / error / client fail-safe ────────────────
