  /** Trimmed first-pass assistant reply (≤500 chars). */
  assistantText?: string;
  /** Profile active during this exchange. */
  modelProfileId?: string;
  /** Where this row was captured (Dexie is local; this disambiguates future writers). */
  source?: string;
  /** Runtime surface active when the exchange was logged (matches /api/spirit body). */
  runtimeSurface?: SpiritRuntimeSurface;
};// ── chat-folder-utils - pure sidebar grouping + order-aware sorts (Prompt 6) ───
import type { ChatFolder, ChatThread } from "@/lib/chat-db.types";

export type FolderSidebarSection = {
  folder: ChatFolder;
  threads: ChatThread[];
};

export type FolderSidebarModel = {
  rootThreads: ChatThread[];
  folderSections: FolderSidebarSection[];
};

export type MoveSelectOption = { value: string; label: string };

export function sortFoldersByOrderThenUpdated(
  folders: ChatFolder[],
): ChatFolder[] {
  return [...folders].sort(
    (a, b) => a.order - b.order || b.updatedAt - a.updatedAt,
  );
}

/** If any row has numeric `order`, sort by order asc then updatedAt; else updatedAt desc only. */
export function sortThreadsWithOrderFallback(threads: ChatThread[]): ChatThread[] {
  const anyOrder = threads.some(
    (t) => typeof t.order === "number" && !Number.isNaN(t.order),
  );
  if (!anyOrder) {
    return [...threads].sort((a, b) => b.updatedAt - a.updatedAt);
  }
  return [...threads].sort((a, b) => {
    const ao =
      typeof a.order === "number" && !Number.isNaN(a.order) ? a.order : 1e15;
    const bo =
      typeof b.order === "number" && !Number.isNaN(b.order) ? b.order : 1e15;
    if (ao !== bo) return ao - bo;
    return b.updatedAt - a.updatedAt;
  });
}

/** When `allowed` is set, keep only threads whose id is in the set (search filter). */
export function filterFolderSidebarModel(
  model: FolderSidebarModel,
  allowed: Set<string> | null,
): FolderSidebarModel {
  if (!allowed) return model;
  return {
    rootThreads: model.rootThreads.filter((t) => allowed.has(t.id)),
    folderSections: model.folderSections
      .map((section) => ({
        ...section,
        threads: section.threads.filter((t) => allowed.has(t.id)),
      }))
      .filter((s) => s.threads.length > 0),
  };
}

export function buildFolderSidebarModel(
  threads: ChatThread[],
  folders: ChatFolder[],
): FolderSidebarModel {
  const orderedFolders = sortFoldersByOrderThenUpdated(folders);
  const folderIds = new Set(orderedFolders.map((f) => f.id));

  const rootThreads = sortThreadsWithOrderFallback(
    threads.filter((t) => {
      const fid = t.folderId ?? null;
      if (fid == null || fid === "") return true;
      return !folderIds.has(fid);
    }),
  );

  const folderSections: FolderSidebarSection[] = orderedFolders.map(
    (folder) => ({
      folder,
      threads: sortThreadsWithOrderFallback(
        threads.filter((t) => (t.folderId ?? null) === folder.id),
      ),
    }),
  );

  return { rootThreads, folderSections };
}

/** Full move dropdown: Chats + every folder; value matches current bucket. */
export function buildMoveSelectModel(
  thread: ChatThread,
  allFolders: ChatFolder[],
): { show: boolean; value: string; options: MoveSelectOption[] } {
  const sortedFolders = sortFoldersByOrderThenUpdated(allFolders);
  const options: MoveSelectOption[] = [
    { value: "__root__", label: "Chats" },
    ...sortedFolders.map((f) => ({ value: f.id, label: f.name })),
  ];
  const cur = thread.folderId ?? null;
  const inKnownFolder = cur != null && sortedFolders.some((f) => f.id === cur);
  const value = inKnownFolder ? cur! : "__root__";
  const show = sortedFolders.length > 0;
  return { show, value, options };
}

/** Trim + lowercase for duplicate folder detection (case-insensitive). */
export function normalizeFolderName(name: string): string {
  return name.trim().toLowerCase();
}

export function isDuplicateFolderName(
  name: string,
  folders: Pick<ChatFolder, "id" | "name">[],
  ignoreId?: string,
): boolean {
  const key = normalizeFolderName(name);
  if (!key) return false;
  return folders.some(
    (f) => (ignoreId == null || f.id !== ignoreId) && normalizeFolderName(f.name) === key,
  );
}

/** @deprecated Prefer buildMoveSelectModel - kept for tests referencing old API */
export function buildMoveTargetsForThread(
  thread: ChatThread,
  allFolders: ChatFolder[],
): { folderId: string | null; label: string }[] {
  const cur = thread.folderId ?? null;
  const targets: { folderId: string | null; label: string }[] = [];
  if (cur !== null) {
    targets.push({ folderId: null, label: "Chats" });
  }
  for (const f of allFolders) {
    if (f.id !== cur) targets.push({ folderId: f.id, label: f.name });
  }
  return targets;
}// ── chat-scroll - near-bottom detection for SpiritChat stickiness (Prompt 9H) ───

export const DEFAULT_SCROLL_NEAR_BOTTOM_PX = 160;

/** True when the user is within `threshold` px of the scroll bottom. */
export function isNearBottom(
  el: HTMLElement | null | undefined,
  threshold: number = DEFAULT_SCROLL_NEAR_BOTTOM_PX,
): boolean {
  if (!el) return true;
  const gap = el.scrollHeight - el.scrollTop - el.clientHeight;
  return gap < threshold;
}// ── chat-thread-format - sidebar timestamp labels (shared by folder + list rows) ─

export function formatThreadUpdatedLabel(updatedAt: number): string {
  const diffMs = Math.max(0, Date.now() - updatedAt);
  if (diffMs < 60_000) return "now";
  if (diffMs < 3_600_000) return `${Math.floor(diffMs / 60_000)}m ago`;
  if (diffMs < 86_400_000) return `${Math.floor(diffMs / 3_600_000)}h ago`;
  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(updatedAt);
}// ── clipboard - SpiritMessage copy without assuming secure context (10B) ─────────

export type CopyTextResult = { ok: true } | { ok: false; reason: "unavailable" | "denied" };

/** Best-effort copy; never throws. */
export async function copyTextToClipboard(text: string): Promise<CopyTextResult> {
  const t = text;
  try {
    const w = typeof navigator !== "undefined" ? navigator : undefined;
    const clip = w?.clipboard;
    const write = clip?.writeText;
    if (typeof write === "function") {
      await write.call(clip, t);
      return { ok: true };
    }
  } catch {
    return { ok: false, reason: "denied" };
  }

  if (typeof document === "undefined") {
    return { ok: false, reason: "unavailable" };
  }

  try {
    const ta = document.createElement("textarea");
    ta.value = t;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    ta.style.top = "0";
    document.body.appendChild(ta);
    ta.select();
    const legacyOk = document.execCommand?.("copy");
    document.body.removeChild(ta);
    if (legacyOk) return { ok: true };
  } catch {
    /* fall through */
  }

  return { ok: false, reason: "unavailable" };
}// ── cn() - Tailwind class merge without fighting yourself ─────────────────────
// > Extracted from: ad-hoc dashboard copy-paste (deleted with prejudice)
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}// ── spirit-chat-tts - pure guards for outbound assistant finish (Prompt 9H) ───

export type AssistantOutboundFinishPlan =
  | { kind: "commit" }
  | { kind: "skip"; reason: string; keepOutcomeRef: boolean };

/**
 * Decide whether to persist + clear `assistantOutcomeThreadRef`.
 * Empty body / missing thread / wrong active thread → skip and usually **keep** ref
 * so a later legitimate finish still sees the outcome thread id.
 */
export function planAssistantOutboundFinish(opts: {
  threadId: string | null;
  body: string;
  activeThreadId: string | null;
  draftLaneActive: boolean;
}): AssistantOutboundFinishPlan {
  if (!opts.threadId) {
    return { kind: "skip", reason: "no-outcome-thread", keepOutcomeRef: true };
  }
  if (!opts.body.trim()) {
    return { kind: "skip", reason: "empty-assistant-text", keepOutcomeRef: true };
  }
  /* Draft lane: always commit outbound assistant for that thread id (Dexie lane has no activeThreadId). */
  if (opts.draftLaneActive) {
    return { kind: "commit" };
  }
  if (opts.activeThreadId != null && opts.threadId !== opts.activeThreadId) {
    return { kind: "skip", reason: "wrong-thread", keepOutcomeRef: true };
  }
  return { kind: "commit" };
}

/** Stop in-flight TTS when user sends a new prompt while auto-speak is on. */
export function shouldStopTtsOnOutboundSubmit(opts: {
  autoSpeakAssistant: boolean;
  isPlaying: boolean;
  queueLength: number;
}): boolean {
  return opts.autoSpeakAssistant && (opts.isPlaying || opts.queueLength > 0);
}

import { pickTtsSpeakPayload } from "@/lib/tts/tts-text-budget";

/**
 * Single auto-speak entry (Prompt 9K + 10B): long assistant replies → summary TTS path.
 */
export function runAutoSpeakAssistantFinish(opts: {
  text: string;
  messageId: string;
  speak: (
    text: string,
    o?: { interrupt?: boolean; preferHtmlAudioFirst?: boolean; spokenSummaryLine?: string },
  ) => void;
  voiceEnabled: boolean;
  autoSpeakAssistant: boolean;
}): void {
  if (!opts.voiceEnabled) {
    if (process.env.NODE_ENV === "development") {
      console.info("[tts] auto-speak skipped: disabled");
    }
    return;
  }
  if (!opts.autoSpeakAssistant) {
    if (process.env.NODE_ENV === "development") {
      console.info("[tts] auto-speak skipped: auto-speak off");
    }
    return;
  }
  const t = opts.text.trim();
  if (!t) {
    if (process.env.NODE_ENV === "development") {
      console.info("[tts] auto-speak skipped: no text");
    }
    return;
  }
  if (process.env.NODE_ENV === "development") {
    console.info(`[tts] auto-speaking finished assistant response ${opts.messageId}`);
  }
  const plan = pickTtsSpeakPayload(t, "summary");
  const chunk = plan.segments[0] ?? "";
  if (!chunk) return;
  opts.speak(chunk, {
    interrupt: true,
    preferHtmlAudioFirst: false,
    spokenSummaryLine: plan.spokenSummaryLine,
  });
}// ── verified-http-url - shared digest / policy / header URL gate ─────────────────
// > Client-safe: `research-source-enforcement` is imported by SpiritChat; do not
//   depend on `server-only` OpenAI modules here.

/**
 * Bare host / protocol-relative → https so OpenAI payload quirks still produce
 * one canonical string for digest lines and `x-spirit-web-sources`.
 */
export function normalizeToHttpUrl(raw: string | undefined): string | undefined {
  let t = (raw ?? "").trim();
  // OpenAI / markdown sometimes wraps links - strip before host detection.
  t = t.replace(/^<+/, "").replace(/>+$/, "").trim();
  if (!t) return undefined;
  if (/^(javascript|data|mailto|vbscript):/i.test(t)) return undefined;
  if (/^https?:\/\//i.test(t)) return t;
  if (t.startsWith("//")) {
    const host = t.slice(2).replace(/^\/+/, "");
    return host ? `https://${host}` : undefined;
  }
  if (/[\s<>"]/.test(t)) return undefined;
  if (!/^[a-zA-Z0-9][a-zA-Z0-9.-]*\.[a-zA-Z]{2,}/.test(t)) return undefined;
  return `https://${t}`;
}

/**
 * After normalization, only true http(s) origins count as “verified” everywhere:
 * digest, Teacher budget, policy `searchUsed`, telemetry headers.
 */
export function resolveVerifiedHttpUrl(raw: string | undefined): string | undefined {
  const n = normalizeToHttpUrl(raw);
  if (!n) return undefined;
  return /^https?:\/\//i.test(n) ? n : undefined;
}

/** `normalizeToHttpUrl` then strict `^https?:` - post-normalize bare hosts count as verified. */
export function isVerifiedHttpUrl(url: string | undefined): boolean {
  return Boolean(resolveVerifiedHttpUrl(url));
}/* ── Spirit Demo · Animations ────────────────────────────────────────────────
 * > Keyframes + motion utility classes + reduced-motion overrides.
 * > All keyframe identifiers are prefixed `demo*` so they cannot collide with
 *   any keyframes defined in the host app.
 * > Respects `prefers-reduced-motion: reduce` - looping motion is disabled,
 *   static gradients and layout remain.
 * ────────────────────────────────────────────────────────────────────────── */

/* ─────────── Keyframes ─────────── */
@keyframes demoOrbBreathe {
  0%, 100% {
    transform: scale(1);
    box-shadow:
      0 0 36px -2px color-mix(in oklab, var(--demo-cyan, #22d3ee) 50%, transparent),
      0 0 68px -8px color-mix(in oklab, var(--demo-violet, #a855f7) 45%, transparent),
      inset 0 0 28px -6px rgba(255, 255, 255, 0.32);
  }
  50% {
    transform: scale(1.04);
    box-shadow:
      0 0 48px 0 color-mix(in oklab, var(--demo-cyan, #22d3ee) 60%, transparent),
      0 0 88px -4px color-mix(in oklab, var(--demo-violet, #a855f7) 55%, transparent),
      inset 0 0 32px -4px rgba(255, 255, 255, 0.4);
  }
}

@keyframes demoOrbHalo {
  0%, 100% { opacity: 0.7; transform: scale(1); }
  50%      { opacity: 1;   transform: scale(1.06); }
}

@keyframes demoOrbPulse {
  0%, 100% { transform: scale(1);    opacity: 0.4; }
  50%      { transform: scale(1.08); opacity: 0.85; }
}

@keyframes demoWave {
  0%, 100% { height: 18%; }
  20%      { height: 65%; }
  40%      { height: 30%; }
  60%      { height: 90%; }
  80%      { height: 45%; }
}

@keyframes demoPulseDot {
  0%   { transform: scale(0.9);  opacity: 0.9; }
  80%  { transform: scale(2.2);  opacity: 0; }
  100% { transform: scale(2.4);  opacity: 0; }
}

@keyframes demoShimmer {
  0%      { opacity: 0;    transform: translateX(-30%); }
  10%     { opacity: 0.9; }
  50%     { opacity: 0.9;  transform: translateX(0); }
  90%     { opacity: 0.9; }
  100%    { opacity: 0;    transform: translateX(30%); }
}

@keyframes demoGradientPan {
  0%   { background-position:   0% 50%; }
  100% { background-position: 200% 50%; }
}

@keyframes demoFadeUp {
  0%   { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes demoBlinkCaret {
  0%, 60%   { opacity: 1; }
  61%, 100% { opacity: 0; }
}

@keyframes demoScrollUp {
  0%   { transform: translateY(0); }
  100% { transform: translateY(-50%); }
}

/* ─────────── Motion utilities ─────────── */
.spirit-demo-root .demo-motion-fade-up {
  animation: demoFadeUp var(--demo-dur-mid) var(--demo-ease-out) both;
}
.spirit-demo-root .demo-motion-fade-up--delay-1 { animation-delay: 80ms; }
.spirit-demo-root .demo-motion-fade-up--delay-2 { animation-delay: 160ms; }
.spirit-demo-root .demo-motion-fade-up--delay-3 { animation-delay: 240ms; }
.spirit-demo-root .demo-motion-fade-up--delay-4 { animation-delay: 320ms; }
.spirit-demo-root .demo-motion-fade-up--delay-5 { animation-delay: 400ms; }

.spirit-demo-root .demo-motion-caret {
  animation: demoBlinkCaret 1.1s steps(1) infinite;
}

.spirit-demo-root .demo-motion-marquee {
  display: flex;
  flex-direction: column;
  animation: demoScrollUp 28s linear infinite;
}

/* ─────────── Reduced motion overrides ─────────── */
@media (prefers-reduced-motion: reduce) {
  .spirit-demo-root *,
  .spirit-demo-root *::before,
  .spirit-demo-root *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
  /* Keep the orb visually stable but not animated */
  .spirit-demo-root .demo-orb__core {
    transform: none !important;
  }
  .spirit-demo-root .demo-orb__halo,
  .spirit-demo-root .demo-orb__ring {
    opacity: 0.6 !important;
    transform: none !important;
  }
  /* Keep waveform legible (static height) */
  .spirit-demo-root .demo-wave__bar {
    height: 38% !important;
  }
  /* Keep gradient text visible without panning */
  .spirit-demo-root .demo-hero__title em {
    background-position: 0% 50% !important;
    animation: none !important;
  }
  /* Keep shimmer line invisible (no looping sweep) */
  .spirit-demo-root .demo-shimmer {
    opacity: 0 !important;
    animation: none !important;
  }
  /* Pulse dot rings hidden - keep only the static dot */
  .spirit-demo-root .demo-pulse-dot::after {
    display: none !important;
  }
}

/* Focus ring (accessibility) - always present, doesn’t care about motion */
.spirit-demo-root :where(a, button, [role="button"]):focus-visible {
  outline: 2px solid color-mix(in oklab, var(--demo-cyan) 80%, transparent);
  outline-offset: 2px;
  border-radius: inherit;
}/* ── Spirit Demo · Components ────────────────────────────────────────────────
 * > Cards, buttons, badges, panels, chat bubbles, status rows, profile chips.
 * > Fully scoped under .spirit-demo-root.
 * ────────────────────────────────────────────────────────────────────────── */

/* ─────────── Cards ─────────── */
.spirit-demo-root .demo-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  padding: clamp(1rem, 2.4vw, 1.4rem);
  border-radius: var(--demo-radius-lg);
  background: var(--demo-glass);
  border: 1px solid var(--demo-border);
  box-shadow: var(--demo-inset-shine);
  backdrop-filter: blur(var(--demo-blur-md));
  -webkit-backdrop-filter: blur(var(--demo-blur-md));
  transition:
    transform var(--demo-dur-mid) var(--demo-ease-out),
    border-color var(--demo-dur-mid) var(--demo-ease-out),
    box-shadow var(--demo-dur-mid) var(--demo-ease-out);
}
@media (min-width: 1024px) and (hover: hover) {
  .spirit-demo-root .demo-card:hover {
    transform: translateY(-2px);
    border-color: var(--demo-border-strong);
    box-shadow:
      var(--demo-glow-soft),
      var(--demo-inset-shine-strong);
  }
}
.spirit-demo-root .demo-card--feature {
  background: linear-gradient(
    150deg,
    color-mix(in oklab, var(--demo-cyan) 7%, transparent),
    color-mix(in oklab, var(--demo-violet) 4%, transparent) 60%,
    transparent
  );
  border-color: color-mix(in oklab, var(--demo-cyan) 26%, transparent);
  box-shadow: var(--demo-glow-soft), var(--demo-inset-shine-strong);
}
.spirit-demo-root .demo-card--quarantine {
  border-color: color-mix(in oklab, var(--demo-rose) 32%, transparent);
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--demo-rose) 8%, transparent),
    color-mix(in oklab, var(--demo-rose) 1.5%, transparent) 70%
  );
  box-shadow: var(--demo-glow-rose), var(--demo-inset-shine);
}
.spirit-demo-root .demo-card--oracle {
  border-color: color-mix(in oklab, var(--demo-violet) 30%, transparent);
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--demo-violet) 8%, transparent),
    color-mix(in oklab, var(--demo-violet) 1.5%, transparent) 70%
  );
  box-shadow: var(--demo-glow-violet), var(--demo-inset-shine);
}

.spirit-demo-root .demo-card__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  font-weight: 600;
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: color-mix(in oklab, var(--demo-accent-strong) 80%, white);
}
.spirit-demo-root .demo-card--quarantine .demo-card__eyebrow {
  color: color-mix(in oklab, var(--demo-rose-strong) 90%, white);
}
.spirit-demo-root .demo-card--oracle .demo-card__eyebrow {
  color: color-mix(in oklab, var(--demo-violet-strong) 90%, white);
}
.spirit-demo-root .demo-card__title {
  font-size: var(--demo-text-lead);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--demo-text);
}
.spirit-demo-root .demo-card__body {
  font-size: var(--demo-text-caption);
  line-height: 1.55;
  color: var(--demo-text-muted);
}
.spirit-demo-root .demo-card__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-top: auto;
  padding-top: 0.5rem;
}

/* ─────────── Buttons ─────────── */
.spirit-demo-root .demo-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 44px;
  min-width: 44px;
  padding: 0.55rem 1.05rem;
  border-radius: var(--demo-radius-pill);
  border: 1px solid var(--demo-border);
  background: var(--demo-glass-strong);
  color: var(--demo-text);
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-caption);
  font-weight: 600;
  letter-spacing: 0.02em;
  text-decoration: none;
  cursor: pointer;
  transition:
    transform var(--demo-dur-fast) var(--demo-ease-out),
    background var(--demo-dur-fast) var(--demo-ease-out),
    border-color var(--demo-dur-fast) var(--demo-ease-out);
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}
.spirit-demo-root .demo-btn:hover {
  border-color: var(--demo-border-strong);
  background: color-mix(in oklab, var(--demo-glass-strong) 100%, white 4%);
}
.spirit-demo-root .demo-btn:active { transform: scale(0.98); }
.spirit-demo-root .demo-btn--primary {
  background: color-mix(in oklab, var(--demo-cyan) 14%, transparent);
  border-color: color-mix(in oklab, var(--demo-cyan) 42%, transparent);
  color: var(--demo-cyan-strong);
  box-shadow: var(--demo-glow-soft);
}
.spirit-demo-root .demo-btn--primary:hover {
  background: color-mix(in oklab, var(--demo-cyan) 22%, transparent);
  border-color: color-mix(in oklab, var(--demo-cyan) 60%, transparent);
}
.spirit-demo-root .demo-btn--violet {
  background: color-mix(in oklab, var(--demo-violet) 14%, transparent);
  border-color: color-mix(in oklab, var(--demo-violet) 42%, transparent);
  color: var(--demo-violet-strong);
}
.spirit-demo-root .demo-btn--violet:hover {
  background: color-mix(in oklab, var(--demo-violet) 22%, transparent);
}
.spirit-demo-root .demo-btn--rose {
  background: color-mix(in oklab, var(--demo-rose) 12%, transparent);
  border-color: color-mix(in oklab, var(--demo-rose) 38%, transparent);
  color: var(--demo-rose-strong);
}
.spirit-demo-root .demo-btn--rose:hover {
  background: color-mix(in oklab, var(--demo-rose) 20%, transparent);
}
.spirit-demo-root .demo-btn--ghost {
  background: transparent;
  border-color: var(--demo-border);
  color: var(--demo-text-muted);
}
.spirit-demo-root .demo-btn--ghost:hover {
  color: var(--demo-text);
  border-color: var(--demo-border-strong);
}
.spirit-demo-root .demo-btn--sm {
  min-height: 36px;
  padding: 0.35rem 0.75rem;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
}
.spirit-demo-root .demo-btn[aria-disabled="true"],
.spirit-demo-root .demo-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* ─────────── Badges & chips ─────────── */
.spirit-demo-root .demo-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.25rem 0.6rem;
  border-radius: var(--demo-radius-pill);
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  font-weight: 600;
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  border: 1px solid var(--demo-border);
  color: var(--demo-text-muted);
  background: var(--demo-glass-soft);
  white-space: nowrap;
}
.spirit-demo-root .demo-badge--cyan {
  border-color: color-mix(in oklab, var(--demo-cyan) 36%, transparent);
  background: color-mix(in oklab, var(--demo-cyan) 10%, transparent);
  color: var(--demo-cyan-strong);
}
.spirit-demo-root .demo-badge--violet {
  border-color: color-mix(in oklab, var(--demo-violet) 36%, transparent);
  background: color-mix(in oklab, var(--demo-violet) 10%, transparent);
  color: var(--demo-violet-strong);
}
.spirit-demo-root .demo-badge--rose {
  border-color: color-mix(in oklab, var(--demo-rose) 36%, transparent);
  background: color-mix(in oklab, var(--demo-rose) 10%, transparent);
  color: var(--demo-rose-strong);
}
.spirit-demo-root .demo-badge--emerald {
  border-color: color-mix(in oklab, var(--demo-emerald) 36%, transparent);
  background: color-mix(in oklab, var(--demo-emerald) 10%, transparent);
  color: var(--demo-emerald-strong);
}
.spirit-demo-root .demo-badge--warn {
  border-color: color-mix(in oklab, var(--demo-warn) 36%, transparent);
  background: color-mix(in oklab, var(--demo-warn) 10%, transparent);
  color: var(--demo-amber-strong);
}

/* ─────────── Section nav (top tabs / dock buttons) ─────────── */
.spirit-demo-root .demo-tab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 1 1 auto;
  min-height: 44px;
  padding: 0.4rem 0.65rem;
  border: 0;
  background: transparent;
  color: var(--demo-text-faint);
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  font-weight: 600;
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  text-decoration: none;
  border-radius: var(--demo-radius-pill);
  cursor: pointer;
  transition:
    color var(--demo-dur-fast) var(--demo-ease-out),
    background var(--demo-dur-fast) var(--demo-ease-out);
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}
.spirit-demo-root .demo-tab:hover { color: var(--demo-text); }
.spirit-demo-root .demo-tab[aria-current="true"],
.spirit-demo-root .demo-tab--active {
  color: var(--demo-cyan-strong);
  background: color-mix(in oklab, var(--demo-cyan) 14%, transparent);
  box-shadow: var(--demo-glow-soft);
}
.spirit-demo-root .demo-tab__icon {
  display: inline-grid;
  place-items: center;
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}
.spirit-demo-root .demo-tab__label {
  display: none;
}
@media (min-width: 480px) {
  .spirit-demo-root .demo-tab__label {
    display: inline;
  }
}

/* ─────────── Side rail buttons ─────────── */
.spirit-demo-root .demo-rail-btn {
  display: grid;
  place-items: center;
  width: 2.6rem;
  height: 2.6rem;
  border: 1px solid transparent;
  background: transparent;
  color: var(--demo-text-faint);
  border-radius: var(--demo-radius-md);
  cursor: pointer;
  transition:
    color var(--demo-dur-fast) var(--demo-ease-out),
    background var(--demo-dur-fast) var(--demo-ease-out),
    border-color var(--demo-dur-fast) var(--demo-ease-out);
}
.spirit-demo-root .demo-rail-btn:hover {
  color: var(--demo-text);
  background: var(--demo-glass);
  border-color: var(--demo-border);
}
.spirit-demo-root .demo-rail-btn[aria-current="true"] {
  color: var(--demo-cyan-strong);
  background: color-mix(in oklab, var(--demo-cyan) 12%, transparent);
  border-color: color-mix(in oklab, var(--demo-cyan) 32%, transparent);
  box-shadow: var(--demo-glow-soft);
}

/* ─────────── Hero panel ─────────── */
.spirit-demo-root .demo-hero {
  position: relative;
  overflow: hidden;
  border-radius: var(--demo-radius-xl);
  padding: clamp(1.25rem, 4vw, 2rem);
  min-height: 18rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 1.25rem;
  background:
    radial-gradient(
      ellipse 70% 90% at 100% 0%,
      color-mix(in oklab, var(--demo-violet) 14%, transparent),
      transparent 65%
    ),
    radial-gradient(
      ellipse 80% 100% at 0% 100%,
      color-mix(in oklab, var(--demo-cyan) 12%, transparent),
      transparent 60%
    ),
    var(--demo-glass-strong);
  border: 1px solid color-mix(in oklab, var(--demo-cyan) 22%, transparent);
  box-shadow:
    var(--demo-glow-cyan),
    var(--demo-inset-shine-strong);
  backdrop-filter: blur(var(--demo-blur-md));
  -webkit-backdrop-filter: blur(var(--demo-blur-md));
}
.spirit-demo-root .demo-hero__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.spirit-demo-root .demo-hero__title {
  font-size: var(--demo-text-h1);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1;
  color: var(--demo-text);
  margin-block: 0.25rem 0.75rem;
}
.spirit-demo-root .demo-hero__title em {
  font-style: normal;
  background: linear-gradient(
    100deg,
    var(--demo-cyan-strong),
    var(--demo-violet-strong) 60%,
    var(--demo-cyan-strong)
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
          background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: demoGradientPan 12s linear infinite;
}
.spirit-demo-root .demo-hero__sub {
  max-width: 38rem;
  font-size: var(--demo-text-body);
  line-height: 1.55;
  color: var(--demo-text-muted);
}
.spirit-demo-root .demo-hero__ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

/* ─────────── Status row (telemetry stripe) ─────────── */
.spirit-demo-root .demo-status-row {
  display: grid;
  grid-template-columns: minmax(0, 5rem) minmax(0, 1fr) minmax(0, auto);
  align-items: center;
  gap: 0.75rem;
  padding: 0.55rem 0.75rem;
  border-radius: var(--demo-radius-md);
  background: var(--demo-glass-soft);
  border: 1px solid var(--demo-border);
}
.spirit-demo-root .demo-status-row + .demo-status-row { margin-top: 0.4rem; }
.spirit-demo-root .demo-status-row__label {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  font-weight: 600;
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: var(--demo-text-faint);
}
.spirit-demo-root .demo-status-row__value {
  min-width: 0;
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-caption);
  color: var(--demo-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.spirit-demo-root .demo-status-row__hint {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: 0.05em;
  color: var(--demo-text-faint);
  white-space: nowrap;
}

/* ─────────── Diagnostics card ─────────── */
.spirit-demo-root .demo-diag {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 1rem;
  border-radius: var(--demo-radius-md);
  border: 1px solid var(--demo-border);
  background: var(--demo-glass-soft);
}
.spirit-demo-root .demo-diag__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}
.spirit-demo-root .demo-diag__name {
  font-size: var(--demo-text-caption);
  font-weight: 600;
  color: var(--demo-text);
}
.spirit-demo-root .demo-diag__detail {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: 0.04em;
  color: var(--demo-text-faint);
  word-break: break-word;
}

/* ─────────── Chat preview bubbles ─────────── */
.spirit-demo-root .demo-chat-rail {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-height: 0;
}
.spirit-demo-root .demo-chat-rail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding-bottom: 0.4rem;
  border-bottom: 1px solid var(--demo-border);
}
.spirit-demo-root .demo-chat-rail__group {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.spirit-demo-root .demo-chat-rail__folder {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: var(--demo-text-faint);
  padding: 0.4rem 0.55rem 0.2rem;
}
.spirit-demo-root .demo-chat-rail__thread {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.55rem 0.6rem;
  border-radius: var(--demo-radius-sm);
  font-size: var(--demo-text-caption);
  color: var(--demo-text-muted);
  background: transparent;
  border: 1px solid transparent;
  cursor: default;
  min-height: 44px;
}
.spirit-demo-root .demo-chat-rail__thread--active {
  background: color-mix(in oklab, var(--demo-cyan) 10%, transparent);
  border-color: color-mix(in oklab, var(--demo-cyan) 28%, transparent);
  color: var(--demo-text);
}
.spirit-demo-root .demo-chat-rail__thread-pin {
  width: 6px;
  height: 6px;
  flex-shrink: 0;
  border-radius: 50%;
  background: color-mix(in oklab, var(--demo-amber) 80%, transparent);
}
.spirit-demo-root .demo-chat-rail__thread-title {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.spirit-demo-root .demo-chat-pane {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  min-height: 24rem;
}
.spirit-demo-root .demo-chat-modebar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--demo-border);
}
.spirit-demo-root .demo-chat-stream {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}
.spirit-demo-root .demo-bubble {
  max-width: 85%;
  padding: 0.75rem 1rem;
  border-radius: var(--demo-radius-md);
  font-size: var(--demo-text-body);
  line-height: 1.55;
  background: var(--demo-glass);
  border: 1px solid var(--demo-border);
  color: var(--demo-text);
}
.spirit-demo-root .demo-bubble--user {
  align-self: flex-end;
  background: color-mix(in oklab, var(--demo-cyan) 12%, transparent);
  border-color: color-mix(in oklab, var(--demo-cyan) 28%, transparent);
}
.spirit-demo-root .demo-bubble--spirit {
  align-self: flex-start;
  background: var(--demo-glass-strong);
}
.spirit-demo-root .demo-bubble__role {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: var(--demo-text-faint);
  margin-bottom: 0.35rem;
}
.spirit-demo-root .demo-bubble--spirit .demo-bubble__role {
  color: var(--demo-cyan-strong);
}
.spirit-demo-root .demo-chat-composer {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem;
  border-radius: var(--demo-radius-pill);
  border: 1px solid var(--demo-border);
  background: var(--demo-glass-soft);
}
.spirit-demo-root .demo-chat-composer__field {
  flex: 1;
  min-width: 0;
  padding: 0.35rem 0.75rem;
  font-family: inherit;
  font-size: 16px; /* mobile: prevents iOS zoom */
  color: var(--demo-text-muted);
}

/* ─────────── Profile preview ─────────── */
.spirit-demo-root .demo-profile {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.spirit-demo-root .demo-profile__head {
  display: flex;
  align-items: center;
  gap: 0.875rem;
}
.spirit-demo-root .demo-profile__avatar {
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(
    140deg,
    color-mix(in oklab, var(--demo-cyan) 30%, transparent),
    color-mix(in oklab, var(--demo-violet) 30%, transparent)
  );
  border: 1px solid color-mix(in oklab, var(--demo-cyan) 30%, transparent);
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--demo-cyan-strong);
}
.spirit-demo-root .demo-profile__meta-name {
  font-size: var(--demo-text-lead);
  font-weight: 600;
  color: var(--demo-text);
}
.spirit-demo-root .demo-profile__meta-id {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: var(--demo-text-faint);
}

/* - -  Personality stats bars - -  */
.spirit-demo-root .demo-stat {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}
.spirit-demo-root .demo-stat__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: var(--demo-text-muted);
}
.spirit-demo-root .demo-stat__value {
  color: var(--demo-cyan-strong);
}
.spirit-demo-root .demo-stat__track {
  position: relative;
  height: 4px;
  border-radius: var(--demo-radius-pill);
  background: color-mix(in oklab, var(--demo-bg-deep) 60%, transparent);
  overflow: hidden;
  border: 1px solid var(--demo-border);
}
.spirit-demo-root .demo-stat__fill {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    var(--demo-cyan),
    var(--demo-violet)
  );
  box-shadow: 0 0 8px color-mix(in oklab, var(--demo-cyan) 50%, transparent);
}

/* - -  Disabled / mock surface tag - -  */
.spirit-demo-root .demo-mock-tag {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: var(--demo-text-ghost);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}
.spirit-demo-root .demo-mock-tag::before {
  content: "";
  width: 8px;
  height: 1px;
  background: currentColor;
}

/* - -  Compact stat tile - -  */
.spirit-demo-root .demo-stat-tile {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.85rem;
  border-radius: var(--demo-radius-md);
  border: 1px solid var(--demo-border);
  background: var(--demo-glass-soft);
}
.spirit-demo-root .demo-stat-tile__label {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: var(--demo-text-faint);
}
.spirit-demo-root .demo-stat-tile__value {
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-h3);
  font-weight: 600;
  color: var(--demo-text);
  font-feature-settings: "tnum" 1;
}
.spirit-demo-root .demo-stat-tile__hint {
  font-size: var(--demo-text-eyebrow);
  letter-spacing: 0.04em;
  color: var(--demo-text-faint);
}

/* - -  Visual divider - -  */
.spirit-demo-root .demo-divider {
  height: 1px;
  width: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    var(--demo-border-strong),
    transparent
  );
  border: 0;
  margin-block: 0.5rem;
}/* ── Spirit Demo · Effects ───────────────────────────────────────────────────
 * > Glass surface treatments, accent glows, scanline overlays, orb rings,
 *   shimmer lines. All scoped under .spirit-demo-root.
 * ────────────────────────────────────────────────────────────────────────── */

/* - -  Glass surface base - -  */
.spirit-demo-root .demo-glass {
  background: var(--demo-glass);
  backdrop-filter: blur(var(--demo-blur-md)) saturate(115%);
  -webkit-backdrop-filter: blur(var(--demo-blur-md)) saturate(115%);
  border: 1px solid var(--demo-border);
  box-shadow: var(--demo-inset-shine);
}
.spirit-demo-root .demo-glass--strong {
  background: var(--demo-glass-strong);
  border-color: var(--demo-border-strong);
  box-shadow:
    var(--demo-glow-soft),
    var(--demo-inset-shine-strong);
}
.spirit-demo-root .demo-glass--soft {
  background: var(--demo-glass-soft);
  border-color: color-mix(in oklab, var(--demo-border) 60%, transparent);
}

/* - -  Accent-tinted glass (per lane) - -  */
.spirit-demo-root .demo-glass--cyan {
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--demo-cyan) 7%, transparent),
    color-mix(in oklab, var(--demo-cyan) 2%, transparent) 70%
  );
  border-color: color-mix(in oklab, var(--demo-cyan) 22%, transparent);
  box-shadow: var(--demo-glow-cyan), var(--demo-inset-shine);
}
.spirit-demo-root .demo-glass--violet {
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--demo-violet) 8%, transparent),
    color-mix(in oklab, var(--demo-violet) 2%, transparent) 70%
  );
  border-color: color-mix(in oklab, var(--demo-violet) 24%, transparent);
  box-shadow: var(--demo-glow-violet), var(--demo-inset-shine);
}
.spirit-demo-root .demo-glass--rose {
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--demo-rose) 8%, transparent),
    color-mix(in oklab, var(--demo-rose) 2%, transparent) 70%
  );
  border-color: color-mix(in oklab, var(--demo-rose) 26%, transparent);
  box-shadow: var(--demo-glow-rose), var(--demo-inset-shine);
}
.spirit-demo-root .demo-glass--emerald {
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--demo-emerald) 7%, transparent),
    color-mix(in oklab, var(--demo-emerald) 2%, transparent) 70%
  );
  border-color: color-mix(in oklab, var(--demo-emerald) 22%, transparent);
  box-shadow: var(--demo-glow-emerald), var(--demo-inset-shine);
}

/* - -  Scanline overlay (decorative; aria-hidden on host) - -  */
.spirit-demo-root .demo-scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    0deg,
    rgba(255, 255, 255, 0.025) 0,
    rgba(255, 255, 255, 0.025) 1px,
    transparent 1px,
    transparent 4px
  );
  opacity: 0.55;
  mix-blend-mode: overlay;
  border-radius: inherit;
}

/* - -  Shimmer line (horizontal sweep across hero) - -  */
.spirit-demo-root .demo-shimmer {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 1px;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--demo-cyan) 70%, transparent) 30%,
    color-mix(in oklab, var(--demo-cyan-strong) 100%, transparent) 50%,
    color-mix(in oklab, var(--demo-cyan) 70%, transparent) 70%,
    transparent
  );
  opacity: 0;
  animation: demoShimmer var(--demo-dur-shimmer) ease-in-out infinite;
  border-radius: inherit;
}

/* - -  Orb ring system (Oracle preview) - -  */
.spirit-demo-root .demo-orb {
  position: relative;
  width: clamp(11rem, 50vw, 16rem);
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  margin-inline: auto;
}
.spirit-demo-root .demo-orb__halo {
  position: absolute;
  inset: -22%;
  border-radius: 50%;
  background: radial-gradient(
    circle at 50% 50%,
    color-mix(in oklab, var(--demo-violet) 22%, transparent) 0%,
    color-mix(in oklab, var(--demo-cyan) 14%, transparent) 35%,
    transparent 70%
  );
  filter: blur(24px);
  animation: demoOrbHalo 5s ease-in-out infinite;
}
.spirit-demo-root .demo-orb__ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid color-mix(in oklab, var(--demo-cyan) 35%, transparent);
  background: color-mix(in oklab, var(--demo-cyan) 4%, transparent);
}
.spirit-demo-root .demo-orb__ring--1 {
  inset: 14%;
  animation: demoOrbPulse var(--demo-dur-breath) ease-in-out infinite;
}
.spirit-demo-root .demo-orb__ring--2 {
  inset: 4%;
  border-color: color-mix(in oklab, var(--demo-cyan) 22%, transparent);
  animation: demoOrbPulse calc(var(--demo-dur-breath) + 600ms) ease-in-out
    infinite reverse;
  animation-delay: -1.2s;
}
.spirit-demo-root .demo-orb__ring--3 {
  inset: -8%;
  border-color: color-mix(in oklab, var(--demo-violet) 18%, transparent);
  animation: demoOrbPulse calc(var(--demo-dur-breath) + 1.2s) ease-in-out
    infinite;
  animation-delay: -2.4s;
}
.spirit-demo-root .demo-orb__core {
  position: relative;
  width: 50%;
  aspect-ratio: 1;
  border-radius: 50%;
  background:
    radial-gradient(
      circle at 32% 28%,
      rgba(255, 255, 255, 0.55),
      rgba(255, 255, 255, 0.05) 35%,
      transparent 70%
    ),
    linear-gradient(140deg, var(--demo-cyan), var(--demo-violet) 60%, #4f46e5);
  box-shadow:
    0 0 36px -2px color-mix(in oklab, var(--demo-cyan) 50%, transparent),
    0 0 68px -8px color-mix(in oklab, var(--demo-violet) 45%, transparent),
    inset 0 0 28px -6px rgba(255, 255, 255, 0.32);
  animation: demoOrbBreathe var(--demo-dur-breath) ease-in-out infinite;
}
.spirit-demo-root .demo-orb__core::after {
  content: "";
  position: absolute;
  inset: 6%;
  border-radius: 50%;
  background: radial-gradient(
    circle at 70% 80%,
    color-mix(in oklab, var(--demo-violet) 60%, transparent),
    transparent 50%
  );
  mix-blend-mode: screen;
  opacity: 0.7;
}

/* - -  Audio waveform bars (Oracle preview) - -  */
.spirit-demo-root .demo-wave {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 3rem;
  padding-inline: 0.5rem;
}
.spirit-demo-root .demo-wave__bar {
  flex: 1 1 0;
  min-width: 2px;
  border-radius: 2px;
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--demo-cyan-strong) 100%, transparent),
    color-mix(in oklab, var(--demo-cyan-deep) 80%, transparent)
  );
  animation: demoWave 1.4s ease-in-out infinite;
}
.spirit-demo-root .demo-wave__bar:nth-child(1)  { animation-delay: -0.05s; }
.spirit-demo-root .demo-wave__bar:nth-child(2)  { animation-delay: -0.15s; }
.spirit-demo-root .demo-wave__bar:nth-child(3)  { animation-delay: -0.25s; }
.spirit-demo-root .demo-wave__bar:nth-child(4)  { animation-delay: -0.35s; }
.spirit-demo-root .demo-wave__bar:nth-child(5)  { animation-delay: -0.45s; }
.spirit-demo-root .demo-wave__bar:nth-child(6)  { animation-delay: -0.55s; }
.spirit-demo-root .demo-wave__bar:nth-child(7)  { animation-delay: -0.65s; }
.spirit-demo-root .demo-wave__bar:nth-child(8)  { animation-delay: -0.75s; }
.spirit-demo-root .demo-wave__bar:nth-child(9)  { animation-delay: -0.85s; }
.spirit-demo-root .demo-wave__bar:nth-child(10) { animation-delay: -0.95s; }
.spirit-demo-root .demo-wave__bar:nth-child(11) { animation-delay: -1.05s; }
.spirit-demo-root .demo-wave__bar:nth-child(12) { animation-delay: -1.15s; }
.spirit-demo-root .demo-wave__bar:nth-child(13) { animation-delay: -1.25s; }
.spirit-demo-root .demo-wave__bar:nth-child(14) { animation-delay: -1.35s; }
.spirit-demo-root .demo-wave__bar:nth-child(15) { animation-delay: -1.45s; }
.spirit-demo-root .demo-wave__bar:nth-child(16) { animation-delay: -1.55s; }

/* - -  Status pulse dot - -  */
.spirit-demo-root .demo-pulse-dot {
  position: relative;
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--demo-online);
  box-shadow: 0 0 6px color-mix(in oklab, var(--demo-online) 80%, transparent);
}
.spirit-demo-root .demo-pulse-dot::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 1px solid color-mix(in oklab, var(--demo-online) 60%, transparent);
  animation: demoPulseDot 2s ease-out infinite;
}
.spirit-demo-root .demo-pulse-dot--warn {
  background: var(--demo-warn);
  box-shadow: 0 0 6px color-mix(in oklab, var(--demo-warn) 70%, transparent);
}
.spirit-demo-root .demo-pulse-dot--warn::after {
  border-color: color-mix(in oklab, var(--demo-warn) 60%, transparent);
}
.spirit-demo-root .demo-pulse-dot--rose {
  background: var(--demo-quarantine);
  box-shadow: 0 0 6px color-mix(in oklab, var(--demo-quarantine) 70%, transparent);
}
.spirit-demo-root .demo-pulse-dot--rose::after {
  border-color: color-mix(in oklab, var(--demo-quarantine) 60%, transparent);
}

/* - -  Corner caret marks (cinematic instrument feel) - -  */
.spirit-demo-root .demo-corners {
  position: absolute;
  inset: 0.5rem;
  pointer-events: none;
}
.spirit-demo-root .demo-corners::before,
.spirit-demo-root .demo-corners::after {
  content: "";
  position: absolute;
  width: 14px;
  height: 14px;
  border-color: color-mix(in oklab, var(--demo-accent) 60%, transparent);
  border-style: solid;
}
.spirit-demo-root .demo-corners::before {
  top: 0;
  left: 0;
  border-width: 1px 0 0 1px;
}
.spirit-demo-root .demo-corners::after {
  bottom: 0;
  right: 0;
  border-width: 0 1px 1px 0;
}/* ── Spirit Demo · Layout ────────────────────────────────────────────────────
 * > Shell, section grid, mobile dock, side rail, safe-area handling.
 * > Mobile-first. Targets iPhone 375px / Android 360px / tablet / desktop.
 * > All selectors are nested under .spirit-demo-root - no leakage.
 * ────────────────────────────────────────────────────────────────────────── */

.spirit-demo-root {
  position: relative;
  min-height: 100dvh;
  width: 100%;
  background-color: var(--demo-bg);
  color: var(--demo-text);
  overflow-x: hidden;
  /* Reserve space for mobile bottom dock (overridden on lg) */
  padding-bottom: calc(5rem + env(safe-area-inset-bottom, 0px));
  font-feature-settings: "kern" 1, "liga" 1;
}

@media (min-width: 1024px) {
  .spirit-demo-root {
    padding-bottom: env(safe-area-inset-bottom, 0px);
    /* Reserve space for the desktop side rail */
    padding-left: 4.5rem;
  }
}

/* - -  Atmospherics layer - -  */
.spirit-demo-root .demo-atmos {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: var(--demo-z-bg);
}
.spirit-demo-root .demo-atmos__aurora {
  position: absolute;
  inset: -10%;
  z-index: var(--demo-z-aurora);
  background:
    radial-gradient(
      ellipse 60% 45% at 18% 12%,
      color-mix(in oklab, var(--demo-cyan) 18%, transparent),
      transparent 60%
    ),
    radial-gradient(
      ellipse 50% 40% at 86% 30%,
      color-mix(in oklab, var(--demo-violet) 16%, transparent),
      transparent 60%
    ),
    radial-gradient(
      ellipse 70% 55% at 50% 110%,
      color-mix(in oklab, var(--demo-cyan) 12%, transparent),
      transparent 60%
    );
  filter: blur(20px) saturate(120%);
  opacity: 0.85;
}
.spirit-demo-root .demo-atmos__grid {
  position: absolute;
  inset: 0;
  z-index: var(--demo-z-grid);
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: radial-gradient(ellipse 80% 60% at 50% 30%, black 30%, transparent 80%);
  -webkit-mask-image: radial-gradient(ellipse 80% 60% at 50% 30%, black 30%, transparent 80%);
  opacity: 0.6;
}
.spirit-demo-root .demo-atmos__noise {
  position: absolute;
  inset: 0;
  z-index: var(--demo-z-noise);
  opacity: 0.04;
  mix-blend-mode: overlay;
  background-image:
    repeating-radial-gradient(
      circle at 20% 30%,
      rgba(255, 255, 255, 0.6) 0,
      rgba(255, 255, 255, 0.6) 0.5px,
      transparent 1px,
      transparent 4px
    );
}
.spirit-demo-root .demo-atmos__vignette {
  position: absolute;
  inset: 0;
  z-index: var(--demo-z-grid);
  background: radial-gradient(
    ellipse 90% 70% at 50% 50%,
    transparent 50%,
    color-mix(in oklab, var(--demo-bg-deep) 92%, black) 100%
  );
}

/* - -  Shell - -  */
.spirit-demo-root .demo-shell {
  position: relative;
  z-index: var(--demo-z-content);
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: min(1280px, 100%);
  margin: 0 auto;
  padding-inline: clamp(1rem, 4vw, 2rem);
  padding-top: calc(1rem + env(safe-area-inset-top, 0px));
}

/* - -  Section bands - -  */
.spirit-demo-root .demo-section {
  position: relative;
  padding-block: clamp(2.5rem, 7vw, 4.5rem);
  scroll-margin-top: 5rem;
}
.spirit-demo-root .demo-section + .demo-section {
  border-top: 1px solid var(--demo-border);
}

/* - -  Section header (eyebrow + title + lede) - -  */
.spirit-demo-root .demo-section__header {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-width: 56rem;
  margin-bottom: clamp(1.5rem, 3vw, 2.25rem);
}
.spirit-demo-root .demo-section__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-family: var(--font-jetbrains-mono), ui-monospace, monospace;
  font-size: var(--demo-text-eyebrow);
  font-weight: 600;
  letter-spacing: var(--demo-tracking-rail);
  text-transform: uppercase;
  color: color-mix(in oklab, var(--demo-accent-strong) 78%, white);
}
.spirit-demo-root .demo-section__eyebrow::before {
  content: "";
  width: 1.5rem;
  height: 1px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--demo-accent) 70%, transparent),
    transparent
  );
}
.spirit-demo-root .demo-section__title {
  font-size: var(--demo-text-h2);
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.1;
  color: var(--demo-text);
}
.spirit-demo-root .demo-section__lede {
  max-width: 42rem;
  font-size: var(--demo-text-body);
  line-height: 1.6;
  color: var(--demo-text-muted);
}

/* - -  Hero grid - -  */
.spirit-demo-root .demo-hero-grid {
  display: grid;
  gap: 1rem;
  grid-template-columns: 1fr;
}
@media (min-width: 640px) {
  .spirit-demo-root .demo-hero-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.25rem;
  }
}
@media (min-width: 1024px) {
  .spirit-demo-root .demo-hero-grid {
    grid-template-columns: 1.6fr 1fr 1fr;
    gap: 1.25rem;
  }
}

/* - -  Generic 2-up / 3-up / 4-up grids - -  */
.spirit-demo-root .demo-grid-2 {
  display: grid;
  gap: 1rem;
  grid-template-columns: 1fr;
}
@media (min-width: 640px) {
  .spirit-demo-root .demo-grid-2 {
