    .command-open .command-scrim { display: block; }
    .command-open .command-panel { opacity: 1; pointer-events: auto; transform: translate(-50%, 0) scale(1); }
    .command-inner { max-height: 72vh; display: flex; flex-direction: column; border-radius: 30px; overflow: hidden; border: 1px solid color-mix(in oklch, var(--spirit-500) 22%, var(--stroke-1)); box-shadow: var(--shadow-2), 0 0 70px color-mix(in oklch, var(--spirit-500) 30%, transparent); }
    .command-input { display: flex; align-items: center; gap: 12px; padding: 15px 18px; border-bottom: 1px solid var(--stroke-1); }
    .command-input input { flex: 1; min-width: 0; height: 32px; border: 0; outline: 0; background: transparent; color: var(--text-1); font-size: 15px; }
    .suggestions { overflow: auto; padding: 10px; }
    .suggestion { display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 12px; align-items: center; width: 100%; border: 0; border-radius: 14px; padding: 10px 12px; background: transparent; text-align: left; transition: 120ms ease; }
    .suggestion:hover, .suggestion.active { background: linear-gradient(180deg, color-mix(in oklch, var(--spirit-500) 16%, transparent), rgb(255 255 255 / .025)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--spirit-500) 28%, transparent); }
    .suggestion .box { width: 34px; height: 34px; border-radius: 10px; border: 1px solid var(--stroke-2); background: var(--glass-2); display: grid; place-items: center; color: var(--spirit-300); }
    .command-footer { border-top: 1px solid var(--stroke-1); padding: 10px 18px; display: flex; align-items: center; justify-content: space-between; gap: 12px; background: rgb(0 0 0 / .22); flex-wrap: wrap; }
    .hidden { display: none !important; }

    .tweaks-toggle { position: fixed; right: 16px; bottom: 16px; z-index: 55; }
    .tweaks { position: fixed; right: 16px; bottom: 66px; z-index: 56; width: min(320px, calc(100vw - 24px)); display: none; padding: 16px; border-radius: 26px; border: 1px solid color-mix(in oklch, var(--spirit-500) 16%, var(--stroke-1)); box-shadow: var(--shadow-2), 0 0 50px color-mix(in oklch, var(--spirit-500) 18%, transparent); }
    @media (max-width: 880px) { .tweaks { left: 12px; right: 12px; bottom: 12px; width: auto; } .tweaks-toggle { bottom: 12px; right: 12px; } }
    .tweaks.open { display: block; }
    .tweak-row { display: grid; gap: 6px; margin-top: 12px; }
    .tweak-row:first-of-type { margin-top: 0; }
    .tweak-row label { font-size: 10px; color: var(--text-4); letter-spacing: .14em; text-transform: uppercase; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
    input[type="range"] { width: 100%; accent-color: var(--spirit-500); }
    select { width: 100%; background: rgb(255 255 255 / .06); border: 1px solid var(--stroke-2); color: var(--text-1); border-radius: 10px; padding: 8px 10px; }
    .switch-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 10px; }
    .switch { width: 42px; height: 24px; border-radius: 999px; border: 1px solid var(--stroke-2); background: rgb(255 255 255 / .08); padding: 2px; }
    .switch::before { content: ""; display: block; width: 18px; height: 18px; border-radius: 50%; background: var(--text-2); transition: 160ms ease; }
    .switch[aria-checked="true"] { background: color-mix(in oklch, var(--spirit-500) 28%, transparent); }
    .switch[aria-checked="true"]::before { transform: translateX(18px); background: white; }

        /* Mobile-first responsive override */
    .app-shell { position: relative; z-index: 1; display: grid; grid-template-columns: 1fr; min-height: 100vh; padding-top: 60px; }
    .desktop-sidebar { display: none; }
    .mobile-bar { display: flex; }
    main { min-width: 0; padding: 16px; }
    .hero { align-items: stretch; }
    .hero-actions { width: 100%; display: grid; grid-template-columns: 44px 44px minmax(0, 1fr); }
    .dashboard-grid { display: grid; grid-template-columns: 1fr; gap: var(--gap); }
    .span-4, .span-5, .span-7, .span-8, .span-12 { grid-column: 1 / -1; }
    .cluster-grid { grid-template-columns: 1fr; }
    @media (min-width: 700px) {
      .cluster-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
    @media (min-width: 881px) {
      .app-shell { grid-template-columns: 248px minmax(0, 1fr); min-height: 100vh; padding-top: 0; }
      .desktop-sidebar { display: flex; }
      .mobile-bar { display: none; }
      main { padding: clamp(16px, 3vw, 34px); }
      .hero-actions { width: auto; display: flex; }
      .dashboard-grid { grid-template-columns: repeat(12, minmax(0, 1fr)); }
      .cluster-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
    @media (min-width: 1160px) {
      .cluster-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    }

@media (max-width: 1160px) {
      .span-4, .span-5, .span-7, .span-8 { grid-column: span 6; }
      .span-8:first-child { grid-column: span 12; }
    }
    @media (max-width: 880px) {
      .app-shell { grid-template-columns: 1fr; padding-top: 60px; }
      .desktop-sidebar { display: none; }
      .mobile-bar { display: flex; }
      .mobile-scrim { position: fixed; inset: 0; z-index: 70; background: rgb(0 0 0 / .62); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); }
      .mobile-drawer { position: fixed; display: flex; flex-direction: column; z-index: 80; inset: 0 auto 0 0; width: min(340px, 88vw); background: color-mix(in oklch, var(--bg-0) 92%, transparent); border-right: 1px solid var(--stroke-2); border-top-right-radius: 24px; border-bottom-right-radius: 24px; transform: translateX(-104%); transition: transform 220ms cubic-bezier(.2,.8,.2,1); box-shadow: 20px 0 70px rgb(0 0 0 / .5); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); }
      body.drawer-open .mobile-drawer { transform: translateX(0); }
      body.drawer-open .mobile-scrim { display: block; }
      body:not(.drawer-open) .mobile-scrim { display: none; }
      main { padding: 16px; }
      .hero { align-items: stretch; }
      .hero-actions { width: 100%; }
      .hero-actions .btn:last-child { flex: 1; }
      .dashboard-grid { grid-template-columns: 1fr; }
      .span-4, .span-5, .span-7, .span-8, .span-12 { grid-column: 1 / -1; }
      .briefing-row { grid-template-columns: 1fr auto; }
      .briefing-row .tag { grid-column: 1 / -1; width: fit-content; }
      .project-row { grid-template-columns: auto minmax(0, 1fr); }
      .project-row > div:last-child { grid-column: 2; align-items: flex-start !important; margin-top: 4px; }
      .energy-costs { grid-template-columns: 1fr; }
      .command-panel { top: auto; left: 0; right: 0; bottom: 0; width: 100%; padding: 10px 10px 0; transform: translateY(100%); }
      .command-open .command-panel { transform: translateY(0); }
      .command-inner { max-height: 84vh; border-radius: 28px 28px 0 0; }
      .command-footer { align-items: flex-start; }
    }
    @media (max-width: 520px) {
      .card-head { flex-direction: column; }
      .cluster-shell { margin-left: -2px; margin-right: -2px; }
      .grid-auto { grid-template-columns: 1fr; }
      .hero-actions { flex-wrap: wrap; }
      .orb-wrap { height: 190px; }
    }
  </style>
</head>
<body data-density="comfortable" data-quarantine="on" data-grain="on">
  <div class="ambient" aria-hidden="true"></div>

  <header class="mobile-bar">
    <div class="brand" style="height:auto;border:0;padding:0"><div class="logo"></div><div class="brand-title"><strong>Spirit OS</strong><span>Trinity Node</span></div></div>
    <button class="btn icon" id="openDrawer" aria-label="Open navigation">☰</button>
  </header>
  <div class="mobile-scrim" id="drawerScrim"></div>
  <aside class="mobile-drawer" id="mobileDrawer">
    <div class="brand"><div class="logo"></div><div class="brand-title"><strong>Spirit OS</strong><span>Mobile Shell</span></div><button class="btn icon" id="closeDrawer" style="margin-left:auto">×</button></div>
    <nav class="nav" id="mobileNav"></nav>
    <div class="profile"><div class="avatar"><span>S</span></div><div><strong style="font-size:12px">Source</strong><div class="mono" style="font-size:9px;color:var(--text-4);letter-spacing:.14em;text-transform:uppercase">Sovereign · Tier 0</div></div></div>
  </aside>

  <div class="app-shell">
    <aside class="desktop-sidebar">
      <div class="brand"><div class="logo"></div><div class="brand-title"><strong>Spirit OS</strong><span>Trinity Node</span></div></div>
      <nav class="nav" id="desktopNav"></nav>
      <div class="profile"><div class="avatar"><span>S</span></div><div><strong style="font-size:12px">Source</strong><div class="mono" style="font-size:9px;color:var(--text-4);letter-spacing:.14em;text-transform:uppercase">Sovereign · Tier 0</div></div></div>
    </aside>

    <main>
      <section class="hero">
        <div>
          <span class="eyebrow"><span class="dot"></span>Trinity Dashboard · Sovereign</span>
          <h1 class="serif">Good Morning <span style="color:var(--spirit-300)">Source</span></h1>
          <div class="subline"><span class="online">● All nodes nominal</span><span>·</span><span>Local time <span class="mono" id="clock">--:--</span></span><span>·</span><span>Cluster uptime <span class="mono">14d 06h</span></span></div>
        </div>
        <div class="hero-actions">
          <button class="btn ghost icon" aria-label="Notifications">◌</button>
          <button class="btn ghost icon" aria-label="Settings">⚙</button>
          <button class="btn primary" id="openCommand">✦ Command <kbd>⌘K</kbd></button>
        </div>
      </section>

      <section class="glass cluster-shell" aria-label="Cluster status">
        <div class="cluster-head">
          <span class="eyebrow"><span class="dot"></span>Cluster Mesh</span>
          <div class="cluster-meta">
            <span class="cluster-chip mono">4 nodes</span>
            <span class="cluster-chip mono">3 live</span>
            <span class="cluster-chip mono">1 pending</span>
          </div>
        </div>
        <div class="cluster-grid" id="nodes"></div>
      </section>

      <section class="dashboard-grid">
        <article class="glass accent card span-4" id="oracle">
          <div class="card-head"><div><span class="eyebrow"><span class="dot"></span>Spirit · AI Core</span><h2 class="card-title serif" style="font-size:28px">Oracle</h2><p class="tiny muted">Local Llama 3.3 · Q4_K_M · 24GB VRAM</p></div><span class="badge info">Idle</span></div>
          <div class="orb-wrap"><span class="orb-glow"></span><span class="ring one"></span><span class="ring two"></span><button class="orb" id="orbButton" aria-label="Open Oracle command">✦</button></div>
          <div class="wave" id="wave"></div>
          <div style="display:flex;gap:8px;margin-top:16px"><button class="btn primary" style="flex:1" id="openCommand2">Open Command <kbd>⌘K</kbd></button><button class="btn icon">🎙</button></div>
        </article>

        <article class="glass card span-8" id="briefing">
          <div class="card-head"><div><span class="eyebrow"><span class="dot"></span>Intelligence Briefing · 06:00</span><h2 class="card-title">Daily Briefing</h2><p class="tiny muted">SearXNG + GPT-Researcher · demo data clearly labeled</p></div><div style="display:flex;gap:8px;align-items:center"><span class="badge mock">Demo</span><span class="badge live">Synced</span></div></div>
          <div class="briefing-list" id="briefings"></div>
          <div style="display:flex;align-items:center;gap:12px;margin-top:14px"><div style="height:1px;background:var(--stroke-1);flex:1"></div><span class="mono" style="font-size:10px;color:var(--text-4);letter-spacing:.16em;text-transform:uppercase">4 of 12</span><button class="btn ghost">All briefings →</button></div>
        </article>

        <article class="glass card span-7" id="projects">
          <div class="card-head"><div><span class="eyebrow"><span class="dot"></span>Project Hub · Architecture 6</span><h2 class="card-title">Active Repositories</h2><p class="tiny muted">Spirit scans TODOs vs README · mock completion for demo</p></div><span class="badge mock">Demo</span></div>
          <div class="project-list" id="projectsList"></div>
        </article>

        <article class="glass card span-5" id="storage">
          <div class="card-head"><div><span class="eyebrow"><span class="dot"></span>Local Drive Health</span><h2 class="card-title">Storage</h2><p class="tiny muted">SMART telemetry across cluster</p></div><span class="badge mock">Mock</span></div>
          <div class="stack" id="drivesList"></div>
          <div class="notice" style="margin-top:14px"><span>⚠</span><span>Wire <span class="mono" style="color:var(--text-2)">smartctl</span> on Node 2 for live readings. Values remain labeled as mock until connected.</span></div>
        </article>

        <article class="glass card span-8" id="stats">
          <div class="card-head"><div><span class="eyebrow"><span class="dot"></span>Node Vitals</span><h2 class="card-title">System Stats</h2><p class="tiny muted">Polled every 5s · demo layer only</p></div><span class="badge mock">Demo</span></div>
          <div class="grid-auto" id="statsList"></div>
        </article>

        <article class="glass card span-4" id="energy">
          <div class="card-head"><div><span class="eyebrow"><span class="dot"></span>Energy Matrix · Node 5</span><div style="display:flex;align-items:baseline;gap:7px;margin-top:6px"><span class="serif" id="watts" style="font-size:42px;line-height:.9">0</span><span class="mono muted" style="font-size:12px;letter-spacing:.08em">WATTS</span></div></div><div style="text-align:right"><div class="num" style="font-size:15px;color:var(--good);font-weight:800">$0.11<span class="muted" style="font-size:11px;font-weight:400">/kWh</span></div><div class="mono" style="font-size:9px;color:var(--good);letter-spacing:.12em;text-transform:uppercase">Super Off-Peak</div></div></div>
          <div class="energy-costs"><div class="tile"><div class="eyebrow" style="font-size:9px">Hourly</div><div class="num" id="costHr" style="font-size:17px;margin-top:4px">$0.000</div></div><div class="tile"><div class="eyebrow" style="font-size:9px">Daily Est.</div><div class="num" id="costDay" style="font-size:17px;margin-top:4px">$0.00</div></div></div>
          <div class="stack" id="energyList" style="margin-top:14px"></div>
          <div class="notice" style="margin-top:14px"><span>⏱</span><span>Peak window in <span class="mono" style="color:var(--text-1)">6h 14m</span>. Queue heavy compute now.</span></div>
        </article>

        <article class="glass terminal card span-12 quarantine-card" id="quarantine">
          <div class="card-head"><div><span class="eyebrow"><span class="dot"></span>Quarantine · Experimental Modules</span><h2 class="card-title">Toxic Grader</h2><p class="tiny muted">Roast wall kept as brand concept, clearly marked experimental.</p></div><div style="display:flex;gap:8px;align-items:center"><span class="badge info">Quarantine</span><span class="badge mock">Mock</span></div></div>
          <div class="terminal-lines" id="terminalLines"></div>
          <div style="display:flex;gap:8px;margin-top:16px;flex-wrap:wrap"><button class="btn danger">🔥 GRADE ME - IF YOU DARE</button><button class="btn ghost">Tune module</button></div>
        </article>
      </section>

      <footer style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin-top:32px;padding:16px 0;border-top:1px solid var(--stroke-1)">
        <span class="mono" style="font-size:10px;color:var(--text-5);letter-spacing:.16em;text-transform:uppercase">Spirit OS · finished quarantine demo</span>
        <span class="mono" style="font-size:10px;color:var(--text-5)">Standalone HTML · no CDN dependencies · ready to port</span>
      </footer>
    </main>
  </div>

  <div class="command-scrim" id="commandScrim"></div>
  <section class="command-panel" role="dialog" aria-modal="true" aria-label="Spirit command bar">
    <div class="glass command-inner">
      <div class="command-input"><div class="logo" style="width:32px;height:32px;border-radius:10px"></div><input id="commandInput" placeholder="Issue a command to Spirit..." autocomplete="off" /><kbd>ESC</kbd><button class="btn icon ghost" id="closeCommand">×</button></div>
      <div class="suggestions"><div class="eyebrow" style="padding:8px 12px 7px"><span class="dot"></span><span id="suggestionLabel">Quick Actions</span></div><div id="suggestionList"></div></div>
      <div class="command-footer"><div style="display:flex;gap:14px;flex-wrap:wrap"><span class="mono tiny muted"><kbd>↑↓</kbd> navigate</span><span class="mono tiny muted"><kbd>↵</kbd> run</span><span class="mono tiny muted"><kbd>⌘K</kbd> toggle</span></div><span class="badge live">Online</span></div>
    </div>
  </section>

  <button class="btn tweaks-toggle" id="tweaksToggle">⚙ Tune demo</button>
  <aside class="glass tweaks" id="tweaksPanel" aria-label="Demo tweaks">
    <div style="display:flex;justify-content:space-between;align-items:center;gap:12px"><span class="eyebrow"><span class="dot"></span>Tweaks</span><button class="btn icon ghost" id="closeTweaks">×</button></div>
    <div class="tweak-row"><label for="hueRange">Accent Hue <span id="hueValue" class="num">300</span></label><input id="hueRange" type="range" min="0" max="360" step="5" value="300" /></div>
    <div class="tweak-row"><label for="densitySelect">Density</label><select id="densitySelect"><option value="compact">Compact</option><option value="comfortable" selected>Comfortable</option><option value="spacious">Spacious</option></select></div>
    <div class="switch-row"><label class="eyebrow" style="font-size:10px">Show Quarantine</label><button class="switch" id="quarantineSwitch" role="switch" aria-checked="true"></button></div>
    <div class="switch-row"><label class="eyebrow" style="font-size:10px">Grain Overlay</label><button class="switch" id="grainSwitch" role="switch" aria-checked="true"></button></div>
  </aside>

  <script>
    const $ = (sel, root = document) => root.querySelector(sel);
    const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

    const navItems = [
      ["⌘", "Command", "#", "01"], ["✦", "Oracle", "#oracle", "02"], ["▣", "Projects", "#projects", "03"],
      ["◫", "Storage", "#storage", "04"], ["⚡", "Energy", "#energy", "05"], ["⚗", "Quarantine", "#quarantine", "06"],
    ];
    function renderNav(target) {
      target.innerHTML = '<span class="nav-label"><span class="dot"></span>Modules</span>' + navItems.map((n, i) => `
        <a class="nav-item ${i === 0 ? 'active' : ''}" href="${n[2]}" data-nav>
          <span class="nav-icon">${n[0]}</span><span>${n[1]}</span><span class="nav-code mono">${n[3]}</span>
        </a>`).join('');
    }
    renderNav($('#desktopNav')); renderNav($('#mobileNav'));
    $$('[data-nav]').forEach(link => link.addEventListener('click', e => {
      $$('[data-nav]').forEach(x => x.classList.remove('active'));
      e.currentTarget.classList.add('active');
      document.body.classList.remove('drawer-open');
      document.body.style.position = '';
      const href = e.currentTarget.getAttribute('href');
      if (href && href !== '#') setTimeout(() => $(href)?.scrollIntoView({behavior:'smooth', block:'start'}), 0);
      e.preventDefault();
    }));

    const nodes = [
      ["spiritdesktop", "Ryzen AM5 · 12% CPU", "live"], ["spirit (Dell)", "i7-6700 · 34% CPU", "live"],
      ["Ghost Node", "Pi 3 · 22% CPU", "live"], ["Tesla P40", "Awaiting PSU upgrade", "pending"]
    ];
    $('#nodes').innerHTML = nodes.map(n => { const pending = n[2] === 'pending'; const stat = pending ? 'Standby' : 'Nominal'; return `<div class="cluster-node"><span class="state-dot ${pending ? 'pending' : ''}"></span><div class="cluster-node-copy"><strong>${n[0]}</strong><span>${n[1]}</span></div><div class="cluster-node-stat"><strong>${stat}</strong><span>${pending ? 'queued' : 'live'}</span></div></div>`; }).join('');

    $('#wave').innerHTML = Array.from({length: 30}, (_, i) => `<span class="bar" style="--i:${i};--h:${5 + ((i * 47 + 9) % 18)}"></span>`).join('');

    const briefings = [
      ["Local LLM", "Llama 3.3 Q4_K_M quant benchmarks on consumer DDR5 - context window throughput.", "06:02", "arxiv"],
      ["Homelab", "PCIe x1 riser bottleneck: TTFT degradation on 24GB VRAM models vs x16 ribbon.", "06:04", "level1tech"],
      ["Privacy", "CCPA Q3 enforcement: brokers ignoring opt-outs face record seven-figure penalties.", "06:06", "eff"],
      ["Energy", "SoCal ToU shift: super off-peak window narrows to 11 PM–5 AM next billing cycle.", "06:08", "sce"]
    ];
    $('#briefings').innerHTML = briefings.map((b, i) => `<div class="tile briefing-row"><span class="tag">${b[0]}</span><div><p style="margin:0;font-size:13px;color:var(--text-2);line-height:1.45">${b[1]}</p><div style="display:flex;gap:10px;margin-top:6px;align-items:center"><span class="mono" style="font-size:9.5px;color:var(--text-5)">${b[2]}</span><span style="width:2px;height:2px;border-radius:99px;background:var(--text-5)"></span><span class="mono" style="font-size:9.5px;color:var(--text-5)">src · ${b[3]}</span></div></div><span class="num" style="font-size:10px;color:var(--text-5)">0${i+1}</span></div>`).join('');

    const projects = [
      ["spirit-os-dashboard", "main", 38, 14, "2h", "active"], ["toxic-grader-agent", "feat/langfuse", 61, 6, "5h", "active"],
      ["cinema-engine-config", "main", 82, 2, "1d", "idle"], ["ghost-node-setup", "dns-pihole", 20, 9, "3d", "idle"]
    ];
    $('#projectsList').innerHTML = projects.map(p => {
      const tone = p[2] >= 70 ? 'good' : p[2] < 40 ? 'warn' : '';
      return `<div class="tile project-row"><span class="state-dot ${p[5] !== 'active' ? 'pending' : ''}" style="width:8px;height:8px"></span><div style="min-width:0"><div style="display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;margin-bottom:7px"><span class="mono" style="font-size:12px;color:var(--text-1)">${p[0]}</span><span class="mono" style="font-size:9.5px;color:var(--text-4)">⑂ ${p[1]}</span></div><div style="display:flex;align-items:center;gap:10px"><div class="progress" style="flex:1"><div class="fill ${tone}" style="--pct:${p[2]}%"></div></div><span class="num" style="font-size:10.5px;color:var(--text-3);width:34px;text-align:right">${p[2]}%</span></div></div><div style="display:flex;flex-direction:column;align-items:flex-end;gap:2px"><span class="mono" style="font-size:9.5px;color:var(--text-4)">${p[3]} TODO</span><span class="mono" style="font-size:9.5px;color:var(--text-5)">${p[4]} ago</span></div></div>`;
    }).join('');

    const driveGroups = [
      ["spiritdesktop · Node 1", "mock", [["OS · Samsung 980", "SSD", 250, 147, 38, "Healthy"], ["Media Vault", "HDD", 1000, 412, 34, "Healthy"], ["Archive", "HDD", 2000, 880, 36, "Healthy"]]],
      ["spirit (Dell) · Node 2", "pending", [["Dell SSD 512GB", "SSD", 512, 198, 41, "Unknown"]]]
    ];
    const fmt = n => n >= 1000 ? `${(n/1000).toFixed(1)} TB` : `${n} GB`;
