                  try { $_.MediaType.ToString() } catch {}
                } | Where-Object { $_ -and $_ -ne 'Unspecified' } | Select-Object -Unique)
                if ($poolMedia.Count -eq 1) { $media = $poolMedia[0] }
              } catch {}
            }
            if (-not $health) {
