            if ($pd) {
              if (-not $bus) { $bus = $pd.BusType.ToString() }
              if (-not $media -or $media -eq 'Unspecified') { $media = $pd.MediaType.ToString() }
              if (-not $health) { try { $health = $pd.HealthStatus.ToString() } catch {} }
