// ── ResearchPlanPanel - plan gate before /api/spirit research (Prompt 10C-D) ─────
// > Sits above the composer, not under sticky chrome. Internal scroll + sticky actions.

import { Plus, Play, Trash2, X } from "lucide-react";
import { memo, useCallback, useState } from "react";

import type { ResearchPlan, ResearchPlanStep } from "@/lib/spirit/research-plan";
import {
  addResearchPlanStep,
  editResearchPlanStep,
  removeResearchPlanStep,
} from "@/lib/spirit/research-plan";
import { cn } from "@/lib/cn";

export type ResearchPlanPanelProps = {
  open: boolean;
  plan: ResearchPlan | null;
  onClose: () => void;
  onPlanChange: (next: ResearchPlan) => void;
  onStartResearch: (plan: ResearchPlan) => void;
  variant?: "inline" | "sheet";
  /** Trinity /chat liquid glass (Language C). */
  trinityLiquid?: boolean;
};

export const ResearchPlanPanel = memo(function ResearchPlanPanel({
  open,
  plan,
  onClose,
  onPlanChange,
  onStartResearch,
  variant = "inline",
  trinityLiquid = false,
}: ResearchPlanPanelProps) {
  const [newLabel, setNewLabel] = useState("");

  const updateStep = useCallback(
    (id: string, patch: Partial<Pick<ResearchPlanStep, "label" | "detail" | "searchQuery">>) => {
      if (!plan) return;
      onPlanChange(editResearchPlanStep(plan, id, patch));
    },
    [plan, onPlanChange],
  );

  const removeStep = useCallback(
    (id: string) => {
      if (!plan) return;
      onPlanChange(removeResearchPlanStep(plan, id));
    },
    [plan, onPlanChange],
  );

  const addStep = useCallback(() => {
    if (!plan || !newLabel.trim()) return;
    onPlanChange(addResearchPlanStep(plan, newLabel.trim()));
    setNewLabel("");
  }, [plan, newLabel, onPlanChange]);

  if (!open || !plan) return null;

  const sheet = variant === "sheet";

  return (
    <div
      data-testid="research-plan-panel"
      data-trinity-liquid={trinityLiquid ? "research-panel" : undefined}
      className={cn(
        "relative z-[42] flex max-h-[min(280px,45dvh)] min-h-0 shrink-0 flex-col",
        !trinityLiquid &&
          "border-b border-[color:color-mix(in_oklab,var(--spirit-border)_55%,transparent)] bg-black/40 shadow-[inset_0_-1px_0_rgba(255,255,255,0.03)]",
        trinityLiquid &&
          "spirit-trinity-panel-glass border-transparent bg-transparent shadow-none",
        sheet &&
          cn(
            "fixed inset-x-0 bottom-0 z-[120] max-h-[70dvh] rounded-t-xl",
            !trinityLiquid && "border-x border-t",
            trinityLiquid && "border border-transparent",
          ),
      )}
    >
      <div className="mx-auto flex min-h-0 w-full max-w-3xl flex-1 flex-col px-2 py-2 sm:px-3">
        <div
          className={cn(
            "spirit-trinity-research-head flex shrink-0 items-start justify-between gap-2 border-b border-white/[0.06] pb-2",
          )}
        >
          <div>
            <p className="font-mono text-[10px] font-semibold uppercase tracking-[0.18em] text-chalk/45">
              Research plan
            </p>
            <p className="mt-0.5 font-mono text-[11px] text-chalk/75">
              Edit the checklist, then <span className="text-[color:var(--spirit-accent-strong)]">Start research</span>{" "}
              - nothing hits /api/spirit until you do.
            </p>
            <p
              data-testid="research-plan-no-cot"
              className="mt-1 font-mono text-[9px] text-chalk/40"
            >
              No private chain-of-thought - editable checklist only.
            </p>
          </div>
          <button
            type="button"
            aria-label="Close research plan"
            onClick={onClose}
            className={cn(
              "inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-chalk/60 hover:bg-white/[0.06]",
              !trinityLiquid && "border border-[color:var(--spirit-border)]/70",
              trinityLiquid && "spirit-trinity-glass-button border-transparent bg-transparent",
            )}
          >
            <X className="h-4 w-4" aria-hidden />
          </button>
        </div>

        <div className="scrollbar-hide min-h-0 flex-1 overflow-y-auto overscroll-y-contain py-2">
          <p className="font-mono text-[10px] font-semibold text-[color:var(--spirit-accent-strong)]">{plan.title}</p>
          <ul className="mt-2 space-y-1.5">
            {plan.steps.map((s) => (
              <li
                key={s.id}
                className={cn(
                  "spirit-trinity-research-step rounded-md p-2",
                  !trinityLiquid &&
                    "border border-[color:color-mix(in_oklab,var(--spirit-border)_45%,transparent)] bg-white/[0.03]",
                  trinityLiquid && "border-transparent bg-transparent",
                )}
              >
                <input
                  value={s.label}
                  onChange={(e) => updateStep(s.id, { label: e.target.value })}
                  className="w-full bg-transparent font-mono text-[11px] text-chalk outline-none"
                  aria-label="Step label"
                />
                <textarea
                  value={s.detail ?? ""}
                  onChange={(e) => updateStep(s.id, { detail: e.target.value })}
                  placeholder="Optional detail"
                  rows={2}
                  className="mt-1 w-full resize-none bg-black/25 px-1.5 py-1 font-mono text-[10px] text-chalk/80 outline-none"
                />
                <div className="mt-1 flex justify-end">
                  <button
                    type="button"
                    onClick={() => removeStep(s.id)}
                    className="inline-flex items-center gap-1 font-mono text-[9px] text-rose-200/90"
                  >
                    <Trash2 className="h-3 w-3" aria-hidden />
                    Remove
                  </button>
                </div>
              </li>
            ))}
          </ul>
          <div className="mt-2 flex flex-wrap items-end gap-2">
            <input
              value={newLabel}
              onChange={(e) => setNewLabel(e.target.value)}
              placeholder="New step label"
              className={cn(
                "spirit-trinity-glass-input min-w-[8rem] flex-1 rounded-md px-2 py-1 font-mono text-[10px] text-chalk",
                !trinityLiquid && "border border-[color:var(--spirit-border)] bg-black/30",
                trinityLiquid && "border-transparent bg-transparent",
              )}
            />
            <button
              type="button"
              onClick={addStep}
              className={cn(
                "spirit-trinity-glass-button inline-flex items-center gap-1 rounded-md px-2 py-1 font-mono text-[10px] text-chalk/80",
                !trinityLiquid && "border border-[color:var(--spirit-border)]",
                trinityLiquid && "border-transparent bg-transparent",
              )}
            >
              <Plus className="h-3.5 w-3.5" aria-hidden />
              Add step
            </button>
          </div>
        </div>

        <div
          className={cn(
            "spirit-trinity-research-footer flex shrink-0 flex-wrap gap-2 border-t border-white/[0.06] py-2 pt-2",
            !trinityLiquid && "bg-[color:color-mix(in_oklab,var(--spirit-bg)_92%,black)]",
          )}
        >
          <button
            type="button"
            data-testid="research-plan-start"
            onClick={() => onStartResearch(plan)}
            className="inline-flex items-center gap-1.5 rounded-full border border-[color:color-mix(in_oklab,var(--spirit-accent)_45%,transparent)] bg-[color:color-mix(in_oklab,var(--spirit-accent)_14%,transparent)] px-3 py-1.5 font-mono text-[10px] font-semibold uppercase tracking-wide text-[color:var(--spirit-accent-strong)]"
          >
            <Play className="h-3.5 w-3.5" aria-hidden />
            Start research
          </button>
          <button
            type="button"
            data-testid="research-plan-cancel"
            onClick={onClose}
            className={cn(
              "rounded-full px-3 py-1.5 font-mono text-[10px]",
              trinityLiquid
                ? "spirit-trinity-glass-button border border-transparent text-chalk/72"
                : "border border-[color:var(--spirit-border)] text-chalk/65",
            )}
          >
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
});"use client";

// ── SortableChatThreadItem - dnd-kit; drawer can use handle-only activator (9F) ──
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { DraggableAttributes, DraggableSyntheticListeners } from "@dnd-kit/core";
import { memo, type CSSProperties, type ReactNode } from "react";

import { THREAD_DND_PREFIX } from "@/lib/chat-sidebar-dnd";

/** Tight sidebar: long transitions read as laggy index shifts. */
const SORTABLE_LAYOUT_EASING = "cubic-bezier(0.2, 0, 0, 1)";
const SORTABLE_LAYOUT_MS = 115;

export type DragActivatorProps = DraggableAttributes & DraggableSyntheticListeners;

export type SortableChatThreadItemProps = {
  threadId: string;
  disabled?: boolean;
  /** Mobile drawer: put drag listeners on handle only so list scrolls normally. */
  useDragHandle?: boolean;
  children: (p: {
    dragActivatorProps: DragActivatorProps;
    dragHandleProps?: DragActivatorProps;
    /** Same node as `listeners` — required for handle / detached activator patterns (dnd-kit PR #748). */
    setDragActivatorRef: (element: HTMLElement | null) => void;
    isDragging: boolean;
  }) => ReactNode;
};

export const SortableChatThreadItem = memo(function SortableChatThreadItem({
  threadId,
  disabled = false,
  useDragHandle = false,
  children,
}: SortableChatThreadItemProps) {
  const id = `${THREAD_DND_PREFIX}${threadId}`;
  const {
    attributes,
    listeners,
    setNodeRef,
    setActivatorNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id,
    disabled,
    // Live layout transitions while `over` thrashes = droppableRects dance under the pointer.
    // Runtime: debug log still flipped 3228658b ↔ 51bd47ce after vertical-midpoint pick (eafb6b L217–228).
    animateLayoutChanges: () => false,
    transition: {
      duration: SORTABLE_LAYOUT_MS,
      easing: SORTABLE_LAYOUT_EASING,
    },
  });

  const style: CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition: transition ?? undefined,
    opacity: isDragging ? 0.5 : 1,
    // Invisible source row still hit-tests by default → blocks pointerWithin on targets below; kills snap/drop.
    pointerEvents: isDragging ? "none" : undefined,
    willChange: transform ? "transform" : undefined,
  };

  // ── attributes on the sortable node, listeners ONLY on the activator (bubble / row / grip).
  //    Merging both onto the title row used to park tabIndex on inner controls and eat first clicks.
  const dragListenersOnly = listeners as unknown as DragActivatorProps;

  return (
    <div
      ref={setNodeRef}
      style={style}
      className="min-w-0"
      {...attributes}
      // dnd-kit defaults attributes.role="button" + tabIndex=0 on the draggable node — fine for a
      // single-handle chip, lethal next to real <button> titles (first click focuses this div).
      role="group"
      tabIndex={-1}
    >
      {useDragHandle
        ? children({
            dragActivatorProps: {} as DragActivatorProps,
            dragHandleProps: dragListenersOnly,
            setDragActivatorRef: setActivatorNodeRef,
            isDragging,
          })
        : children({
            dragActivatorProps: dragListenersOnly,
            dragHandleProps: undefined,
            setDragActivatorRef: setActivatorNodeRef,
            isDragging,
          })}
    </div>
  );
});"use client";

// ── SpiritActivityPanel - high-level signals only (no chain-of-thought) ─────────
import { Activity, X } from "lucide-react";
import { memo } from "react";

import type { SpiritActivityEvent } from "@/lib/spirit/spirit-activity-events";
import { cn } from "@/lib/cn";

export type SpiritActivityPanelProps = {
  open: boolean;
  onClose: () => void;
  /** Mobile = bottom sheet */
  variant: "popover" | "sheet";
  /** Optional extra classes on the anchored panel surface */
  anchorClassName?: string;
  modeLabel: string;
  runtimeLabel: string;
  voiceLabel: string;
  searchLabel: string;
  memoryLabel: string;
  researchNote: string;
  /** Optional lines for /api/spirit web search diagnostics (no secrets). */
  webSearchDiagnosticLines?: string[];
  events: SpiritActivityEvent[];
};

function kindLabel(k: SpiritActivityEvent["kind"]): string {
  switch (k) {
    case "message_submitted":
      return "msg";
    case "assistant_finished":
      return "done";
    case "mode_changed":
      return "mode";
    case "voice_played":
      return "tts";
    case "voice_error":
      return "err";
    case "workflow_step":
      return "flow";
    case "copy_feedback":
      return "cpy";
    case "workspace_list":
      return "list";
    case "workspace_read":
      return "read";
    case "workspace_tail":
      return "tail";
    case "file_edit_proposed":
      return "edit";
    case "file_edit_applied":
      return "apply";
    case "dev_command_started":
    case "dev_command_completed":
    case "dev_command_failed":
      return "cmd";
    case "tool_blocked":
      return "block";
    case "tool_unavailable":
      return "off";
    default:
      return "evt";
  }
}

export const SpiritActivityPanel = memo(function SpiritActivityPanel({
  open,
  onClose,
  variant,
  modeLabel,
  runtimeLabel,
  voiceLabel,
  searchLabel,
  memoryLabel,
  researchNote,
  webSearchDiagnosticLines,
  events,
  anchorClassName = "",
}: SpiritActivityPanelProps) {
  if (!open) return null;

  const sheet = variant === "sheet";

  return (
    <>
      <button
        type="button"
        aria-label="Close activity panel"
        className={cn("fixed inset-0 z-[140] bg-black/55 backdrop-blur-[2px]", !sheet && "lg:bg-black/40")}
        onClick={onClose}
      />
      <div
        className={cn(
          "fixed z-[150] flex max-h-[min(520px,82dvh)] w-[min(100vw-1.5rem,22rem)] flex-col overflow-hidden rounded-xl border border-[color:var(--spirit-border)] bg-[color:color-mix(in_oklab,var(--spirit-bg)_94%,black)] shadow-[0_24px_80px_-24px_rgba(0,0,0,0.75)]",
          sheet
            ? "inset-x-0 bottom-0 mx-auto max-h-[70dvh] w-full max-w-lg rounded-b-none rounded-t-2xl border-b-0 pb-[env(safe-area-inset-bottom,0px)]"
            : "right-3 top-[3.25rem] max-lg:right-2 max-lg:top-[6.5rem]",
          anchorClassName,
        )}
        role="dialog"
        aria-modal="true"
        aria-labelledby="spirit-activity-heading"
      >
        <div className="flex items-center justify-between gap-2 border-b border-[color:var(--spirit-border)] px-3 py-2">
          <div className="flex min-w-0 items-center gap-2">
            <Activity className="h-4 w-4 shrink-0 text-[color:var(--spirit-accent-strong)]" aria-hidden />
            <h2 id="spirit-activity-heading" className="truncate font-mono text-[11px] font-semibold uppercase tracking-wider text-chalk">
              Activity
            </h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-transparent text-chalk/60 transition hover:bg-white/[0.06] hover:text-chalk"
            aria-label="Close"
          >
            <X className="h-4 w-4" aria-hidden />
          </button>
        </div>
        <div className="scrollbar-hide min-h-0 flex-1 space-y-2 overflow-y-auto px-3 py-2">
          <ul className="space-y-1.5 font-mono text-[10px] leading-relaxed text-chalk/75">
            <li>
              <span className="text-chalk/45">Mode · </span>
              {modeLabel}
            </li>
            <li>
              <span className="text-chalk/45">Runtime · </span>
              {runtimeLabel}
            </li>
            <li>
              <span className="text-chalk/45">Voice · </span>
              {voiceLabel}
            </li>
            <li>
              <span className="text-chalk/45">Search · </span>
              {searchLabel}
            </li>
            <li>
              <span className="text-chalk/45">Memory · </span>
              {memoryLabel}
            </li>
            <li>
              <span className="text-chalk/45">Research tools · </span>
              {researchNote}
            </li>
          </ul>
          {webSearchDiagnosticLines && webSearchDiagnosticLines.length > 0 ? (
            <div
              data-testid="spirit-web-search-diagnostics"
              className="rounded-lg border border-[color:color-mix(in_oklab,var(--spirit-border)_40%,transparent)] bg-black/20 px-2 py-1.5"
            >
              <p className="font-mono text-[9px] font-semibold uppercase tracking-wider text-chalk/40">
                Web search diagnostics
              </p>
              <ul className="mt-1 space-y-0.5 font-mono text-[10px] leading-relaxed text-chalk/70">
                {webSearchDiagnosticLines.map((line) => (
                  <li key={line}>{line}</li>
                ))}
              </ul>
            </div>
          ) : null}
          <div className="border-t border-[color:color-mix(in_oklab,var(--spirit-border)_55%,transparent)] pt-2">
            <p className="font-mono text-[9px] font-semibold uppercase tracking-[0.18em] text-chalk/40">
              Recent events
            </p>
            {events.length === 0 ? (
              <p className="mt-1 font-mono text-[10px] text-chalk/45">No events yet this session.</p>
            ) : (
              <ol className="mt-1 space-y-1">
                {events
                  .slice()
                  .reverse()
                  .map((e) => (
                    <li
                      key={e.id}
                      className="flex gap-2 font-mono text-[10px] text-chalk/70"
                    >
                      <span className="shrink-0 text-chalk/35">{kindLabel(e.kind)}</span>
                      <span className="min-w-0 flex-1 break-words">{e.label}</span>
                    </li>
                  ))}
              </ol>
            )}
          </div>
        </div>
      </div>
    </>
  );
});"use client";

// ── SpiritWorkflowVisualizer - route + web proof rail (no chain-of-thought cosplay) ─
// > Extracted so SpiritChat stops being a 2k-line monolith. Still one product surface.

import { X } from "lucide-react";
import { memo, useMemo } from "react";

import { cn } from "@/lib/cn";

export type SpiritSearchStatusUi = "used" | "skipped" | "failed" | "disabled" | "none";

export type SpiritWorkflowVisualizerProps = {
  visible: boolean;
  /** Idle one-liner instead of the full stepper */
  compact?: boolean;
  completedSummary?: string;
  onExpand?: () => void;
  busy: boolean;
  lane?: string;
  confidence?: string;
  provider?: string;
  /** From x-spirit-search-status (normalized); preferred over raw web header. */
  searchStatus?: SpiritSearchStatusUi;
  searchKind?: "researcher" | "teacher" | "none";
  searchQuery?: string;
  searchElapsedMs?: number;
  skipReason?: string;
  searchUsed?: boolean;
  sourceCount?: number;
  sources?: Array<{
    title?: string;
    url?: string;
    snippet?: string;
  }>;
  steps: Array<{
    id: string;
    label: string;
    detail?: string;
    status: "pending" | "active" | "done" | "error";
  }>;
  onDismiss?: () => void;
};

function hostFromUrl(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return "";
  }
}

export const SpiritWorkflowVisualizer = memo(function SpiritWorkflowVisualizer({
  visible,
  compact = false,
  completedSummary,
  onExpand,
  busy,
  lane,
  confidence,
  provider,
  searchStatus = "none",
  searchKind = "none",
  searchQuery,
  searchElapsedMs,
  skipReason,
  searchUsed,
  sourceCount,
  sources,
  steps,
  onDismiss,
}: SpiritWorkflowVisualizerProps) {
  const activeLabel = useMemo(() => {
    const a = steps.find((s) => s.status === "active");
    return a?.label ?? steps.find((s) => s.status === "pending")?.label;
  }, [steps]);

  if (!visible) return null;

  if (compact && !busy) {
    return (
      <section
        data-testid="spirit-workflow-visualizer-compact"
        aria-busy={busy}
        className={cn(
          "relative z-20 shrink-0 border-b border-[color:color-mix(in_oklab,var(--spirit-border)_55%,transparent)]",
          "bg-[color:color-mix(in_oklab,var(--spirit-bg)_92%,black)] px-2 py-1.5 sm:px-3",
        )}
      >
        <div className="mx-auto flex max-w-3xl items-center justify-between gap-2">
          <p
            data-testid="spirit-workflow-compact-summary"
            className="min-w-0 font-mono text-[10px] text-chalk/70 sm:text-[11px]"
          >
            {completedSummary ?? "Local answer complete"}
          </p>
          {onExpand ? (
            <button
              type="button"
              data-testid="spirit-workflow-expand"
              onClick={onExpand}
              className="shrink-0 rounded-md border border-[color:var(--spirit-border)]/70 px-2 py-0.5 font-mono text-[9px] uppercase tracking-wide text-chalk/60 hover:bg-white/[0.06]"
            >
              Expand
            </button>
          ) : null}
        </div>
      </section>
    );
  }

  const routeLine =
    lane === "local-web-search" && searchKind === "teacher"
      ? "Teacher web aids"
      : lane === "local-web-search"
        ? "Local-first web search"
      : lane === "openai-web-search"
        ? "Web search"
        : lane === "research-plan"
          ? "Research plan"
          : lane === "local-chat"
            ? "Local chat"
            : lane ?? "Local chat";

  const searchProofLine = (() => {
    const prov = provider ? ` · Provider: ${provider}` : "";
    const q = searchQuery?.trim() ? ` · Query: ${searchQuery.trim().slice(0, 140)}` : "";
    const t =
      typeof searchElapsedMs === "number" && Number.isFinite(searchElapsedMs)
        ? ` · Time: ${(searchElapsedMs / 1000).toFixed(1)}s`
        : "";
    const n = typeof sourceCount === "number" ? ` · Sources: ${sourceCount}` : "";
    if (searchStatus === "used") return `Search: used${prov}${n}${q}${t}`;
    if (searchStatus === "skipped") return `Search: skipped${skipReason ? ` (${skipReason})` : ""}${q}`;
    if (searchStatus === "disabled") return `Search: skipped (disabled)${q}`;
    if (searchStatus === "failed") {
      const human =
        skipReason === "missing_openai_key"
          ? "missing API key"
          : skipReason
            ? skipReason.replace(/_/g, " ")
            : "provider error";
      return `Search: failed - ${human}${prov}${q}${t}`;
    }
    if (searchUsed) return `Search: used${prov}${n}${q}${t}`;
    return null;
  })();

  return (
    <section
      data-testid="spirit-workflow-visualizer"
      aria-busy={busy}
      className={cn(
        "relative z-20 max-h-[min(220px,38dvh)] overflow-y-auto overscroll-y-contain border-b border-[color:color-mix(in_oklab,var(--spirit-border)_55%,transparent)]",
        "bg-[color:color-mix(in_oklab,var(--spirit-bg)_92%,black)] px-2 py-2 shadow-[inset_0_-1px_0_rgba(255,255,255,0.03)] sm:px-3 sm:py-2.5",
        "max-lg:text-[11px]",
      )}
    >
      <div className="mx-auto flex max-w-3xl flex-col gap-1.5">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <p className="font-mono text-[10px] font-semibold uppercase tracking-[0.2em] text-chalk/50">
              {busy ? "Spirit is working" : "Spirit status"}
            </p>
            <p
              data-testid="spirit-workflow-route-line"
              className="mt-0.5 font-mono text-[11px] text-[color:var(--spirit-accent-strong)]/95 sm:text-xs"
            >
              Route: {routeLine}
              {confidence ? (
                <span className="text-chalk/45"> · confidence {confidence}</span>
              ) : null}
            </p>
            {busy && activeLabel ? (
              <p className="mt-0.5 font-mono text-[10px] text-chalk/70 sm:text-[11px]">{activeLabel}</p>
            ) : null}
            {searchProofLine ? (
              <p
                data-testid="spirit-workflow-search-proof"
                className="mt-0.5 font-mono text-[10px] text-chalk/65 sm:text-[11px]"
              >
                {searchProofLine}
              </p>
            ) : null}
            <p
              data-testid="spirit-workflow-no-cot"
              className="mt-1 font-mono text-[9px] leading-snug text-chalk/40 sm:text-[10px]"
            >
              No private chain-of-thought. High-level status only.
            </p>
          </div>
          {onDismiss ? (
            <button
              type="button"
              aria-label="Dismiss workflow panel"
              data-testid="spirit-workflow-dismiss"
              onClick={onDismiss}
              className="inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-md border border-[color:var(--spirit-border)]/70 text-chalk/55 hover:bg-white/[0.06] hover:text-chalk"
            >
              <X className="h-3.5 w-3.5" aria-hidden />
            </button>
          ) : null}
        </div>
        <ol className="sr-only" aria-hidden>
          {steps.map((s) => (
            <li key={s.id}>
              {s.label} {s.status}
            </li>
          ))}
        </ol>
        {sources && sources.length > 0 ? (
          <ul
            data-testid="spirit-workflow-source-cards"
            className="mt-1 grid gap-1.5 sm:grid-cols-2"
          >
            {sources.map((s, i) => {
              const url = s.url?.trim();
              const title = (s.title?.trim() || url || "Source").slice(0, 200);
              const domain = url ? hostFromUrl(url) : "";
              const sn = s.snippet?.trim().slice(0, 140);
              return (
                <li key={`${url ?? title}-${i}`}>
                  {url ? (
                    <a
                      href={url}
                      target="_blank"
                      rel="noreferrer"
                      className="block rounded-lg border border-[color:color-mix(in_oklab,var(--spirit-border)_50%,transparent)] bg-black/25 px-2 py-1.5 transition hover:border-[color:color-mix(in_oklab,var(--spirit-accent)_40%,transparent)]"
                    >
                      <p className="font-mono text-[10px] font-semibold text-chalk">{title}</p>
                      {domain ? (
                        <p className="mt-0.5 font-mono text-[9px] text-[color:var(--spirit-accent-strong)]/85">
                          {domain}
                        </p>
                      ) : null}
                      {sn ? <p className="mt-1 font-mono text-[9px] leading-snug text-chalk/55">{sn}</p> : null}
                    </a>
                  ) : (
                    <div className="rounded-lg border border-white/[0.06] bg-black/20 px-2 py-1.5 font-mono text-[9px] text-chalk/50">
                      {title}
                      <span className="mt-1 block text-chalk/40">No URL - not clickable</span>
                    </div>
                  )}
                </li>
              );
            })}
          </ul>
        ) : null}
      </div>
    </section>
  );
});"use client";

// ── VoiceSettingsPanel - Voice picker + timing (Prompt 9I mobile-first polish) ───
import { ChevronDown, ChevronRight } from "lucide-react";
import { memo, useState } from "react";

import type { UseTtsState } from "@/hooks/useTTS";
import { TTS_VOICE_SPEED_PRESETS } from "@/lib/tts/voice-speed";
import { cn } from "@/lib/cn";
import { formatTtsFriendlySummaryLines, formatTtsLastVoiceLine } from "@/lib/tts/format-tts-latency";

function voiceCatalogSourceLine(
  source: string | undefined,
  allowlistMode: string | undefined,
): string {
  if (!source && !allowlistMode) return "Source: -";
  if (source === "elevenlabs-api") return "Source: ElevenLabs catalog";
  if (source === "env-name-allowlist") {
    return "Source: allowlist (names resolved by catalog)";
  }
  if (source === "env-allowlist") return "Source: allowlist (voice IDs from env)";
  if (source === "mixed") return "Source: allowlist + catalog metadata";
  if (source) return `Source: ${source}`;
  return `Source: - · mode: ${allowlistMode ?? "-"}`;
}

const START_OPTS = [0, 250, 500, 1000] as const;
const GAP_OPTS = [0, 150, 300, 600] as const;

export type VoiceSettingsPanelProps = {
  state: UseTtsState;
  onEnableAudio: () => void | Promise<void | boolean>;
  onStartDelayChange: (ms: number) => void;
  onSentenceGapChange: (ms: number) => void;
  onVoiceSpeedChange?: (speed: number) => void;
  onToggleAutoSpeak?: () => void;
  /** ElevenLabs voice_id from catalog select. */
  onElevenLabsVoiceChange?: (voiceId: string) => void;
  /** Refetch `/api/tts/voices` after a catalog failure. */
  onRetryVoiceCatalog?: () => void | Promise<void>;
  disabled?: boolean;
  /** Trinity /chat — section cards use liquid glass (Language C). */
  trinityLiquid?: boolean;
};

export const VoiceSettingsPanel = memo(function VoiceSettingsPanel({
  state,
  onEnableAudio,
  onStartDelayChange,
  onSentenceGapChange,
  onVoiceSpeedChange,
  onToggleAutoSpeak,
  onElevenLabsVoiceChange,
  onRetryVoiceCatalog,
  disabled = false,
  trinityLiquid = false,
}: VoiceSettingsPanelProps) {
  const [debugTimingOpen, setDebugTimingOpen] = useState(false);
  const ctx = state.audioContextState;
  const showVoiceRetry =
    Boolean(onRetryVoiceCatalog) &&
    (state.voicesStatus === "error" ||
      (state.voicesStatus === "ok" &&
        state.voices.length === 0 &&
        (state.voicesWarnings?.length ?? 0) > 0));
  const showEnableAudioInSettings =
    ctx === "suspended" ||
    (typeof state.lastError === "string" &&
      (/audio blocked/i.test(state.lastError) || /enable audio/i.test(state.lastError)));

  return (
    <div
      className={cn(
        "flex min-w-0 flex-col gap-3.5",
