            </p>
          </div>
        ) : null}

        {onToggleAutoSpeak ? (
          <button
            type="button"
            onClick={onToggleAutoSpeak}
            aria-pressed={state.autoSpeakAssistant}
            className={cn(
              "touch-manipulation rounded-md border px-3 py-2 text-left font-mono text-[10px] uppercase tracking-wide",
              state.autoSpeakAssistant
