});"use client";

// ── OracleVoiceControls - hands-free Oracle session controls (Prompt 10D-E) ─────
// > Big "Start session" CTA, big "Stop session" while running, tiny "Finish now"
// > backup that only shows mid-utterance. Mic + Whisper + secure-context info live
// > inline so the user never has to spelunk an advanced menu.

import { Mic, MicOff, RefreshCw, Square } from "lucide-react";
import { memo } from "react";

import { VoiceControl } from "@/components/chat/VoiceControl";
import "@/components/oracle/oracle-visuals.css";
import type { UseTtsState } from "@/hooks/useTTS";
import type { UseOracleSpeechInputReturn } from "@/hooks/useOracleSpeechInput";
import { useMounted } from "@/lib/hooks/useMounted";
import type {
  OracleVoiceLoopMode,
  OracleVoiceSessionStatus,
} from "@/lib/oracle/oracle-voice-session";
import { oracleSessionStatusLabel } from "@/lib/oracle/oracle-voice-session";
import { cn } from "@/lib/cn";

export type OracleVoiceControlsProps = {
  mounted: boolean;
  status: OracleVoiceSessionStatus;
  loopMode: OracleVoiceLoopMode;
  onLoopModeChange: (mode: OracleVoiceLoopMode) => void;
  sessionActive: boolean;
  onStartSession: () => void | Promise<void>;
  onStopSession: () => void;
  onFinishThought: () => void | Promise<void>;
  speech: UseOracleSpeechInputReturn;
  ttsState: UseTtsState;
  onToggleTtsEnabled: () => void;
  onEnableAudio: () => void | Promise<void | boolean>;
  onStopSpeech: () => void;
  onSpeakLatestAssistant: () => void | Promise<void>;
  onStartDelayChange: (ms: number) => void;
  onSentenceGapChange: (ms: number) => void;
  onVoiceSpeedChange: (speed: number) => void;
  onToggleAutoSpeak: () => void;
  onRequestVoiceCatalog: () => void | Promise<void>;
  onElevenLabsVoiceChange: (voiceId: string) => void;
  transportBusy: boolean;
};

function primaryLabel(
  mounted: boolean,
  status: OracleVoiceSessionStatus,
  sessionActive: boolean,
): string {
  if (!mounted) return "…";
  switch (status) {
    case "blocked":
    case "unsupported":
      return "Mic blocked";
    case "requesting-mic":
      return "Requesting mic…";
    case "permission-needed":
      return "Grant mic access";
    case "listening":
      return "Listening…";
    case "hearing-speech":
      return "Hearing you…";
    case "silence-detected":
      return "Sending…";
    case "transcribing":
      return "Transcribing…";
    case "thinking":
      return "Thinking…";
    case "speaking":
      return "Speaking…";
    case "ready":
      return sessionActive ? "Mic idle - waiting…" : "Start session";
    case "restarting":
      return "Restarting…";
    case "stopped":
      return "Resume session";
    case "error":
      return "Try again";
    default:
      if (sessionActive) return "Listening…";
      return "Start session";
  }
}

const SILENCE_PRESETS = [
  { value: 800, label: "0.8s" },
  { value: 1200, label: "1.2s · default" },
  { value: 1800, label: "1.8s" },
  { value: 2500, label: "2.5s" },
];

const SENSITIVITY_PRESETS: { value: "low" | "medium" | "high"; threshold: number; label: string }[] = [
  { value: "low", threshold: 0.06, label: "Low" },
  { value: "medium", threshold: 0.035, label: "Medium · default" },
  { value: "high", threshold: 0.018, label: "High" },
];

function thresholdToSensitivity(threshold: number): "low" | "medium" | "high" {
  if (threshold >= 0.05) return "low";
  if (threshold <= 0.025) return "high";
  return "medium";
}

export const OracleVoiceControls = memo(function OracleVoiceControls({
  mounted,
  status,
  loopMode,
  onLoopModeChange,
  sessionActive,
  onStartSession,
  onStopSession,
  onFinishThought,
  speech,
  ttsState,
  onToggleTtsEnabled,
  onEnableAudio,
  onStopSpeech,
  onSpeakLatestAssistant,
  onStartDelayChange,
  onSentenceGapChange,
  onVoiceSpeedChange,
  onToggleAutoSpeak,
  onRequestVoiceCatalog,
  onElevenLabsVoiceChange,
  transportBusy,
}: OracleVoiceControlsProps) {
  const localMounted = useMounted();
  const readyForHints = mounted && localMounted;

  const showStopSpeech = ttsState.isPlaying || ttsState.queueLength > 0;
  const showSessionButtons = loopMode !== "manual-text";

  const insecureContext =
    readyForHints && speech.capability.isSecureContext === false;
  const blocked = readyForHints && (!speech.canUseMic || speech.blockedReason !== null);
  const showFinishNow =
    readyForHints &&
    (status === "listening" || status === "hearing-speech") &&
    speech.isRecording &&
    loopMode !== "manual-text";

  const hint = (() => {
    if (!readyForHints) return "Checking voice input…";
    if (loopMode === "manual-text") return "Text fallback - type below.";
    if (insecureContext) return speech.capabilityMessage;
    if (blocked) return speech.captureBlockedHint ?? speech.capabilityMessage;
    if (speech.permissionState === "denied")
      return "Mic permission denied - use text fallback or adjust browser site settings.";
    if (speech.devicesEnumerateError) return `Mic list: ${speech.devicesEnumerateError}`;
    if (status === "thinking") return "Thinking…";
    if (status === "speaking") {
      const name = ttsState.elevenLabsVoiceName ?? ttsState.elevenLabsVoiceId ?? "voice";
      return `Speaking with ${name}`;
    }
    if (status === "silence-detected") return "Heard the gap - sending to Whisper.";
    if (status === "restarting") return "Returning to listening…";
    if (status === "hearing-speech")
      return `Auto-send after ${(speech.silenceDurationMs / 1000).toFixed(1)}s of silence.`;
    if (status === "listening") return "Waiting for speech…";
    if (speech.permissionState === "granted")
      return sessionActive
        ? "Session active - speak naturally, Oracle hears the gap."
        : "Mic ready - tap Start session to begin.";
    return oracleSessionStatusLabel(status);
  })();

  const primaryDisabled =
    transportBusy ||
    status === "thinking" ||
    status === "speaking" ||
    status === "transcribing" ||
    status === "silence-detected" ||
    status === "requesting-mic" ||
    status === "restarting" ||
    blocked;

  const micPermissionLabel =
    !readyForHints
      ? "…"
      : speech.permissionState === "granted"
        ? "Granted"
        : speech.permissionState === "denied"
          ? "Denied"
          : speech.permissionState === "unsupported"
            ? "Unavailable"
            : "Needed";

  const meterPct = Math.round((speech.audioLevel ?? 0) * 100);
  const silenceLabel = (() => {
    if (!speech.isRecording) return "Idle";
    if (status === "silence-detected") return "Silence detected - sending…";
    if (status === "hearing-speech") return "Hearing speech";
    return `Waiting for speech (${Math.min(
      Math.round((speech.silenceMs / Math.max(1, speech.silenceDurationMs)) * 100),
      100,
    )}% of ${(speech.silenceDurationMs / 1000).toFixed(1)}s)`;
  })();

  const sensitivity = thresholdToSensitivity(speech.silenceThreshold);

  return (
    <section
      data-testid="oracle-voice-controls"
      aria-label="Oracle voice controls"
      className="oracle-chrome-px flex w-full min-w-0 flex-col gap-3 pb-2 pt-1"
    >
      {/* ── Secure-context warning - impossible to miss when blocked ───────────────── */}
      {readyForHints && insecureContext ? (
        <div
          role="alert"
          data-testid="oracle-secure-context-warning"
          className="rounded-xl border border-rose-500/40 bg-rose-950/30 px-3 py-3 text-rose-50 sm:px-4"
        >
          <p className="font-mono text-[11px] font-semibold uppercase tracking-wider text-rose-200">
            Mic blocked - insecure context
          </p>
          <p className="mt-1 font-mono text-[11px] leading-snug text-rose-100/95">
            This page is open over plain HTTP from a LAN/Tailscale IP. Browsers refuse
            mic access here. Use one of:
          </p>
          <ul className="mt-2 list-disc pl-5 font-mono text-[11px] leading-snug text-rose-100/90">
            <li>
              <span className="rounded border border-white/10 bg-black/30 px-1.5 py-0.5">http://localhost:3000</span>
            </li>
            <li>
              <span className="rounded border border-white/10 bg-black/30 px-1.5 py-0.5">http://127.0.0.1:3000</span>
            </li>
            <li>An HTTPS tunnel (Tailscale Serve/Funnel, Caddy, ngrok, trusted local cert).</li>
          </ul>
          {speech.httpsSamePageUrl ? (
            <a
              href={speech.httpsSamePageUrl}
              data-testid="oracle-https-upgrade-cta"
              className="mt-3 inline-flex min-h-[44px] w-full touch-manipulation items-center justify-center break-all rounded-lg border border-cyan-400/40 bg-cyan-500/15 px-3 py-2 text-center font-mono text-[11px] font-semibold leading-snug text-cyan-50 hover:bg-cyan-500/25"
            >
              Open {speech.httpsSamePageUrl}
            </a>
          ) : null}
        </div>
      ) : null}

      {/* ── Status strip: STT backend / mic permission / mic name ──────────────────── */}
      <div className="flex min-w-0 flex-wrap gap-2 rounded-xl border border-white/[0.06] bg-black/25 px-3 py-2 font-mono text-[11px] text-chalk/75 sm:gap-4">
        <div>
          <span className="text-chalk/45">STT</span> Whisper backend
        </div>
        <div>
          <span className="text-chalk/45">Mic permission</span> {micPermissionLabel}
        </div>
        <div className="min-w-0 truncate">
          <span className="text-chalk/45">Selected mic</span> {speech.selectedDeviceLabel}
        </div>
        <div>
          <span className="text-chalk/45">Secure</span>{" "}
          {readyForHints
            ? speech.capability.isSecureContext
              ? "OK"
              : "Blocked"
            : "…"}
        </div>
      </div>

      {/* ── Loop mode + microphone select (mic select stays accessible) ───────────── */}
      <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:flex-wrap sm:items-center">
        <label className="flex min-w-0 flex-col gap-1 font-mono text-[10px] uppercase tracking-wider text-chalk/50">
          Session mode
          <select
            value={loopMode}
            onChange={(e) => onLoopModeChange(e.target.value as OracleVoiceLoopMode)}
            className="min-h-[44px] rounded-lg border border-[color:var(--spirit-border)] bg-black/40 px-2 py-2 text-base text-chalk sm:max-w-[16rem]"
          >
            <option value="hands-free">Hands-free session (default)</option>
            <option value="push-to-talk">Push-to-talk</option>
            <option value="manual-text">Text only</option>
          </select>
        </label>

        <label className="flex min-w-0 flex-1 flex-col gap-1 font-mono text-[10px] uppercase tracking-wider text-chalk/50">
          Microphone
          <div className="flex min-w-0 flex-wrap items-center gap-2">
            <select
              disabled={
                speech.permissionState !== "granted" || Boolean(speech.devicesEnumerateError)
              }
              value={speech.selectedDeviceId ?? ""}
              onChange={(e) =>
                speech.setSelectedDeviceId(e.target.value ? e.target.value : null)
              }
              className="min-h-[44px] min-w-0 flex-1 rounded-lg border border-[color:var(--spirit-border)] bg-black/40 px-2 py-2 text-base text-chalk disabled:opacity-40 sm:max-w-[min(100%,22rem)]"
            >
              <option value="">Default microphone</option>
              {speech.devices.map((d) => (
                <option key={d.deviceId} value={d.deviceId}>
                  {d.label}
                </option>
              ))}
            </select>
            <button
              type="button"
              disabled={speech.permissionState !== "granted"}
              onClick={() => void speech.refreshDevices()}
              className="inline-flex h-11 min-h-[44px] min-w-[44px] shrink-0 touch-manipulation items-center justify-center rounded-lg border border-[color:var(--spirit-border)] bg-white/[0.04] text-chalk/80 [-webkit-tap-highlight-color:transparent] disabled:opacity-35"
              aria-label="Refresh microphone list"
            >
              <RefreshCw className="h-4 w-4" aria-hidden />
            </button>
          </div>
        </label>
      </div>

      {/* ── Audio meter + silence indicator (only when recording) ──────────────────── */}
      {readyForHints && loopMode !== "manual-text" ? (
        <div
          data-testid="oracle-audio-meter"
          className="flex min-w-0 flex-col gap-1 rounded-xl border border-white/[0.06] bg-black/15 px-3 py-2"
        >
          <div className="flex items-center gap-2">
            <span className="shrink-0 font-mono text-[10px] uppercase tracking-wider text-chalk/45">
              Input level
            </span>
            <div
              className="h-2 min-w-0 flex-1 overflow-hidden rounded-full bg-white/10"
              role="progressbar"
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={meterPct}
              aria-label="Microphone input level"
            >
              <div
                className={cn(
                  "h-full rounded-full transition-[width] duration-75",
                  status === "hearing-speech"
                    ? "bg-emerald-400/80"
                    : status === "silence-detected"
                      ? "bg-amber-400/80"
                      : "bg-cyan-400/70",
                )}
                style={{ width: `${Math.min(100, meterPct)}%` }}
              />
            </div>
            <span className="shrink-0 font-mono text-[10px] tabular-nums text-chalk/50">
              {meterPct}%
            </span>
          </div>
          <p className="font-mono text-[10px] text-chalk/55" data-testid="oracle-silence-indicator">
            {silenceLabel}
          </p>
        </div>
      ) : null}

      {/* ── Primary CTA + Stop session ─────────────────────────────────────────────── */}
      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-stretch">
        {showSessionButtons ? (
          <div className="flex min-w-0 flex-1 flex-col gap-2 sm:flex-row">
            <button
              type="button"
              data-testid="oracle-start-session"
              disabled={primaryDisabled}
              onClick={() => void onStartSession()}
              className={cn(
                "flex min-h-[52px] flex-1 touch-manipulation items-center justify-center gap-2 rounded-2xl border px-4 py-3 font-mono text-[13px] font-semibold uppercase tracking-wide transition sm:min-h-[54px]",
                blocked
                  ? "border-rose-500/45 bg-rose-500/15 text-rose-100"
                  : sessionActive
                    ? "border-cyan-400/45 bg-cyan-500/12 text-chalk"
                    : "border-[color:color-mix(in_oklab,var(--spirit-accent)_45%,transparent)] bg-[color:color-mix(in_oklab,var(--spirit-accent)_12%,transparent)] text-chalk",
                primaryDisabled && "opacity-60",
              )}
            >
              {blocked ? (
                <MicOff className="h-5 w-5 shrink-0" aria-hidden />
              ) : (
                <Mic className="h-5 w-5 shrink-0" aria-hidden />
              )}
              {primaryLabel(mounted, status, sessionActive)}
            </button>

            {sessionActive ? (
              <button
                type="button"
                data-testid="oracle-stop-session"
                onClick={onStopSession}
                className="inline-flex min-h-[52px] shrink-0 touch-manipulation items-center justify-center rounded-2xl border border-amber-400/35 bg-amber-500/15 px-4 font-mono text-[12px] font-semibold uppercase tracking-wide text-amber-50 sm:min-h-[54px]"
              >
                Stop session
              </button>
            ) : null}

            {showFinishNow ? (
              <button
                type="button"
                data-testid="oracle-finish-now"
                onClick={() => void onFinishThought()}
                className="inline-flex min-h-[44px] shrink-0 touch-manipulation items-center justify-center rounded-xl border border-white/10 bg-white/[0.05] px-3 font-mono text-[10px] font-semibold uppercase tracking-wider text-chalk/80 hover:bg-white/[0.08]"
                title="Backup - Oracle will normally auto-send when you stop talking."
              >
                Finish now
              </button>
            ) : null}
          </div>
        ) : (
          <p className="flex flex-1 items-center rounded-xl border border-dashed border-[color:var(--spirit-border)] px-3 py-3 font-mono text-xs text-chalk/55">
            Text-only mode - open the composer below.
          </p>
        )}

        <div className="flex min-w-0 flex-1 flex-col gap-2">
          <div className="font-mono text-[10px] uppercase tracking-wider text-chalk/45">
            Output voice
          </div>
          <VoiceControl
            hideVoiceEnableToggle
            state={ttsState}
            onToggleEnabled={onToggleTtsEnabled}
            onEnableAudio={onEnableAudio}
            onStop={onStopSpeech}
            onSpeakLatestAssistant={onSpeakLatestAssistant}
            onStartDelayChange={onStartDelayChange}
            onSentenceGapChange={onSentenceGapChange}
            onVoiceSpeedChange={onVoiceSpeedChange}
            onToggleAutoSpeak={onToggleAutoSpeak}
            onRequestVoiceCatalog={onRequestVoiceCatalog}
            onElevenLabsVoiceChange={onElevenLabsVoiceChange}
            disabled={transportBusy}
          />
        </div>
      </div>

      {showStopSpeech ? (
        <button
          type="button"
          onClick={onStopSpeech}
          className="inline-flex min-h-[48px] touch-manipulation items-center justify-center gap-2 rounded-xl border border-rose-400/40 bg-rose-500/15 px-4 font-mono text-xs font-semibold uppercase tracking-wide text-rose-50"
        >
          <Square className="h-4 w-4 fill-current" aria-hidden />
          Stop speech
        </button>
      ) : null}

      {/* ── Advanced settings (silence + sensitivity + text fallback toggle) ──────── */}
      <details
        className="rounded-xl border border-white/[0.06] bg-black/15 px-3 py-1"
        data-testid="oracle-vad-settings"
      >
        <summary className="oracle-details-summary cursor-pointer list-none font-mono text-[11px] uppercase tracking-wider text-chalk/55 [&::-webkit-details-marker]:hidden">
          Advanced · silence + sensitivity
        </summary>
        <div className="mt-3 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
          <label className="flex min-w-0 flex-1 flex-col gap-1 font-mono text-[10px] uppercase tracking-wider text-chalk/50">
            Silence duration
            <select
              data-testid="oracle-silence-duration"
              value={String(speech.silenceDurationMs)}
              onChange={(e) => speech.setSilenceDurationMs(Number(e.target.value))}
              className="min-h-[44px] rounded-lg border border-[color:var(--spirit-border)] bg-black/40 px-2 py-2 text-base text-chalk"
            >
              {SILENCE_PRESETS.map((p) => (
                <option key={p.value} value={p.value}>
                  {p.label}
                </option>
              ))}
            </select>
          </label>
          <label className="flex min-w-0 flex-1 flex-col gap-1 font-mono text-[10px] uppercase tracking-wider text-chalk/50">
            Sensitivity
            <select
              data-testid="oracle-sensitivity"
              value={sensitivity}
              onChange={(e) => {
                const choice = SENSITIVITY_PRESETS.find((p) => p.value === e.target.value);
                if (choice) speech.setSilenceThreshold(choice.threshold);
              }}
              className="min-h-[44px] rounded-lg border border-[color:var(--spirit-border)] bg-black/40 px-2 py-2 text-base text-chalk"
            >
              {SENSITIVITY_PRESETS.map((p) => (
                <option key={p.value} value={p.value}>
                  {p.label}
                </option>
              ))}
            </select>
          </label>
          <label className="flex min-w-0 flex-1 items-center gap-2 self-end font-mono text-[11px] text-chalk/70">
            <input
              data-testid="oracle-text-fallback-toggle"
              type="checkbox"
              checked={loopMode === "manual-text"}
              onChange={(e) =>
                onLoopModeChange(e.target.checked ? "manual-text" : "hands-free")
              }
              className="h-4 w-4 accent-cyan-400"
            />
            Text fallback only
          </label>
        </div>
      </details>

      <p className="font-mono text-[11px] leading-snug text-chalk/55">{hint}</p>
      {speech.permissionState === "granted" &&
      speech.devices.length === 0 &&
      !speech.devicesEnumerateError ? (
        <p className="font-mono text-[10px] text-chalk/45">
          No labeled mics yet - default capture still works.
        </p>
      ) : null}
    </section>
  );
});"use client";

// ── OracleVoiceStatusCard - compact session telemetry (hands-free aware) ──────────
import Link from "next/link";

import {
  oracleSessionStatusLabel,
  type OracleVoiceSessionStatus,
} from "@/lib/oracle/oracle-voice-session";
import { cn } from "@/lib/cn";

export type OracleVoiceStatusCardProps = {
  status: OracleVoiceSessionStatus;
  modeLabel: string;
  runtimeLabel: string;
  voiceProviderLine: string;
  selectedVoiceLabel: string;
  /** "Hands-free" / "Push-to-talk" / "Text only". */
  loopModeLabel?: string;
  /** Browser STT vs manual vs unsupported */
  speechInputLabel?: string;
  /** Resolved microphone label */
  micLabel?: string;
  /** "Granted" / "Denied" / "Unavailable" / "Needed" */
  micPermissionLabel?: string;
  /** True / false / null when not yet mounted. */
  secureContextOk?: boolean | null;
  audioLevel?: number;
  silenceMs?: number;
  silenceThresholdMs?: number;
  lastTranscript?: string;
  recordingStartedAt?: number | null;
  lastPlaybackWallMs?: number;
  lastError?: string | null;
  /** `/api/spirit` banner - orthogonal to TTS fetch failures. */
  spiritTransportError?: string | null;
  speechError?: string | null;
  className?: string;
};

function formatWallTime(wallMs: number): string {
  try {
    return new Date(wallMs).toLocaleTimeString(undefined, {
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
  } catch {
    return " - ";
  }
}

export function OracleVoiceStatusCard({
  status,
  modeLabel,
  runtimeLabel,
  voiceProviderLine,
  selectedVoiceLabel,
  loopModeLabel,
  speechInputLabel = " - ",
  micLabel = " - ",
  micPermissionLabel,
  secureContextOk,
  audioLevel,
  silenceMs,
  silenceThresholdMs,
  lastTranscript,
  recordingStartedAt,
  lastPlaybackWallMs,
  lastError,
  spiritTransportError,
  speechError,
  className,
}: OracleVoiceStatusCardProps) {
  const playedClock =
    typeof lastPlaybackWallMs === "number"
      ? formatWallTime(lastPlaybackWallMs)
      : null;
  const recordingClock =
    typeof recordingStartedAt === "number" ? formatWallTime(recordingStartedAt) : null;

  const tone =
    status === "error"
      ? "border-rose-500/35 bg-rose-500/[0.07]"
      : status === "blocked"
        ? "border-rose-500/45 bg-rose-950/30"
        : status === "thinking"
          ? "border-cyan-500/30 bg-cyan-500/[0.06]"
          : status === "speaking"
            ? "border-[color:color-mix(in_oklab,var(--spirit-accent)_45%,transparent)] bg-white/[0.04]"
            : status === "stopped"
              ? "border-amber-500/30 bg-amber-500/[0.06]"
              : status === "listening" ||
                  status === "hearing-speech" ||
                  status === "silence-detected" ||
                  status === "transcribing"
                ? "border-violet-500/30 bg-violet-500/[0.06]"
                : status === "permission-needed"
                  ? "border-amber-500/25 bg-amber-500/[0.05]"
                  : status === "unsupported"
                    ? "border-rose-400/25 bg-rose-950/20"
                    : "border-[color:var(--spirit-border)] bg-black/[0.12]";

  const audioPct =
    typeof audioLevel === "number" ? `${Math.round(Math.min(1, Math.max(0, audioLevel)) * 100)}%` : null;

  const silenceLine =
    typeof silenceMs === "number" && typeof silenceThresholdMs === "number"
      ? `${silenceMs}ms / ${silenceThresholdMs}ms`
      : null;

  const transcriptShort = lastTranscript?.trim()
    ? lastTranscript.trim().slice(0, 140)
    : null;

  const secureLabel =
    secureContextOk === null || secureContextOk === undefined
      ? "Checking…"
      : secureContextOk
        ? "OK"
        : "Blocked";

  return (
    <section
      data-testid="oracle-voice-status-card"
      aria-label="Oracle voice status"
      className={cn(
        "mx-2 rounded-xl border px-3 py-2.5 font-mono text-[11px] leading-snug text-chalk/85 sm:mx-5 lg:mx-6",
        tone,
        className,
      )}
    >
      <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/[0.06] pb-2">
        <span className="text-[10px] uppercase tracking-[0.2em] text-chalk/55">Oracle session</span>
        <span className="rounded-full border border-emerald-500/35 bg-emerald-500/[0.07] px-2 py-0.5 text-[9px] uppercase tracking-wider text-emerald-300/95">
          Hands-free MVP
        </span>
      </div>
      <dl className="mt-2 grid gap-y-1.5 text-[11px] sm:grid-cols-2 sm:gap-x-4">
        <div className="flex flex-wrap gap-x-2">
          <dt className="text-chalk/45">Runtime</dt>
          <dd className="text-[color:var(--spirit-accent-strong)]">{runtimeLabel}</dd>
        </div>
        <div className="flex flex-wrap gap-x-2">
          <dt className="text-chalk/45">Mode</dt>
          <dd className="text-chalk/90">{modeLabel}</dd>
        </div>
        {loopModeLabel ? (
          <div className="flex flex-wrap gap-x-2">
            <dt className="text-chalk/45">Loop</dt>
            <dd className="text-chalk/90">{loopModeLabel}</dd>
          </div>
        ) : null}
        <div className="flex flex-wrap gap-x-2">
          <dt className="text-chalk/45">Status</dt>
          <dd className="text-chalk">{oracleSessionStatusLabel(status)}</dd>
        </div>
        <div className="flex flex-wrap gap-x-2">
          <dt className="text-chalk/45">Mic permission</dt>
          <dd className="min-w-0 truncate">{micPermissionLabel ?? "-"}</dd>
        </div>
        <div className="flex flex-wrap gap-x-2">
          <dt className="text-chalk/45">Mic</dt>
          <dd className="min-w-0 truncate">{micLabel}</dd>
        </div>
        <div className="flex flex-wrap gap-x-2">
          <dt className="text-chalk/45">Input</dt>
          <dd className="min-w-0 truncate">{speechInputLabel}</dd>
        </div>
        <div className="flex flex-wrap gap-x-2">
          <dt className="text-chalk/45">Secure context</dt>
          <dd
            className={cn(
              "min-w-0 truncate",
              secureContextOk === false ? "text-rose-300/95" : "text-chalk/85",
            )}
          >
            {secureLabel}
          </dd>
        </div>
        {audioPct ? (
          <div className="flex flex-wrap gap-x-2">
            <dt className="text-chalk/45">Audio level</dt>
            <dd className="tabular-nums">{audioPct}</dd>
          </div>
        ) : null}
        {silenceLine ? (
          <div className="flex flex-wrap gap-x-2">
            <dt className="text-chalk/45">Silence</dt>
            <dd className="tabular-nums">{silenceLine}</dd>
          </div>
        ) : null}
        <div className="flex flex-wrap gap-x-2">
          <dt className="text-chalk/45">Voice backend</dt>
          <dd className="min-w-0 truncate">{voiceProviderLine}</dd>
        </div>
        <div className="flex flex-wrap gap-x-2 sm:col-span-2">
          <dt className="text-chalk/45">Voice</dt>
          <dd className="min-w-0 flex-1 truncate">{selectedVoiceLabel}</dd>
        </div>
        {transcriptShort ? (
          <div className="flex flex-wrap gap-x-2 sm:col-span-2">
            <dt className="text-chalk/45">Last transcript</dt>
            <dd className="min-w-0 flex-1 break-words text-chalk/85">{transcriptShort}</dd>
          </div>
        ) : null}
        {recordingClock ? (
          <div className="flex flex-wrap gap-x-2">
            <dt className="text-chalk/45">Recording started</dt>
            <dd>{recordingClock}</dd>
          </div>
        ) : null}
        {playedClock ? (
          <div className="flex flex-wrap gap-x-2">
            <dt className="text-chalk/45">Last audio (local)</dt>
            <dd>{playedClock}</dd>
          </div>
        ) : null}
        {lastError?.trim() || spiritTransportError?.trim() || speechError?.trim() ? (
          <div className="sm:col-span-2">
            <dt className="text-chalk/45">Last error</dt>
            <dd className="mt-0.5 space-y-1 text-rose-300/95">
              {spiritTransportError?.trim() ? (
                <p className="font-mono text-[10px] leading-snug">{spiritTransportError.trim()}</p>
              ) : null}
              {speechError?.trim() ? (
                <p className="font-mono text-[10px] leading-snug">STT: {speechError.trim()}</p>
              ) : null}
              {lastError?.trim() ? (
                <p className="font-mono text-[10px] leading-snug">TTS: {lastError.trim()}</p>
              ) : null}
            </dd>
          </div>
        ) : null}
      </dl>
      <div className="mt-2 border-t border-white/[0.06] pt-2 text-[10px] text-chalk/45">
        <Link
          href="/oracle"
          className="text-[color:var(--spirit-accent-strong)] underline underline-offset-4 hover:brightness-110"
        >
          Oracle voice session
        </Link>
        <span className="text-chalk/35"> · ephemeral · no saved threads</span>
      </div>
    </section>
  );
}"use client";

// ── usePersistentChat - Dexie shell: draft lane + optimistic deletes (no phantom rows) ─
import { useLiveQuery } from "dexie-react-hooks";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { useChatFolders } from "@/hooks/useChatFolders";
import { useChatThreads } from "@/hooks/useChatThreads";

import { buildFolderSidebarModel } from "@/lib/chat-folder-utils";
import { db } from "@/lib/chat-db";
import type { ChatMessage, ChatThread } from "@/lib/chat-db.types";
import {
  buildTitleFromText,
  createThread,
  deleteMessage as persistDeleteMessage,
  deleteMessages as persistDeleteMessages,
  generateChatRecordId,
  moveThreadToFolder as persistMoveThreadToFolder,
  reorderFolders,
  reorderThreadsInFolder,
  persistAssistantOutboundIfAbsent,
  persistUserOutboundMessage,
  updateMessageText as persistUpdateMessageText,
  updateThreadModelProfile as persistUpdateThreadModelProfile,
  pinThread as persistPinThread,
  unpinThread as persistUnpinThread,
} from "@/lib/chat-persistence";
import type { ThreadReorderOp } from "@/lib/chat-sidebar-dnd";
import { DEFAULT_MODEL_PROFILE_ID } from "@/lib/spirit/model-profile.types";
import type { ModelProfileId } from "@/lib/spirit/model-profile.types";

function mintDraftLaneId(): string {
  return `draft:${generateChatRecordId()}`;
}

export function usePersistentChat(enabled: boolean) {
  const {
    threads: rawThreads,
    isLoading: threadsLoading,
    createNewThread,
    renameThread,
    removeThread,
  } = useChatThreads(enabled);

  const {
    folders,
    isLoading: foldersLoading,
    createNewFolder,
    renameFolder,
    removeFolder,
    toggleFolderCollapsed,
    setFolderCollapsed,
  } = useChatFolders(enabled);

  const threadsRef = useRef(rawThreads);

  useEffect(() => {
    threadsRef.current = rawThreads;
  }, [rawThreads]);

  const activeThreadIdRef = useRef<string | null>(null);

  const [activeThreadId, setActiveThreadId] = useState<string | null>(null);
  const [draftLaneId, setDraftLaneId] = useState<string | null>(null);
  const [draftModelProfileId, setDraftModelProfileId] = useState<ModelProfileId>(
    DEFAULT_MODEL_PROFILE_ID,
  );
  const [pendingDeletedIds, setPendingDeletedIds] = useState(
    () => new Set<string>(),
  );

  useEffect(() => {
    activeThreadIdRef.current = activeThreadId;
  }, [activeThreadId]);

  const visibleThreads = useMemo(
    () => rawThreads.filter((t) => !pendingDeletedIds.has(t.id)),
    [rawThreads, pendingDeletedIds],
  );

  const folderModel = useMemo(
    () => buildFolderSidebarModel(visibleThreads, folders),
    [visibleThreads, folders],
  );

  const draftLaneActive = Boolean(draftLaneId && activeThreadId === null);
  /** While Dexie threads are loading, block only `activeThreadId` paths - first send can mint a thread. */
  const canSendOutbound =
    draftLaneActive || Boolean(activeThreadId) || threadsLoading;

  const activeModelProfileId = useMemo((): ModelProfileId => {
    if (!enabled) return DEFAULT_MODEL_PROFILE_ID;
    if (draftLaneActive) return draftModelProfileId;
    if (activeThreadId) {
      const row = visibleThreads.find((t) => t.id === activeThreadId);
      return row?.modelProfileId ?? DEFAULT_MODEL_PROFILE_ID;
    }
    return DEFAULT_MODEL_PROFILE_ID;
  }, [
    enabled,
    draftLaneActive,
    draftModelProfileId,
    activeThreadId,
    visibleThreads,
  ]);

  const persistedSnapshot = useLiveQuery(
    () => {
      if (!enabled || !db || !activeThreadId) return [] as ChatMessage[];
      return db.messages.where("threadId").equals(activeThreadId).sortBy("createdAt");
    },
    [enabled, activeThreadId],
  );

  const isPersistedHydrationReady =
    !enabled || activeThreadId === null || persistedSnapshot !== undefined;

  const enterDraftLane = useCallback(() => {
    setDraftModelProfileId(DEFAULT_MODEL_PROFILE_ID);
    setDraftLaneId(mintDraftLaneId());
    setActiveThreadId(null);
  }, []);

  const selectPersistedThread = useCallback((id: string) => {
    setDraftLaneId(null);
    setActiveThreadId(id);
  }, []);

  /* eslint-disable react-hooks/set-state-in-effect -- Dexie/live bootstrap reconciles observable thread list vs React focus */
  useEffect(() => {
    if (!enabled) return;
    if (threadsLoading) return;
    if (draftLaneId !== null) return;

    if (activeThreadId) {
      if (visibleThreads.some((t) => t.id === activeThreadId)) return;
      if (visibleThreads.length > 0) {
        setActiveThreadId(visibleThreads[0]!.id);
        setDraftLaneId(null);
        return;
      }
      enterDraftLane();
      return;
    }

    // ── GPT-style landing: plain /chat opens draft lane, not the latest saved thread ─
    // User picks a thread from the sidebar/drawer; we only auto-pick when reconciling a stale id above.
    enterDraftLane();
  }, [
    enabled,
    threadsLoading,
    visibleThreads,
    activeThreadId,
    draftLaneId,
    enterDraftLane,
  ]);
  /* eslint-enable react-hooks/set-state-in-effect */

  const beginNewDraftChat = useCallback(() => {
    enterDraftLane();
  }, [enterDraftLane]);

  /** Legacy/tests: persist shell thread immediately - UI should prefer draft lane instead. */
  const createPersistedShellThread = useCallback(async () => {
    const id = await createNewThread();
    if (id) {
      setDraftLaneId(null);
      setActiveThreadId(id);
    }
    return id;
  }, [createNewThread]);

  const persistAssistantMessageToThread = useCallback(
    async (threadId: string, messageId: string, text: string) => {
      if (!enabled) return;
      await persistAssistantOutboundIfAbsent(threadId, messageId, text);
    },
    [enabled],
  );

  const persistUserOutboundForSend = useCallback(
    async (
      text: string,
      preferredUserMessageId?: string,
    ): Promise<{ threadId: string } | null> => {
      if (!enabled) return null;
      const trimmed = text.trim();
      if (!trimmed) return null;

      if (activeThreadId) {
        await persistUserOutboundMessage(
          activeThreadId,
          trimmed,
          preferredUserMessageId,
        );
        return { threadId: activeThreadId };
      }

      const row = await createThread({
        title: buildTitleFromText(trimmed),
        modelProfileId: draftModelProfileId,
      });
      if (!row) return null;

      await persistUserOutboundMessage(
        row.id,
        trimmed,
        preferredUserMessageId,
      );
      setDraftLaneId(null);
      setActiveThreadId(row.id);
      return { threadId: row.id };
    },
    [enabled, activeThreadId, draftModelProfileId],
  );

  const setActiveModelProfile = useCallback(
    async (profileId: ModelProfileId) => {
      if (!enabled) return;
      if (draftLaneActive) {
        setDraftModelProfileId(profileId);
        return;
      }
      if (activeThreadId) {
        await persistUpdateThreadModelProfile(activeThreadId, profileId);
      }
    },
    [enabled, draftLaneActive, activeThreadId],
  );

  const updateThreadModelProfile = useCallback(
    async (threadId: string, profileId: ModelProfileId) => {
      if (!enabled) return;
      await persistUpdateThreadModelProfile(threadId, profileId);
    },
    [enabled],
  );

  const deleteThreadOptimistic = useCallback(
    async (id: string) => {
      if (!enabled) return;

      let restVisible: ChatThread[] = [];
      setPendingDeletedIds((prev) => {
        const n = new Set(prev);
        n.add(id);
        restVisible = threadsRef.current.filter((t) => !n.has(t.id));
        return n;
      });

      if (activeThreadIdRef.current === id) {
        const nextPick = restVisible[0]?.id ?? null;
        if (nextPick) {
          setDraftLaneId(null);
          setActiveThreadId(nextPick);
        } else {
          enterDraftLane();
        }
      }

      try {
        await removeThread(id);
      } catch (e) {
        console.error("[usePersistentChat] optimistic delete failed:", e);
      } finally {
        setPendingDeletedIds((prev) => {
          const n = new Set(prev);
          n.delete(id);
          return n;
        });
      }
    },
    [enabled, removeThread, enterDraftLane],
  );

  const renameThreadStable = renameThread;

  const moveThreadToFolder = useCallback(
    async (threadId: string, folderId: string | null) => {
      if (!enabled) return;
      await persistMoveThreadToFolder(threadId, folderId);
    },
    [enabled],
  );

  const pinThread = useCallback(
    async (id: string) => {
      if (!enabled) return;
      await persistPinThread(id);
    },
    [enabled],
  );

  const unpinThread = useCallback(
    async (id: string) => {
      if (!enabled) return;
      await persistUnpinThread(id);
    },
    [enabled],
  );

  const commitThreadSidebarOrder = useCallback(
    async (ops: ThreadReorderOp[]) => {
      if (!enabled) return;
      for (const op of ops) {
        if (op.orderedIds.length === 0) continue;
        await reorderThreadsInFolder(op.folderId, op.orderedIds);
      }
    },
    [enabled],
  );

  const commitFolderSidebarOrder = useCallback(async (ids: string[]) => {
    if (!enabled) return;
    await reorderFolders(ids);
  }, [enabled]);

  const updatePersistedMessageText = useCallback(
    async (messageId: string, text: string) => {
      if (!enabled) return;
      await persistUpdateMessageText(messageId, text);
    },
    [enabled],
  );

  const deletePersistedMessage = useCallback(
    async (messageId: string) => {
      if (!enabled) return;
      await persistDeleteMessage(messageId);
    },
    [enabled],
  );

  const deletePersistedMessages = useCallback(
    async (messageIds: string[]) => {
      if (!enabled) return;
      await persistDeleteMessages(messageIds);
    },
    [enabled],
  );

  const expandFolder = useCallback(
    async (id: string) => {
      if (!enabled) return;
      await setFolderCollapsed(id, false);
    },
    [enabled, setFolderCollapsed],
  );

  return useMemo(() => {
    const persistedMessages = persistedSnapshot ?? ([] as ChatMessage[]);
    const messagesLoading =
      Boolean(enabled && activeThreadId && persistedSnapshot === undefined);

    return {
      enabled,
      activeThreadId,
      draftLaneId,
      draftLaneActive,
      activeModelProfileId,
      canSendOutbound,
      setActiveThreadId,
      visibleThreads,
      threadsLoading,
      folders,
      foldersLoading,
      rootThreads: folderModel.rootThreads,
      folderSections: folderModel.folderSections,
      createFolder: createNewFolder,
      renameFolder,
      deleteFolder: removeFolder,
      toggleFolderCollapsed,
      expandFolder,
      moveThreadToFolder,
      pinThread,
      unpinThread,
      commitThreadSidebarOrder,
      commitFolderSidebarOrder,
      setActiveModelProfile,
      updateThreadModelProfile,
      persistedMessages,
      messagesLoading,
      isPersistedHydrationReady,
      beginNewDraftChat,
      createNewThread: createPersistedShellThread,
      selectPersistedThread,
      renameThread: renameThreadStable,
      deleteThread: deleteThreadOptimistic,
      persistUserOutboundForSend,
      persistAssistantMessageToThread,
      updatePersistedMessageText,
      deletePersistedMessage,
      deletePersistedMessages,
    };
  }, [
    enabled,
    activeThreadId,
    draftLaneId,
    draftLaneActive,
    activeModelProfileId,
    canSendOutbound,
    visibleThreads,
    threadsLoading,
    folders,
    foldersLoading,
    folderModel.rootThreads,
    folderModel.folderSections,
    createNewFolder,
    renameFolder,
    removeFolder,
    toggleFolderCollapsed,
    expandFolder,
    moveThreadToFolder,
    pinThread,
    unpinThread,
    commitThreadSidebarOrder,
    commitFolderSidebarOrder,
    setActiveModelProfile,
    updateThreadModelProfile,
    persistedSnapshot,
    isPersistedHydrationReady,
    beginNewDraftChat,
    createPersistedShellThread,
    selectPersistedThread,
    renameThreadStable,
    deleteThreadOptimistic,
    persistUserOutboundForSend,
    persistAssistantMessageToThread,
    updatePersistedMessageText,
    deletePersistedMessage,
    deletePersistedMessages,
  ]);
}"use client";

/* eslint-disable react-hooks/set-state-in-effect -- Dexie search + sidebar; same pattern as pre-extract SpiritChat */
import { useEffect, useMemo, useState } from "react";

import { usePersistentChat } from "@/hooks/usePersistentChat";
import {
  filterFolderSidebarModel,
  sortThreadsWithOrderFallback,
} from "@/lib/chat-folder-utils";
import type { FolderSidebarSection } from "@/lib/chat-folder-utils";
import type { ChatFolder, ChatMessage, ChatThread } from "@/lib/chat-db.types";
import { searchThreadsAndMessages } from "@/lib/chat-persistence";

/** Search sidebar empty state - Dexie returned zero thread ids for query */
export function spiritThreadSearchEmpty(args: {
  sidebarFeaturesEnabled: boolean;
  debouncedSearchTrimmed: string;
  searchPending: boolean;
  searchAllow: Set<string> | null;
}): boolean {
  return (
    Boolean(args.sidebarFeaturesEnabled) &&
    args.debouncedSearchTrimmed.length > 0 &&
    !args.searchPending &&
    args.searchAllow !== null &&
    args.searchAllow.size === 0
  );
}

export type UseSpiritThreadRuntimeInput = {
  /** Mirrors `persistence` prop - Dexie on/off */
  enabled: boolean;
  /** Saved-thread sidebar features (search, debounced hits); off for ephemeral surfaces */
  sidebarFeaturesEnabled: boolean;
};

export type SpiritThreadRuntime = {
  persistent: ReturnType<typeof usePersistentChat>;
  savedThreadCount: number;
  rootThreads: ChatThread[];
  folderSections: FolderSidebarSection[];
  allFolders: ChatFolder[];
  activeThreadId: string | null;
  draftActive: boolean;
  activeThread: ChatThread | null;
  activeThreadIdOrDraftKey: string;
  persistedMessages: ChatMessage[] | undefined;
  isPersistedHydrationReady: boolean;
  isThreadHydrating: boolean;

  beginNewChat(): void;
  selectThread(threadId: string): void;
  deleteThread(threadId: string): void;
  renameThread(threadId: string, title: string): void;
  pinThread(threadId: string): void;
  unpinThread(threadId: string): void;

  createFolder(name: string): Promise<boolean>;
  renameFolder(folderId: string, name: string): Promise<boolean>;
  deleteFolder(folderId: string): void;
  toggleFolderCollapsed(folderId: string): void;
  moveThreadToFolder(threadId: string, folderId: string | null): void;
  commitThreadSidebarOrder: ReturnType<
    typeof usePersistentChat
  >["commitThreadSidebarOrder"];
  commitFolderSidebarOrder: ReturnType<
    typeof usePersistentChat
  >["commitFolderSidebarOrder"];

  searchQuery: string;
  setSearchQuery: (query: string) => void;
  debouncedSearchTrimmed: string;
  searchPending: boolean;
  searchSnippets: Record<string, string>;
  searchAllow: Set<string> | null;
  searchEmptyResults: boolean;
  pinnedThreadsDisplay: ChatThread[];
};

export function useSpiritThreadRuntime(
  input: UseSpiritThreadRuntimeInput,
): SpiritThreadRuntime {
  const persistent = usePersistentChat(input.enabled);

  const [searchInput, setSearchInput] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  useEffect(() => {
    const t = window.setTimeout(() => setDebouncedSearch(searchInput), 220);
    return () => window.clearTimeout(t);
  }, [searchInput]);

  const [searchAllow, setSearchAllow] = useState<Set<string> | null>(null);
  const [searchSnippets, setSearchSnippets] = useState<Record<string, string>>({});
  const [searchPending, setSearchPending] = useState(false);

  useEffect(() => {
    if (!input.sidebarFeaturesEnabled || !persistent.enabled) {
      setSearchAllow(null);
      setSearchSnippets({});
      setSearchPending(false);
      return;
    }
    const q = debouncedSearch.trim();
    if (!q) {
      setSearchAllow(null);
      setSearchSnippets({});
      setSearchPending(false);
      return;
    }
    setSearchPending(true);
    let cancelled = false;
    void searchThreadsAndMessages(q).then((hits) => {
      if (cancelled) return;
      const rec: Record<string, string> = {};
      const s = new Set<string>();
      for (const h of hits) {
        s.add(h.thread.id);
        if (h.snippet && !rec[h.thread.id]) rec[h.thread.id] = h.snippet;
      }
      setSearchAllow(s);
      setSearchSnippets(rec);
      setSearchPending(false);
    });
    return () => {
      cancelled = true;
    };
  }, [input.sidebarFeaturesEnabled, persistent.enabled, debouncedSearch]);

  const filteredSidebarModel = useMemo(() => {
    const base = {
      rootThreads: persistent.rootThreads,
      folderSections: persistent.folderSections,
    };
    if (!searchAllow) return base;
    return filterFolderSidebarModel(base, searchAllow);
  }, [persistent.rootThreads, persistent.folderSections, searchAllow]);

  const pinnedThreadsDisplay = useMemo(() => {
    const pinned = persistent.visibleThreads.filter((t) => t.pinned);
    // DnD commits `order` via reorderThreadsInFolder — **not** pinnedAt. Sorting pins by pinnedAt
    // made downward drags “stick” in Dexie then snap back in React (Spirit is not amused).
    const list = sortThreadsWithOrderFallback(pinned);
    if (!searchAllow) return list;
    return list.filter((t) => searchAllow.has(t.id));
  }, [persistent.visibleThreads, searchAllow]);

  const activeThread =
    persistent.activeThreadId == null
      ? null
      : persistent.visibleThreads.find((t) => t.id === persistent.activeThreadId) ?? null;

  const activeThreadIdOrDraftKey = persistent.draftLaneActive
    ? `draft:${persistent.draftLaneId ?? ""}`
    : (persistent.activeThreadId ?? "");

  const isThreadHydrating = Boolean(
    persistent.messagesLoading &&
      !persistent.draftLaneActive &&
      persistent.activeThreadId,
  );

  const debouncedSearchTrimmed = debouncedSearch.trim();
  const searchEmptyResults = spiritThreadSearchEmpty({
    sidebarFeaturesEnabled: input.sidebarFeaturesEnabled,
    debouncedSearchTrimmed,
    searchPending,
    searchAllow,
  });

  return useMemo(
    (): SpiritThreadRuntime => ({
      persistent,
      savedThreadCount: persistent.visibleThreads.length,
      rootThreads: filteredSidebarModel.rootThreads,
      folderSections: filteredSidebarModel.folderSections,
      allFolders: persistent.folders,
      activeThreadId: persistent.activeThreadId,
      draftActive: persistent.draftLaneActive,
      activeThread,
      activeThreadIdOrDraftKey,
      persistedMessages: persistent.persistedMessages,
      isPersistedHydrationReady: persistent.isPersistedHydrationReady,
      isThreadHydrating,

      beginNewChat: persistent.beginNewDraftChat,
      selectThread: persistent.selectPersistedThread,
      deleteThread: persistent.deleteThread,
      renameThread: persistent.renameThread,
      pinThread: persistent.pinThread,
      unpinThread: persistent.unpinThread,

      createFolder: persistent.createFolder,
      renameFolder: persistent.renameFolder,
      deleteFolder: persistent.deleteFolder,
      toggleFolderCollapsed: persistent.toggleFolderCollapsed,
      moveThreadToFolder: persistent.moveThreadToFolder,
      commitThreadSidebarOrder: persistent.commitThreadSidebarOrder,
      commitFolderSidebarOrder: persistent.commitFolderSidebarOrder,

      searchQuery: searchInput,
      setSearchQuery: setSearchInput,
      debouncedSearchTrimmed,
      searchPending,
      searchSnippets,
      searchAllow,
      searchEmptyResults,
      pinnedThreadsDisplay,
    }),
    [
      persistent,
      filteredSidebarModel.rootThreads,
      filteredSidebarModel.folderSections,
      activeThread,
      activeThreadIdOrDraftKey,
      searchInput,
      debouncedSearchTrimmed,
      searchPending,
      searchSnippets,
      searchAllow,
      searchEmptyResults,
      pinnedThreadsDisplay,
      isThreadHydrating,
    ],
  );
}"use client";

// ── useTTS - localStorage-backed Piper/ElevenLabs via /api/tts (Prompt 9H + 9I) ───
// > Initial render must NOT read localStorage - Next will hydration-murder you.
// > isEnabledRef: onFinish auto-speak must not lose to a stale `speak` closure on desktop.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import {
  AudioQueue,
  type AudioQueueState,
  type TtsLatency,
  type TtsPlaybackEvent,
  TTS_AUDIO_BLOCKED_MESSAGE,
} from "@/lib/tts/audio-queue";
import {
  clampTtsVoiceSpeed,
  TTS_SPEED_DEFAULT,
  TTS_VOICE_SPEED_PRESETS,
} from "@/lib/tts/voice-speed";

export type { TtsLatency, TtsPlaybackMode } from "@/lib/tts/audio-queue";

export { TTS_VOICE_SPEED_PRESETS };

export type TtsVoiceCatalogRow = {
  voice_id: string;
  name: string;
  category?: string;
  labels?: Record<string, string>;
  preview_url?: string | null;
};

const LS_ENABLED = "spirit:ttsEnabled";
const LS_START = "spirit:ttsStartDelayMs";
const LS_GAP = "spirit:ttsSentenceGapMs";
const LS_AUTO = "spirit:ttsAutoSpeak";
const LS_VOICE_SPEED = "spirit:ttsVoiceSpeed";
const LS_VOICE_ID = "spirit:ttsVoiceId";
const LS_VOICE_NAME = "spirit:ttsVoiceName";

function readBool(key: string, fallback: boolean): boolean {
  if (typeof window === "undefined") return fallback;
  try {
    const v = window.localStorage.getItem(key);
    if (v === null) return fallback;
    return v === "1" || v === "true";
  } catch {
    return fallback;
  }
}

function readNum(key: string, fallback: number): number {
  if (typeof window === "undefined") return fallback;
  try {
    const v = window.localStorage.getItem(key);
    if (v === null) return fallback;
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  } catch {
    return fallback;
  }
}

function readStr(key: string, fallback: string | null): string | null {
  if (typeof window === "undefined") return fallback;
  try {
    const v = window.localStorage.getItem(key);
    if (v === null) return fallback;
    const t = v.trim();
    return t ? t : fallback;
  } catch {
    return fallback;
  }
}

function writeLs(key: string, value: string): void {
  try {
    window.localStorage.setItem(key, value);
  } catch {
    /* private mode / quota */
  }
}

export type UseTtsState = AudioQueueState & {
  isEnabled: boolean;
  startDelayMs: number;
  sentenceGapMs: number;
  autoSpeakAssistant: boolean;
  /** Clamped 0.7–1.2; POSTed to /api/tts as `speed`. */
  voiceSpeed: number;
  /** ElevenLabs voice_id (localStorage + Voice picker). */
  elevenLabsVoiceId: string | null;
  elevenLabsVoiceName: string | null;
  voices: TtsVoiceCatalogRow[];
  voicesStatus: "idle" | "loading" | "ok" | "error";
  voicesError?: string;
  lastError?: string;
  lastLatency?: TtsLatency;
  lastVoiceNote?: "interrupted";
  /** Wall-clock ms when /api/tts playback latency was logged (Oracle status card). */
  lastPlaybackWallMs?: number;
  /** Wall-clock ms when user invoked Stop (Oracle "stopped" hint). */
  lastUserStopAtMs?: number | null;
  /** From GET /api/tts/voices (Prompt 9L). */
  voicesSource?: string;
  voicesAllowlistMode?: string;
  voicesWarnings?: string[];
};

export function useTTS() {
  const [isEnabled, setIsEnabledState] = useState(false);
  const isEnabledRef = useRef(false);

  const [startDelayMs, setStartDelayMsState] = useState(0);
  const [sentenceGapMs, setSentenceGapMsState] = useState(150);
  const [autoSpeakAssistant, setAutoSpeakAssistantState] = useState(false);
  const [voiceSpeed, setVoiceSpeedState] = useState(TTS_SPEED_DEFAULT);
  const [elevenLabsVoiceId, setElevenLabsVoiceIdState] = useState<string | null>(null);
  const [elevenLabsVoiceName, setElevenLabsVoiceNameState] = useState<string | null>(null);
  const [voices, setVoices] = useState<TtsVoiceCatalogRow[]>([]);
  const [voicesSource, setVoicesSource] = useState<string | undefined>(undefined);
  const [voicesAllowlistMode, setVoicesAllowlistMode] = useState<string | undefined>(undefined);
  const [voicesWarnings, setVoicesWarnings] = useState<string[]>([]);
  const [voicesStatus, setVoicesStatus] = useState<"idle" | "loading" | "ok" | "error">(
    "idle",
  );
  const [voicesError, setVoicesError] = useState<string | undefined>(undefined);
  const [queueUi, setQueueUi] = useState<AudioQueueState>({
    isPlaying: false,
    queueLength: 0,
    audioContextState: "unknown",
  });
  const [lastError, setLastError] = useState<string | undefined>(undefined);
  const [lastLatency, setLastLatency] = useState<TtsLatency | undefined>(undefined);
  const [lastVoiceNote, setLastVoiceNote] = useState<"interrupted" | undefined>(
    undefined,
  );
  const [lastPlaybackWallMs, setLastPlaybackWallMs] = useState<number | undefined>(
    undefined,
  );
  const [lastUserStopAtMs, setLastUserStopAtMs] = useState<number | null>(null);

  const queueRef = useRef<AudioQueue | null>(null);

  const onPlaybackEvent = useCallback((e: TtsPlaybackEvent) => {
    if (e === "interrupted") setLastVoiceNote("interrupted");
  }, []);

  const getQueue = useCallback(() => {
    if (!queueRef.current) {
      queueRef.current = new AudioQueue({
        onState: (s) => setQueueUi(s),
        onError: (msg) => setLastError(msg),
        onLatency: (m) => {
          setLastVoiceNote(undefined);
          setLastLatency(m);
          setLastPlaybackWallMs(Date.now());
          setLastUserStopAtMs(null);
        },
        onPlaybackEvent,
      });
    }
    return queueRef.current;
  }, [onPlaybackEvent]);

  useEffect(() => {
    queueMicrotask(() => {
      const en = readBool(LS_ENABLED, false);
      isEnabledRef.current = en;
      setIsEnabledState(en);
      setStartDelayMsState(readNum(LS_START, 0));
      setSentenceGapMsState(readNum(LS_GAP, 150));
      setAutoSpeakAssistantState(readBool(LS_AUTO, false));
      const raw = readNum(LS_VOICE_SPEED, TTS_SPEED_DEFAULT);
      setVoiceSpeedState(clampTtsVoiceSpeed(raw));
      setElevenLabsVoiceIdState(readStr(LS_VOICE_ID, null));
      setElevenLabsVoiceNameState(readStr(LS_VOICE_NAME, null));
    });
  }, []);

  useEffect(() => {
    const q = getQueue();
    q.startDelayMs = startDelayMs;
    q.sentenceGapMs = sentenceGapMs;
    q.ttsVoiceSpeed = voiceSpeed;
    q.ttsVoiceId = elevenLabsVoiceId?.trim() ? elevenLabsVoiceId.trim() : null;
    q.ttsVoiceName = elevenLabsVoiceName?.trim() ? elevenLabsVoiceName.trim() : null;
  }, [getQueue, startDelayMs, sentenceGapMs, voiceSpeed, elevenLabsVoiceId, elevenLabsVoiceName]);

  useEffect(() => {
    if (!isEnabled) {
      getQueue().stop();
    }
  }, [getQueue, isEnabled]);

  const applyVoiceSelection = useCallback((id: string, name: string | null) => {
    const tid = id.trim();
    if (!tid) return;
    setElevenLabsVoiceIdState(tid);
    setElevenLabsVoiceNameState(name?.trim() ? name.trim() : null);
    writeLs(LS_VOICE_ID, tid);
    if (name?.trim()) writeLs(LS_VOICE_NAME, name.trim());
    else {
      try {
        window.localStorage.removeItem(LS_VOICE_NAME);
      } catch {
        /* ignore */
      }
    }
  }, []);

  const refreshElevenLabsVoices = useCallback(async () => {
    setVoicesError(undefined);
    setVoicesStatus("loading");
    setVoicesWarnings([]);
    try {
      const res = await fetch("/api/tts/voices", { method: "GET", cache: "no-store" });
      let json: {
        ok?: boolean;
        voices?: TtsVoiceCatalogRow[];
        defaultVoiceId?: string | null;
        defaultVoiceName?: string | null;
        error?: string;
        detail?: string;
        status?: number;
        source?: string;
        allowlistMode?: string;
        warnings?: unknown[];
        pickWarning?: string;
      };
      try {
        json = (await res.json()) as typeof json;
      } catch {
        throw new Error(`voices_${res.status}_invalid_json`);
      }
      if (!res.ok || !json.ok) {
        const parts = [json.error || `voices_${res.status}`];
        if (json.detail) parts.push(json.detail);
        throw new Error(parts.join(" - "));
      }
      const list = Array.isArray(json.voices) ? json.voices : [];
      setVoices(list);
      setVoicesStatus("ok");
      setVoicesSource(typeof json.source === "string" ? json.source : undefined);
      setVoicesAllowlistMode(typeof json.allowlistMode === "string" ? json.allowlistMode : undefined);
      const w: string[] = [];
      if (Array.isArray(json.warnings)) {
        for (const x of json.warnings) {
          if (typeof x === "string" && x.trim()) w.push(x.trim());
        }
      }
      if (typeof json.pickWarning === "string" && json.pickWarning.trim()) {
        w.push(json.pickWarning.trim());
      }
      setVoicesWarnings(w);

      const savedId = readStr(LS_VOICE_ID, null);
      if (savedId) {
        const row = list.find((v) => v.voice_id === savedId);
        if (row) {
          applyVoiceSelection(row.voice_id, row.name);
        } else if (json.defaultVoiceId) {
          applyVoiceSelection(json.defaultVoiceId, json.defaultVoiceName ?? null);
        } else if (list[0]) {
          applyVoiceSelection(list[0].voice_id, list[0].name);
        }
      } else if (json.defaultVoiceId) {
        applyVoiceSelection(json.defaultVoiceId, json.defaultVoiceName ?? null);
      } else if (list[0]) {
        applyVoiceSelection(list[0].voice_id, list[0].name);
      }
    } catch (e) {
      setVoicesStatus("error");
      setVoicesError(e instanceof Error ? e.message : String(e));
      setVoicesSource(undefined);
      setVoicesAllowlistMode(undefined);
      setVoicesWarnings([]);
    }
  }, [applyVoiceSelection]);

  const setEnabled = useCallback(
    (next: boolean) => {
      isEnabledRef.current = next;
      setIsEnabledState(next);
      writeLs(LS_ENABLED, next ? "1" : "0");
      if (!next) getQueue().stop();
    },
    [getQueue],
  );

  const toggleEnabled = useCallback(() => {
    setEnabled(!isEnabled);
  }, [isEnabled, setEnabled]);

  const setStartDelayMs = useCallback((ms: number) => {
    setStartDelayMsState(ms);
    writeLs(LS_START, String(ms));
  }, []);

  const setSentenceGapMs = useCallback((ms: number) => {
    setSentenceGapMsState(ms);
    writeLs(LS_GAP, String(ms));
  }, []);

  const setAutoSpeakAssistant = useCallback((next: boolean) => {
    setAutoSpeakAssistantState(next);
    writeLs(LS_AUTO, next ? "1" : "0");
  }, []);

  const toggleAutoSpeakAssistant = useCallback(() => {
    setAutoSpeakAssistantState((v) => {
      const n = !v;
      writeLs(LS_AUTO, n ? "1" : "0");
      return n;
    });
  }, []);

  const setVoiceSpeed = useCallback((next: number) => {
    const v = clampTtsVoiceSpeed(next);
    setVoiceSpeedState(v);
    writeLs(LS_VOICE_SPEED, String(v));
  }, []);

  const setElevenLabsVoiceFromPicker = useCallback(
    (voiceId: string, name?: string | null) => {
      const row = voices.find((v) => v.voice_id === voiceId);
      applyVoiceSelection(voiceId, name ?? row?.name ?? null);
    },
    [applyVoiceSelection, voices],
  );

  const ensureAudioUnlocked = useCallback(async (): Promise<boolean> => {
    const ok = await getQueue().ensureAudioUnlocked();
    if (ok) setLastError(undefined);
    else setLastError(TTS_AUDIO_BLOCKED_MESSAGE);
    return ok;
  }, [getQueue]);

  const prime = ensureAudioUnlocked;

  const stop = useCallback(() => {
    setLastUserStopAtMs(Date.now());
    getQueue().stop();
  }, [getQueue]);

  const speak = useCallback(
    (
      text: string,
      options?: {
        interrupt?: boolean;
        preferHtmlAudioFirst?: boolean;
        spokenSummaryLine?: string;
      },
    ) => {
      if (!isEnabledRef.current) return;
      setLastError(undefined);
      setLastUserStopAtMs(null);
      getQueue().speak(text, {
        interrupt: options?.interrupt ?? true,
        preferHtmlAudioFirst: options?.preferHtmlAudioFirst,
        spokenSummaryLine: options?.spokenSummaryLine,
      });
    },
    [getQueue],
  );

  const speakMany = useCallback(
    (
      texts: string[],
      options?: {
        interrupt?: boolean;
        preferHtmlAudioFirst?: boolean;
        spokenSummaryLine?: string;
      },
    ) => {
      if (!isEnabledRef.current) return;
      setLastError(undefined);
      setLastUserStopAtMs(null);
      getQueue().speakMany(texts, {
        interrupt: options?.interrupt ?? true,
        preferHtmlAudioFirst: options?.preferHtmlAudioFirst,
        spokenSummaryLine: options?.spokenSummaryLine,
      });
    },
    [getQueue],
  );

  const enqueue = useCallback(
    (text: string) => {
      if (!isEnabledRef.current) return;
      setLastError(undefined);
      setLastUserStopAtMs(null);
      getQueue().enqueue(text);
    },
    [getQueue],
  );

  const drain = useCallback(async () => {
    await getQueue().drain();
  }, [getQueue]);

  const state: UseTtsState = useMemo(
    () => ({
      ...queueUi,
      isEnabled,
      startDelayMs,
      sentenceGapMs,
      autoSpeakAssistant,
      voiceSpeed,
      elevenLabsVoiceId,
      elevenLabsVoiceName,
      voices,
      voicesSource,
      voicesAllowlistMode,
      voicesWarnings,
      voicesStatus,
      voicesError,
      lastError,
      lastLatency,
      lastVoiceNote,
      lastPlaybackWallMs,
      lastUserStopAtMs,
    }),
    [
      queueUi,
      isEnabled,
      startDelayMs,
      sentenceGapMs,
      autoSpeakAssistant,
      voiceSpeed,
      elevenLabsVoiceId,
      elevenLabsVoiceName,
      voices,
      voicesSource,
      voicesAllowlistMode,
      voicesWarnings,
      voicesStatus,
      voicesError,
      lastError,
      lastLatency,
      lastVoiceNote,
      lastPlaybackWallMs,
      lastUserStopAtMs,
    ],
  );

  return {
    state,
    speak,
    speakMany,
    enqueue,
    stop,
    ensureAudioUnlocked,
    prime,
    drain,
    setEnabled,
    toggleEnabled,
    setStartDelayMs,
    setSentenceGapMs,
    setAutoSpeakAssistant,
    toggleAutoSpeakAssistant,
    setVoiceSpeed,
    refreshElevenLabsVoices,
    setElevenLabsVoiceFromPicker,
  };
}"use client";

// ── useSpiritVisualViewportVars - iOS Safari keyboard: layout viewport lies, VV doesn’t ─
// > 100dvh is cosplay on mobile WebKit. Drive shell height from visualViewport + rAF coalesce.
// > Keyboard inset state is effect-only — safe for SSR (starts at 0).
import { type RefObject, useEffect, useRef, useState } from "react";

export type SpiritVisualViewportVarTarget = RefObject<HTMLElement | null>;

export type SpiritVisualViewportMetrics = {
  /** Rounded px; updated from visualViewport inside useEffect only. */
  keyboardInsetPx: number;
};

/**
 * Paints CSS custom properties on `ref.current` for mobile keyboard-safe layouts.
 * - `--spirit-visual-viewport-height` — `visualViewport.height` when keyboard is open; when the
 *   keyboard lane is idle, **pinned to `window.innerHeight`** (same as vv on stable loads, but
 *   we stop listening to VV resize/scroll so iOS PTR rubber-band cannot spam `apply()`).
 * - `--spirit-keyboard-inset` — max(0, layout height − visible height − vv.offsetTop)
 * - `--spirit-visual-offset-top` — raw offset **clamped to 0** when keyboard lane is idle
 *
 * **PTR / rubber-band:** (1) `visualViewport` `resize`/`scroll` listeners stay detached while the
 * keyboard lane is idle. (2) Inset must stay ≥ 14px for **50ms** before we treat the lane as
 * active (ignores one-frame PTR spikes). (3) Identical CSS triple + lane state skips redundant
 * `setProperty` when `window.resize` fires in a tight loop.
 */
export function useSpiritVisualViewportVars(
  ref: SpiritVisualViewportVarTarget,
  enabled = true,
): SpiritVisualViewportMetrics {
  const [keyboardInsetPx, setKeyboardInsetPx] = useState(0);
  const lastInsetRef = useRef(0);

  useEffect(() => {
    if (!enabled || typeof window === "undefined") return;
    const el = ref.current;
    if (!el) return;

    const vv = window.visualViewport ?? null;
    let raf = 0;
    let vvListenersAttached = false;
    /** Sustained inset before we treat the keyboard lane as active (avoids PTR spikes). */
    let keyboardLaneActive = false;
    let armKbTimer: number | null = null;
    let lastStyleTriple = "";

    const clearKbArmTimer = () => {
      if (armKbTimer != null) {
        window.clearTimeout(armKbTimer);
        armKbTimer = null;
      }
    };

    const schedule = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(apply);
    };

    const onWinResize = () => schedule();
    const onOrientation = () => schedule();
    const onFocusIn = () => schedule();
    const onFocusOut = () => schedule();
    const onVvResize = () => schedule();
    const onVvScroll = () => schedule();

    const setVvListeners = (laneIdle: boolean) => {
      if (!vv) return;
      if (laneIdle && vvListenersAttached) {
        vv.removeEventListener("resize", onVvResize);
        vv.removeEventListener("scroll", onVvScroll);
        vvListenersAttached = false;
      } else if (!laneIdle && !vvListenersAttached) {
        vv.addEventListener("resize", onVvResize);
        vv.addEventListener("scroll", onVvScroll);
        vvListenersAttached = true;
      }
    };

    function apply() {
      const node = ref.current;
      if (!node) return;
      const innerH = window.innerHeight;
      let vh = innerH;
      let offsetTop = 0;
      let keyboardInset = 0;
      let rawOffsetTop = 0;
      if (vv) {
        vh = vv.height;
        rawOffsetTop = vv.offsetTop;
        keyboardInset = Math.max(0, innerH - vh - rawOffsetTop);
        offsetTop = keyboardInset < 14 ? 0 : rawOffsetTop;
      }

      // ── Keyboard lane hysteresis: PTR can briefly inflate inset without a real keyboard.
      // Require inset ≥ 14 for 50ms before attaching VV / switching to vv.height paint path.
      if (keyboardInset < 14) {
        clearKbArmTimer();
        if (keyboardLaneActive) {
          keyboardLaneActive = false;
        }
      } else if (!keyboardLaneActive && armKbTimer == null) {
        armKbTimer = window.setTimeout(() => {
          armKbTimer = null;
          if (!vv) return;
          const ih = window.innerHeight;
          const insNow = Math.max(0, ih - vv.height - vv.offsetTop);
          if (insNow >= 14) {
            keyboardLaneActive = true;
            schedule();
          }
        }, 50);
      }

      const keyboardLaneIdle = !keyboardLaneActive;
      const paintVh = keyboardLaneIdle ? innerH : vh;

      const styleTriple = `${paintVh}|${keyboardInset}|${offsetTop}|${keyboardLaneActive ? 1 : 0}`;
      if (styleTriple === lastStyleTriple) {
        return;
      }
      lastStyleTriple = styleTriple;

      node.style.setProperty("--spirit-visual-viewport-height", `${paintVh}px`);
      node.style.setProperty("--spirit-keyboard-inset", `${keyboardInset}px`);
      node.style.setProperty("--spirit-visual-offset-top", `${offsetTop}px`);

      setVvListeners(keyboardLaneIdle);

      const rounded = Math.round(keyboardInset);
      if (rounded !== lastInsetRef.current) {
        lastInsetRef.current = rounded;
        setKeyboardInsetPx(rounded);
      }
    }

    window.addEventListener("resize", onWinResize);
    window.addEventListener("orientationchange", onOrientation);
    document.addEventListener("focusin", onFocusIn);
    document.addEventListener("focusout", onFocusOut);

    schedule();

    return () => {
      clearKbArmTimer();
      cancelAnimationFrame(raf);
      if (vv && vvListenersAttached) {
        vv.removeEventListener("resize", onVvResize);
        vv.removeEventListener("scroll", onVvScroll);
        vvListenersAttached = false;
      }
      window.removeEventListener("resize", onWinResize);
      window.removeEventListener("orientationchange", onOrientation);
      document.removeEventListener("focusin", onFocusIn);
      document.removeEventListener("focusout", onFocusOut);
    };
  }, [ref, enabled]);

  return { keyboardInsetPx };
}import type { ClusterNodeTelemetry } from "./types";

/** Remote Windows agent runs synchronous PowerShell (multi-drive); sub-3s fetch timeouts falsely mark nodes offline. */
const REMOTE_TIMEOUT_MS = 12_000;

function offlineNode(
  id: string,
  label: string,
  telemetryUrl: string | undefined,
  error: string,
): ClusterNodeTelemetry {
  return {
    id,
    label,
    hostname: null,
    status: "offline",
    source: "remote",
    telemetryUrl,
    platform: null,
    arch: null,
    cpu: { model: null, cores: null, usagePct: null, loadAvg: null },
    memory: { totalBytes: null, freeBytes: null, usedBytes: null, usedPct: null },
    uptimeSec: null,
    collectedAt: new Date().toISOString(),
    error,
  };
}

/** Returns null if JSON matches minimal remote contract; otherwise a human-readable reason. */
function getRemoteTelemetryValidationError(data: unknown): string | null {
  if (!data || typeof data !== "object") {
    return "invalid response: body not a JSON object";
  }
  const d = data as Record<string, unknown>;
  const missing: string[] = [];
  if (typeof d.id !== "string") missing.push("id");
  if (typeof d.status !== "string") missing.push("status");
  if (typeof d.collectedAt !== "string") missing.push("collectedAt");
  if (missing.length > 0) {
    return `invalid response: missing ${missing.join(", ")}`;
  }
  return null;
}

export async function fetchRemoteNodeTelemetry(
  id: string,
  label: string,
  telemetryUrl: string | undefined,
): Promise<ClusterNodeTelemetry> {
  if (!telemetryUrl) {
    return offlineNode(id, label, undefined, "not configured");
  }

  // Mirror scripts/spiritdesktop-windows/agent.js default so Dell reaches auth without extra .env.
  const token = process.env.SPIRIT_TELEMETRY_TOKEN?.trim() || "3399";
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REMOTE_TIMEOUT_MS);

  try {
    const res = await fetch(telemetryUrl, {
      cache: "no-store",
      signal: controller.signal,
      headers: { Authorization: `Bearer ${token}` },
    });

    clearTimeout(timer);

    if (!res.ok) {
      return offlineNode(id, label, telemetryUrl, `HTTP ${res.status}`);
    }

    const data: unknown = await res.json();

    const validationErr = getRemoteTelemetryValidationError(data);
    if (validationErr) {
      return offlineNode(id, label, telemetryUrl, validationErr);
    }

    const node = data as ClusterNodeTelemetry;
    // Preserve optional fields (e.g. storage) - do not hand-rebuild the node without them.
    return {
      ...node,
      id: node.id || id,
      label: node.label || label,
      telemetryUrl,
      source: "remote",
      storage: node.storage,
    };
  } catch (err) {
    clearTimeout(timer);
    const name = err instanceof Error ? err.name : "";
    const message =
      name === "AbortError" ? "timeout" : "unreachable";
    return offlineNode(id, label, telemetryUrl, message);
  }
}import "server-only";

import { createUIMessageStream, createUIMessageStreamResponse } from "ai";
import type { UIMessage } from "ai";

import type {
  SpiritAssistantMessageMetadata,
  SpiritToolActivityCard,
} from "@/lib/spirit/spirit-activity-events";
import { sanitizeForHttpByteStringHeader } from "@/lib/server/spirit-search-telemetry";

/** Same UI stream framing as LLM path - useChat / Oracle stay happy */
export function createDeterministicAssistantUIMessageResponse(opts: {
  text: string;
  originalMessages: UIMessage[];
  headers?: HeadersInit;
  /** Compact tool/workspace telemetry for assistant message metadata + optional headers */
  toolActivity?: SpiritToolActivityCard[];
}): Response {
  const body = opts.text;
  const meta: SpiritAssistantMessageMetadata | undefined =
    opts.toolActivity && opts.toolActivity.length > 0
      ? { spiritToolActivity: opts.toolActivity }
      : undefined;

  const stream = createUIMessageStream({
    originalMessages: opts.originalMessages,
    execute: ({ writer }) => {
      writer.write({ type: "start" });
      writer.write({ type: "start-step" });
      const textId = "text-1";
      writer.write({ type: "text-start", id: textId });
      writer.write({ type: "text-delta", id: textId, delta: body });
      writer.write({ type: "text-end", id: textId });
      writer.write({ type: "finish-step" });
      writer.write({
        type: "finish",
        finishReason: "stop",
        messageMetadata: meta,
      });
    },
  });

  const headers = new Headers(opts.headers ?? undefined);
  if (opts.toolActivity && opts.toolActivity.length > 0) {
    headers.set(
      "x-spirit-tool-activity-json",
      sanitizeForHttpByteStringHeader(JSON.stringify(opts.toolActivity)),
    );
  }

  return createUIMessageStreamResponse({
    stream,
    headers,
  });
}import "server-only";

import type { UIMessage } from "ai";

import { ApiError } from "@/lib/server/api-errors";
import {
  parseSpiritChatRequestBody,
  SpiritRequestValidationError,
} from "@/lib/spirit/spirit-chat-request-body";
