export type SpiritRequestBody = {
  messages: UIMessage[];
  modelProfileId: ModelProfileId;
  runtimeSurface: SpiritRuntimeSurface;
  personalizationSummary?: string;
  deepThinkEnabled: boolean;
  webSearchOptOut: boolean;
  teacherWebSearchEnabled: boolean;
  researchPlanSummary?: string;
  oracleMemoryContext?: string;
};

export async function readSpiritRequest(req: Request): Promise<SpiritRequestBody> {
  let body: unknown;

  try {
    body = await req.json();
  } catch {
    throw new ApiError(400, "Invalid JSON body");
  }

  try {
    return parseSpiritChatRequestBody(body);
  } catch (e) {
    if (e instanceof SpiritRequestValidationError) {
      throw new ApiError(e.status, e.message);
    }
    throw e;
  }
}import "server-only";

// ── spirit-search-telemetry - [spirit-search] logs + response headers (Prompt 10C-D) ─
// > No secrets, no full prompts - trimmed query only.

export type SpiritSearchLogRoute =
  | "openai-web-search"
  | "local-web-search"
  | "teacher-web-aids"
  | "research-plan"
  | "local-chat"
  | "none";

export type SpiritSearchLogEvent = {
  route: SpiritSearchLogRoute;
  status: "starting" | "used" | "failed" | "skipped" | "disabled";
  mode: "researcher" | "teacher" | "other";
  queryTrimmed: string;
  provider?: string;
  sources?: number;
  elapsedMs?: number;
  reason?: string;
};

const QUERY_LOG_MAX = 160;

/** HTTP response headers must be ByteString (per-byte ≤255). No Unicode ellipsis in trim output. */
export function trimSearchQueryForLog(q: string): string {
  const t = q.replace(/\s+/g, " ").trim();
  if (t.length <= QUERY_LOG_MAX) return t;
  return `${t.slice(0, QUERY_LOG_MAX)}...`;
}

/** WHATWG ByteString / ISO-8859-1 header values: code points > U+00FF are invalid (8230 = … blows up). */
export function sanitizeForHttpByteStringHeader(value: string): string {
  let out = "";
  for (const ch of value) {
    const cp = ch.codePointAt(0)!;
    if (cp === 0x2026) {
      out += "...";
      continue;
    }
    if (cp <= 0xff) {
      if (cp === 9 || cp === 10 || cp === 13) out += " ";
      else if (cp < 32) out += " ";
      else out += String.fromCodePoint(cp);
    } else {
      out += "?";
    }
  }
  return out;
}

export function logSpiritSearchEvent(ev: SpiritSearchLogEvent): void {
  const parts = [
    `[spirit-search]`,
    `route=${ev.route}`,
    `status=${ev.status}`,
    `mode=${ev.mode}`,
    `query="${ev.queryTrimmed.replace(/"/g, '\\"')}"`,
  ];
  if (ev.provider) parts.push(`provider=${ev.provider}`);
  if (typeof ev.sources === "number") parts.push(`sources=${ev.sources}`);
  if (typeof ev.elapsedMs === "number") parts.push(`elapsedMs=${ev.elapsedMs}`);
  if (ev.reason) parts.push(`reason="${ev.reason.replace(/"/g, '\\"')}"`);
  console.log(parts.join(" "));
}

export function normalizeSearchStatus(
  raw: string | null | undefined,
): "used" | "skipped" | "failed" | "disabled" | "none" {
  const s = (raw ?? "none").trim().toLowerCase();
  if (s === "used") return "used";
  if (s === "failed") return "failed";
  if (s === "disabled") return "disabled";
  if (s === "skipped") return "skipped";
  return "none";
}

export type SpiritSearchHeaderInput = {
  routeLane: string;
  routeConfidence: string;
  webSearch: string;
  searchStatus: string;
  provider: string | null;
  sourceCount: number;
  queryTrimmed: string;
  elapsedMs: number | null;
  searchKind: "researcher" | "teacher" | "none";
  skipReason?: string | null;
  webSourcesJson: string | null;
};

export function buildSpiritSearchHeaders(input: SpiritSearchHeaderInput): Record<string, string> {
  const h: Record<string, string> = {
    "x-spirit-route-lane": input.routeLane,
    "x-spirit-route-confidence": input.routeConfidence,
    "x-spirit-web-search": input.webSearch,
    "x-spirit-search-status": input.searchStatus,
    "x-spirit-source-count": String(input.sourceCount),
    "x-spirit-search-query": input.queryTrimmed.slice(0, 200),
    "x-spirit-search-kind": input.searchKind,
  };
  if (input.provider) h["x-spirit-search-provider"] = input.provider;
  if (input.elapsedMs != null && Number.isFinite(input.elapsedMs)) {
    h["x-spirit-search-elapsed-ms"] = String(Math.round(input.elapsedMs));
  }
  if (input.skipReason?.trim()) {
    h["x-spirit-search-skip-reason"] = input.skipReason.trim().slice(0, 120);
  }
  if (input.webSourcesJson) h["x-spirit-web-sources"] = input.webSourcesJson;

  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(h)) {
    const s = sanitizeForHttpByteStringHeader(v);
    out[k] = s;
  }
  return out;
}import "server-only";

import type { ModelProfileId } from "@/lib/spirit/model-profile.types";
import { shouldPrefetchOpenAiWebForResearcher } from "@/lib/spirit/spirit-route-decision";
import { resolveVerifiedHttpUrl } from "@/lib/verified-http-url";

type ResearchWebSearchResult =
  | {
      ok: true;
      provider: string;
      query?: string;
      searched: true;
      sources: Array<{ title?: string; url?: string; snippet?: string }>;
      answerPreview?: string;
    }
  | {
      ok: false;
      provider: string;
      searched: boolean;
      error: string;
      detail?: string;
    };

export function isWebSearchGloballyEnabled(): boolean {
  const v = process.env.WEB_SEARCH_ENABLED?.trim().toLowerCase();
  return v === "1" || v === "true" || v === "yes";
}

/** Hermes researcher lane - thin wrapper for diagnostics/tests. */
export function shouldRunResearcherWebSearch(opts: {
  modelProfileId: ModelProfileId;
  lastUserText: string;
  webSearchOptOut?: boolean;
}): boolean {
  return shouldPrefetchOpenAiWebForResearcher({
    modelProfileId: opts.modelProfileId,
    lastUserText: opts.lastUserText,
    webSearchOptOut: opts.webSearchOptOut,
    webSearchGloballyEnabled: isWebSearchGloballyEnabled(),
  });
}

export function formatResearchSkippedBanner(reason: string): string {
  return `## Web research status
Search used: no (${reason})
No verified external sources were available for this response.
Do not claim you ran a web search. Do **not** add [1], [2], numbered citations, **## Sources**, or **## References**. Answer as **Unverified background** only; if live facts are uncertain, say so.`;
}

function providerLabel(provider: string): string {
  if (provider === "searxng") return "SearXNG";
  if (provider === "fetch") return "direct fetch";
  if (provider === "cache") return "cache";
  if (provider === "openai") return "OpenAI";
  if (provider === "manual") return "manual";
  return provider;
}

export function formatResearchContextForHermes(query: string, search: ResearchWebSearchResult): string {
  if (!search.ok || !search.searched) {
    return `## Web research status
Search used: no (${"error" in search ? search.error : "unknown"}${"detail" in search && search.detail ? ` - ${search.detail}` : ""})
Answer from general knowledge only; label uncertain claims as unverified.`;
  }

  type DigestRow = { title: string; url: string; snippet?: string };
  const withUrls: DigestRow[] = [];
  for (const s of search.sources) {
    const url = resolveVerifiedHttpUrl(s.url);
    if (!url) continue;
    withUrls.push({
      title: s.title?.trim() || "Untitled",
      url,
      ...(s.snippet?.trim() ? { snippet: s.snippet.trim() } : {}),
    });
  }

  if (withUrls.length === 0) {
    return `## Web research status
Search used: yes (provider: ${providerLabel(search.provider)}) but **no verified external URLs** were returned for this query.
Do not invent URLs or paper titles. If the user asked for recent studies or other time-bounded claims, say you **cannot verify** without attached sources.
User query: ${query.slice(0, 800)}`;
  }

  const lines = withUrls.map((row, i) => {
    const sn = row.snippet ? ` - snippet: ${row.snippet.slice(0, 320)}` : "";
    return `${i + 1}. **${row.title}** | url: ${row.url}${sn}`;
  });

  const preview = search.answerPreview?.trim()
    ? `\nProvider preview (trimmed; verify before citing):\n${search.answerPreview.trim().slice(0, 2000)}`
    : "";

  return `## Web research digest
Provider: ${providerLabel(search.provider)}
Search used: yes
User query: ${query.slice(0, 800)}
Verified URL sources (${withUrls.length}):
${lines.join("\n")}
${preview}

Instructions: Only claim facts supported by the digest above. Use [n](url) inline only for URLs listed. Your final answer must include **## Sources** with those same URLs. If the user asked for recent studies and this digest is empty of usable links, say you cannot verify that request.`;
}

/** Compact JSON for `x-spirit-web-sources` - keep under typical proxy header limits. */
export function buildWebSearchSourcesHeader(search: ResearchWebSearchResult): string | null {
  if (!search.ok || !search.searched) return null;
  const items: { title: string; url: string; snippet: string }[] = [];
  for (const s of search.sources) {
    const url = resolveVerifiedHttpUrl(s.url);
    if (!url) continue;
    items.push({
      title: (s.title ?? "").trim().slice(0, 180),
      url: url.slice(0, 900),
      snippet: (s.snippet ?? "").trim().slice(0, 240),
    });
    if (items.length >= 10) break;
  }
  let payload = {
    provider: search.provider,
    count: items.length,
    sources: items,
  };
  let json = JSON.stringify(payload);
  while (json.length > 3600 && payload.sources.length > 1) {
    payload = {
      ...payload,
      sources: payload.sources.slice(0, -1),
    };
    json = JSON.stringify(payload);
  }
  return json.length > 4000 ? null : json;
}import { describe, expect, it } from "vitest";

import { getModelProfile, isModelProfileId, MODEL_PROFILES } from "@/lib/spirit/model-profiles";
import { DEFAULT_MODEL_PROFILE_ID } from "@/lib/spirit/model-profile.types";

describe("model-profiles", () => {
  it("Peer shortLabel and researcher flags", () => {
    expect(MODEL_PROFILES["normal-peer"].shortLabel).toBe("Peer");
    expect(MODEL_PROFILES["normal-peer"].label).toBe("Peer");
    expect(MODEL_PROFILES.researcher.searchPreferred).toBe(true);
    expect(MODEL_PROFILES.researcher.requiresCitationStyle).toBe(true);
    expect(MODEL_PROFILES.researcher.reportStyle).toBe(true);
  });

  it("Peer profile does not brand itself as a coding assistant by default", () => {
    const p = MODEL_PROFILES["normal-peer"].systemPrompt;
    expect(p).not.toMatch(/\bcoding assistant\b/i);
    expect(p).toContain("You are Spirit in Peer mode");
  });

  it("Peer profile describes concise conversational behavior", () => {
    expect(MODEL_PROFILES["normal-peer"].systemPrompt).toMatch(/1 to 4 sentences|casual replies short/i);
  });

  it("Peer profile reserves technical help for when user asks", () => {
    expect(MODEL_PROFILES["normal-peer"].systemPrompt).toMatch(
      /technical, coding, or build help|asks for technical/i,
    );
  });

  it("mode prompts differ between Peer and Teacher", () => {
    expect(MODEL_PROFILES["normal-peer"].systemPrompt).toContain("Peer mode");
    expect(MODEL_PROFILES.teacher.systemPrompt).toContain("Teacher mode");
    expect(MODEL_PROFILES["normal-peer"].systemPrompt).not.toContain("Teacher mode");
  });

  it("brutal and sassy summaries exist", () => {
    expect(MODEL_PROFILES.brutal.responseStyleSummary.length).toBeGreaterThan(2);
    expect(MODEL_PROFILES["sassy-chaotic"].responseStyleSummary.length).toBeGreaterThan(2);
  });

  it("returns normal-peer for missing id", () => {
    expect(getModelProfile(undefined).id).toBe(DEFAULT_MODEL_PROFILE_ID);
    expect(getModelProfile(null).id).toBe(DEFAULT_MODEL_PROFILE_ID);
  });

  it("returns normal-peer for invalid id", () => {
    expect(getModelProfile("nope").id).toBe(DEFAULT_MODEL_PROFILE_ID);
  });

  it("researcher temperature is 0.28", () => {
    expect(MODEL_PROFILES.researcher.temperature).toBe(0.28);
  });

  it("sassy-chaotic temperature is 1.05", () => {
    expect(MODEL_PROFILES["sassy-chaotic"].temperature).toBe(1.05);
  });

  it("isModelProfileId narrows union", () => {
    expect(isModelProfileId("teacher")).toBe(true);
    expect(isModelProfileId(1)).toBe(false);
  });

  it("researcher system prompt forbids invented citations", () => {
    expect(MODEL_PROFILES.researcher.systemPrompt).toMatch(/Never invent citations/i);
  });

  it("normal-peer explicitly allows technical depth for code, repo, and homelab questions", () => {
    const p = MODEL_PROFILES["normal-peer"].systemPrompt;
    expect(p).toMatch(/enough structure and detail|technical.*enough structure/i);
  });

  it("normal-peer does not hard-block technical framing, only casual defaults", () => {
    const p = MODEL_PROFILES["normal-peer"].systemPrompt;
    expect(p).toMatch(/When the user actually asks for coding|asks for coding, repo/i);
  });
});import { afterEach, describe, expect, it, vi } from "vitest";

