import {
  getSpiritDevCommandTools,
  getSpiritReadOnlyTools,
  getSpiritToolsForRuntime,
  isLocalToolsEnabled,
  spiritToolsetIncludesRunDevCommand,
} from "../tool-registry";

describe("tool-registry", () => {
  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it("disabled env returns undefined or no tools", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "false");
    expect(isLocalToolsEnabled()).toBe(false);
    expect(getSpiritToolsForRuntime()).toBeUndefined();
    expect(getSpiritReadOnlyTools()).toBeUndefined();
  });

  it("SPIRIT_ENABLE_LOCAL_TOOLS=true returns exactly four tools when dev commands off", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "true");
    vi.stubEnv("SPIRIT_ENABLE_DEV_COMMAND_TOOLS", "false");
    const tools = getSpiritToolsForRuntime();
    expect(tools).toBeDefined();
    if (!tools) throw new Error("tools");
    expect(Object.keys(tools).sort()).toEqual(
      [
        "get_system_status",
        "list_workspace_files",
        "read_log_tail",
        "read_workspace_file",
      ].sort(),
    );
  });

  it("includes expected tool keys and excludes forbidden keys", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "true");
    vi.stubEnv("SPIRIT_ENABLE_DEV_COMMAND_TOOLS", "false");
    const tools = getSpiritReadOnlyTools();
    expect(tools).toBeDefined();
    if (!tools) throw new Error("tools");
    expect(tools).toHaveProperty("list_workspace_files");
    expect(tools).toHaveProperty("read_workspace_file");
    expect(tools).toHaveProperty("read_log_tail");
    expect(tools).toHaveProperty("get_system_status");
    expect(tools).not.toHaveProperty("file_editing");
    expect(tools).not.toHaveProperty("terminal_execution");
    expect(tools).not.toHaveProperty("email_access");
    expect(tools).not.toHaveProperty("calendar_access");
  });

  it("returns undefined when Ollama tool transport is not opted in", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "false");
    expect(getSpiritToolsForRuntime()).toBeUndefined();
  });

  it("SPIRIT_ENABLE_FILE_EDIT_TOOLS=true adds propose_file_edit and apply_confirmed_file_edit", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "true");
    vi.stubEnv("SPIRIT_ENABLE_DEV_COMMAND_TOOLS", "false");
    vi.stubEnv("SPIRIT_ENABLE_FILE_EDIT_TOOLS", "true");
    const tools = getSpiritToolsForRuntime();
    expect(tools).toBeDefined();
    if (!tools) throw new Error("tools");
    expect(Object.keys(tools).sort()).toEqual(
      [
        "apply_confirmed_file_edit",
        "get_system_status",
        "list_workspace_files",
        "propose_file_edit",
        "read_log_tail",
        "read_workspace_file",
      ].sort(),
    );
    expect(tools).not.toHaveProperty("execute_bash");
    expect(tools).not.toHaveProperty("terminal_execution");
  });

  it("SPIRIT_ENABLE_DEV_COMMAND_TOOLS=true adds run_dev_command when local tools enabled", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "true");
    vi.stubEnv("SPIRIT_ENABLE_DEV_COMMAND_TOOLS", "true");
    const tools = getSpiritToolsForRuntime();
    expect(tools).toBeDefined();
    if (!tools) throw new Error("tools");
    expect(Object.keys(tools)).toContain("run_dev_command");
    expect(spiritToolsetIncludesRunDevCommand(tools)).toBe(true);
    expect(tools).not.toHaveProperty("execute_bash");
    expect(tools).not.toHaveProperty("execute_shell");
  });

  it("SPIRIT_ENABLE_DEV_COMMAND_TOOLS=false does not include run_dev_command", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "true");
    vi.stubEnv("SPIRIT_ENABLE_DEV_COMMAND_TOOLS", "false");
    const tools = getSpiritToolsForRuntime();
    expect(tools).toBeDefined();
    if (!tools) throw new Error("tools");
    expect(tools).not.toHaveProperty("run_dev_command");
    expect(getSpiritDevCommandTools()).toEqual({});
  });

  it("SPIRIT_WINDOWS_FS_ENABLED=true adds list_windows_files", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "true");
    vi.stubEnv("SPIRIT_ENABLE_DEV_COMMAND_TOOLS", "false");
    vi.stubEnv("SPIRIT_WINDOWS_FS_ENABLED", "true");
    const tools = getSpiritToolsForRuntime();
    expect(tools).toBeDefined();
    if (!tools) throw new Error("tools");
    expect(tools).toHaveProperty("list_windows_files");
  });

  it("file edit tools still merge when dev commands also enabled", () => {
    vi.stubEnv("SPIRIT_ENABLE_LOCAL_TOOLS", "true");
    vi.stubEnv("SPIRIT_OLLAMA_SUPPORTS_TOOLS", "true");
    vi.stubEnv("SPIRIT_ENABLE_DEV_COMMAND_TOOLS", "true");
    vi.stubEnv("SPIRIT_ENABLE_FILE_EDIT_TOOLS", "true");
    const tools = getSpiritToolsForRuntime();
    expect(tools).toBeDefined();
    if (!tools) throw new Error("tools");
    expect(tools).toHaveProperty("propose_file_edit");
    expect(tools).toHaveProperty("run_dev_command");
  });
});// ── tool-registry - AI SDK read-only tools gated by SPIRIT_ENABLE_LOCAL_TOOLS ──
// > Also requires SPIRIT_OLLAMA_SUPPORTS_TOOLS=true: Hermes4 and many registry pulls
// > reject requests with tools ("does not support tools"); opt in after switching models.

import { tool } from "ai";
import { z } from "zod";

import { toolErrorFromUnknown } from "@/lib/spirit/tools/tool-safety";
import { probeOllamaChatCompletionsAcceptsToolSchema } from "@/lib/server/ollama";
import {
  proposeFileEdit,
  applyConfirmedFileEdit,
  isFileEditToolsEnvEnabled,
} from "@/lib/spirit/tools/file-edit-tools";
import {
  getAllowedDevCommandIds,
  isDevCommandToolsEnvEnabled,
  runDevCommand,
  type DevCommandId,
} from "@/lib/spirit/tools/dev-command-tools";
import {
  getSystemStatus,
  listWorkspaceFiles,
  readLogTail,
  readWorkspaceFile,
} from "@/lib/spirit/tools/workspace-tools";
import { isWindowsFsEnabled, listWindowsFiles } from "@/lib/spirit/tools/windows-workspace-tools";

export { isFileEditToolsEnvEnabled, isDevCommandToolsEnvEnabled };

/** True when streamText received run_dev_command from resolveSpiritToolsForOllamaModel. */
export function spiritToolsetIncludesRunDevCommand(
  tools: Record<string, unknown> | undefined | null,
): boolean {
  return Boolean(tools && typeof tools === "object" && "run_dev_command" in tools);
}

export function isLocalToolsEnabled(): boolean {
  return process.env.SPIRIT_ENABLE_LOCAL_TOOLS === "true";
}

/** Ollama OpenAI-compat must accept tools on /v1/chat/completions (many models do not). */
export function isOllamaToolTransportReady(): boolean {
  return process.env.SPIRIT_OLLAMA_SUPPORTS_TOOLS === "true";
}

export function getSpiritReadOnlyTools() {
  if (!isLocalToolsEnabled()) return undefined;
  if (!isOllamaToolTransportReady()) return undefined;

  return {
    list_workspace_files: tool({
      description:
        "List files and folders in a workspace-relative directory (non-recursive). Sensitive or blocked entries are omitted.",
      inputSchema: z.object({
        directory: z
          .string()
          .optional()
          .describe('Workspace-relative directory; default is ".".'),
        maxEntries: z
          .number()
          .optional()
          .describe("Maximum entries (default 80, hard cap 200)."),
      }),
      execute: async (input) => {
        try {
          return await listWorkspaceFiles(input);
        } catch (e) {
          return toolErrorFromUnknown(e);
        }
      },
    }),
    read_workspace_file: tool({
      description:
        "Read a UTF-8 text file from the workspace (max 120 KB file size on disk; tool output may truncate at 20 KB).",
      inputSchema: z.object({
        filePath: z.string().describe("Workspace-relative path to the file."),
      }),
      execute: async (input) => {
        try {
          return await readWorkspaceFile(input);
        } catch (e) {
          return toolErrorFromUnknown(e);
        }
      },
    }),
    read_log_tail: tool({
      description:
        "Return the last lines of a UTF-8 log file (default 80 lines, max 300; output capped at 20 KB characters).",
      inputSchema: z.object({
        filePath: z.string().describe("Workspace-relative path to the log file."),
        lineCount: z
          .number()
          .optional()
          .describe("How many trailing lines to return."),
      }),
      execute: async (input) => {
        try {
          return await readLogTail(input);
        } catch (e) {
          return toolErrorFromUnknown(e);
        }
      },
    }),
    get_system_status: tool({
      description:
        "Summarize whether local read-only Spirit tools are enabled and which capabilities remain unavailable. Never returns raw absolute filesystem paths.",
      inputSchema: z.object({}),
      execute: async () => {
        try {
          return await getSystemStatus();
        } catch (e) {
          return toolErrorFromUnknown(e);
        }
      },
    }),
    ...(isWindowsFsEnabled()
      ? {
          list_windows_files: tool({
            description:
              "List files and folders in an allowlisted Windows absolute path via the SpiritDesktop filesystem bridge. Read-only, non-recursive, and never browses arbitrary drives.",
            inputSchema: z.object({
              path: z.string().describe("Windows absolute path such as C:\\Projects."),
              maxEntries: z
                .number()
                .optional()
                .describe("Maximum entries (default 200, hard cap 200)."),
            }),
            execute: async (input) => {
              try {
                return await listWindowsFiles(input);
              } catch (e) {
                return toolErrorFromUnknown(e);
              }
            },
          }),
        }
      : {}),
  };
}

export function getSpiritDevCommandTools() {
  if (!isLocalToolsEnabled()) return {};
  if (!isOllamaToolTransportReady()) return {};
  if (!isDevCommandToolsEnvEnabled()) return {};

  const allowed = getAllowedDevCommandIds();
  if (allowed.length === 0) return {};

  const idsTuple = allowed as [DevCommandId, ...DevCommandId[]];

  return {
    run_dev_command: tool({
      description:
        "Runs only fixed allowlisted development commands by commandId. Does not accept shell strings. Does not install packages. Does not mutate workspace source files except typical build or test caches. npm_test and npm_build require confirm: true before execution.",
      inputSchema: z.object({
        commandId: z.enum(idsTuple),
        confirm: z
          .boolean()
          .optional()
          .describe("Must be true when the command requires explicit user confirmation."),
      }),
      execute: async (input) => {
        try {
          return await runDevCommand(input);
        } catch (e) {
          return toolErrorFromUnknown(e);
        }
      },
    }),
  };
}

function getSpiritFileEditTools() {
  if (!isFileEditToolsEnvEnabled()) return {};
  return {
    propose_file_edit: tool({
      description:
        "Stage a workspace file edit for review only. Computes a diff against the current file and stores a proposal. Never writes to disk. The user must approve; apply only via apply_confirmed_file_edit with confirm true.",
      inputSchema: z.object({
        filePath: z.string().describe("Workspace-relative path to the file."),
        nextContent: z.string().describe("Full replacement UTF-8 text for the file."),
        reason: z.string().optional().describe("Short note on why this edit is suggested."),
      }),
      execute: async (input) => {
        try {
          return await proposeFileEdit(input);
        } catch (e) {
          return toolErrorFromUnknown(e);
        }
      },
    }),
    apply_confirmed_file_edit: tool({
      description:
        "Apply a previously stored proposal only when confirm is true and the user explicitly approved this proposal id. Creates a backup before overwriting. Rejects if the file changed since proposal.",
      inputSchema: z.object({
        proposalId: z.string().describe("Id returned by propose_file_edit."),
        confirm: z
          .boolean()
          .describe("Must be true to apply; false is rejected."),
      }),
      execute: async (input) => {
        try {
          return await applyConfirmedFileEdit(input);
        } catch (e) {
          return toolErrorFromUnknown(e);
        }
      },
    }),
  };
}

export function getSpiritToolsForRuntime() {
  const readOnly = getSpiritReadOnlyTools();
  if (!readOnly) return undefined;
  return { ...readOnly, ...getSpiritFileEditTools(), ...getSpiritDevCommandTools() };
}

const modelToolSchemaSupported = new Map<string, boolean>();

/** Clears per-model probe cache (tests only). */
export function clearReadOnlyToolProbeCache(): void {
  modelToolSchemaSupported.clear();
}

/**
 * Returns read-only tools only when env flags allow and Ollama accepts a tools payload for this model.
 * Result is cached per model id for the lifetime of the Node process.
 */
export async function resolveSpiritToolsForOllamaModel(
  modelId: string,
): Promise<ReturnType<typeof getSpiritToolsForRuntime>> {
  const tools = getSpiritToolsForRuntime();
  if (!tools) return undefined;

  const cached = modelToolSchemaSupported.get(modelId);
  if (cached === false) return undefined;
  if (cached === true) return tools;

  let supported = true;
  try {
    supported = await probeOllamaChatCompletionsAcceptsToolSchema(modelId);
  } catch {
    supported = true;
  }
  modelToolSchemaSupported.set(modelId, supported);
  return supported ? tools : undefined;
}// ── assistant-output-sanitizer - kill leaked CoT / mode contracts in user-visible text ─
// > Models sometimes echo training junk. Strip it before render, copy, TTS, or Dexie.

const TAG_PAIRS: Array<[RegExp, string]> = [
  [/<redacted_thinking[^>]*>[\s\S]*?<\/redacted_thinking>/gi, ""],
  [/<thinking[^>]*>[\s\S]*?<\/thinking>/gi, ""],
  [/<chain_of_thought[^>]*>[\s\S]*?<\/chain_of_thought>/gi, ""],
  [/<system[^>]*>[\s\S]*?<\/system>/gi, ""],
  [/<developer[^>]*>[\s\S]*?<\/developer>/gi, ""],
];

const VISIBLE_CONTAINER_TAGS = [
  "chat_message",
  "assistant_message",
  "assistant_response",
  "response",
] as const;

/** Line starts that almost always mean leaked instructions (not user content). */
const LEAK_LINE_STARTS = [
  /^respond in ["']sassy mode["']\s*only\b/i,
  /^respond in ["']sassy mode["']/i,
  /^I'm here to help with coding questions\b/i,
  /^respond in ["']brutal mode["']/i,
  /^keep sentences short\b/i,
  /^no hidden chain[- ]of[- ]thought\b/i,
  /^technical stuff should still be correct\b/i,
  /^answer depth\s*=\s*user'?s message depth\b/i,
  /^mode contract:\s*$/i,
  /^system prompt:\s*$/i,
  /^developer instruction:\s*$/i,
  /^hidden instruction:\s*$/i,
];

function stripTaggedBlocks(text: string): string {
  let t = text;
  for (const [re, rep] of TAG_PAIRS) {
    t = t.replace(re, rep);
  }
  return t;
}

function unwrapVisibleContainerTags(text: string): string {
  let t = text;
  for (const tag of VISIBLE_CONTAINER_TAGS) {
    t = t.replace(new RegExp(`^\\s*<${tag}[^>]*>\\s*`, "i"), "");
    t = t.replace(new RegExp(`\\s*</${tag}>\\s*$`, "i"), "");
  }
  return t;
}

function stripLeakedInstructionLines(text: string): string {
  const lines = text.split("\n");
  const out: string[] = [];
  let skippingLeakRun = false;

  for (const line of lines) {
    const trimmed = line.trim();
    const isLeakStart = LEAK_LINE_STARTS.some((re) => re.test(trimmed));
    if (isLeakStart) {
      skippingLeakRun = true;
      continue;
    }
    if (skippingLeakRun) {
      if (trimmed === "") {
        skippingLeakRun = false;
        continue;
      }
      if (trimmed.startsWith("-") || trimmed.startsWith("•")) {
        continue;
      }
      if (/^respond in\b/i.test(trimmed)) {
        continue;
      }
      skippingLeakRun = false;
    }
    out.push(line);
  }

  return out.join("\n");
}

/**
 * Removes hidden reasoning tags and common leaked mode-contract lines.
 * Conservative: only nukes obvious instruction lines, not every mention of "think".
 */
export function sanitizeAssistantVisibleText(text: string): string {
  if (!text) return "";
  let t = stripTaggedBlocks(text);
  t = unwrapVisibleContainerTags(t);
  t = stripLeakedInstructionLines(t);
  t = t.replace(/\n{3,}/g, "\n\n").trim();
  return t;
}// ── capability-intent - categorized detector for deterministic /api/spirit replies ─
// > Order matters: narrow intents before broad; false negatives beat hijacking normal chat.

export type CapabilityIntentKind =
  | "hardware_summary"
  | "node_status"
  | "storage_status"
  | "dev_commands"
  | "file_access"
  | "desktop_control"
  | "ai_runtime"
  | "tool_inventory"
  | "general_capabilities";

/** Exported for tests - normalizes typos like "capabilites" before pattern matching */
export function normalizeForCapabilityIntent(raw: string): string {
  let s = raw.trim().toLowerCase();
  s = s.replace(/\s+/g, " ");
  // strip decorative wrapping punctuation (keep ? ! . inside phrase)
  s = s.replace(/^[^a-z0-9]+/i, "");
  s = s.replace(/[^a-z0-9?.!]+$/i, "");

  s = s.replace(/\bcapabilites\b/g, "capabilities");
  s = s.replace(/\bcapabilties\b/g, "capabilities");
  s = s.replace(/\bcapibility\b/g, "capabilities");
  s = s.replace(/\bcapabilty\b/g, "capabilities");
  s = s.replace(/\bcapabilitiy\b/g, "capabilities");
  s = s.replace(/\babilites\b/g, "abilities");

  return s.trim();
}

/** Avoid matching “what can you see wrong with this” - only pure capability asks */
function isStandaloneWhatCanYouSeeOrControl(t: string): boolean {
  return (
    /^(what\s+can\s+you\s+see)(\s*[?.!])*$/i.test(t) ||
    /^(what\s+can\s+you\s+control)(\s*[?.!])*$/i.test(t)
  );
}

/** Need pairing with telemetry/host context to avoid “best CPU for gaming” false positives */
const HARDWARE_TERMS = /\b(cpu|processor|ram|memory|gpu)\b/i;
const TELEMETRY_CONTEXT =
  /\b(telemetry|nodes?|hardware|homelab|spirit|machine|host|online|offline|uptime|disk|drive|storage)\b/i;

const MODEL_RUNTIME =
  /\b(hermes|ollama|oracle\s+model|which\s+model|what\s+model|what\s+ai\b|backend\s+model)\b/i;

const INFRA_STATUS =
  /\b(web\s+search|tts|stt|whisper|piper|elevenlabs|voice)\b/i;

/** Legacy catch-all patterns → general_capabilities */
const GENERAL_STRONG: RegExp[] = [
  /\bcluster\s+telemetry\b/i,
  /\bstorage\s+telemetry\b/i,
  /can\s+you\s+see.*\b(nodes?|machines?)\b/i,
  /\bspirit(os)?\s+capabilities\b/i,
];

/** Filesystem / path ops - not drive-level “see” visibility */
function matchesFileAccessIntent(t: string): boolean {
  if (/\bedit\s+\S+\.\w+/i.test(t)) return true;
  if (
    /\b(can\s+you\s+)?(browse|list|open)\b.*\b(files?|folders?|directories?)\b/i.test(t)
  ) {
    return true;
  }
  if (/\b(list|browse)\b.*\b(my\s+)?files?\b/i.test(t)) return true;
  if (/\b(show\s+folders|list\s+files)\b/i.test(t)) return true;
  if (/\b(can\s+you\s+)?(read|write|edit|delete|move)\b.*\bfiles?\b/i.test(t)) return true;
  // Path + browse/list/open (no “see” - that’s storage visibility)
  if (
    (/\bc:[\\\/]/i.test(t) || /\bc\s*drive\b/i.test(t) || /\bd\s*drive\b/i.test(t)) &&
    /\b(browse|list|open)\b/i.test(t)
  ) {
    return true;
  }
  // files/folders on a drive letter
  if (/\b(files?|folders?)\b/i.test(t) && /\b(c:|c\s*drive|d\s*drive|e\s*drive)\b/i.test(t)) {
    return true;
  }
  return false;
}

/** See drives / storage volumes - not browse/list files (exported for storage formatter) */
export function matchesStorageVisibilityIntent(t: string): boolean {
  if (matchesFileAccessIntent(t)) return false;

  return (
    /\b(can\s+you\s+|do\s+you\s+)?see\b.*\b(c:|c\s*drive|d\s*drive|e\s*drive|my\s+drives?|my\s+storage)\b/i.test(
      t,
    ) ||
    /\b(can\s+you\s+|do\s+you\s+)?see\b.*\b(my\s+)?drives?\b/i.test(t) ||
    /\bwhat\s+drives\b/i.test(t) ||
    /\bwhat\s+storage\b.*\b(see|show|have)\b/i.test(t) ||
    /\bdo\s+you\s+see\b.*\bc:/i.test(t) ||
    /\bhow\s+much\s+(disk|storage)\b/i.test(t) ||
    (/\bstorage\b/i.test(t) && /\b(see|show|have|telemetry|drives?)\b/i.test(t))
  );
}

/** Git / npm / vitest asks: deterministic dev-command availability (not arbitrary shell). */
export function matchesDevCommandIntent(t: string): boolean {
  return (
    /\b(run\s+npm\s+test|npm\s+test)\b/i.test(t) ||
    /\b(run\s+tests?|run\s+the\s+tests?)\b/i.test(t) ||
    /\b(npx\s+vitest|vitest\s+run)\b/i.test(t) ||
    /\b(git\s+status|check\s+git\s+status|show\s+git\s+status)\b/i.test(t) ||
    /\b(git\s+diff|show\s+git\s+diff|show\s+the\s+diff)\b/i.test(t) ||
    /\bwhat\s+changed\s+in\s+git\b/i.test(t) ||
    /\b(run\s+typecheck|npm\s+run\s+typecheck|run\s+npm\s+typecheck)\b/i.test(t) ||
    /\bcheck\s+types\b/i.test(t) ||
    /\b(run\s+lint|npm\s+run\s+lint)\b/i.test(t) ||
    /\b(run\s+build|npm\s+run\s+build)\b/i.test(t) ||
    /\bcan\s+you\s+run\s+(npm\s+test|tests?|git|vitest)\b/i.test(t)
  );
}

export function detectCapabilityIntent(raw: string): CapabilityIntentKind | null {
  const t = normalizeForCapabilityIntent(raw);
  if (t.length < 6) return null;

  // ── 0. Allowlisted dev commands (fixed ids only, before generic file_access) ─
  if (matchesDevCommandIntent(t)) {
    return "dev_commands";
  }

  // ── 1. File / folder / explicit path file ops (before “see my C:” storage) ─
  if (matchesFileAccessIntent(t)) {
    return "file_access";
  }

  // ── 2. Drive & storage visibility (see C:, what drives, what storage can you see) ─
  if (matchesStorageVisibilityIntent(t)) {
    return "storage_status";
  }

  // ── 3. Desktop / remote control / SSH (app-level) ─
  if (
    /\b(can\s+you\s+)?control\b.*\b(desktop|my\s+pc|this\s+machine|computer)\b/i.test(t) ||
    /\bssh\b/i.test(t) ||
    /\bremote\s+(desktop|control)\b/i.test(t)
  ) {
    return "desktop_control";
  }

  // ── 4. Models / runtime ─
  if (
    /\b(hermes|ollama)\b/i.test(t) ||
    /\b(what|which)\s+(model|ai|backend)\b/i.test(t) ||
    /\b(running|using)\s+(on\s+)?(hermes|ollama)\b/i.test(t) ||
    /\bare\s+you\s+running\b/i.test(t)
  ) {
    return "ai_runtime";
  }

  // ── 5. Tools vs broad capability / “what can you do” ─
  const toolsExplicit =
    /\bwhat\s+tools\b/i.test(t) ||
    /\btools\b.*\b(have|got|available)\b/i.test(t) ||
    /\bspirit\s*os\s+tools\b/i.test(t) ||
    /\bspiritos\s+tools\b/i.test(t);

  const capabilityOverview =
    /\bwhat\s+are\s+your\s+capabilities\b/i.test(t) ||
    /\bwhat\s+can\s+you\s+do\b/i.test(t) ||
    /\bwhat\s+abilities\b/i.test(t) ||
    /\bwhat\s+powers\b/i.test(t) ||
    /\bwhat\s+access\b/i.test(t) ||
    /\bwhat\s+can\s+spirit\s*os\b/i.test(t) ||
    /\bwhat\s+can\s+spiritos\b/i.test(t) ||
    /\bwhat\s+do\s+you\s+know\s+about\s+your\s+system\b/i.test(t) ||
    isStandaloneWhatCanYouSeeOrControl(t);

  if (toolsExplicit) return "tool_inventory";
  if (capabilityOverview) return "general_capabilities";

  // ── 6. Nodes (online/offline) ─
  if (
    /\bwhat\s+nodes\b/i.test(t) ||
    /\bwhich\s+nodes\b/i.test(t) ||
    /\bnodes\s+are\s+online\b/i.test(t) ||
    (/\bwhat\s+machines\b/i.test(t) && /\bonline|offline\b/i.test(t))
  ) {
    return "node_status";
  }

  // ── 7. Storage quantity (without “see” already handled) ─
  if (/\bwhat\s+storage\b/i.test(t)) {
    return "storage_status";
  }

  // ── 8. Hardware overview ─
  if (
    /\bwhat\s+hardware\b/i.test(t) ||
    /\bhardware\b.*\b(see|have|show)\b/i.test(t) ||
    /\bcan\s+you\s+see.*\b(hardware|machines)\b/i.test(t)
  ) {
    return "hardware_summary";
  }

  // ── 9. General capability / infra questions ─
  if (GENERAL_STRONG.some((re) => re.test(t))) return "general_capabilities";
  if (MODEL_RUNTIME.test(t) || INFRA_STATUS.test(t)) return "general_capabilities";
  if (HARDWARE_TERMS.test(t) && TELEMETRY_CONTEXT.test(t)) return "general_capabilities";

  return null;
}

export function isCapabilityIntent(raw: string): boolean {
  return detectCapabilityIntent(raw) !== null;
}// ── MODEL_PROFILES - Mode Calibration V2 (Prompt 10B) ─────────────────────────────
