export function isModelProfileId(value: unknown): value is ModelProfileId {
  return typeof value === "string" && value in MODEL_PROFILES;
}

export function getModelProfile(id?: string | null): ModelProfile {
  if (id != null && isModelProfileId(id)) return MODEL_PROFILES[id];
  return MODEL_PROFILES[DEFAULT_MODEL_PROFILE_ID];
}// ── spirit-activity-events - workspace / tool telemetry for UI (no secrets, no raw root) ─

export const SPIRIT_ACTIVITY_EVENT_CAP = 20;

export type SpiritToolActivityKind =
  | "workspace_list"
  | "windows_workspace_list"
  | "workspace_read"
  | "workspace_tail"
  | "file_edit_proposed"
  | "file_edit_applied"
  | "dev_command_started"
  | "dev_command_completed"
  | "dev_command_failed"
  | "tool_blocked"
  | "tool_unavailable";

export type SpiritToolActivityStatus =
  | "pending"
  | "completed"
  | "failed"
  | "blocked"
  | "confirmation_required";

export type SpiritToolActivityCard = {
  id: string;
  timestamp: number;
  kind: SpiritToolActivityKind;
  label: string;
  status: SpiritToolActivityStatus;
  target?: string;
  summary?: string;
  safeMessage?: string;
};

export type SpiritAssistantMessageMetadata = {
  spiritToolActivity?: SpiritToolActivityCard[];
};

export type SpiritActivityKind =
  | "message_submitted"
  | "assistant_finished"
  | "mode_changed"
  | "voice_played"
  | "voice_error"
  | "workflow_step"
  | "copy_feedback"
  | SpiritToolActivityKind;

export type SpiritActivityEvent = {
  id: string;
  at: number;
  kind: SpiritActivityKind;
  label: string;
  status?: SpiritToolActivityStatus;
  target?: string;
  summary?: string;
  safeMessage?: string;
};

export function createSpiritToolActivityCard(
  partial: Omit<SpiritToolActivityCard, "id" | "timestamp"> & {
    id?: string;
    timestamp?: number;
  },
): SpiritToolActivityCard {
  const summary =
    partial.summary != null ? partial.summary.slice(0, 320) : undefined;
  const safeMessage =
    partial.safeMessage != null ? partial.safeMessage.slice(0, 320) : undefined;
  return {
    id: partial.id ?? `ta_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
    timestamp: partial.timestamp ?? Date.now(),
    kind: partial.kind,
    label: partial.label,
    status: partial.status,
    target: partial.target,
    summary,
    safeMessage,
  };
}

export function spiritToolCardToActivityEvent(card: SpiritToolActivityCard): Omit<
  SpiritActivityEvent,
  never
> {
  return {
    id: card.id,
    at: card.timestamp,
    kind: card.kind,
    label: card.label,
    status: card.status,
    target: card.target,
    summary: card.summary,
    safeMessage: card.safeMessage,
  };
}

export function appendSpiritActivityEvent(
  prev: SpiritActivityEvent[],
  event: Omit<SpiritActivityEvent, "id" | "at"> & { id?: string; at?: number },
): SpiritActivityEvent[] {
  const row: SpiritActivityEvent = {
    id: event.id ?? `evt_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
    at: event.at ?? Date.now(),
    kind: event.kind,
    label: event.label,
    status: event.status,
    target: event.target,
    summary: event.summary,
    safeMessage: event.safeMessage,
  };
  const next = [...prev, row];
  if (next.length <= SPIRIT_ACTIVITY_EVENT_CAP) return next;
  return next.slice(-SPIRIT_ACTIVITY_EVENT_CAP);
}// ── spirit-chat-request-body - JSON validation (client-safe; no server-only) ────
import type { UIMessage } from "ai";

import type { SpiritRuntimeSurface } from "@/lib/spirit/spirit-runtime-surface";
import {
  DEFAULT_MODEL_PROFILE_ID,
  type ModelProfileId,
} from "@/lib/spirit/model-profile.types";
import { isModelProfileId } from "@/lib/spirit/model-profiles";

export class SpiritRequestValidationError extends Error {
  constructor(
    public readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = "SpiritRequestValidationError";
  }
}

export const SPIRIT_PERSONALIZATION_SUMMARY_MAX = 1500;
export const SPIRIT_RESEARCH_PLAN_SUMMARY_MAX = 4000;
export const SPIRIT_ORACLE_MEMORY_CONTEXT_MAX = 3000;

export type SpiritChatRequestBody = {
  messages: UIMessage[];
  modelProfileId: ModelProfileId;
  /** Optional: `/oracle` passes `"oracle"` for ORACLE_OLLAMA_MODEL lane. */
  runtimeSurface: SpiritRuntimeSurface;
  /** Optional local profile slice; server validates length + type */
  personalizationSummary?: string;
  /** Prompt 10B - extra deliberation + modest token bump */
  deepThinkEnabled: boolean;
  /**
   * Researcher only: when true, skip provider-router web prefetch. Default false (web ON).
   * Legacy clients sent `webSearchRequested`; we map `webSearchRequested: false` → opt-out true.
   */
  webSearchOptOut: boolean;
  /** Teacher-only: opt-in provider-router web prefetch for current-data prompts. */
  teacherWebSearchEnabled: boolean;
  /** Optional approved research plan text (Stage 5 stub). */
  researchPlanSummary?: string;
  /** Optional Oracle voice session memory context block (Phase 3). */
  oracleMemoryContext?: string;
};

function assertMessagesShape(raw: unknown[]): void {
  for (let i = 0; i < raw.length; i++) {
    const m = raw[i];
    if (!m || typeof m !== "object") {
      throw new SpiritRequestValidationError(400, "Each message must be an object");
    }
    const msg = m as Record<string, unknown>;
    if (typeof msg.role !== "string" || msg.role.length === 0) {
      throw new SpiritRequestValidationError(
        400,
        "Each message must have a non-empty string role",
      );
    }
    if (!Array.isArray(msg.parts)) {
      throw new SpiritRequestValidationError(
        400,
        "Each message must include a parts array",
      );
    }
  }
}

function normalizeModelProfileId(raw: unknown): ModelProfileId {
  if (raw === undefined || raw === null) return DEFAULT_MODEL_PROFILE_ID;
  if (isModelProfileId(raw)) return raw;
  return DEFAULT_MODEL_PROFILE_ID;
}

function normalizeRuntimeSurface(raw: unknown): SpiritRuntimeSurface {
  if (raw === "oracle") return "oracle";
  return "chat";
}

function normalizeBool(raw: unknown, field: string, defaultVal: boolean): boolean {
  if (raw === undefined || raw === null) return defaultVal;
  if (raw === true) return true;
  if (raw === false) return false;
  throw new SpiritRequestValidationError(400, `${field} must be a boolean`);
}

/** Prefer explicit opt-out; else map deprecated `webSearchRequested` (inverted). */
function normalizeWebSearchOptOut(record: Record<string, unknown>): boolean {
  if (typeof record.webSearchOptOut === "boolean") return record.webSearchOptOut;
  if (typeof record.webSearchRequested === "boolean") {
    return !record.webSearchRequested;
  }
  return false;
}

function normalizePersonalizationSummary(raw: unknown): string | undefined {
  if (raw === undefined || raw === null) return undefined;
  if (typeof raw !== "string") {
    throw new SpiritRequestValidationError(
      400,
      "personalizationSummary must be a string when provided",
    );
  }
  const t = raw.trim();
  if (!t) return undefined;
  if (t.length > SPIRIT_PERSONALIZATION_SUMMARY_MAX) {
    throw new SpiritRequestValidationError(
      400,
      `personalizationSummary exceeds ${SPIRIT_PERSONALIZATION_SUMMARY_MAX} characters`,
    );
  }
  return t;
}

function normalizeResearchPlanSummary(raw: unknown): string | undefined {
  if (raw === undefined || raw === null) return undefined;
  if (typeof raw !== "string") {
    throw new SpiritRequestValidationError(400, "researchPlanSummary must be a string when provided");
  }
  const t = raw.trim();
  if (!t) return undefined;
  if (t.length > SPIRIT_RESEARCH_PLAN_SUMMARY_MAX) {
    throw new SpiritRequestValidationError(
      400,
      `researchPlanSummary exceeds ${SPIRIT_RESEARCH_PLAN_SUMMARY_MAX} characters`,
    );
  }
  return t;
}

function normalizeOracleMemoryContext(raw: unknown): string | undefined {
  if (raw === undefined || raw === null) return undefined;
  if (typeof raw !== "string") {
    throw new SpiritRequestValidationError(400, "oracleMemoryContext must be a string when provided");
  }
  const t = raw.trim();
  if (!t) return undefined;
  if (t.length > SPIRIT_ORACLE_MEMORY_CONTEXT_MAX) {
    throw new SpiritRequestValidationError(
      400,
      `oracleMemoryContext exceeds ${SPIRIT_ORACLE_MEMORY_CONTEXT_MAX} characters`,
    );
  }
  return t;
}

/** Validates POST JSON for /api/spirit (messages + optional modelProfileId). */
export function parseSpiritChatRequestBody(body: unknown): SpiritChatRequestBody {
  if (!body || typeof body !== "object") {
    throw new SpiritRequestValidationError(400, "Request body must be an object");
  }

  const record = body as Record<string, unknown>;
  const maybeMessages = record.messages;

  if (!Array.isArray(maybeMessages)) {
    throw new SpiritRequestValidationError(400, "Request body must include messages[]");
  }

  if (maybeMessages.length === 0) {
    throw new SpiritRequestValidationError(400, "messages[] cannot be empty");
  }

  assertMessagesShape(maybeMessages);

  const modelProfileId = normalizeModelProfileId(record.modelProfileId);
  const runtimeSurface = normalizeRuntimeSurface(record.runtimeSurface);
  const personalizationSummary = normalizePersonalizationSummary(
    record.personalizationSummary,
  );
  const deepThinkEnabled = normalizeBool(record.deepThinkEnabled, "deepThinkEnabled", false);
  const webSearchOptOut = normalizeWebSearchOptOut(record);
  const teacherWebSearchEnabled = normalizeBool(
    record.teacherWebSearchEnabled,
    "teacherWebSearchEnabled",
    true,
  );
  const researchPlanSummary = normalizeResearchPlanSummary(record.researchPlanSummary);
  const oracleMemoryContext = normalizeOracleMemoryContext(record.oracleMemoryContext);

  return {
    messages: maybeMessages as UIMessage[],
    modelProfileId,
    runtimeSurface,
    personalizationSummary,
    deepThinkEnabled,
    webSearchOptOut,
    teacherWebSearchEnabled,
    researchPlanSummary,
    oracleMemoryContext,
  };
}// ── Client-visible Ollama label (optional NEXT_PUBLIC_OLLAMA_MODEL) ───────────────

import type { SpiritRuntimeSurface } from "@/lib/spirit/spirit-runtime-surface";

export function getSpiritChatRuntimeDisplayLabel(): string {
  const v = process.env.NEXT_PUBLIC_OLLAMA_MODEL?.trim();
  if (v) return v;
  return "Hermes-class (local Ollama)";
}

/** Activity panel + Oracle chrome - chat shows local model hint; Oracle is explicit. */
export function getSpiritRuntimeSurfaceDisplayLabel(surface: SpiritRuntimeSurface): string {
  if (surface === "oracle") return "Oracle";
  return getSpiritChatRuntimeDisplayLabel();
}// ── spirit-route-decision - hybrid lane picker (Prompt 10C) ─────────────────────
// > Client-safe: no server-only imports. Callers pass env-derived flags from route.ts.
// > `lane` describes the dominant *orchestration* path this turn, not who owns every token.
// > Today Hermes always streams the user-visible reply; OpenAI is optional prefetch only.

import type { ModelProfileId } from "@/lib/spirit/model-profile.types";
import {
  isLikelyCasualShortMessage,
  mentionsCodeOrBuild,
  wantsResearchDepth,
  wantsTeacherWebStudyAids,
} from "@/lib/spirit/response-budget";

export type SpiritRouteLane =
  | "local-chat"
  | "local-web-search"
  | "openai-web-search"
  | "research-plan"
  | "deepseek-local"
  | "deepseek-api"
  | "disabled";

export type SpiritRouteDecisionReason =
  | "casual_chat"
  | "coding_or_complex_logic"
  | "current_data_needed"
  | "researcher_mode"
  | "deep_think_enabled"
  | "web_search_enabled"
  | "deep_research_requested"
  | "teacher_learning_request"
  | "local_default"
  | "provider_unavailable";

export type SpiritRouteDecision = {
  lane: SpiritRouteLane;
  confidence: "low" | "medium" | "high";
  reasons: SpiritRouteDecisionReason[];
  shouldSearchWeb: boolean;
  /** Teacher lane web prefetch when aids allowed + prompt looks educational. */
  shouldSearchTeacherWeb: boolean;
  shouldDraftResearchPlan: boolean;
  shouldUseDeepThink: boolean;
  shouldShowVisualizer: boolean;
  modelHint: string;
};

export type SpiritRouteDecisionInput = {
  modelProfileId: ModelProfileId;
  lastUserText: string;
  deepThinkEnabled: boolean;
  /**
   * When true, Researcher skips the provider-router web prefetch (explicit user opt-out).
   * Default OFF at the protocol level - Researcher web is on unless opted out.
   */
  webSearchOptOut: boolean;
  /** Teacher-only: web study aids. Default ON (omit or undefined); set false to opt out per thread. */
  teacherWebSearchEnabled?: boolean;
  /** Caller reads WEB_SEARCH_ENABLED (or test inject). */
  webSearchGloballyEnabled: boolean;
  /** Ollama model id hint for diagnostics / headers */
  modelHint: string;
};

/** Hermes researcher lane: default web ON unless user opted out or env killed it. */
export function shouldPrefetchOpenAiWebForResearcher(opts: {
  modelProfileId: ModelProfileId;
  lastUserText: string;
  webSearchOptOut?: boolean;
  webSearchGloballyEnabled: boolean;
}): boolean {
  if (opts.modelProfileId !== "researcher") return false;
  if (!opts.webSearchGloballyEnabled) return false;
  if (opts.webSearchOptOut) return false;
  return opts.lastUserText.trim().length > 0;
}

function uniqReasons(r: SpiritRouteDecisionReason[]): SpiritRouteDecisionReason[] {
  return [...new Set(r)];
}

/**
 * Deterministic routing for /api/spirit - extensible when DeepSeek / plan-first land.
 */
export function decideSpiritRoute(input: SpiritRouteDecisionInput): SpiritRouteDecision {
  const last = input.lastUserText.trim();
  const reasons: SpiritRouteDecisionReason[] = [];
  const deep = Boolean(input.deepThinkEnabled);
  const webOptOut = Boolean(input.webSearchOptOut);

  if (input.modelProfileId === "researcher") {
    reasons.push("researcher_mode");
  }
  if (deep) {
    reasons.push("deep_think_enabled");
  }
  if (input.webSearchGloballyEnabled) {
    reasons.push("web_search_enabled");
  }
  if (input.modelProfileId === "teacher" && wantsTeacherWebStudyAids(last)) {
    reasons.push("teacher_learning_request");
  }
  if (mentionsCodeOrBuild(last)) {
    reasons.push("coding_or_complex_logic");
  }
  if (wantsResearchDepth(last)) {
    reasons.push("current_data_needed");
  }
  if (isLikelyCasualShortMessage(last)) {
    reasons.push("casual_chat");
  }

  const shouldSearchWeb = shouldPrefetchOpenAiWebForResearcher({
    modelProfileId: input.modelProfileId,
    lastUserText: input.lastUserText,
    webSearchOptOut: input.webSearchOptOut,
    webSearchGloballyEnabled: input.webSearchGloballyEnabled,
  });

  const teacherWebAidsAllowed = input.teacherWebSearchEnabled !== false;
  const shouldSearchTeacherWeb =
    input.modelProfileId === "teacher" &&
    teacherWebAidsAllowed &&
    input.webSearchGloballyEnabled &&
    wantsTeacherWebStudyAids(last) &&
    last.length > 0;

  const shouldDraftResearchPlan =
    input.modelProfileId === "researcher" &&
    (!isLikelyCasualShortMessage(last) || shouldSearchWeb || !webOptOut || deep);

  let lane: SpiritRouteLane = "local-chat";
  if (shouldSearchWeb || shouldSearchTeacherWeb) {
    lane = "local-web-search";
  } else if (shouldDraftResearchPlan) {
    lane = "research-plan";
  } else {
    reasons.push("local_default");
  }

  const casual = last.length === 0 ? true : isLikelyCasualShortMessage(last);
  const shouldShowVisualizer =
    deep ||
    (input.modelProfileId === "teacher" && wantsTeacherWebStudyAids(last)) ||
    (input.modelProfileId === "researcher" && !casual) ||
    (shouldSearchWeb && !casual) ||
    shouldSearchTeacherWeb;

  let confidence: "low" | "medium" | "high" = "high";
  if (last.length === 0) {
    confidence = "low";
  } else if (isLikelyCasualShortMessage(last) && input.modelProfileId === "researcher") {
    confidence = "medium";
  }

  return {
    lane,
    confidence,
    reasons: uniqReasons(reasons),
    shouldSearchWeb,
    shouldSearchTeacherWeb,
    shouldDraftResearchPlan,
    shouldUseDeepThink: deep,
    shouldShowVisualizer,
    modelHint: input.modelHint,
  };
}// ── spirit-workflow-events - plan / research steps for UI (Prompt 10C) ───────────
// > High-level labels only - no chain-of-thought, no tool dumps.

import type { ModelProfileId } from "@/lib/spirit/model-profile.types";
import type { SpiritRouteDecision, SpiritRouteLane } from "@/lib/spirit/spirit-route-decision";

export type SpiritWorkflowStepStatus = "pending" | "active" | "done" | "skipped" | "error";

export type SpiritWorkflowStep = {
  id: string;
  label: string;
  status: SpiritWorkflowStepStatus;
};

/** UI visualizer uses a subset (no "skipped" in props contract - map to pending/done). */
export type SpiritVisualizerStepStatus = "pending" | "active" | "done" | "error";

export type SpiritVisualizerStep = {
  id: string;
  label: string;
  detail?: string;
  status: SpiritVisualizerStepStatus;
};

export function emptySpiritWorkflowSteps(): SpiritWorkflowStep[] {
  return [];
}

function clampStatuses(steps: SpiritVisualizerStep[], busy: boolean, tick: number): SpiritVisualizerStep[] {
  if (steps.length === 0) return steps;
  if (!busy) {
    return steps.map((s, i) => ({
      ...s,
      status: i === steps.length - 1 ? ("done" as const) : ("done" as const),
    }));
  }
  const cap = Math.max(steps.length - 1, 0);
  const idx = Math.min(Math.max(tick, 0), cap);
  return steps.map((s, i) => {
    if (i < idx) return { ...s, status: "done" as const };
    if (i === idx) return { ...s, status: "active" as const };
    return { ...s, status: "pending" as const };
  });
}

/** Baseline chat path (no provider-router web prefetch in this turn). */
export function buildWorkflowStepsForLocalChat(opts: {
  modelProfileId: ModelProfileId;
  deepThink: boolean;
  busy: boolean;
  tick: number;
}): SpiritVisualizerStep[] {
  const modeLabel =
    opts.modelProfileId === "researcher"
      ? "Researcher"
      : opts.modelProfileId === "teacher"
        ? "Teacher"
        : opts.modelProfileId === "brutal"
          ? "Brutal"
          : opts.modelProfileId === "sassy-chaotic"
            ? "Sassy"
            : "Peer";
  const steps: SpiritVisualizerStep[] = [
    { id: "understand", label: "Understanding request", status: "pending" },
    { id: "route", label: "Choosing route", detail: modeLabel, status: "pending" },
    { id: "searchAvail", label: "Checking search availability", status: "pending" },
  ];
  if (opts.deepThink) {
    steps.push({ id: "deep", label: "Deep think pass", status: "pending" });
  }
  steps.push(
    { id: "draft", label: "Drafting answer", status: "pending" },
    { id: "voice", label: "Preparing voice summary", status: "pending" },
    { id: "complete", label: "Complete", status: "pending" },
  );
  return clampStatuses(steps, opts.busy, opts.tick);
}

export function buildWorkflowStepsForWebSearch(opts: {
  modelProfileId: ModelProfileId;
  deepThink: boolean;
  busy: boolean;
  tick: number;
}): SpiritVisualizerStep[] {
  const steps: SpiritVisualizerStep[] = [
    { id: "understand", label: "Understanding request", status: "pending" },
    { id: "route", label: "Search route selected", detail: "Local-first web search", status: "pending" },
    { id: "searchAvail", label: "Checking search availability", status: "pending" },
    { id: "search", label: "Searching web providers", status: "pending" },
    { id: "found", label: "Collecting sources", detail: "Verified URLs only", status: "pending" },
    { id: "review", label: "Reviewing source snippets", status: "pending" },
  ];
  if (opts.deepThink) {
    steps.push({ id: "deep", label: "Deep think verification", status: "pending" });
  }
  steps.push(
    { id: "draft", label: "Drafting answer", status: "pending" },
    { id: "voice", label: "Preparing voice summary", status: "pending" },
    { id: "complete", label: "Complete", status: "pending" },
  );
  return clampStatuses(steps, opts.busy, opts.tick);
}

export function buildWorkflowStepsForResearchPlan(opts: {
  deepThink: boolean;
  busy: boolean;
  tick: number;
}): SpiritVisualizerStep[] {
  const steps: SpiritVisualizerStep[] = [
    { id: "understand", label: "Understanding request", status: "pending" },
    { id: "route", label: "Search route selected", detail: "Research plan before web pull", status: "pending" },
    { id: "plan", label: "Structuring research plan", status: "pending" },
    { id: "review", label: "Waiting for you to start research", status: "pending" },
  ];
  if (opts.deepThink) {
    steps.push({ id: "deep", label: "Deep think shaping", status: "pending" });
  }
  steps.push(
    { id: "draft", label: "Drafting answer", status: "pending" },
    { id: "complete", label: "Complete", status: "pending" },
  );
  return clampStatuses(steps, opts.busy, opts.tick);
}

/** Pick step pipeline from server lane + heuristics. */
export function buildWorkflowStepsForRouteDecision(
  lane: SpiritRouteLane | string,
  opts: {
    modelProfileId: ModelProfileId;
    deepThink: boolean;
    busy: boolean;
    tick: number;
  },
): SpiritVisualizerStep[] {
  if (lane === "openai-web-search" || lane === "local-web-search") {
    return buildWorkflowStepsForWebSearch(opts);
  }
  if (lane === "research-plan") {
    return buildWorkflowStepsForResearchPlan({
      deepThink: opts.deepThink,
      busy: opts.busy,
      tick: opts.tick,
    });
  }
  return buildWorkflowStepsForLocalChat(opts);
}

/** @deprecated prefer buildWorkflowStepsForRouteDecision + labels map */
export function buildSpiritWorkflowStepLabels(opts: {
  modelProfileId: ModelProfileId;
  webSearchOptOut: boolean;
  deepThinkEnabled: boolean;
}): string[] {
  const lane: SpiritRouteLane =
    opts.modelProfileId === "researcher" && !opts.webSearchOptOut
      ? "local-web-search"
      : "local-chat";
  const steps = buildWorkflowStepsForRouteDecision(lane, {
    modelProfileId: opts.modelProfileId,
    deepThink: opts.deepThinkEnabled,
    busy: true,
    tick: 0,
  });
  return steps.map((s) => s.label);
}

export function workflowStepsFromServerDecision(
  decision: Pick<SpiritRouteDecision, "lane">,
  opts: {
    modelProfileId: ModelProfileId;
    deepThink: boolean;
    busy: boolean;
    tick: number;
  },
): SpiritVisualizerStep[] {
  return buildWorkflowStepsForRouteDecision(decision.lane, opts);
}// ── AudioQueue - /api/tts + WebAudio + HTMLAudio fallback (Prompt 9G hard interrupt) ─
// > Chaining speak() behind `this.chain.then` was leaving B waiting on A’s fetch - UX rot.
// > Interrupt resets the promise tail; stale runSession finally must not nuke the new session’s op.
// > Generation gate: every interrupt/stop bumps playGeneration; async tails bail before play.
import { parseTtsSegments, type TtsSegment } from "@/lib/tts/tts-parser";
import { decodeTtsVoiceNameFromHeader } from "@/lib/tts/safe-tts-headers";

/** User-facing copy - VoiceSettingsPanel + toast-adjacent; keep in sync with VoiceSettingsPanel filters. */
export const TTS_AUDIO_BLOCKED_MESSAGE =
  "Audio blocked. Tap Enable audio, then try Speak again.";

export type TtsPlaybackMode = "audio-context" | "html-audio";

export type TtsLatency = {
  fetchMs?: number;
  decodeMs?: number;
  totalMs?: number;
  /** First `/api/tts` fetch start → audible playback start (first chunk). */
  timeToFirstAudioMs?: number;
  startDelayMs?: number;
  provider?: string;
  upstreamMs?: number;
  playbackMode?: TtsPlaybackMode;
  /** Applied voice speed (X-Spirit-TTS-Speed / ElevenLabs). */
  speed?: number;
  /** ElevenLabs voice_id (header + client mirror). */
  voiceId?: string;
  /** Friendly label (client-selected name at request time). */
  voiceName?: string;
  /** Prompt 10B - e.g. "Spoken: summary (message was long)" */
  spokenSummaryLine?: string;
};

export type AudioQueueState = {
  isPlaying: boolean;
  queueLength: number;
  audioContextState: AudioContextState | "unknown";
};

export type TtsPlaybackEvent = "interrupted";

type QueueItem =
  | { kind: "pause"; ms: number }
  | { kind: "speech"; text: string };

function segmentsToQueue(segments: TtsSegment[]): QueueItem[] {
  const out: QueueItem[] = [];
  for (const s of segments) {
    if (s.type === "pause" && s.ms > 0) out.push({ kind: "pause", ms: s.ms });
    else if (s.type === "speech" && s.text.trim())
      out.push({ kind: "speech", text: s.text.trim() });
  }
  return out;
}

function nowMs(): number {
  try {
    if (typeof performance !== "undefined" && typeof performance.now === "function") {
      return performance.now();
    }
  } catch {
    /* ignore */
  }
  return Date.now();
}

function sniffAudioMime(buf: ArrayBuffer): string {
  const u = new Uint8Array(buf.byteLength > 16 ? buf.slice(0, 16) : buf);
  if (u.length >= 4 && u[0] === 0x52 && u[1] === 0x49 && u[2] === 0x46 && u[3] === 0x46) {
    return "audio/wav";
  }
  if (u.length >= 2 && u[0] === 0xff && (u[1] & 0xe0) === 0xe0) return "audio/mpeg";
  if (u.length >= 3 && u[0] === 0x49 && u[1] === 0x44 && u[2] === 0x33) return "audio/mpeg";
  return "audio/mpeg";
}

function isLikelyIos(): boolean {
  if (typeof navigator === "undefined") return false;
  return /iP(hone|ad|od)/i.test(navigator.userAgent);
}

/** Tiny silent WAV (MDN-style data URL) - primes `HTMLAudioElement` on iOS inside user activation. */
const IOS_SILENT_WAV_DATA_URL =
  "data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEA...";

export type AudioQueueOptions = {
  onState?: (s: AudioQueueState) => void;
  onError?: (message: string) => void;
  onLatency?: (m: TtsLatency) => void;
  /** Fired when a hard interrupt cuts active work (manual Speak / auto-speak / stop). */
  onPlaybackEvent?: (e: TtsPlaybackEvent) => void;
  ttsEndpoint?: string;
};

export class AudioQueue {
  private readonly ttsEndpoint: string;
  private readonly onState?: (s: AudioQueueState) => void;
  private readonly onError?: (message: string) => void;
  private readonly onLatency?: (m: TtsLatency) => void;
  private readonly onPlaybackEvent?: (e: TtsPlaybackEvent) => void;

  private ctx: AudioContext | null = null;
  private pending: QueueItem[] = [];
  private activeSources = new Set<AudioBufferSourceNode>();
  private chain: Promise<void> = Promise.resolve();
  private op: AbortController | null = null;
  private playing = false;
  private sessionChunkIndex = 0;
  /** Bumped on every interrupt-speak / stop; stale async tails compare against this. */
  private playGeneration = 0;

  private sessionPreferHtmlAudioFirst = false;
  /** Appended to final chunk latency row (Prompt 10B). */
  private sessionSpokenSummaryLine?: string;
  private htmlAudioEl: HTMLAudioElement | null = null;
  private htmlAudioObjectUrl: string | null = null;
  /**
   * iOS Safari: `play()` on a fresh `Audio(blob)` after async `/api/tts` often throws
   * NotAllowedError - the element was not created during the user gesture. We keep the
   * silent `Audio()` primed in `syncPrimeFromUserGesture` and reuse it for real chunks.
   */
  private iosCarrierAudioEl: HTMLAudioElement | null = null;

  startDelayMs = 0;
  sentenceGapMs = 150;
  /** POSTed to /api/tts as `speed` (useTTS mirrors localStorage). */
  ttsVoiceSpeed = 1.12;
  /** POSTed to /api/tts as `voiceId` (ElevenLabs only). */
  ttsVoiceId: string | null = null;
  /** Shown on “Last voice” line when provider echoes id without name. */
  ttsVoiceName: string | null = null;

  constructor(opts: AudioQueueOptions = {}) {
    this.onState = opts.onState;
    this.onError = opts.onError;
    this.onLatency = opts.onLatency;
    this.onPlaybackEvent = opts.onPlaybackEvent;
    this.ttsEndpoint = opts.ttsEndpoint ?? "/api/tts";
  }

  private err(msg: string): void {
    try {
      this.onError?.(msg);
    } catch {
      /* swallow */
    }
    console.error("[audio-queue]", msg);
  }

  private emit(): void {
    try {
      this.onState?.({
        isPlaying: this.playing,
        queueLength: this.pending.length,
        audioContextState: this.ctx?.state ?? "unknown",
      });
    } catch {
      /* swallow */
    }
  }

  private logLatency(m: TtsLatency): void {
    try {
      this.onLatency?.(m);
    } catch {
      /* swallow */
    }
    if (process.env.NODE_ENV === "development") {
      const pm = m.playbackMode ?? "?";
      console.info(
        `[tts] latency mode=${pm} fetch=${m.fetchMs ?? "?"}ms decode=${m.decodeMs ?? "?"}ms ttfa=${m.timeToFirstAudioMs ?? "?"}ms total=${m.totalMs ?? "?"}ms`,
      );
    }
  }

  private ensureContext(): AudioContext | null {
    if (typeof window === "undefined") return null;
    if (this.ctx) return this.ctx;
    const Ctx =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctx) return null;
    this.ctx = new Ctx();
    this.emit();
    return this.ctx;
  }

  /**
   * Synchronous audio priming - MUST run before any `await` inside the same user gesture
   * (iOS Safari revokes activation across microtasks). Invoked from `ensureAudioUnlocked`.
   */
  private syncPrimeFromUserGesture(): void {
    if (typeof window === "undefined") return;
    const c = this.ensureContext();
    if (c) {
      try {
        void c.resume();
      } catch {
        /* ignore */
      }
    }
    if (!isLikelyIos()) {
      this.emit();
      return;
    }
    try {
      if (c) {
        const osc = c.createOscillator();
        const gain = c.createGain();
        gain.gain.value = 0.0001;
        osc.connect(gain);
        gain.connect(c.destination);
        const t0 = c.currentTime;
        osc.start(t0);
        osc.stop(t0 + 0.02);
      }
    } catch {
      /* ignore */
    }
    try {
      const a = new Audio(IOS_SILENT_WAV_DATA_URL);
      a.setAttribute("playsinline", "");
      (a as HTMLAudioElement & { playsInline?: boolean }).playsInline = true;
      a.volume = 0.0001;
      void a.play().catch(() => {});
      // Reuse this element for blob TTS - new Audio(blobUrl) is not gesture-blessed.
      if (isLikelyIos()) this.iosCarrierAudioEl ??= a;
    } catch {
      /* ignore */
    }
    this.emit();
  }

  /**
   * Resume AudioContext - call from a tap/handler before playback.
   * @returns false if context exists but could not enter `running` (mobile gesture / policy).
   */
  async ensureAudioUnlocked(): Promise<boolean> {
    this.syncPrimeFromUserGesture();
    const c = this.ensureContext();
    if (!c) return true;
    try {
      if (c.state === "suspended") await c.resume();
    } catch (e) {
      console.error("[audio-queue] ensureAudioUnlocked resume:", e);
      this.emit();
      return false;
    }
    this.emit();
    if (c.state === "running") return true;
    // iOS WebKit sometimes lags `state` transitions after resume; blocking here caused silent TTS
    // even when `play()` later succeeds. Trust syncPrime + resume attempt unless dead/closed.
    if (isLikelyIos() && c.state !== "closed") return true;
    return false;
  }

  /** @deprecated alias for ensureAudioUnlocked */
  async prime(): Promise<boolean> {
    return this.ensureAudioUnlocked();
  }

  private async resumeIfNeeded(): Promise<void> {
    const c = this.ctx;
    if (!c) return;
    try {
      if (c.state === "suspended") await c.resume();
    } catch (e) {
      console.error("[audio-queue] resume:", e);
    }
    this.emit();
  }

  private tearDownHtmlAudio(): void {
    const el = this.htmlAudioEl;
    const url = this.htmlAudioObjectUrl;
    this.htmlAudioEl = null;
    this.htmlAudioObjectUrl = null;
    if (url) {
      try {
        URL.revokeObjectURL(url);
      } catch {
        /* ignore */
      }
    }
    if (!el) return;
    if (el === this.iosCarrierAudioEl) {
      try {
        el.pause();
      } catch {
        /* ignore */
      }
      try {
        el.removeAttribute("src");
        el.load();
      } catch {
        /* ignore */
      }
      return;
    }
    try {
      el.pause();
      el.removeAttribute("src");
      el.load();
    } catch {
      /* ignore */
    }
  }

  private hardStopPlayback(): void {
    this.op?.abort();
    this.op = null;
    for (const s of this.activeSources) {
      try {
        s.stop(0);
      } catch {
        /* already stopped */
      }
    }
    this.activeSources.clear();
    this.tearDownHtmlAudio();
    this.playing = false;
    this.emit();
  }

  stop(): void {
    this.playGeneration += 1;
    this.pending = [];
    this.hardStopPlayback();
    this.emit();
  }

  private snapshotHadActivePlayback(): boolean {
    return (
      this.playing ||
      this.activeSources.size > 0 ||
      this.htmlAudioEl != null ||
      (this.op != null && !this.op.signal.aborted)
    );
  }

  speak(
    text: string,
    options?: {
      interrupt?: boolean;
      preferHtmlAudioFirst?: boolean;
      spokenSummaryLine?: string;
    },
  ): void {
    const interrupt = options?.interrupt !== false;
    if (!interrupt) {
      this.enqueue(text);
      return;
    }
    const hadActive = this.snapshotHadActivePlayback();
    this.playGeneration += 1;
    const generation = this.playGeneration;
    this.hardStopPlayback();
    this.pending = segmentsToQueue(parseTtsSegments(text));
    this.sessionPreferHtmlAudioFirst = Boolean(options?.preferHtmlAudioFirst);
    this.sessionSpokenSummaryLine = options?.spokenSummaryLine;
    if (hadActive) {
      try {
        this.onPlaybackEvent?.("interrupted");
      } catch {
        /* swallow */
      }
    }
    if (process.env.NODE_ENV === "development") {
      console.info("[tts] interrupt current playback");
    }
    // ── Do NOT chain behind the old tail - B must not wait for A’s fetch/decode/play.
    this.chain = Promise.resolve()
      .catch(() => {})
      .then(async () => {
        if (generation !== this.playGeneration) {
          if (process.env.NODE_ENV === "development") {
            console.info("[tts] session skipped stale audio");
          }
          return;
        }
        await this.runSession(generation);
      });
    void this.chain.catch(() => {});
  }

  /**
   * Speak multiple segments in one session (chunked long reads).
   * Each segment must already respect /api/tts char limits.
   */
  speakMany(
    texts: string[],
    options?: {
      interrupt?: boolean;
      preferHtmlAudioFirst?: boolean;
      spokenSummaryLine?: string;
    },
  ): void {
    const parts = texts.map((t) => t.trim()).filter(Boolean);
    if (!parts.length) return;
    const interrupt = options?.interrupt !== false;
    if (!interrupt) {
      for (const t of parts) this.enqueue(t);
      return;
    }
    const hadActive = this.snapshotHadActivePlayback();
    this.playGeneration += 1;
    const generation = this.playGeneration;
    this.hardStopPlayback();
    const q: QueueItem[] = [];
    for (const t of parts) q.push(...segmentsToQueue(parseTtsSegments(t)));
    this.pending = q;
    this.sessionPreferHtmlAudioFirst = Boolean(options?.preferHtmlAudioFirst);
    this.sessionSpokenSummaryLine = options?.spokenSummaryLine;
    if (hadActive) {
      try {
        this.onPlaybackEvent?.("interrupted");
      } catch {
        /* swallow */
      }
    }
    this.chain = Promise.resolve()
      .catch(() => {})
      .then(async () => {
        if (generation !== this.playGeneration) return;
        await this.runSession(generation);
      });
    void this.chain.catch(() => {});
  }

  enqueue(text: string): void {
    const extra = segmentsToQueue(parseTtsSegments(text));
    const scheduledGen = this.playGeneration;
    this.chain = this.chain
      .catch(() => {})
      .then(async () => {
        if (scheduledGen !== this.playGeneration) return;
        this.pending.push(...extra);
        const gen = this.playGeneration;
        if (!this.playing && this.pending.length > 0) {
          await this.runSession(gen);
        }
      });
    void this.chain.catch(() => {});
  }

  async drain(): Promise<void> {
    await this.chain;
  }

  private sleep(ms: number, signal: AbortSignal): Promise<void> {
    return new Promise((resolve, reject) => {
      if (signal.aborted) {
        reject(new DOMException("aborted", "AbortError"));
        return;
      }
      const t = window.setTimeout(() => {
        signal.removeEventListener("abort", onAbort);
        resolve();
      }, ms);
      const onAbort = () => {
        window.clearTimeout(t);
        reject(new DOMException("aborted", "AbortError"));
      };
      signal.addEventListener("abort", onAbort, { once: true });
    });
  }

  private async fetchSpeechBuffer(
    text: string,
    signal: AbortSignal,
  ): Promise<{
    buffer: ArrayBuffer;
    provider?: string;
    upstreamMs?: number;
    speed?: number;
    voiceId?: string;
    voiceName?: string;
  }> {
    const res = await fetch(this.ttsEndpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        text,
        speed: this.ttsVoiceSpeed,
        ...(this.ttsVoiceId ? { voiceId: this.ttsVoiceId } : {}),
        ...(this.ttsVoiceName ? { voiceName: this.ttsVoiceName } : {}),
      }),
      signal,
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => res.statusText);
      throw new Error(errText.slice(0, 200) || res.statusText);
    }
    const prov = res.headers.get("x-spirit-tts-provider")?.trim();
    const upstreamRaw = res.headers.get("x-spirit-tts-upstream-ms")?.trim();
    const upstreamMsParsed = upstreamRaw ? Number.parseInt(upstreamRaw, 10) : NaN;
    const upstreamMs =
      Number.isFinite(upstreamMsParsed) && upstreamMsParsed >= 0
        ? upstreamMsParsed
        : undefined;
    const speedRaw = res.headers.get("x-spirit-tts-speed")?.trim();
    const speedParsed = speedRaw ? Number.parseFloat(speedRaw) : NaN;
    const speed =
      Number.isFinite(speedParsed) && speedParsed > 0 ? speedParsed : undefined;
    const voiceIdHdr = res.headers.get("x-spirit-tts-voice-id")?.trim();
    const encHdr =
      res.headers.get("x-spirit-tts-voice-name-encoded")?.trim();
    const legacyAscii = res.headers.get("x-spirit-tts-voice-name")?.trim();
    const decoded = decodeTtsVoiceNameFromHeader(encHdr);
    const voiceNameResolved = decoded ?? legacyAscii ?? this.ttsVoiceName ?? undefined;
    const buffer = await res.arrayBuffer();
    return {
      buffer,
      provider: prov || undefined,
      upstreamMs,
      speed,
      voiceId: voiceIdHdr || this.ttsVoiceId || undefined,
      voiceName: voiceNameResolved || undefined,
    };
  }

  private stale(gen: number): boolean {
    return gen !== this.playGeneration;
  }

  private async playHtmlAudioSegment(
    buf: ArrayBuffer,
    signal: AbortSignal,
    requestStart: number,
    responseReceived: number,
    provider: string | undefined,
    upstreamMs: number | undefined,
    isFirstSpeechChunk: boolean,
    expectedGeneration: number,
    ttsSpeed?: number,
    ttsVoiceId?: string,
    ttsVoiceName?: string,
    extraLatency?: Partial<TtsLatency>,
  ): Promise<boolean> {
    if (signal.aborted || this.stale(expectedGeneration)) return false;
    this.tearDownHtmlAudio();
    const mime = sniffAudioMime(buf);
    const blob = new Blob([buf], { type: mime });
    const url = URL.createObjectURL(blob);
    this.htmlAudioObjectUrl = url;

    const carrier = isLikelyIos() ? this.iosCarrierAudioEl : null;
    const el = carrier ?? new Audio();
    el.src = url;
    if (carrier) {
      try {
        el.load();
      } catch {
        /* ignore */
      }
    }
    el.setAttribute("playsinline", "");
    (el as HTMLAudioElement & { playsInline?: boolean }).playsInline = true;
    if (carrier) el.volume = 1;
    this.htmlAudioEl = el;

    try {
      await el.play().catch((e: unknown) => {
        const name = e && typeof e === "object" && "name" in e ? String((e as Error).name) : "";
        if (name === "NotAllowedError") {
          this.err(TTS_AUDIO_BLOCKED_MESSAGE);
        }
        throw e;
      });

      const playbackStartAt = nowMs();

      if (this.stale(expectedGeneration)) {
        try {
          el.pause();
        } catch {
          /* ignore */
        }
        return false;
      }

      await new Promise<void>((resolve, reject) => {
        const cleanup = () => {
          el.removeEventListener("ended", onEnded);
          el.removeEventListener("error", onErr);
          signal.removeEventListener("abort", onAbort);
        };
        const onEnded = () => {
          cleanup();
          resolve();
        };
        const onErr = () => {
          cleanup();
          reject(new Error("HTMLAudioElement error"));
        };
        const onAbort = () => {
          cleanup();
          try {
            el.pause();
          } catch {
            /* ignore */
          }
          reject(new DOMException("aborted", "AbortError"));
        };
        el.addEventListener("ended", onEnded, { once: true });
        el.addEventListener("error", onErr, { once: true });
        signal.addEventListener("abort", onAbort, { once: true });
      });

      if (this.stale(expectedGeneration)) return false;

      const endedAt = nowMs();
      this.logLatency({
        fetchMs: Math.round(responseReceived - requestStart),
        decodeMs: 0,
        totalMs: Math.round(endedAt - requestStart),
        timeToFirstAudioMs: Math.round(playbackStartAt - requestStart),
        startDelayMs: isFirstSpeechChunk ? this.startDelayMs : 0,
        provider,
        upstreamMs,
        playbackMode: "html-audio",
        speed: ttsSpeed,
        voiceId: ttsVoiceId,
        voiceName: ttsVoiceName,
        ...extraLatency,
      });
      return true;
    } catch (e) {
      if ((e as Error)?.name === "AbortError") return false;
      if (
        e &&
        typeof e === "object" &&
        "name" in e &&
        (e as Error).name === "NotAllowedError"
      ) {
        return false;
      }
      this.err(e instanceof Error ? e.message : "HTML audio playback failed");
      return false;
    } finally {
      this.tearDownHtmlAudio();
    }
  }

  private async tryPlayWithAudioContext(
    buf: ArrayBuffer,
    signal: AbortSignal,
    requestStart: number,
    responseReceived: number,
    provider: string | undefined,
    upstreamMs: number | undefined,
    isFirstSpeechChunk: boolean,
    expectedGeneration: number,
    ttsSpeed?: number,
    ttsVoiceId?: string,
    ttsVoiceName?: string,
    extraLatency?: Partial<TtsLatency>,
  ): Promise<boolean> {
    const ctx = this.ensureContext();
    if (!ctx) return false;

    await this.resumeIfNeeded();
    if (ctx.state !== "running" || this.stale(expectedGeneration)) return false;

    const decodeStart = nowMs();
    let audio: AudioBuffer;
    try {
      const copy = buf.slice(0);
      audio = await new Promise((resolve, reject) => {
        ctx.decodeAudioData(copy, resolve, () => reject(new Error("decodeAudioData failed")));
      });
    } catch {
      return false;
    }
    const decodeEnd = nowMs();
    if (signal.aborted || this.stale(expectedGeneration)) return false;

    await this.resumeIfNeeded();
    if (ctx.state !== "running" || this.stale(expectedGeneration)) return false;

    try {
      let playbackStartAt = 0;
      await new Promise<void>((resolve, reject) => {
        const src = ctx.createBufferSource();
        src.buffer = audio;
        src.connect(ctx.destination);
        this.activeSources.add(src);
        src.onended = () => {
          this.activeSources.delete(src);
          resolve();
        };
        try {
          src.start(0);
          playbackStartAt = nowMs();
        } catch (e) {
          this.activeSources.delete(src);
          reject(e);
        }
      });
      if (this.stale(expectedGeneration)) return false;
      const endedAt = nowMs();
      this.logLatency({
        fetchMs: Math.round(responseReceived - requestStart),
        decodeMs: Math.round(decodeEnd - decodeStart),
        totalMs: Math.round(endedAt - requestStart),
        timeToFirstAudioMs: Math.round(playbackStartAt - requestStart),
        startDelayMs: isFirstSpeechChunk ? this.startDelayMs : 0,
        provider,
        upstreamMs,
        playbackMode: "audio-context",
        speed: ttsSpeed,
        voiceId: ttsVoiceId,
        voiceName: ttsVoiceName,
        ...extraLatency,
      });
      return true;
    } catch (e) {
      if ((e as Error)?.name === "AbortError") return false;
      return false;
    }
  }

  private async runSession(expectedGeneration: number): Promise<void> {
    if (this.playing) return;

    try {
      const unlocked = await this.ensureAudioUnlocked();
      if (this.stale(expectedGeneration)) return;
      if (!unlocked) {
        this.err(TTS_AUDIO_BLOCKED_MESSAGE);
        return;
      }

      this.op = new AbortController();
      const signal = this.op.signal;
      this.playing = true;
      this.sessionChunkIndex = 0;
      this.emit();

      if (this.startDelayMs > 0) {
        try {
          await this.sleep(this.startDelayMs, signal);
        } catch {
          return;
        }
      }

      if (this.stale(expectedGeneration)) return;

      while (!signal.aborted && !this.stale(expectedGeneration)) {
        const item = this.pending.shift();
        if (!item) break;

        if (item.kind === "pause") {
          try {
            await this.sleep(item.ms, signal);
          } catch {
            break;
          }
          continue;
        }

        const requestStart = nowMs();
        let buf: ArrayBuffer;
        let provider: string | undefined;
        let upstreamMs: number | undefined;
        let ttsSpeed: number | undefined;
        let ttsVoiceId: string | undefined;
        let ttsVoiceName: string | undefined;
        try {
          const fetched = await this.fetchSpeechBuffer(item.text, signal);
          buf = fetched.buffer;
          provider = fetched.provider;
          upstreamMs = fetched.upstreamMs;
          ttsSpeed = fetched.speed;
          ttsVoiceId = fetched.voiceId;
          ttsVoiceName = fetched.voiceName;
        } catch (e) {
          if ((e as Error)?.name === "AbortError") break;
          this.err(e instanceof Error ? e.message : "fetch /api/tts failed");
          continue;
        }
        const responseReceived = nowMs();

        if (signal.aborted || this.stale(expectedGeneration)) {
          if (process.env.NODE_ENV === "development" && this.stale(expectedGeneration)) {
            console.info("[tts] session skipped stale audio");
          }
          break;
        }

        const isFirstSpeechChunk = this.sessionChunkIndex === 0;
        this.sessionChunkIndex += 1;

        const moreSpeechLater = this.pending.some((x) => x.kind === "speech");
        const tail: Partial<TtsLatency> =
          !moreSpeechLater && this.sessionSpokenSummaryLine
            ? { spokenSummaryLine: this.sessionSpokenSummaryLine }
            : {};

        const preferHtmlFirst =
          this.sessionPreferHtmlAudioFirst ||
          (isLikelyIos() && this.iosCarrierAudioEl != null) ||
          (typeof window !== "undefined" &&
            !(
              window.AudioContext ||
              (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
            ));

        let played = false;
        if (preferHtmlFirst) {
          played = await this.playHtmlAudioSegment(
            buf,
            signal,
            requestStart,
            responseReceived,
            provider,
            upstreamMs,
            isFirstSpeechChunk,
            expectedGeneration,
            ttsSpeed,
            ttsVoiceId,
            ttsVoiceName,
            tail,
          );
          if (!played && !this.stale(expectedGeneration)) {
            played = await this.tryPlayWithAudioContext(
              buf,
              signal,
              requestStart,
              responseReceived,
              provider,
              upstreamMs,
              isFirstSpeechChunk,
              expectedGeneration,
              ttsSpeed,
              ttsVoiceId,
              ttsVoiceName,
              tail,
            );
          }
        } else {
          played = await this.tryPlayWithAudioContext(
            buf,
            signal,
            requestStart,
            responseReceived,
            provider,
            upstreamMs,
            isFirstSpeechChunk,
            expectedGeneration,
            ttsSpeed,
            ttsVoiceId,
            ttsVoiceName,
            tail,
          );
          if (!played && !this.stale(expectedGeneration)) {
            played = await this.playHtmlAudioSegment(
              buf,
              signal,
              requestStart,
              responseReceived,
              provider,
              upstreamMs,
              isFirstSpeechChunk,
              expectedGeneration,
              ttsSpeed,
              ttsVoiceId,
              ttsVoiceName,
              tail,
            );
          }
        }

        if (this.sentenceGapMs > 0 && !signal.aborted && !this.stale(expectedGeneration)) {
          try {
            await this.sleep(this.sentenceGapMs, signal);
          } catch {
            break;
          }
        }
      }
    } finally {
      this.sessionPreferHtmlAudioFirst = false;
      this.sessionSpokenSummaryLine = undefined;
      // ── Stale tail must NOT call hardStopPlayback - it would murder the new session’s op/sources.
      if (!this.stale(expectedGeneration)) {
        this.hardStopPlayback();
      }
      this.emit();
    }
  }
}// ── chat-persistence - browser-guarded CRUD helpers (no UI, no transports) ────
// > Failure mode: console.error + soft return - never chuck the orchestrator shell.
import { db, isBrowserChatDbAvailable } from "@/lib/chat-db";
import { isDuplicateFolderName, sortThreadsWithOrderFallback } from "@/lib/chat-folder-utils";
import type {
  ChatFolder,
  ChatMessage,
  ChatThread,
  NewChatMessageInput,
  NewChatThreadInput,
} from "@/lib/chat-db.types";
import type { ModelProfileId } from "@/lib/spirit/model-profile.types";

const NEW_CHAT_TITLE = "New chat";

export function buildTitleFromText(text: string): string {
  const oneLine = text.trim().replace(/\s+/g, " ");
  if (!oneLine) return NEW_CHAT_TITLE;
  const t = oneLine.slice(0, 42).trimEnd();
  return t || NEW_CHAT_TITLE;
}

export function generateChatRecordId(): string {
  try {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID();
    }
  } catch {
    /* fallthrough */
  }
  return `id_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
}

export async function createThread(
  input?: Partial<NewChatThreadInput>,
): Promise<ChatThread | undefined> {
  if (!db) return undefined;
  const now = Date.now();
  const thread: ChatThread = {
    id: generateChatRecordId(),
    title: input?.title ?? NEW_CHAT_TITLE,
    createdAt: now,
    updatedAt: now,
    archived: input?.archived ?? false,
    folderId: input?.folderId ?? undefined,
    order: input?.order,
    ...(input?.modelProfileId != null
      ? { modelProfileId: input.modelProfileId }
      : {}),
  };
  try {
    await db.threads.add(thread);
    return thread;
  } catch (e) {
    console.error("[chat-persistence] createThread:", e);
    return undefined;
  }
}

export async function getThread(id: string): Promise<ChatThread | undefined> {
  if (!db) return undefined;
  try {
    return await db.threads.get(id);
  } catch (e) {
    console.error("[chat-persistence] getThread:", e);
    return undefined;
  }
}

export async function updateThreadTitle(id: string, title: string): Promise<void> {
  if (!db) return;
  try {
    const now = Date.now();
    await db.threads.update(id, {
      title,
      updatedAt: now,
    });
  } catch (e) {
    console.error("[chat-persistence] updateThreadTitle:", e);
  }
}

export async function updateThreadModelProfile(
  threadId: string,
  profileId: ModelProfileId,
): Promise<void> {
  if (!db) return;
  try {
    await db.threads.update(threadId, {
      modelProfileId: profileId,
      updatedAt: Date.now(),
    });
  } catch (e) {
    console.error("[chat-persistence] updateThreadModelProfile:", e);
  }
}

export async function touchThread(id: string): Promise<void> {
  if (!db) return;
  try {
    await db.threads.update(id, { updatedAt: Date.now() });
  } catch (e) {
    console.error("[chat-persistence] touchThread:", e);
  }
}

export async function listThreads(): Promise<ChatThread[]> {
  if (!db) return [];
  try {
    return await db.threads.orderBy("updatedAt").reverse().toArray();
  } catch (e) {
    console.error("[chat-persistence] listThreads:", e);
    return [];
  }
}

export async function deleteThread(id: string): Promise<void> {
  if (!db) return;
  try {
    await db.transaction("rw", db.threads, db.messages, async () => {
      await db!.messages.where("threadId").equals(id).delete();
      await db!.threads.delete(id);
    });
  } catch (e) {
    console.error("[chat-persistence] deleteThread:", e);
  }
}

async function countUserMessages(threadId: string): Promise<number> {
  if (!db) return 0;
  try {
    return await db.messages
      .where("threadId")
      .equals(threadId)
      .filter((m) => m.role === "user")
      .count();
  } catch (e) {
    console.error("[chat-persistence] countUserMessages:", e);
    return 0;
  }
}

async function maybeRenameFromFirstUserMessage(
  threadId: string,
  userPlainText: string,
): Promise<void> {
  if (!db) return;
  try {
    const thread = await getThread(threadId);
    if (!thread || thread.title !== NEW_CHAT_TITLE) return;
    const n = await countUserMessages(threadId);
    if (n !== 1) return;
    await updateThreadTitle(threadId, buildTitleFromText(userPlainText));
  } catch (e) {
    console.error("[chat-persistence] maybeRenameFromFirstUserMessage:", e);
  }
}

/** Inserts row + bumps thread.updatedAt (+ auto-retitle stub thread on first user line). */
export async function saveMessage(
  input: NewChatMessageInput,
): Promise<ChatMessage | undefined> {
  if (!db || !isBrowserChatDbAvailable()) return undefined;
  const now = Date.now();
  const row: ChatMessage = {
    id: input.id ?? generateChatRecordId(),
    threadId: input.threadId,
    role: input.role,
    text: input.text,
    createdAt: now,
    updatedAt: now,
  };
  try {
    await db.messages.add(row);
    await touchThread(input.threadId);
    if (input.role === "user") {
      await maybeRenameFromFirstUserMessage(input.threadId, input.text);
    }
    return row;
  } catch (e) {
    console.error("[chat-persistence] saveMessage:", e);
    return undefined;
  }
}

export async function listMessages(threadId: string): Promise<ChatMessage[]> {
  if (!db) return [];
  try {
    return await db.messages.where("threadId").equals(threadId).sortBy("createdAt");
  } catch (e) {
    console.error("[chat-persistence] listMessages:", e);
    return [];
  }
}

export async function clearThreadMessages(threadId: string): Promise<void> {
  if (!db) return;
  try {
    await db.messages.where("threadId").equals(threadId).delete();
    await touchThread(threadId);
  } catch (e) {
    console.error("[chat-persistence] clearThreadMessages:", e);
  }
}

/** Persist outbound user plaintext (Dexie-only; align `messageId` with useChat user id when persisting-first). */
export async function persistUserOutboundMessage(
  threadId: string,
  text: string,
  messageId?: string,
): Promise<void> {
  if (!threadId.trim() || !text.trim()) return;
  await saveMessage({ threadId, role: "user", text, id: messageId });
}

/**
 * Persist a completed assistant turn once (idempotent per message id).
 * Does not duplicate if the row already exists (thread switch safe).
 */
export async function persistAssistantOutboundIfAbsent(
  threadId: string,
  messageId: string,
  text: string,
): Promise<void> {
  if (!db || !threadId.trim() || !messageId.trim()) return;
  const trimmed = text.trim();
  if (!trimmed) return;
  try {
    const existing = await db.messages.get(messageId);
    if (existing) return;
    await saveMessage({ threadId, role: "assistant", text: trimmed, id: messageId });
  } catch (e) {
    console.error("[chat-persistence] persistAssistantOutboundIfAbsent:", e);
  }
}

export async function updateMessageText(messageId: string, text: string): Promise<void> {
  if (!db) return;
  try {
    const row = await db.messages.get(messageId);
    if (!row) return;
    await db.messages.update(messageId, {
      text,
      updatedAt: Date.now(),
    });
    await touchThread(row.threadId);
  } catch (e) {
    console.error("[chat-persistence] updateMessageText:", e);
  }
}

export async function deleteMessage(messageId: string): Promise<void> {
  if (!db) return;
  try {
    const row = await db.messages.get(messageId);
    if (!row) return;
    await db.messages.delete(messageId);
    await touchThread(row.threadId);
  } catch (e) {
    console.error("[chat-persistence] deleteMessage:", e);
  }
}

export async function deleteMessages(messageIds: string[]): Promise<void> {
  if (!db || messageIds.length === 0) return;
  try {
    const threadIds = new Set<string>();
    for (const id of messageIds) {
      const row = await db.messages.get(id);
      if (row) threadIds.add(row.threadId);
    }
    await db.transaction("rw", db.messages, async () => {
      for (const id of messageIds) {
        await db!.messages.delete(id);
      }
    });
    for (const tid of threadIds) {
      await touchThread(tid);
    }
  } catch (e) {
    console.error("[chat-persistence] deleteMessages:", e);
  }
}

// ── Folders (Prompt 5) - CRUD only; delete never nukes threads ─────────────────

export async function createFolder(
  name?: string,
): Promise<ChatFolder | undefined> {
  if (!db) return undefined;
  const now = Date.now();
  let order = now;
  try {
    const last = await db.folders.orderBy("order").last();
    if (last != null) order = last.order + 1;
  } catch (e) {
    console.error("[chat-persistence] createFolder order probe:", e);
  }
  const trimmedName = name?.trim() || "New folder";
  try {
    const existing = await db.folders.toArray();
    if (isDuplicateFolderName(trimmedName, existing)) {
      return undefined;
    }
  } catch (e) {
    console.error("[chat-persistence] createFolder duplicate probe:", e);
  }
  const folder: ChatFolder = {
    id: generateChatRecordId(),
    name: trimmedName,
    createdAt: now,
    updatedAt: now,
    order,
    collapsed: false,
  };
  try {
    await db.folders.add(folder);
    return folder;
  } catch (e) {
    console.error("[chat-persistence] createFolder:", e);
    return undefined;
  }
}

export async function listFolders(): Promise<ChatFolder[]> {
  if (!db) return [];
  try {
    const rows = await db.folders.toArray();
    rows.sort((a, b) => a.order - b.order || b.updatedAt - a.updatedAt);
    return rows;
  } catch (e) {
    console.error("[chat-persistence] listFolders:", e);
    return [];
  }
}

export async function updateFolderName(id: string, name: string): Promise<boolean> {
  if (!db) return false;
  const trimmed = name.trim();
  if (!trimmed) return false;
  try {
    const rows = await db.folders.toArray();
    if (isDuplicateFolderName(trimmed, rows, id)) {
      return false;
    }
    await db.folders.update(id, { name: trimmed, updatedAt: Date.now() });
    return true;
  } catch (e) {
    console.error("[chat-persistence] updateFolderName:", e);
    return false;
  }
}

export async function updateFolderCollapsed(
  id: string,
  collapsed: boolean,
): Promise<void> {
  if (!db) return;
  try {
    await db.folders.update(id, { collapsed, updatedAt: Date.now() });
  } catch (e) {
    console.error("[chat-persistence] updateFolderCollapsed:", e);
  }
}

export async function deleteFolder(
  id: string,
  options?: { moveThreadsToRoot?: boolean },
): Promise<void> {
  if (!db) return;
  const moveThreadsToRoot = options?.moveThreadsToRoot !== false;
  try {
    await db.transaction("rw", db.threads, db.folders, async () => {
      if (moveThreadsToRoot) {
        const rows = await db!.threads.where("folderId").equals(id).toArray();
        for (const t of rows) {
          await db!.threads.update(t.id, {
            folderId: undefined,
          });
        }
      }
      await db!.folders.delete(id);
    });
  } catch (e) {
    console.error("[chat-persistence] deleteFolder:", e);
    return;
  }
  try {
    const rootAll = (await db.threads.toArray()).filter((t) => !t.folderId);
    const ids = sortThreadsWithOrderFallback(rootAll).map((t) => t.id);
    await reorderThreadsInFolder(null, ids);
  } catch (e) {
    console.error("[chat-persistence] deleteFolder root reorder:", e);
  }
}

export async function updateThreadFolderAndOrder(
  threadId: string,
  folderId: string | null,
  order: number,
): Promise<void> {
  if (!db) return;
  try {
    await db.threads.update(threadId, {
      folderId: folderId ?? undefined,
      order,
      updatedAt: Date.now(),
    });
  } catch (e) {
    console.error("[chat-persistence] updateThreadFolderAndOrder:", e);
  }
}

export async function reorderThreadsInFolder(
  folderId: string | null,
  orderedThreadIds: string[],
): Promise<void> {
  if (!db) {
    return;
  }
  const fid = folderId ?? undefined;
  try {
    await db.transaction("rw", db.threads, async () => {
      let i = 0;
      for (const id of orderedThreadIds) {
        i += 1;
        await db!.threads.update(id, {
          folderId: fid,
          order: i * 1000,
        });
      }
    });
  } catch (e) {
    console.error("[chat-persistence] reorderThreadsInFolder:", e);
  }
}

export async function reorderFolders(orderedFolderIds: string[]): Promise<void> {
  if (!db) return;
  try {
    await db.transaction("rw", db.folders, async () => {
      let i = 0;
      for (const id of orderedFolderIds) {
        i += 1;
        await db!.folders.update(id, { order: i * 1000, updatedAt: Date.now() });
      }
    });
  } catch (e) {
    console.error("[chat-persistence] reorderFolders:", e);
  }
}

export async function moveThreadToFolder(
  threadId: string,
  folderId: string | null,
): Promise<void> {
  if (!db) return;
  try {
    const fid = folderId ?? undefined;
    const all = await db.threads.toArray();
    const siblings = all.filter(
      (t) => (t.folderId ?? undefined) === fid && t.id !== threadId,
    );
    let maxO = 0;
    for (const t of siblings) {
      if (typeof t.order === "number" && !Number.isNaN(t.order)) {
        maxO = Math.max(maxO, t.order);
      }
    }
    await db.threads.update(threadId, {
      folderId: fid,
      order: maxO + 1000,
      updatedAt: Date.now(),
    });
  } catch (e) {
    console.error("[chat-persistence] moveThreadToFolder:", e);
  }
}

// ── Pins + local search (Prompt 10A) ────────────────────────────────────────────

export type ChatThreadSearchHit = {
  thread: ChatThread;
  snippet?: string;
};

/** Case-insensitive match on title + message bodies; empty query ⇒ []. */
export async function searchThreadsAndMessages(
  query: string,
): Promise<ChatThreadSearchHit[]> {
  if (!db) return [];
  const qq = query.trim().toLowerCase();
  if (!qq) return [];

  try {
    const threads = await db.threads.toArray();
    const hits: ChatThreadSearchHit[] = [];
    const seen = new Set<string>();

    for (const t of threads) {
      if (t.archived) continue;
      if (t.title.toLowerCase().includes(qq)) {
        seen.add(t.id);
        hits.push({ thread: t });
      }
    }

    const msgRows = await db.messages
      .filter((m) => m.text.toLowerCase().includes(qq))
      .toArray();

    for (const m of msgRows) {
      if (seen.has(m.threadId)) continue;
      const thread = threads.find((x) => x.id === m.threadId);
      if (!thread || thread.archived) continue;
      seen.add(m.threadId);
      const lower = m.text.toLowerCase();
      const idx = lower.indexOf(qq);
      const start = Math.max(0, idx - 36);
      const end = Math.min(m.text.length, idx + qq.length + 72);
      let snippet = m.text.slice(start, end).replace(/\s+/g, " ");
      if (start > 0) snippet = `…${snippet}`;
      if (end < m.text.length) snippet = `${snippet}…`;
      hits.push({ thread, snippet });
    }

    hits.sort((a, b) => b.thread.updatedAt - a.thread.updatedAt);
    return hits;
  } catch (e) {
    console.error("[chat-persistence] searchThreadsAndMessages:", e);
    return [];
  }
}

export async function pinThread(id: string): Promise<void> {
  if (!db) return;
  try {
    const now = Date.now();
    await db.threads.update(id, {
      pinned: true,
      pinnedAt: now,
      updatedAt: now,
    });
  } catch (e) {
    console.error("[chat-persistence] pinThread:", e);
  }
}

export async function unpinThread(id: string): Promise<void> {
  if (!db) return;
  try {
    await db.threads.update(id, {
      pinned: false,
      pinnedAt: undefined,
      updatedAt: Date.now(),
    });
  } catch (e) {
    console.error("[chat-persistence] unpinThread:", e);
  }
}// ── chat-sidebar-dnd - pure drop math (oldSpiritOS rules, Dexie-agnostic) ───────
// > parseDragId + getThreadLocation + computeThreadDropPlan - no DOM geometry.
import {
  closestCenter,
  pointerWithin,
  type Collision,
  type CollisionDetection,
} from "@dnd-kit/core";
import type { UniqueIdentifier } from "@dnd-kit/core";

import type { FolderSidebarSection } from "@/lib/chat-folder-utils";
import type { ChatThread } from "@/lib/chat-db.types";

export const THREAD_DND_PREFIX = "thread:";
export const FOLDER_DROP_PREFIX = "folder:";
/** Sortable folder row id — distinct from `folder:` thread-drop droppable on the same card. */
export const FOLDER_SORT_PREFIX = "folder-sort:";

export const CHAT_SIDEBAR_ROOT_DROP_ID = `${FOLDER_DROP_PREFIX}root` as const;

type CollisionArgs = Parameters<CollisionDetection>[0];

/** Survives pointerWithin membership jitter at row boundaries (see debug-eafb6b L217–228). */
let threadOverSticky: { activeId: string; overId: string } | null = null;

/** Call on thread drag start — activeId can match a prior drag; sticky must not leak. */
export function resetThreadCollisionSticky(): void {
  threadOverSticky = null;
}

type NearestFallbackArgs = Pick<
  CollisionArgs,
  "pointerCoordinates" | "droppableContainers" | "droppableRects"
>;

/**
 * When pointer sits in the gap between rects or closestCenter is dominated by the active item,
 * pick the nearest *other* droppable by rect-center distance (fixes flaky downward drags).
 */
/** @internal exported for unit tests */
export function fallbackNearestExcludingActive(
  args: NearestFallbackArgs,
  activeId: string,
): Collision[] {
  const pc = args.pointerCoordinates;
  if (!pc) return [];
  let best: Collision | null = null;
  let bestD = Number.POSITIVE_INFINITY;
  for (const cont of args.droppableContainers) {
    const sid = String(cont.id);
    if (sid === activeId) continue;
    const rect = args.droppableRects.get(cont.id);
    if (!rect) continue;
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const dx = pc.x - cx;
    const dy = pc.y - cy;
    const d = dx * dx + dy * dy;
    if (d < bestD) {
      bestD = d;
      best = { id: cont.id };
    }
  }
  return best ? [best] : [];
}

/**
 * When the pointer sits in overlapping / adjacent thread row rects, Euclidean “nearest center”
 * flips on tiny moves (runtime: onDragOver oscillates between two ids — Spirit debug log lines
 * 121–135). Partition vertically by midpoints between row centers so the active target is stable.
 */
/** @internal exported for unit tests */
export function pickThreadCollisionByVerticalMidpoints(
  threadHits: Collision[],
  pointerY: number,
  droppableRects: CollisionArgs["droppableRects"],
): Collision {
  if (threadHits.length === 1) return threadHits[0]!;

  const withCy = threadHits
    .map((h) => {
      const rect = droppableRects.get(h.id as UniqueIdentifier);
      const cy = rect ? rect.top + rect.height / 2 : pointerY;
      return { h, cy };
    })
    .sort((a, b) => a.cy - b.cy);

  if (withCy.length === 0) return threadHits[0]!;
  if (withCy.length === 1) return withCy[0]!.h;

  if (pointerY < (withCy[0]!.cy + withCy[1]!.cy) / 2) {
    return withCy[0]!.h;
  }
  for (let i = 1; i < withCy.length - 1; i++) {
    const midUp = (withCy[i - 1]!.cy + withCy[i]!.cy) / 2;
    const midDown = (withCy[i]!.cy + withCy[i + 1]!.cy) / 2;
    if (pointerY >= midUp && pointerY < midDown) {
      return withCy[i]!.h;
    }
  }
  return withCy[withCy.length - 1]!.h;
}

/** Sticky hand-off between midpoint-picked rows; exported for unit tests only. */
export function applyThreadOverHysteresis(
  picked: Collision,
  threadHits: Collision[],
  pointerY: number,
  droppableRects: CollisionArgs["droppableRects"],
  activeId: string,
): Collision {
  const pickedId = String(picked.id);
  if (threadHits.length < 2) {
    threadOverSticky = { activeId, overId: pickedId };
    return picked;
  }
  if (!threadOverSticky || threadOverSticky.activeId !== activeId) {
    threadOverSticky = { activeId, overId: pickedId };
    return picked;
  }
  const sid = threadOverSticky.overId;
  if (sid === pickedId) {
    return picked;
  }
  const stickyHit = threadHits.find((h) => String(h.id) === sid);
  if (!stickyHit) {
    threadOverSticky = { activeId, overId: pickedId };
    return picked;
  }
  const sr = droppableRects.get(stickyHit.id as UniqueIdentifier);
  const pr = droppableRects.get(picked.id as UniqueIdentifier);
  if (!sr || !pr) {
    threadOverSticky = { activeId, overId: pickedId };
    return picked;
  }
  const sMid = sr.top + sr.height / 2;
  const pMid = pr.top + pr.height / 2;
  if (Math.abs(sMid - pMid) < 1) {
    threadOverSticky = { activeId, overId: pickedId };
    return picked;
  }
  const boundary = (sMid + pMid) / 2;
  // Hand off exactly at row mid-boundary so `overId` tracks the midpoint pick (no +h stickiness).
  if (sMid < pMid) {
    if (pointerY < boundary) {
      return stickyHit;
    }
  } else {
    if (pointerY > boundary) {
      return stickyHit;
    }
  }
  threadOverSticky = { activeId, overId: pickedId };
  return picked;
}

/**
 * Prefer pointer hit targets so `folder:root` wins over ghost `closestCenter` folder grabs
 * when dragging a thread back to Chats - still picks nearest thread when hovering a row.
 */
export const chatSidebarThreadCollisionDetection: CollisionDetection = (args) => {
  const activeId = String(args.active.id);

  // Folder reorder: `closestCenter` after notSelf still picks thread rows under the pointer
  // (runtime debug-5a2791: overId thread:… while active folder-sort:… → reorder plan null).
  // Prefer other folder-sort rects, then folder: droppables — never thread:* for this drag type.
  if (activeId.startsWith(FOLDER_SORT_PREFIX)) {
    threadOverSticky = null;
    const idStr = (c: Collision) => String(c.id);
    const notSelf = (c: Collision) => idStr(c) !== activeId;
    const isThread = (c: Collision) => idStr(c).startsWith(THREAD_DND_PREFIX);
    const isFolderSort = (c: Collision) => idStr(c).startsWith(FOLDER_SORT_PREFIX);
    const isFolderDrop = (c: Collision) => {
      const s = idStr(c);
      return (
        s.startsWith(FOLDER_DROP_PREFIX) &&
        !s.startsWith(FOLDER_SORT_PREFIX) &&
        s !== CHAT_SIDEBAR_ROOT_DROP_ID
      );
    };

    const candidates = closestCenter(args).filter(notSelf);
    const folderSortHits = candidates.filter(isFolderSort);
    if (folderSortHits.length) return folderSortHits;

    const folderDropHits = candidates.filter(isFolderDrop);
    if (folderDropHits.length) return folderDropHits;

    const nonThread = candidates.filter((c) => !isThread(c));
    if (nonThread.length) return nonThread;

    // closestCenter can be thread-only when the pointer sits over expanded thread lists; still pick
    // the nearest folder card by rect so reorder doesn't die with over=null / thread steal.
    const fb = fallbackNearestExcludingActive(args, activeId).filter((c) => {
      const s = idStr(c);
      if (isThread(c)) return false;
      if (isFolderSort(c)) return true;
      return isFolderDrop(c);
    });
    return fb.length ? fb : [];
  }

  if (!activeId.startsWith(THREAD_DND_PREFIX)) {
    threadOverSticky = null;
    return closestCenter(args);
  }

  const idStr = (c: Collision) => String(c.id);

  /** Never treat the dragged thread as the drop target — self-drop makes computeThreadDropPlan return null. */
  const notSelf = (c: Collision) => idStr(c) !== activeId;

  const pw = pointerWithin(args).filter(notSelf);
  if (pw.length === 0) {
    threadOverSticky = null;
    const cc = closestCenter(args).filter(notSelf);
    if (cc.length) return cc;
    const fb = fallbackNearestExcludingActive(args, activeId);
    return fb.length ? fb : [];
  }

  const threadHits = pw.filter((c) => idStr(c).startsWith(THREAD_DND_PREFIX));
  if (threadHits.length > 0) {
    const pc = args.pointerCoordinates;
    if (!pc || threadHits.length === 1) return [threadHits[0]!];

    const midpointPick = pickThreadCollisionByVerticalMidpoints(
      threadHits,
      pc.y,
      args.droppableRects,
    );
    const stabilized = applyThreadOverHysteresis(
      midpointPick,
      threadHits,
      pc.y,
      args.droppableRects,
      activeId,
    );
    return [stabilized];
  }

  const root = pw.find((c) => idStr(c) === CHAT_SIDEBAR_ROOT_DROP_ID);
  if (root) return [root];

  const folderHits = pw.filter((c) => {
    const s = idStr(c);
    return (
      s.startsWith(FOLDER_DROP_PREFIX) &&
      !s.startsWith(FOLDER_SORT_PREFIX) &&
      s !== CHAT_SIDEBAR_ROOT_DROP_ID
    );
  });
  if (folderHits.length > 0) return [folderHits[folderHits.length - 1]!];

  const cc = closestCenter(args).filter(notSelf);
  if (cc.length) return cc;
  const fb = fallbackNearestExcludingActive(args, activeId);
  return fb.length ? fb : [];
};

export type ThreadReorderOp = { folderId: string | null; orderedIds: string[] };

export type ParsedDragId =
  | { kind: "thread"; threadId: string }
  | { kind: "folder"; folderId: string | null }
  | { kind: "unknown" };

export function parseDragId(id: string): ParsedDragId {
  if (id.startsWith(THREAD_DND_PREFIX)) {
    return { kind: "thread", threadId: id.slice(THREAD_DND_PREFIX.length) };
  }
  if (id.startsWith(FOLDER_SORT_PREFIX)) {
    return { kind: "unknown" };
  }
  if (id === CHAT_SIDEBAR_ROOT_DROP_ID) {
    return { kind: "folder", folderId: null };
  }
  if (id.startsWith(FOLDER_DROP_PREFIX)) {
    return {
      kind: "folder",
      folderId: id.slice(FOLDER_DROP_PREFIX.length),
    };
  }
  return { kind: "unknown" };
}

export type ThreadLocation =
  | { bucket: "root" }
  | { bucket: "folder"; folderId: string };

export function getThreadLocation(
  threadId: string,
  rootThreads: ChatThread[],
  folderSections: FolderSidebarSection[],
): ThreadLocation | undefined {
  if (rootThreads.some((t) => t.id === threadId)) return { bucket: "root" };
  for (const s of folderSections) {
    if (s.threads.some((t) => t.id === threadId)) {
      return { bucket: "folder", folderId: s.folder.id };
    }
  }
  return undefined;
}

function bucketKey(loc: ThreadLocation): string | null {
  return loc.bucket === "root" ? null : loc.folderId;
}

function cloneBuckets(
  rootThreads: ChatThread[],
  folderSections: FolderSidebarSection[],
): Map<string | null, ChatThread[]> {
  const m = new Map<string | null, ChatThread[]>();
  m.set(null, [...rootThreads]);
  for (const s of folderSections) {
    m.set(s.folder.id, [...s.threads]);
  }
  return m;
}

/** dnd-kit-style move: indices are positions in the *original* list before the move. */
function arrayMoveLocal<T>(items: T[], from: number, to: number): T[] {
  const next = [...items];
  const [item] = next.splice(from, 1);
  next.splice(to, 0, item);
  return next;
}

/** Reorder sidebar folders (Dexie `folders.order`) after a folder card drag. */
export function computeFolderReorderPlan(args: {
  activeFolderId: string;
  overId: string;
  folderSections: FolderSidebarSection[];
}): string[] | null {
  const { activeFolderId, overId, folderSections } = args;
  const order = folderSections.map((s) => s.folder.id);
  const activeIdx = order.indexOf(activeFolderId);
  if (activeIdx < 0) return null;

  let overFolderId: string | null = null;
  if (overId.startsWith(FOLDER_SORT_PREFIX)) {
    overFolderId = overId.slice(FOLDER_SORT_PREFIX.length);
  } else if (
    overId.startsWith(FOLDER_DROP_PREFIX) &&
    overId !== CHAT_SIDEBAR_ROOT_DROP_ID
  ) {
    overFolderId = overId.slice(FOLDER_DROP_PREFIX.length);
  } else {
    return null;
  }

  const overIdx = order.indexOf(overFolderId);
  if (overIdx < 0 || activeIdx === overIdx) return null;

  return arrayMoveLocal(order, activeIdx, overIdx);
}

/** Dexie reorder writes after a thread drag (root = null bucket). */
export function computeThreadDropPlan(args: {
  activeThreadId: string;
  overId: string;
  rootThreads: ChatThread[];
  folderSections: FolderSidebarSection[];
}): ThreadReorderOp[] | null {
  const { activeThreadId, overId, rootThreads, folderSections } = args;
  if (!activeThreadId) return null;

  const overParsed = parseDragId(overId);
  if (overParsed.kind === "unknown") return null;
  if (
    overParsed.kind === "thread" &&
    overParsed.threadId === activeThreadId
  ) {
    return null;
  }

  const srcLoc = getThreadLocation(activeThreadId, rootThreads, folderSections);
  if (!srcLoc) return null;
  const srcKey = bucketKey(srcLoc);

  let destKey: string | null;
  let overThreadId: string | null = null;

  if (overParsed.kind === "folder") {
    destKey = overParsed.folderId;
  } else {
    overThreadId = overParsed.threadId;
    const overLoc = getThreadLocation(overThreadId, rootThreads, folderSections);
    if (!overLoc) return null;
    destKey = bucketKey(overLoc);
  }

  // Same bucket + hovering another thread: arrayMove on original order. Remove+insertBefore
  // was wrong for downward drags (remove B then insert before C → noop).
  if (overThreadId != null && srcKey === destKey) {
    const originalIds = cloneBuckets(rootThreads, folderSections)
      .get(srcKey)!
      .map((t) => t.id);
    const activeIdx = originalIds.indexOf(activeThreadId);
    const overIdx = originalIds.indexOf(overThreadId);
    if (activeIdx < 0 || overIdx < 0 || activeIdx === overIdx) return null;
    const orderedIds = arrayMoveLocal(originalIds, activeIdx, overIdx);
    return [{ folderId: srcKey, orderedIds }];
  }

  let insertBeforeThreadId: string | null = null;
  if (overParsed.kind === "thread") {
    insertBeforeThreadId = overParsed.threadId;
  }

  const buckets = cloneBuckets(rootThreads, folderSections);
  const srcList = buckets.get(srcKey)!;
  const activeIdx = srcList.findIndex((t) => t.id === activeThreadId);
  if (activeIdx < 0) return null;
  const [moving] = srcList.splice(activeIdx, 1);

  const dstList = buckets.get(destKey)!;

  if (insertBeforeThreadId) {
    const ins = dstList.findIndex((t) => t.id === insertBeforeThreadId);
    if (ins >= 0) dstList.splice(ins, 0, moving);
    else dstList.push(moving);
  } else {
    dstList.push(moving);
  }

  if (srcKey === destKey) {
    return [{ folderId: srcKey, orderedIds: dstList.map((t) => t.id) }];
  }
  return [
    { folderId: srcKey, orderedIds: srcList.map((t) => t.id) },
    { folderId: destKey, orderedIds: dstList.map((t) => t.id) },
  ];
}

/** @deprecated use computeThreadDropPlan */
export const computeThreadDragOps = computeThreadDropPlan;

/** Pure gate: desktop rail vs mobile drawer-only DnD (Prompt 9F). */
export function shouldEnableChatThreadSidebarDnd(opts: {
  /** Thread bucket reorder and/or folder reorder — either arms the sidebar DnD shell. */
  hasCommitHandler: boolean;
  railLocked: boolean;
  lgDesktop: boolean;
  layoutVariant: "default" | "drawer";
  mobileDndEnabled: boolean;
}): boolean {
  return Boolean(
    opts.hasCommitHandler &&
      !opts.railLocked &&
      (opts.lgDesktop || (opts.layoutVariant === "drawer" && opts.mobileDndEnabled)),
  );
