  type OracleVoiceLoopMode,
} from "@/lib/oracle/oracle-voice-session";
import { getOracleVisualStateFromSessionStatus } from "@/lib/oracle/oracle-visual-state";
import "@/components/oracle/oracle-visuals.css";
