  persistedChatRowsToUIMessages,
  textFromParts,
  updateUIMessageText,
} from "@/lib/chat-utils";
import { generateChatRecordId } from "@/lib/chat-persistence";
import { sanitizeAssistantVisibleText } from "@/lib/spirit/assistant-output-sanitizer";
