  getRecentOracleMemoryEvents,
  isOracleMemoryEnabled,
  summarizeOracleMemoryForPrompt,
} from "@/lib/oracle/oracle-memory";

type WebSearchPreference = "unset" | "enabled" | "disabled";

export type UseSpiritChatTransportInput = {
  api: string;
  persistence: boolean;
  persistenceEnabled: boolean;
  savedChatShell: boolean;
  workspaceChrome: boolean;
  attachSpiritBody: boolean;
  persistent: ReturnType<typeof usePersistentChat>;
  modeRuntime: SpiritModeRuntime;
  /** Unified mode id (Dexie thread profile or Oracle ephemeral) */
  activeModelProfileId: ModelProfileId;
  ttsRef: RefObject<SpiritTTS | null>;
  ttsSpeakGateRef: RefObject<{ isEnabled: boolean; autoSpeakAssistant: boolean }>;
  pushActivity: (e: Omit<SpiritActivityEvent, "id" | "at">) => void;
  /** Scroll container coordination - optional for embedded/minimal shells */
  outboundScrollRefs?: {
    forceScrollOnNextMessageRef: MutableRefObject<boolean>;
    shouldStickToBottomRef: MutableRefObject<boolean>;
  } | null;
};

export type SpiritChatTransport = {
  messages: UIMessage[];
  setMessages: (
    messages: UIMessage[] | ((messages: UIMessage[]) => UIMessage[]),
  ) => void;
  sendMessage: ReturnType<typeof useChat>["sendMessage"];
  regenerate: ReturnType<typeof useChat>["regenerate"];
  stop: ReturnType<typeof useChat>["stop"];
  status: ReturnType<typeof useChat>["status"];
  error: ReturnType<typeof useChat>["error"];
  input: string;
  setInput: (v: string | ((p: string) => string)) => void;
  isBusy: boolean;
  submitMessage: () => void;
  onSubmit: (e: FormEvent) => void;
  onKeyDown: (e: KeyboardEvent<HTMLTextAreaElement>) => void;
  runSpiritOutbound: (t: string) => Promise<void>;

  assistantSourceProof: import("@/hooks/useSpiritVoiceRuntime").AssistantSourceProofState;
  setAssistantSourceProof: Dispatch<
    SetStateAction<import("@/hooks/useSpiritVoiceRuntime").AssistantSourceProofState>
  >;

  handleMessageDelete: (id: string) => void;
  handleMessageEditSave: (id: string, text: string) => void;
  handleRegenerateAssistant: (assistantId: string) => Promise<void>;
  lastAssistantId: string | null;

  deepThinkEnabled: boolean;
  setDeepThinkEnabled: Dispatch<SetStateAction<boolean>>;
  webSearchPreference: WebSearchPreference;
  setWebSearchPreference: Dispatch<SetStateAction<WebSearchPreference>>;
  teacherWebSearchEnabled: boolean;
  setTeacherWebSearchEnabled: Dispatch<SetStateAction<boolean>>;
  webSearchOptOut: boolean;

  lastOutboundUserSnapshot: string;
  lastWebSearchHeader: string | null;
  lastSearchStatus: SpiritSearchStatusNormalized;
  lastSearchProvider: string | null;
  lastSearchQuery: string | null;
  lastSearchElapsedMs: number | null;
  lastSearchKind: "researcher" | "teacher" | "none";
  lastSearchSkipReason: string | null;
  lastHeaderSourceCount: number | null;
  lastWebSourcesPayload: SpiritWebSourcesHeaderPayload | null;
  lastRouteLane: SpiritRouteLane | null;
  lastRouteConfidence: string | null;
  workflowDismissed: boolean;
  setWorkflowDismissed: Dispatch<SetStateAction<boolean>>;
  workflowStepIdx: number;
  setWorkflowStepIdx: Dispatch<SetStateAction<number>>;
  researchPlanOpen: boolean;
  setResearchPlanOpen: Dispatch<SetStateAction<boolean>>;
  researchPlan: ResearchPlan | null;
  setResearchPlan: Dispatch<SetStateAction<ResearchPlan | null>>;
  pendingResearchPlanSummaryRef: React.MutableRefObject<string | null>;
  lastSentForPlanRef: React.MutableRefObject<string>;
  handleResearchPlanClose: () => void;
  handleResearchPlanStart: (plan: ResearchPlan) => void;

  hydrateDraftMarkerRef: React.MutableRefObject<string | null>;
  hydrateSigRef: React.MutableRefObject<string>;
  hydrateThreadFocusRef: React.MutableRefObject<string | null>;
  skipDexieHydrateRef: React.MutableRefObject<boolean>;

  onSidebarNewChatResetHydration: () => void;
  onSidebarSelectResetHydration: () => void;

  assistantOutcomeThreadRef: React.MutableRefObject<string | null>;
  spiritOutboundSeqRef: React.MutableRefObject<number>;
};

export function useSpiritChatTransport(
  input: UseSpiritChatTransportInput,
): SpiritChatTransport {
  const {
    api,
    persistence,
    persistenceEnabled,
    savedChatShell,
    attachSpiritBody,
    persistent,
    modeRuntime,
    activeModelProfileId,
    ttsRef,
    ttsSpeakGateRef,
    pushActivity,
    outboundScrollRefs,
  } = input;

  const modelProfileIdRef = modeRuntime.modelProfileIdRef;
  const runtimeSurfaceRef = modeRuntime.runtimeSurfaceRef;

  const assistantOutcomeThreadRef = useRef<string | null>(null);
  const persistAssistantToThreadRef = useRef(persistent.persistAssistantMessageToThread);
  useEffect(() => {
    persistAssistantToThreadRef.current = persistent.persistAssistantMessageToThread;
  }, [persistent.persistAssistantMessageToThread]);

  const persistentRef = useRef(persistent);
  useEffect(() => {
    persistentRef.current = persistent;
  }, [persistent]);

  const activeThreadIdRef = useRef<string | null>(null);
  useEffect(() => {
    if (!savedChatShell || !persistent.enabled) {
      activeThreadIdRef.current = null;
      return;
    }
    activeThreadIdRef.current = persistent.draftLaneActive
      ? null
      : (persistent.activeThreadId ?? null);
  }, [
    savedChatShell,
    persistent.enabled,
    persistent.draftLaneActive,
    persistent.activeThreadId,
  ]);

  const THREAD_UI_LS = "spirit:threadUiPrefs:v2";
  const THREAD_UI_LEGACY = "spirit:threadUiPrefs:v1";

  const persistUiPrefsToStorage = savedChatShell && persistent.enabled;

  const [deepThinkEnabled, setDeepThinkEnabled] = useState(false);
  const [webSearchPreference, setWebSearchPreference] =
    useState<WebSearchPreference>("unset");
  const [teacherWebSearchEnabled, setTeacherWebSearchEnabled] = useState(true);

  const threadUiStorageKey = useCallback((): string | null => {
    if (!persistUiPrefsToStorage) return null;
    if (persistent.draftLaneActive) return "draft";
    if (persistent.activeThreadId) return persistent.activeThreadId;
    return null;
  }, [
    persistUiPrefsToStorage,
    persistent.draftLaneActive,
    persistent.activeThreadId,
  ]);

  useEffect(() => {
    if (!persistUiPrefsToStorage) return;
    const k = threadUiStorageKey();
    if (!k) return;
    try {
      let raw = window.localStorage.getItem(THREAD_UI_LS);
      if (!raw) raw = window.localStorage.getItem(THREAD_UI_LEGACY);
      const map = raw
        ? (JSON.parse(raw) as Record<
            string,
            { d?: boolean; o?: boolean; w?: boolean; tw?: boolean; wp?: WebSearchPreference }
          >)
        : {};
      const row = map[k];
      setDeepThinkEnabled(Boolean(row?.d));
      let pref: WebSearchPreference = "unset";
      if (row?.wp === "enabled" || row?.wp === "disabled" || row?.wp === "unset") {
        pref = row.wp;
      } else if (row?.o === true) {
        pref = "disabled";
      }
      setWebSearchPreference(pref);
      setTeacherWebSearchEnabled(row?.tw !== false);
    } catch {
      setDeepThinkEnabled(false);
      setWebSearchPreference("unset");
      setTeacherWebSearchEnabled(true);
    }
  }, [persistUiPrefsToStorage, threadUiStorageKey]);

  useEffect(() => {
    if (!persistUiPrefsToStorage) return;
    const k = threadUiStorageKey();
    if (!k) return;
    try {
      const raw = window.localStorage.getItem(THREAD_UI_LS);
      const map = raw
        ? (JSON.parse(raw) as Record<
            string,
            { d?: boolean; o?: boolean; tw?: boolean; wp?: WebSearchPreference }
          >)
        : {};
      map[k] = {
        d: deepThinkEnabled,
        tw: teacherWebSearchEnabled,
        wp: webSearchPreference,
      };
      window.localStorage.setItem(THREAD_UI_LS, JSON.stringify(map));
    } catch {
      /* ignore */
    }
  }, [
    persistUiPrefsToStorage,
    threadUiStorageKey,
    deepThinkEnabled,
    webSearchPreference,
    teacherWebSearchEnabled,
  ]);

  const webSearchOptOut = useMemo(
    () =>
      activeModelProfileId === "researcher" && webSearchPreference === "disabled",
    [activeModelProfileId, webSearchPreference],
  );

  const [researchPlanOpen, setResearchPlanOpen] = useState(false);
  const [researchPlan, setResearchPlan] = useState<ResearchPlan | null>(null);
  const [workflowDismissed, setWorkflowDismissed] = useState(false);
  const [workflowStepIdx, setWorkflowStepIdx] = useState(0);

  const [lastWebSearchHeader, setLastWebSearchHeader] = useState<string | null>(null);
  const [lastSearchStatus, setLastSearchStatus] =
    useState<SpiritSearchStatusNormalized>("none");
  const [lastSearchProvider, setLastSearchProvider] = useState<string | null>(null);
  const [lastSearchQuery, setLastSearchQuery] = useState<string | null>(null);
  const [lastSearchElapsedMs, setLastSearchElapsedMs] = useState<number | null>(null);
  const [lastSearchKind, setLastSearchKind] = useState<"researcher" | "teacher" | "none">(
    "none",
  );
  const [lastSearchSkipReason, setLastSearchSkipReason] = useState<string | null>(null);
  const [lastHeaderSourceCount, setLastHeaderSourceCount] = useState<number | null>(null);
  const [lastWebSourcesPayload, setLastWebSourcesPayload] =
    useState<SpiritWebSourcesHeaderPayload | null>(null);
  const [lastOutboundUserSnapshot, setLastOutboundUserSnapshot] = useState("");
  const [lastRouteLane, setLastRouteLane] = useState<SpiritRouteLane | null>(null);
  const [lastRouteConfidence, setLastRouteConfidence] = useState<string | null>(null);

  const [assistantSourceProof, setAssistantSourceProof] = useState<
    import("@/hooks/useSpiritVoiceRuntime").AssistantSourceProofState
  >(null);

  const pendingResearchPlanSummaryRef = useRef<string | null>(null);
  const lastSentForPlanRef = useRef("");
  const assistantReplyModeRef = useRef<ModelProfileId>(activeModelProfileId);

  const outboundExtrasRef = useRef({
    deepThinkEnabled: false,
    webSearchOptOut: false,
    teacherWebSearchEnabled: true,
  });
  const spiritOutboundSeqRef = useRef(0);
  const lastSearchHdrRef = useRef<string | null>(null);
  const lastSourcesPayloadRef = useRef<SpiritWebSourcesHeaderPayload | null>(null);
  const streamHdrRef = useRef<(myId: number, parsed: ReturnType<typeof parseSpiritSearchHeaders>) => void>(
    () => {},
  );

  useEffect(() => {
    if (activeModelProfileId !== "researcher") {
      setResearchPlanOpen(false);
      setResearchPlan(null);
    }
  }, [activeModelProfileId]);

  const threadFocusKeyRef = useRef<string | null>(null);
  useEffect(() => {
    if (!savedChatShell) return;
    const key = persistent.draftLaneActive
      ? `draft:${persistent.draftLaneId ?? ""}`
      : (persistent.activeThreadId ?? "");
    if (threadFocusKeyRef.current === key) return;
    threadFocusKeyRef.current = key;
    setResearchPlanOpen(false);
    setResearchPlan(null);
    setLastRouteLane(null);
    setLastRouteConfidence(null);
    setLastWebSearchHeader(null);
    setLastWebSourcesPayload(null);
    setLastSearchStatus("none");
    setLastSearchProvider(null);
    setLastSearchQuery(null);
    setLastSearchElapsedMs(null);
    setLastSearchKind("none");
    setLastSearchSkipReason(null);
    setLastHeaderSourceCount(null);
    lastSearchHdrRef.current = null;
    lastSourcesPayloadRef.current = null;
    setAssistantSourceProof(null);
    setWorkflowDismissed(false);
  }, [
    savedChatShell,
    persistent.activeThreadId,
    persistent.draftLaneActive,
    persistent.draftLaneId,
  ]);

  useEffect(() => {
    streamHdrRef.current = (myId, parsed) => {
      if (myId !== spiritOutboundSeqRef.current) return;
      const outcomeThread = assistantOutcomeThreadRef.current;
      const active = activeThreadIdRef.current;
      const draft = persistentRef.current.draftLaneActive;
      if (
        outcomeThread != null &&
        active != null &&
        outcomeThread !== active &&
        !draft
      ) {
        return;
      }
      const h = parsed.webSearch;
      setLastWebSearchHeader(h);
      lastSearchHdrRef.current = h;
      setLastSearchStatus(parsed.searchStatus);
      setLastSearchProvider(parsed.searchProvider);
      setLastSearchQuery(parsed.searchQuery);
      setLastSearchElapsedMs(parsed.searchElapsedMs);
      setLastSearchKind(parsed.searchKind);
      setLastSearchSkipReason(parsed.skipReason);
      setLastHeaderSourceCount(parsed.sourceCount);

      const sourcesJson = parsed.webSourcesJson;
      if (sourcesJson) {
        const src = parseSpiritWebSourcesHeader(sourcesJson);
        setLastWebSourcesPayload(src);
        lastSourcesPayloadRef.current = src;
      } else {
        setLastWebSourcesPayload(null);
        lastSourcesPayloadRef.current = null;
      }
      const laneH = parsed.routeLane;
      if (
        laneH &&
        (laneH === "local-chat" ||
          laneH === "local-web-search" ||
          laneH === "openai-web-search" ||
          laneH === "research-plan")
      ) {
        if (laneH !== "research-plan") {
          setLastRouteLane(laneH as SpiritRouteLane);
        }
      }
      if (parsed.routeConfidence) setLastRouteConfidence(parsed.routeConfidence);
      if (!savedChatShell) return;
      if (!h || h === "none") return;
      const prov = sourcesJson
        ? (() => {
            try {
              const o = JSON.parse(sourcesJson) as { provider?: string; count?: number };
              return ` · Provider: ${o.provider ?? "unknown"} · Sources found: ${typeof o.count === "number" ? o.count : "?"}`;
            } catch {
              return "";
            }
          })()
        : "";
      const elapsed =
        parsed.searchElapsedMs != null ? ` · ${(parsed.searchElapsedMs / 1000).toFixed(1)}s` : "";
      pushActivity({
        kind: "workflow_step",
        label: `Search: ${parsed.searchStatus}${elapsed}${prov} · Route: ${laneH ?? "?"}`,
      });
    };
  }, [savedChatShell, pushActivity]);

  const handleChatFinish = useCallback(
    (event: { message: UIMessage }) => {
      if (event.message.role !== "assistant") return;

      const threadId = assistantOutcomeThreadRef.current;
      let body = sanitizeAssistantVisibleText(textFromParts(event.message).trim());
      const hdr = lastSearchHdrRef.current;
      const hadVerified =
        hdr === "used" &&
        (lastSourcesPayloadRef.current?.sources?.some((s) => /^https?:\/\//i.test(s.url)) ??
          false);
      if (assistantReplyModeRef.current === "researcher" && !hadVerified) {
        body = stripFakeCitationsWhenNoSources(body);
      }
      const p = persistentRef.current;

      const plan = planAssistantOutboundFinish({
        threadId,
        body,
        activeThreadId: activeThreadIdRef.current,
        draftLaneActive: p.draftLaneActive,
      });

      if (plan.kind === "skip" && plan.reason === "wrong-thread") {
        if (process.env.NODE_ENV === "development") {
          console.info(`[tts] auto-speak skipped: stale thread`);
        }
        return;
      }

      const toolCards = mergeSpiritToolActivityCardsForMessage(event.message);
      for (const c of toolCards) {
        const ev = spiritToolCardToActivityEvent(c);
        const { id: _tid, at: _tat, ...rest } = ev;
        pushActivity(rest as Omit<SpiritActivityEvent, "id" | "at">);
      }

      if (plan.kind === "skip" && plan.reason === "empty-assistant-text") {
        return;
      }

      const proofPayload = {
        messageId: event.message.id,
        hadVerifiedUrls: hadVerified,
        profileId: assistantReplyModeRef.current,
        webSources:
          hadVerified && lastSourcesPayloadRef.current
            ? {
                provider: lastSourcesPayloadRef.current.provider,
                count: lastSourcesPayloadRef.current.count,
                sources: lastSourcesPayloadRef.current.sources.map((s) => ({
                  title: s.title,
                  url: s.url,
                  ...(s.snippet ? { snippet: s.snippet } : {}),
                })),
              }
            : null,
      };

      const shouldDexieCommit = savedChatShell && plan.kind === "commit";

      if (shouldDexieCommit) {
        setAssistantSourceProof(proofPayload);
        assistantOutcomeThreadRef.current = null;
        void persistAssistantToThreadRef.current(threadId!, event.message.id, body);
        pushActivity({
          kind: "assistant_finished",
          label: "Assistant reply finished",
        });
      } else if (!savedChatShell && body.trim()) {
        setAssistantSourceProof(proofPayload);
        assistantOutcomeThreadRef.current = null;
      } else if (savedChatShell && plan.kind === "skip") {
        if (process.env.NODE_ENV === "development") {
          const r =
            plan.reason === "no-outcome-thread"
              ? "no outcome thread"
              : plan.reason;
          console.info(`[spirit-chat] assistant finish skipped: ${r}`);
        }
        return;
      }

      const msgId = event.message.id;
      const bodyForSpeak = body;
      const canAutoSpeak =
        bodyForSpeak.trim().length > 0 &&
        (plan.kind === "commit" ||
          (plan.kind === "skip" && plan.reason === "no-outcome-thread"));

      if (!canAutoSpeak) return;

      queueMicrotask(() => {
        const gate = ttsSpeakGateRef.current;
        const hook = ttsRef.current;
        if (!hook) return;
        runAutoSpeakAssistantFinish({
          text: bodyForSpeak,
          messageId: msgId,
          speak: hook.speak.bind(hook),
          voiceEnabled: gate.isEnabled,
          autoSpeakAssistant: gate.autoSpeakAssistant,
        });
        if (
          bodyForSpeak.length > TTS_TEXT_LIMIT &&
          gate.autoSpeakAssistant &&
          gate.isEnabled
        ) {
          pushActivity({
            kind: "voice_played",
            label: "Voice spoke summary because message was long.",
          });
        }
      });
    },
    [savedChatShell, pushActivity, ttsRef, ttsSpeakGateRef],
  );

  const transport = useMemo(() => {
    if (!attachSpiritBody) {
      return new DefaultChatTransport({ api });
    }
    return new DefaultChatTransport({
      api,
      fetch: async (initInput, init) => {
        const myId = ++spiritOutboundSeqRef.current;
        const res = await globalThis.fetch(initInput, init);
        const parsed = parseSpiritSearchHeaders(res);
        streamHdrRef.current(myId, parsed);
        return res;
      },
      prepareSendMessagesRequest: async ({ body, messages: msgs }) => {
        const profile = loadSpiritUserProfile();
        const summary = buildModeAwarePersonalizationSummary(
          profile,
          modelProfileIdRef.current,
        ).trim();
        const x = outboundExtrasRef.current;
        const rPlan = pendingResearchPlanSummaryRef.current?.trim();
        pendingResearchPlanSummaryRef.current = null;
        let oracleMemoryContext: string | undefined;
        if (isOracleMemoryEnabled()) {
          const events = await getRecentOracleMemoryEvents();
          const ctx = summarizeOracleMemoryForPrompt(events);
          if (ctx) oracleMemoryContext = ctx;
        }
        return {
          body: {
            ...body,
            messages: msgs,
            modelProfileId: modelProfileIdRef.current,
            runtimeSurface: runtimeSurfaceRef.current,
            deepThinkEnabled: x.deepThinkEnabled,
            webSearchOptOut: x.webSearchOptOut,
            teacherWebSearchEnabled: x.teacherWebSearchEnabled,
            ...(rPlan ? { researchPlanSummary: rPlan } : {}),
            ...(summary ? { personalizationSummary: summary } : {}),
            ...(oracleMemoryContext ? { oracleMemoryContext } : {}),
          },
        };
      },
    });
  }, [api, attachSpiritBody, modelProfileIdRef, runtimeSurfaceRef]);

  const { messages, sendMessage, regenerate, stop, status, error, setMessages } = useChat({
    transport,
    onFinish: handleChatFinish,
  });

  const [composerInput, setComposerInput] = useState("");
  const isBusy = status === "submitted" || status === "streaming";

  const submitGuardRef = useRef(false);
  useEffect(() => {
    if (!isBusy) submitGuardRef.current = false;
  }, [isBusy]);

  const hydrateSigRef = useRef("");
  const hydrateThreadFocusRef = useRef<string | null>(null);
  const hydrateDraftMarkerRef = useRef<string | null>(null);
  const skipDexieHydrateRef = useRef(false);

  useEffect(() => {
    if (!savedChatShell || !persistent.enabled) return;

    if (persistent.draftLaneActive) {
      const d = persistent.draftLaneId;
      if (!d) return;

      if (hydrateDraftMarkerRef.current !== d) {
        hydrateDraftMarkerRef.current = d;
        hydrateThreadFocusRef.current = null;
        hydrateSigRef.current = "";
        setMessages([]);
      }
      return;
    }

    hydrateDraftMarkerRef.current = null;

    const threadId = persistent.activeThreadId;
    if (!threadId) return;

    const threadIdSnap = threadId;

    const threadFlip = hydrateThreadFocusRef.current !== threadId;
    if (threadFlip) {
      hydrateThreadFocusRef.current = threadId;
      hydrateSigRef.current = "";
      setMessages([]);
    }

    if (!persistent.isPersistedHydrationReady) return;

    const tail = messages.at(-1);
    const pendingRemoteAssistant =
      !threadFlip &&
      status === "ready" &&
      tail?.role === "assistant" &&
      !persistent.persistedMessages.some((p) => p.id === tail.id);

    if (pendingRemoteAssistant) return;

    const busySameThread = isBusy && !threadFlip;
    if (busySameThread) return;

    if (skipDexieHydrateRef.current) return;

    const visible = persistent.persistedMessages.filter(
      (r) => r.role === "user" || r.role === "assistant",
    );
    const sig = visible.map((r) => `${r.id}\u001f${r.text}`).join("\u001e");
    if (!threadFlip && sig === hydrateSigRef.current) return;
    hydrateSigRef.current = sig;
    const p = persistentRef.current;
    if (p.activeThreadId !== threadIdSnap || p.draftLaneActive) {
      return;
    }
    setMessages(dedupeUIMessagesById(persistedChatRowsToUIMessages(visible)));
  }, [
    savedChatShell,
    persistent.enabled,
    persistent.draftLaneActive,
    persistent.draftLaneId,
    persistent.activeThreadId,
    persistent.persistedMessages,
    persistent.isPersistedHydrationReady,
    isBusy,
    status,
    messages,
    setMessages,
  ]);

  const onSidebarNewChatResetHydration = useCallback(() => {
    hydrateDraftMarkerRef.current = null;
    hydrateSigRef.current = "";
    hydrateThreadFocusRef.current = null;
  }, []);

  const onSidebarSelectResetHydration = useCallback(() => {
    hydrateDraftMarkerRef.current = null;
    hydrateSigRef.current = "";
    hydrateThreadFocusRef.current = null;
  }, []);

  const runSpiritOutbound = useCallback(
    async (t: string) => {
      const trimmed = t.trim();
      if (!trimmed) {
        submitGuardRef.current = false;
        return;
      }
      try {
        outboundExtrasRef.current = {
          deepThinkEnabled,
          webSearchOptOut: activeModelProfileId === "researcher" ? webSearchOptOut : false,
          teacherWebSearchEnabled: activeModelProfileId === "teacher" ? teacherWebSearchEnabled : false,
        };
        assistantReplyModeRef.current = activeModelProfileId;
        setWorkflowDismissed(false);
        lastSentForPlanRef.current = trimmed;
        setLastRouteLane(null);
        setLastRouteConfidence(null);
        setLastOutboundUserSnapshot(trimmed);
        setLastWebSearchHeader(null);
        setLastWebSourcesPayload(null);
        setLastSearchStatus("none");
        setLastSearchProvider(null);
        setLastSearchQuery(null);
        setLastSearchElapsedMs(null);
        setLastSearchKind("none");
        setLastSearchSkipReason(null);
        setLastHeaderSourceCount(null);
        lastSearchHdrRef.current = null;
        lastSourcesPayloadRef.current = null;
        if (outboundScrollRefs) {
          /* Parent-owned scroll refs - same mutation as pre-refactor SpiritChat */
          outboundScrollRefs.forceScrollOnNextMessageRef.current = true;
          outboundScrollRefs.shouldStickToBottomRef.current = true;
        }
        const ttsSnap = ttsRef.current;
        if (
          ttsSnap &&
          shouldStopTtsOnOutboundSubmit({
            autoSpeakAssistant: ttsSnap.state.autoSpeakAssistant,
            isPlaying: ttsSnap.state.isPlaying,
            queueLength: ttsSnap.state.queueLength,
          })
        ) {
          if (process.env.NODE_ENV === "development") {
            console.info("[tts] stopping old audio before submit");
          }
          ttsSnap.stop();
        }

        if (persistent.enabled) {
          const userMsgId = generateChatRecordId();
          const routed = await persistent.persistUserOutboundForSend(trimmed, userMsgId);
          if (!routed) {
            submitGuardRef.current = false;
            return;
          }
          assistantOutcomeThreadRef.current = routed.threadId;
          await sendMessage({
            role: "user",
            id: userMsgId,
            parts: [{ type: "text", text: trimmed }],
          });
          if (savedChatShell) {
            pushActivity({ kind: "message_submitted", label: "Sent message" });
          }
        } else {
          await sendMessage({ text: trimmed });
        }
      } catch (e) {
        assistantOutcomeThreadRef.current = null;
        console.error("[spirit-chat] send pipeline:", e);
        submitGuardRef.current = false;
      } finally {
        setComposerInput("");
      }
    },
    [
      sendMessage,
      persistent,
      savedChatShell,
      pushActivity,
      deepThinkEnabled,
      webSearchOptOut,
      teacherWebSearchEnabled,
      activeModelProfileId,
      ttsRef,
      outboundScrollRefs,
    ],
  );

  const submitMessage = useCallback(() => {
    const t2 = composerInput.trim();
    if (!t2 || isBusy || submitGuardRef.current) return;

    if (persistence && !persistent.canSendOutbound) {
      if (process.env.NODE_ENV === "development") {
        console.warn("[spirit-chat] submit blocked: canSendOutbound false", {
          threadsLoading: persistent.threadsLoading,
          activeThreadId: persistent.activeThreadId,
          draftLaneActive: persistent.draftLaneActive,
        });
      }
      return;
    }

    submitGuardRef.current = true;
    setAssistantSourceProof(null);

    const routePre = decideSpiritRoute({
      modelProfileId: activeModelProfileId,
      lastUserText: t2,
      deepThinkEnabled,
      webSearchOptOut,
      teacherWebSearchEnabled,
      webSearchGloballyEnabled: true,
      modelHint: "",
    });

    if (
      persistent.enabled &&
      activeModelProfileId === "researcher" &&
      routePre.lane === "research-plan"
    ) {
      lastSentForPlanRef.current = t2;
      setResearchPlan(draftResearchPlanFromPrompt(t2));
      setResearchPlanOpen(true);
      submitGuardRef.current = false;
      setComposerInput("");
      return;
    }

    void runSpiritOutbound(t2);
  }, [
    composerInput,
    isBusy,
    runSpiritOutbound,
    persistence,
    persistent,
    deepThinkEnabled,
    webSearchOptOut,
    teacherWebSearchEnabled,
    activeModelProfileId,
  ]);

  const onSubmit = useCallback(
    (e: FormEvent) => {
      e.preventDefault();
      submitMessage();
    },
    [submitMessage],
  );

  const onKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.nativeEvent.isComposing) return;
      if (e.key !== "Enter" || e.shiftKey) return;
      e.preventDefault();
      submitMessage();
    },
    [submitMessage],
  );

  const displayMessages = useMemo(
    () => dedupeUIMessagesById(messages),
    [messages],
  );

  const lastAssistantId = useMemo(() => {
    for (let i = displayMessages.length - 1; i >= 0; i--) {
      const m = displayMessages[i]!;
      if (m.role === "assistant") return m.id;
    }
    return null;
  }, [displayMessages]);

  const {
    deletePersistedMessage,
    updatePersistedMessageText,
  } = persistent;

  const handleMessageDelete = useCallback(
    (id: string) => {
      if (!window.confirm("Delete this message?")) return;
      setMessages((prev) => dedupeUIMessagesById(deleteUIMessageById(prev, id)));
      if (persistenceEnabled) void deletePersistedMessage(id);
    },
    [persistenceEnabled, deletePersistedMessage, setMessages],
  );

  const handleMessageEditSave = useCallback(
    (id: string, text: string) => {
      setMessages((prev) => dedupeUIMessagesById(updateUIMessageText(prev, id, text)));
      if (persistenceEnabled) void updatePersistedMessageText(id, text);
    },
    [persistenceEnabled, updatePersistedMessageText, setMessages],
  );

  const handleRegenerateAssistant = useCallback(
    async (assistantId: string) => {
      if (assistantId !== lastAssistantId) {
        console.info(
          "[spirit-chat] regenerate only supported for the latest assistant reply",
        );
        return;
      }
      if (persistenceEnabled) {
        skipDexieHydrateRef.current = true;
        try {
          await deletePersistedMessage(assistantId);
          await regenerate({ messageId: assistantId });
        } catch (e) {
          console.error("[spirit-chat] regenerate failed:", e);
        } finally {
          skipDexieHydrateRef.current = false;
        }
        return;
      }
      try {
        await regenerate({ messageId: assistantId });
      } catch (e) {
        console.error("[spirit-chat] regenerate failed:", e);
      }
    },
    [persistenceEnabled, deletePersistedMessage, lastAssistantId, regenerate],
  );

  const handleResearchPlanClose = useCallback(() => {
    setResearchPlanOpen(false);
    setResearchPlan(null);
    lastSentForPlanRef.current = "";
  }, []);

  const handleResearchPlanStart = useCallback(
    (plan: ResearchPlan) => {
      pendingResearchPlanSummaryRef.current = researchPlanToSummary(plan);
      setResearchPlanOpen(false);
      setResearchPlan(null);
      submitGuardRef.current = true;
      setAssistantSourceProof(null);
      void runSpiritOutbound(lastSentForPlanRef.current.trim());
      pushActivity({
        kind: "workflow_step",
        label: "Research plan approved - running /api/spirit",
      });
    },
    [pushActivity, runSpiritOutbound],
  );

  return useMemo(
    (): SpiritChatTransport => ({
      messages,
      setMessages,
      sendMessage,
      regenerate,
      stop,
      status,
      error,
      input: composerInput,
      setInput: setComposerInput,
      isBusy,
      submitMessage,
      onSubmit,
      onKeyDown,
      runSpiritOutbound,

      assistantSourceProof,
      setAssistantSourceProof,

      handleMessageDelete,
      handleMessageEditSave,
      handleRegenerateAssistant,
      lastAssistantId,

      deepThinkEnabled,
      setDeepThinkEnabled,
      webSearchPreference,
      setWebSearchPreference,
      teacherWebSearchEnabled,
      setTeacherWebSearchEnabled,
      webSearchOptOut,

      lastOutboundUserSnapshot,
      lastWebSearchHeader,
      lastSearchStatus,
      lastSearchProvider,
      lastSearchQuery,
      lastSearchElapsedMs,
      lastSearchKind,
      lastSearchSkipReason,
      lastHeaderSourceCount,
      lastWebSourcesPayload,
      lastRouteLane,
      lastRouteConfidence,
      workflowDismissed,
      setWorkflowDismissed,
      workflowStepIdx,
      setWorkflowStepIdx,
      researchPlanOpen,
      setResearchPlanOpen,
      researchPlan,
      setResearchPlan,
      pendingResearchPlanSummaryRef,
      lastSentForPlanRef,
      handleResearchPlanClose,
      handleResearchPlanStart,

      hydrateDraftMarkerRef,
      hydrateSigRef,
      hydrateThreadFocusRef,
      skipDexieHydrateRef,

      onSidebarNewChatResetHydration,
      onSidebarSelectResetHydration,

      assistantOutcomeThreadRef,
      spiritOutboundSeqRef,
    }),
    [
      messages,
      setMessages,
      sendMessage,
      regenerate,
      stop,
      status,
      error,
      composerInput,
      isBusy,
      submitMessage,
      onSubmit,
      onKeyDown,
      runSpiritOutbound,
      assistantSourceProof,
      handleMessageDelete,
      handleMessageEditSave,
      handleRegenerateAssistant,
      lastAssistantId,
      deepThinkEnabled,
      webSearchPreference,
      teacherWebSearchEnabled,
      webSearchOptOut,
      lastOutboundUserSnapshot,
      lastWebSearchHeader,
      lastSearchStatus,
      lastSearchProvider,
      lastSearchQuery,
      lastSearchElapsedMs,
      lastSearchKind,
      lastSearchSkipReason,
      lastHeaderSourceCount,
      lastWebSourcesPayload,
      lastRouteLane,
      lastRouteConfidence,
      workflowDismissed,
      workflowStepIdx,
      setWorkflowStepIdx,
      researchPlanOpen,
      researchPlan,
      handleResearchPlanClose,
      handleResearchPlanStart,
      onSidebarNewChatResetHydration,
      onSidebarSelectResetHydration,
    ],
  );
}import "server-only";

import { createOpenAI } from "@ai-sdk/openai";

import { getSpiritChatModelId } from "@/lib/server/model-routing";

// ── Ollama OpenAI-compat client - server-only; env-derived base URL ───────────

export function getOllamaOpenAIBaseURL(): string {
  const explicit = process.env.OLLAMA_OPENAI_BASE_URL?.trim();
  if (explicit) return explicit.replace(/\/$/, "");

  const raw = (
    process.env.OLLAMA_BASE_URL?.trim() || "http://localhost:11434"
  ).replace(/\/api\/?$/i, "");

  return `${raw.replace(/\/$/, "")}/v1`;
}

/** Primary `/chat` lane model tag (OLLAMA_MODEL). */
export function getSpiritModelId(): string {
  return getSpiritChatModelId();
}

export const ollamaOpenAI = createOpenAI({
  baseURL: getOllamaOpenAIBaseURL(),
  apiKey: process.env.OLLAMA_API_KEY || "ollama",
});

const HEALTH_PROBE_TIMEOUT_MS = 2500;
const TOOL_SCHEMA_PROBE_TIMEOUT_MS = 4000;

/** GET /v1/models - same auth shape as createOpenAI; no prompts logged. */
export type OllamaProbeResult =
  | { ok: true; status: "online" }
  | { ok: false; status: "offline"; error: string };

export async function probeOllamaOpenAICompat(): Promise<OllamaProbeResult> {
  const url = `${getOllamaOpenAIBaseURL()}/models`;
  const apiKey = process.env.OLLAMA_API_KEY || "ollama";
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), HEALTH_PROBE_TIMEOUT_MS);
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      cache: "no-store",
      headers: {
        Authorization: `Bearer ${apiKey}`,
      },
    });
    if (!res.ok) {
      return {
        ok: false,
        status: "offline",
        error: `Health check failed: ${res.status}`,
      };
    }
    return { ok: true, status: "online" };
  } catch {
    return {
      ok: false,
      status: "offline",
      error: "Ollama is unreachable",
    };
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * POST /v1/chat/completions with a minimal tools payload to see if this model
 * accepts OpenAI-style tools. Hermes4 and similar return 400 "does not support tools".
 * Cached per process in tool-registry; callers should not spam this.
 */
export async function probeOllamaChatCompletionsAcceptsToolSchema(modelId: string): Promise<boolean> {
  const url = `${getOllamaOpenAIBaseURL()}/chat/completions`;
  const apiKey = process.env.OLLAMA_API_KEY || "ollama";
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), TOOL_SCHEMA_PROBE_TIMEOUT_MS);
  try {
    const res = await fetch(url, {
      method: "POST",
      cache: "no-store",
      signal: controller.signal,
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: modelId,
        stream: false,
        max_tokens: 1,
        messages: [{ role: "user", content: "." }],
        tools: [
          {
            type: "function",
            function: {
              name: "__spirit_tool_schema_probe",
              description: "Spirit internal probe; not for production use.",
              parameters: { type: "object", properties: {} },
            },
          },
        ],
        tool_choice: "auto",
      }),
    });

    const raw = await res.text();
    const lower = raw.toLowerCase();
    if (!res.ok) {
      if (res.status === 400 && lower.includes("does not support tools")) {
        return false;
      }
      return true;
    }
    if (lower.includes("does not support tools")) {
      return false;
    }
    return true;
  } catch {
    return true;
  } finally {
    clearTimeout(timeout);
  }
}import "server-only";

import { getOracleModelId, getSpiritChatModelId } from "@/lib/server/model-routing";
import { getSttDiagnostics } from "@/lib/server/stt-provider";

// ── Spirit diagnostics - env-derived labels for health JSON (no secrets) ────────
// > Context/output/TTS copy matches runtime in route.ts + Piper / ElevenLabs wiring

/** Route `streamText` cap; override with SPIRIT_MAX_OUTPUT_TOKENS. */
export function getSpiritMaxOutputTokens(): number {
  const raw = process.env.SPIRIT_MAX_OUTPUT_TOKENS?.trim();
  if (!raw) return 1024;
  const n = Number.parseInt(raw, 10);
  if (!Number.isFinite(n) || n < 1) return 1024;
  return n;
}

/** Oracle lane cap; ORACLE_MAX_OUTPUT_TOKENS unset → same as chat cap. */
export function getOracleMaxOutputTokens(): number {
  const raw = process.env.ORACLE_MAX_OUTPUT_TOKENS?.trim();
  if (!raw) return getSpiritMaxOutputTokens();
  const n = Number.parseInt(raw, 10);
  if (!Number.isFinite(n) || n < 1) return getSpiritMaxOutputTokens();
  return n;
}

function getMaxOutputTokensMeta(): { value: number; source: string } {
  const raw = process.env.SPIRIT_MAX_OUTPUT_TOKENS?.trim();
  if (!raw) return { value: 1024, source: "default (1024)" };
  const n = Number.parseInt(raw, 10);
  if (!Number.isFinite(n) || n < 1) return { value: 1024, source: "default (1024)" };
  return { value: n, source: "SPIRIT_MAX_OUTPUT_TOKENS" };
}

function getOracleMaxOutputTokensMeta(): { value: number; source: string } {
  const raw = process.env.ORACLE_MAX_OUTPUT_TOKENS?.trim();
  if (!raw) {
    return {
      value: getSpiritMaxOutputTokens(),
      source: "inherits SPIRIT_MAX_OUTPUT_TOKENS (ORACLE_MAX_OUTPUT_TOKENS unset)",
    };
  }
  const n = Number.parseInt(raw, 10);
  if (!Number.isFinite(n) || n < 1) {
    return {
      value: getSpiritMaxOutputTokens(),
      source: "invalid ORACLE_MAX_OUTPUT_TOKENS → chat cap",
    };
  }
  return { value: n, source: "ORACLE_MAX_OUTPUT_TOKENS" };
}

/**
 * Host-side context window when set on Ollama; never invent "~8k" without env.
 */
export function getSpiritContextWindow(): { label: string; source: string } {
  const raw = process.env.OLLAMA_NUM_CTX?.trim();
  if (!raw) {
    return { label: "Host default", source: "OLLAMA_NUM_CTX unset" };
  }
  const n = Number.parseInt(raw, 10);
  if (!Number.isFinite(n) || n < 1) {
    return { label: "Host default", source: "OLLAMA_NUM_CTX unset" };
  }
  return { label: String(n), source: "OLLAMA_NUM_CTX" };
}

export function getSpiritTtsDiagnostics(): {
  provider: string;
  voice: string;
  source: string;
} {
  const prov = process.env.TTS_PROVIDER?.trim().toLowerCase() || "piper";
  if (prov === "elevenlabs") {
    const hasKey = Boolean(process.env.ELEVENLABS_API_KEY?.trim());
    const voice =
      process.env.ELEVENLABS_VOICE_ID?.trim() || "fgDJOgmENIR82PueQrVs";
    return {
      provider: hasKey ? "ElevenLabs" : "ElevenLabs (no API key)",
      voice,
      source: hasKey
        ? "TTS_PROVIDER=elevenlabs"
        : "TTS_PROVIDER=elevenlabs but ELEVENLABS_API_KEY unset",
    };
  }
  const url = process.env.PIPER_TTS_URL?.trim();
  const voice = process.env.PIPER_TTS_VOICE?.trim() || "fable";
  if (url) {
    return { provider: "Piper", voice, source: "PIPER_TTS_URL" };
  }
  return { provider: "Piper (no URL)", voice, source: "PIPER_TTS_URL unset" };
}

export type SpiritDiagnosticsPayload = {
  engine: string;
  maxOutputTokens: number;
  maxOutputTokensSource: string;
  oracleMaxOutputTokens: number;
  oracleMaxOutputTokensSource: string;
  chatModel: string;
  oracleLaneModel: string;
  context: { label: string; source: string };
  tts: { provider: string; voice: string; source: string };
  stt: { provider: string; url: string; source: string; transcribePath: string };
};

/** Single merge-friendly blob for /api/spirit/health JSON. */
export function getSpiritDiagnostics(): SpiritDiagnosticsPayload {
  const ctx = getSpiritContextWindow();
  const tts = getSpiritTtsDiagnostics();
  const cap = getMaxOutputTokensMeta();
  const oracleCap = getOracleMaxOutputTokensMeta();
  const stt = getSttDiagnostics();
  return {
    engine: "Ollama",
    maxOutputTokens: cap.value,
    maxOutputTokensSource: cap.source,
    oracleMaxOutputTokens: oracleCap.value,
    oracleMaxOutputTokensSource: oracleCap.source,
    chatModel: getSpiritChatModelId(),
    oracleLaneModel: getOracleModelId(),
    context: ctx,
    tts: {
      provider: tts.provider,
      voice: tts.voice,
      source: tts.source,
    },
    stt: {
      provider: stt.provider,
      url: stt.url,
      source: stt.source,
      transcribePath: stt.transcribePath,
    },
  };
}// ── response-budget - match verbosity to prompt + mode (Prompt 10B + 10C) ─────────

import type { ModelProfile, ModelProfileId } from "@/lib/spirit/model-profile.types";
import type { SpiritRuntimeSurface } from "@/lib/spirit/spirit-runtime-surface";

const CASUAL_MAX_CHARS = 140;
const RESEARCH_HINT =
  /\b(research|report|sources?|citations?|peer[- ]review|study|meta[- ]analysis|literature|systematic|verify|current events|news|today|latest|202[0-9])\b/i;
const TEACH_HINT =
  /\b(teach|lesson|explain|tutorial|quiz|exam|homework|course|learn|understand|step by step)\b/i;
/** Teacher web aids - educational / clinical phrasing (Prompt 10C-D, still client+server heuristic). */
const TEACHER_WEB_STUDY_HINT =
  /\b(explain|teach|study|quiz|exam|concept|what is|define|example|aba|psychology|counseling|behavior|reinforcement|punishment|autism|sensory|spectrum|neurodevelopmental|over-?selectivity|meltdown|shutdown|learning|historical connection|history of|article|handout|resource|source|homework|course|tutorial|pedagog|curriculum|IEP|intervention|therap|clinical|disorder|syndrome)\b/i;
const CODE_HINT =
  /\b(code|repo|cursor|terminal|bug|dev|developer|typescript|javascript|python|ollama|build|feature|commit|pr|debug|stack trace|error log|app|project|implementation)\b/i;

export function isLikelyCasualShortMessage(text: string): boolean {
  const t = text.trim();
  if (!t) return true;
  if (t.length > CASUAL_MAX_CHARS) return false;
  if (RESEARCH_HINT.test(t) || TEACH_HINT.test(t) || CODE_HINT.test(t)) return false;
  return true;
}

export function wantsResearchDepth(text: string): boolean {
  return RESEARCH_HINT.test(text) || (text.trim().length > 400 && /\bwhy\b|\bhow\b/i.test(text));
}

export function wantsTeachingDepth(text: string): boolean {
  return TEACH_HINT.test(text);
}

export function wantsTeacherWebStudyAids(text: string): boolean {
  return TEACHER_WEB_STUDY_HINT.test(text);
}

export function mentionsCodeOrBuild(text: string): boolean {
  return CODE_HINT.test(text);
}

/**
 * Runtime instruction block appended after mode system prompt.
 */
export function buildResponseBudgetInstruction(
  profile: ModelProfile,
  userMessage: string,
  opts?: {
    deepThinkEnabled?: boolean;
    digestHasVerifiedUrls?: boolean;
    runtimeSurface?: SpiritRuntimeSurface;
  },
): string {
  const casual = isLikelyCasualShortMessage(userMessage);
  const deep = Boolean(opts?.deepThinkEnabled);
  const budget = profile.responseBudget ?? "medium";
  const maxS = profile.casualMaxSentences ?? 4;
  const surface = opts?.runtimeSurface ?? "chat";

  const lines: string[] = [
    "## Response budget (mandatory)",
    `- Mode budget: ${budget}.`,
    `- Match answer depth to the user's message depth.`,
    `- Do not produce long bullet lists unless the user explicitly asks for a list, report, or breakdown.`,
  ];

  if (profile.id === "normal-peer") {
    lines.push(
      `- Peer: do not slide into repo/dev/productivity framing unless the user clearly asks technical or coding questions.`,
      `- For casual small talk: ${maxS} short sentences max (roughly 1–4). No customer-service phrasing, no unsolicited life coaching.`,
    );
    if (casual && !mentionsCodeOrBuild(userMessage)) {
      lines.push(`- This user message reads casual/non-technical: stay conversational - no IDE/repo defaults unless they steer there.`);
    }
  }

  if (profile.id === "sassy-chaotic") {
    lines.push(
      `- Sassy: **1–3 short sentences** by default - witty, sharp, lightly disrespectful in a funny way; answer first, then stop.`,
      `- No essays, no bullet spam, no fake profundity, no exposed instructions - unless they explicitly asked for depth.`,
    );
  }

  if (profile.id === "brutal") {
    lines.push(
      `- Brutal: short, sharp, funny-mean on behavior/work only. Punchy callout → why it matters → what to do next.`,
      `- No clinical intake tone, no multi-section "assessment" unless they asked for a formal review.`,
      `- No long lecture unless they explicitly ask for one.`,
    );
  }

  if (profile.id === "teacher") {
    const digestUrls = Boolean(opts?.digestHasVerifiedUrls);
    lines.push(`- Teacher: concise first; one example max unless they want a full lesson.`);
    if (digestUrls) {
      lines.push(
        `- **Study aids** (web digest has verified URLs): put **markdown link bullets first** - one \`- [short label](exact-url)\` per digest URL, using only URLs from the digest. After those links, at most **one** optional line: either a mnemonic, a common trap, or a flashcard - not a wall of study-trivia that hides the links.`,
        `- If the user asked for video or peer-reviewed material, prioritize digest links that match (e.g. .edu, journals, YouTube only when digest already has a youtube/youtu.be URL).`,
      );
    } else {
      lines.push(
        `- Include a small **Study aids** footer (mnemonic / trap / flashcard) unless the user opted out.`,
      );
    }
    lines.push(
      `- Offer a quick comprehension check only when it fits (e.g. "Want a one-question check?").`,
    );
    if (!wantsTeachingDepth(userMessage)) {
      lines.push(`- User did not ask for a full lesson: keep it tight - short answer, optional single example.`);
    } else {
      lines.push(`- User asked for teaching depth: you may expand with steps and a tiny quiz offer.`);
    }
  }

  if (profile.id === "researcher") {
    const digestUrls = Boolean(opts?.digestHasVerifiedUrls);
    lines.push(
      `- Researcher: structured mini-report when appropriate (summary bullets, findings, limitations).`,
      `- When web context exists, write like an internal memo: tight headings, minimal hedging, no filler "delve" language.`,
      `- Citations: only cite URLs or titles that were supplied by the system "Web research context" block - never invent sources.`,
      `- End with a Sources list when URLs exist; state "Search used: yes/no" honestly.`,
    );
    if (digestUrls) {
      lines.push(
        `- **Verified URLs are attached**: surface them as real markdown - at least one \`- [short label](exact-url)\` per digest URL under **## Sources**, plus \`[n](url)\` inline where it helps. Do not hand-wave as "unverified background" while those URLs are in the digest.`,
      );
    }
    if (!wantsResearchDepth(userMessage) && !deep && !digestUrls) {
      lines.push(`- This prompt does not obviously require live web data: answer from general knowledge and say search was not used unless context says otherwise.`);
    }
  }

  if (deep) {
    lines.push(
      `- Deep Think is ON: slow down, double-check conclusions, prefer verification - but do NOT ramble; better judgment beats length.`,
    );
    if (profile.id === "sassy-chaotic" || profile.id === "brutal") {
      lines.push(
        `- Deep Think does **not** override ${profile.id === "sassy-chaotic" ? "Sassy" : "Brutal"} brevity: still short unless they explicitly asked for depth.`,
      );
    }
  }

  if (surface === "oracle") {
    lines.push(
      "## Oracle voice response budget (mandatory on this surface)",
      `- Voice-first: default to **1–5 sentences** unless the user explicitly asks for depth or detail.`,
      `- Prefer short spoken answers (~**90 words** or fewer for Peer/Sassy casual turns).`,
      `- Brutal (Oracle): stay sharp and direct - not a long teardown unless asked.`,
      `- Teacher (Oracle): explain clearly; do **not** dump a whole lesson unless the user asks for depth.`,
      `- Researcher (Oracle): if verified web sources are **not** attached for this turn, say honestly what would need checking - **never invent citations or URLs**.`,
    );
  }

  return lines.join("\n");
}

/**
 * Hard output token ceiling per turn - casual prompts stay tiny (Prompt 10C-C).
 * Detailed asks (research / code / explicit depth) keep profile headroom.
 */
export function resolveSpiritMaxOutputTokens(opts: {
  profileId: ModelProfileId;
  profileMax: number;
  lastUserMessage: string;
  deepThinkEnabled: boolean;
  /** Voice-only `/oracle` lane - tighter spoken ceilings; `/chat` omits or passes `"chat"`. */
  runtimeSurface?: SpiritRuntimeSurface;
  /** Researcher: digest URL count from web prefetch (server). */
  webVerifiedUrlCount?: number;
}): number {
  const raw = Number.isFinite(opts.profileMax) && opts.profileMax > 0 ? opts.profileMax : 1536;
  const last = opts.lastUserMessage.trim();
  const casual = isLikelyCasualShortMessage(last);
  const deep = Boolean(opts.deepThinkEnabled);
  const codey = mentionsCodeOrBuild(last);
  const researchWants = wantsResearchDepth(last);
  const teachWants = wantsTeachingDepth(last);

  const allowLong =
    researchWants ||
    teachWants ||
    codey ||
    last.length > CASUAL_MAX_CHARS ||
    (opts.profileId === "researcher" && !casual);

  const hasVerifiedResearchUrls =
    opts.profileId === "researcher" &&
    typeof opts.webVerifiedUrlCount === "number" &&
    opts.webVerifiedUrlCount > 0;

  const capSassy = () => {
    if (allowLong) return Math.min(raw, 1024);
    const base = 200;
    return deep ? Math.min(base + 100, 380) : base;
  };
  const capBrutal = () => {
    if (allowLong) return Math.min(raw, 1200);
    const base = 280;
    return deep ? Math.min(base + 140, 480) : base;
  };
  const capPeer = () => {
    if (allowLong) return Math.min(raw, 1536);
    const base = 280;
    return deep ? Math.min(base + 420, 4096) : base;
  };
  const capTeacher = () => {
    if (teachWants || last.length > CASUAL_MAX_CHARS) return Math.min(raw, 2400);
    const base = 640;
    return deep ? Math.min(base + 400, 3200) : base;
  };
  const capResearcher = () => Math.min(raw, 3072);

  let base: number;
  switch (opts.profileId) {
    case "sassy-chaotic":
      base = capSassy();
      break;
    case "brutal":
      base = capBrutal();
      break;
    case "normal-peer":
      base = capPeer();
      break;
    case "teacher":
      base = capTeacher();
      break;
    case "researcher": {
      let cap = capResearcher();
      if (deep) cap = Math.min(cap + 256, 4096);
      base = cap;
      break;
    }
    default:
      base = capPeer();
  }

  if (opts.runtimeSurface !== "oracle") return base;

  /** Spoken voice lane - never shrink `/chat`; only applies when `runtimeSurface === "oracle"`. */
  switch (opts.profileId) {
    case "normal-peer":
      return allowLong ? Math.min(base, 1536) : Math.min(base, 260);
    case "sassy-chaotic":
      return allowLong ? Math.min(base, 1024) : Math.min(base, 220);
    case "brutal":
      return allowLong ? Math.min(base, 1200) : Math.min(base, 320);
    case "teacher":
      return teachWants || last.length > CASUAL_MAX_CHARS
        ? Math.min(base, 2400)
        : Math.min(base, 560);
    case "researcher": {
      if (hasVerifiedResearchUrls) return Math.min(base, 3072);
      return Math.min(base, deep ? 2200 : 1600);
    }
    default:
      return Math.min(base, 260);
  }
}// ── spirit-runtime-surface - shared literal union (client + server; no server-only) ─
// > `model-routing.ts` stays server-only; UI + JSON parser import from here only.

export type SpiritRuntimeSurface = "chat" | "oracle";

/** Default POST body surface - `/oracle` overrides with `"oracle"`. */
export const DEFAULT_SPIRIT_RUNTIME_SURFACE: SpiritRuntimeSurface = "chat";

/**
 * Voice-layer context for `/oracle`. Mode text stays first (personality); this overrides
 * workspace/coding-default smell without replacing Peer/Teacher/etc. tone.
 */
export function buildRuntimeSurfaceInstruction(surface: SpiritRuntimeSurface): string {
  if (surface !== "oracle") return "";

  return `## Oracle Voice surface (live conversation context)
You are currently running inside Oracle Voice mode, a live spoken conversation surface.
This is not the coding workspace and not a support chat.
Do not default to coding, repos, debugging, terminal work, projects, or software advice unless the user explicitly brings those up.

Normal human social advice is in scope: dating, texting, flirting, friendships, relationship dynamics, awkward conversations, confidence, and reading social signals. Be warm, direct, practical, lightly playful when it fits - like a grounded friend with boundaries, not a clinic intake unless they ask for clinical framing. Do not over-professionalize everyday dating or social questions; do not dodge with generic AI disclaimers ("as an AI…", "I cannot help with relationships"). Mystical-vague only if they explicitly want that vibe.

Consent, boundaries, respect, and emotional safety stay central. Never encourage manipulation, pressure, stalking, harassment, ignoring rejection, or coercive messages. If they want jealousy games, "win someone over" after a no, or control tactics, redirect to honesty and self-respect. If it sounds like abuse, self-harm, threats, or serious legal/medical risk, slow down, avoid escalation, prioritize safer support.

Treat the user's speech like a real-time conversation.
Keep most replies short enough to speak aloud naturally.
If the user is vague, respond naturally or ask one simple follow-up.
Avoid customer-service phrases like "How may I assist you?" or "I am here to help with coding questions."
Do not say you are a chatbot unless the user directly asks what you are.
Preserve the selected mode's personality, but make it voice-first and conversational.`.trim();
}// ── system-state - dynamic [SYSTEM STATE] block for the SpiritOS system prompt ─
// > resolveSpiritSystemState reads process.env and is server-only in practice.
// > buildSystemStateBlock is a pure string builder - client + server safe.

import type { SpiritRuntimeSurface } from "@/lib/spirit/spirit-runtime-surface";

export type SpiritSystemCapability =
  | "chat"
  | "tts"
  | "stt"
  | "web_search_when_enabled"
  | "workspace_file_read"
  | "workspace_file_list"
  | "windows_folder_list"
  | "log_tail_read"
  | "system_status"
  | "file_editing"
  | "terminal_execution"
  | "email_access"
  | "calendar_access";

export type SpiritSystemStateInput = {
  currentTimeIso: string;
  runtimeSurface: SpiritRuntimeSurface;
  modelHint: string | null;
  modelProfileId: string | null;
  modelProfileLabel: string | null;
  hardwareProfile: string;
  projectPathConfigured: boolean;
  availableCapabilities: SpiritSystemCapability[];
  unavailableCapabilities: SpiritSystemCapability[];
  /** When env enables read-only tools but they are not on the wire for this model */
  localToolsAttachmentNote?: string | null;
  /** When env enables file edit but tools are not attached */
  fileEditingAttachmentNote?: string | null;
  /** When env enables dev commands but run_dev_command is not on the wire for this model */
  devCommandAttachmentNote?: string | null;
};

export type SpiritSystemStateResolveInput = {
  currentTimeIso?: string;
  runtimeSurface: SpiritRuntimeSurface;
  modelHint?: string | null;
  modelProfileId?: string | null;
  modelProfileLabel?: string | null;
  /** Reflects whether read-only tools were actually passed to streamText for this request */
  localToolsAttached?: boolean;
  /** True only when propose_file_edit / apply_confirmed_file_edit are on the wire */
  fileEditToolsAttached?: boolean;
  /** True only when run_dev_command was passed to streamText for this request */
  devCommandToolsAttached?: boolean;
};

const BASELINE_AVAILABLE: SpiritSystemCapability[] = [
  "chat",
  "tts",
  "stt",
  "web_search_when_enabled",
];

const LOCAL_TOOL_CAPS: SpiritSystemCapability[] = [
  "workspace_file_read",
  "workspace_file_list",
  "log_tail_read",
  "system_status",
];

export function resolveSpiritSystemState(
  input: SpiritSystemStateResolveInput,
): SpiritSystemStateInput {
  const available: SpiritSystemCapability[] = [...BASELINE_AVAILABLE];
  const unavailable: SpiritSystemCapability[] = [];

  const localToolsCfg = process.env.SPIRIT_ENABLE_LOCAL_TOOLS === "true";
  const ollamaToolsTransport = process.env.SPIRIT_OLLAMA_SUPPORTS_TOOLS === "true";
  const envSaysReadOnlyTools = localToolsCfg && ollamaToolsTransport;

  let localToolsEffective = envSaysReadOnlyTools;
  if (input.localToolsAttached === false) {
    localToolsEffective = false;
  } else if (input.localToolsAttached === true) {
    localToolsEffective = true;
  }

  const localToolsAttachmentNote =
    localToolsCfg &&
    ollamaToolsTransport &&
    !localToolsEffective
      ? "Read-only tools are configured in the environment but are not attached for this model (tool-call probe failed or transport rejected)."
      : null;
  const fileEditEnv = process.env.SPIRIT_ENABLE_FILE_EDIT_TOOLS === "true";
  const devCommandEnv = process.env.SPIRIT_ENABLE_DEV_COMMAND_TOOLS === "true";
  const emailTools = process.env.SPIRIT_ENABLE_EMAIL_TOOLS === "true";
  const calendarTools = process.env.SPIRIT_ENABLE_CALENDAR_TOOLS === "true";

  let fileEditingEffective = false;
  if (fileEditEnv) {
    if (input.fileEditToolsAttached === true) {
      fileEditingEffective = true;
    } else if (input.fileEditToolsAttached === false) {
      fileEditingEffective = false;
    } else {
      fileEditingEffective = false;
    }
  }

  const fileEditingAttachmentNote =
    fileEditEnv && !fileEditingEffective
      ? "File editing is configured in the environment but edit tools are not attached for this model. Guarded edits require propose_file_edit then apply_confirmed_file_edit after explicit user confirmation."
      : null;

  let terminalExecutionEffective = false;
  if (devCommandEnv) {
    terminalExecutionEffective = input.devCommandToolsAttached === true;
  }

  const devCommandAttachmentNote =
    devCommandEnv && !terminalExecutionEffective
      ? "Dev command tools are configured but not attached for this model/session."
      : null;

  if (localToolsEffective) {
    available.push(...LOCAL_TOOL_CAPS);
  } else {
    unavailable.push(...LOCAL_TOOL_CAPS);
  }

  if (process.env.SPIRIT_WINDOWS_FS_ENABLED === "true") {
    available.push("windows_folder_list");
  } else {
    unavailable.push("windows_folder_list");
  }

  if (fileEditingEffective) {
    available.push("file_editing");
  } else {
    unavailable.push("file_editing");
  }

  if (terminalExecutionEffective) {
    available.push("terminal_execution");
  } else {
    unavailable.push("terminal_execution");
  }

  if (emailTools) {
    available.push("email_access");
  } else {
    unavailable.push("email_access");
  }

  if (calendarTools) {
    available.push("calendar_access");
  } else {
    unavailable.push("calendar_access");
  }

  return {
    currentTimeIso: input.currentTimeIso ?? new Date().toISOString(),
    runtimeSurface: input.runtimeSurface,
    modelHint: input.modelHint ?? null,
    modelProfileId: input.modelProfileId ?? null,
    modelProfileLabel: input.modelProfileLabel ?? null,
    hardwareProfile: process.env.SPIRIT_HARDWARE_PROFILE || "unknown",
    projectPathConfigured: Boolean(process.env.SPIRIT_PROJECT_PATH),
    availableCapabilities: available,
    unavailableCapabilities: unavailable,
    localToolsAttachmentNote,
    fileEditingAttachmentNote,
    devCommandAttachmentNote,
  };
}

export function buildSystemStateBlock(input: SpiritSystemStateInput): string {
  const lines: string[] = ["[SYSTEM STATE]"];

  lines.push(`Time: ${input.currentTimeIso}`);
  lines.push(`Surface: ${input.runtimeSurface}`);

  if (input.modelProfileId) {
    const profilePart = input.modelProfileLabel
      ? `${input.modelProfileId} (${input.modelProfileLabel})`
      : input.modelProfileId;
    lines.push(`Active profile: ${profilePart}`);
  }

  if (input.modelHint) {
    lines.push(`Model: ${input.modelHint}`);
  }

  lines.push(`Hardware profile: ${input.hardwareProfile}`);
  lines.push(`Project path configured: ${input.projectPathConfigured ? "yes" : "no"}`);
  lines.push(`Available capabilities: ${input.availableCapabilities.join(", ")}`);
  lines.push(`Unavailable capabilities: ${input.unavailableCapabilities.join(", ")}`);
  if (input.localToolsAttachmentNote) {
    lines.push(input.localToolsAttachmentNote);
  }
  if (input.fileEditingAttachmentNote) {
    lines.push(input.fileEditingAttachmentNote);
  }
  if (input.devCommandAttachmentNote) {
    lines.push(input.devCommandAttachmentNote);
  }
  lines.push("");
  lines.push(
    "Do not claim you used a tool, read a file, edited a file, ran a command, checked email, or accessed calendar unless that capability is listed as available and an actual tool result was returned in this conversation.",
  );
  lines.push(
    "If a capability is unavailable, say so clearly instead of pretending it happened.",
  );
  lines.push(
    "Windows folder listing is never arbitrary full-disk browsing; it is available only through the SpiritDesktop filesystem bridge and configured allowlist.",
  );
  lines.push(
    "If the user asks you to use an unavailable capability, explain what is unavailable and offer a manual alternative or explain what would be needed to enable it.",
  );

  return lines.join("\n");
}// Spirit palette registry. Theme UI reads this file; the hook applies cssVars
// to documentElement and preserves the html[data-theme] contract.

