                >
                  <X className="h-4 w-4" aria-hidden strokeWidth={2} />
                </button>
              ) : null}
            </div>
            <div className="spirit-sidebar-header-actions flex flex-wrap items-stretch justify-end gap-2">
              <button
                type="button"
                data-sidebar-action="new-chat"
                onClick={() => {
                  if (newChatMuted) return;
                  onNewChat();
                }}
                disabled={newChatMuted}
                aria-disabled={newChatMuted}
                className={cn(
                  "touch-manipulation inline-flex shrink-0 items-center gap-1.5 rounded-full border border-[color:color-mix(in_oklab,var(--spirit-accent)_42%,transparent)] bg-[color:color-mix(in_oklab,var(--spirit-accent)_12%,transparent)] px-3 py-2 font-mono text-[10px] font-semibold uppercase tracking-wider text-[color:var(--spirit-accent-strong)] transition active:scale-[0.98]",
                  newChatMuted && "opacity-35",
                )}
              >
                <MessageSquarePlus className="spirit-sidebar-action-icon" aria-hidden strokeWidth={1.75} />
                New chat
              </button>
              <button
                type="button"
                data-sidebar-action="new-folder"
                onClick={() => {
                  if (newFolderMuted) return;
                  if (creatingFolder) {
                    folderInputRef.current?.focus();
                    folderInputRef.current?.select();
                    return;
                  }
                  setCreatingFolder(true);
                  setDraftFolderName("");
                  setFolderCreateError(null);
                  queueMicrotask(() => folderInputRef.current?.focus());
                }}
                disabled={newFolderMuted}
                aria-disabled={newFolderMuted}
                aria-label="New folder"
                title="New folder"
                className={cn(
                  "touch-manipulation inline-flex shrink-0 items-center gap-1 rounded-full border border-[color:color-mix(in_oklab,var(--spirit-border)_55%,transparent)] bg-white/[0.03] px-2.5 py-2 font-mono text-[10px] font-semibold uppercase tracking-wider text-chalk/60 transition hover:border-[color:color-mix(in_oklab,var(--spirit-accent)_35%,transparent)] hover:text-chalk/85 active:scale-[0.98]",
                  newFolderMuted && "opacity-35",
                )}
              >
                <FolderPlus className="spirit-sidebar-action-icon" aria-hidden strokeWidth={1.75} />
                Folder
              </button>
            </div>
            {creatingFolder ? (
              <div className="flex flex-col gap-1">
                <input
                  ref={folderInputRef}
                  value={draftFolderName}
                  onChange={(e) => {
                    setDraftFolderName(e.target.value);
                    setFolderCreateError(null);
                  }}
                  placeholder="New folder"
                  aria-label="New folder name"
                  className={cn(
                    "spirit-sidebar-folder-input w-full rounded-lg border border-[color:color-mix(in_oklab,var(--spirit-border)_50%,transparent)] bg-black/30 px-2.5 py-2 font-mono text-[11px] text-chalk outline-none",
                    "placeholder:text-chalk/35 focus:border-[color:color-mix(in_oklab,var(--spirit-accent)_45%,transparent)]",
                  )}
                  onKeyDown={(e) => {
                    if (e.key === "Escape") {
                      e.preventDefault();
                      cancelCreateFolder();
                      return;
                    }
                    if (e.key === "Enter") {
                      e.preventDefault();
                      skipFolderBlurRef.current = true;
                      void commitCreateFolder();
                      queueMicrotask(() => {
                        skipFolderBlurRef.current = false;
                      });
                    }
                  }}
                  onBlur={() => {
                    if (skipFolderBlurRef.current) return;
                    const trimmed = (folderInputRef.current?.value ?? "").trim();
                    if (!trimmed) cancelCreateFolder();
                    else void commitCreateFolder();
                  }}
                />
                {folderCreateError ? (
                  <p className="font-mono text-[9px] text-rose-200/90" role="alert">
                    {folderCreateError}
                  </p>
                ) : null}
              </div>
            ) : null}
            {onSearchQueryChange ? (
              <div className="spirit-sidebar-search-wrap relative px-0.5 pt-1">
                <label htmlFor="chat-thread-search" className="sr-only">
                  Search chats
                </label>
                <Search
                  className="spirit-sidebar-search-icon pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2"
                  aria-hidden
                  strokeWidth={1.8}
                />
                <input
                  id="chat-thread-search"
                  type="search"
                  enterKeyHint="search"
                  value={searchQuery}
                  onChange={(e) => onSearchQueryChange(e.target.value)}
                  placeholder="Search chats..."
                  className="spirit-sidebar-search-input w-full rounded-lg border border-[color:color-mix(in_oklab,var(--spirit-border)_50%,transparent)] bg-black/35 py-2 pl-9 pr-2.5 font-mono text-base text-chalk outline-none placeholder:text-chalk/35 focus:border-[color:color-mix(in_oklab,var(--spirit-accent)_42%,transparent)] lg:text-[11px]"
                />
              </div>
            ) : null}
          </>
        )}
      </div>

      {useDnd ? (
        <ChatSidebarDndProvider
          overlayThread={overlayThread}
          touchActivation={
            layoutVariant === "drawer"
              ? { delay: 200, tolerance: 12 }
              : { delay: 150, tolerance: 6 }
          }
          pointerActivation={{
            distance:
              layoutVariant === "drawer" ? 12 : railPointerActivationPx,
          }}
          onDragStart={(ev) => {
            const activeId = String(ev.active.id);
            resetThreadCollisionSticky();
            setDragActive(activeId);
            setOverId(null);
          }}
          onDragOver={(ev) => {
            setOverId(ev.over ? String(ev.over.id) : null);
          }}
          onDragEnd={handleDragEnd}
          onDragCancel={handleDragCancel}
        >
          <div ref={threadScrollRef} className={scrollClass}>
            {innerScroll(true)}
          </div>
        </ChatSidebarDndProvider>
      ) : (
        <div ref={threadScrollRef} className={scrollClass}>
          {innerScroll(false)}
        </div>
      )}
    </aside>
  );
});"use client";

// ── MessageActions - desktop hover rail; persisted mobile = bottom sheet (9E-A) ──
import { Check, Copy, MoreHorizontal, Pencil, RotateCcw, Trash2, Volume2, X } from "lucide-react";
import { memo, useCallback, useEffect, useRef, useState, type ReactNode } from "react";

import { MobileSheet } from "@/components/chat/MobileSheet";
import { cn } from "@/lib/cn";
import { useMediaMinWidthLg } from "@/lib/hooks/useMediaMinWidthLg";

export type MessageActionsPlacement = "bubble-assistant" | "bubble-user";

export type MessageActionsProps = {
  role: "user" | "assistant";
  placement?: MessageActionsPlacement;
  onCopy: () => void;
  onDelete: () => void;
  onSpeak?: () => void | Promise<void>;
  speakDisabled?: boolean;
  onEdit?: () => void;
  onRegenerate?: () => void;
  regenerateDisabled?: boolean;
  regenerateTitle?: string;
  actionDisabled?: boolean;
  /** Workspace / Dexie chat: below `lg`, open actions in a portal sheet instead of a fat inline row. */
  useActionSheetBelowLg?: boolean;
  /** Long assistant text: split Speak into summary vs chunked full read (Prompt 10B). */
  assistantLongTts?: boolean;
  onSpeakFullChunks?: () => void | Promise<void>;
};

type ActionBtnProps = {
  label: string;
  onClick: () => void | Promise<void>;
  disabled?: boolean;
  icon: ReactNode;
  variant?: "default" | "danger";
  /** When true, label stays visible (mobile expanded / desktop dense). */
  showLabel?: boolean;
};

const ActionBtn = memo(function ActionBtn({
  label,
  onClick,
  disabled,
  icon,
  variant = "default",
  showLabel = false,
}: ActionBtnProps) {
  return (
    <div className="relative flex flex-col items-center">
      <button
        type="button"
        disabled={disabled}
        title={label}
        aria-label={label}
        onClick={() => void onClick()}
        className={cn(
          "group/btn touch-manipulation flex flex-col items-center justify-center gap-0.5 rounded-md px-1.5 py-1 transition",
        "min-h-[32px] min-w-[32px] sm:min-h-[34px] sm:min-w-[34px]",
          variant === "danger"
            ? "text-chalk/55 hover:bg-rose-500/15 hover:text-rose-200 disabled:opacity-30"
            : "text-chalk/55 hover:bg-white/[0.1] hover:text-chalk disabled:opacity-30",
        )}
      >
        <span className="flex items-center justify-center [&>svg]:h-3.5 [&>svg]:w-3.5 [&>svg]:shrink-0">
          {icon}
        </span>
        <span
          className={cn(
            "font-mono text-[8px] font-semibold uppercase tracking-wide text-chalk/75",
            !showLabel && "sm:sr-only",
          )}
        >
          {label}
        </span>
        {!showLabel ? (
          <span
            aria-hidden
            className={cn(
              "pointer-events-none absolute left-1/2 top-full z-30 mt-1 hidden -translate-x-1/2 whitespace-nowrap rounded-md bg-black/90 px-2 py-1 font-mono text-[10px] text-chalk/95 opacity-0 shadow-lg ring-1 ring-white/10 transition-opacity",
              "max-sm:hidden sm:block sm:group-hover/btn:opacity-100 sm:group-focus-visible/btn:opacity-100",
            )}
          >
            {label}
          </span>
        ) : null}
      </button>
    </div>
  );
});

function ActionRow({
  role,
  copyLabel,
  onCopy,
  onDelete,
  onSpeak,
  speakDisabled,
  onEdit,
  onRegenerate,
  regenerateDisabled,
  regenerateTitle,
  actionDisabled,
  showLabels,
  assistantLongTts,
  onSpeakFullChunks,
}: {
  role: "user" | "assistant";
  copyLabel: string;
  onCopy: () => void;
  onDelete: () => void;
  onSpeak?: () => void | Promise<void>;
  speakDisabled?: boolean;
  onEdit?: () => void;
  onRegenerate?: () => void;
  regenerateDisabled?: boolean;
  regenerateTitle?: string;
  actionDisabled?: boolean;
  showLabels: boolean;
  assistantLongTts?: boolean;
  onSpeakFullChunks?: () => void | Promise<void>;
}) {
  return (
    <div
      className="flex flex-wrap items-center justify-end gap-0.5 rounded-lg border border-white/[0.06] bg-black/20 px-0.5 py-0.5 shadow-sm backdrop-blur-sm"
      onPointerDown={(e) => e.stopPropagation()}
    >
      <ActionBtn
        label={copyLabel}
        disabled={actionDisabled}
        onClick={onCopy}
        showLabel={showLabels}
        icon={
          copyLabel === "Copied" ? (
            <Check className="text-emerald-400/90" aria-hidden />
          ) : (
            <Copy aria-hidden />
          )
        }
      />
      {onSpeak ? (
        assistantLongTts && onSpeakFullChunks ? (
          <>
            <ActionBtn
              label="Speak summary"
              disabled={actionDisabled || speakDisabled}
              onClick={() => {
                if (actionDisabled || speakDisabled) return;
                void onSpeak();
              }}
              showLabel={showLabels}
              icon={<Volume2 aria-hidden />}
            />
            <ActionBtn
              label="Read full (chunks)"
              disabled={actionDisabled || speakDisabled}
              onClick={() => {
                if (actionDisabled || speakDisabled) return;
                void onSpeakFullChunks();
              }}
              showLabel={showLabels}
              icon={<Volume2 aria-hidden />}
            />
          </>
        ) : (
          <ActionBtn
            label="Speak"
            disabled={actionDisabled || speakDisabled}
            onClick={() => {
              if (actionDisabled || speakDisabled) return;
              void onSpeak();
            }}
            showLabel={showLabels}
            icon={<Volume2 aria-hidden />}
          />
        )
      ) : null}
      {role === "assistant" && onRegenerate ? (
        <div className="relative flex flex-col items-center">
          <button
            type="button"
            disabled={actionDisabled || regenerateDisabled}
            title={regenerateTitle ?? "Regenerate"}
            aria-label="Regenerate"
            onClick={onRegenerate}
            className="group/btn touch-manipulation flex min-h-[36px] min-w-[36px] flex-col items-center justify-center gap-0.5 rounded-md px-1.5 py-1 text-chalk/55 transition hover:bg-white/[0.1] hover:text-chalk disabled:cursor-not-allowed disabled:opacity-30"
          >
            <RotateCcw className="h-3.5 w-3.5" aria-hidden />
            <span
              className={cn(
                "font-mono text-[8px] font-semibold uppercase tracking-wide text-chalk/75",
                !showLabels && "sm:sr-only",
              )}
            >
              Regenerate
            </span>
            {!showLabels ? (
              <span
                aria-hidden
                className="pointer-events-none absolute left-1/2 top-full z-30 mt-1 hidden -translate-x-1/2 whitespace-nowrap rounded-md bg-black/90 px-2 py-1 font-mono text-[10px] text-chalk/95 opacity-0 shadow-lg ring-1 ring-white/10 transition-opacity max-sm:hidden sm:block sm:group-hover/btn:opacity-100 sm:group-focus-visible/btn:opacity-100"
              >
                Regenerate
              </span>
            ) : null}
          </button>
        </div>
      ) : null}
      {role === "user" && onEdit ? (
        <ActionBtn
          label="Edit"
          disabled={actionDisabled}
          onClick={onEdit}
          showLabel={showLabels}
          icon={<Pencil aria-hidden />}
        />
      ) : null}
      <ActionBtn
        label="Delete"
        disabled={actionDisabled}
        onClick={onDelete}
        showLabel={showLabels}
        variant="danger"
        icon={<Trash2 aria-hidden />}
      />
    </div>
  );
}

function TrayActionTile({
  label,
  icon,
  onClick,
  disabled,
  variant = "default",
  compact,
}: {
  label: string;
  icon: ReactNode;
  onClick: () => void | Promise<void>;
  disabled?: boolean;
  variant?: "default" | "danger";
  /** Horizontal compact tray - shorter tiles, still ≥44px touch. */
  compact?: boolean;
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      aria-label={label}
      onClick={() => void onClick()}
      className={cn(
        "touch-manipulation flex min-h-[44px] min-w-0 flex-col items-center justify-center gap-0.5 rounded-xl border px-1.5 font-mono text-[9px] font-semibold uppercase tracking-wide transition active:scale-[0.98]",
        compact ? "flex-1 basis-0 py-1.5 sm:max-w-[5.5rem]" : "gap-1 px-2 py-2",
        variant === "danger"
          ? "border-[color:color-mix(in_oklab,var(--color-rose)_38%,transparent)] bg-rose-500/10 text-rose-100/90 disabled:opacity-35"
          : "border-[color:var(--spirit-border)] bg-white/[0.04] text-chalk/85 hover:bg-white/[0.07] disabled:opacity-35",
      )}
    >
      <span
        className={cn(
          "flex shrink-0 items-center justify-center [&>svg]:h-4 [&>svg]:w-4",
          compact && "[&>svg]:h-[18px] [&>svg]:w-[18px]",
        )}
      >
        {icon}
      </span>
      <span className="max-w-full truncate leading-tight">{label}</span>
    </button>
  );
}

export const MessageActions = memo(function MessageActions({
  role,
  placement = "bubble-assistant",
  onCopy,
  onDelete,
  onSpeak,
  speakDisabled = false,
  onEdit,
  onRegenerate,
  regenerateDisabled = false,
  regenerateTitle,
  actionDisabled = false,
  useActionSheetBelowLg = false,
  assistantLongTts = false,
  onSpeakFullChunks,
}: MessageActionsProps) {
  const isLg = useMediaMinWidthLg();
  const [copied, setCopied] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [sheetOpen, setSheetOpen] = useState(false);
  const copiedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (copiedTimerRef.current) clearTimeout(copiedTimerRef.current);
    };
  }, []);

  const handleCopy = useCallback(() => {
    if (actionDisabled) return;
    onCopy();
    setCopied(true);
    if (copiedTimerRef.current) clearTimeout(copiedTimerRef.current);
    copiedTimerRef.current = setTimeout(() => setCopied(false), 1200);
  }, [actionDisabled, onCopy]);

  const copyLabel = copied ? "Copied" : "Copy";

  const closeSheet = useCallback(() => setSheetOpen(false), []);

  const bubbleLegacy =
    placement === "bubble-assistant"
      ? "mt-1.5 sm:mt-0 sm:absolute sm:right-1.5 sm:top-1.5 sm:z-20"
      : "mt-1.5 sm:mt-0 sm:absolute sm:bottom-1.5 sm:right-1.5 sm:top-auto sm:z-20";

  const bubbleLgSheet =
    placement === "bubble-assistant"
      ? "mt-1.5 lg:mt-0 lg:absolute lg:right-1.5 lg:top-1.5 lg:z-20"
      : "mt-1.5 lg:mt-0 lg:absolute lg:bottom-1.5 lg:right-1.5 lg:top-auto lg:z-20";

  const useActionSheetMode = useActionSheetBelowLg;
  const bubble = useActionSheetBelowLg ? bubbleLgSheet : bubbleLegacy;

  const sheetCopy = useCallback(() => {
    handleCopy();
    closeSheet();
  }, [handleCopy, closeSheet]);

  const sheetSpeak = useCallback(async () => {
    if (actionDisabled || speakDisabled || !onSpeak) return;
    await onSpeak();
    closeSheet();
  }, [actionDisabled, speakDisabled, onSpeak, closeSheet]);

  const sheetSpeakChunks = useCallback(async () => {
    if (actionDisabled || speakDisabled || !onSpeakFullChunks) return;
    await onSpeakFullChunks();
    closeSheet();
  }, [actionDisabled, speakDisabled, onSpeakFullChunks, closeSheet]);

  const sheetEdit = useCallback(() => {
    if (actionDisabled || !onEdit) return;
    onEdit();
    closeSheet();
  }, [actionDisabled, onEdit, closeSheet]);

  const sheetRegenerate = useCallback(() => {
    if (actionDisabled || regenerateDisabled || !onRegenerate) return;
    onRegenerate();
    closeSheet();
  }, [actionDisabled, regenerateDisabled, onRegenerate, closeSheet]);

  const sheetDelete = useCallback(() => {
    if (actionDisabled) return;
    if (typeof window !== "undefined" && !window.confirm("Delete this message?")) return;
    onDelete();
    closeSheet();
  }, [actionDisabled, onDelete, closeSheet]);

  if (useActionSheetMode && !isLg) {
    // Corner chip only — never `block`+margin below body (reads like extra message / loading).
    const sheetTriggerWrap = cn(
      "absolute z-20 sm:right-1.5",
      role === "assistant" ? "right-1.5 top-2 sm:top-2" : "right-1.5 top-1 sm:top-1.5",
    );

    return (
      <>
        <div className={sheetTriggerWrap}>
          <button
            type="button"
            onClick={() => setSheetOpen(true)}
            aria-expanded={sheetOpen}
            aria-label="Message actions"
            className={cn(
              "touch-manipulation flex min-h-[40px] min-w-[40px] items-center justify-center rounded-lg bg-transparent p-1 text-chalk/40",
              "opacity-25 transition-[opacity,transform] duration-150",
              "active:scale-95 active:opacity-100",
              "focus-visible:opacity-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[color:color-mix(in_oklab,var(--spirit-accent)_38%,transparent)]",
              "group-hover/message:opacity-55",
            )}
          >
            <span
              className="flex h-6 w-6 items-center justify-center rounded-md bg-white/[0.04] ring-1 ring-white/[0.04]"
              aria-hidden
            >
              <MoreHorizontal className="h-3 w-3 opacity-75" strokeWidth={2} />
            </span>
          </button>
        </div>

        <MobileSheet
          open={sheetOpen}
          title="Actions"
          onClose={closeSheet}
          side="bottom"
          variant="trayCompact"
          className="spirit-trinity-chat__sheet-panel"
        >
          <div
            className="flex flex-nowrap items-stretch justify-center gap-2 overflow-x-auto pb-0.5"
            onPointerDown={(e) => e.stopPropagation()}
          >
            <TrayActionTile
              label={copyLabel}
              compact
              icon={
                copyLabel === "Copied" ? (
                  <Check className="text-emerald-400/90" aria-hidden />
                ) : (
                  <Copy aria-hidden />
                )
              }
              onClick={sheetCopy}
              disabled={actionDisabled}
            />
            {onSpeak && assistantLongTts && onSpeakFullChunks ? (
              <>
                <TrayActionTile
                  label="Summary"
                  compact
                  icon={<Volume2 aria-hidden />}
                  onClick={sheetSpeak}
                  disabled={actionDisabled || speakDisabled}
                />
                <TrayActionTile
                  label="Full chunks"
                  compact
                  icon={<Volume2 aria-hidden />}
                  onClick={sheetSpeakChunks}
                  disabled={actionDisabled || speakDisabled}
                />
              </>
            ) : onSpeak ? (
              <TrayActionTile
                label="Speak"
                compact
                icon={<Volume2 aria-hidden />}
                onClick={sheetSpeak}
                disabled={actionDisabled || speakDisabled}
              />
            ) : null}
            {role === "user" && onEdit ? (
              <TrayActionTile
                label="Edit"
                compact
                icon={<Pencil aria-hidden />}
                onClick={sheetEdit}
                disabled={actionDisabled}
              />
            ) : null}
            {role === "assistant" && onRegenerate ? (
              <TrayActionTile
                label="Regenerate"
                compact
                icon={<RotateCcw aria-hidden />}
                onClick={sheetRegenerate}
                disabled={actionDisabled || regenerateDisabled}
              />
            ) : null}
            <TrayActionTile
              label="Delete"
              compact
              icon={<Trash2 aria-hidden />}
              onClick={sheetDelete}
              disabled={actionDisabled}
              variant="danger"
            />
          </div>
        </MobileSheet>
      </>
    );
  }

  if (useActionSheetMode && isLg) {
    return (
      <div
        className={cn(
          "flex flex-wrap items-center justify-end gap-0.5 rounded-md border border-white/[0.08] bg-black/25 px-0.5 py-0.5 shadow-sm backdrop-blur-sm",
          "pointer-events-auto opacity-0 transition-opacity duration-150",
          "group-hover/message:opacity-100 group-focus-within/message:opacity-100",
          bubble,
        )}
      >
        <ActionRow
          role={role}
          copyLabel={copyLabel}
          onCopy={handleCopy}
          onDelete={onDelete}
          onSpeak={onSpeak}
          speakDisabled={speakDisabled}
          onEdit={onEdit}
          onRegenerate={onRegenerate}
          regenerateDisabled={regenerateDisabled}
          regenerateTitle={regenerateTitle}
          actionDisabled={actionDisabled}
          showLabels={false}
          assistantLongTts={assistantLongTts}
          onSpeakFullChunks={onSpeakFullChunks}
        />
      </div>
    );
  }

  return (
    <>
      <div className={cn("max-sm:block sm:hidden", bubble)}>
        {!mobileOpen ? (
          <button
            type="button"
            onClick={() => setMobileOpen(true)}
            aria-expanded={false}
            aria-label="Message actions"
            className="touch-manipulation inline-flex min-h-[36px] min-w-[36px] items-center justify-center rounded-full border border-white/[0.08] bg-black/25 p-1.5 text-chalk/45 opacity-80"
          >
            <MoreHorizontal className="h-3.5 w-3.5" aria-hidden />
          </button>
        ) : (
          <div className="flex flex-col gap-1.5 rounded-lg border border-white/[0.1] bg-black/40 p-2">
            <div className="flex justify-end">
              <button
                type="button"
                onClick={() => setMobileOpen(false)}
                aria-label="Close actions"
                className="inline-flex h-8 w-8 items-center justify-center rounded-md border border-[color:var(--spirit-border)] text-chalk/60"
              >
                <X className="h-3.5 w-3.5" aria-hidden />
              </button>
            </div>
            <ActionRow
              role={role}
              copyLabel={copyLabel}
              onCopy={handleCopy}
              onDelete={onDelete}
              onSpeak={onSpeak}
              speakDisabled={speakDisabled}
              onEdit={onEdit}
              onRegenerate={onRegenerate}
              regenerateDisabled={regenerateDisabled}
              regenerateTitle={regenerateTitle}
              actionDisabled={actionDisabled}
              showLabels
              assistantLongTts={assistantLongTts}
              onSpeakFullChunks={onSpeakFullChunks}
            />
          </div>
        )}
      </div>

      <div
        className={cn(
          "hidden sm:flex sm:flex-wrap sm:items-center sm:justify-end sm:gap-0.5 sm:rounded-lg sm:border sm:border-white/[0.06] sm:bg-black/20 sm:px-0.5 sm:py-0.5 sm:shadow-sm sm:backdrop-blur-sm",
          "sm:pointer-events-auto sm:opacity-0 sm:transition-opacity sm:duration-150",
          "sm:group-hover/message:opacity-100 sm:group-focus-within/message:opacity-100",
          bubble,
        )}
      >
        <ActionRow
          role={role}
          copyLabel={copyLabel}
          onCopy={handleCopy}
          onDelete={onDelete}
          onSpeak={onSpeak}
          speakDisabled={speakDisabled}
          onEdit={onEdit}
          onRegenerate={onRegenerate}
          regenerateDisabled={regenerateDisabled}
          regenerateTitle={regenerateTitle}
          actionDisabled={actionDisabled}
          showLabels={false}
          assistantLongTts={assistantLongTts}
          onSpeakFullChunks={onSpeakFullChunks}
        />
      </div>
    </>
  );
});

