    "@types/react-dom": "^19",
    "@vitejs/plugin-react": "^6.0.1",
    "@vitest/ui": "^4.1.5",
    "eslint": "^9",
    "eslint-config-next": "16.2.4",
    "jsdom": "^24.1.3",
    "next-devtools-mcp": "^0.3.10",
    "repomix": "^1.14.0",
    "tailwindcss": "^4",
    "typescript": "^5",
    "vitest": "^4.1.5",
    "ws": "^8.20.0"
  }
}/* ── Spirit OS globals - minimal @theme + Tailwind v4 import ─────────────────
 * > Turbopack/PostCSS was eating glass on this tree; keep @theme flat, fewer @apply.
 * > Accents + ThemeEngine: _blueprints/design_system.md
 */

@import "tailwindcss" source(none);
@source "./";
@source "../components";
@source "../lib";
@source "../theme";

@theme {
  --color-ink: #0a0a0a;
  --color-void: #090a0f;
  --color-glass: #1a1a1e;
  --color-chalk: #f4f4f5;
  --color-cyan: #22d3ee;
  --color-violet: #a855f7;
  --color-rose: #f43f5e;
  --color-emerald: #10b981;
  --color-amber: #f59e0b;
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-jetbrains-mono), ui-monospace, monospace;
  --text-display: clamp(2.5rem, 8vw, 6rem);
  --text-h1: clamp(2rem, 5vw, 3.5rem);
  --text-h2: clamp(1.5rem, 4vw, 2.5rem);
  --text-body: clamp(1rem, 2.5vw, 1.125rem);
  --leading-reader: 1.8;
  --spacing-section-y: clamp(4rem, 12vw, 6rem);
  --radius-card: 1.5rem;
}

/* Default palette = Frozen Water; useSpiritTheme mirrors stored choice onto <html> */
:root {
  --spirit-bg: #161413;
  --spirit-bg-soft: #1e1c1a;
  --spirit-panel: #242120;
  --spirit-panel-strong: #2e2b29;
  --spirit-accent: #8fb8de;
  --spirit-accent-strong: #cdf7f6;
  --spirit-glow: rgba(143, 184, 222, 0.28);
  --spirit-border: rgba(205, 247, 246, 0.11);
  --spirit-secondary-mix: #9a94bc;
  /* Dashboard v2 atmosphere defaults (mirrors frozen-water; palettes override) */
  --spirit-atmosphere-base: linear-gradient(
    165deg,
    rgba(255, 255, 255, 0.10) 0%,
    transparent 42%,
    rgba(0, 0, 0, 0.12) 100%
  );
  --spirit-atmosphere-a: #8fb8de;
  --spirit-atmosphere-b: #9a94bc;
  --spirit-glass-surface: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.11) 0%,
    rgba(255, 255, 255, 0.03) 55%,
    rgba(36, 33, 32, 0.55) 100%
  );
  --spirit-glass-border: rgba(255, 255, 255, 0.22);
  --spirit-panel-glow:
    0 48px 120px -32px rgba(0, 0, 0, 0.72),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
  --spirit-nav-glow: 0 0 40px -10px rgba(143, 184, 222, 0.42);
  --spirit-fairy-halo: rgba(143, 184, 222, 0.44);
  --spirit-progress-track: rgba(0, 0, 0, 0.48);
  --spirit-theme-chip-active-bg: rgba(143, 184, 222, 0.24);
  --spirit-theme-chip-active-glow: 0 0 28px -6px rgba(143, 184, 222, 0.38);
}

@utility glass {
  background: rgba(255, 255, 255, 0.02);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

@utility scrollbar-hide {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

@utility shadow-quarantine-inset {
  box-shadow: inset 0 0 120px color-mix(in oklab, var(--color-rose) 14%, transparent);
}

@layer utilities {
  .scrollbar-hide::-webkit-scrollbar {
    display: none;
  }
  html[data-spirit-typography="mono"] body {
    font-family: var(--font-mono), ui-monospace, monospace;
    font-feature-settings: "kern" 0, "liga" 0;
  }
  html[data-spirit-typography="mono"] :where(h1, h2, h3, h4) {
    font-family: var(--font-mono), ui-monospace, monospace;
    font-feature-settings: "kern" 0, "liga" 0;
  }
}

/* ── Homelab Design System - keyframes ──────────────────────────────────── */

@keyframes hl-track-pulse {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 1; }
}
@keyframes hl-bar-glow {
  0%, 100% { filter: brightness(1) saturate(1); }
  50% { filter: brightness(1.14) saturate(1.1); }
}
@keyframes hl-bar-sheen {
  to { transform: translateX(200%); }
}
@keyframes hl-status-glow {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.14); filter: brightness(1.22); }
}
@keyframes hl-tag-glow {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.12); }
}
@keyframes hl-tag-sheen {
  to { transform: translateX(160%); }
}
@keyframes hl-badge-pulse {
  to { box-shadow: 0 0 0 7px transparent; }
}
@keyframes hl-badge-sheen {
  to { transform: translateX(180%); }
}

/* ── Dashboard v2 shell (dashboardDemo port — production / only via SpiritDashboardHome) ── */
@keyframes spirit-dashboard-v2-drift-a {
  0%,
  100% {
    transform: translate(0, 0) rotate(15deg);
  }
  33% {
    transform: translate(8%, 4%) rotate(18deg);
  }
  66% {
    transform: translate(3%, -3%) rotate(12deg);
  }
}
@keyframes spirit-dashboard-v2-drift-b {
  0%,
  100% {
    transform: translate(0, 0) rotate(-12deg);
  }
  50% {
    transform: translate(-10%, -5%) rotate(-16deg);
  }
}
@keyframes spirit-dashboard-v2-breathe {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(1);
  }
  50% {
    opacity: 0.55;
    transform: scale(1.06);
  }
}

@layer utilities {

  /* Dashboard glass shell: transparent surface over atmosphere, wraps sidebar + content */
  .spirit-dashboard-v2-glass-shell {
    background: color-mix(in oklab, var(--spirit-bg-soft) 6%, transparent);
  }

  /* Frosted shell cards — dashboardDemo glass-pearl / glass-smoke parity */
  .spirit-dashboard-v2-glass {
    position: relative;
    overflow: hidden;
    border-radius: clamp(1.35rem, 3vw, 2.25rem);
    border: 1px solid var(--spirit-glass-border);
    background: var(--spirit-glass-surface);
    backdrop-filter: blur(52px) saturate(150%);
    -webkit-backdrop-filter: blur(52px) saturate(150%);
    box-shadow: var(--spirit-panel-glow);
  }

  .spirit-dashboard-v2-glass--oracle {
    border-radius: clamp(1.5rem, 3.4vw, 2.65rem);
    border-color: color-mix(in oklab, var(--spirit-accent) 38%, var(--spirit-glass-border));
    box-shadow:
      var(--spirit-panel-glow),
      0 0 64px -36px color-mix(in oklab, var(--spirit-fairy-halo) 48%, transparent);
  }

  .spirit-dashboard-v2-glass__shine-t,
  .spirit-dashboard-v2-glass__shine-l {
    pointer-events: none;
    position: absolute;
  }

  .spirit-dashboard-v2-glass__shine-t {
    inset-inline: 10%;
    top: 0;
    height: 1px;
    background: linear-gradient(
      90deg,
      transparent,
      color-mix(in oklab, var(--spirit-accent-strong) 35%, transparent),
      transparent
    );
    opacity: 0.65;
  }

  .spirit-dashboard-v2-glass__shine-l {
    inset-block: 18%;
    left: 0;
    width: 1px;
    background: linear-gradient(
      180deg,
      transparent,
      rgba(255, 255, 255, 0.18),
      transparent
    );
    opacity: 0.45;
  }

  .spirit-dashboard-v2-inner-card {
    border-radius: 1.125rem;
    border: 1px solid color-mix(in oklab, var(--spirit-glass-border) 62%, transparent);
    background: color-mix(in oklab, var(--spirit-bg-soft) 44%, transparent);
  }

  /* Telemetry bars: rimmed track reads better on smoky glass */
  .spirit-dashboard-v2-glass .homelab-progress {
    box-shadow:
      inset 0 1px 2px rgba(0, 0, 0, 0.58),
      0 0 0 1px color-mix(in oklab, var(--spirit-glass-border) 38%, transparent);
  }

  .spirit-dashboard-v2-header-glass {
    border-bottom: 1px solid color-mix(in oklab, var(--spirit-glass-border) 48%, transparent);
    background: color-mix(in oklab, var(--spirit-glass-surface) 35%, transparent);
    backdrop-filter: blur(36px) saturate(140%);
    -webkit-backdrop-filter: blur(36px) saturate(140%);
  }

  .spirit-dashboard-v2-fairy-halo {
    position: absolute;
    inset: -8%;
    border-radius: 50%;
    background: radial-gradient(
      circle at 50% 50%,
      var(--spirit-fairy-halo),
      transparent 68%
    );
    filter: blur(42px);
    opacity: 0.44;
    animation: spirit-dashboard-v2-breathe 5.5s ease-in-out infinite;
  }

  .spirit-dashboard-v2-cta-primary {
    border-radius: 9999px;
    box-shadow:
      0 18px 48px -16px color-mix(in oklab, var(--spirit-accent) 42%, transparent),
      inset 0 1px 0 rgba(255, 255, 255, 0.12);
  }

  /* Theme chip dock — dashboardDemo pill tray without touching shared `glass` utility consumers */
  .spirit-dashboard-v2-theme-shell {
    border-radius: 9999px;
    padding: 4px;
    border: 1px solid color-mix(in oklab, var(--spirit-glass-border) 85%, transparent);
    background: color-mix(in oklab, var(--spirit-bg-soft) 58%, transparent);
    backdrop-filter: blur(28px) saturate(145%);
    -webkit-backdrop-filter: blur(28px) saturate(145%);
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.07),
      0 12px 40px -18px rgba(0, 0, 0, 0.45);
  }

  @media (prefers-reduced-motion: reduce) {
    .spirit-dashboard-v2-fairy-halo {
      animation: none !important;
    }
  }

  /* Glass panel - layered depth */
  .homelab-panel {
    position: relative;
    background:
      linear-gradient(180deg, rgba(255,255,255,0.052) 0%, rgba(255,255,255,0.018) 45%, rgba(255,255,255,0.012) 100%),
      color-mix(in oklab, var(--spirit-bg) 88%, transparent);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 20px;
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,0.06),
      0 2px 4px rgba(0,0,0,0.45),
      0 20px 48px -24px rgba(0,0,0,0.85);
    backdrop-filter: blur(22px) saturate(140%);
    overflow: hidden;
  }
  /** Slimmer glass slab - nodes strip only (still reads Homelab, less podium) */
  .homelab-panel--dense {
    border-radius: 14px;
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,0.055),
      0 1px 2px rgba(0,0,0,0.38),
      0 10px 28px -16px rgba(0,0,0,0.72);
    backdrop-filter: blur(16px) saturate(132%);
  }
  .homelab-panel-accent {
    border-color: color-mix(in oklab, var(--spirit-accent) 36%, transparent);
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,0.07),
      0 2px 4px rgba(0,0,0,0.45),
      0 32px 80px -40px color-mix(in oklab, var(--spirit-accent) 45%, transparent);
  }

  /* Progress bar track */
  .homelab-progress {
    position: relative;
    height: 7px;
    border-radius: 9999px;
    background: var(--spirit-progress-track, rgba(0, 0, 0, 0.4));
    box-shadow: inset 0 1px 1px rgba(0,0,0,0.62);
    overflow: hidden;
  }
  .homelab-progress::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
      90deg,
      transparent var(--hl-pct, 0%),
      color-mix(in oklab, var(--spirit-accent) 22%, transparent) var(--hl-pct, 0%),
      color-mix(in oklab, var(--spirit-accent) 10%, transparent) 100%
    );
    animation: hl-track-pulse 2.8s ease-in-out infinite;
  }

  /* Progress bar fill */
  .homelab-progress-fill {
    position: absolute;
    top: 0; bottom: 0; left: 0;
    border-radius: 9999px;
    background: linear-gradient(90deg, color-mix(in oklab, var(--spirit-accent) 60%, #000), var(--spirit-accent));
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.22);
    animation: hl-bar-glow 2.6s ease-in-out infinite;
    overflow: hidden;
  }
  .homelab-progress-fill::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(100deg, transparent 15%, rgba(255,255,255,0.30) 50%, transparent 85%);
    transform: translateX(-100%);
    animation: hl-bar-sheen 2.9s linear infinite;
  }
  .homelab-progress-fill--good {
    background: linear-gradient(90deg, oklch(0.44 0.16 160), oklch(0.76 0.16 160));
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.22);
  }
  .homelab-progress-fill--warn {
    background: linear-gradient(90deg, oklch(0.50 0.16 80), oklch(0.82 0.14 80));
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.22);
  }
  .homelab-progress-fill--bad {
    background: linear-gradient(90deg, oklch(0.44 0.20 25), oklch(0.70 0.20 25));
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.22);
  }

  /* Animated status dot */
  .homelab-status-dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    flex-shrink: 0;
    background: oklch(0.74 0.16 160);
    box-shadow: 0 0 10px oklch(0.74 0.16 160 / 0.85), 0 0 0 3px oklch(0.74 0.16 160 / 0.14);
    animation: hl-status-glow 2s ease-in-out infinite;
  }
  .homelab-status-dot--pending {
    background: oklch(0.80 0.16 80);
    box-shadow: 0 0 10px oklch(0.80 0.16 80 / 0.85), 0 0 0 3px oklch(0.80 0.16 80 / 0.14);
  }
  .homelab-status-dot--offline {
    background: oklch(0.66 0.20 25);
    box-shadow: 0 0 8px oklch(0.66 0.20 25 / 0.7), 0 0 0 3px oklch(0.66 0.20 25 / 0.12);
    animation: none;
  }

  /* Glowing tag (SSD, HDD, labels) */
  .homelab-tag {
    position: relative;
    overflow: hidden;
    display: inline-flex;
    align-items: center;
    font-family: var(--font-mono);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--spirit-accent-strong);
    padding: 3px 8px;
    border-radius: 9999px;
    border: 1px solid color-mix(in oklab, var(--spirit-accent) 28%, transparent);
    background: color-mix(in oklab, var(--spirit-accent) 34%, transparent);
    white-space: nowrap;
    animation: hl-tag-glow 2.8s ease-in-out infinite;
  }
  .homelab-tag::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(110deg, transparent 10%, rgba(255,255,255,0.38) 50%, transparent 90%);
    transform: translateX(-130%);
    animation: hl-tag-sheen 3.5s linear infinite;
  }
  .homelab-tag--ssd {
    color: oklch(0.72 0.14 230);
    border-color: oklch(0.72 0.14 230 / 0.28);
    background: oklch(0.72 0.14 230 / 0.28);
  }
  .homelab-tag--hdd {
    color: oklch(0.78 0.16 80);
    border-color: oklch(0.78 0.16 80 / 0.26);
    background: oklch(0.78 0.16 80 / 0.26);
  }
  .homelab-tag--unknown {
    color: oklch(0.74 0.06 280);
    border-color: oklch(0.74 0.06 280 / 0.24);
    background: oklch(0.74 0.06 280 / 0.22);
  }

  /* Status badges */
  .homelab-badge {
    position: relative;
    overflow: hidden;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 22px;
    padding: 0 9px;
    border-radius: 9999px;
    font-family: var(--font-mono);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    border: 1px solid;
    white-space: nowrap;
    animation: hl-tag-glow 3.2s ease-in-out infinite;
  }
  .homelab-badge::before {
    content: "";
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: currentColor;
    flex-shrink: 0;
  }
  .homelab-badge::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(110deg, transparent 12%, rgba(255,255,255,0.34) 50%, transparent 88%);
    transform: translateX(-130%);
    animation: hl-badge-sheen 4.2s linear infinite;
  }
  .homelab-badge--live {
    color: oklch(0.74 0.16 160);
    background: oklch(0.74 0.16 160 / 0.28);
    border-color: oklch(0.74 0.16 160 / 0.30);
  }
  .homelab-badge--live::before {
    animation: hl-badge-pulse 1.6s ease-out infinite;
    box-shadow: 0 0 0 0 currentColor;
  }
  .homelab-badge--pending {
    color: oklch(0.80 0.16 80);
    background: oklch(0.80 0.16 80 / 0.26);
    border-color: oklch(0.80 0.16 80 / 0.28);
  }
  .homelab-badge--mock {
    color: rgba(255,255,255,0.48);
    background: rgba(255,255,255,0.16);
    border-color: rgba(255,255,255,0.08);
  }
  .homelab-badge--offline {
    color: oklch(0.66 0.20 25);
    background: oklch(0.66 0.20 25 / 0.24);
    border-color: oklch(0.66 0.20 25 / 0.28);
  }
  .homelab-badge--ready {
    color: var(--spirit-accent-strong);
    background: color-mix(in oklab, var(--spirit-accent) 30%, transparent);
    border-color: color-mix(in oklab, var(--spirit-accent) 30%, transparent);
  }

  /* Reduced-motion fallback */
  @media (prefers-reduced-motion: reduce) {
    .homelab-progress-fill,
    .homelab-progress-fill::after,
    .homelab-progress::before,
    .homelab-status-dot,
    .homelab-tag,
    .homelab-tag::after,
    .homelab-badge,
    .homelab-badge::after,
    .homelab-badge--live::before {
      animation: none !important;
    }
  }

  /* -- Phase 2.7/2.8: compact theme swatches for nav bubble ───────────── */

  .dash-theme-bubble-swatch {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.375rem;   /* 38px touch target */
    height: 2.375rem;
    border-radius: 9999px;
    border: 2px solid transparent;
    flex-shrink: 0;
    touch-action: manipulation;
    transition: border-color 0.15s, box-shadow 0.15s, transform 0.12s;
  }
  .dash-theme-bubble-swatch:hover {
    transform: scale(1.12);
  }
  /* Dark themes: white ring for active swatch */
  .dash-theme-bubble-swatch--active {
    border-color: rgba(255, 255, 255, 0.62);
    box-shadow: 0 0 12px -3px rgba(255, 255, 255, 0.40);
  }
  /* Frozen Water: dark ring on light bubble */
  html[data-theme="frozen-water"] [data-layout="spirit-dashboard-home"] .dash-theme-bubble-swatch--active {
    border-color: rgba(15, 23, 42, 0.65);
    box-shadow: 0 0 10px -4px rgba(15, 23, 42, 0.28);
  }

  /* -- Phase 2.9: Frozen Water pearl board (dashboardDemo glass-pearl) ───────
   * Kills Phase 2.5 navy smoke on widgets + reconciles Tailwind text-chalk here. */
  html[data-theme="frozen-water"] [data-layout="spirit-dashboard-home"] {
    --color-chalk: #0f172a;
    --dash-utility-fg: #1e293b;
    --dash-utility-muted: rgba(30, 41, 59, 0.52);
    --spirit-glass-surface: linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.15) 0%,
      rgba(255, 255, 255, 0.06) 52%,
      rgba(255, 255, 255, 0.11) 100%
    );
    --spirit-glass-border: rgba(255, 255, 255, 0.72);
    --spirit-panel-glow:
      0 40px 100px -24px rgba(15, 23, 42, 0.08),
      inset 0 1px 0 rgba(255, 255, 255, 0.48);
    --spirit-progress-track: rgba(15, 23, 42, 0.12);
    --spirit-theme-chip-active-bg: rgba(255, 255, 255, 0.42);
    --spirit-theme-chip-active-glow: 0 0 18px -6px rgba(15, 23, 42, 0.12);
  }

  html[data-theme="frozen-water"] [data-layout="spirit-dashboard-home"] .spirit-dashboard-v2-inner-card {
    border-color: rgba(255, 255, 255, 0.52);
    background: rgba(255, 255, 255, 0.16);
  }

  html[data-theme="frozen-water"] [data-layout="spirit-dashboard-home"] .spirit-dashboard-v2-glass .homelab-progress {
    box-shadow:
      inset 0 1px 2px rgba(15, 23, 42, 0.08),
      0 0 0 1px rgba(255, 255, 255, 0.28);
  }

}

@layer base {
  html {
    scroll-behavior: smooth;
    background-color: var(--spirit-bg, #090a0f);
  }
  body {
    background-color: var(--spirit-bg, #090a0f);
    color: color-mix(in oklab, var(--color-chalk) 97%, transparent);
    font-family: var(--font-sans);
    font-size: var(--text-body);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    font-feature-settings: "kern" 1, "liga" 1;
  }
  :where(h1, h2, h3, h4) {
    font-family: var(--font-sans);
    font-weight: 600;
    letter-spacing: normal;
    color: var(--color-chalk);
  }
  ::selection {
    background-color: color-mix(in oklab, var(--color-cyan) 25%, transparent);
    color: var(--color-chalk);
  }
  :focus-visible {
    outline: 2px solid color-mix(in oklab, var(--color-cyan) 80%, transparent);
    outline-offset: 2px;
  }
  @media (max-width: 1023px) {
    input,
    textarea,
    select {
      font-size: 16px;
    }
  }
}"use client";

// ── MobileSheet - portal overlay; escapes overflow/transform hell (Prompt 9E-A) ─
import { X } from "lucide-react";
import {
  memo,
  useCallback,
  useEffect,
  useId,
  useState,
} from "react";
import { createPortal } from "react-dom";

import { cn } from "@/lib/cn";

export type MobileSheetSide = "left" | "right" | "bottom";

export type MobileSheetVariant = "panel" | "tray" | "trayCompact";

export type MobileSheetProps = {
  open: boolean;
  title: string;
  onClose: () => void;
  children: React.ReactNode;
  side?: MobileSheetSide;
  className?: string;
  /** `tray` = compact bottom sheet for quick actions (Prompt 9F). */
  variant?: MobileSheetVariant;
  /** Trinity /chat: portaled panel uses global liquid-glass selectors (Language C). */
  trinityLiquidChrome?: boolean;
};

export const MobileSheet = memo(function MobileSheet({
  open,
  title,
  onClose,
  children,
  side = "bottom",
  className,
  variant = "panel",
  trinityLiquidChrome = false,
}: MobileSheetProps) {
  const [mounted, setMounted] = useState(false);
  const titleId = useId();

  useEffect(() => {
    setMounted(true);
  }, []);

  const onKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    },
    [onClose],
  );

  useEffect(() => {
    if (!open) return;
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open, onKeyDown]);

  // ── While a sheet covers the screen, lock document scroll (replacing the old /chat-wide lock).
  // SpiritChat uses default overscroll on mobile so PTR works; overlays must not scroll the page behind.
  useEffect(() => {
    if (!mounted || !open) return;
    const html = document.documentElement;
    const body = document.body;
    const prevHtml = html.style.overflow;
    const prevBody = body.style.overflow;
    html.style.overflow = "hidden";
    body.style.overflow = "hidden";
    return () => {
      html.style.overflow = prevHtml;
      body.style.overflow = prevBody;
    };
  }, [mounted, open]);

  if (!mounted || !open) return null;

  const liquidShell =
    trinityLiquidChrome &&
    "spirit-trinity-modal-glass border-transparent bg-transparent shadow-none backdrop-blur-xl";

  const panel =
    side === "left" ? (
      <div
        data-trinity-liquid={trinityLiquidChrome ? "sheet-panel" : undefined}
        className={cn(
          "pointer-events-auto absolute inset-y-0 left-0 z-[2] flex w-[min(92vw,360px)] flex-col border-r border-[color:var(--spirit-border)] bg-[color:color-mix(in_oklab,var(--spirit-bg)_98%,black)] shadow-[8px_0_40px_-12px_rgba(0,0,0,0.65)]",
          liquidShell,
          className,
        )}
      >
        <header className="flex shrink-0 items-center justify-between gap-2 border-b border-white/[0.06] px-3 py-2.5">
          <h2
            id={titleId}
            className="truncate font-mono text-[11px] font-semibold uppercase tracking-[0.18em] text-chalk/70"
          >
            {title}
          </h2>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="inline-flex h-9 w-9 shrink-0 touch-manipulation items-center justify-center rounded-lg border border-[color:var(--spirit-border)] bg-white/[0.04] text-chalk/75"
          >
            <X className="h-4 w-4" aria-hidden strokeWidth={2} />
          </button>
        </header>
        <div className="scrollbar-hide min-h-0 flex-1 overflow-y-auto overscroll-y-contain px-1 pb-[max(0.75rem,env(safe-area-inset-bottom))] pt-1">
          {children}
        </div>
      </div>
    ) : side === "right" ? (
      <div
        data-trinity-liquid={trinityLiquidChrome ? "sheet-panel" : undefined}
        className={cn(
          "pointer-events-auto absolute inset-y-0 right-0 z-[2] flex w-[min(92vw,360px)] flex-col border-l border-[color:var(--spirit-border)] bg-[color:color-mix(in_oklab,var(--spirit-bg)_98%,black)] shadow-[-8px_0_40px_-12px_rgba(0,0,0,0.65)]",
          liquidShell,
          className,
        )}
      >
        <header className="flex shrink-0 items-center justify-between gap-2 border-b border-white/[0.06] px-3 py-2.5">
          <h2
            id={titleId}
            className="truncate font-mono text-[11px] font-semibold uppercase tracking-[0.18em] text-chalk/70"
          >
            {title}
          </h2>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="inline-flex h-9 w-9 shrink-0 touch-manipulation items-center justify-center rounded-lg border border-[color:var(--spirit-border)] bg-white/[0.04] text-chalk/75"
          >
            <X className="h-4 w-4" aria-hidden strokeWidth={2} />
          </button>
        </header>
        <div className="scrollbar-hide min-h-0 flex-1 overflow-y-auto overscroll-y-contain px-1 pb-[max(0.75rem,env(safe-area-inset-bottom))] pt-1">
          {children}
        </div>
      </div>
    ) : (
      <div
        data-trinity-liquid={trinityLiquidChrome ? "sheet-panel" : undefined}
        className={cn(
          "pointer-events-auto absolute inset-x-0 bottom-0 z-[2] flex flex-col rounded-t-2xl border border-b-0 border-[color:var(--spirit-border)] bg-[color:color-mix(in_oklab,var(--spirit-bg)_98%,black)] shadow-[0_-12px_48px_-8px_rgba(0,0,0,0.55)]",
          variant === "tray"
            ? "max-h-[min(52dvh,420px)] rounded-t-3xl"
            : variant === "trayCompact"
              ? "max-h-[min(45dvh,360px)] rounded-t-2xl"
              : "max-h-[min(70dvh,560px)]",
          liquidShell,
          className,
        )}
      >
        {variant === "tray" || variant === "trayCompact" ? (
          <div
            className={cn(
              "flex shrink-0 flex-col items-center border-b border-white/[0.06] px-3",
              variant === "trayCompact" ? "pt-1.5 pb-1" : "pt-2 pb-1",
            )}
          >
            <div
              className={cn(
                "mb-1 flex shrink-0 items-center justify-center gap-0.5",
                variant === "trayCompact" ? "min-h-[10px] py-1" : "min-h-[12px]",
              )}
              aria-hidden
            >
              {variant === "trayCompact" ? (
                <span className="grid grid-cols-3 gap-0.5 opacity-40">
                  {Array.from({ length: 6 }).map((_, i) => (
                    <span key={i} className="h-[3px] w-[3px] rounded-full bg-chalk/55" />
                  ))}
                </span>
              ) : (
                <div className="h-1 w-10 shrink-0 rounded-full bg-chalk/25" />
              )}
            </div>
            <div className="flex w-full items-center justify-between gap-2">
              <h2
                id={titleId}
                className={cn(
                  "truncate font-mono font-semibold uppercase tracking-[0.2em] text-chalk/50",
                  variant === "trayCompact"
                    ? "text-[8px] opacity-70"
                    : "text-[9px]",
                )}
              >
                {title}
              </h2>
              <button
                type="button"
                onClick={onClose}
                aria-label="Close"
                className={cn(
                  "inline-flex shrink-0 touch-manipulation items-center justify-center rounded-lg border border-[color:var(--spirit-border)] bg-white/[0.04] text-chalk/75",
                  variant === "trayCompact"
                    ? "h-8 w-8 [&>svg]:h-3 [&>svg]:w-3"
                    : "h-8 w-8 [&>svg]:h-3.5 [&>svg]:w-3.5",
                )}
              >
                <X aria-hidden strokeWidth={2} />
              </button>
            </div>
          </div>
        ) : (
          <header className="flex shrink-0 items-center justify-between gap-2 border-b border-white/[0.06] px-3 py-2.5">
            <h2
              id={titleId}
              className="truncate font-mono text-[11px] font-semibold uppercase tracking-[0.18em] text-chalk/70"
            >
              {title}
            </h2>
            <button
              type="button"
              onClick={onClose}
              aria-label="Close"
              className="inline-flex h-9 w-9 shrink-0 touch-manipulation items-center justify-center rounded-lg border border-[color:var(--spirit-border)] bg-white/[0.04] text-chalk/75"
            >
              <X className="h-4 w-4" aria-hidden strokeWidth={2} />
            </button>
          </header>
        )}
        <div
          className={cn(
            "scrollbar-hide min-h-0 flex-1 overflow-y-auto overscroll-y-contain px-3 pb-[max(1rem,env(safe-area-inset-bottom))] pt-2",
            (variant === "tray" || variant === "trayCompact") &&
              "px-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] pt-2",
            variant === "trayCompact" && "pt-1.5",
          )}
        >
          {children}
        </div>
      </div>
    );

  return createPortal(
    <div
      className="fixed inset-0 z-[110] isolate"
      role="presentation"
    >
      <button
        type="button"
        aria-label="Dismiss"
        className="absolute inset-0 z-[1] bg-black/55 backdrop-blur-[1px]"
        onClick={onClose}
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="pointer-events-none absolute inset-0 z-[2]"
      >
        {panel}
      </div>
    </div>,
    document.body,
  );
});"use client";

// ── SpiritMessage - bubble-first layout; actions in-bubble (Prompt 9B) ───────────
// > GPT-adjacent polish: calm assistant surface (no lateral glow smear), compact user rail.
import type { UIMessage } from "ai";
import { motion } from "framer-motion";
import { memo, useCallback, useMemo, useState } from "react";

import { EditableUserMessage } from "@/components/chat/EditableUserMessage";
import { MessageActions } from "@/components/chat/MessageActions";
import { MessageMarkdown } from "@/components/chat/MessageMarkdown";
import { SpiritToolActivityCards } from "@/components/chat/SpiritToolActivityCards";
import type { SpiritWebSourcesHeaderPayload } from "@/lib/spirit/spirit-web-sources";
import { SectionLabel } from "@/components/ui/SectionLabel";
import { StreamingCursor } from "@/components/chat/StreamingCursor";
import { cn } from "@/lib/cn";
import { textFromParts } from "@/lib/chat-utils";
import { copyTextToClipboard } from "@/lib/clipboard";
import { sanitizeAssistantVisibleText } from "@/lib/spirit/assistant-output-sanitizer";
import { stripFakeCitationsWhenNoSources } from "@/lib/spirit/research-source-enforcement";
import { mergeSpiritToolActivityCardsForMessage } from "@/lib/spirit/spirit-assistant-tool-activity";

export type SpiritMessageProps = {
  message: UIMessage;
  isStreamingLatest?: boolean;
  isBusy?: boolean;
  canRegenerate?: boolean;
  onDelete?: () => void;
  onEditSave?: (text: string) => void;
  onRegenerate?: () => void;
  onSpeak?: () => void | Promise<void>;
  /** Prompt 10B - read full assistant reply in TTS-safe chunks */
  onSpeakFullChunks?: () => void | Promise<void>;
  assistantLongVoice?: boolean;
  speakDisabled?: boolean;
  actionDisabled?: boolean;
  /** Dexie workspace: message actions use a portal sheet below the `lg` breakpoint. */
  useActionSheetBelowLg?: boolean;
  onCopyFeedback?: (ok: boolean) => void;
  /** Prompt 10C-C - strip fake [n] / Sources when Researcher had zero verified URLs */
  stripFakeResearchCitations?: boolean;
  /** When assistant had verified web sources, rewrite degenerate ## Sources from header JSON */
  webSourcesSnapshot?: SpiritWebSourcesHeaderPayload | null;
};

export const SpiritMessage = memo(function SpiritMessage({
  message,
  isStreamingLatest = false,
  isBusy = false,
  canRegenerate = false,
  onDelete,
  onEditSave,
  onRegenerate,
  onSpeak,
  onSpeakFullChunks,
  assistantLongVoice = false,
  speakDisabled = false,
  actionDisabled = false,
  useActionSheetBelowLg = false,
  onCopyFeedback,
  stripFakeResearchCitations = false,
  webSourcesSnapshot = null,
}: SpiritMessageProps) {
  const isUser = message.role === "user";
  const [editing, setEditing] = useState(false);
  const rawBody = textFromParts(message);
  const body = useMemo(() => {
    if (isUser) return rawBody;
    const cleaned = sanitizeAssistantVisibleText(rawBody);
    return stripFakeResearchCitations ? stripFakeCitationsWhenNoSources(cleaned) : cleaned;
  }, [isUser, rawBody, stripFakeResearchCitations]);

  const toolActivityCards = useMemo(() => {
    if (isUser) return [];
    return mergeSpiritToolActivityCardsForMessage(message);
  }, [isUser, message]);

  const handleCopy = useCallback(async () => {
    const r = await copyTextToClipboard(body);
    onCopyFeedback?.(r.ok);
  }, [body, onCopyFeedback]);

  const actionsDisabled = Boolean(actionDisabled || (isUser && editing));

  return (
    <motion.div
      initial={false}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
      className={cn(
        "group/message flex w-full min-w-0",
        isUser ? "justify-end" : "justify-start",
      )}
      data-role={message.role}
    >
      <div
        className={cn(
          isUser
            ? "max-w-[min(34rem,calc(100%-0.25rem))] sm:max-w-[min(38rem,calc(100%-1.5rem))]"
            : "w-full max-w-[min(720px,calc(100%-0.25rem))] sm:max-w-[min(760px,calc(100%-1.5rem))]",
        )}
      >
        <div
          className={cn(
            "relative flex min-w-0 flex-col",
            !isUser && [
              "w-full max-w-full",
              "border border-[color:color-mix(in_oklab,var(--spirit-border)_38%,transparent)] border-l-[2px] border-l-[color:color-mix(in_oklab,var(--spirit-accent)_55%,transparent)]",
              "bg-white/[0.028]",
              "max-lg:rounded-2xl max-lg:py-2 max-lg:pl-3 max-lg:pr-2",
              "rounded-2xl py-2.5 pl-3.5 pr-2.5 sm:py-3 sm:pl-4 sm:pr-3 lg:rounded-2xl",
            ],
            isUser && [
              "w-fit max-w-full",
              "max-lg:rounded-2xl max-lg:px-3 max-lg:py-1.5",
              "rounded-2xl border border-[color:color-mix(in_oklab,var(--spirit-border)_55%,transparent)]",
              "bg-white/[0.038] px-3 py-2 sm:rounded-2xl sm:px-4 sm:py-2",
            ],
          )}
        >
          <div
            className={cn(
              "min-w-0",
            !isUser &&
              "max-lg:pr-11 pr-1 sm:pr-2 lg:pr-[5.5rem]",
            isUser &&
              (useActionSheetBelowLg
                ? "pb-1 pr-1 max-lg:pr-11 sm:pr-2 sm:pb-1.5 lg:pb-8"
                : "sm:pb-8 sm:pr-2"),
            )}
          >
            {isUser ? (
              <SectionLabel className="mb-0.5 block text-[10px] font-medium tracking-wider text-chalk/38 max-lg:text-[10px] sm:mb-1 sm:text-[11px]">
                You
              </SectionLabel>
            ) : (
              <SectionLabel className="mb-0.5 block max-w-[calc(100%-2.5rem)] font-mono text-[9px] tracking-[0.14em] text-chalk/48 max-lg:text-[9px] sm:mb-1 sm:max-w-none sm:text-[10px] sm:tracking-[0.18em]">
                Spirit
              </SectionLabel>
            )}
            {isUser && editing && onEditSave ? (
              <EditableUserMessage
                initialText={body}
                disabled={isBusy}
                onSave={(next) => {
                  onEditSave(next);
                  setEditing(false);
                }}
                onCancel={() => setEditing(false)}
              />
            ) : isUser ? (
              <p className="whitespace-pre-wrap break-words [overflow-wrap:anywhere] font-sans text-[16px] leading-snug text-chalk/90 max-lg:text-[16px] sm:text-[15px] sm:leading-relaxed">
                {body}
              </p>
            ) : (
              <div className="min-w-0 max-w-full [overflow-wrap:anywhere]">
                <MessageMarkdown text={body} webSourcesSnapshot={webSourcesSnapshot} />
                {toolActivityCards.length > 0 ? (
                  <SpiritToolActivityCards cards={toolActivityCards} />
                ) : null}
                {isStreamingLatest ? <StreamingCursor /> : null}
              </div>
            )}
          </div>
          {onDelete ? (
            <MessageActions
              role={isUser ? "user" : "assistant"}
              placement={isUser ? "bubble-user" : "bubble-assistant"}
              onCopy={() => void handleCopy()}
              onDelete={onDelete}
              onEdit={
                isUser && onEditSave
                  ? () => {
                      if (isBusy) return;
                      setEditing(true);
                    }
                  : undefined
              }
              onRegenerate={!isUser && onRegenerate ? onRegenerate : undefined}
              onSpeak={onSpeak}
              onSpeakFullChunks={!isUser ? onSpeakFullChunks : undefined}
              assistantLongTts={!isUser && assistantLongVoice}
              speakDisabled={speakDisabled}
              regenerateDisabled={!isUser && !canRegenerate}
              regenerateTitle={
                !isUser && !canRegenerate
                  ? "Regenerate is only available for the latest assistant reply"
                  : undefined
              }
              actionDisabled={actionsDisabled}
              useActionSheetBelowLg={useActionSheetBelowLg}
            />
          ) : null}
        </div>
      </div>
    </motion.div>
  );
});"use client";

// ── SpiritWorkspaceShell - `/chat` GPT workspace (VV-sized shell, scroll inside SpiritChat) ─
// DEPRECATED CONTEXT: DashboardClient StageId rails are archival only; Neural has no throne.
// **Do not** set html/body overflow:hidden for the whole route lifetime — iOS Safari needs the
// document overscroll path for native pull-to-refresh (see MDN `overscroll-behavior: contain`).
// Keyboard safety stays in `useSpiritVisualViewportVars` + composer focus scroll resets.
import { useRef, useState, type ReactNode } from "react";
import { usePathname } from "next/navigation";
import { PanelLeftClose, PanelLeft } from "lucide-react";

import { SpiritChat } from "@/components/chat/SpiritChat";
import { Clock } from "@/components/dashboard/Clock";
import { ThemeStrip } from "@/components/dashboard/ThemeStrip";
import { ClientFailSafe } from "@/components/system/ClientFailSafe";
import {
  SpiritWorkspaceMobileChromeProvider,
  useSpiritWorkspaceMobileChrome,
} from "@/components/dashboard/SpiritWorkspaceMobileChromeContext";
import { WorkspacePrimarySidebar } from "@/components/dashboard/WorkspacePrimarySidebar";
import { cn } from "@/lib/cn";
import { useSpiritVisualViewportVars } from "@/lib/hooks/useSpiritVisualViewportVars";

export type SpiritWorkspaceShellProps = {
  chatTitle?: string;
  chatSubtitle?: string;
  className?: string;
};

/** Main column padding: full dock gap by default; tight when keyboard or composer claims bottom. */
function SpiritWorkspaceMainColumn({ children }: { children: ReactNode }) {
  const mobileChrome = useSpiritWorkspaceMobileChrome();
  const pathname = usePathname() ?? "";
  const isChatRoute = pathname === "/chat" || pathname.startsWith("/chat/");
  // `/chat` mobile: floating dock is hidden — do not reserve space for a dock that is not there.
  const relaxBottom =
    (mobileChrome?.keyboardInsetPx ?? 0) > 0 ||
    (mobileChrome?.composerFocused ?? false) ||
    isChatRoute;

  return (
    <div
      className={cn(
        "relative z-10 flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden",
        relaxBottom
          ? "max-lg:pb-[max(0.5rem,env(safe-area-inset-bottom,0px))] lg:pb-0"
          : "max-lg:pb-[calc(5rem+env(safe-area-inset-bottom,0px))] lg:pb-0",
      )}
    >
      {children}
    </div>
  );
}

function SpiritWorkspaceShellInner({
  chatTitle = "Neural // Spirit",
  chatSubtitle = "/api/spirit · Dark Node surface",
  className,
}: SpiritWorkspaceShellProps) {
  const [threadsRailOpen, setThreadsRailOpen] = useState(false);
  const workspaceRootRef = useRef<HTMLDivElement>(null);
  const { keyboardInsetPx } = useSpiritVisualViewportVars(workspaceRootRef);

  return (
    <div
      ref={workspaceRootRef}
      data-layout="spirit-workspace"
      className={cn(
        "relative flex w-full overflow-hidden bg-[color:var(--spirit-bg)] text-chalk",
        "max-lg:fixed max-lg:inset-x-0 max-lg:z-[100] max-lg:top-[var(--spirit-visual-offset-top,0px)]",
        "max-lg:h-[var(--spirit-visual-viewport-height,100dvh)] max-lg:max-h-[var(--spirit-visual-viewport-height,100dvh)] max-lg:min-h-0",
        "lg:relative lg:top-auto lg:z-auto lg:min-h-0 lg:max-h-none",
        "lg:h-[100dvh]",
        className,
      )}
      style={{ transition: "background-color 320ms ease" }}
    >
      <div
        className="spirit-trinity-chat__bg-base pointer-events-none absolute inset-0 z-0 bg-[color:var(--spirit-bg)]"
        aria-hidden
      />
      <div
        className="spirit-trinity-chat__bg-wash pointer-events-none absolute inset-0 z-0 bg-[radial-gradient(ellipse_110%_75%_at_50%_-8%,color-mix(in_oklab,var(--spirit-accent)_16%,transparent),transparent_55%)]"
        aria-hidden
      />
      <div
        className="spirit-trinity-chat__bg-grid pointer-events-none absolute inset-0 z-0 opacity-[0.2] [background-image:linear-gradient(rgba(255,255,255,0.035)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.035)_1px,transparent_1px)] [background-size:52px_52px]"
        aria-hidden
      />
      <div
        className="spirit-trinity-chat__bg-vignette pointer-events-none absolute inset-0 z-0 bg-[radial-gradient(circle_at_50%_115%,rgba(0,0,0,0.42),transparent_52%)]"
        aria-hidden
      />

      <SpiritWorkspaceMobileChromeProvider keyboardInsetPx={keyboardInsetPx}>
        <WorkspacePrimarySidebar />

        <SpiritWorkspaceMainColumn>
          <header className="spirit-trinity-chat__desktop-header hidden shrink-0 border-b border-[color:var(--spirit-border)] bg-white/[0.03] backdrop-blur-xl lg:flex">
          <div className="flex items-center gap-3 px-4 py-2 sm:px-5">
            <button
              type="button"
              aria-label={
                threadsRailOpen ? "Close saved threads" : "Open saved threads"
              }
              aria-expanded={threadsRailOpen}
              onClick={() => setThreadsRailOpen((o) => !o)}
              className={cn(
                "inline-flex min-h-[44px] shrink-0 touch-manipulation items-center justify-center gap-1.5 rounded-lg border border-[color:var(--spirit-border)]/80 bg-white/[0.04] px-2.5 font-mono text-[10px] font-semibold uppercase tracking-wider text-chalk transition hover:bg-white/[0.07] lg:hidden",
                threadsRailOpen &&
                  "border-[color:color-mix(in_oklab,var(--spirit-accent)_42%,transparent)] text-[color:var(--spirit-accent-strong)]",
              )}
            >
              {threadsRailOpen ? (
                <PanelLeftClose className="h-5 w-5 shrink-0" aria-hidden />
              ) : (
                <PanelLeft className="h-5 w-5 shrink-0" aria-hidden />
              )}
              <span className="max-[380px]:sr-only">Threads</span>
            </button>

            <div className="min-w-0 flex-1">
              <h1 className="truncate text-sm font-semibold tracking-tight text-chalk sm:text-base lg:text-lg">
                Spirit OS · Chat
              </h1>
              <p className="hidden truncate font-mono text-[10px] leading-snug text-chalk/50 sm:block sm:text-[11px] lg:inline">
                Saved threads · Dexie · /api/spirit
              </p>
            </div>

            <div className="flex min-w-0 shrink-0 flex-wrap items-center justify-end gap-2 sm:gap-3">
              <div className="hidden lg:block">
                <ThemeStrip />
              </div>
              <Clock />
            </div>
          </div>
        </header>

        <div className="flex min-h-0 flex-1 flex-row overflow-hidden">
          <div className="spirit-trinity-chat__main flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden lg:pl-1 lg:pt-1 lg:pr-0">
            <SpiritChat
              persistence
              variant="workspace"
              showThreadSidebar
              title={chatTitle}
              subtitle={chatSubtitle}
              shellClassName="flex h-full min-h-0 flex-1 flex-col overflow-hidden"
              mobileThreadRail={{
                open: threadsRailOpen,
                onOpenChange: setThreadsRailOpen,
              }}
            />
          </div>
        </div>
        </SpiritWorkspaceMainColumn>
      </SpiritWorkspaceMobileChromeProvider>
    </div>
  );
}

