            "flex items-center gap-0.5 rounded-full",
            "border border-[color:color-mix(in_oklab,var(--spirit-glass-border)_78%,transparent)]",
            "bg-[color:color-mix(in_oklab,var(--spirit-bg)_88%,transparent)]",
